window.DOCS = [{"id": "README", "group": "开始这里", "groupKey": "README.md", "title": "开始这里 · 怎么用这套东西", "order": 0, "file": "README.md", "html": "<h1 id=\"s0\">开始这里 · 怎么用这套东西</h1>\n<blockquote><strong>这一页是入口。</strong> 所有内容都在本站点内，点左侧导航即可跳转，不需要打开任何其他文件。<br><br><strong>本站定位</strong>：中国大陆保险纠纷的<strong>实战知识体系</strong>。以广东判例为锚，按「争议类型」而非「险种」组织——因为重疾险和车险打起来其实是同一套牌。</blockquote>\n<hr>\n<h2 id=\"s1\">一、你有三种可能的来意，直接对号入座</h2>\n<h3 id=\"s2\">场景 A · 我拿到拒赔通知书了（30 分钟定位）</h3>\n<p><strong>第一步：读拒赔理由，看它落在哪一行。</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>拒赔理由（通知书原话）</th><th>本质</th><th>直接去读</th></tr></thead><tbody>\n<tr><td>\"未如实告知\"\"投保前已患 XX 疾病\"</td><td>如实告知义务</td><td><a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a> 武器二</td></tr>\n<tr><td>\"属于责任免除范围\"</td><td>免责条款</td><td><a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a> 武器一 + 三</td></tr>\n<tr><td>\"不属于保险责任范围\"\"不满足疾病定义\"</td><td>隐性免责 / 疾病定义</td><td><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F01-%E9%87%8D%E7%96%BE%E9%99%A9\">《重疾险 · 纠纷全解》</a> C1</td></tr>\n<tr><td>\"未达到伤残等级\"\"按比例赔付\"</td><td>比例给付条款</td><td><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F03-%E6%84%8F%E5%A4%96%E9%99%A9\">《意外险 · 纠纷全解》</a> A4</td></tr>\n<tr><td>\"属既往症\"</td><td>既往症定义</td><td><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F02-%E5%8C%BB%E7%96%97%E9%99%A9\">《医疗险 · 纠纷全解》</a> M3</td></tr>\n<tr><td>\"投保时你自己勾选了'已阅读'\"</td><td>🔥 <strong>合同编通则解释 §10③：电子合同仅勾选/弹窗不足以免责</strong></td><td><a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E4%B8%93%E9%A2%98-%E6%8F%90%E7%A4%BA%E8%AF%B4%E6%98%8E%E4%B9%89%E5%8A%A1%E4%B8%8E%E7%94%B5%E5%AD%90%E6%8A%95%E4%BF%9D\">《专题案例 · 提示说明义务与电子投保格式条款》</a></td></tr>\n<tr><td>\"产品停售了所以不能续\"</td><td>短期健康险停售披露义务</td><td><a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F03-%E5%81%A5%E5%BA%B7%E9%99%A9%E7%9B%91%E7%AE%A1%E8%A7%84%E8%8C%83\">《健康险监管规范 · 短期健康保险（银保监办发〔2021〕7 号）原文摘录》</a> 第 10 条</td></tr>\n<tr><td>\"疾病定义不符合约定\"</td><td>重疾定义规范原文</td><td><a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F01-%E9%87%8D%E7%96%BE%E5%AE%9A%E4%B9%89%E4%BD%BF%E7%94%A8%E8%A7%84%E8%8C%832020\">《重大疾病保险的疾病定义使用规范（2020 年修订版）· 原文》</a></td></tr>\n<tr><td>\"改变使用性质 / 从事营运\"</td><td>危险程度显著增加</td><td><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F05-%E8%BD%A6%E9%99%A9\">《车险 · 纠纷全解》</a> V2</td></tr>\n<tr><td>\"保险事故不属于意外\"</td><td>近因原则</td><td><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F03-%E6%84%8F%E5%A4%96%E9%99%A9\">《意外险 · 纠纷全解》</a> A3</td></tr>\n<tr><td>\"你已在别处报销过了\"</td><td>损失补偿原则</td><td><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F02-%E5%8C%BB%E7%96%97%E9%99%A9\">《医疗险 · 纠纷全解》</a> M1</td></tr>\n<tr><td>\"超过索赔时效了\"</td><td>诉讼时效</td><td>见下方时效速查表（<strong>非寿险是 3 年，多数人以为 2 年</strong>）</td></tr>\n<tr><td>\"你跑营运 / 顺风车\"</td><td>改变使用性质</td><td><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F05-%E8%BD%A6%E9%99%A9\">《车险 · 纠纷全解》</a> V2</td></tr>\n</tbody></table></div>\n<p><strong>第二步：走完整流程。</strong> → <a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></p>\n<p><strong>第三步：找同类案例。</strong></p>\n<ul>\n<li>🔥 <strong>优先</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7\">《广东二审判决原文精读 · 第一辑（人身险）》</a> —— <strong>16 份广东中院二审判决书原文</strong>，含案号、一审案号、裁判理由逐字摘录，<strong>可直接写进代理词</strong></li>\n<li>补充：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E9%87%8D%E7%96%BE%E5%8C%BB%E7%96%97\">《重疾险 / 医疗险 · 案例库》</a>、<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E6%84%8F%E5%A4%96%E5%AF%BF%E9%99%A9%E4%B8%8E%E4%BA%92%E8%81%94%E7%BD%91%E6%8A%95%E4%BF%9D\">《意外险 / 寿险 / 互联网平台投保 · 案例库》</a>、<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E8%BD%A6%E9%99%A9%E4%B8%8E%E8%B4%A2%E4%BA%A7%E9%99%A9\">《车险 / 财产险 / 责任险 · 案例库（广东）》</a>（B 级，法院官网/官媒来源）</li>\n</ul>\n<hr>\n<h3 id=\"s3\">场景 B · 我还没买，想避开坑</h3>\n<p>按顺序读这三篇就够了：</p>\n<ol>\n<li><a class=\"dlink\" href=\"#/L3-%E8%BE%93%E5%87%BA%E5%B1%82%2F02-%E6%99%AE%E9%80%9A%E4%BA%BA%E4%B9%B0%E4%BF%9D%E9%99%A9%E7%9A%84%E5%9D%91\">《普通人买保险的常见坑（投保前 → 理赔后）》</a> —— 25 个常见坑，按投保前 → 投保中 → 理赔后排列</li>\n<li><a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F07-%E4%BA%92%E8%81%94%E7%BD%91%E6%8A%95%E4%BF%9D%E4%B8%93%E7%AB%A0\">《互联网投保专章 · 支付宝 / 微信 / App 买保险的坑与打法》</a> —— 支付宝/微信买保险专章，<strong>含 5 分钟证据包标准动作</strong></li>\n<li>对应险种篇的「投保前 checklist」—— 重疾 / 医疗 / 意外 / 寿险 / 车险 各有一份</li>\n</ol>\n<hr>\n<h3 id=\"s4\">场景 C · 我想系统学这套东西</h3>\n<p>按左侧导航顺序读即可，顺序就是设计好的：</p>\n<pre><code>\n开始这里（本页）\n\n  ↓\n\n1 通用打法   八把通用武器 → 维权操作全流程\n\n  ↓\n\n2 险种深挖   重疾 → 医疗 → 意外 → 寿险 → 车险 → 财产责任 → 互联网投保\n\n  ↓\n\n3 广东案例库  重疾医疗 / 意外寿险+互联网 / 车险财产\n\n  ↓\n\n4 工具箱     风险清单 → 常见坑 → 比喻库 → AI 指令库\n\n  ↓\n\n5 法条原文   保险法 + 司法解释二三四 + 民法典格式条款\n\n</code></pre>\n<hr>\n<h2 id=\"s5\">二、时效速查表（最容易被忽略、也最容易翻车）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>事项</th><th>期限</th><th>起算点</th><th>依据</th></tr></thead><tbody>\n<tr><td><strong>诉讼时效 · 非寿险</strong></td><td><strong>3 年</strong>（<span class=\"warn\">!</span> 不是 2 年，见下方注）</td><td>知道或应当知道保险事故发生之日</td><td>民法典 §188 + 保险法 §26①</td></tr>\n<tr><td><strong>诉讼时效 · 人寿保险</strong></td><td><strong>5 年</strong></td><td>同上</td><td>保险法 §26②</td></tr>\n<tr><td><strong>责任保险诉讼时效</strong></td><td>3 年</td><td><strong>被保险人对第三者的赔偿责任确定之日</strong></td><td>解释四 §18</td></tr>\n<tr><td><strong>保险人核定期限</strong></td><td>情形复杂的 <strong>30 日</strong></td><td>初次收到索赔请求及有关证明资料之日</td><td>保险法 §23①、解释二 §15</td></tr>\n<tr><td><strong>赔付期限</strong></td><td>达成协议后 <strong>10 日</strong></td><td>达成赔付协议之日</td><td>保险法 §23②</td></tr>\n<tr><td><strong>先予支付</strong></td><td><strong>60 日</strong></td><td>收到请求及资料之日</td><td>保险法 §25</td></tr>\n<tr><td><strong>保险人解除权 · 一般</strong></td><td><strong>30 日</strong></td><td><strong>知道解除事由之日</strong></td><td>保险法 §16③</td></tr>\n<tr><td><strong>两年不可抗辩</strong></td><td><strong>2 年</strong></td><td><strong>合同成立之日</strong></td><td>保险法 §16③</td></tr>\n<tr><td><strong>自杀条款</strong></td><td><strong>2 年</strong></td><td>合同成立<strong>或复效</strong>之日</td><td>保险法 §44</td></tr>\n<tr><td><strong>保费宽限期</strong></td><td><strong>60 日</strong></td><td>约定的分期缴费到期日</td><td>保险法 §36</td></tr>\n<tr><td><strong>合同中止后复效期</strong></td><td><strong>2 年</strong></td><td>合同效力中止之日</td><td>保险法 §37</td></tr>\n</tbody></table></div>\n<blockquote><span class=\"warn\">!</span> <strong>关于\"2 年诉讼时效\"的重要更正</strong>：保险法 §26 写的确实是 2 年，但<strong>广州中院 (2025)粤01民终19766号明确认定应适用民法典的 3 年</strong>——理由是保险法两年规定系对当时民法通则普通时效的\"照准适用\"，属一般性规定，民法典改为三年后应随之适用。另注意起算点是<strong>知道或应当知道保险事故发生之日</strong>，本案中被保险人直到 2024 年才通过电话得知承保公司和保单内容，时效从那时才起算。详见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7-%E7%AC%AC%E4%BA%8C%E8%BE%91\">《广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）》</a> V-A5。</blockquote>\n<p>| <strong>犹豫期</strong> | 通常 <strong>10 或 15 日</strong> | 签收保单之日（<strong>以条款为准</strong>） | 条款约定 | | <strong>交通事故认定书复核</strong> | <strong>3 日</strong> | 收到认定书之日 | 道路交通事故处理程序规定 | | <strong>退保金返还</strong> | <strong>30 日</strong> | 收到解除合同通知之日 | 保险法 §47 |</p>\n<p><strong><span class=\"warn\">!</span> 最容易踩的三个坑</strong></p>\n<ol>\n<li><strong>跟保险公司耗了三年，起诉被驳回</strong>——谈判期间时效<strong>不中断</strong>，必须发书面催告、律师函或直接起诉。</li>\n<li><strong>保单约定了仲裁</strong>——去法院起诉会被驳回。<strong>起诉前先看争议解决条款</strong>。</li>\n<li><strong>保险人未先解除就拒赔</strong>——这是<strong>我方武器</strong>，不是障碍（解释二 §8）。</li>\n</ol>\n<hr>\n<h2 id=\"s6\">三、八把牌（记住这八个词，就掌握了 90% 的案子）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>武器</th><th>一句话</th><th>依据</th></tr></thead><tbody>\n<tr><td>1</td><td><strong>提示说明义务</strong></td><td>保险人拿免责条款拒赔，先问\"你提示和明确说明了吗\"，举证责任在它。<strong>电子合同仅勾选/弹窗不算</strong>（§10③）</td><td>§17 + 解释二 §9-13 + <strong>合同编通则解释 §10</strong></td></tr>\n<tr><td>2</td><td><strong>如实告知 / 两年不可抗辩</strong></td><td>没问就不用说；概括性询问无效；解除权 30 日 + 2 年双重限制</td><td>§16 + 解释二 §5-8</td></tr>\n<tr><td>3</td><td><strong>隐性免责条款</strong></td><td>藏在\"保险责任\"章节里的地雷，照样要提示说明</td><td>§17 + 解释二 §9</td></tr>\n<tr><td>4</td><td><strong>不利解释</strong></td><td>先按通常理解，仍有两种以上解释的，判给被保险人</td><td>§30</td></tr>\n<tr><td>5</td><td><strong>举证责任分配</strong></td><td>说明义务、询问范围、免责事由——都由保险人举证</td><td>§22 + 解释二 §4/§6/§13</td></tr>\n<tr><td>6</td><td><strong>核定与迟延赔付</strong></td><td>拖延本身就是一个独立诉请</td><td>§21/§23/§25/§26</td></tr>\n<tr><td>7</td><td><strong>近因原则</strong></td><td>找\"第一张倒下的骨牌\"；难以确定的<strong>按比例</strong>支持</td><td>判例 + 解释三 §25</td></tr>\n<tr><td>8</td><td><strong>代位求偿与责任险</strong></td><td>车险与责任险专用；第三者有直接请求权</td><td>§60-63/§65 + 解释四</td></tr>\n</tbody></table></div>\n<p>完整论证见 <a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a>。</p>\n<hr>\n<h2 id=\"s7\">四、内容地图</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>分组</th><th>内容</th><th>什么时候读</th></tr></thead><tbody>\n<tr><td><strong>开始这里</strong></td><td>本页</td><td>每次都从这里进</td></tr>\n<tr><td><strong>1 通用打法</strong></td><td>八把通用武器（含 2026 广东二审新规则）、维权操作全流程（含文书模板）</td><td>拿到拒赔通知书时</td></tr>\n<tr><td><strong>2 险种深挖</strong></td><td>重疾 / 医疗 / 意外 / 寿险 / 车险 / 财产责任 / 互联网投保</td><td>针对具体险种</td></tr>\n<tr><td><strong>3 案例库</strong></td><td><strong>A 级判例精读两辑</strong>（第一辑人身险 16 例 / 第二辑车险财产险 9 例）+ 专题案例 + 广东案例 3 篇</td><td>🔥 <strong>广东二审判决原文精读（A 级，16 份）</strong> + 专题：提示说明义务与电子投保 + 广东案例 3 篇（B 级）</td><td>找同类判例支撑时</td></tr>\n<tr><td><strong>4 工具箱</strong></td><td>风险清单 47 条、常见坑 28 条、比喻库、AI 指令库</td><td>查表、讲给别人听、让 AI 干活</td></tr>\n<tr><td><strong>5 法条原文</strong></td><td>保险法 + 司法解释二三四；<strong>重疾定义规范 2020（A 级官方 PDF）</strong>；<strong>民法典格式条款 + 合同编通则解释</strong>；<strong>健康险监管规范</strong></td><td>需要引原文时</td></tr>\n<tr><td><strong>6 关于</strong></td><td><a class=\"dlink\" href=\"#/L5-%E5%85%B3%E4%BA%8E%2F01-%E5%85%8D%E8%B4%A3%E5%A3%B0%E6%98%8E%E4%B8%8E%E5%86%85%E5%AE%B9%E8%AF%B4%E6%98%8E\">《免责声明与内容说明》</a></td><td>引用、转载、核对来源前</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s8\">五、案例可信度分级（重要）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>级别</th><th>含义</th><th>使用规则</th></tr></thead><tbody>\n<tr><td><strong>A</strong></td><td>裁判文书网 / 人民法院案例库<strong>原文</strong></td><td>可直接引用</td></tr>\n<tr><td><strong>B</strong></td><td>法院官网、人民法院报、官媒发布的典型案例（含\"法官说法\"原文）</td><td>可引用，注明来源</td></tr>\n<tr><td><strong>C</strong></td><td>律所解读、自媒体等二手来源</td><td><strong>待核验，不得直接写入结论</strong></td></tr>\n</tbody></table></div>\n<p><strong>当前状态（2026-09-16 更新）</strong>：</p>\n<ul>\n<li>✅ <strong>A 级已有 16 份</strong>——广东广州、深圳、佛山、梅州、湛江、阳江、汕尾 7 家中院的二审判决书原文，全部含案号、一审案号、裁判理由逐字摘录。见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7\">《广东二审判决原文精读 · 第一辑（人身险）》</a>。</li>\n<li><span class=\"warn\">!</span> 其余案例为 <strong>B 级</strong>（法院官网、人民法院报、官媒发布的典型案例，含\"法官说法\"原文），每个都标注了来源 URL。</li>\n<li>❌ 人民法院案例库（rmfyalk.court.gov.cn）与裁判文书网的检索接口均需登录，无法自动化批量获取——A 级案例靠人工导出。</li>\n</ul>\n<p><strong>本站不编造案号、法院名称、裁判理由。</strong> 找不到的争议类型标注为\"检索缺口\"，不凑数。 完整规则见<a class=\"dlink\" href=\"#/L5-%E5%85%B3%E4%BA%8E%2F01-%E5%85%8D%E8%B4%A3%E5%A3%B0%E6%98%8E%E4%B8%8E%E5%86%85%E5%AE%B9%E8%AF%B4%E6%98%8E\">《免责声明与内容说明》</a>。</p>\n<hr>\n<h2 id=\"s9\">六、使用前必读</h2>\n<ul>\n<li>本站点是<strong>个人知识管理与学习资料</strong>，<strong>不构成针对具体案件的法律意见</strong>。</li>\n<li>法条、司法解释、案例在对外使用前，<strong>须与最新有效版本及原始来源核对</strong>。</li>\n<li>法律会变（司法解释会有新版本、监管规则会更新），<strong>本站点内容有时间戳</strong>，请以当前日期判断是否需要复核。</li>\n<li>涉及具体案件的，请咨询执业律师或自行检索官方数据库。</li>\n</ul>\n<hr>\n<h2 id=\"s10\">七、内容更新</h2>\n<p>最近一次更新：<strong>2026-09-16</strong> —— 新增「广东二审判决原文精读（A 级）」16 份判决书原文， 并据此回填了通用打法、重疾险、医疗险、意外险、互联网投保专章的新规则； 新增免责声明与可信度分级说明页。</p>\n<p>法条与判例会变，引用前请核对最新有效版本——见<a class=\"dlink\" href=\"#/L5-%E5%85%B3%E4%BA%8E%2F01-%E5%85%8D%E8%B4%A3%E5%A3%B0%E6%98%8E%E4%B8%8E%E5%86%85%E5%AE%B9%E8%AF%B4%E6%98%8E\">《免责声明与内容说明》</a>。</p>", "toc": [{"id": "s1", "lv": 2, "t": "一、你有三种可能的来意，直接对号入座"}, {"id": "s2", "lv": 3, "t": "场景 A · 我拿到拒赔通知书了（30 分钟定位）"}, {"id": "s3", "lv": 3, "t": "场景 B · 我还没买，想避开坑"}, {"id": "s4", "lv": 3, "t": "场景 C · 我想系统学这套东西"}, {"id": "s5", "lv": 2, "t": "二、时效速查表（最容易被忽略、也最容易翻车）"}, {"id": "s6", "lv": 2, "t": "三、八把牌（记住这八个词，就掌握了 90% 的案子）"}, {"id": "s7", "lv": 2, "t": "四、内容地图"}, {"id": "s8", "lv": 2, "t": "五、案例可信度分级（重要）"}, {"id": "s9", "lv": 2, "t": "六、使用前必读"}, {"id": "s10", "lv": 2, "t": "七、内容更新"}], "text": "开始这里 · 怎么用这套东西 这一页是入口。 所有内容都在本站点内，点左侧导航即可跳转，不需要打开任何其他文件。 本站定位 ：中国大陆保险纠纷的 实战知识体系 。以广东判例为锚，按「争议类型」而非「险种」组织——因为重疾险和车险打起来其实是同一套牌。 一、你有三种可能的来意，直接对号入座 场景 A · 我拿到拒赔通知书了（30 分钟定位） 第一步：读拒赔理由，看它落在哪一行。 拒赔理由（通知书原话） 本质 直接去读 \"未如实告知\"\"投保前已患 XX 疾病\" 如实告知义务 L0 打法层/01 八把通用武器 武器二 \"属于责任免除范围\" 免责条款 L0 打法层/01 八把通用武器 武器一 + 三 \"不属于保险责任范围\"\"不满足疾病定义\" 隐性免责 / 疾病定义 L1 险种层/01 重疾险 C1 \"未达到伤残等级\"\"按比例赔付\" 比例给付条款 L1 险种层/03 意外险 A4 \"属既往症\" 既往症定义 L1 险种层/02 医疗险 M3 \"投保时你自己勾选了'已阅读'\" 🔥 合同编通则解释 §10③：电子合同仅勾选/弹窗不足以免责 L2 案例库/专题 提示说明义务与电子投保 \"产品停售了所以不能续\" 短期健康险停售披露义务 L4 法条库/03 健康险监管规范 第 10 条 \"疾病定义不符合约定\" 重疾定义规范原文 L4 法条库/01 重疾定义使用规范2020 \"改变使用性质 / 从事营运\" 危险程度显著增加 L1 险种层/05 车险 V2 \"保险事故不属于意外\" 近因原则 L1 险种层/03 意外险 A3 \"你已在别处报销过了\" 损失补偿原则 L1 险种层/02 医疗险 M1 \"超过索赔时效了\" 诉讼时效 见下方时效速查表（ 非寿险是 3 年，多数人以为 2 年 ） \"你跑营运 / 顺风车\" 改变使用性质 L1 险种层/05 车险 V2 第二步：走完整流程。 → L0 打法层/02 维权操作全流程 第三步：找同类案例。 🔥 优先 ：L2 案例库/广东二审判决原文精读 A级 —— 16 份广东中院二审判决书原文 ，含案号、一审案号、裁判理由逐字摘录， 可直接写进代理词 补充：L2 案例库/广东案例 重疾医疗、L2 案例库/广东案例 意外寿险与互联网投保、L2 案例库/广东案例 车险与财产险（B 级，法院官网/官媒来源） 场景 B · 我还没买，想避开坑 按顺序读这三篇就够了： 1. L3 输出层/02 普通人买保险的坑 —— 25 个常见坑，按投保前 → 投保中 → 理赔后排列 2. L1 险种层/07 互联网投保专章 —— 支付宝/微信买保险专章， 含 5 分钟证据包标准动作 3. 对应险种篇的「投保前 checklist」—— 重疾 / 医疗 / 意外 / 寿险 / 车险 各有一份 场景 C · 我想系统学这套东西 按左侧导航顺序读即可，顺序就是设计好的： 二、时效速查表（最容易被忽略、也最容易翻车） 事项 期限 起算点 依据 诉讼时效 · 非寿险 3 年 （⚠️ 不是 2 年，见下方注） 知道或应当知道保险事故发生之日 民法典 §188 + 保险法 §26① 诉讼时效 · 人寿保险 5 年 同上 保险法 §26② 责任保险诉讼时效 3 年 被保险人对第三者的赔偿责任确定之日 解释四 §18 保险人核定期限 情形复杂的 30 日 初次收到索赔请求及有关证明资料之日 保险法 §23①、解释二 §15 赔付期限 达成协议后 10 日 达成赔付协议之日 保险法 §23② 先予支付 60 日 收到请求及资料之日 保险法 §25 保险人解除权 · 一般 30 日 知道解除事由之日 保险法 §16③ 两年不可抗辩 2 年 合同成立之日 保险法 §16③ 自杀条款 2 年 合同成立 或复效 之日 保险法 §44 保费宽限期 60 日 约定的分期缴费到期日 保险法 §36 合同中止后复效期 2 年 合同效力中止之日 保险法 §37 ⚠️ 关于\"2 年诉讼时效\"的重要更正 ：保险法 §26 写的确实是 2 年，但 广州中院 (2025)粤01民终19766号明确认定应适用民法典的 3 年 ——理由是保险法两年规定系对当时民法通则普通时效的\"照准适用\"，属一般性规定，民法典改为三年后应随之适用。另注意起算点是 知道或应当知道保险事故发生之日 ，本案中被保险人直到 2024 年才通过电话得知承保公司和保单内容，时效从那时才起算。详见L2 案例库/广东二审判决原文精读 A级 第二辑 V A5。 犹豫期 通常 10 或 15 日 签收保单之日（ 以条款为准 ） 条款约定 交通事故认定书复核 3 日 收到认定书之日 道路交通事故处理程序规定 退保金返还 30 日 收到解除合同通知之日 保险法 §47 ⚠️ 最容易踩的三个坑 1. 跟保险公司耗了三年，起诉被驳回 ——谈判期间时效 不中断 ，必须发书面催告、律师函或直接起诉。 2. 保单约定了仲裁 ——去法院起诉会被驳回。 起诉前先看争议解决条款 。 3. 保险人未先解除就拒赔 ——这是 我方武器 ，不是障碍（解释二 §8）。 三、八把牌（记住这八个词，就掌握了 90% 的案子） 武器 一句话 依据 1 提示说明义务 保险人拿免责条款拒赔，先问\"你提示和明确说明了吗\"，举证责任在它。 电子合同仅勾选/弹窗不算 （§10③） §17 + 解释二 §9 13 + 合同编通则解释 §10 2 如实告知 / 两年不可抗辩 没问就不用说；概括性询问无效；解除权 30 日 + 2 年双重限制 §16 + 解释二 §5 8 3 隐性免责条款 藏在\"保险责任\"章节里的地雷，照样要提示说明 §17 + 解释二 §9 4 不利解释 先按通常理解，仍有两种以上解释的，判给被保险人 §30 5 举证责任分配 说明义务、询问范围、免责事由——都由保险人举证 §22 + 解释二 §4/§6/§13 6 核定与迟延赔付 拖延本身就是一个独立诉请 §21/§23/§25/§26 7 近因原则 找\"第一张倒下的骨牌\"；难以确定的 按比例 支持 判例 + 解释三 §25 8 代位求偿与责任险 车险与责任险专用；第三者有直接请求权 §60 63/§65 + 解释四 完整论证见 L0 打法层/01 八把通用武器。 四、内容地图 分组 内容 什么时候读 开始这里 本页 每次都从这里进 1 通用打法 八把通用武器（含 2026 广东二审新规则）、维权操作全流程（含文书模板） 拿到拒赔通知书时 2 险种深挖 重疾 / 医疗 / 意外 / 寿险 / 车险 / 财产责任 / 互联网投保 针对具体险种 3 案例库 A 级判例精读两辑 （第一辑人身险 16 例 / 第二辑车险财产险 9 例）+ 专题案例 + 广东案例 3 篇 🔥 广东二审判决原文精读（A 级，16 份） + 专题：提示说明义务与电子投保 + 广东案例 3 篇（B 级） 找同类判例支撑时 4 工具箱 风险清单 47 条、常见坑 28 条、比喻库、AI 指令库 查表、讲给别人听、让 AI 干活 5 法条原文 保险法 + 司法解释二三四； 重疾定义规范 2020（A 级官方 PDF） ； 民法典格式条款 + 合同编通则解释 ； 健康险监管规范 需要引原文时 6 关于 L5 关于/01 免责声明与内容说明 引用、转载、核对来源前 五、案例可信度分级（重要） 级别 含义 使用规则 A 裁判文书网 / 人民法院案例库 原文 可直接引用 B 法院官网、人民法院报、官媒发布的典型案例（含\"法官说法\"原文） 可引用，注明来源 C 律所解读、自媒体等二手来源 待核验，不得直接写入结论 当前状态（2026 09 16 更新） ： ✅ A 级已有 16 份 ——广东广州、深圳、佛山、梅州、湛江、阳江、汕尾 7 家中院的二审判决书原文，全部含案号、一审案号、裁判理由逐字摘录。见L2 案例库/广东二审判决原文精读 A级。 ⚠️ 其余案例为 B 级 （法院官网、人民法院报、官媒发布的典型案例，含\"法官说法\"原文），每个都标注了来源 URL。 ❌ 人民法院案例库（rmfyalk.court.gov.cn）与裁判文书网的检索接口均需登录，无法自动化批量获取——A 级案例靠人工导出。 本站不编造案号、法院名称、裁判理由。 找不到的争议类型标注为\"检索缺口\"，不凑数。 完整规则见L5 关于/01 免责声明与内容说明。 六、使用前必读 本站点是 个人知识管理与学习资料 ， 不构成针对具体案件的法律意见 。 法条、司法解释、案例在对外使用前， 须与最新有效版本及原始来源核对 。 法律会变（司法解释会有新版本、监管规则会更新）， 本站点内容有时间戳 ，请以当前日期判断是否需要复核。 涉及具体案件的，请咨询执业律师或自行检索官方数据库。 七、内容更新 最近一次更新： 2026 09 16 —— 新增「广东二审判决原文精读（A 级）」16 份判决书原文， 并据此回填了通用打法、重疾险、医疗险、意外险、互联网投保专章的新规则； 新增免责声明与可信度分级说明页。 法条与判例会变，引用前请核对最新有效版本——见L5 关于/01 免责声明与内容说明。"}, {"id": "L0-打法层/01-八把通用武器", "group": "1 · 通用打法", "groupKey": "L0-打法层", "title": "八把通用武器", "order": 1, "file": "01-八把通用武器.md", "html": "<h1 id=\"s0\">八把通用武器</h1>\n<blockquote><strong>这一层是整个体系的地基。</strong> 重疾险、医疗险、意外险、车险看上去风马牛不相及，<br>但真打起来，90% 的案子翻来覆去就是这八把牌。<br>吃透这一层，拿到一份拒赔通知书 30 分钟内就能定位打法。<br><br>法条原文见本站 <a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a> 篇（左侧导航「法条原文」）。本文只写规则与打法，不重复抄条文。</blockquote>\n<hr>\n<h2 id=\"s1\">武器一 · 提示说明义务（出现频率：★★★★★）</h2>\n<p><strong>一句话定位：绝大多数拒赔案的第一突破口。保险人拿免责条款拒赔，先问一句\"你提示和明确说明了吗\"。</strong></p>\n<p><strong>依据</strong>：《保险法》第 17 条 + 司法解释（二）第 9–13 条； <strong>并行的更锋利路径</strong>：《民法典》§496–498 + <strong>《合同编通则司法解释》第 10 条</strong>（2023-12-05 施行）。</p>\n<p><strong>规则拆解</strong></p>\n<ol>\n<li><strong>🔥 2023 年之后最重要的一条（电子投保直接适用）</strong>——《合同编通则司法解释》第 10 条第 3 款：</li>\n<p>&gt; 提供格式条款的一方对其已经尽到提示义务或者说明义务承担举证责任。<strong>对于通过互联网等信息网络订立的电子合同，提供格式条款的一方仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持</strong>，但是其举证符合前两款规定的除外。    同条第 1、2 款还明确了标准：提示 = \"通常足以引起对方注意的文字、符号、字体等<strong>明显标识</strong>\"；说明 = 就异常条款的<strong>概念、内容及其法律后果</strong>作出\"<strong>通常能够理解</strong>\"的解释说明。    <span class=\"warn\">!</span> 这直接击穿了互联网投保中\"你已经勾选了已阅读\"的抗辩。详见<a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F07-%E4%BA%92%E8%81%94%E7%BD%91%E6%8A%95%E4%BF%9D%E4%B8%93%E7%AB%A0\">《互联网投保专章 · 支付宝 / 微信 / App 买保险的坑与打法》</a>与<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E4%B8%93%E9%A2%98-%E6%8F%90%E7%A4%BA%E8%AF%B4%E6%98%8E%E4%B9%89%E5%8A%A1%E4%B8%8E%E7%94%B5%E5%AD%90%E6%8A%95%E4%BF%9D\">《专题案例 · 提示说明义务与电子投保格式条款》</a>。    <strong>另可主张民法典 §496②</strong>：未履行提示说明义务致对方未注意或未理解的，<strong>对方可以主张该条款不成为合同的内容</strong>（比\"不生效\"更彻底）。</p>\n</ol>\n<ol>\n<li><strong>\"提示\"和\"明确说明\"是两个义务，缺一不可。</strong> 提示 = 用文字、字体、符号等<strong>足以引起注意</strong>的标志标出来（加粗、加黑、阴影、变色）；明确说明 = 对该条款的<strong>概念、内容及其法律后果</strong>作出<strong>常人能够理解</strong>的解释说明。只加粗不解释，只完成了一半。</li>\n<li><strong>哪些条款算\"免责条款\"？范围比想象的宽。</strong> 司法解释（二）第 9 条明确：责任免除条款、<strong>免赔额、免赔率、比例赔付或者给付</strong>等免除或减轻保险人责任的条款，都算。所以\"伤残按等级比例赔付\"\"医疗费只报 80%\"这类条款，一样要提示说明。</li>\n<li><strong>网络投保同样适用。</strong> 司法解释（二）第 12 条：网络、电话订立的合同，保险人以<strong>网页、音频、视频</strong>形式提示和明确说明的，可以认定履行了义务。反过来讲——网页上没做，就是没做。</li>\n<li><strong>举证责任在保险人。</strong> 司法解释（二）第 13 条第 1 款：保险人对其履行了明确说明义务<strong>负举证责任</strong>。这是我们的结构性优势。</li>\n<li><strong><span class=\"warn\">!</span> 但有一个坑：签字确认。</strong> 司法解释（二）第 13 条第 2 款：投保人在相关文书上签字、盖章或以其他形式确认的，<strong>应当认定保险人履行了该项义务</strong>，但有其他证据证明保险人未履行的除外。所以\"我只是在手机上点了同意\"往往不够，要找<strong>其他证据</strong>推翻（如销售聊天记录、回访录音、页面截屏证明没有强制阅读停留）。</li>\n</ol>\n<p><strong>保险人常见抗辩 → 破解点</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>抗辩</th><th>破解</th></tr></thead><tbody>\n<tr><td>\"条款已经加粗加黑了\"</td><td>加粗只完成\"提示\"，还要证明\"明确说明\"。要求其出示说明过程的证据（录音、视频、客服记录）</td></tr>\n<tr><td>\"投保单上有投保人签字\"</td><td>用第 13 条第 2 款但书：提交销售过程的聊天记录、电话回访录音，证明未实际说明</td></tr>\n<tr><td>\"这是保险责任范围条款，不是免责条款，不用说明\"</td><td>引<strong>隐性免责条款</strong>规则（见武器三）：未标注为免责但暗含免除责任的，仍须提示说明</td></tr>\n<tr><td>\"这是法律禁止性规定（如醉驾），提示即可\"</td><td>司法解释（二）第 10 条确实如此，但仍须<strong>提示</strong>，且要确认该情形确属法律、行政法规的禁止性规定</td></tr>\n</tbody></table></div>\n<p><strong>证据清单</strong>：投保页面的完整截屏/录屏（含健康告知页、条款展示页、勾选与跳转逻辑）、电子投保单、保险条款全文、销售聊天记录、电话回访录音、付款凭证。</p>\n<p><strong>生活比喻</strong>：这就像药品说明书的\"黑框警告\"。药厂不能把不良反应塞在说明书第 38 页的小字里，然后说\"你自己没看\"。必须印在盒子最显眼的地方，还得让你看得懂。</p>\n<hr>\n<h3 id=\"s2\">2026 年广东二审新规则（A 级判例更新，必读）</h3>\n<blockquote>以下均来自裁判文书网判决书原文，逐字摘录见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7\">《广东二审判决原文精读 · 第一辑（人身险）》</a>。</blockquote>\n<p><strong>① 说明义务判\"结果\"，不判\"动作\"</strong></p>\n<blockquote>\"应以保险人有进行提示与解释说明的作为<strong>且该作为达到使投保人了解免责条款内容的程度</strong>……因<strong>视频直接跳转</strong>而未能达到使投保人了解免责条款内容之认定标准\"<br>——深圳中院 (2025)粤03民终8930号</blockquote>\n<p>保险人提交了说明视频 ≠ 履行义务。<strong>视频可跳过、自动跳转、默认勾选 = 未履行。</strong></p>\n<p><strong>② 加黑加粗 ≠ 明确说明</strong></p>\n<blockquote>\"上述条款<strong>虽然采用加黑、加粗方式提醒投保人注意</strong>，但……保险公司未能举证说明其对于先天性畸形的概念、内容作出具体解释，且为一般人能够知晓和理解\"<br>——广州中院 (2024)粤01民终28133号</blockquote>\n<p>\"提示\"与\"明确说明\"是<strong>两项独立义务</strong>。加黑加粗只完成前者。</p>\n<p><strong>③ 引用 ICD-10/ICD-O-3 却不列明内容 = 未说明</strong></p>\n<blockquote>\"<strong>并未将 ICD-10 中关于……的定义和分类在案涉保险合同中列明</strong>，亦未提供证据证明已就前述疾病……作出了常人能够理解的解释说明……<strong>更不能以投保人的签章行为推定其已完全理解</strong>\"<br>——广州中院 (2026)粤01民终10449号</blockquote>\n<p><strong>④ 取证技巧：同页对比</strong></p>\n<blockquote>\"第33-34页中77点对'严重Ⅰ型糖尿病'并发症的定义部分<strong>并未有加粗加重或其他足以提醒投保人慎重阅读、理解的标识，与同页……其他重要条款字体的背景明显不一致</strong>\"<br>——梅州中院 (2025)粤14民终795号</blockquote>\n<p><strong>把条款那一页打印出来：别的条款加粗、争议条款没加粗 —— 对比本身就是证据。</strong></p>\n<p><strong>⑤ 电子签名只证明\"投保操作完成\"</strong></p>\n<blockquote>\"<strong>电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务</strong>\"<br>——湛江中院 (2026)粤08民终2074号</blockquote>\n<p><strong>⑥ 提交的\"示范视频\"不是本案投保轨迹</strong></p>\n<blockquote>\"<strong>某公司广州分公司提交的投保示范视频并非张某甲父亲代投保时的视频轨迹</strong>，仅凭投保单上'张某甲'的签名字样尚不足以证明\"<br>——广州中院 (2025)粤01民终24935号（一审说理，二审维持）</blockquote>\n<p>→ 要求保险人提供<strong>本次投保的可回溯记录</strong>（互联网保险可回溯是监管硬要求）。</p>\n<p><strong>⑦ <span class=\"warn\">!</span> 反面：三件套齐备时法院会认定已履行</strong></p>\n<blockquote>\"提交了投保单及投保人通过电子形式投保时的<strong>照片</strong>……<strong>在投保单上'投保人声明'处签名</strong>……相关保险条款中也<strong>进行了加黑加粗</strong>，足以证实……<strong>本院认定已履行提示和明确说明义务</strong>\"<br>——汕尾中院 (2025)粤15民终501号</blockquote>\n<p><strong>别把全部筹码押在提示说明义务上。</strong> 评估胜诉可能时，先看自己这边是不是恰好三件套齐全。</p>\n<hr>\n<h3 id=\"s3\">武器一 · 补遗：第二辑 A 级判例新增的三条硬规则</h3>\n<ol>\n<li>🔥 <strong>\"这是保险标的/保险责任范围条款，不是免责条款\"——这个挡箭牌已经失效。</strong></li>\n<p>江门中院 (2026)粤07民终1377号（家财险把金银珠宝排除出\"室内财产\"）：</p>\n</ol>\n<p>&gt; 该部分内容实际上系对保险责任范围中的室内财产范围<strong>单方进行了限缩</strong>，限制了被保险人的权利及保险人的义务，该约定<strong>已实质上构成免责条款</strong>，除非保险公司已就该部分内容尽到提示说明义务，否则对投保人不发生法律约束力。</p>\n<ol>\n<li>🔥 <strong>互联网投保的举证标准被法院量化了：要\"阅读时长、点击路径\"。</strong></li>\n<p>佛山中院 (2026)粤06民终4139号：</p>\n</ol>\n<p>&gt; 保险人应当完整保存投保人在销售页面的操作轨迹，<strong>包括阅读时长、点击路径等关键节点</strong>。然……未提交可验证的操作记录，<strong>仅以投保人签字的格式化声明主张已履行说明义务，此证据不足以证明</strong>其履行了对相应免责条款的提示说明义务。</p>\n<p>→ 庭审上直接按这个口径要求对方举证：把操作轨迹拿出来。</p>\n<ol>\n<li>🔥 <strong>只提交\"同类产品/示范流程\"公证书或视频 = 未举证。</strong></li>\n<p>广州中院 (2025)粤01民终19766号：保险人仅提交<strong>同类保险产品</strong>的投保流程公证书，法院认定未能证明<strong>已向投保人本人</strong>作出提示说明 → 《投保须知》中限制保额的条款不生效，按保单载明金额全额赔付 150 万。</p>\n</ol>\n<ol>\n<li><span class=\"warn\">!</span> <strong>但请注意反面</strong>：中山中院 (2025)粤20民终2567号认定\"<strong>加粗加黑 + 强制停留阅读程序 + 阅读后勾选 + 条款内容明确无歧义</strong>\"四件套齐备 = 已履行。四件套中的每一项都可以单独质证（加粗了但可跳过？停留了但没显示全文？），见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7-%E7%AC%AC%E4%BA%8C%E8%BE%91\">《广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）》</a> V-D3。</li>\n</ol>\n<hr>\n<h2 id=\"s4\">武器二 · 如实告知义务与两年不可抗辩（出现频率：★★★★★）</h2>\n<p><strong>一句话定位：保险人拒赔的第二大理由。核心战场不在\"你有没有说\"，而在\"他有没有问、怎么问的\"。</strong></p>\n<p><strong>依据</strong>：《保险法》第 16 条 + 司法解释（二）第 5–8 条 + 司法解释（三）第 5 条。</p>\n<p><strong>规则拆解</strong></p>\n<ol>\n<li><strong>告知义务以\"询问\"为前提。</strong> 第 16 条第 1 款：保险人<strong>就有关情况提出询问的</strong>，投保人才如实告知。<strong>没问就不用说。</strong> 这是最重要的边界。</li>\n<li><strong>告知范围 = 询问范围。</strong> 司法解释（二）第 6 条第 1 款：告知义务<strong>限于保险人询问的范围和内容</strong>；对询问范围有争议的，<strong>保险人负举证责任</strong>。</li>\n<li><strong>概括性询问无效。</strong> 司法解释（二）第 6 条第 2 款：保险人以投保人违反<strong>概括性条款</strong>（如\"有无其他疾病\"\"身体是否有异常\"）的告知义务为由解除合同的，<strong>法院不予支持</strong>，除非该概括性条款有具体内容。</li>\n<li><strong>只告知\"明知\"的事项。</strong> 司法解释（二）第 5 条：投保人<strong>明知</strong>的才属于应告知内容。不知道的体检异常，不构成违反义务。</li>\n<li><strong>两年不可抗辩。</strong> 第 16 条第 3 款：合同解除权自保险人知道解除事由之日起 <strong>30 日</strong>不行使而消灭；<strong>自合同成立之日起超过 2 年，保险人不得解除合同</strong>。</li>\n<li><strong><span class=\"warn\">!</span> 两个重要限制</strong>：① 保险人<strong>未行使解除权直接拒赔</strong>的，法院不予支持（司法解释二第 8 条）——必须先解除再拒赔；② 保险人知情后<strong>仍收取保费</strong>的，不得再解除（司法解释二第 7 条）。</li>\n<li><strong>体检不免除告知义务，但保险人知道体检结果的除外。</strong> 司法解释（三）第 5 条。</li>\n</ol>\n<p><strong>保险人常见抗辩 → 破解点</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>抗辩</th><th>破解</th></tr></thead><tbody>\n<tr><td>\"你投保前有结节/指标异常没说\"</td><td>① 询问表上是否有<strong>具体、明确</strong>的对应问题？② 该异常是否属于投保人\"明知\"？③ 该异常与所患疾病有无<strong>因果关系</strong>？</td></tr>\n<tr><td>\"你没告知肿瘤家族史\"</td><td>电子投保单只问了\"遗传性疾病\"的，不算询问了家族史</td></tr>\n<tr><td>\"你在其他公司投保超过 50 万没说\"</td><td>即使问了，还要看保险人是否在<strong>法定期限内</strong>行使解除权</td></tr>\n<tr><td>\"这是恶意骗保，不适用两年不可抗辩\"</td><td>两年不可抗辩的例外限于故意不履行告知义务且保险事故在合同成立前已发生；要求保险人举证</td></tr>\n</tbody></table></div>\n<p><strong>证据清单</strong>：健康告知页完整截屏（<strong>每一条询问的原文表述</strong>）、投保时的体检报告、就诊记录、投保时间与确诊时间的时间轴、保险人的解除合同通知书（<strong>注意落款时间与知道解除事由的时间差</strong>）。</p>\n<p><strong>生活比喻</strong>：相亲时\"问什么答什么\"。对方没问你有没有房，你不必主动交代；但问了就得说实话。反之，对方问一句\"你人没问题吧\"这种含糊问题，等于没问——法律上这叫\"概括性询问\"，不能拿来当拒赔理由。</p>\n<p><strong><span class=\"warn\">!</span> 时效陷阱</strong>：保险人知道解除事由后 30 日内必须行使解除权，超期消灭。实务中保险公司常拖到理赔阶段才发解除通知，<strong>这个时间差就是我们的武器</strong>（广州天河法院那起网络投保重疾险案，保险人受理理赔申请 35 天后才发解除通知，被认定超期）。</p>\n<hr>\n<h2 id=\"s5\">武器三 · 免责条款的认定（含隐性免责条款）</h2>\n<p><strong>一句话定位：把保险人藏在\"保险责任\"章节里的地雷挖出来。</strong></p>\n<p><strong>依据</strong>：《保险法》第 17、19 条 + 司法解释（二）第 9 条 + 人民法院案例库裁判规则。</p>\n<p><strong>规则拆解</strong></p>\n<ol>\n<li><strong>免责条款不限于\"责任免除\"那几段。</strong> 司法解释（二）第 9 条第 1 款列举了免赔额、免赔率、比例赔付等，实质标准是\"<strong>免除或者减轻保险人责任</strong>\"。</li>\n<li><strong>隐性免责条款（最狠的一招）。</strong> 有些条款写在\"保险责任\"章节，表面在说\"保什么\"，实际在说\"这种情况下不保\"。人民法院案例库明确规则：<strong>未标注或提示为免责条款但暗含免除责任情形的，属于隐性免责条款，保险人应当单独明确告知说明，否则不发生效力。</strong></li>\n<li><strong>注意第 9 条第 2 款的反向规定</strong>：保险人因投保人、被保险人违反法定或约定义务而<strong>享有解除合同权利</strong>的条款，<strong>不属于</strong>第 17 条第 2 款的免责条款（即无需按免责条款标准说明）——这是保险人的抗辩路径，要预判。</li>\n<li><strong>格式条款无效（第 19 条）</strong>：免除保险人依法应承担的义务、加重投保人责任、排除投保人/被保险人/受益人依法享有的权利的条款<strong>无效</strong>。这与\"未提示说明不生效\"是两条路，可以并列主张。</li>\n</ol>\n<p><strong>实战动作</strong>：拿到条款后，做一次\"<strong>责任范围反向扫描</strong>\"——把保险责任章节里所有带\"但\"\"除外\"\"仅限于\"\"须满足以下条件\"\"不包括\"字样的句子全部摘出来，逐条问保险人：这条你提示说明了吗？</p>\n<p><strong>生活比喻</strong>：菜单的\"推荐菜\"栏里写着\"本店不提供\"，这就是隐性免责条款。它不长得像免责，但效果一样。</p>\n<hr>\n<h2 id=\"s6\">武器四 · 不利解释规则（疑义利益解释）</h2>\n<p><strong>一句话定位：条款有歧义时的兜底武器。便宜但好用。</strong></p>\n<p><strong>依据</strong>：《保险法》第 30 条。</p>\n<p><strong>规则拆解</strong></p>\n<ol>\n<li><strong>两步走，不能跳步。</strong> 第 30 条的顺序是：先按<strong>通常理解</strong>解释 → <strong>仍有两种以上解释</strong>的，才作有利于被保险人和受益人的解释。</li>\n<p><span class=\"warn\">!</span> 常见误用：一上来就喊\"应作不利于保险人的解释\"。法院会要求你先证明按通常理解仍有两种解释。</p>\n<li><strong>\"通常理解\"的参照系</strong>：一个<strong>不具备保险或医学专业知识的普通人</strong>在阅读该条款时会怎么理解，而不是保险业内的专业理解。</li>\n<li><strong>适用场景举例</strong>：重疾险里\"恶性肿瘤\"是否包含原位癌、\"肢体缺失\"是否要求从腕关节还是肘关节、\"严重昏迷\"是否要求持续 96 小时——这些定义与医学通说不一致时，是典型的不利解释战场。</li>\n<li><strong>与\"隐性免责\"配合</strong>：先主张该条款实质是免责条款（武器三），再主张即便不是，也有两种解释应作有利解释（本武器）。双保险。</li>\n</ol>\n<p><strong>生活比喻</strong>：格式合同是出题人自己出的卷子。卷子出得含糊，分数判给考生，不判给出题人。</p>\n<hr>\n<h2 id=\"s7\">武器五 · 举证责任分配</h2>\n<p><strong>一句话定位：打官司打的就是举证。保险纠纷里举证责任是\"倾斜\"的，用足这个倾斜。</strong></p>\n<p><strong>依据</strong>：《保险法》第 22 条 + 司法解释（二）第 4、6、13 条。</p>\n<p><strong>规则拆解</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>待证事实</th><th>谁举证</th></tr></thead><tbody>\n<tr><td>保险事故发生、损失存在及程度</td><td>索赔方（<strong>以其\"所能提供\"为限</strong>——第 22 条的关键限定）</td></tr>\n<tr><td>保险人已履行提示和明确说明义务</td><td><strong>保险人</strong>（解释二 §13①）</td></tr>\n<tr><td>健康告知的询问范围与内容</td><td><strong>保险人</strong>（解释二 §6①）</td></tr>\n<tr><td>投保人不符合承保条件</td><td><strong>保险人</strong>（解释二 §4②）</td></tr>\n<tr><td>存在免责事由</td><td>保险人</td></tr>\n</tbody></table></div>\n<p><strong>要点</strong></p>\n<ol>\n<li><strong>\"所能提供\"是索赔方的保护伞。</strong> 第 22 条只要求提供\"其所能提供的\"证明和资料。被保险人提交了住院病案、诊断证明、基因检测报告等，即完成初步举证；保险人反驳需提交反证，不申请司法鉴定的承担<strong>举证不能的不利后果</strong>。</li>\n<li><strong>保险人要求补充材料必须\"及时一次性\"通知</strong>（第 22 条第 2 款）。反复要求补材料制造拖延的，可以主张其违反法定程序。</li>\n<li><strong>互联网投保特别提示</strong>：电子数据的举证（页面设计、勾选状态）由保险人掌握后台记录，可申请法院责令其提交。</li>\n</ol>\n<p><strong>生活比喻</strong>：打牌时，规则说明书在谁手里，谁就有义务把规则讲清楚。说明书在保险公司手里，所以\"规则没讲清楚\"这个风险由它背。</p>\n<hr>\n<h2 id=\"s8\">武器六 · 理赔核定与迟延赔付责任</h2>\n<p><strong>一句话定位：保险公司拖着不赔，本身就是一个独立的诉请。</strong></p>\n<p><strong>依据</strong>：《保险法》第 21、23、25、26 条。</p>\n<p><strong>规则拆解</strong></p>\n<ol>\n<li><strong>核定期限</strong>：收到理赔请求后应<strong>及时</strong>核定；情形复杂的应在 <strong>30 日内</strong>作出核定（合同另有约定除外），并<strong>通知核定结果</strong>（§23）。</li>\n<li><strong>赔付期限</strong>：属于保险责任的，达成赔付协议后 <strong>10 日内</strong>履行赔付义务。</li>\n<li><strong>迟延的法律后果</strong>：未及时履行的，<strong>除支付保险金外，还应当赔偿被保险人或者受益人因此受到的损失</strong>（§23 第 3 款）。这是可以单独主张的——车辆被修理厂留置产生的停运损失、贷款利息等，都可能落到保险人头上。</li>\n<li><strong>先予支付（§25）</strong>：自收到请求和有关证明资料之日起 <strong>60 日</strong>内，对赔偿数额不能确定的，应当<strong>先支付可以确定数额的最低部分</strong>。保险人主张\"金额没谈拢所以一分不给\"的，直接引这一条。</li>\n<li><strong>诉讼时效（§26）</strong>：非寿险 <strong>3 年</strong>、人寿保险 <strong>5 年</strong>，自知道或应当知道保险事故发生之日起算。</li>\n</ol>\n<p>&gt; <span class=\"warn\">!</span> <strong>实务更正</strong>：保险法 §26 白纸黑字写\"二年\"，但<strong>广州中院 (2025)粤01民终19766号</strong>认定应适用民法典的<strong>三年</strong>——理由：保险法该项规定系对当时民法通则两年时效的照准适用，属一般性规定，民法典改为三年后随之适用。    &gt; 起算点同样关键：<strong>知道或应当知道保险事故发生之日</strong>，不是客观出险日。该案中保险人一直未告知保单内容，被保险人 2024 年电话询问才得知，时效从那时起算。    &gt; 详见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7-%E7%AC%AC%E4%BA%8C%E8%BE%91\">《广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）》</a> V-A5。</p>\n<ol>\n<li><strong>出险通知（§21）</strong>：故意或重大过失未及时通知，致使事故性质、原因、损失程度<strong>难以确定</strong>的，保险人对<strong>无法确定的部分</strong>不担责。注意：是\"无法确定部分\"，不是全部。</li>\n</ol>\n<p><strong>生活比喻</strong>：保险公司不能既当裁判又当计时员。核定期限是法律给它设的闹钟，闹钟响了还没结果，就得赔你等待期间的损失。</p>\n<hr>\n<h2 id=\"s9\">武器七 · 近因原则</h2>\n<p><strong>一句话定位：多因一果时，决定\"赔不赔\"的那把尺子。保险法无明文，靠判例。</strong></p>\n<p><strong>规则拆解</strong></p>\n<ol>\n<li><strong>近因 ≠ 时间上最接近的原因</strong>，而是<strong>最主要、最有效、最直接</strong>的原因（对损失结果起决定性作用的原因）。</li>\n<li><strong>单一原因</strong>：该原因属于承保范围则赔，属于免责范围则不赔。</li>\n<li><strong>多因连续（链条式）</strong>：A→B→C，若链条未中断且前因是承保风险，一般认定前因为近因。</li>\n<li><strong>多因并存、相互独立</strong>：若承保风险与免责风险<strong>各自独立</strong>、可区分，一般只就承保风险造成的部分负责；若不可区分，实务中常结合<strong>不利解释</strong>（武器四）向被保险人倾斜。</li>\n<li><strong>典型战场</strong>：</li>\n<p>- 意外险：被保险人本身有心脏病，摔倒诱发心梗死亡 → 摔倒（意外）还是疾病是近因？    - 重疾险：交通事故导致需要进行合同约定的手术 → 意外还是疾病？    - 医疗险：既往症与本次治疗的关系。</p>\n</ol>\n<p><strong>实务打法</strong>：争取<strong>司法鉴定</strong>（死因鉴定、因果关系鉴定），把\"近因是什么\"从保险公司的一句话变成一个鉴定结论。保险人不申请鉴定的，主张其承担举证不能后果。</p>\n<p><strong>生活比喻</strong>：一排骨牌倒下，最后倒的那张牌不是原因，第一张被推倒的才是。法官要找的是\"第一张牌\"。</p>\n<hr>\n<h2 id=\"s10\">武器八 · 代位求偿与责任保险</h2>\n<p><strong>一句话定位：主要用在车险和责任险。搞清楚\"保险公司赔完之后能找谁算账\"。</strong></p>\n<p><strong>依据</strong>：《保险法》第 60–63、65 条 + 司法解释（四）第 7–9 条。</p>\n<p><strong>规则拆解</strong></p>\n<ol>\n<li><strong>代位求偿（§60）</strong>：因第三者对保险标的的损害造成保险事故，保险人自<strong>向被保险人赔偿保险金之日起</strong>，在<strong>赔偿金额范围内</strong>代位行使被保险人对第三者的赔偿请求权。</li>\n<li><strong>不影响被保险人就未获赔部分继续索赔</strong>（§60 第 3 款）。</li>\n<li><strong>对象限制（§62）</strong>：除被保险人的家庭成员或其组成人员<strong>故意</strong>造成的外，保险人<strong>不得</strong>对其行使代位求偿权。</li>\n<li><strong>被保险人弃权的后果（解释四 §9）</strong>：保险合同订立前已放弃对第三者索赔权利的，保险人相应部分不能代位；订立时保险人已询问而投保人未如实告知的，保险人可请求返还相应保险金。</li>\n<li><strong>责任保险（§65）</strong>：被保险人怠于请求的，<strong>第三者有权直接向保险人请求赔偿保险金</strong>。这是受害人一方的直接武器。</li>\n<li><strong><span class=\"warn\">!</span> 附：危险程度显著增加（§52）—— 车险拒赔的核心条款。</strong> 保险标的危险程度显著增加的，被保险人应<strong>按合同约定及时通知</strong>保险人；未履行通知义务，因危险程度显著增加而发生的事故，<strong>保险人不赔</strong>。</li>\n<p>- 判断标准见司法解释（四）第 4 条：用途改变、使用范围改变、所处环境变化、改装、使用人或管理人改变、持续时间等<strong>综合判断</strong>；增加的危险<strong>属于订约时保险人预见或应当预见的承保范围</strong>的，不构成显著增加。    - 广东判例倾向：<strong>不是\"只要跑过顺风车就拒赔\"</strong>，而是看接单频率、路线匹配度、收费性质、是否以营运为目的。低频、真实分摊成本的一般不构成。</p>\n</ol>\n<p><strong>生活比喻</strong>：代位求偿就是保险公司先替你掏钱，然后\"穿上你的鞋\"去告那个撞你的人——但它只能站在你的位置上，权利不会比你更多。</p>\n<hr>\n<h2 id=\"s11\">附：拿到拒赔通知书后的 30 分钟定位流程</h2>\n<ol>\n<li><strong>读拒赔理由</strong>，判断它落在哪一把武器上（通常是武器一、二、三）。</li>\n<li><strong>问三个问题</strong>：</li>\n<p>- 保险人依据的条款，是免责条款还是责任范围条款？（→ 隐性免责，武器三）    - 该条款提示和明确说明了吗？有证据吗？（→ 武器一）    - 如果是未如实告知，询问表里<strong>原文</strong>是怎么问的？（→ 武器二）</p>\n<li><strong>看时间轴</strong>：合同成立日 / 出险日 / 报案日 / 保险人知道解除事由日 / 解除通知发出日 / 起诉日。（→ 二年不可抗辩、30 日除斥期间、<strong>3 年诉讼时效</strong>）</li>\n<li><strong>定诉讼请求</strong>：保险金 + 迟延损失（武器六）+ 继续履行合同 / 保费豁免。</li>\n<li><strong>列证据清单</strong>：保单与条款、投保流程留痕、病历与诊断、理赔往来记录、拒赔通知书、解除通知书。</li>\n<li><strong>选路径</strong>：先 12378 / 12315 投诉留痕，不成再诉讼；同步评估诉前调解。</li>\n</ol>\n<blockquote>完整流程、时效速查表与文书模板见本站 <a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a> 篇。</blockquote>", "toc": [{"id": "s1", "lv": 2, "t": "武器一 · 提示说明义务（出现频率：★★★★★）"}, {"id": "s2", "lv": 3, "t": "2026 年广东二审新规则（A 级判例更新，必读）"}, {"id": "s3", "lv": 3, "t": "武器一 · 补遗：第二辑 A 级判例新增的三条硬规则"}, {"id": "s4", "lv": 2, "t": "武器二 · 如实告知义务与两年不可抗辩（出现频率：★★★★★）"}, {"id": "s5", "lv": 2, "t": "武器三 · 免责条款的认定（含隐性免责条款）"}, {"id": "s6", "lv": 2, "t": "武器四 · 不利解释规则（疑义利益解释）"}, {"id": "s7", "lv": 2, "t": "武器五 · 举证责任分配"}, {"id": "s8", "lv": 2, "t": "武器六 · 理赔核定与迟延赔付责任"}, {"id": "s9", "lv": 2, "t": "武器七 · 近因原则"}, {"id": "s10", "lv": 2, "t": "武器八 · 代位求偿与责任保险"}, {"id": "s11", "lv": 2, "t": "附：拿到拒赔通知书后的 30 分钟定位流程"}], "text": "八把通用武器 这一层是整个体系的地基。 重疾险、医疗险、意外险、车险看上去风马牛不相及， 但真打起来，90% 的案子翻来覆去就是这八把牌。 吃透这一层，拿到一份拒赔通知书 30 分钟内就能定位打法。 法条原文见本站 L4 法条库/00 法条与司法解释原文 篇（左侧导航「法条原文」）。本文只写规则与打法，不重复抄条文。 武器一 · 提示说明义务（出现频率：★★★★★） 一句话定位：绝大多数拒赔案的第一突破口。保险人拿免责条款拒赔，先问一句\"你提示和明确说明了吗\"。 依据 ：《保险法》第 17 条 + 司法解释（二）第 9–13 条； 并行的更锋利路径 ：《民法典》§496–498 + 《合同编通则司法解释》第 10 条 （2023 12 05 施行）。 规则拆解 0. 🔥 2023 年之后最重要的一条（电子投保直接适用） ——《合同编通则司法解释》第 10 条第 3 款： 提供格式条款的一方对其已经尽到提示义务或者说明义务承担举证责任。 对于通过互联网等信息网络订立的电子合同，提供格式条款的一方仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持 ，但是其举证符合前两款规定的除外。 同条第 1、2 款还明确了标准：提示 = \"通常足以引起对方注意的文字、符号、字体等 明显标识 \"；说明 = 就异常条款的 概念、内容及其法律后果 作出\" 通常能够理解 \"的解释说明。 ⚠️ 这直接击穿了互联网投保中\"你已经勾选了已阅读\"的抗辩。详见L1 险种层/07 互联网投保专章与L2 案例库/专题 提示说明义务与电子投保。 另可主张民法典 §496② ：未履行提示说明义务致对方未注意或未理解的， 对方可以主张该条款不成为合同的内容 （比\"不生效\"更彻底）。 1. \"提示\"和\"明确说明\"是两个义务，缺一不可。 提示 = 用文字、字体、符号等 足以引起注意 的标志标出来（加粗、加黑、阴影、变色）；明确说明 = 对该条款的 概念、内容及其法律后果 作出 常人能够理解 的解释说明。只加粗不解释，只完成了一半。 2. 哪些条款算\"免责条款\"？范围比想象的宽。 司法解释（二）第 9 条明确：责任免除条款、 免赔额、免赔率、比例赔付或者给付 等免除或减轻保险人责任的条款，都算。所以\"伤残按等级比例赔付\"\"医疗费只报 80%\"这类条款，一样要提示说明。 3. 网络投保同样适用。 司法解释（二）第 12 条：网络、电话订立的合同，保险人以 网页、音频、视频 形式提示和明确说明的，可以认定履行了义务。反过来讲——网页上没做，就是没做。 4. 举证责任在保险人。 司法解释（二）第 13 条第 1 款：保险人对其履行了明确说明义务 负举证责任 。这是我们的结构性优势。 5. ⚠️ 但有一个坑：签字确认。 司法解释（二）第 13 条第 2 款：投保人在相关文书上签字、盖章或以其他形式确认的， 应当认定保险人履行了该项义务 ，但有其他证据证明保险人未履行的除外。所以\"我只是在手机上点了同意\"往往不够，要找 其他证据 推翻（如销售聊天记录、回访录音、页面截屏证明没有强制阅读停留）。 保险人常见抗辩 → 破解点 抗辩 破解 \"条款已经加粗加黑了\" 加粗只完成\"提示\"，还要证明\"明确说明\"。要求其出示说明过程的证据（录音、视频、客服记录） \"投保单上有投保人签字\" 用第 13 条第 2 款但书：提交销售过程的聊天记录、电话回访录音，证明未实际说明 \"这是保险责任范围条款，不是免责条款，不用说明\" 引 隐性免责条款 规则（见武器三）：未标注为免责但暗含免除责任的，仍须提示说明 \"这是法律禁止性规定（如醉驾），提示即可\" 司法解释（二）第 10 条确实如此，但仍须 提示 ，且要确认该情形确属法律、行政法规的禁止性规定 证据清单 ：投保页面的完整截屏/录屏（含健康告知页、条款展示页、勾选与跳转逻辑）、电子投保单、保险条款全文、销售聊天记录、电话回访录音、付款凭证。 生活比喻 ：这就像药品说明书的\"黑框警告\"。药厂不能把不良反应塞在说明书第 38 页的小字里，然后说\"你自己没看\"。必须印在盒子最显眼的地方，还得让你看得懂。 2026 年广东二审新规则（A 级判例更新，必读） 以下均来自裁判文书网判决书原文，逐字摘录见L2 案例库/广东二审判决原文精读 A级。 ① 说明义务判\"结果\"，不判\"动作\" \"应以保险人有进行提示与解释说明的作为 且该作为达到使投保人了解免责条款内容的程度 ……因 视频直接跳转 而未能达到使投保人了解免责条款内容之认定标准\" ——深圳中院 (2025)粤03民终8930号 保险人提交了说明视频 ≠ 履行义务。 视频可跳过、自动跳转、默认勾选 = 未履行。 ② 加黑加粗 ≠ 明确说明 \"上述条款 虽然采用加黑、加粗方式提醒投保人注意 ，但……保险公司未能举证说明其对于先天性畸形的概念、内容作出具体解释，且为一般人能够知晓和理解\" ——广州中院 (2024)粤01民终28133号 \"提示\"与\"明确说明\"是 两项独立义务 。加黑加粗只完成前者。 ③ 引用 ICD 10/ICD O 3 却不列明内容 = 未说明 \" 并未将 ICD 10 中关于……的定义和分类在案涉保险合同中列明 ，亦未提供证据证明已就前述疾病……作出了常人能够理解的解释说明…… 更不能以投保人的签章行为推定其已完全理解 \" ——广州中院 (2026)粤01民终10449号 ④ 取证技巧：同页对比 \"第33 34页中77点对'严重Ⅰ型糖尿病'并发症的定义部分 并未有加粗加重或其他足以提醒投保人慎重阅读、理解的标识，与同页……其他重要条款字体的背景明显不一致 \" ——梅州中院 (2025)粤14民终795号 把条款那一页打印出来：别的条款加粗、争议条款没加粗 —— 对比本身就是证据。 ⑤ 电子签名只证明\"投保操作完成\" \" 电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务 \" ——湛江中院 (2026)粤08民终2074号 ⑥ 提交的\"示范视频\"不是本案投保轨迹 \" 某公司广州分公司提交的投保示范视频并非张某甲父亲代投保时的视频轨迹 ，仅凭投保单上'张某甲'的签名字样尚不足以证明\" ——广州中院 (2025)粤01民终24935号（一审说理，二审维持） → 要求保险人提供 本次投保的可回溯记录 （互联网保险可回溯是监管硬要求）。 ⑦ ⚠️ 反面：三件套齐备时法院会认定已履行 \"提交了投保单及投保人通过电子形式投保时的 照片 …… 在投保单上'投保人声明'处签名 ……相关保险条款中也 进行了加黑加粗 ，足以证实…… 本院认定已履行提示和明确说明义务 \" ——汕尾中院 (2025)粤15民终501号 别把全部筹码押在提示说明义务上。 评估胜诉可能时，先看自己这边是不是恰好三件套齐全。 武器一 · 补遗：第二辑 A 级判例新增的三条硬规则 1. 🔥 \"这是保险标的/保险责任范围条款，不是免责条款\"——这个挡箭牌已经失效。 江门中院 (2026)粤07民终1377号（家财险把金银珠宝排除出\"室内财产\"）： 该部分内容实际上系对保险责任范围中的室内财产范围 单方进行了限缩 ，限制了被保险人的权利及保险人的义务，该约定 已实质上构成免责条款 ，除非保险公司已就该部分内容尽到提示说明义务，否则对投保人不发生法律约束力。 2. 🔥 互联网投保的举证标准被法院量化了：要\"阅读时长、点击路径\"。 佛山中院 (2026)粤06民终4139号： 保险人应当完整保存投保人在销售页面的操作轨迹， 包括阅读时长、点击路径等关键节点 。然……未提交可验证的操作记录， 仅以投保人签字的格式化声明主张已履行说明义务，此证据不足以证明 其履行了对相应免责条款的提示说明义务。 → 庭审上直接按这个口径要求对方举证：把操作轨迹拿出来。 3. 🔥 只提交\"同类产品/示范流程\"公证书或视频 = 未举证。 广州中院 (2025)粤01民终19766号：保险人仅提交 同类保险产品 的投保流程公证书，法院认定未能证明 已向投保人本人 作出提示说明 → 《投保须知》中限制保额的条款不生效，按保单载明金额全额赔付 150 万。 4. ⚠️ 但请注意反面 ：中山中院 (2025)粤20民终2567号认定\" 加粗加黑 + 强制停留阅读程序 + 阅读后勾选 + 条款内容明确无歧义 \"四件套齐备 = 已履行。四件套中的每一项都可以单独质证（加粗了但可跳过？停留了但没显示全文？），见L2 案例库/广东二审判决原文精读 A级 第二辑 V D3。 武器二 · 如实告知义务与两年不可抗辩（出现频率：★★★★★） 一句话定位：保险人拒赔的第二大理由。核心战场不在\"你有没有说\"，而在\"他有没有问、怎么问的\"。 依据 ：《保险法》第 16 条 + 司法解释（二）第 5–8 条 + 司法解释（三）第 5 条。 规则拆解 1. 告知义务以\"询问\"为前提。 第 16 条第 1 款：保险人 就有关情况提出询问的 ，投保人才如实告知。 没问就不用说。 这是最重要的边界。 2. 告知范围 = 询问范围。 司法解释（二）第 6 条第 1 款：告知义务 限于保险人询问的范围和内容 ；对询问范围有争议的， 保险人负举证责任 。 3. 概括性询问无效。 司法解释（二）第 6 条第 2 款：保险人以投保人违反 概括性条款 （如\"有无其他疾病\"\"身体是否有异常\"）的告知义务为由解除合同的， 法院不予支持 ，除非该概括性条款有具体内容。 4. 只告知\"明知\"的事项。 司法解释（二）第 5 条：投保人 明知 的才属于应告知内容。不知道的体检异常，不构成违反义务。 5. 两年不可抗辩。 第 16 条第 3 款：合同解除权自保险人知道解除事由之日起 30 日 不行使而消灭； 自合同成立之日起超过 2 年，保险人不得解除合同 。 6. ⚠️ 两个重要限制 ：① 保险人 未行使解除权直接拒赔 的，法院不予支持（司法解释二第 8 条）——必须先解除再拒赔；② 保险人知情后 仍收取保费 的，不得再解除（司法解释二第 7 条）。 7. 体检不免除告知义务，但保险人知道体检结果的除外。 司法解释（三）第 5 条。 保险人常见抗辩 → 破解点 抗辩 破解 \"你投保前有结节/指标异常没说\" ① 询问表上是否有 具体、明确 的对应问题？② 该异常是否属于投保人\"明知\"？③ 该异常与所患疾病有无 因果关系 ？ \"你没告知肿瘤家族史\" 电子投保单只问了\"遗传性疾病\"的，不算询问了家族史 \"你在其他公司投保超过 50 万没说\" 即使问了，还要看保险人是否在 法定期限内 行使解除权 \"这是恶意骗保，不适用两年不可抗辩\" 两年不可抗辩的例外限于故意不履行告知义务且保险事故在合同成立前已发生；要求保险人举证 证据清单 ：健康告知页完整截屏（ 每一条询问的原文表述 ）、投保时的体检报告、就诊记录、投保时间与确诊时间的时间轴、保险人的解除合同通知书（ 注意落款时间与知道解除事由的时间差 ）。 生活比喻 ：相亲时\"问什么答什么\"。对方没问你有没有房，你不必主动交代；但问了就得说实话。反之，对方问一句\"你人没问题吧\"这种含糊问题，等于没问——法律上这叫\"概括性询问\"，不能拿来当拒赔理由。 ⚠️ 时效陷阱 ：保险人知道解除事由后 30 日内必须行使解除权，超期消灭。实务中保险公司常拖到理赔阶段才发解除通知， 这个时间差就是我们的武器 （广州天河法院那起网络投保重疾险案，保险人受理理赔申请 35 天后才发解除通知，被认定超期）。 武器三 · 免责条款的认定（含隐性免责条款） 一句话定位：把保险人藏在\"保险责任\"章节里的地雷挖出来。 依据 ：《保险法》第 17、19 条 + 司法解释（二）第 9 条 + 人民法院案例库裁判规则。 规则拆解 1. 免责条款不限于\"责任免除\"那几段。 司法解释（二）第 9 条第 1 款列举了免赔额、免赔率、比例赔付等，实质标准是\" 免除或者减轻保险人责任 \"。 2. 隐性免责条款（最狠的一招）。 有些条款写在\"保险责任\"章节，表面在说\"保什么\"，实际在说\"这种情况下不保\"。人民法院案例库明确规则： 未标注或提示为免责条款但暗含免除责任情形的，属于隐性免责条款，保险人应当单独明确告知说明，否则不发生效力。 3. 注意第 9 条第 2 款的反向规定 ：保险人因投保人、被保险人违反法定或约定义务而 享有解除合同权利 的条款， 不属于 第 17 条第 2 款的免责条款（即无需按免责条款标准说明）——这是保险人的抗辩路径，要预判。 4. 格式条款无效（第 19 条） ：免除保险人依法应承担的义务、加重投保人责任、排除投保人/被保险人/受益人依法享有的权利的条款 无效 。这与\"未提示说明不生效\"是两条路，可以并列主张。 实战动作 ：拿到条款后，做一次\" 责任范围反向扫描 \"——把保险责任章节里所有带\"但\"\"除外\"\"仅限于\"\"须满足以下条件\"\"不包括\"字样的句子全部摘出来，逐条问保险人：这条你提示说明了吗？ 生活比喻 ：菜单的\"推荐菜\"栏里写着\"本店不提供\"，这就是隐性免责条款。它不长得像免责，但效果一样。 武器四 · 不利解释规则（疑义利益解释） 一句话定位：条款有歧义时的兜底武器。便宜但好用。 依据 ：《保险法》第 30 条。 规则拆解 1. 两步走，不能跳步。 第 30 条的顺序是：先按 通常理解 解释 → 仍有两种以上解释 的，才作有利于被保险人和受益人的解释。 ⚠️ 常见误用：一上来就喊\"应作不利于保险人的解释\"。法院会要求你先证明按通常理解仍有两种解释。 2. \"通常理解\"的参照系 ：一个 不具备保险或医学专业知识的普通人 在阅读该条款时会怎么理解，而不是保险业内的专业理解。 3. 适用场景举例 ：重疾险里\"恶性肿瘤\"是否包含原位癌、\"肢体缺失\"是否要求从腕关节还是肘关节、\"严重昏迷\"是否要求持续 96 小时——这些定义与医学通说不一致时，是典型的不利解释战场。 4. 与\"隐性免责\"配合 ：先主张该条款实质是免责条款（武器三），再主张即便不是，也有两种解释应作有利解释（本武器）。双保险。 生活比喻 ：格式合同是出题人自己出的卷子。卷子出得含糊，分数判给考生，不判给出题人。 武器五 · 举证责任分配 一句话定位：打官司打的就是举证。保险纠纷里举证责任是\"倾斜\"的，用足这个倾斜。 依据 ：《保险法》第 22 条 + 司法解释（二）第 4、6、13 条。 规则拆解 待证事实 谁举证 保险事故发生、损失存在及程度 索赔方（ 以其\"所能提供\"为限 ——第 22 条的关键限定） 保险人已履行提示和明确说明义务 保险人 （解释二 §13①） 健康告知的询问范围与内容 保险人 （解释二 §6①） 投保人不符合承保条件 保险人 （解释二 §4②） 存在免责事由 保险人 要点 1. \"所能提供\"是索赔方的保护伞。 第 22 条只要求提供\"其所能提供的\"证明和资料。被保险人提交了住院病案、诊断证明、基因检测报告等，即完成初步举证；保险人反驳需提交反证，不申请司法鉴定的承担 举证不能的不利后果 。 2. 保险人要求补充材料必须\"及时一次性\"通知 （第 22 条第 2 款）。反复要求补材料制造拖延的，可以主张其违反法定程序。 3. 互联网投保特别提示 ：电子数据的举证（页面设计、勾选状态）由保险人掌握后台记录，可申请法院责令其提交。 生活比喻 ：打牌时，规则说明书在谁手里，谁就有义务把规则讲清楚。说明书在保险公司手里，所以\"规则没讲清楚\"这个风险由它背。 武器六 · 理赔核定与迟延赔付责任 一句话定位：保险公司拖着不赔，本身就是一个独立的诉请。 依据 ：《保险法》第 21、23、25、26 条。 规则拆解 1. 核定期限 ：收到理赔请求后应 及时 核定；情形复杂的应在 30 日内 作出核定（合同另有约定除外），并 通知核定结果 （§23）。 2. 赔付期限 ：属于保险责任的，达成赔付协议后 10 日内 履行赔付义务。 3. 迟延的法律后果 ：未及时履行的， 除支付保险金外，还应当赔偿被保险人或者受益人因此受到的损失 （§23 第 3 款）。这是可以单独主张的——车辆被修理厂留置产生的停运损失、贷款利息等，都可能落到保险人头上。 4. 先予支付（§25） ：自收到请求和有关证明资料之日起 60 日 内，对赔偿数额不能确定的，应当 先支付可以确定数额的最低部分 。保险人主张\"金额没谈拢所以一分不给\"的，直接引这一条。 5. 诉讼时效（§26） ：非寿险 3 年 、人寿保险 5 年 ，自知道或应当知道保险事故发生之日起算。 ⚠️ 实务更正 ：保险法 §26 白纸黑字写\"二年\"，但 广州中院 (2025)粤01民终19766号 认定应适用民法典的 三年 ——理由：保险法该项规定系对当时民法通则两年时效的照准适用，属一般性规定，民法典改为三年后随之适用。 起算点同样关键： 知道或应当知道保险事故发生之日 ，不是客观出险日。该案中保险人一直未告知保单内容，被保险人 2024 年电话询问才得知，时效从那时起算。 详见L2 案例库/广东二审判决原文精读 A级 第二辑 V A5。 6. 出险通知（§21） ：故意或重大过失未及时通知，致使事故性质、原因、损失程度 难以确定 的，保险人对 无法确定的部分 不担责。注意：是\"无法确定部分\"，不是全部。 生活比喻 ：保险公司不能既当裁判又当计时员。核定期限是法律给它设的闹钟，闹钟响了还没结果，就得赔你等待期间的损失。 武器七 · 近因原则 一句话定位：多因一果时，决定\"赔不赔\"的那把尺子。保险法无明文，靠判例。 规则拆解 1. 近因 ≠ 时间上最接近的原因 ，而是 最主要、最有效、最直接 的原因（对损失结果起决定性作用的原因）。 2. 单一原因 ：该原因属于承保范围则赔，属于免责范围则不赔。 3. 多因连续（链条式） ：A→B→C，若链条未中断且前因是承保风险，一般认定前因为近因。 4. 多因并存、相互独立 ：若承保风险与免责风险 各自独立 、可区分，一般只就承保风险造成的部分负责；若不可区分，实务中常结合 不利解释 （武器四）向被保险人倾斜。 5. 典型战场 ： 意外险：被保险人本身有心脏病，摔倒诱发心梗死亡 → 摔倒（意外）还是疾病是近因？ 重疾险：交通事故导致需要进行合同约定的手术 → 意外还是疾病？ 医疗险：既往症与本次治疗的关系。 实务打法 ：争取 司法鉴定 （死因鉴定、因果关系鉴定），把\"近因是什么\"从保险公司的一句话变成一个鉴定结论。保险人不申请鉴定的，主张其承担举证不能后果。 生活比喻 ：一排骨牌倒下，最后倒的那张牌不是原因，第一张被推倒的才是。法官要找的是\"第一张牌\"。 武器八 · 代位求偿与责任保险 一句话定位：主要用在车险和责任险。搞清楚\"保险公司赔完之后能找谁算账\"。 依据 ：《保险法》第 60–63、65 条 + 司法解释（四）第 7–9 条。 规则拆解 1. 代位求偿（§60） ：因第三者对保险标的的损害造成保险事故，保险人自 向被保险人赔偿保险金之日起 ，在 赔偿金额范围内 代位行使被保险人对第三者的赔偿请求权。 2. 不影响被保险人就未获赔部分继续索赔 （§60 第 3 款）。 3. 对象限制（§62） ：除被保险人的家庭成员或其组成人员 故意 造成的外，保险人 不得 对其行使代位求偿权。 4. 被保险人弃权的后果（解释四 §9） ：保险合同订立前已放弃对第三者索赔权利的，保险人相应部分不能代位；订立时保险人已询问而投保人未如实告知的，保险人可请求返还相应保险金。 5. 责任保险（§65） ：被保险人怠于请求的， 第三者有权直接向保险人请求赔偿保险金 。这是受害人一方的直接武器。 6. ⚠️ 附：危险程度显著增加（§52）—— 车险拒赔的核心条款。 保险标的危险程度显著增加的，被保险人应 按合同约定及时通知 保险人；未履行通知义务，因危险程度显著增加而发生的事故， 保险人不赔 。 判断标准见司法解释（四）第 4 条：用途改变、使用范围改变、所处环境变化、改装、使用人或管理人改变、持续时间等 综合判断 ；增加的危险 属于订约时保险人预见或应当预见的承保范围 的，不构成显著增加。 广东判例倾向： 不是\"只要跑过顺风车就拒赔\" ，而是看接单频率、路线匹配度、收费性质、是否以营运为目的。低频、真实分摊成本的一般不构成。 生活比喻 ：代位求偿就是保险公司先替你掏钱，然后\"穿上你的鞋\"去告那个撞你的人——但它只能站在你的位置上，权利不会比你更多。 附：拿到拒赔通知书后的 30 分钟定位流程 1. 读拒赔理由 ，判断它落在哪一把武器上（通常是武器一、二、三）。 2. 问三个问题 ： 保险人依据的条款，是免责条款还是责任范围条款？（→ 隐性免责，武器三） 该条款提示和明确说明了吗？有证据吗？（→ 武器一） 如果是未如实告知，询问表里 原文 是怎么问的？（→ 武器二） 3. 看时间轴 ：合同成立日 / 出险日 / 报案日 / 保险人知道解除事由日 / 解除通知发出日 / 起诉日。（→ 二年不可抗辩、30 日除斥期间、 3 年诉讼时效 ） 4. 定诉讼请求 ：保险金 + 迟延损失（武器六）+ 继续履行合同 / 保费豁免。 5. 列证据清单 ：保单与条款、投保流程留痕、病历与诊断、理赔往来记录、拒赔通知书、解除通知书。 6. 选路径 ：先 12378 / 12315 投诉留痕，不成再诉讼；同步评估诉前调解。 完整流程、时效速查表与文书模板见本站 L0 打法层/02 维权操作全流程 篇。"}, {"id": "L0-打法层/02-维权操作全流程", "group": "1 · 通用打法", "groupKey": "L0-打法层", "title": "维权操作全流程（从拒赔到执行）", "order": 1, "file": "02-维权操作全流程.md", "html": "<h1 id=\"s0\">维权操作全流程（从拒赔到执行）</h1>\n<blockquote>面向实操。拿到案件后按本文件的顺序走一遍，不会漏动作。</blockquote>\n<hr>\n<h2 id=\"s1\">一、时效速查表（先看这个，超时就全完了）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>期间</th><th>长度</th><th>起算点</th><th>依据</th><th>后果</th></tr></thead><tbody>\n<tr><td><strong>诉讼时效 · 非寿险</strong>（车险、医疗险、意外险、财产险）</td><td><strong>3 年</strong>（§26 写 2 年，但法院按民法典适用 3 年，见注）</td><td>知道或应当知道保险事故发生之日</td><td>§26① + 民法典 §188</td><td>超期丧失胜诉权</td></tr>\n<tr><td><strong>诉讼时效 · 人寿保险</strong></td><td><strong>5 年</strong></td><td>同上</td><td>§26②</td><td>同上</td></tr>\n<tr><td><strong>保险人解除权 · 一般</strong></td><td>30 日</td><td>保险人知道解除事由之日</td><td>§16③</td><td>超期消灭</td></tr>\n<tr><td><strong>保险人解除权 · 最长期间</strong></td><td>2 年</td><td>合同成立之日</td><td>§16③</td><td>超期不得解除（不可抗辩）</td></tr>\n</tbody></table></div>\n<blockquote><span class=\"warn\">!</span> <strong>时效更正</strong>：广州中院 (2025)粤01民终19766号认定非寿险适用<strong>三年</strong>诉讼时效（保险法 §26 两年规定系照准民法通则，属一般性规定）。且起算点为\"知道或应当知道保险事故发生之日\"——该案出险在 2020 年，因保险人未告知保单内容，被保险人 2024 年才知情，2025 年起诉仍获支持。</blockquote>\n<p>| <strong>核定期间</strong> | 及时 / 复杂 30 日 | 收到理赔请求及资料之日 | §23① | 超期须赔偿损失 | | <strong>赔付期间</strong> | 10 日 | 达成赔付协议后 | §23① | 同上 | | <strong>先予支付</strong> | 60 日 | 收到请求及证明资料之日 | §25 | 应支付可确定最低数额 | | <strong>出险通知</strong> | 及时 | 知道保险事故发生 | §21 | 致使难以确定的部分不赔 |</p>\n<p><strong><span class=\"warn\">!</span> 最常见的三个死法</strong></p>\n<ol>\n<li>跟保险公司\"再谈谈\"，谈了三年，诉讼时效过了。</li>\n<li>收到拒赔通知后只顾生气，忘了<strong>保险人解除权有 30 日 + 2 年的双重限制</strong>——这两个其实是我们的武器，但要主动主张。</li>\n<li>以为\"解除合同通知\"就等于合同真的解除了——没有解除权或者超期行使的，解除无效。</li>\n</ol>\n<hr>\n<h2 id=\"s2\">二、证据清单</h2>\n<h3 id=\"s3\">通用（所有险种都要）</h3>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保险单 / 电子保单（<strong>含特别约定页</strong>——很多地雷埋在这里）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保险条款全文（<strong>投保时的版本</strong>，不是现在的版本）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 投保单 / 电子投保流程留痕（<strong>健康告知页逐条截屏或录屏</strong>）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保费支付凭证</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 拒赔通知书（<strong>书面</strong>，口头拒赔要录音或要求出具书面文件）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 解除合同通知书（如有——注意落款日期与送达日期）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 与保险公司/销售人员的全部沟通记录（电话录音、微信、App 内消息、邮件）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 电话回访录音（可向保险公司申请调取；其拒绝提供的，主张不利推定）</div>\n<h3 id=\"s4\">人身险（重疾 / 医疗 / 寿险 / 意外）</h3>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 完整住院病案（<strong>含入院记录、出院小结、手术记录、病理报告、检查报告</strong>）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 诊断证明书</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 门诊病历、体检报告（投保前 + 投保后）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 基因检测报告（罕见病、遗传性疾病案件）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 医疗费用发票、费用清单、医保结算单</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 伤残鉴定报告（意外险）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 死亡证明、户籍注销证明、亲属关系证明（身故理赔）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 日常生活能力受损的音视频证据（\"自主生活能力丧失\"类条款）</div>\n<h3 id=\"s5\">财产险 / 车险</h3>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 交通事故认定书</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 定损单、维修清单与发票</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 车辆行驶证、驾驶证、营运资质（<strong>使用性质争议的核心</strong>）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 平台接单记录（顺风车、网约车、货拉拉等——<strong>保险人也会去调，我方要先拿到</strong>）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 现场照片、行车记录仪视频</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 停运损失证明（营运车辆：营运证、收入流水）</div>\n<h3 id=\"s6\"><span class=\"warn\">!</span> 互联网投保（支付宝 / 微信 / App）的特别动作</h3>\n<p><strong>投保当下就要做，出险后再补就晚了：</strong></p>\n<ol>\n<li>用另一台手机<strong>全程录屏</strong>（从打开商品页到付款完成），不要只截屏。</li>\n<li>录屏要完整覆盖：健康告知页逐条 → 条款链接点开 → 勾选/同意动作 → 支付确认。</li>\n<li>保存<strong>订单快照</strong>（平台一般有\"保单详情-投保时的页面版本\"入口）。</li>\n<li>与在线客服的对话<strong>截图并导出</strong>，不要只留在 App 里（App 内容平台可修改）。</li>\n<li>记下<strong>投保时间戳</strong>——用于证明保险人是否在法定期限内行使解除权。</li>\n</ol>\n<hr>\n<h2 id=\"s7\">三、维权路径（由低成本到高成本）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>顺序</th><th>路径</th><th>适用</th><th>注意</th></tr></thead><tbody>\n<tr><td>1</td><td><strong>与保险公司协商 / 投诉其总部</strong></td><td>所有</td><td>全程留痕，书面化；不要只打电话</td></tr>\n<tr><td>2</td><td><strong>12378</strong>（金融监管总局消费者投诉热线）</td><td>所有保险纠纷</td><td>保险公司有处理时限压力，<strong>性价比最高的第一步</strong></td></tr>\n<tr><td>3</td><td><strong>12315</strong> / 消协</td><td>涉及销售误导、虚假宣传</td><td>调解不具强制执行力</td></tr>\n<tr><td>4</td><td><strong>银行业保险业消费纠纷调解</strong>（各地调解中心）</td><td>金额不大、事实清楚</td><td>调解协议可申请司法确认</td></tr>\n<tr><td>5</td><td><strong>法院诉前调解</strong></td><td>已准备起诉</td><td>可以此促成保险公司让步</td></tr>\n<tr><td>6</td><td><strong>诉讼</strong></td><td>争议金额大 / 保险人态度强硬</td><td>见下</td></tr>\n</tbody></table></div>\n<p><strong>判断标准</strong>：争议金额 &lt; 2 万且事实清楚的，走 12378 + 调解；金额大或涉及条款效力认定（有先例价值的），直接诉讼。</p>\n<hr>\n<h2 id=\"s8\">四、管辖</h2>\n<ul>\n<li>财产保险：一般由<strong>被告住所地</strong>或者<strong>保险标的物所在地</strong>法院管辖。</li>\n<li>人身保险：一般由<strong>被告住所地</strong>法院管辖；实务中被保险人住所地法院常予受理，需在起诉前确认当地口径。</li>\n<li>保险合同<strong>约定仲裁</strong>的，走仲裁，不能起诉（<strong>先看保单争议解决条款</strong>）。</li>\n<li>海上保险、铁路运输等适用专门管辖。</li>\n</ul>\n<p><span class=\"warn\">!</span> <strong>起诉前第一件事：翻到保单最后看争议解决条款。</strong> 有仲裁条款却去法院起诉，会被驳回。</p>\n<hr>\n<h2 id=\"s9\">五、诉讼请求设计（别只写\"判令赔付保险金\"）</h2>\n<ol>\n<li><strong>主请求</strong>：判令被告支付保险金 XXX 元。</li>\n<li><strong>迟延损失</strong>（§23 第 3 款）：自应赔付之日起的利息损失 / 停运损失 / 其他实际损失。<strong>很多律师会漏，白给保险公司省了一笔。</strong></li>\n<li><strong>继续履行合同</strong>：涉及\"合同解除\"争议的，一并请求确认解除行为无效、合同继续有效。</li>\n<li><strong>保费豁免</strong>：重疾/轻症理赔中，若合同有豁免条款，一并主张。</li>\n<li><strong>诉讼费、鉴定费</strong>由被告承担。</li>\n</ol>\n<hr>\n<h2 id=\"s10\">六、鉴定：什么时候申请</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>争议类型</th><th>鉴定种类</th></tr></thead><tbody>\n<tr><td>伤残等级（意外险）</td><td>法医临床鉴定（注意合同约定的是《人身保险伤残评定标准》还是《人体损伤致残程度分级》）</td></tr>\n<tr><td>死因不明</td><td>尸体解剖 / 死因鉴定</td></tr>\n<tr><td>疾病是否符合条款定义</td><td>一般<strong>不做</strong>司法鉴定（属合同条款解释问题，由法院认定），但可申请<strong>专家辅助人</strong>出庭</td></tr>\n<tr><td>笔迹（代签名争议）</td><td>文书司法鉴定</td></tr>\n<tr><td>车辆损失</td><td>车损评估</td></tr>\n</tbody></table></div>\n<p><strong>战术要点</strong>：保险人对\"是否符合理赔条件\"有异议却不申请鉴定的，主张其承担<strong>举证不能的不利后果</strong>。</p>\n<hr>\n<h2 id=\"s11\">七、庭审攻防：保险人举证清单与我方质证点</h2>\n<p>保险人通常会提交这些证据，逐个质证：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>保险人证据</th><th>质证点</th></tr></thead><tbody>\n<tr><td>投保单（有投保人签字）</td><td>签字是否本人？是否为<strong>电子勾选</strong>？是否有证据证明签字前已阅读条款？有无销售误导？</td></tr>\n<tr><td>条款（加粗加黑版）</td><td>是否系<strong>投保时</strong>的版本？加粗是否覆盖争议条款？是否对专业术语作了解释？</td></tr>\n<tr><td>健康告知问卷</td><td>询问是否<strong>具体、明确</strong>？是否为概括性询问？争议事项是否在询问范围内？</td></tr>\n<tr><td>回访录音</td><td>回访是否只问\"是否本人投保、是否了解条款\"这种形式化问题？有无逐条说明免责条款？</td></tr>\n<tr><td>体检报告 / 既往就诊记录</td><td>该异常与本次保险事故有无<strong>因果关系</strong>？投保人是否\"明知\"？</td></tr>\n<tr><td>拒赔/解除通知</td><td><strong>发出时间</strong>是否在知道解除事由后 30 日内？合同是否成立满 2 年？</td></tr>\n<tr><td>网页投保流程公证</td><td>公证的是否为<strong>投保时</strong>的页面版本？是否证明投保人<strong>实际停留阅读</strong>？</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s12\">八、执行阶段提醒</h2>\n<ul>\n<li>保险公司一般履行能力无虞，重点是<strong>判决书生效后及时申请执行</strong>并主张迟延履行利息。</li>\n<li>涉及\"继续履行合同 + 保费豁免\"的，确认保险公司系统内是否实际恢复了保单效力。</li>\n</ul>\n<hr>\n<h2 id=\"s13\">九、常见翻车点清单（自查）</h2>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 诉讼时效还剩多久？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保单里有没有仲裁条款？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保险人有没有<strong>先解除</strong>合同再拒赔？（没解除直接拒赔 = 违法，§解释二 8）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保险人解除权的 30 日 / 2 年期间有没有超？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 争议条款到底是免责条款还是责任范围条款？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 我有没有拿到<strong>投保时的条款版本</strong>？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 有没有申请法院责令保险人提交后台电子数据？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 迟延损失有没有一并主张？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 有没有漏了\"继续履行合同 / 保费豁免\"的请求？</div>", "toc": [{"id": "s1", "lv": 2, "t": "一、时效速查表（先看这个，超时就全完了）"}, {"id": "s2", "lv": 2, "t": "二、证据清单"}, {"id": "s3", "lv": 3, "t": "通用（所有险种都要）"}, {"id": "s4", "lv": 3, "t": "人身险（重疾 / 医疗 / 寿险 / 意外）"}, {"id": "s5", "lv": 3, "t": "财产险 / 车险"}, {"id": "s6", "lv": 3, "t": "! 互联网投保（支付宝 / 微信 / App）的特别动作"}, {"id": "s7", "lv": 2, "t": "三、维权路径（由低成本到高成本）"}, {"id": "s8", "lv": 2, "t": "四、管辖"}, {"id": "s9", "lv": 2, "t": "五、诉讼请求设计（别只写\"判令赔付保险金\"）"}, {"id": "s10", "lv": 2, "t": "六、鉴定：什么时候申请"}, {"id": "s11", "lv": 2, "t": "七、庭审攻防：保险人举证清单与我方质证点"}, {"id": "s12", "lv": 2, "t": "八、执行阶段提醒"}, {"id": "s13", "lv": 2, "t": "九、常见翻车点清单（自查）"}], "text": "维权操作全流程（从拒赔到执行） 面向实操。拿到案件后按本文件的顺序走一遍，不会漏动作。 一、时效速查表（先看这个，超时就全完了） 期间 长度 起算点 依据 后果 诉讼时效 · 非寿险 （车险、医疗险、意外险、财产险） 3 年 （§26 写 2 年，但法院按民法典适用 3 年，见注） 知道或应当知道保险事故发生之日 §26① + 民法典 §188 超期丧失胜诉权 诉讼时效 · 人寿保险 5 年 同上 §26② 同上 保险人解除权 · 一般 30 日 保险人知道解除事由之日 §16③ 超期消灭 保险人解除权 · 最长期间 2 年 合同成立之日 §16③ 超期不得解除（不可抗辩） ⚠️ 时效更正 ：广州中院 (2025)粤01民终19766号认定非寿险适用 三年 诉讼时效（保险法 §26 两年规定系照准民法通则，属一般性规定）。且起算点为\"知道或应当知道保险事故发生之日\"——该案出险在 2020 年，因保险人未告知保单内容，被保险人 2024 年才知情，2025 年起诉仍获支持。 核定期间 及时 / 复杂 30 日 收到理赔请求及资料之日 §23① 超期须赔偿损失 赔付期间 10 日 达成赔付协议后 §23① 同上 先予支付 60 日 收到请求及证明资料之日 §25 应支付可确定最低数额 出险通知 及时 知道保险事故发生 §21 致使难以确定的部分不赔 ⏰ 最常见的三个死法 1. 跟保险公司\"再谈谈\"，谈了三年，诉讼时效过了。 2. 收到拒赔通知后只顾生气，忘了 保险人解除权有 30 日 + 2 年的双重限制 ——这两个其实是我们的武器，但要主动主张。 3. 以为\"解除合同通知\"就等于合同真的解除了——没有解除权或者超期行使的，解除无效。 二、证据清单 通用（所有险种都要） [ ] 保险单 / 电子保单（ 含特别约定页 ——很多地雷埋在这里） [ ] 保险条款全文（ 投保时的版本 ，不是现在的版本） [ ] 投保单 / 电子投保流程留痕（ 健康告知页逐条截屏或录屏 ） [ ] 保费支付凭证 [ ] 拒赔通知书（ 书面 ，口头拒赔要录音或要求出具书面文件） [ ] 解除合同通知书（如有——注意落款日期与送达日期） [ ] 与保险公司/销售人员的全部沟通记录（电话录音、微信、App 内消息、邮件） [ ] 电话回访录音（可向保险公司申请调取；其拒绝提供的，主张不利推定） 人身险（重疾 / 医疗 / 寿险 / 意外） [ ] 完整住院病案（ 含入院记录、出院小结、手术记录、病理报告、检查报告 ） [ ] 诊断证明书 [ ] 门诊病历、体检报告（投保前 + 投保后） [ ] 基因检测报告（罕见病、遗传性疾病案件） [ ] 医疗费用发票、费用清单、医保结算单 [ ] 伤残鉴定报告（意外险） [ ] 死亡证明、户籍注销证明、亲属关系证明（身故理赔） [ ] 日常生活能力受损的音视频证据（\"自主生活能力丧失\"类条款） 财产险 / 车险 [ ] 交通事故认定书 [ ] 定损单、维修清单与发票 [ ] 车辆行驶证、驾驶证、营运资质（ 使用性质争议的核心 ） [ ] 平台接单记录（顺风车、网约车、货拉拉等—— 保险人也会去调，我方要先拿到 ） [ ] 现场照片、行车记录仪视频 [ ] 停运损失证明（营运车辆：营运证、收入流水） ⚠️ 互联网投保（支付宝 / 微信 / App）的特别动作 投保当下就要做，出险后再补就晚了： 1. 用另一台手机 全程录屏 （从打开商品页到付款完成），不要只截屏。 2. 录屏要完整覆盖：健康告知页逐条 → 条款链接点开 → 勾选/同意动作 → 支付确认。 3. 保存 订单快照 （平台一般有\"保单详情 投保时的页面版本\"入口）。 4. 与在线客服的对话 截图并导出 ，不要只留在 App 里（App 内容平台可修改）。 5. 记下 投保时间戳 ——用于证明保险人是否在法定期限内行使解除权。 三、维权路径（由低成本到高成本） 顺序 路径 适用 注意 1 与保险公司协商 / 投诉其总部 所有 全程留痕，书面化；不要只打电话 2 12378 （金融监管总局消费者投诉热线） 所有保险纠纷 保险公司有处理时限压力， 性价比最高的第一步 3 12315 / 消协 涉及销售误导、虚假宣传 调解不具强制执行力 4 银行业保险业消费纠纷调解 （各地调解中心） 金额不大、事实清楚 调解协议可申请司法确认 5 法院诉前调解 已准备起诉 可以此促成保险公司让步 6 诉讼 争议金额大 / 保险人态度强硬 见下 判断标准 ：争议金额 < 2 万且事实清楚的，走 12378 + 调解；金额大或涉及条款效力认定（有先例价值的），直接诉讼。 四、管辖 财产保险：一般由 被告住所地 或者 保险标的物所在地 法院管辖。 人身保险：一般由 被告住所地 法院管辖；实务中被保险人住所地法院常予受理，需在起诉前确认当地口径。 保险合同 约定仲裁 的，走仲裁，不能起诉（ 先看保单争议解决条款 ）。 海上保险、铁路运输等适用专门管辖。 ⚠️ 起诉前第一件事：翻到保单最后看争议解决条款。 有仲裁条款却去法院起诉，会被驳回。 五、诉讼请求设计（别只写\"判令赔付保险金\"） 1. 主请求 ：判令被告支付保险金 XXX 元。 2. 迟延损失 （§23 第 3 款）：自应赔付之日起的利息损失 / 停运损失 / 其他实际损失。 很多律师会漏，白给保险公司省了一笔。 3. 继续履行合同 ：涉及\"合同解除\"争议的，一并请求确认解除行为无效、合同继续有效。 4. 保费豁免 ：重疾/轻症理赔中，若合同有豁免条款，一并主张。 5. 诉讼费、鉴定费 由被告承担。 六、鉴定：什么时候申请 争议类型 鉴定种类 伤残等级（意外险） 法医临床鉴定（注意合同约定的是《人身保险伤残评定标准》还是《人体损伤致残程度分级》） 死因不明 尸体解剖 / 死因鉴定 疾病是否符合条款定义 一般 不做 司法鉴定（属合同条款解释问题，由法院认定），但可申请 专家辅助人 出庭 笔迹（代签名争议） 文书司法鉴定 车辆损失 车损评估 战术要点 ：保险人对\"是否符合理赔条件\"有异议却不申请鉴定的，主张其承担 举证不能的不利后果 。 七、庭审攻防：保险人举证清单与我方质证点 保险人通常会提交这些证据，逐个质证： 保险人证据 质证点 投保单（有投保人签字） 签字是否本人？是否为 电子勾选 ？是否有证据证明签字前已阅读条款？有无销售误导？ 条款（加粗加黑版） 是否系 投保时 的版本？加粗是否覆盖争议条款？是否对专业术语作了解释？ 健康告知问卷 询问是否 具体、明确 ？是否为概括性询问？争议事项是否在询问范围内？ 回访录音 回访是否只问\"是否本人投保、是否了解条款\"这种形式化问题？有无逐条说明免责条款？ 体检报告 / 既往就诊记录 该异常与本次保险事故有无 因果关系 ？投保人是否\"明知\"？ 拒赔/解除通知 发出时间 是否在知道解除事由后 30 日内？合同是否成立满 2 年？ 网页投保流程公证 公证的是否为 投保时 的页面版本？是否证明投保人 实际停留阅读 ？ 八、执行阶段提醒 保险公司一般履行能力无虞，重点是 判决书生效后及时申请执行 并主张迟延履行利息。 涉及\"继续履行合同 + 保费豁免\"的，确认保险公司系统内是否实际恢复了保单效力。 九、常见翻车点清单（自查） [ ] 诉讼时效还剩多久？ [ ] 保单里有没有仲裁条款？ [ ] 保险人有没有 先解除 合同再拒赔？（没解除直接拒赔 = 违法，§解释二 8） [ ] 保险人解除权的 30 日 / 2 年期间有没有超？ [ ] 争议条款到底是免责条款还是责任范围条款？ [ ] 我有没有拿到 投保时的条款版本 ？ [ ] 有没有申请法院责令保险人提交后台电子数据？ [ ] 迟延损失有没有一并主张？ [ ] 有没有漏了\"继续履行合同 / 保费豁免\"的请求？"}, {"id": "L1-险种层/01-重疾险", "group": "2 · 险种深挖", "groupKey": "L1-险种层", "title": "重疾险 · 纠纷全解", "order": 2, "file": "01-重疾险.md", "html": "<h1 id=\"s0\">重疾险 · 纠纷全解</h1>\n<blockquote><strong>本页自包含</strong>——读这一页不需要翻其他文件。案例编号（如「案例库·M3」）指本站点「广东案例库」分组中的对应篇目，左侧导航可直接点。<br><br><strong>一句话定位</strong>：重疾险是\"<strong>确诊就给钱</strong>\"的定额给付型保险，不看实际花了多少。所以它的战场<strong>不在医疗费，而在\"你得的这个病，算不算条款里写的那个病\"</strong>。</blockquote>\n<hr>\n<h2 id=\"s1\">0. 速查卡片（本页最重要的 12 条）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>要点</th><th>依据</th></tr></thead><tbody>\n<tr><td>1</td><td>重疾定义只有三种赔付条件：<strong>确诊即赔 / 做了约定手术 / 达到约定状态</strong>。搞错类别 = 拒赔</td><td>规范 3.1</td></tr>\n<tr><td>2</td><td>2020 版规范：<strong>28 种重度疾病 + 3 种轻度疾病</strong></td><td>规范 2.1</td></tr>\n<tr><td>3</td><td>轻症赔付比例<strong>上限 30%</strong>（累计保额、多次赔付时单次保额，双重限制）</td><td>规范 2.2</td></tr>\n<tr><td>4</td><td><strong>甲状腺癌 TNM Ⅰ期</strong>不属于\"恶性肿瘤——重度\"，但<strong>属于\"恶性肿瘤——轻度\"</strong>（不是不赔）</td><td>规范 3.1.1.1(2) / 3.1.2.1(1)</td></tr>\n<tr><td>5</td><td><strong>原位癌</strong>不在\"恶性肿瘤——重度\"<strong>也不在</strong>\"恶性肿瘤——轻度\"范围内，需看产品是否单独保</td><td>规范 3.1.1.1(1)a</td></tr>\n<tr><td>6</td><td>🔥 <strong>规范 2.5：保险公司设定除外责任时，不承担保险责任的情形不能超出规范 3.2 的 9 项范围</strong></td><td>规范 2.5 + 3.2</td></tr>\n<tr><td>7</td><td>冠状动脉搭桥术：2020 版只要求\"<strong>切开心包</strong>\"，不再要求\"开胸\"</td><td>规范 3.1.1.5</td></tr>\n<tr><td>8</td><td>对疾病定义作出的、超出普通人预期的<strong>限定</strong>，属于<strong>隐性免责条款</strong>，未提示说明不生效</td><td>保险法 §17 + 解释二 §9</td></tr>\n<tr><td>9</td><td>定义有歧义的，先按<strong>通常理解</strong>解释，仍有两种以上解释的，作有利于被保险人的解释</td><td>保险法 §30</td></tr>\n<tr><td>10</td><td>保险人<strong>未先解除合同直接拒赔</strong>的，法院不予支持</td><td>解释二 §8</td></tr>\n<tr><td>11</td><td>解除权：知道解除事由起 <strong>30 日</strong>内行使；合同成立满 <strong>2 年</strong>不得解除</td><td>保险法 §16③</td></tr>\n<tr><td>12</td><td>就诊医院不符约定拒赔的，<strong>情况紧急立即就医</strong>的除外；诉讼时效 <strong>2 年</strong></td><td>解释三 §20 / 保险法 §26</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">1. 险种地图：重疾险到底保什么</h2>\n<pre><code>\n重疾险（定额给付型）\n\n├── 重度疾病保险金（主责任，100% 保额）\n\n│     2020 版规范：28 种必保/可选重度疾病\n\n├── 轻度疾病保险金（轻症，≤30% 保额）\n\n│     2020 版规范必保 3 种：轻度恶性肿瘤 / 较轻急性心梗 / 轻度脑中风后遗症\n\n├── 中症疾病保险金（非规范强制，各家自定，常见 50-60%）\n\n├── 身故/全残责任（有的产品捆绑，有的不绑）\n\n├── 保费豁免（确诊轻症/中症/重疾后，后续保费不用交，合同继续有效）\n\n└── 多次赔付（分组 / 不分组；受\"三同条款\"与间隔期限制）\n\n</code></pre>\n<p><strong>关键认知</strong>：重疾险<strong>不是</strong>医疗险。你住院花了 8 万还是 80 万，跟重疾险赔多少没关系；它只认\"是否触发了合同约定的那个疾病/手术/状态\"。</p>\n<p><strong>比喻</strong>：重疾险像消防喷淋头——不是看你家烧掉多少钱，而是看<strong>温度有没有到 68 度</strong>。温度一到，喷淋头炸开，固定洒这么多水。保险公司跟你吵的永远是\"温度到底到没到 68 度\"。</p>\n<hr>\n<h2 id=\"s3\">2. 争点逐解</h2>\n<h3 id=\"s4\">C1 · 疾病定义不符：确诊 / 手术 / 状态，三类赔付条件</h3>\n<p><strong>场景</strong>：确诊了癌症、做了心脏手术、中风了，保险公司说\"不满足条款定义\"。</p>\n<p><strong>这是重疾险第一大争点。</strong> 中国保险行业协会《重大疾病保险的疾病定义使用规范》把重疾赔付条件分成三类：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>类型</th><th>含义</th><th>2020 版规范中的典型条目（原文要点）</th></tr></thead><tbody>\n<tr><td><strong>确诊即赔</strong></td><td>经组织病理学等检查明确诊断即触发</td><td><strong>恶性肿瘤——重度</strong>（3.1.1.1）：病灶经<strong>组织病理学检查</strong>（涵盖骨髓病理学检查）结果明确诊断，临床诊断属于 <strong>ICD-10</strong> 恶性肿瘤类别，且 <strong>ICD-O-3</strong> 肿瘤形态学编码属于 <strong>3、6、9</strong>（恶性肿瘤）范畴</td></tr>\n<tr><td><strong>实施了特定手术</strong></td><td>必须实际做了约定的手术方式</td><td><strong>冠状动脉搭桥术</strong>（3.1.1.5）：已经实施了<strong>切开心包</strong>进行的冠状动脉血管旁路移植的手术（\"未切开心包的冠状动脉介入治疗不在保障范围内\"）；<strong>重大器官移植术</strong>（3.1.1.4）；<strong>心脏瓣膜手术</strong>（3.1.1.16）：已经实施了<strong>切开心脏</strong>进行的瓣膜置换或修复</td></tr>\n<tr><td><strong>达到特定状态后</strong></td><td>需持续一定时间、遗留一定后遗症</td><td><strong>严重脑中风后遗症</strong>（3.1.1.3）：确诊 <strong>180 天</strong>后仍遗留至少一种障碍（一肢以上肌力 2 级以下 / 语言能力完全丧失 / 自主生活能力完全丧失）；<strong>严重慢性肾衰竭</strong>（3.1.1.6）：CKD <strong>5 期</strong>且已进行至少 <strong>90 天规律透析</strong>；<strong>深度昏迷</strong>（3.1.1.12）：GCS <strong>5 分或以下</strong>且持续使用呼吸机及其他生命维持系统 <strong>96 小时以上</strong></td></tr>\n</tbody></table></div>\n<blockquote>规范 3.3.3 还规定：<strong>ICD-10 与 ICD-O-3 不一致的，以 ICD-O-3 为准</strong>。这一条在编码争议中是决定性的。</blockquote>\n<p><strong>保险人的拒赔点</strong>：你做的是微创 / 介入 / 腔镜手术，不是条款写的\"开胸\"。</p>\n<p><strong>拆解</strong></p>\n<ol>\n<li><strong>先定类别</strong>：拿到条款第一件事，找到目标疾病，看它属于哪一类。类别搞错了，索赔必然失败。</li>\n<li><strong>再看限定词</strong>：条款里\"须\"\"应当\"\"不包括\"\"仅限于\"这些词后面的内容，就是限定义务。</li>\n<li><strong>攻击路径一：隐性免责条款。</strong> 对疾病定义作出的、超出一个普通人对该疾病通常理解的限定（例如要求\"必须开胸\"而现代医学早已普遍采用微创），实质上<strong>减轻了保险人的保险责任</strong>，符合司法解释（二）第 9 条\"免除或者减轻保险人责任的条款\"的实质标准 → 保险人必须<strong>提示 + 明确说明</strong>，否则该限定不生效。</li>\n<li><strong>攻击路径二：不利解释（§30）。</strong> 条款对手术方式的表述存在两种以上理解的，作有利于被保险人的解释。</li>\n<li><strong>攻击路径三：格式条款无效（§19）。</strong> 该限定实质排除被保险人主要权利、加重其责任的，可主张无效。</li>\n<li><strong>攻击路径四：医学发展抗辩。</strong> 条款制定时的主流术式已被淘汰，仍以旧术式为赔付条件的，可主张该条款目的落空、显失公平（配合上述三条使用）。</li>\n</ol>\n<p><strong>证据</strong>：完整住院病案（含手术记录、麻醉记录、病理报告）、诊断证明书、手术方式说明（主治医师出具）、该术式在临床上属标准治疗的医学文献或诊疗指南。</p>\n<p><strong>比喻</strong>：你跟房东签约时说\"漏水就修\"，结果合同小字写着\"只有从天花板正中间漏的水才修\"。水从墙角漏下来，房东说不符合约定——这种\"小字限定\"如果签约时没跟你讲清楚，就不能拿来卡你。</p>\n<hr>\n<h3 id=\"s5\">C2 · 甲状腺癌降级赔付</h3>\n<p><strong>场景</strong>：确诊甲状腺癌，保险公司按\"轻度恶性肿瘤\"赔 30%，不是 100%。</p>\n<p><strong>规则（2020 版规范原文）</strong></p>\n<ul>\n<li><strong>3.1.1.1 恶性肿瘤——重度</strong>的排除清单第（2）项：<strong>\"TNM 分期为Ⅰ期或更轻分期的甲状腺癌\"</strong> 不属于重度。</li>\n<li><strong>3.1.2.1 恶性肿瘤——轻度</strong>第（1）项：<strong>\"TNM 分期为Ⅰ期的甲状腺癌\"</strong> 属于轻度。</li>\n<li><strong>2.2 条</strong>：轻度疾病累计保险金额<strong>不应高于</strong>相应重度疾病累计保险金额的 <strong>30%</strong>。</li>\n</ul>\n<p><strong>所以结论是：不是不赔，是降级赔（且降级上限由规范锁定在 30% 以内，保险公司只能更低不能更高）。</strong></p>\n<p><strong>关键判断点：看合同适用哪一版规范。</strong></p>\n<ul>\n<li>2020 版规范 2020-11-05 发布，<strong>过渡期至 2021-01-31</strong>；过渡期结束后不得继续销售基于旧规范（2007 版）的产品。</li>\n<li>因此 <strong>2021 年 1 月 31 日之后签发</strong>的重疾险适用 2020 版；<strong>之前的适用 2007 版</strong>。</li>\n<li><span class=\"warn\">!</span> <strong>适用 2007 版的老保单，甲状腺癌不分期，应按\"恶性肿瘤\"重度全额赔付。</strong> 这是老保单持有人的重要权利，实务中被大量误按 30% 赔付。</li>\n</ul>\n<p><strong>破解路径</strong></p>\n<ol>\n<li>查明<strong>保单签发日期</strong> + 条款明确引用的规范版本（合同里通常写明\"本合同疾病定义适用《重大疾病保险的疾病定义使用规范（2020年修订版）》\"）。</li>\n<li>老保单被按轻症赔付的 → 主张适用 2007 版，全额给付。</li>\n<li>新保单：核查病理报告的 <strong>TNM 分期</strong>——注意依规范 3.3.4，TNM 分期采用 <strong>AJCC 癌症分期手册标准</strong>；规范 3.3.5 专门列出了甲状腺癌的 TNM 分期（AJCC 第八版）。分期存疑或病理报告未作分期的，主张按通常理解仍有两种解释（§30）。</li>\n<li>无论新旧，均核查销售过程中是否有\"癌症都全额赔\"的口头/页面承诺（→ 销售误导证据）。</li>\n</ol>\n<p><strong>证据</strong>：保单签发日期、条款全文、<strong>病理报告（含 TNM 分期与 AJCC 版本）</strong>、销售页面快照。</p>\n<hr>\n<h3 id=\"s6\">C3 · 微创手术 vs 开胸开腹条款</h3>\n<p><strong>场景</strong>：冠状动脉搭桥做了微创（不停跳、小切口），保险公司以\"未开胸\"拒赔。</p>\n<p><strong>这是重疾险最经典的战场。</strong></p>\n<p><strong><span class=\"warn\">!</span> 先搞清楚你手上合同的规范版本</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>版本</th><th>冠状动脉搭桥术（3.1.1.5）</th><th>心脏瓣膜手术（3.1.1.16）</th></tr></thead><tbody>\n<tr><td><strong>2020 版</strong></td><td>\"指为治疗严重的冠心病，已经实施了<strong>切开心包</strong>进行的冠状动脉血管旁路移植的手术。所有未切开心包的冠状动脉介入治疗不在保障范围内。\"</td><td>\"指为治疗心脏瓣膜疾病，已经实施了<strong>切开心脏</strong>进行的心脏瓣膜置换或修复的手术。所有未切开心脏的心脏瓣膜介入手术不在保障范围内。\"</td></tr>\n<tr><td><strong>2007 版（老保单）</strong></td><td>要求\"<strong>开胸</strong>\"</td><td>要求\"<strong>开胸</strong>\"</td></tr>\n</tbody></table></div>\n<p><strong>所以</strong>：2020 版已经把\"开胸\"放宽为\"<strong>切开心包</strong>（搭桥）/\"<strong>切开心脏</strong>（瓣膜）\"。<strong>如果你拿的是 2020 版合同，保险公司还拿\"没开胸\"拒赔，直接引条文怼回去。</strong></p>\n<p><strong>老保单（2007 版）的破解路径</strong>    - 属<strong>隐性免责条款</strong>，未提示说明不生效（§17 + 解释二 §9）；    - 即便生效，按通常理解存在歧义 → §30 不利解释；    - 实质加重被保险人责任 → §19 无效。</p>\n<ol>\n<li><strong>医学事实补强</strong>：出具主治医师说明，证明该微创术式与开胸术式在<strong>治疗目的、风险程度、适应症</strong>上实质相当，或证明被保险人因身体条件<strong>不能耐受</strong>开胸。</li>\n<li><strong>实务提示</strong>：不少法院在此类案件中支持被保险人，理由正是\"投保人作为普通人不具备医学知识，无法理解'开胸'这一限定的法律后果，保险人未尽明确说明义务\"。</li>\n</ol>\n<p><strong>证据</strong>：手术记录（含切口方式、是否体外循环）、麻醉记录、主管医师书面说明、临床诊疗指南。</p>\n<hr>\n<h3 id=\"s7\">C4 · 等待期内出险</h3>\n<p><strong>规则</strong>：重疾险等待期通常 <strong>90 天或 180 天</strong>。等待期内<strong>确诊</strong>或<strong>出现相关症状体征</strong>的，多数条款约定不赔（通常退还保费、合同继续或终止，看条款）。</p>\n<p><strong>争点</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>争点</th><th>破解</th></tr></thead><tbody>\n<tr><td>等待期内只是<strong>体检异常</strong>，等待期后才确诊</td><td>区分\"出险\"与\"确诊\"。保险事故是\"确诊合同约定疾病\"，看条款如何定义\"初次发生\"——若条款定义为\"出现相关症状体征\"，可主张加重责任/不利解释</td></tr>\n<tr><td>等待期起算日争议</td><td>核对合同成立日 / 生效日 / 等待期条款，通常自<strong>合同生效日</strong>起算；续保的看是否有新等待期</td></tr>\n<tr><td>\"初次发生\"定义过宽</td><td>该定义实质免除责任的，按隐性免责攻击</td></tr>\n<tr><td>保险人在等待期内已知异常仍承保并收保费</td><td>参照解释二 §7 的精神（知情后收保费不得解除）</td></tr>\n</tbody></table></div>\n<p><strong>比喻</strong>：等待期像新入职的试用期。但公司不能把\"试用期里咳嗽了一声\"说成\"你入职前就有病\"。</p>\n<hr>\n<h3 id=\"s8\">C5 · 如实告知：结节、体检异常、他司投保</h3>\n<p><strong>规则（详见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a>）</strong>：告知义务<strong>以保险人询问为前提 + 限于询问范围 + 限于投保人明知 + 概括性询问无效</strong>。</p>\n<p><strong>重疾险最高频的三类告知争议</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>告知事项</th><th>争议点</th><th>破解</th></tr></thead><tbody>\n<tr><td><strong>甲状腺/乳腺/肺结节</strong></td><td>询问表是否具体问到\"结节\"？还是只问\"肿瘤\"\"肿块\"？</td><td>结节≠肿瘤。询问表未明确列\"结节\"的，主张未询问；即便问了，要看投保人是否<strong>明知</strong>该结节存在</td></tr>\n<tr><td><strong>体检指标异常</strong>（如肿瘤标志物升高）</td><td>投保人是否看到并理解该异常？</td><td>解释二 §5：<strong>明知</strong>才须告知。体检报告未取、未被医生告知异常的，不构成明知</td></tr>\n<tr><td><strong>在他司投保/理赔记录</strong></td><td>是否询问？询问表述是否具体？</td><td>广州天河法院曾审理一起网络投保重疾险案，保险人以未告知他司投保记录拒赔，未获支持（详见案例库·网络投保篇）。另须审查保险人是否在法定期限内行使解除权</td></tr>\n</tbody></table></div>\n<p><strong>关键动作</strong>：投保时<strong>逐条截图健康告知页</strong>，保存\"每一条询问的原文表述\"。日后保险公司说\"你没告知 XX\"，第一步就是回到这张截图——<strong>询问表上有没有问</strong>。</p>\n<p><strong>因果关系抗辩</strong>：部分地区裁判会考察未告知事项与所患疾病之间有无因果关系。虽非法定要件，但作为事实论证有说服力（尤其保险人是\"概括性询问\"的情形）。</p>\n<hr>\n<h3 id=\"s9\">C6 &amp; C7 · 两年不可抗辩与\"未先解除即拒赔\"</h3>\n<p><strong>规则</strong></p>\n<ul>\n<li>保险法 §16③：解除权自保险人知道解除事由之日起 <strong>30 日</strong>内不行使而消灭；<strong>自合同成立之日起超过 2 年</strong>的，保险人不得解除合同。</li>\n<li>解释二 §8：保险人<strong>未行使解除权、直接以未如实告知为由拒赔</strong>的，法院不予支持。</li>\n<li>解释二 §7：保险人知情后<strong>仍收取保费</strong>的，不得再依 §16②解除。</li>\n</ul>\n<p><strong>实战动作：画时间轴</strong></p>\n<pre><code>\n合同成立日 ──► 出险/确诊日 ──► 报案日 ──► 保险人知道解除事由日 ──► 解除通知发出日 ──► 起诉日\n\n                                                    │                          │\n\n                                              +30 日内须行使解除权        超出即消灭\n\n</code></pre>\n<p><strong>三个必须核的时间点</strong></p>\n<ol>\n<li>保险人<strong>何时知道</strong>解除事由（通常以理赔调查完成日/调取到病历日为准，而非其自称的时间）→ 距发出解除通知是否超过 30 日。</li>\n<li>合同成立是否<strong>满 2 年</strong> → 满 2 年不得解除。</li>\n<li>保险人<strong>解除通知与拒赔通知的先后</strong> → 先拒赔后解除的，直接引解释二 §8。</li>\n</ol>\n<p><strong><span class=\"warn\">!</span> 两年不可抗辩的边界</strong>：它限制的是<strong>解除权</strong>，不当然使保险人对合同成立前<strong>已经发生</strong>的保险事故承担责任；对故意骗保仍留有争议空间。不要把它当万能钥匙，作为<strong>并列理由</strong>之一提出，不要单挂。</p>\n<hr>\n<h3 id=\"s10\">C8 · 轻症 / 中症赔付比例与\"三同条款\"</h3>\n<p><strong>场景一：轻症只赔 20-30%</strong></p>\n<ul>\n<li>2020 版规范：三种必保轻度疾病的赔付比例<strong>上限为重度疾病保险金额的 30%</strong>。这是<strong>监管上限</strong>，不禁止低于 30%。所以\"只赔 20%\"不必然违规，投保前要看清。</li>\n<li>但若<strong>销售页面宣传\"轻症赔 30%\"而合同写 20%</strong> → 销售误导 + 解释二 §14（合同记载不一致的规则）。</li>\n</ul>\n<p><strong>场景二：多次赔付的\"三同条款\"（重点攻击对象）</strong></p>\n<blockquote>典型表述：若被保险人因<strong>同一疾病原因、同次医疗行为或同次意外伤害事故</strong>导致两项或两项以上重大疾病，仅按其中一项给付。</blockquote>\n<p><strong>拆解</strong></p>\n<ol>\n<li>该条款写在\"<strong>保险责任</strong>\"章节、标题像在说\"怎么赔\"，实质<strong>限制赔付次数</strong> → 典型的<strong>隐性免责条款</strong>。</li>\n<li>保险人未就该条款单独提示并明确说明的 → 不发生效力。</li>\n<li>即便说明过，\"同一疾病原因\"的外延模糊 → §30 不利解释（例如：肺癌 → 一年后骨转移，是否\"同一疾病原因\"？条款未界定时间间隔的，应作有利于被保险人的解释）。</li>\n</ol>\n<p><strong>比喻</strong>：买了\"三次赔付\"的套餐，付款时才发现写着\"同一顿饭只算一次\"——而\"一顿饭\"的定义由店家说了算。</p>\n<hr>\n<h3 id=\"s11\">C9 · 分组、间隔期与保费豁免</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>要点</th><th>说明</th></tr></thead><tbody>\n<tr><td><strong>分组多次赔付</strong></td><td>同组疾病只赔一次。癌症单独分组的产品更优。分组规则属限制责任条款 → 隐性免责攻击</td></tr>\n<tr><td><strong>间隔期</strong>（常见 180 天 / 1 年 / 3 年）</td><td>看清楚间隔期起算点与长度；间隔期条款同样可主张需提示说明</td></tr>\n<tr><td><strong>保费豁免</strong></td><td>确诊轻症/中症/重疾后免交后续保费。豁免条件与疾病定义挂钩，纠纷随主险一并处理。<strong>注意：豁免失效往往源于主险被解除</strong></td></tr>\n<tr><td><strong>多次赔付的\"首次\"认定</strong></td><td>首次赔付后合同是否继续、现金价值归零等，看条款</td></tr>\n</tbody></table></div>\n<hr>\n<h3 id=\"s12\">C10 · 遗传性疾病 / 先天性疾病免责</h3>\n<p><strong>规则</strong>：多数重疾险将\"遗传性疾病、先天性畸形/变形/染色体异常\"列为免责，但通常会<strong>附条件</strong>（如\"符合 ICD-10 编码范围\"\"须有明确家族遗传史诊断\"）。</p>\n<p><strong>破解</strong></p>\n<ol>\n<li>要求保险人举证该疾病<strong>确实属于</strong>条款界定的遗传/先天性疾病（谁主张谁举证）。</li>\n<li>条款对\"遗传性疾病\"的定义过于宽泛、无客观标准的 → §19 无效 + §30 不利解释。</li>\n<li>该免责条款本身是否<strong>提示并明确说明</strong>过（回到武器一）。</li>\n<li>该疾病是否也可能由后天因素导致（区分\"有遗传倾向\"与\"遗传性疾病\"）。</li>\n</ol>\n<hr>\n<h3 id=\"s13\">C11 · 就诊医院不符约定</h3>\n<p><strong>规则</strong>：多数重疾险要求\"<strong>国家二级及以上公立医院</strong>\"或\"二级甲等及以上\"出具的诊断。</p>\n<p><strong>关键</strong>：<strong>司法解释（三）第 20 条</strong>——</p>\n<blockquote>保险人以被保险人未在保险合同约定的医疗服务机构接受治疗为由拒绝给付保险金的，人民法院应予支持，<strong>但被保险人因情况紧急必须立即就医的除外</strong>。</blockquote>\n<p><strong>所以</strong>：紧急情况下就近就医（哪怕是民营/一级医院）的，保险人不能据此拒赔。事后转院的，注意保留急诊记录与时间链条。</p>\n<p>另：条款要求\"二级及以上<strong>公立</strong>医院\"而患者在医保定点的<strong>民营</strong>医院就诊的，可结合 §30 主张\"公立\"限定属加重责任、且未明确说明。</p>\n<hr>\n<h3 id=\"s14\">C12 · 病历主诉与\"既往症\"推定</h3>\n<p><strong>场景</strong>：急诊病历主诉写着\"反复头晕 3 年\"，保险公司据此主张投保前已患病、未如实告知。</p>\n<p><strong>这是实务中最隐蔽也最致命的坑。</strong> 医生写主诉时往往直接采信患者或家属的随口描述，未经核实。</p>\n<p><strong>防范</strong></p>\n<ol>\n<li>就诊时<strong>准确陈述</strong>症状起始时间，不要为求重视而夸大病程。</li>\n<li>发现病历主诉与事实不符的，<strong>及时申请医院更正</strong>（病程记录更正有规范程序，越早越好）。</li>\n<li>事后补救：用投保前的体检报告、既往就诊记录、单位体检结论<strong>反证</strong>此前无该病史；申请主治医生出具说明。</li>\n</ol>\n<p><strong>比喻</strong>：病历主诉是保险公司最爱的\"免费证人\"，而且这个证人还不用出庭。你在急诊室随口说的一句话，三年后会变成拒赔通知书上的第三行。</p>\n<hr>\n<h3 id=\"s15\">C13 · 病理报告与 ICD 编码（容易被保险人反用的一节）</h3>\n<p><strong>规则（2020 版规范原文）</strong></p>\n<ul>\n<li><strong>3.1.1.1</strong>：恶性肿瘤——重度要求\"病灶经<strong>组织病理学检查</strong>（涵盖骨髓病理学检查）结果明确诊断\"，临床诊断属 ICD-10 恶性肿瘤类别，且 ICD-O-3 编码属 <strong>3、6、9</strong>。</li>\n<li><strong>3.3.2（术语释义）</strong>：</li>\n<p>&gt; 组织病理学检查是通过<strong>局部切除、钳取、穿刺</strong>等手术方法，从患者机体采取<strong>病变组织块</strong>，经过包埋、切片后，进行病理检查的方法。   &gt; 通过采集病变部位脱落细胞、细针吸取病变部位细胞、体腔积液分离病变细胞等方式获取病变细胞，制成涂片，进行病理检查的方法，属于<strong>细胞病理学检查</strong>，<strong>不属于组织病理学检查</strong>。</p>\n<li><strong>3.3.3</strong>：ICD-10 与 ICD-O-3 不一致的，<strong>以 ICD-O-3 为准</strong>；形态学编码 0=良性、1=动态未定性、2=原位癌和非侵袭性癌、3=恶性（原发性）、6=恶性（转移性）、9=恶性（原发或转移未肯定）。</li>\n</ul>\n<p><strong><span class=\"warn\">!</span> 双向武器——这一条保险人也会用</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>方向</th><th>情形</th><th>打法</th></tr></thead><tbody>\n<tr><td><strong>保险人用（对你不利）</strong></td><td>只有胸水/腹水细胞学、支气管镜刷检、EUS-FNA 细胞学涂片，<strong>未取得组织块</strong></td><td>保险人主张不符合\"组织病理学检查\"</td></tr>\n<tr><td><strong>你用（对保险人不利）</strong></td><td>病灶位置<strong>客观上无法</strong>取得组织块（如胰腺、纵隔、脑干），临床上只能细胞学诊断</td><td>① 主张条款未界定\"无法取得组织时如何处理\"，存在两种以上解释 → §30；② 主张该要求属<strong>隐性免责</strong>，未提示说明不生效；③ 要求保险人举证\"必须取得组织块\"已向投保人明确说明</td></tr>\n<tr><td><strong>你用</strong></td><td>骨髓/血液系统疾病（白血病、淋巴瘤）</td><td>规范明确<strong>涵盖骨髓病理学检查</strong>；以骨髓细胞学/流式/活检综合诊断的，主张符合定义</td></tr>\n<tr><td><strong>你用</strong></td><td>编码争议（交界性肿瘤、动态未定肿瘤）</td><td>规范已明确 1=动态未定性、2=原位癌<strong>不在</strong>重度范围；但<strong>老保单（2007 版）未采 ICD-O-3</strong>，可主张应作有利解释</td></tr>\n</tbody></table></div>\n<p><strong>防范建议</strong>：确诊后<strong>主动向医生说明保险理赔需要\"组织病理学\"报告</strong>，在病情允许、风险可控的前提下争取取得组织块（活检/术后病理）。这一句话可能值几十万。</p>\n<hr>\n<h3 id=\"s16\">C14 · 理赔核定与迟延</h3>\n<ul>\n<li>情形复杂的应在 <strong>30 日内</strong>作出核定（§23①）；核定期间自<strong>初次收到索赔请求及有关证明资料之日</strong>起算（解释二 §15）。</li>\n<li>属于保险责任的，达成协议后 <strong>10 日内</strong>给付。</li>\n<li>自收到请求及资料起 <strong>60 日</strong>内对数额不能确定的，应<strong>先支付可以确定数额的最低部分</strong>（§25）。</li>\n<li>未及时履行的，<strong>应赔偿因此受到的损失</strong>（§23③）——可一并主张利息。</li>\n</ul>\n<p><strong>实战</strong>：保险人在 30 日内既不核定也不通知的，书面催告并固定时间节点，把\"拖延\"本身变成一项独立诉请。</p>\n<hr>\n<h3 id=\"s17\">C15 · 🔥 免责范围本身有\"天花板\"（规范 2.5 —— 最容易被忽略的武器）</h3>\n<p><strong>规范 2.5 原文</strong>：</p>\n<blockquote>保险公司设定重大疾病保险除外责任时，对于被保险人发生的疾病、达到的疾病状态或进行的手术，<strong>保险公司不承担保险责任的情形不能超出本规范 3.2 规定的范围</strong>。</blockquote>\n<p><strong>规范 3.2 列举的除外责任只有 9 项</strong>：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>情形</th></tr></thead><tbody>\n<tr><td>3.2.1</td><td>投保人对被保险人的<strong>故意杀害、故意伤害</strong></td></tr>\n<tr><td>3.2.2</td><td>被保险人<strong>故意犯罪</strong>或抗拒依法采取的刑事强制措施</td></tr>\n<tr><td>3.2.3</td><td>被保险人<strong>故意自伤</strong>，或自本合同成立/效力恢复之日起 <strong>2 年内自杀</strong>（自杀时为无民事行为能力人的除外）</td></tr>\n<tr><td>3.2.4</td><td>被保险人服用、吸食或注射<strong>毒品</strong></td></tr>\n<tr><td>3.2.5</td><td>被保险人<strong>酒后驾驶、无合法有效驾驶证驾驶</strong>，或驾驶无合法有效行驶证的机动车</td></tr>\n<tr><td>3.2.6</td><td>被保险人<strong>感染艾滋病病毒或患艾滋病</strong></td></tr>\n<tr><td>3.2.7</td><td><strong>战争、军事冲突、暴乱或武装叛乱</strong></td></tr>\n<tr><td>3.2.8</td><td><strong>核爆炸、核辐射或核污染</strong></td></tr>\n<tr><td>3.2.9</td><td><strong>遗传性疾病，先天性畸形、变形或染色体异常</strong></td></tr>\n</tbody></table></div>\n<p><strong>这意味着什么</strong></p>\n<ol>\n<li><strong>超出这 9 项的\"疾病类免责\"，是超出行业规范的。</strong> 例如条款把\"被保险人患有 XX 疾病\"\"未在特定医院就诊\"\"未采用特定治疗方式\"直接写成重疾险的<strong>除外责任</strong>，就超出了 3.2 的封闭范围。</li>\n<li><strong>打法</strong>：先主张该条款<strong>违反行业规范</strong>（规范虽非法律，但属监管认可的行业标准，且 2.5 是强制性表述\"不能超出\"）；<strong>同时</strong>主张该条款属\"免除或减轻保险人责任的条款\"，未提示说明不生效（§17 + 解释二 §9）。两条并用，不要单挂。</li>\n<li><strong>注意区分</strong>：3.2 限定的是<strong>除外责任（免责条款）</strong>；\"疾病定义\"本身（3.1）是<strong>责任范围</strong>，不受 9 项限制。保险人最常见的防守就是把\"定义限定\"说成\"不是免责条款\"——这正是<strong>隐性免责规则</strong>要解决的（见 C1）。两张牌要一起打：</li>\n<p>- 若它主张\"这是定义/责任范围\" → 打<strong>隐性免责</strong>（未提示说明不生效）；    - 若它承认\"这是免责条款\" → 打<strong>规范 2.5</strong>（超出 3.2 九项范围）。    <strong>它总得选一边，而两边都有坑。</strong></p>\n</ol>\n<p><strong>比喻</strong>：保险公司开餐厅，行业协会规定\"不许卖的菜只有 9 样\"。结果它的菜单上写着 30 样\"本店不供应\"。你只要问一句：\"这 9 样之外的，凭什么？\"</p>\n<hr>\n<h3 id=\"s18\">C16 · \"不在保障范围内\"的排除列举，也是免责条款 🔥</h3>\n<p><strong>规则</strong>：写在\"释义/定义\"章节里的排除列举（如\"下列疾病不属于恶性肿瘤——重度：ICD-O-3 编码 0/1/2，如交界性肿瘤……\"），只要<strong>实质限缩了理赔范围、减轻了保险人责任</strong>，就是免责条款，未提示说明<strong>不生效</strong>。</p>\n<blockquote>\"<strong>但该约定实质限缩了恶性肿瘤的理赔范围、减轻了保险人的保险赔付责任，依法属于免除保险人责任的条款</strong>……未依法向投保人明确说明该免责条款内容，该免责条款依法不产生效力。\"<br>——湛江中院 (2026)粤08民终2416号（卵巢交界性肿瘤，判赔 49.9 万 + LPR 利息）</blockquote>\n<p><strong>保险人标准抗辩</strong>：\"这是<strong>责任范围条款</strong>，不是免责条款，所以我不用提示说明。\" <strong>破解</strong>：直接引本案原文。判断标准是<strong>实质效果</strong>（是否限缩责任），不是条款放在哪一章。</p>\n<h3 id=\"s19\">C17 · ICD 编码不能否定病理报告记载的事实</h3>\n<blockquote>\"<strong>尽管原位癌的形态学编码为2，但该编码系基于主要病理特征的整体归类，不能否定病理诊断中已明确记载的浸润性病变事实。</strong>保险合同条款未明确将'局灶间质微浸润'排除在'恶性肿瘤——重度'定义之外……依法亦应当作出有利于被保险人的解释。\"<br>——深圳中院 (2026)粤03民终9578号（乳腺导管原位癌伴局灶间质微浸润）</blockquote>\n<p><strong>用法</strong>：病理报告里有\"<strong>浸润</strong>\"\"侵犯\"\"突破基底膜\"字样的，主张满足条款的实质特征（\"浸润和破坏周围正常组织\"），编码只是归类工具 → §30 兜底。</p>\n<h3 id=\"s20\">C18 · 疾病定义限缩常人理解 = 隐性免责</h3>\n<blockquote>\"上述糖尿病定义应满足的多种并发症情形<strong>已超出一般人对'严重Ⅰ型糖尿病'的理解，极大缩小了一般医学标准</strong>……<strong>不论是在释义部分还是免责条款中</strong>，其目的在于充分保护投保人的知情权和选择权\"<br>——梅州中院 (2025)粤14民终795号</blockquote>\n<p>配套取证：<strong>同一页上其他条款加粗、争议条款没加粗 → 对比即证据</strong>。 另：保险人\"<strong>仅指引投保人注意其他条款</strong>\"的指引条款不能替代说明；<strong>电话回访不能替代投保时的说明</strong>。</p>\n<h3 id=\"s21\">C19 · 先天性疾病免责：加黑加粗也不够</h3>\n<blockquote>\"上述条款<strong>虽然采用加黑、加粗方式提醒投保人注意</strong>，但……仅明确符合 ICD-10 确定的分类和定义，<strong>未能举证说明其对于先天性畸形的概念、内容作出具体解释，且为一般人能够知晓和理解</strong>\"<br>——广州中院 (2024)粤01民终28133号（少儿重疾）</blockquote>\n<p>同案另两条：<strong>少儿特定重疾保险金与陪护保险金可同时主张</strong>（保险人\"发生重大疾病后不再付\"的主张因缺乏合同依据被驳）；<strong>\"同一次住院\"按 30 日间隔认定</strong>，算医疗费时先自己算一遍。</p>\n<h2 id=\"s22\">3. 投保前 checklist（照着逐项打勾）</h2>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 目标疾病（尤其是最高发的恶性肿瘤、急性心梗、脑中风）的<strong>定义条款逐字读过</strong></div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 确认条款引用的是 <strong>2007 版还是 2020 版</strong>规范</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 甲状腺癌、原位癌、交界性肿瘤的赔付方式（重度还是轻度？比例多少？）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 冠状动脉搭桥、主动脉手术是否仍要求\"<strong>开胸</strong>\"</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 脑中风后遗症的观察期（180 天？）与后遗症标准</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 轻症/中症的<strong>赔付比例</strong>与是否有\"三同\"限制</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 多次赔付的<strong>分组规则、间隔期</strong></div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 疾病种类数量（<strong>80 种 vs 120 种意义有限</strong>，高发的前 28 种由规范统一定义，差异在尾部）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 等待期长度与\"初次发生\"的定义</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 就诊医院要求（二级及以上？公立？）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否含身故责任（含身故的重疾险保费明显更高，单独买定寿通常更划算）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保费豁免的触发条件</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>健康告知页逐条截屏</strong>（每一条的原文表述）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 销售宣传页面<strong>整页快照</strong>（日后证明销售误导的唯一依据）</div>\n<hr>\n<h2 id=\"s23\">4. 出险后 72 小时动作清单</h2>\n<ol>\n<li><strong>立即报案</strong>（多数条款要求\"及时通知\"，通常约定 10 日内；延迟通知的后果限于\"致使事故难以确定的部分\"——§21）。</li>\n<li><strong>病历主诉核对</strong>：确认医生记录的症状起始时间、既往史准确。发现错误当场提出更正。</li>\n<li><strong>证据固定清单</strong>：门/急诊病历、住院病案全套（含入院记录、手术记录、麻醉记录、病理报告、出院小结、检验报告）、诊断证明书（加盖医院公章）、费用清单与发票、影像资料与报告。</li>\n<li><strong>核对条款</strong>：确认目标疾病的赔付条件类别，看自己是否满足；不满足的，立刻评估\"隐性免责 + 不利解释\"路径。</li>\n<li><strong>书面提交理赔申请</strong>（保留收件凭证），索取<strong>书面</strong>核定结果——<strong>拒绝口头拒赔</strong>。</li>\n<li><strong>所有沟通留痕</strong>：与理赔员的电话录音（中国法律下单方录音一般可作为证据）、微信/短信文字确认。</li>\n<li><strong>不要急着签和解协议</strong>：签字前算清全部损失（保险金 + 迟延损失 + 后续治疗 + 保费豁免价值）。</li>\n</ol>\n<hr>\n<h2 id=\"s24\">5. 五个常见误解</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody>\n<tr><td>\"病种越多越好\"</td><td>前 28 种由行业规范统一定义，各家公司一样。<strong>差异在轻症比例、分组、定义细节</strong>，不在数量</td></tr>\n<tr><td>\"确诊癌症就赔\"</td><td>要看是否满足\"恶性肿瘤——重度\"定义（含分期、除外项）</td></tr>\n<tr><td>\"熬过两年就一定赔\"</td><td>两年不可抗辩限制的是<strong>解除权</strong>，不是万能钥匙；且保险人仍可在 30 日内行使解除权</td></tr>\n<tr><td>\"没住过院就是健康体\"</td><td>体检异常、门诊诊断、影像报告同样可能构成应告知事项（取决于询问是否具体）</td></tr>\n<tr><td>\"有医保就不用买重疾险\"</td><td>医保报销医疗费用（补偿型）；重疾险给付的是<strong>收入损失与康复费用</strong>（定额型），两者不重叠</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s25\">6. 与其他页面的关系</h2>\n<ul>\n<li><strong>规范原文全文（A 级 · 中国保险行业协会官方 PDF）</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F01-%E9%87%8D%E7%96%BE%E5%AE%9A%E4%B9%89%E4%BD%BF%E7%94%A8%E8%A7%84%E8%8C%832020\">《重大疾病保险的疾病定义使用规范（2020 年修订版）· 原文》</a>（含 28 种重度 + 3 种轻度的<strong>逐条定义</strong>、除外责任 9 项、术语释义、甲状腺癌 TNM 分期表）</li>\n<li><strong>武器层面的完整论证</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a></li>\n<li><strong>完整维权流程、时效表、文书模板</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>广东真实案例</strong>：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E9%87%8D%E7%96%BE%E5%8C%BB%E7%96%97\">《重疾险 / 医疗险 · 案例库》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "0. 速查卡片（本页最重要的 12 条）"}, {"id": "s2", "lv": 2, "t": "1. 险种地图：重疾险到底保什么"}, {"id": "s3", "lv": 2, "t": "2. 争点逐解"}, {"id": "s4", "lv": 3, "t": "C1 · 疾病定义不符：确诊 / 手术 / 状态，三类赔付条件"}, {"id": "s5", "lv": 3, "t": "C2 · 甲状腺癌降级赔付"}, {"id": "s6", "lv": 3, "t": "C3 · 微创手术 vs 开胸开腹条款"}, {"id": "s7", "lv": 3, "t": "C4 · 等待期内出险"}, {"id": "s8", "lv": 3, "t": "C5 · 如实告知：结节、体检异常、他司投保"}, {"id": "s9", "lv": 3, "t": "C6 &amp; C7 · 两年不可抗辩与\"未先解除即拒赔\""}, {"id": "s10", "lv": 3, "t": "C8 · 轻症 / 中症赔付比例与\"三同条款\""}, {"id": "s11", "lv": 3, "t": "C9 · 分组、间隔期与保费豁免"}, {"id": "s12", "lv": 3, "t": "C10 · 遗传性疾病 / 先天性疾病免责"}, {"id": "s13", "lv": 3, "t": "C11 · 就诊医院不符约定"}, {"id": "s14", "lv": 3, "t": "C12 · 病历主诉与\"既往症\"推定"}, {"id": "s15", "lv": 3, "t": "C13 · 病理报告与 ICD 编码（容易被保险人反用的一节）"}, {"id": "s16", "lv": 3, "t": "C14 · 理赔核定与迟延"}, {"id": "s17", "lv": 3, "t": "C15 · 🔥 免责范围本身有\"天花板\"（规范 2.5 —— 最容易被忽略的武器）"}, {"id": "s18", "lv": 3, "t": "C16 · \"不在保障范围内\"的排除列举，也是免责条款 🔥"}, {"id": "s19", "lv": 3, "t": "C17 · ICD 编码不能否定病理报告记载的事实"}, {"id": "s20", "lv": 3, "t": "C18 · 疾病定义限缩常人理解 = 隐性免责"}, {"id": "s21", "lv": 3, "t": "C19 · 先天性疾病免责：加黑加粗也不够"}, {"id": "s22", "lv": 2, "t": "3. 投保前 checklist（照着逐项打勾）"}, {"id": "s23", "lv": 2, "t": "4. 出险后 72 小时动作清单"}, {"id": "s24", "lv": 2, "t": "5. 五个常见误解"}, {"id": "s25", "lv": 2, "t": "6. 与其他页面的关系"}], "text": "重疾险 · 纠纷全解 本页自包含 ——读这一页不需要翻其他文件。案例编号（如「案例库·M3」）指本站点「广东案例库」分组中的对应篇目，左侧导航可直接点。 一句话定位 ：重疾险是\" 确诊就给钱 \"的定额给付型保险，不看实际花了多少。所以它的战场 不在医疗费，而在\"你得的这个病，算不算条款里写的那个病\" 。 0. 速查卡片（本页最重要的 12 条） 要点 依据 1 重疾定义只有三种赔付条件： 确诊即赔 / 做了约定手术 / 达到约定状态 。搞错类别 = 拒赔 规范 3.1 2 2020 版规范： 28 种重度疾病 + 3 种轻度疾病 规范 2.1 3 轻症赔付比例 上限 30% （累计保额、多次赔付时单次保额，双重限制） 规范 2.2 4 甲状腺癌 TNM Ⅰ期 不属于\"恶性肿瘤——重度\"，但 属于\"恶性肿瘤——轻度\" （不是不赔） 规范 3.1.1.1(2) / 3.1.2.1(1) 5 原位癌 不在\"恶性肿瘤——重度\" 也不在 \"恶性肿瘤——轻度\"范围内，需看产品是否单独保 规范 3.1.1.1(1)a 6 🔥 规范 2.5：保险公司设定除外责任时，不承担保险责任的情形不能超出规范 3.2 的 9 项范围 规范 2.5 + 3.2 7 冠状动脉搭桥术：2020 版只要求\" 切开心包 \"，不再要求\"开胸\" 规范 3.1.1.5 8 对疾病定义作出的、超出普通人预期的 限定 ，属于 隐性免责条款 ，未提示说明不生效 保险法 §17 + 解释二 §9 9 定义有歧义的，先按 通常理解 解释，仍有两种以上解释的，作有利于被保险人的解释 保险法 §30 10 保险人 未先解除合同直接拒赔 的，法院不予支持 解释二 §8 11 解除权：知道解除事由起 30 日 内行使；合同成立满 2 年 不得解除 保险法 §16③ 12 就诊医院不符约定拒赔的， 情况紧急立即就医 的除外；诉讼时效 2 年 解释三 §20 / 保险法 §26 1. 险种地图：重疾险到底保什么 关键认知 ：重疾险 不是 医疗险。你住院花了 8 万还是 80 万，跟重疾险赔多少没关系；它只认\"是否触发了合同约定的那个疾病/手术/状态\"。 比喻 ：重疾险像消防喷淋头——不是看你家烧掉多少钱，而是看 温度有没有到 68 度 。温度一到，喷淋头炸开，固定洒这么多水。保险公司跟你吵的永远是\"温度到底到没到 68 度\"。 2. 争点逐解 C1 · 疾病定义不符：确诊 / 手术 / 状态，三类赔付条件 场景 ：确诊了癌症、做了心脏手术、中风了，保险公司说\"不满足条款定义\"。 这是重疾险第一大争点。 中国保险行业协会《重大疾病保险的疾病定义使用规范》把重疾赔付条件分成三类： 类型 含义 2020 版规范中的典型条目（原文要点） 确诊即赔 经组织病理学等检查明确诊断即触发 恶性肿瘤——重度 （3.1.1.1）：病灶经 组织病理学检查 （涵盖骨髓病理学检查）结果明确诊断，临床诊断属于 ICD 10 恶性肿瘤类别，且 ICD O 3 肿瘤形态学编码属于 3、6、9 （恶性肿瘤）范畴 实施了特定手术 必须实际做了约定的手术方式 冠状动脉搭桥术 （3.1.1.5）：已经实施了 切开心包 进行的冠状动脉血管旁路移植的手术（\"未切开心包的冠状动脉介入治疗不在保障范围内\"）； 重大器官移植术 （3.1.1.4）； 心脏瓣膜手术 （3.1.1.16）：已经实施了 切开心脏 进行的瓣膜置换或修复 达到特定状态后 需持续一定时间、遗留一定后遗症 严重脑中风后遗症 （3.1.1.3）：确诊 180 天 后仍遗留至少一种障碍（一肢以上肌力 2 级以下 / 语言能力完全丧失 / 自主生活能力完全丧失）； 严重慢性肾衰竭 （3.1.1.6）：CKD 5 期 且已进行至少 90 天规律透析 ； 深度昏迷 （3.1.1.12）：GCS 5 分或以下 且持续使用呼吸机及其他生命维持系统 96 小时以上 规范 3.3.3 还规定： ICD 10 与 ICD O 3 不一致的，以 ICD O 3 为准 。这一条在编码争议中是决定性的。 保险人的拒赔点 ：你做的是微创 / 介入 / 腔镜手术，不是条款写的\"开胸\"。 拆解 1. 先定类别 ：拿到条款第一件事，找到目标疾病，看它属于哪一类。类别搞错了，索赔必然失败。 2. 再看限定词 ：条款里\"须\"\"应当\"\"不包括\"\"仅限于\"这些词后面的内容，就是限定义务。 3. 攻击路径一：隐性免责条款。 对疾病定义作出的、超出一个普通人对该疾病通常理解的限定（例如要求\"必须开胸\"而现代医学早已普遍采用微创），实质上 减轻了保险人的保险责任 ，符合司法解释（二）第 9 条\"免除或者减轻保险人责任的条款\"的实质标准 → 保险人必须 提示 + 明确说明 ，否则该限定不生效。 4. 攻击路径二：不利解释（§30）。 条款对手术方式的表述存在两种以上理解的，作有利于被保险人的解释。 5. 攻击路径三：格式条款无效（§19）。 该限定实质排除被保险人主要权利、加重其责任的，可主张无效。 6. 攻击路径四：医学发展抗辩。 条款制定时的主流术式已被淘汰，仍以旧术式为赔付条件的，可主张该条款目的落空、显失公平（配合上述三条使用）。 证据 ：完整住院病案（含手术记录、麻醉记录、病理报告）、诊断证明书、手术方式说明（主治医师出具）、该术式在临床上属标准治疗的医学文献或诊疗指南。 比喻 ：你跟房东签约时说\"漏水就修\"，结果合同小字写着\"只有从天花板正中间漏的水才修\"。水从墙角漏下来，房东说不符合约定——这种\"小字限定\"如果签约时没跟你讲清楚，就不能拿来卡你。 C2 · 甲状腺癌降级赔付 场景 ：确诊甲状腺癌，保险公司按\"轻度恶性肿瘤\"赔 30%，不是 100%。 规则（2020 版规范原文） 3.1.1.1 恶性肿瘤——重度 的排除清单第（2）项： \"TNM 分期为Ⅰ期或更轻分期的甲状腺癌\" 不属于重度。 3.1.2.1 恶性肿瘤——轻度 第（1）项： \"TNM 分期为Ⅰ期的甲状腺癌\" 属于轻度。 2.2 条 ：轻度疾病累计保险金额 不应高于 相应重度疾病累计保险金额的 30% 。 所以结论是：不是不赔，是降级赔（且降级上限由规范锁定在 30% 以内，保险公司只能更低不能更高）。 关键判断点：看合同适用哪一版规范。 2020 版规范 2020 11 05 发布， 过渡期至 2021 01 31 ；过渡期结束后不得继续销售基于旧规范（2007 版）的产品。 因此 2021 年 1 月 31 日之后签发 的重疾险适用 2020 版； 之前的适用 2007 版 。 ⚠️ 适用 2007 版的老保单，甲状腺癌不分期，应按\"恶性肿瘤\"重度全额赔付。 这是老保单持有人的重要权利，实务中被大量误按 30% 赔付。 破解路径 1. 查明 保单签发日期 + 条款明确引用的规范版本（合同里通常写明\"本合同疾病定义适用《重大疾病保险的疾病定义使用规范（2020年修订版）》\"）。 2. 老保单被按轻症赔付的 → 主张适用 2007 版，全额给付。 3. 新保单：核查病理报告的 TNM 分期 ——注意依规范 3.3.4，TNM 分期采用 AJCC 癌症分期手册标准 ；规范 3.3.5 专门列出了甲状腺癌的 TNM 分期（AJCC 第八版）。分期存疑或病理报告未作分期的，主张按通常理解仍有两种解释（§30）。 4. 无论新旧，均核查销售过程中是否有\"癌症都全额赔\"的口头/页面承诺（→ 销售误导证据）。 证据 ：保单签发日期、条款全文、 病理报告（含 TNM 分期与 AJCC 版本） 、销售页面快照。 C3 · 微创手术 vs 开胸开腹条款 场景 ：冠状动脉搭桥做了微创（不停跳、小切口），保险公司以\"未开胸\"拒赔。 这是重疾险最经典的战场。 ⚠️ 先搞清楚你手上合同的规范版本 版本 冠状动脉搭桥术（3.1.1.5） 心脏瓣膜手术（3.1.1.16） 2020 版 \"指为治疗严重的冠心病，已经实施了 切开心包 进行的冠状动脉血管旁路移植的手术。所有未切开心包的冠状动脉介入治疗不在保障范围内。\" \"指为治疗心脏瓣膜疾病，已经实施了 切开心脏 进行的心脏瓣膜置换或修复的手术。所有未切开心脏的心脏瓣膜介入手术不在保障范围内。\" 2007 版（老保单） 要求\" 开胸 \" 要求\" 开胸 \" 所以 ：2020 版已经把\"开胸\"放宽为\" 切开心包 （搭桥）/\" 切开心脏 （瓣膜）\"。 如果你拿的是 2020 版合同，保险公司还拿\"没开胸\"拒赔，直接引条文怼回去。 老保单（2007 版）的破解路径 属 隐性免责条款 ，未提示说明不生效（§17 + 解释二 §9）； 即便生效，按通常理解存在歧义 → §30 不利解释； 实质加重被保险人责任 → §19 无效。 3. 医学事实补强 ：出具主治医师说明，证明该微创术式与开胸术式在 治疗目的、风险程度、适应症 上实质相当，或证明被保险人因身体条件 不能耐受 开胸。 4. 实务提示 ：不少法院在此类案件中支持被保险人，理由正是\"投保人作为普通人不具备医学知识，无法理解'开胸'这一限定的法律后果，保险人未尽明确说明义务\"。 证据 ：手术记录（含切口方式、是否体外循环）、麻醉记录、主管医师书面说明、临床诊疗指南。 C4 · 等待期内出险 规则 ：重疾险等待期通常 90 天或 180 天 。等待期内 确诊 或 出现相关症状体征 的，多数条款约定不赔（通常退还保费、合同继续或终止，看条款）。 争点 争点 破解 等待期内只是 体检异常 ，等待期后才确诊 区分\"出险\"与\"确诊\"。保险事故是\"确诊合同约定疾病\"，看条款如何定义\"初次发生\"——若条款定义为\"出现相关症状体征\"，可主张加重责任/不利解释 等待期起算日争议 核对合同成立日 / 生效日 / 等待期条款，通常自 合同生效日 起算；续保的看是否有新等待期 \"初次发生\"定义过宽 该定义实质免除责任的，按隐性免责攻击 保险人在等待期内已知异常仍承保并收保费 参照解释二 §7 的精神（知情后收保费不得解除） 比喻 ：等待期像新入职的试用期。但公司不能把\"试用期里咳嗽了一声\"说成\"你入职前就有病\"。 C5 · 如实告知：结节、体检异常、他司投保 规则（详见L0 打法层/01 八把通用武器） ：告知义务 以保险人询问为前提 + 限于询问范围 + 限于投保人明知 + 概括性询问无效 。 重疾险最高频的三类告知争议 告知事项 争议点 破解 甲状腺/乳腺/肺结节 询问表是否具体问到\"结节\"？还是只问\"肿瘤\"\"肿块\"？ 结节≠肿瘤。询问表未明确列\"结节\"的，主张未询问；即便问了，要看投保人是否 明知 该结节存在 体检指标异常 （如肿瘤标志物升高） 投保人是否看到并理解该异常？ 解释二 §5： 明知 才须告知。体检报告未取、未被医生告知异常的，不构成明知 在他司投保/理赔记录 是否询问？询问表述是否具体？ 广州天河法院曾审理一起网络投保重疾险案，保险人以未告知他司投保记录拒赔，未获支持（详见案例库·网络投保篇）。另须审查保险人是否在法定期限内行使解除权 关键动作 ：投保时 逐条截图健康告知页 ，保存\"每一条询问的原文表述\"。日后保险公司说\"你没告知 XX\"，第一步就是回到这张截图—— 询问表上有没有问 。 因果关系抗辩 ：部分地区裁判会考察未告知事项与所患疾病之间有无因果关系。虽非法定要件，但作为事实论证有说服力（尤其保险人是\"概括性询问\"的情形）。 C6 & C7 · 两年不可抗辩与\"未先解除即拒赔\" 规则 保险法 §16③：解除权自保险人知道解除事由之日起 30 日 内不行使而消灭； 自合同成立之日起超过 2 年 的，保险人不得解除合同。 解释二 §8：保险人 未行使解除权、直接以未如实告知为由拒赔 的，法院不予支持。 解释二 §7：保险人知情后 仍收取保费 的，不得再依 §16②解除。 实战动作：画时间轴 三个必须核的时间点 1. 保险人 何时知道 解除事由（通常以理赔调查完成日/调取到病历日为准，而非其自称的时间）→ 距发出解除通知是否超过 30 日。 2. 合同成立是否 满 2 年 → 满 2 年不得解除。 3. 保险人 解除通知与拒赔通知的先后 → 先拒赔后解除的，直接引解释二 §8。 ⚠️ 两年不可抗辩的边界 ：它限制的是 解除权 ，不当然使保险人对合同成立前 已经发生 的保险事故承担责任；对故意骗保仍留有争议空间。不要把它当万能钥匙，作为 并列理由 之一提出，不要单挂。 C8 · 轻症 / 中症赔付比例与\"三同条款\" 场景一：轻症只赔 20 30% 2020 版规范：三种必保轻度疾病的赔付比例 上限为重度疾病保险金额的 30% 。这是 监管上限 ，不禁止低于 30%。所以\"只赔 20%\"不必然违规，投保前要看清。 但若 销售页面宣传\"轻症赔 30%\"而合同写 20% → 销售误导 + 解释二 §14（合同记载不一致的规则）。 场景二：多次赔付的\"三同条款\"（重点攻击对象） 典型表述：若被保险人因 同一疾病原因、同次医疗行为或同次意外伤害事故 导致两项或两项以上重大疾病，仅按其中一项给付。 拆解 1. 该条款写在\" 保险责任 \"章节、标题像在说\"怎么赔\"，实质 限制赔付次数 → 典型的 隐性免责条款 。 2. 保险人未就该条款单独提示并明确说明的 → 不发生效力。 3. 即便说明过，\"同一疾病原因\"的外延模糊 → §30 不利解释（例如：肺癌 → 一年后骨转移，是否\"同一疾病原因\"？条款未界定时间间隔的，应作有利于被保险人的解释）。 比喻 ：买了\"三次赔付\"的套餐，付款时才发现写着\"同一顿饭只算一次\"——而\"一顿饭\"的定义由店家说了算。 C9 · 分组、间隔期与保费豁免 要点 说明 分组多次赔付 同组疾病只赔一次。癌症单独分组的产品更优。分组规则属限制责任条款 → 隐性免责攻击 间隔期 （常见 180 天 / 1 年 / 3 年） 看清楚间隔期起算点与长度；间隔期条款同样可主张需提示说明 保费豁免 确诊轻症/中症/重疾后免交后续保费。豁免条件与疾病定义挂钩，纠纷随主险一并处理。 注意：豁免失效往往源于主险被解除 多次赔付的\"首次\"认定 首次赔付后合同是否继续、现金价值归零等，看条款 C10 · 遗传性疾病 / 先天性疾病免责 规则 ：多数重疾险将\"遗传性疾病、先天性畸形/变形/染色体异常\"列为免责，但通常会 附条件 （如\"符合 ICD 10 编码范围\"\"须有明确家族遗传史诊断\"）。 破解 1. 要求保险人举证该疾病 确实属于 条款界定的遗传/先天性疾病（谁主张谁举证）。 2. 条款对\"遗传性疾病\"的定义过于宽泛、无客观标准的 → §19 无效 + §30 不利解释。 3. 该免责条款本身是否 提示并明确说明 过（回到武器一）。 4. 该疾病是否也可能由后天因素导致（区分\"有遗传倾向\"与\"遗传性疾病\"）。 C11 · 就诊医院不符约定 规则 ：多数重疾险要求\" 国家二级及以上公立医院 \"或\"二级甲等及以上\"出具的诊断。 关键 ： 司法解释（三）第 20 条 —— 保险人以被保险人未在保险合同约定的医疗服务机构接受治疗为由拒绝给付保险金的，人民法院应予支持， 但被保险人因情况紧急必须立即就医的除外 。 所以 ：紧急情况下就近就医（哪怕是民营/一级医院）的，保险人不能据此拒赔。事后转院的，注意保留急诊记录与时间链条。 另：条款要求\"二级及以上 公立 医院\"而患者在医保定点的 民营 医院就诊的，可结合 §30 主张\"公立\"限定属加重责任、且未明确说明。 C12 · 病历主诉与\"既往症\"推定 场景 ：急诊病历主诉写着\"反复头晕 3 年\"，保险公司据此主张投保前已患病、未如实告知。 这是实务中最隐蔽也最致命的坑。 医生写主诉时往往直接采信患者或家属的随口描述，未经核实。 防范 1. 就诊时 准确陈述 症状起始时间，不要为求重视而夸大病程。 2. 发现病历主诉与事实不符的， 及时申请医院更正 （病程记录更正有规范程序，越早越好）。 3. 事后补救：用投保前的体检报告、既往就诊记录、单位体检结论 反证 此前无该病史；申请主治医生出具说明。 比喻 ：病历主诉是保险公司最爱的\"免费证人\"，而且这个证人还不用出庭。你在急诊室随口说的一句话，三年后会变成拒赔通知书上的第三行。 C13 · 病理报告与 ICD 编码（容易被保险人反用的一节） 规则（2020 版规范原文） 3.1.1.1 ：恶性肿瘤——重度要求\"病灶经 组织病理学检查 （涵盖骨髓病理学检查）结果明确诊断\"，临床诊断属 ICD 10 恶性肿瘤类别，且 ICD O 3 编码属 3、6、9 。 3.3.2（术语释义） ： 组织病理学检查是通过 局部切除、钳取、穿刺 等手术方法，从患者机体采取 病变组织块 ，经过包埋、切片后，进行病理检查的方法。 通过采集病变部位脱落细胞、细针吸取病变部位细胞、体腔积液分离病变细胞等方式获取病变细胞，制成涂片，进行病理检查的方法，属于 细胞病理学检查 ， 不属于组织病理学检查 。 3.3.3 ：ICD 10 与 ICD O 3 不一致的， 以 ICD O 3 为准 ；形态学编码 0=良性、1=动态未定性、2=原位癌和非侵袭性癌、3=恶性（原发性）、6=恶性（转移性）、9=恶性（原发或转移未肯定）。 ⚠️ 双向武器——这一条保险人也会用 方向 情形 打法 保险人用（对你不利） 只有胸水/腹水细胞学、支气管镜刷检、EUS FNA 细胞学涂片， 未取得组织块 保险人主张不符合\"组织病理学检查\" 你用（对保险人不利） 病灶位置 客观上无法 取得组织块（如胰腺、纵隔、脑干），临床上只能细胞学诊断 ① 主张条款未界定\"无法取得组织时如何处理\"，存在两种以上解释 → §30；② 主张该要求属 隐性免责 ，未提示说明不生效；③ 要求保险人举证\"必须取得组织块\"已向投保人明确说明 你用 骨髓/血液系统疾病（白血病、淋巴瘤） 规范明确 涵盖骨髓病理学检查 ；以骨髓细胞学/流式/活检综合诊断的，主张符合定义 你用 编码争议（交界性肿瘤、动态未定肿瘤） 规范已明确 1=动态未定性、2=原位癌 不在 重度范围；但 老保单（2007 版）未采 ICD O 3 ，可主张应作有利解释 防范建议 ：确诊后 主动向医生说明保险理赔需要\"组织病理学\"报告 ，在病情允许、风险可控的前提下争取取得组织块（活检/术后病理）。这一句话可能值几十万。 C14 · 理赔核定与迟延 情形复杂的应在 30 日内 作出核定（§23①）；核定期间自 初次收到索赔请求及有关证明资料之日 起算（解释二 §15）。 属于保险责任的，达成协议后 10 日内 给付。 自收到请求及资料起 60 日 内对数额不能确定的，应 先支付可以确定数额的最低部分 （§25）。 未及时履行的， 应赔偿因此受到的损失 （§23③）——可一并主张利息。 实战 ：保险人在 30 日内既不核定也不通知的，书面催告并固定时间节点，把\"拖延\"本身变成一项独立诉请。 C15 · 🔥 免责范围本身有\"天花板\"（规范 2.5 —— 最容易被忽略的武器） 规范 2.5 原文 ： 保险公司设定重大疾病保险除外责任时，对于被保险人发生的疾病、达到的疾病状态或进行的手术， 保险公司不承担保险责任的情形不能超出本规范 3.2 规定的范围 。 规范 3.2 列举的除外责任只有 9 项 ： 情形 3.2.1 投保人对被保险人的 故意杀害、故意伤害 3.2.2 被保险人 故意犯罪 或抗拒依法采取的刑事强制措施 3.2.3 被保险人 故意自伤 ，或自本合同成立/效力恢复之日起 2 年内自杀 （自杀时为无民事行为能力人的除外） 3.2.4 被保险人服用、吸食或注射 毒品 3.2.5 被保险人 酒后驾驶、无合法有效驾驶证驾驶 ，或驾驶无合法有效行驶证的机动车 3.2.6 被保险人 感染艾滋病病毒或患艾滋病 3.2.7 战争、军事冲突、暴乱或武装叛乱 3.2.8 核爆炸、核辐射或核污染 3.2.9 遗传性疾病，先天性畸形、变形或染色体异常 这意味着什么 1. 超出这 9 项的\"疾病类免责\"，是超出行业规范的。 例如条款把\"被保险人患有 XX 疾病\"\"未在特定医院就诊\"\"未采用特定治疗方式\"直接写成重疾险的 除外责任 ，就超出了 3.2 的封闭范围。 2. 打法 ：先主张该条款 违反行业规范 （规范虽非法律，但属监管认可的行业标准，且 2.5 是强制性表述\"不能超出\"）； 同时 主张该条款属\"免除或减轻保险人责任的条款\"，未提示说明不生效（§17 + 解释二 §9）。两条并用，不要单挂。 3. 注意区分 ：3.2 限定的是 除外责任（免责条款） ；\"疾病定义\"本身（3.1）是 责任范围 ，不受 9 项限制。保险人最常见的防守就是把\"定义限定\"说成\"不是免责条款\"——这正是 隐性免责规则 要解决的（见 C1）。两张牌要一起打： 若它主张\"这是定义/责任范围\" → 打 隐性免责 （未提示说明不生效）； 若它承认\"这是免责条款\" → 打 规范 2.5 （超出 3.2 九项范围）。 它总得选一边，而两边都有坑。 比喻 ：保险公司开餐厅，行业协会规定\"不许卖的菜只有 9 样\"。结果它的菜单上写着 30 样\"本店不供应\"。你只要问一句：\"这 9 样之外的，凭什么？\" C16 · \"不在保障范围内\"的排除列举，也是免责条款 🔥 规则 ：写在\"释义/定义\"章节里的排除列举（如\"下列疾病不属于恶性肿瘤——重度：ICD O 3 编码 0/1/2，如交界性肿瘤……\"），只要 实质限缩了理赔范围、减轻了保险人责任 ，就是免责条款，未提示说明 不生效 。 \" 但该约定实质限缩了恶性肿瘤的理赔范围、减轻了保险人的保险赔付责任，依法属于免除保险人责任的条款 ……未依法向投保人明确说明该免责条款内容，该免责条款依法不产生效力。\" ——湛江中院 (2026)粤08民终2416号（卵巢交界性肿瘤，判赔 49.9 万 + LPR 利息） 保险人标准抗辩 ：\"这是 责任范围条款 ，不是免责条款，所以我不用提示说明。\" 破解 ：直接引本案原文。判断标准是 实质效果 （是否限缩责任），不是条款放在哪一章。 C17 · ICD 编码不能否定病理报告记载的事实 \" 尽管原位癌的形态学编码为2，但该编码系基于主要病理特征的整体归类，不能否定病理诊断中已明确记载的浸润性病变事实。 保险合同条款未明确将'局灶间质微浸润'排除在'恶性肿瘤——重度'定义之外……依法亦应当作出有利于被保险人的解释。\" ——深圳中院 (2026)粤03民终9578号（乳腺导管原位癌伴局灶间质微浸润） 用法 ：病理报告里有\" 浸润 \"\"侵犯\"\"突破基底膜\"字样的，主张满足条款的实质特征（\"浸润和破坏周围正常组织\"），编码只是归类工具 → §30 兜底。 C18 · 疾病定义限缩常人理解 = 隐性免责 \"上述糖尿病定义应满足的多种并发症情形 已超出一般人对'严重Ⅰ型糖尿病'的理解，极大缩小了一般医学标准 …… 不论是在释义部分还是免责条款中 ，其目的在于充分保护投保人的知情权和选择权\" ——梅州中院 (2025)粤14民终795号 配套取证： 同一页上其他条款加粗、争议条款没加粗 → 对比即证据 。 另：保险人\" 仅指引投保人注意其他条款 \"的指引条款不能替代说明； 电话回访不能替代投保时的说明 。 C19 · 先天性疾病免责：加黑加粗也不够 \"上述条款 虽然采用加黑、加粗方式提醒投保人注意 ，但……仅明确符合 ICD 10 确定的分类和定义， 未能举证说明其对于先天性畸形的概念、内容作出具体解释，且为一般人能够知晓和理解 \" ——广州中院 (2024)粤01民终28133号（少儿重疾） 同案另两条： 少儿特定重疾保险金与陪护保险金可同时主张 （保险人\"发生重大疾病后不再付\"的主张因缺乏合同依据被驳）； \"同一次住院\"按 30 日间隔认定 ，算医疗费时先自己算一遍。 3. 投保前 checklist（照着逐项打勾） [ ] 目标疾病（尤其是最高发的恶性肿瘤、急性心梗、脑中风）的 定义条款逐字读过 [ ] 确认条款引用的是 2007 版还是 2020 版 规范 [ ] 甲状腺癌、原位癌、交界性肿瘤的赔付方式（重度还是轻度？比例多少？） [ ] 冠状动脉搭桥、主动脉手术是否仍要求\" 开胸 \" [ ] 脑中风后遗症的观察期（180 天？）与后遗症标准 [ ] 轻症/中症的 赔付比例 与是否有\"三同\"限制 [ ] 多次赔付的 分组规则、间隔期 [ ] 疾病种类数量（ 80 种 vs 120 种意义有限 ，高发的前 28 种由规范统一定义，差异在尾部） [ ] 等待期长度与\"初次发生\"的定义 [ ] 就诊医院要求（二级及以上？公立？） [ ] 是否含身故责任（含身故的重疾险保费明显更高，单独买定寿通常更划算） [ ] 保费豁免的触发条件 [ ] 健康告知页逐条截屏 （每一条的原文表述） [ ] 销售宣传页面 整页快照 （日后证明销售误导的唯一依据） 4. 出险后 72 小时动作清单 1. 立即报案 （多数条款要求\"及时通知\"，通常约定 10 日内；延迟通知的后果限于\"致使事故难以确定的部分\"——§21）。 2. 病历主诉核对 ：确认医生记录的症状起始时间、既往史准确。发现错误当场提出更正。 3. 证据固定清单 ：门/急诊病历、住院病案全套（含入院记录、手术记录、麻醉记录、病理报告、出院小结、检验报告）、诊断证明书（加盖医院公章）、费用清单与发票、影像资料与报告。 4. 核对条款 ：确认目标疾病的赔付条件类别，看自己是否满足；不满足的，立刻评估\"隐性免责 + 不利解释\"路径。 5. 书面提交理赔申请 （保留收件凭证），索取 书面 核定结果—— 拒绝口头拒赔 。 6. 所有沟通留痕 ：与理赔员的电话录音（中国法律下单方录音一般可作为证据）、微信/短信文字确认。 7. 不要急着签和解协议 ：签字前算清全部损失（保险金 + 迟延损失 + 后续治疗 + 保费豁免价值）。 5. 五个常见误解 误解 正解 \"病种越多越好\" 前 28 种由行业规范统一定义，各家公司一样。 差异在轻症比例、分组、定义细节 ，不在数量 \"确诊癌症就赔\" 要看是否满足\"恶性肿瘤——重度\"定义（含分期、除外项） \"熬过两年就一定赔\" 两年不可抗辩限制的是 解除权 ，不是万能钥匙；且保险人仍可在 30 日内行使解除权 \"没住过院就是健康体\" 体检异常、门诊诊断、影像报告同样可能构成应告知事项（取决于询问是否具体） \"有医保就不用买重疾险\" 医保报销医疗费用（补偿型）；重疾险给付的是 收入损失与康复费用 （定额型），两者不重叠 6. 与其他页面的关系 规范原文全文（A 级 · 中国保险行业协会官方 PDF） ：见L4 法条库/01 重疾定义使用规范2020（含 28 种重度 + 3 种轻度的 逐条定义 、除外责任 9 项、术语释义、甲状腺癌 TNM 分期表） 武器层面的完整论证 ：见L0 打法层/01 八把通用武器 完整维权流程、时效表、文书模板 ：见L0 打法层/02 维权操作全流程 广东真实案例 ：见L2 案例库/广东案例 重疾医疗 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L1-险种层/02-医疗险", "group": "2 · 险种深挖", "groupKey": "L1-险种层", "title": "医疗险 · 纠纷全解", "order": 2, "file": "02-医疗险.md", "html": "<h1 id=\"s0\">医疗险 · 纠纷全解</h1>\n<blockquote><strong>本页自包含</strong>——读这一页不需要翻其他文件。<br><br><strong>一句话定位</strong>：医疗险是\"<strong>花多少报多少</strong>\"的补偿型保险。它的战场不在\"得了什么病\"，而在\"<strong>这笔钱该不该报、按什么口径算</strong>\"。<br>主流形态：<strong>百万医疗险</strong>（高保额、1 万免赔额、一年期）+ <strong>小额住院医疗</strong>（低免赔、低保额）+ <strong>中高端医疗</strong>（直付、含门急诊）。</blockquote>\n<hr>\n<h2 id=\"s1\">0. 速查卡片（本页最重要的 12 条）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>要点</th><th>依据</th></tr></thead><tbody>\n<tr><td>1</td><td>医疗险适用<strong>损失补偿原则</strong>，不能因保险获利；<strong>定额津贴型</strong>（住院津贴）除外</td><td>保险法 §55 / 财产保险合同原则类推</td></tr>\n<tr><td>2</td><td>保险人主张<strong>扣减医保已报销部分</strong>的，必须证明<strong>费率厘定时已扣除社保部分并按扣减后标准收费</strong></td><td>解释三 §18</td></tr>\n<tr><td>3</td><td>约定\"按<strong>基本医疗保险标准</strong>核定费用\"的，保险人不能仅以\"超出医保范围\"拒赔；只能对<strong>超过同类费用标准</strong>的部分拒赔</td><td>解释三 §19</td></tr>\n<tr><td>4</td><td>未在约定医疗机构就诊拒赔的，<strong>情况紧急立即就医</strong>的除外</td><td>解释三 §20</td></tr>\n<tr><td>5</td><td><strong>免赔额</strong>属\"免除或减轻保险人责任的条款\"，必须提示说明</td><td>解释二 §9</td></tr>\n<tr><td>6</td><td><strong>既往症</strong>定义过宽、无客观标准的 → §19 无效 + §30 不利解释</td></tr>\n<tr><td>7</td><td>既往症抗辩的前提是该疾病<strong>投保前已明确诊断且未治愈</strong>；仅有症状、未经诊断的不构成</td></tr>\n<tr><td>8</td><td><strong>续保条款是非保证续保产品最大的坑</strong>：理赔后拒续、产品停售</td></tr>\n<tr><td>9</td><td>一年期医疗险<strong>不适用</strong>两年不可抗辩的实践意义有限（合同每年重订）</td></tr>\n<tr><td>10</td><td><strong>社保罚则</strong>（未用社保结算则报销比例降至 60%）属比例给付条款 → 需提示说明</td></tr>\n<tr><td>11</td><td>院外特药、质子重离子、CAR-T 属<strong>责任范围</strong>问题，不是免责问题，重点在<strong>投保时看清</strong></td></tr>\n<tr><td>12</td><td>诉讼时效 <strong>2 年</strong>，自知道或应当知道保险事故发生之日起算</td><td>保险法 §26</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">1. 险种地图</h2>\n<pre><code>\n医疗险（费用补偿型）\n\n├── 住院医疗费用（核心责任）\n\n├── 特殊门诊（透析、放化疗、器官移植抗排异等）\n\n├── 门诊手术 / 住院前后门急诊（前 7 后 30 天常见）\n\n├── 院外特药 / 靶向药（是否含、清单范围、是否直付）\n\n├── 质子重离子治疗（是否含、指定医院）\n\n├── 免赔额（常见 1 万；有的\"6 年共享 1 万\"）\n\n├── 给付比例（社保结算后 100%？未用社保 60%？）\n\n├── 续保条款（保证续保 X 年 / 非保证续保 / 承诺续保至 X 岁）\n\n└── 增值服务（就医绿通、住院垫付、外购药）\n\n</code></pre>\n<p><strong>关键认知</strong>：医疗险的\"保额 400 万\"基本是营销数字——<strong>你一年实际住院花销超过免赔额、进入赔付区间的概率才是关键</strong>。真正决定体验的是：免赔额口径、续保稳定性、责任范围边界。</p>\n<p><strong>比喻</strong>：百万医疗险像一张\"满 1 万减全部\"的券。看起来力度惊人，但你得先自己掏满 1 万。而这张券<strong>每年都要重新发</strong>——这就是续保风险。</p>\n<hr>\n<h2 id=\"s3\">2. 争点逐解</h2>\n<h3 id=\"s4\">M1 · 损失补偿原则与重复理赔</h3>\n<p><strong>规则</strong>：费用补偿型医疗险适用<strong>损失补偿原则</strong>——被保险人获得的赔偿<strong>不得超过实际支出</strong>。已通过医保、其他商业保险、第三人赔偿获得补偿的部分，不能重复索赔。</p>\n<p><strong>例外</strong>：<strong>定额给付型</strong>（如住院津贴 200 元/天、手术津贴）与实际支出无关，可以叠加。</p>\n<p><strong>争点</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>保险人主张</th><th>破解</th></tr></thead><tbody>\n<tr><td>\"你已从医保报销，所以要扣减\"</td><td>引<strong>解释三 §18</strong>：保险人须证明该产品在<strong>厘定费率时已将公费医疗/社保部分相应扣除，并按扣减后标准收取保费</strong>。很多\"有社保版本/无社保版本\"收费不同的产品能证明；<strong>收费相同的则难以主张扣减</strong></td></tr>\n<tr><td>\"你已从其他商业医疗险获赔，不能重复\"</td><td>看条款是否明确约定为<strong>分摊/扣除</strong>条款。未约定的，损失补偿原则的具体适用存在争议；主张己方条款无此约定、且保险人未尽提示说明</td></tr>\n<tr><td>\"第三者已赔偿，我们不赔\"</td><td>人身保险的被保险人<strong>可以同时</strong>向第三者和保险人主张（人身损害赔偿不适用财产保险的代位规则）；费用型医疗险的实务处理则看条款</td></tr>\n</tbody></table></div>\n<p><strong>实战动作</strong>：把\"医保结算单 + 自付凭证 + 其他保险赔付凭证\"全部整理成一张<strong>费用流水表</strong>，逐项标注：总费用 / 医保支付 / 大病保险支付 / 自付 / 其他商业险已赔 / 本次索赔金额。</p>\n<hr>\n<h3 id=\"s5\">M2 · 社保罚则与\"按医保标准核定\"</h3>\n<p><strong>典型条款</strong>：</p>\n<blockquote>若被保险人<strong>未以社会医疗保险身份</strong>就诊并结算，本公司按应赔付金额的 <strong>60%</strong> 给付。</blockquote>\n<blockquote>本合同医疗费用按<strong>基本医疗保险标准</strong>核定。</blockquote>\n<p><strong>拆解（解释三 §19 是核心武器）</strong></p>\n<blockquote>保险合同约定按照基本医疗保险的标准核定医疗费用，保险人以被保险人的医疗支出<strong>超出基本医疗保险范围</strong>为由拒绝给付保险金的，<strong>人民法院不予支持</strong>；保险人有证据证明被保险人支出的费用<strong>超过基本医疗保险同类医疗费用标准</strong>，要求对超出部分拒绝给付保险金的，人民法院应予支持。</blockquote>\n<p><strong>这条的意思是</strong>：</p>\n<ol>\n<li>保险人<strong>不能笼统地说\"这个药不在医保目录，不报\"</strong>。</li>\n<li>保险人只能针对\"<strong>同类项目，你的花费高于医保同类标准</strong>\"的那部分拒赔——即必须做<strong>同类对比</strong>，而不是目录比对。</li>\n<li>保险人对此<strong>负举证责任</strong>（要证明超出部分、超出多少）。</li>\n</ol>\n<p><strong>社保罚则（未用社保结算降比例）</strong></p>\n<ul>\n<li>定性与<strong>解释二 §9</strong>：比例给付条款属于\"免除或者减轻保险人责任的条款\" → <strong>必须提示 + 明确说明</strong>，否则不生效。</li>\n<li>破解方向：① 该条款是否显著提示、是否明确说明\"降比例\"的后果；② 未用社保的原因是否合理（异地急诊、社保断缴、医院不支持等）；③ 该比例限制是否显失公平。</li>\n<li><strong>防范优先</strong>：用社保身份就诊并结算，是最省事的做法。</li>\n</ul>\n<hr>\n<h3 id=\"s6\">M3 · 既往症拒赔（医疗险第一大拒赔理由）</h3>\n<p><strong>典型条款</strong>：</p>\n<blockquote>既往症：指<strong>本合同生效前</strong>被保险人已知或应当知道的有关疾病或症状。通常包括：① 本合同生效前，医生已有明确诊断且<strong>未治愈</strong>的；② 症状明显、持续存在，<strong>以普通人医学常识应当知晓</strong>的。</blockquote>\n<p><strong>拆解</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>攻击点</th><th>论证</th></tr></thead><tbody>\n<tr><td><strong>须\"明确诊断\"</strong></td><td>仅有体检指标异常、影像描述（如\"结节，建议随访\"）<strong>未经医生明确诊断</strong>的，不构成既往症</td></tr>\n<tr><td><strong>须\"未治愈\"</strong></td><td>已治愈的急性疾病（如已治愈的肺炎、已切除且病理良性的息肉）不属于</td></tr>\n<tr><td><strong>\"应当知道\"标准过宽</strong></td><td>\"以普通人医学常识应当知晓\"缺乏客观标准 → §19 无效 + §30 不利解释</td></tr>\n<tr><td><strong>与本次治疗的因果关系</strong></td><td>既往症与本次住院无关联的，即便是既往症也不应影响本次赔付</td></tr>\n<tr><td><strong>提示说明义务</strong></td><td>既往症条款一般在\"责任免除\"或\"释义\"章节 → 必须提示 + 明确说明（§17）</td></tr>\n</tbody></table></div>\n<p><strong>证据</strong>：投保前 2-3 年的体检报告、门诊记录（<strong>证明此前无相关诊断</strong>）、本次住院病案的入院记录与主诉、主管医师关于\"本次为新发疾病\"的说明。</p>\n<p><strong>比喻</strong>：既往症条款像健身房会籍协议里的\"入会前已有的旧伤不负责\"。问题在于：什么叫\"旧伤\"？三年前扭过一次脚算吗？<strong>定义模糊时，判给会员。</strong></p>\n<hr>\n<h3 id=\"s7\">M4 · 免赔额的计算口径</h3>\n<p><strong>争点</strong>：社保报销的金额<strong>是否计入</strong>免赔额？</p>\n<p><strong>典型条款表述对比</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>表述</th><th>效果</th></tr></thead><tbody>\n<tr><td>\"被保险人<strong>自行支付</strong>的医疗费用超过 1 万元的部分\"</td><td>对被保险人有利（社保支付部分不计入免赔额）</td></tr>\n<tr><td>\"被保险人<strong>实际发生</strong>的医疗费用扣除 1 万元后\"</td><td>对保险人有利（社保部分先填免赔额）</td></tr>\n</tbody></table></div>\n<p><strong>拆解</strong></p>\n<ol>\n<li>这是<strong>条款文义之争</strong>，先按通常理解解释；仍有歧义的 → §30 不利解释。</li>\n<li>免赔额属于解释二 §9 列举的\"免赔额、免赔率\"→ <strong>必须提示说明</strong>，否则不生效。</li>\n<li>\"6 年共享 1 万免赔额\"这类优惠条款，注意<strong>起算与清零规则</strong>（保证续保期间内累计）。</li>\n</ol>\n<p><strong>防范</strong>：投保前直接问客服\"社保报销的部分算不算免赔额\"，<strong>留文字记录</strong>。</p>\n<hr>\n<h3 id=\"s8\">M5 · 续保条款（最大的隐藏风险）—— 监管有明文禁令</h3>\n<p><strong><span class=\"warn\">!</span> 2021 年起，监管机构对\"短险长做\"下了硬禁令。</strong> 见《中国银保监会办公厅关于规范短期健康保险业务有关问题的通知》（银保监办发〔2021〕7 号）。</p>\n<p><strong>监管原文（第 3 条）</strong></p>\n<blockquote>保险公司开发的短期健康保险产品中包含续保责任的，应当在保险条款中<strong>明确表述为\"不保证续保\"条款</strong>。不保证续保条款中至少应当包含以下内容：<br><strong>本产品保险期间为一年（或不超过一年）。保险期间届满，投保人需要重新向保险公司申请投保本产品，并经保险人同意，交纳保险费，获得新的保险合同。</strong><br>保险公司不得在短期健康保险产品条款、宣传材料中使用<strong>\"自动续保\"\"承诺续保\"\"终身限额\"</strong>等易与长期健康保险混淆的词句。</blockquote>\n<p><strong>看到这些词，就是违规（可举报 + 可主张按页面承诺履行）</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>页面/条款表述</th><th>判断</th></tr></thead><tbody>\n<tr><td>\"自动续保\"\"承诺续保\"\"终身限额\"</td><td>❌ <strong>明令禁止</strong></td></tr>\n<tr><td>\"可续保至 100 岁\"\"续保时最高年龄可至 XX 周岁\"</td><td>❌ 易混淆，禁止</td></tr>\n<tr><td>\"我们不会因为被保险人在首次投保后的健康状况变化而拒绝您的重新投保申请\"</td><td>❌ 变相承诺续保，禁止</td></tr>\n<tr><td>\"不保证续保\" + \"期满需重新申请投保，经保险人同意\"</td><td>✅ 合规</td></tr>\n<tr><td>\"<strong>保证续保</strong> 20 年\"</td><td>✅ 长期健康险，不受本条限制</td></tr>\n</tbody></table></div>\n<p><strong>三种续保形态</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>形态</th><th>含义</th><th>风险</th></tr></thead><tbody>\n<tr><td><strong>保证续保 X 年</strong></td><td>在保证续保期间内，保险公司<strong>必须</strong>按约定费率和条款续保，不因健康变化或理赔而拒续</td><td>最稳。到期后仍需重新投保</td></tr>\n<tr><td><strong>非保证续保</strong>（\"不因健康变化拒绝续保\"之类表述）</td><td>表述模糊，<strong>产品停售则可拒续</strong></td><td><span class=\"warn\">!</span> 高风险</td></tr>\n<tr><td><strong>承诺续保至 X 岁</strong></td><td>常见于宣传页</td><td>须有<strong>书面</strong>证据；且若属短期健康险，该表述本身<strong>违规</strong></td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 关键</strong>：真正值钱的不是\"保额 400 万\"（第 5 条甚至禁止设定严重背离理赔经验的虚高保额），而是\"<strong>保证续保 20 年</strong>\"这七个字。</p>\n<p><strong>破解路径</strong></p>\n<ol>\n<li>看条款中\"<strong>保证续保</strong>\"四字是否明确出现，以及保证期间。</li>\n<li>宣传页面有\"可续保至 100 岁\"\"自动续保\"等表述的，<strong>保存页面快照</strong> → ① 销售误导，主张按页面承诺履行；② 向 12378 举报违规宣传。</li>\n<li>续保时保险人<strong>要求重新健康告知或加费</strong>的，看是否违反保证续保条款。</li>\n<li><strong>产品停售</strong>：依第 10 条，保险公司须披露停售原因与时间、为已购用户在保险期间内继续提供保障、<strong>期满时提供转保建议</strong>；主动停售须<strong>至少提前 30 日</strong>披露。<strong>没做到的，既是监管违规，也是主张损失的事实基础。</strong></li>\n</ol>\n<p><strong>另外两条被低估的武器（同通知第 8、9 条）</strong></p>\n<ul>\n<li><strong>投保须知书</strong>：销售短期健康险时，保险公司<strong>应当向消费者提供\"短期健康保险产品投保须知书\"</strong>，并重点提示 9 项内容（如实告知后果、保险责任与除外责任、保险期间、保险金额、免赔额、赔付比例、等待期、投保年龄与保费关联性等）。→ <strong>向保险人索要这份文件，核对是否给过你、9 项是否齐全。</strong> 缺失 = 未尽提示义务的证据。</li>\n<li><strong>第 9 条</strong>：<strong>\"健康告知信息的设定不得出现有违一般医学常识等情形\"</strong> → 这是攻击<strong>概括性询问</strong>的<strong>监管依据</strong>，与司法解释二 §6② 并用。同时该条明令<strong>\"严禁保险公司通过设定产品拒赔率等考核指标\"</strong>影响正常理赔诉求——怀疑理赔员因考核拒赔的，可在投诉中要求监管核查其考核指标。</li>\n</ul>\n<p>完整条文见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F03-%E5%81%A5%E5%BA%B7%E9%99%A9%E7%9B%91%E7%AE%A1%E8%A7%84%E8%8C%83\">《健康险监管规范 · 短期健康保险（银保监办发〔2021〕7 号）原文摘录》</a>。</p>\n<hr>\n<h3 id=\"s9\">M6 · 责任边界：特药、质子重离子、院外购药、CAR-T</h3>\n<p><strong><span class=\"warn\">!</span> 这类争议的本质是\"责任范围\"，不是\"免责条款\"</strong>——保险人主张\"这本来就不在保障范围内\"，而不是\"我们免责\"。所以<strong>武器一（提示说明义务）在这里作用有限，重点在投保前看清</strong>。</p>\n<div class=\"tablewrap\"><table><thead><tr><th>项目</th><th>常见坑</th><th>投保前看什么</th></tr></thead><tbody>\n<tr><td><strong>院外特药 / 靶向药</strong></td><td>医院开不出药，需院外 DTP 药房购买 → 不在\"住院医疗费用\"内</td><td>是否含\"<strong>院外特定药品费用</strong>\"责任、药品清单范围、是否需指定药店</td></tr>\n<tr><td><strong>质子重离子</strong></td><td>部分产品不含，或限定\"上海质子重离子医院\"</td><td>是否含、指定机构、赔付比例（常见 100% 或 60%）</td></tr>\n<tr><td><strong>CAR-T / 免疫治疗</strong></td><td>单价百万级，多数百万医疗险不含或有限额</td><td>是否列入特定药品清单、有无单独限额</td></tr>\n<tr><td><strong>器官移植</strong></td><td>有的只报\"手术费\"不报\"器官源费用\"</td><td>责任表述与除外项</td></tr>\n<tr><td><strong>门诊手术 / 日间病房</strong></td><td>不住院则不属于\"住院医疗\"</td><td>是否含\"门诊手术\"\"日间手术\"责任</td></tr>\n<tr><td><strong>中医 / 康复 / 理疗</strong></td><td>多被除外</td><td>除外清单</td></tr>\n</tbody></table></div>\n<p><strong>事后救济</strong>：若<strong>销售页面明确宣传</strong>包含上述责任、而条款未包含 → 销售误导 + 页面快照作为证据；争议时主张以<strong>对消费者有利的表述</strong>为准（§30 / 解释二 §14）。</p>\n<hr>\n<h3 id=\"s10\">M7 · 就诊医院与紧急就医</h3>\n<p><strong>规则</strong>：<strong>解释三 §20</strong>——</p>\n<blockquote>保险人以被保险人未在保险合同约定的医疗服务机构接受治疗为由拒绝给付保险金的，人民法院应予支持，<strong>但被保险人因情况紧急必须立即就医的除外</strong>。</blockquote>\n<p><strong>实务要点</strong></p>\n<ol>\n<li>常见约定：\"<strong>中国大陆境内二级及以上公立医院</strong>普通部\"（不含特需/VIP/国际部）。</li>\n<li>危急情况就近就医的，注意固定<strong>急诊记录</strong>、时间链条、转院记录。</li>\n<li>条款要求\"<strong>公立</strong>\"而实际在医保定点民营医院就诊的 → 主张\"公立\"限定属加重责任、且未尽明确说明；并结合是否符合\"紧急\"情形。</li>\n<li>特需部/VIP 部：中端医疗险才含，百万医疗险通常不含。</li>\n</ol>\n<hr>\n<h3 id=\"s11\">M8 · 健康告知与一年期产品的特殊性</h3>\n<p><strong><span class=\"warn\">!</span> 一年期医疗险的特殊风险</strong>：合同<strong>每年重新订立</strong>，\"两年不可抗辩\"的实践意义被大幅削弱——保险人可以在<strong>续保时</strong>重新核保、拒保或除外责任。</p>\n<p><strong>应对</strong></p>\n<ol>\n<li>优先选<strong>保证续保</strong>产品，把风险锁死。</li>\n<li>如实告知依然是第一原则——隐瞒告知的代价比重疾险更高（一年期产品下，几乎不存在\"熬两年就安全\"）。</li>\n<li>投保时逐条截屏健康告知页。</li>\n</ol>\n<hr>\n<h3 id=\"s12\">M9 · 理赔核定、举证与补充材料</h3>\n<ul>\n<li>情形复杂的 <strong>30 日内</strong>核定（§23①），自<strong>初次收到索赔请求及资料之日</strong>起算（解释二 §15）。</li>\n<li>索赔方只需提供\"<strong>其所能提供的</strong>\"证明和资料（§22①）。</li>\n<li>保险人要求补充材料应<strong>及时一次性</strong>通知（§22②）——反复补材料制造拖延的，可主张违反法定程序。</li>\n<li>未及时赔付的，<strong>应赔偿因此受到的损失</strong>（§23③）。</li>\n</ul>\n<p><strong>实战</strong>：把每一次补充材料的要求<strong>书面化</strong>（要求出具书面清单），形成时间轴。这既是抗辩拖延的证据，也是主张迟延损失的依据。</p>\n<hr>\n<h3 id=\"s13\">M10 · 既往症与\"示范视频\"（A 级判例）</h3>\n<blockquote>\"<strong>提交的投保示范视频并非张某甲父亲代投保时的视频轨迹</strong>，仅凭投保单上'张某甲'的签名字样尚不足以证明……已通过人工、网页、音频、视频等任何形式说明免责条款的内容及法律后果\"<br>——广州中院 (2025)粤01民终24935号（百万医疗，一审说理，二审维持）</blockquote>\n<p><strong>打法</strong>：要求保险人提供<strong>本次投保的可回溯记录</strong>。互联网保险可回溯是监管硬要求，拿不出来就是没做。</p>\n<h3 id=\"s14\">M11 · <span class=\"warn\">!</span> 反面：医疗险适用损失补偿原则，医保已付部分要扣除</h3>\n<p>同案（粤01民终24935号）：法院认定百万医疗属<strong>补偿性保险合同</strong>，医保统筹基金已支付的 40,947.45 元须扣除 → 5.2 万诉求扣完只剩 1,231.35 元。</p>\n<p>且一般医疗保额未赔满前，<strong>不能跳到\"恶性肿瘤——重度医疗\"责任项下重复主张</strong>。</p>\n<p><strong>教训</strong>：赢了免责条款也可能输在金额上。投保前看清\"是否限社保范围内\"\"免赔额多少\"\"各项责任是否共用保额\"。</p>\n<h2 id=\"s15\">3. 投保前 checklist</h2>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>保证续保</strong>几个字是否在条款中明确出现？保证多少年？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 免赔额：<strong>多少</strong>？社保报销部分<strong>是否计入</strong>？是否多年共享？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 给付比例：用社保结算后多少？未用社保多少？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否含<strong>院外特药</strong>？药品清单范围？是否指定药店？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否含<strong>质子重离子</strong>？指定机构？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否含门诊手术 / 日间病房 / 住院前后门急诊（天数）？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 既往症定义原文（要求\"明确诊断 + 未治愈\"？）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 就诊医院要求（二级及以上？公立？含不含特需？）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 除外责任逐条读过（特に：生育、牙科、整形、体检、康复、中医、艾滋病、战争、高风险运动）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 职业类别是否匹配（部分医疗险对高危职业拒保或除外）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否有<strong>住院垫付 / 就医绿通</strong>（实用性高于保额数字）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 健康告知页<strong>逐条截屏</strong></div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 销售页面<strong>整页快照</strong></div>\n<hr>\n<h2 id=\"s16\">4. 出险后动作清单</h2>\n<ol>\n<li><strong>用社保身份就诊并结算</strong>（避免社保罚则）。</li>\n<li><strong>核对医院等级</strong>是否符合条款；紧急就医的保留急诊记录。</li>\n<li>固定全套资料：门急诊病历、住院病案（入院记录、手术记录、出院小结）、诊断证明（盖章）、费用明细清单、发票原件、医保结算单。</li>\n<li><strong>院外购药</strong>：保留处方、药店发票、药品清单；确认是否在特药清单内。</li>\n<li>书面提交理赔申请，索取<strong>书面</strong>核定结果。</li>\n<li>保险人反复要求补材料的，要求其<strong>一次性书面列明</strong>。</li>\n<li>超 30 日未核定的，书面催告并保留凭证。</li>\n</ol>\n<hr>\n<h2 id=\"s17\">5. 四个常见误解</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody>\n<tr><td>\"买了两份百万医疗能赔两次\"</td><td>费用补偿型<strong>不能重复获利</strong>；定额津贴型可以</td></tr>\n<tr><td>\"保额 400 万很够用\"</td><td>一年实际能用到的上限取决于<strong>责任范围</strong>，保额数字基本是营销</td></tr>\n<tr><td>\"续保是自动的\"</td><td>只有<strong>保证续保</strong>产品才是；非保证续保产品停售或被保险人健康恶化都可能不续</td></tr>\n<tr><td>\"超过医保目录就不报\"</td><td>解释三 §19：保险人只能拒赔\"<strong>超过同类医疗费用标准</strong>\"的部分，不能笼统以\"超出医保范围\"拒赔</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s18\">6. 与其他页面的关系</h2>\n<ul>\n<li><strong>通用打法</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a></li>\n<li><strong>完整流程与时效</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>专题案例</strong>：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E4%B8%93%E9%A2%98-%E6%8F%90%E7%A4%BA%E8%AF%B4%E6%98%8E%E4%B9%89%E5%8A%A1%E4%B8%8E%E7%94%B5%E5%AD%90%E6%8A%95%E4%BF%9D\">《专题案例 · 提示说明义务与电子投保格式条款》</a></li>\n<li><strong>广东案例</strong>：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E9%87%8D%E7%96%BE%E5%8C%BB%E7%96%97\">《重疾险 / 医疗险 · 案例库》</a></li>\n<li><strong>监管规范</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F03-%E5%81%A5%E5%BA%B7%E9%99%A9%E7%9B%91%E7%AE%A1%E8%A7%84%E8%8C%83\">《健康险监管规范 · 短期健康保险（银保监办发〔2021〕7 号）原文摘录》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "0. 速查卡片（本页最重要的 12 条）"}, {"id": "s2", "lv": 2, "t": "1. 险种地图"}, {"id": "s3", "lv": 2, "t": "2. 争点逐解"}, {"id": "s4", "lv": 3, "t": "M1 · 损失补偿原则与重复理赔"}, {"id": "s5", "lv": 3, "t": "M2 · 社保罚则与\"按医保标准核定\""}, {"id": "s6", "lv": 3, "t": "M3 · 既往症拒赔（医疗险第一大拒赔理由）"}, {"id": "s7", "lv": 3, "t": "M4 · 免赔额的计算口径"}, {"id": "s8", "lv": 3, "t": "M5 · 续保条款（最大的隐藏风险）—— 监管有明文禁令"}, {"id": "s9", "lv": 3, "t": "M6 · 责任边界：特药、质子重离子、院外购药、CAR-T"}, {"id": "s10", "lv": 3, "t": "M7 · 就诊医院与紧急就医"}, {"id": "s11", "lv": 3, "t": "M8 · 健康告知与一年期产品的特殊性"}, {"id": "s12", "lv": 3, "t": "M9 · 理赔核定、举证与补充材料"}, {"id": "s13", "lv": 3, "t": "M10 · 既往症与\"示范视频\"（A 级判例）"}, {"id": "s14", "lv": 3, "t": "M11 · ! 反面：医疗险适用损失补偿原则，医保已付部分要扣除"}, {"id": "s15", "lv": 2, "t": "3. 投保前 checklist"}, {"id": "s16", "lv": 2, "t": "4. 出险后动作清单"}, {"id": "s17", "lv": 2, "t": "5. 四个常见误解"}, {"id": "s18", "lv": 2, "t": "6. 与其他页面的关系"}], "text": "医疗险 · 纠纷全解 本页自包含 ——读这一页不需要翻其他文件。 一句话定位 ：医疗险是\" 花多少报多少 \"的补偿型保险。它的战场不在\"得了什么病\"，而在\" 这笔钱该不该报、按什么口径算 \"。 主流形态： 百万医疗险 （高保额、1 万免赔额、一年期）+ 小额住院医疗 （低免赔、低保额）+ 中高端医疗 （直付、含门急诊）。 0. 速查卡片（本页最重要的 12 条） 要点 依据 1 医疗险适用 损失补偿原则 ，不能因保险获利； 定额津贴型 （住院津贴）除外 保险法 §55 / 财产保险合同原则类推 2 保险人主张 扣减医保已报销部分 的，必须证明 费率厘定时已扣除社保部分并按扣减后标准收费 解释三 §18 3 约定\"按 基本医疗保险标准 核定费用\"的，保险人不能仅以\"超出医保范围\"拒赔；只能对 超过同类费用标准 的部分拒赔 解释三 §19 4 未在约定医疗机构就诊拒赔的， 情况紧急立即就医 的除外 解释三 §20 5 免赔额 属\"免除或减轻保险人责任的条款\"，必须提示说明 解释二 §9 6 既往症 定义过宽、无客观标准的 → §19 无效 + §30 不利解释 7 既往症抗辩的前提是该疾病 投保前已明确诊断且未治愈 ；仅有症状、未经诊断的不构成 8 续保条款是非保证续保产品最大的坑 ：理赔后拒续、产品停售 9 一年期医疗险 不适用 两年不可抗辩的实践意义有限（合同每年重订） 10 社保罚则 （未用社保结算则报销比例降至 60%）属比例给付条款 → 需提示说明 11 院外特药、质子重离子、CAR T 属 责任范围 问题，不是免责问题，重点在 投保时看清 12 诉讼时效 2 年 ，自知道或应当知道保险事故发生之日起算 保险法 §26 1. 险种地图 关键认知 ：医疗险的\"保额 400 万\"基本是营销数字—— 你一年实际住院花销超过免赔额、进入赔付区间的概率才是关键 。真正决定体验的是：免赔额口径、续保稳定性、责任范围边界。 比喻 ：百万医疗险像一张\"满 1 万减全部\"的券。看起来力度惊人，但你得先自己掏满 1 万。而这张券 每年都要重新发 ——这就是续保风险。 2. 争点逐解 M1 · 损失补偿原则与重复理赔 规则 ：费用补偿型医疗险适用 损失补偿原则 ——被保险人获得的赔偿 不得超过实际支出 。已通过医保、其他商业保险、第三人赔偿获得补偿的部分，不能重复索赔。 例外 ： 定额给付型 （如住院津贴 200 元/天、手术津贴）与实际支出无关，可以叠加。 争点 保险人主张 破解 \"你已从医保报销，所以要扣减\" 引 解释三 §18 ：保险人须证明该产品在 厘定费率时已将公费医疗/社保部分相应扣除，并按扣减后标准收取保费 。很多\"有社保版本/无社保版本\"收费不同的产品能证明； 收费相同的则难以主张扣减 \"你已从其他商业医疗险获赔，不能重复\" 看条款是否明确约定为 分摊/扣除 条款。未约定的，损失补偿原则的具体适用存在争议；主张己方条款无此约定、且保险人未尽提示说明 \"第三者已赔偿，我们不赔\" 人身保险的被保险人 可以同时 向第三者和保险人主张（人身损害赔偿不适用财产保险的代位规则）；费用型医疗险的实务处理则看条款 实战动作 ：把\"医保结算单 + 自付凭证 + 其他保险赔付凭证\"全部整理成一张 费用流水表 ，逐项标注：总费用 / 医保支付 / 大病保险支付 / 自付 / 其他商业险已赔 / 本次索赔金额。 M2 · 社保罚则与\"按医保标准核定\" 典型条款 ： 若被保险人 未以社会医疗保险身份 就诊并结算，本公司按应赔付金额的 60% 给付。 本合同医疗费用按 基本医疗保险标准 核定。 拆解（解释三 §19 是核心武器） 保险合同约定按照基本医疗保险的标准核定医疗费用，保险人以被保险人的医疗支出 超出基本医疗保险范围 为由拒绝给付保险金的， 人民法院不予支持 ；保险人有证据证明被保险人支出的费用 超过基本医疗保险同类医疗费用标准 ，要求对超出部分拒绝给付保险金的，人民法院应予支持。 这条的意思是 ： 1. 保险人 不能笼统地说\"这个药不在医保目录，不报\" 。 2. 保险人只能针对\" 同类项目，你的花费高于医保同类标准 \"的那部分拒赔——即必须做 同类对比 ，而不是目录比对。 3. 保险人对此 负举证责任 （要证明超出部分、超出多少）。 社保罚则（未用社保结算降比例） 定性与 解释二 §9 ：比例给付条款属于\"免除或者减轻保险人责任的条款\" → 必须提示 + 明确说明 ，否则不生效。 破解方向：① 该条款是否显著提示、是否明确说明\"降比例\"的后果；② 未用社保的原因是否合理（异地急诊、社保断缴、医院不支持等）；③ 该比例限制是否显失公平。 防范优先 ：用社保身份就诊并结算，是最省事的做法。 M3 · 既往症拒赔（医疗险第一大拒赔理由） 典型条款 ： 既往症：指 本合同生效前 被保险人已知或应当知道的有关疾病或症状。通常包括：① 本合同生效前，医生已有明确诊断且 未治愈 的；② 症状明显、持续存在， 以普通人医学常识应当知晓 的。 拆解 攻击点 论证 须\"明确诊断\" 仅有体检指标异常、影像描述（如\"结节，建议随访\"） 未经医生明确诊断 的，不构成既往症 须\"未治愈\" 已治愈的急性疾病（如已治愈的肺炎、已切除且病理良性的息肉）不属于 \"应当知道\"标准过宽 \"以普通人医学常识应当知晓\"缺乏客观标准 → §19 无效 + §30 不利解释 与本次治疗的因果关系 既往症与本次住院无关联的，即便是既往症也不应影响本次赔付 提示说明义务 既往症条款一般在\"责任免除\"或\"释义\"章节 → 必须提示 + 明确说明（§17） 证据 ：投保前 2 3 年的体检报告、门诊记录（ 证明此前无相关诊断 ）、本次住院病案的入院记录与主诉、主管医师关于\"本次为新发疾病\"的说明。 比喻 ：既往症条款像健身房会籍协议里的\"入会前已有的旧伤不负责\"。问题在于：什么叫\"旧伤\"？三年前扭过一次脚算吗？ 定义模糊时，判给会员。 M4 · 免赔额的计算口径 争点 ：社保报销的金额 是否计入 免赔额？ 典型条款表述对比 表述 效果 \"被保险人 自行支付 的医疗费用超过 1 万元的部分\" 对被保险人有利（社保支付部分不计入免赔额） \"被保险人 实际发生 的医疗费用扣除 1 万元后\" 对保险人有利（社保部分先填免赔额） 拆解 1. 这是 条款文义之争 ，先按通常理解解释；仍有歧义的 → §30 不利解释。 2. 免赔额属于解释二 §9 列举的\"免赔额、免赔率\"→ 必须提示说明 ，否则不生效。 3. \"6 年共享 1 万免赔额\"这类优惠条款，注意 起算与清零规则 （保证续保期间内累计）。 防范 ：投保前直接问客服\"社保报销的部分算不算免赔额\"， 留文字记录 。 M5 · 续保条款（最大的隐藏风险）—— 监管有明文禁令 ⚠️ 2021 年起，监管机构对\"短险长做\"下了硬禁令。 见《中国银保监会办公厅关于规范短期健康保险业务有关问题的通知》（银保监办发〔2021〕7 号）。 监管原文（第 3 条） 保险公司开发的短期健康保险产品中包含续保责任的，应当在保险条款中 明确表述为\"不保证续保\"条款 。不保证续保条款中至少应当包含以下内容： 本产品保险期间为一年（或不超过一年）。保险期间届满，投保人需要重新向保险公司申请投保本产品，并经保险人同意，交纳保险费，获得新的保险合同。 保险公司不得在短期健康保险产品条款、宣传材料中使用 \"自动续保\"\"承诺续保\"\"终身限额\" 等易与长期健康保险混淆的词句。 看到这些词，就是违规（可举报 + 可主张按页面承诺履行） 页面/条款表述 判断 \"自动续保\"\"承诺续保\"\"终身限额\" ❌ 明令禁止 \"可续保至 100 岁\"\"续保时最高年龄可至 XX 周岁\" ❌ 易混淆，禁止 \"我们不会因为被保险人在首次投保后的健康状况变化而拒绝您的重新投保申请\" ❌ 变相承诺续保，禁止 \"不保证续保\" + \"期满需重新申请投保，经保险人同意\" ✅ 合规 \" 保证续保 20 年\" ✅ 长期健康险，不受本条限制 三种续保形态 形态 含义 风险 保证续保 X 年 在保证续保期间内，保险公司 必须 按约定费率和条款续保，不因健康变化或理赔而拒续 最稳。到期后仍需重新投保 非保证续保 （\"不因健康变化拒绝续保\"之类表述） 表述模糊， 产品停售则可拒续 ⚠️ 高风险 承诺续保至 X 岁 常见于宣传页 须有 书面 证据；且若属短期健康险，该表述本身 违规 ⚠️ 关键 ：真正值钱的不是\"保额 400 万\"（第 5 条甚至禁止设定严重背离理赔经验的虚高保额），而是\" 保证续保 20 年 \"这七个字。 破解路径 1. 看条款中\" 保证续保 \"四字是否明确出现，以及保证期间。 2. 宣传页面有\"可续保至 100 岁\"\"自动续保\"等表述的， 保存页面快照 → ① 销售误导，主张按页面承诺履行；② 向 12378 举报违规宣传。 3. 续保时保险人 要求重新健康告知或加费 的，看是否违反保证续保条款。 4. 产品停售 ：依第 10 条，保险公司须披露停售原因与时间、为已购用户在保险期间内继续提供保障、 期满时提供转保建议 ；主动停售须 至少提前 30 日 披露。 没做到的，既是监管违规，也是主张损失的事实基础。 另外两条被低估的武器（同通知第 8、9 条） 投保须知书 ：销售短期健康险时，保险公司 应当向消费者提供\"短期健康保险产品投保须知书\" ，并重点提示 9 项内容（如实告知后果、保险责任与除外责任、保险期间、保险金额、免赔额、赔付比例、等待期、投保年龄与保费关联性等）。→ 向保险人索要这份文件，核对是否给过你、9 项是否齐全。 缺失 = 未尽提示义务的证据。 第 9 条 ： \"健康告知信息的设定不得出现有违一般医学常识等情形\" → 这是攻击 概括性询问 的 监管依据 ，与司法解释二 §6② 并用。同时该条明令 \"严禁保险公司通过设定产品拒赔率等考核指标\" 影响正常理赔诉求——怀疑理赔员因考核拒赔的，可在投诉中要求监管核查其考核指标。 完整条文见L4 法条库/03 健康险监管规范。 M6 · 责任边界：特药、质子重离子、院外购药、CAR T ⚠️ 这类争议的本质是\"责任范围\"，不是\"免责条款\" ——保险人主张\"这本来就不在保障范围内\"，而不是\"我们免责\"。所以 武器一（提示说明义务）在这里作用有限，重点在投保前看清 。 项目 常见坑 投保前看什么 院外特药 / 靶向药 医院开不出药，需院外 DTP 药房购买 → 不在\"住院医疗费用\"内 是否含\" 院外特定药品费用 \"责任、药品清单范围、是否需指定药店 质子重离子 部分产品不含，或限定\"上海质子重离子医院\" 是否含、指定机构、赔付比例（常见 100% 或 60%） CAR T / 免疫治疗 单价百万级，多数百万医疗险不含或有限额 是否列入特定药品清单、有无单独限额 器官移植 有的只报\"手术费\"不报\"器官源费用\" 责任表述与除外项 门诊手术 / 日间病房 不住院则不属于\"住院医疗\" 是否含\"门诊手术\"\"日间手术\"责任 中医 / 康复 / 理疗 多被除外 除外清单 事后救济 ：若 销售页面明确宣传 包含上述责任、而条款未包含 → 销售误导 + 页面快照作为证据；争议时主张以 对消费者有利的表述 为准（§30 / 解释二 §14）。 M7 · 就诊医院与紧急就医 规则 ： 解释三 §20 —— 保险人以被保险人未在保险合同约定的医疗服务机构接受治疗为由拒绝给付保险金的，人民法院应予支持， 但被保险人因情况紧急必须立即就医的除外 。 实务要点 1. 常见约定：\" 中国大陆境内二级及以上公立医院 普通部\"（不含特需/VIP/国际部）。 2. 危急情况就近就医的，注意固定 急诊记录 、时间链条、转院记录。 3. 条款要求\" 公立 \"而实际在医保定点民营医院就诊的 → 主张\"公立\"限定属加重责任、且未尽明确说明；并结合是否符合\"紧急\"情形。 4. 特需部/VIP 部：中端医疗险才含，百万医疗险通常不含。 M8 · 健康告知与一年期产品的特殊性 ⚠️ 一年期医疗险的特殊风险 ：合同 每年重新订立 ，\"两年不可抗辩\"的实践意义被大幅削弱——保险人可以在 续保时 重新核保、拒保或除外责任。 应对 1. 优先选 保证续保 产品，把风险锁死。 2. 如实告知依然是第一原则——隐瞒告知的代价比重疾险更高（一年期产品下，几乎不存在\"熬两年就安全\"）。 3. 投保时逐条截屏健康告知页。 M9 · 理赔核定、举证与补充材料 情形复杂的 30 日内 核定（§23①），自 初次收到索赔请求及资料之日 起算（解释二 §15）。 索赔方只需提供\" 其所能提供的 \"证明和资料（§22①）。 保险人要求补充材料应 及时一次性 通知（§22②）——反复补材料制造拖延的，可主张违反法定程序。 未及时赔付的， 应赔偿因此受到的损失 （§23③）。 实战 ：把每一次补充材料的要求 书面化 （要求出具书面清单），形成时间轴。这既是抗辩拖延的证据，也是主张迟延损失的依据。 M10 · 既往症与\"示范视频\"（A 级判例） \" 提交的投保示范视频并非张某甲父亲代投保时的视频轨迹 ，仅凭投保单上'张某甲'的签名字样尚不足以证明……已通过人工、网页、音频、视频等任何形式说明免责条款的内容及法律后果\" ——广州中院 (2025)粤01民终24935号（百万医疗，一审说理，二审维持） 打法 ：要求保险人提供 本次投保的可回溯记录 。互联网保险可回溯是监管硬要求，拿不出来就是没做。 M11 · ⚠️ 反面：医疗险适用损失补偿原则，医保已付部分要扣除 同案（粤01民终24935号）：法院认定百万医疗属 补偿性保险合同 ，医保统筹基金已支付的 40,947.45 元须扣除 → 5.2 万诉求扣完只剩 1,231.35 元。 且一般医疗保额未赔满前， 不能跳到\"恶性肿瘤——重度医疗\"责任项下重复主张 。 教训 ：赢了免责条款也可能输在金额上。投保前看清\"是否限社保范围内\"\"免赔额多少\"\"各项责任是否共用保额\"。 3. 投保前 checklist [ ] 保证续保 几个字是否在条款中明确出现？保证多少年？ [ ] 免赔额： 多少 ？社保报销部分 是否计入 ？是否多年共享？ [ ] 给付比例：用社保结算后多少？未用社保多少？ [ ] 是否含 院外特药 ？药品清单范围？是否指定药店？ [ ] 是否含 质子重离子 ？指定机构？ [ ] 是否含门诊手术 / 日间病房 / 住院前后门急诊（天数）？ [ ] 既往症定义原文（要求\"明确诊断 + 未治愈\"？） [ ] 就诊医院要求（二级及以上？公立？含不含特需？） [ ] 除外责任逐条读过（特に：生育、牙科、整形、体检、康复、中医、艾滋病、战争、高风险运动） [ ] 职业类别是否匹配（部分医疗险对高危职业拒保或除外） [ ] 是否有 住院垫付 / 就医绿通 （实用性高于保额数字） [ ] 健康告知页 逐条截屏 [ ] 销售页面 整页快照 4. 出险后动作清单 1. 用社保身份就诊并结算 （避免社保罚则）。 2. 核对医院等级 是否符合条款；紧急就医的保留急诊记录。 3. 固定全套资料：门急诊病历、住院病案（入院记录、手术记录、出院小结）、诊断证明（盖章）、费用明细清单、发票原件、医保结算单。 4. 院外购药 ：保留处方、药店发票、药品清单；确认是否在特药清单内。 5. 书面提交理赔申请，索取 书面 核定结果。 6. 保险人反复要求补材料的，要求其 一次性书面列明 。 7. 超 30 日未核定的，书面催告并保留凭证。 5. 四个常见误解 误解 正解 \"买了两份百万医疗能赔两次\" 费用补偿型 不能重复获利 ；定额津贴型可以 \"保额 400 万很够用\" 一年实际能用到的上限取决于 责任范围 ，保额数字基本是营销 \"续保是自动的\" 只有 保证续保 产品才是；非保证续保产品停售或被保险人健康恶化都可能不续 \"超过医保目录就不报\" 解释三 §19：保险人只能拒赔\" 超过同类医疗费用标准 \"的部分，不能笼统以\"超出医保范围\"拒赔 6. 与其他页面的关系 通用打法 ：见L0 打法层/01 八把通用武器 完整流程与时效 ：见L0 打法层/02 维权操作全流程 专题案例 ：见L2 案例库/专题 提示说明义务与电子投保 广东案例 ：见L2 案例库/广东案例 重疾医疗 监管规范 ：见L4 法条库/03 健康险监管规范 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L1-险种层/03-意外险", "group": "2 · 险种深挖", "groupKey": "L1-险种层", "title": "意外险 · 纠纷全解", "order": 2, "file": "03-意外险.md", "html": "<h1 id=\"s0\">意外险 · 纠纷全解</h1>\n<blockquote><strong>本页自包含</strong>——读这一页不需要翻其他文件。<br><br><strong>一句话定位</strong>：意外险只赔\"<strong>外来的、突发的、非本意的、非疾病的</strong>\"四个要件同时满足的伤害。90% 的纠纷都在这四个词上，尤其最后一个：<strong>\"非疾病的\"</strong>。</blockquote>\n<hr>\n<h2 id=\"s1\">0. 速查卡片（本页最重要的 12 条）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>要点</th><th>依据</th></tr></thead><tbody>\n<tr><td>1</td><td>\"意外\"四要件：<strong>外来的、突发的、非本意的、非疾病的</strong>，缺一不可</td><td>条款通行定义</td></tr>\n<tr><td>2</td><td><strong>猝死</strong>通常<strong>不属</strong>意外（多因疾病），除非产品<strong>单独附加猝死责任</strong></td><td>条款约定</td></tr>\n<tr><td>3</td><td><strong>伤残按等级比例赔付</strong>属\"比例赔付\"条款 → <strong>必须提示说明</strong>，否则不生效</td><td>解释二 §9</td></tr>\n<tr><td>4</td><td><strong>伤残评定标准</strong>的选择（行标 vs 其他）实质影响赔付额 → 同样需提示说明</td><td>解释二 §9</td></tr>\n<tr><td>5</td><td>多因一果时适用<strong>近因原则</strong>：找\"最主要、最有效、最直接\"的原因</td><td>判例规则</td></tr>\n<tr><td>6</td><td>承保风险与免责风险<strong>难以确定</strong>的，法院可<strong>按比例</strong>支持</td><td>解释三 §25</td></tr>\n<tr><td>7</td><td>保险人以自杀拒赔的，<strong>由保险人承担举证责任</strong></td><td>解释三 §21</td></tr>\n<tr><td>8</td><td>\"被保险人<strong>故意犯罪</strong>\"的认定，以<strong>刑事司法机关生效文书</strong>为依据</td><td>解释三 §22</td></tr>\n<tr><td>9</td><td>保险人主张故意犯罪免责的，还须证明<strong>死亡伤残结果与犯罪行为有因果关系</strong></td><td>解释三 §23</td></tr>\n<tr><td>10</td><td><strong>职业类别</strong>不实是意外险高频拒赔理由，看保险人是否询问、是否提示</td><td>保险法 §16</td></tr>\n<tr><td>11</td><td><strong>高风险运动</strong>免责范围不明的 → §30 不利解释</td></tr>\n<tr><td>12</td><td>诉讼时效 <strong>2 年</strong>（非寿险），自知道或应当知道保险事故发生之日起算</td><td>保险法 §26</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">1. 险种地图</h2>\n<pre><code>\n意外险\n\n├── 意外身故保险金（100% 保额）\n\n├── 意外伤残保险金（按伤残等级 1-10 级，比例 100%→10%）\n\n├── 意外医疗（费用补偿型，受损失补偿原则约束）\n\n├── 意外住院津贴（定额给付型，可叠加）\n\n├── 猝死责任（附加，非默认！）\n\n└── 特定场景责任（交通意外、航空、公共交通、自驾、骨折等）\n\n</code></pre>\n<p><strong>关键认知</strong>：意外险的核心不是\"死了赔多少\"，而是\"<strong>什么算意外</strong>\"。保额 100 万听起来很多，但伤残 10 级只赔 10 万。</p>\n<p><strong>比喻</strong>：意外险像一把四道锁的保险箱——外来的、突发的、非本意的、非疾病的，四把钥匙全对上才开。而\"非疾病的\"这把钥匙，往往卡在你意想不到的地方：摔倒诱发心梗、游泳时心脏病发作、高温中暑。</p>\n<hr>\n<h2 id=\"s3\">2. 争点逐解</h2>\n<h3 id=\"s4\">A1 · 四要件：什么算\"意外\"</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>要件</th><th>含义</th><th>典型争议</th></tr></thead><tbody>\n<tr><td><strong>外来的</strong></td><td>来自身体外部的因素</td><td>自身疾病导致的伤害（如癫痫发作摔倒）不是外来</td></tr>\n<tr><td><strong>突发的</strong></td><td>突然发生、来不及预防</td><td>长期重复劳动造成的职业病、慢性损伤不是突发</td></tr>\n<tr><td><strong>非本意的</strong></td><td>非被保险人故意所致</td><td>自伤、自杀、斗殴中故意受伤</td></tr>\n<tr><td><strong>非疾病的</strong></td><td>非由自身疾病引起</td><td><span class=\"warn\">!</span> 最高频争议：疾病与意外共同作用</td></tr>\n</tbody></table></div>\n<p><strong>实务判断路径</strong></p>\n<pre><code>\n发生了伤害\n\n   ↓\n\n是纯粹外来事件造成的？（如车祸、坠落、砸伤）\n\n   ├─ 是 → 一般构成意外（再看是否有免责情形）\n\n   └─ 否 → 是否存在自身疾病/体质因素参与？\n\n          ├─ 无 → 构成意外\n\n          └─ 有 → 进入「近因原则」分析（见 A3）\n\n</code></pre>\n<hr>\n<h3 id=\"s5\">A2 · 猝死到底赔不赔</h3>\n<p><strong>规则</strong>：<strong>多数意外险的默认责任不含猝死。</strong> 因为猝死在医学上通常由<strong>自身疾病</strong>（心源性为主）引起，不满足\"非疾病的\"要件。</p>\n<p><strong>三种处理</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>情形</th><th>结果</th></tr></thead><tbody>\n<tr><td>产品<strong>未附加猝死责任</strong></td><td>通常不予赔付（但可尝试 A3 近因路径）</td></tr>\n<tr><td>产品<strong>附加猝死责任</strong></td><td>按约定赔付，注意\"<strong>发病后 X 小时内身故</strong>\"的时间限定（常见 6 小时或 24 小时）</td></tr>\n<tr><td>猝死<strong>由外部事件诱发</strong>（如触电、溺水、中毒、外伤后）</td><td>可主张属意外</td></tr>\n</tbody></table></div>\n<p><strong>破解路径</strong></p>\n<ol>\n<li><strong>查条款</strong>：有没有\"猝死\"两个字，定义是什么，有无时间限制。</li>\n<li><strong>查死因</strong>：有尸检/抢救记录的，看能否确定外部因素参与。</li>\n<li><strong>近因抗辩</strong>：若存在明确的外部诱因（如高温作业中暑、剧烈运动诱发），主张<strong>近因是外部事件</strong>而非自身疾病。</li>\n<li><strong>举证</strong>：死因不明且<strong>未做尸检</strong>的，主张保险人未尽调查义务、应承担举证不能后果（保险人主张免责的，对免责事由负举证责任）。</li>\n</ol>\n<p><strong>比喻</strong>：猝死拒赔的本质是——保险公司说\"这是你的身体自己出了问题\"，你说\"是外面的事把它逼出了问题\"。<strong>谁对起决定作用的那个原因负举证责任，是胜负手。</strong></p>\n<hr>\n<h3 id=\"s6\">A3 · 近因原则与\"多因一果\"</h3>\n<p><strong>规则</strong>：近因 ≠ 时间上最接近的原因，而是<strong>最主要、最有效、最直接</strong>的原因。</p>\n<p><strong>三种典型结构</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>结构</th><th>示例</th><th>处理</th></tr></thead><tbody>\n<tr><td><strong>单一原因</strong></td><td>车祸致骨折</td><td>属承保范围则赔</td></tr>\n<tr><td><strong>链条式</strong>（A→B→C）</td><td>摔倒 → 诱发心梗 → 死亡</td><td>链条未中断的，一般认定<strong>前因</strong>（摔倒）为近因</td></tr>\n<tr><td><strong>并存独立</strong></td><td>既有旧伤又有新伤</td><td>能区分的按比例；不能区分的见下</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 重要武器：司法解释（三）第 25 条</strong></p>\n<blockquote>被保险人的损失系由承保事故或者非承保事故、免责事由造成<strong>难以确定</strong>的，当事人请求保险人给付保险金的，人民法院<strong>可以按照相应比例</strong>予以支持。</blockquote>\n<p>这是\"<strong>全赔 or 不赔</strong>\"之外的第三条路——<strong>按比例判</strong>。在死因鉴定无法明确、或疾病与意外难分主次时，这是非常实用的请求方式。</p>\n<p><strong>实战动作</strong></p>\n<ol>\n<li><strong>争取司法鉴定</strong>（死因鉴定、伤病关系鉴定、参与度鉴定）。把\"谁是近因\"从保险公司的一句话，变成一个鉴定结论。</li>\n<li>保险人<strong>不申请鉴定</strong>的，主张其承担举证不能的不利后果。</li>\n<li>鉴定结论给出\"参与度\"（如外力参与度 40%）时，正是 §25 的适用场景。</li>\n</ol>\n<hr>\n<h3 id=\"s7\">A4 · 伤残评定标准之争（最高频的\"暗亏\"）</h3>\n<p><strong>场景</strong>：买了 100 万意外险，伤残后只赔 20 万。</p>\n<p><strong>两套标准的差别</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>标准</th><th>适用</th><th>特点</th></tr></thead><tbody>\n<tr><td>《<strong>人身保险伤残评定标准及代码</strong>》（保险行业标准，中保协发〔2013〕88 号）</td><td>意外险合同通常约定</td><td>分 10 级 281 项，赔付比例 100%→10%</td></tr>\n<tr><td>《<strong>人体损伤致残程度分级</strong>》（最高法、最高检、公安部、国安部、司法部 2016 年联合发布）</td><td>人身损害赔偿案件</td><td>分 10 级，但<strong>分级门槛与项目不同</strong></td></tr>\n</tbody></table></div>\n<p><strong>关键</strong>：同一处伤残，用行标可能评 10 级（赔 10%），用《分级》可能评 9 级甚至更高。差一级就是 10 万。</p>\n<p><strong>破解路径</strong></p>\n<ol>\n<li><strong>比例赔付属免责条款</strong>：解释二 §9 明确列举\"比例赔付或者给付\"→ 保险人必须<strong>提示 + 明确说明</strong>，否则不生效。这是最有力的攻击点。</li>\n<li><strong>标准选择本身</strong>减轻保险人责任的，同样需提示说明。</li>\n<li><strong>鉴定机构的选择</strong>：合同中常约定\"由双方认可的司法鉴定机构\"或指定机构。对鉴定结论有异议的，可申请<strong>重新鉴定</strong>。</li>\n<li><strong>评定时机</strong>：条款通常约定\"事故发生之日起 <strong>180 日</strong>内\"或\"治疗结束后\"。过早评定会低估伤残程度——<strong>注意不要被催着早评</strong>。</li>\n</ol>\n<p><strong>证据</strong>：完整病历、影像资料、康复记录、鉴定意见书、条款中伤残评定标准全文（<strong>投保时是否向你展示过？</strong>）。</p>\n<p><strong>比喻</strong>：你买了\"按损坏程度赔\"的手机险，但合同规定\"损坏程度由厂家的尺子量\"。而市面上还有一把更宽的尺子。<strong>厂家的尺子没在卖你的时候拿出来给你看过，就不能用。</strong></p>\n<hr>\n<h3 id=\"s8\">A5 · 职业类别不实</h3>\n<p><strong>规则</strong>：意外险按职业风险分为 1-6 类（有的 1-4 类），高风险职业保费高或拒保。</p>\n<p><strong>争点</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>情形</th><th>处理</th></tr></thead><tbody>\n<tr><td>投保时报低了类别</td><td>看保险人是否<strong>具体询问</strong>职业（工种、工作内容），还是只问行业</td></tr>\n<tr><td>投保后<strong>换了工作</strong></td><td>多属\"危险程度显著增加\"，参照保险法 §52 与解释四 §4（主要适用于财产险，人身意外险中看条款约定）</td></tr>\n<tr><td>出险时从事的活动<strong>超出</strong>申报职业范围</td><td>看条款是否将\"从事高风险职业期间\"列为免责</td></tr>\n<tr><td>职业分类表本身模糊</td><td>该职业属于哪一类存在歧义 → §30 不利解释</td></tr>\n</tbody></table></div>\n<p><strong>关键</strong>：职业类别条款若实质限制赔付（如\"从事 5 类及以上职业期间出险，按 50% 赔付\"），属<strong>比例给付条款</strong> → 需提示说明。</p>\n<p><strong>证据</strong>：投保时的职业申报页面截屏、劳动合同、社保缴纳记录、单位出具的工作内容证明、事故时的现场记录。</p>\n<hr>\n<h3 id=\"s9\">A6 · 高风险运动免责</h3>\n<p><strong>典型条款</strong>：被保险人从事<strong>潜水、滑水、滑雪、攀岩、探险、武术、摔跤、特技、赛马、赛车</strong>等高风险运动期间，保险人不承担责任。</p>\n<p><strong>破解路径</strong></p>\n<ol>\n<li><strong>范围不明 → §30</strong>：什么叫\"潜水\"？浮潜算不算？\"探险\"的定义是什么？条款未界定、无清单的，作有利于被保险人的解释。</li>\n<li><strong>\"许可经营项目\"限定</strong>：有的条款限定为\"未经许可经营的\"\"非营业性的\"\"竞技性的\"。在<strong>正规经营场所</strong>（如持证滑雪场、有资质的潜水机构）参与的项目，可主张不属于免责范围。</li>\n<li><strong>提示说明义务</strong>：该免责条款须提示 + 明确说明（§17）。</li>\n<li><strong>因果关系</strong>：即使从事了免责活动，若伤亡由<strong>与该活动无关</strong>的原因造成，主张不应适用免责（如滑雪场缆车事故、更衣室滑倒）。</li>\n</ol>\n<hr>\n<h3 id=\"s10\">A7 · 意外医疗的补偿原则</h3>\n<ul>\n<li>意外医疗是<strong>费用补偿型</strong>，适用损失补偿原则，<strong>不能重复获利</strong>。</li>\n<li>已在医保、其他商业险、第三人处获赔的部分不能重复索赔。</li>\n<li><strong>意外住院津贴</strong>是定额给付，可以叠加。</li>\n<li>免赔额、给付比例同样属解释二 §9 的\"免赔额、免赔率、比例赔付\"→ 需提示说明。</li>\n</ul>\n<hr>\n<h3 id=\"s11\">A8 · 免责条款的常规战场</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>免责事由</th><th>要点</th></tr></thead><tbody>\n<tr><td><strong>自杀 / 自伤</strong></td><td>保险人以自杀拒赔的，<strong>由保险人举证</strong>（解释三 §21）。两年后自杀的寿险仍需赔付（保险法 §44）——但意外险不适用该规则</td></tr>\n<tr><td><strong>故意犯罪</strong></td><td>认定须以<strong>刑事侦查、检察、审判机关的生效文书或结论性意见</strong>为依据（解释三 §22）；且须证明<strong>死亡伤残结果与犯罪行为存在因果关系</strong>（解释三 §23）</td></tr>\n<tr><td><strong>醉酒 / 吸毒</strong></td><td>属法律禁止性规定情形的，保险人<strong>提示后</strong>即可生效（解释二 §10），但仍须证明<strong>已提示</strong>。注意：须有血液酒精检测等客观证据</td></tr>\n<tr><td><strong>无合法有效驾驶证 / 车辆未年检</strong></td><td>车险高频，意外险中若涉及驾驶亦需注意；属禁止性规定的，提示即生效</td></tr>\n<tr><td><strong>战争、核、恐怖活动</strong></td><td>一般无争议</td></tr>\n<tr><td><strong>妊娠、分娩、整容、牙科</strong></td><td>看是否属免责范围</td></tr>\n</tbody></table></div>\n<hr>\n<h3 id=\"s12\">A9 · 保险人的举证责任清单</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>待证事实</th><th>谁举证</th></tr></thead><tbody>\n<tr><td>保险事故发生（意外伤害的存在）</td><td>索赔方（以\"所能提供\"为限，§22）</td></tr>\n<tr><td><strong>存在免责事由</strong>（如自杀、犯罪、醉酒）</td><td><strong>保险人</strong></td></tr>\n<tr><td><strong>自杀</strong></td><td><strong>保险人</strong>（解释三 §21）</td></tr>\n<tr><td>已履行提示和明确说明义务</td><td><strong>保险人</strong>（解释二 §13①）</td></tr>\n<tr><td>健康/职业告知的询问范围与内容</td><td><strong>保险人</strong>（解释二 §6①）</td></tr>\n<tr><td>不符合承保条件</td><td><strong>保险人</strong>（解释二 §4②）</td></tr>\n</tbody></table></div>\n<p><strong>实战</strong>：答辩阶段第一件事就是<strong>逐项要求保险人举证</strong>。很多时候保险人只甩一句\"属于免责范围\"，拿不出证据。</p>\n<hr>\n<h3 id=\"s13\">A10 · 无证驾驶免责：电子签名不够，且人身意外险不适用损失补偿</h3>\n<blockquote>\"<strong>仅提交带有周某丁电子签名的投保单</strong>，但无任何证据证明投保人签名前页面完整展示保险条款、无弹窗单独提示免责内容……<strong>电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务</strong>\"<br><br>\"案涉意外伤害意外保险属于人身保险，<strong>原则上不适用'损害填补'原则</strong>，交通事故的侵权人是否已赔偿……医疗费，不影响……应承担的赔付意外伤害医疗费保险金的责任\"<br><br>\"对于保险合同约定的<strong>免赔3天属于免责条款</strong>，……免责条款不生效，……应按照42天计算意外伤害住院津贴\"<br>——湛江中院 (2026)粤08民终2074号</blockquote>\n<p><strong>三条一次到手</strong>：① 电子签名不够；② 侵权人赔过了意外医疗照样赔；③ <strong>免赔天数也是免责条款</strong>。</p>\n<h3 id=\"s14\">A11 · 平台自动投保 = 纯格式条款；\"必须尸检\"也是免责条款</h3>\n<blockquote>\"投保流程中<strong>骑手接单后系统自动扣收保费并生成保单</strong>，并无证据显示投保人及被保险人对合同条款有协商或修改的权利……<strong>符合格式条款的特征</strong>。某深圳分公司主张……经过合意磋商做出的个性化约定，但未能提供证据证明……<strong>不予采信</strong>\"<br><br>\"特别约定的<strong>尸检义务及相关责任条款，属于减免保险人责任的格式条款</strong>，……应当作出<strong>有利于被保险人的解释</strong>\"<br><br>\"其猝死处于工作时间、工作岗位<strong>具有高度盖然性</strong>\"<br>——深圳中院 (2026)粤03民终2970号（外卖骑手猝死，判赔 60 万）</blockquote>\n<p><strong>要点</strong>：① 保险人\"这是协商达成的个性化约定\"抗辩，在自动投保场景直接无效；② <strong>\"必须尸检\"\"须在工作岗位\"这类义务性/限定性规定也是免责条款</strong>；③ 事实认定可用<strong>高度盖然性</strong>（最后接单 15:45、急救通知 16:30 → 认定工作时间）。</p>\n<h3 id=\"s15\">A12 · 免责内容本身违反公平原则（新就业形态）</h3>\n<blockquote>\"案涉免责条款<strong>将已从人社部门获得职业伤害保障作为免除自身赔付责任的情形，不当排除了新就业形态劳动者的合法权利，有违公平原则</strong>\"<br>——阳江中院 (2026)粤17民终14号</blockquote>\n<p><strong>双保险</strong>：① 没提示说明 → 不生效；② 即使提示了，内容违反公平 → 再打保险法 §19 / 民法典 §497。 另：<strong>向平台、经纪公司发邮件告知 ≠ 向被保险人（骑手）说明</strong>。</p>\n<h2 id=\"s16\">3. 投保前 checklist</h2>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>是否含猝死责任</strong>？定义（发病后几小时内身故）？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>意外医疗</strong>是否含？免赔额、给付比例、是否限社保目录</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>伤残评定标准</strong>是哪一套？比例表（1 级 100% → 10 级 10%）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否<strong>只保身故/伤残</strong>而无医疗（很多低价产品只有身故伤残）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 职业类别要求与自己的实际职业是否匹配</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 高风险运动免责清单</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否有<strong>特定交通意外额外赔付</strong>（航空、公共交通、自驾）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 就诊医院要求</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 生效时间（有的 T+3 日或 T+7 日生效）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保险期间（一年期？长期？保证续保？）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 职业变更是否需要通知保险人</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 健康告知页与投保页面<strong>截屏</strong></div>\n<hr>\n<h2 id=\"s17\">4. 出险后动作清单</h2>\n<ol>\n<li><strong>立即报案</strong>（注意条款约定的通知期限，通常 10 日内）。</li>\n<li><strong>固定现场证据</strong>：事故现场照片/视频、目击证人联系方式、报警记录与笔录、监控录像（<strong>尽早申请调取，监控通常只保留 30 天</strong>）。</li>\n<li><strong>医疗记录</strong>：门急诊病历、住院病案、诊断证明。注意<strong>医生对受伤原因的记录</strong>（\"高处坠落\"\"车祸伤\"等），这直接决定能否证明\"外来的\"。</li>\n<li><strong>死亡案件</strong>：争取尸检与死因鉴定；家属拒绝尸检的，说明理由并保留沟通记录。</li>\n<li><strong>伤残评定</strong>：不要过早评定。按条款约定的时点（通常 180 日后或治疗终结后）评，选择有资质的司法鉴定机构；对结论不服的申请重新鉴定。</li>\n<li>书面提交理赔，索取<strong>书面</strong>拒赔/核定通知。</li>\n<li>保险人主张免责的，<strong>书面要求其说明依据条款与证据</strong>。</li>\n</ol>\n<hr>\n<h2 id=\"s18\">5. 四个常见误解</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody>\n<tr><td>\"意外险什么都保\"</td><td>只保四要件齐备的意外；疾病（含猝死）不保</td></tr>\n<tr><td>\"100 万保额就是赔 100 万\"</td><td>伤残按比例，10 级只赔 10%</td></tr>\n<tr><td>\"摔倒致死肯定是意外\"</td><td>若主要死因是自身疾病（如心梗），可能被认定非意外；但可走解释三 §25 按比例</td></tr>\n<tr><td>\"保险公司说不赔就没办法\"</td><td>免责事由由<strong>保险人举证</strong>；很多拒赔在举证环节就垮了</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s19\">6. 与其他页面的关系</h2>\n<ul>\n<li><strong>通用打法</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a>（武器三 隐性免责、武器四 不利解释、武器七 近因原则）</li>\n<li><strong>流程与时效</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>广东案例</strong>：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E6%84%8F%E5%A4%96%E5%AF%BF%E9%99%A9%E4%B8%8E%E4%BA%92%E8%81%94%E7%BD%91%E6%8A%95%E4%BF%9D\">《意外险 / 寿险 / 互联网平台投保 · 案例库》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "0. 速查卡片（本页最重要的 12 条）"}, {"id": "s2", "lv": 2, "t": "1. 险种地图"}, {"id": "s3", "lv": 2, "t": "2. 争点逐解"}, {"id": "s4", "lv": 3, "t": "A1 · 四要件：什么算\"意外\""}, {"id": "s5", "lv": 3, "t": "A2 · 猝死到底赔不赔"}, {"id": "s6", "lv": 3, "t": "A3 · 近因原则与\"多因一果\""}, {"id": "s7", "lv": 3, "t": "A4 · 伤残评定标准之争（最高频的\"暗亏\"）"}, {"id": "s8", "lv": 3, "t": "A5 · 职业类别不实"}, {"id": "s9", "lv": 3, "t": "A6 · 高风险运动免责"}, {"id": "s10", "lv": 3, "t": "A7 · 意外医疗的补偿原则"}, {"id": "s11", "lv": 3, "t": "A8 · 免责条款的常规战场"}, {"id": "s12", "lv": 3, "t": "A9 · 保险人的举证责任清单"}, {"id": "s13", "lv": 3, "t": "A10 · 无证驾驶免责：电子签名不够，且人身意外险不适用损失补偿"}, {"id": "s14", "lv": 3, "t": "A11 · 平台自动投保 = 纯格式条款；\"必须尸检\"也是免责条款"}, {"id": "s15", "lv": 3, "t": "A12 · 免责内容本身违反公平原则（新就业形态）"}, {"id": "s16", "lv": 2, "t": "3. 投保前 checklist"}, {"id": "s17", "lv": 2, "t": "4. 出险后动作清单"}, {"id": "s18", "lv": 2, "t": "5. 四个常见误解"}, {"id": "s19", "lv": 2, "t": "6. 与其他页面的关系"}], "text": "意外险 · 纠纷全解 本页自包含 ——读这一页不需要翻其他文件。 一句话定位 ：意外险只赔\" 外来的、突发的、非本意的、非疾病的 \"四个要件同时满足的伤害。90% 的纠纷都在这四个词上，尤其最后一个： \"非疾病的\" 。 0. 速查卡片（本页最重要的 12 条） 要点 依据 1 \"意外\"四要件： 外来的、突发的、非本意的、非疾病的 ，缺一不可 条款通行定义 2 猝死 通常 不属 意外（多因疾病），除非产品 单独附加猝死责任 条款约定 3 伤残按等级比例赔付 属\"比例赔付\"条款 → 必须提示说明 ，否则不生效 解释二 §9 4 伤残评定标准 的选择（行标 vs 其他）实质影响赔付额 → 同样需提示说明 解释二 §9 5 多因一果时适用 近因原则 ：找\"最主要、最有效、最直接\"的原因 判例规则 6 承保风险与免责风险 难以确定 的，法院可 按比例 支持 解释三 §25 7 保险人以自杀拒赔的， 由保险人承担举证责任 解释三 §21 8 \"被保险人 故意犯罪 \"的认定，以 刑事司法机关生效文书 为依据 解释三 §22 9 保险人主张故意犯罪免责的，还须证明 死亡伤残结果与犯罪行为有因果关系 解释三 §23 10 职业类别 不实是意外险高频拒赔理由，看保险人是否询问、是否提示 保险法 §16 11 高风险运动 免责范围不明的 → §30 不利解释 12 诉讼时效 2 年 （非寿险），自知道或应当知道保险事故发生之日起算 保险法 §26 1. 险种地图 关键认知 ：意外险的核心不是\"死了赔多少\"，而是\" 什么算意外 \"。保额 100 万听起来很多，但伤残 10 级只赔 10 万。 比喻 ：意外险像一把四道锁的保险箱——外来的、突发的、非本意的、非疾病的，四把钥匙全对上才开。而\"非疾病的\"这把钥匙，往往卡在你意想不到的地方：摔倒诱发心梗、游泳时心脏病发作、高温中暑。 2. 争点逐解 A1 · 四要件：什么算\"意外\" 要件 含义 典型争议 外来的 来自身体外部的因素 自身疾病导致的伤害（如癫痫发作摔倒）不是外来 突发的 突然发生、来不及预防 长期重复劳动造成的职业病、慢性损伤不是突发 非本意的 非被保险人故意所致 自伤、自杀、斗殴中故意受伤 非疾病的 非由自身疾病引起 ⚠️ 最高频争议：疾病与意外共同作用 实务判断路径 A2 · 猝死到底赔不赔 规则 ： 多数意外险的默认责任不含猝死。 因为猝死在医学上通常由 自身疾病 （心源性为主）引起，不满足\"非疾病的\"要件。 三种处理 情形 结果 产品 未附加猝死责任 通常不予赔付（但可尝试 A3 近因路径） 产品 附加猝死责任 按约定赔付，注意\" 发病后 X 小时内身故 \"的时间限定（常见 6 小时或 24 小时） 猝死 由外部事件诱发 （如触电、溺水、中毒、外伤后） 可主张属意外 破解路径 1. 查条款 ：有没有\"猝死\"两个字，定义是什么，有无时间限制。 2. 查死因 ：有尸检/抢救记录的，看能否确定外部因素参与。 3. 近因抗辩 ：若存在明确的外部诱因（如高温作业中暑、剧烈运动诱发），主张 近因是外部事件 而非自身疾病。 4. 举证 ：死因不明且 未做尸检 的，主张保险人未尽调查义务、应承担举证不能后果（保险人主张免责的，对免责事由负举证责任）。 比喻 ：猝死拒赔的本质是——保险公司说\"这是你的身体自己出了问题\"，你说\"是外面的事把它逼出了问题\"。 谁对起决定作用的那个原因负举证责任，是胜负手。 A3 · 近因原则与\"多因一果\" 规则 ：近因 ≠ 时间上最接近的原因，而是 最主要、最有效、最直接 的原因。 三种典型结构 结构 示例 处理 单一原因 车祸致骨折 属承保范围则赔 链条式 （A→B→C） 摔倒 → 诱发心梗 → 死亡 链条未中断的，一般认定 前因 （摔倒）为近因 并存独立 既有旧伤又有新伤 能区分的按比例；不能区分的见下 ⚠️ 重要武器：司法解释（三）第 25 条 被保险人的损失系由承保事故或者非承保事故、免责事由造成 难以确定 的，当事人请求保险人给付保险金的，人民法院 可以按照相应比例 予以支持。 这是\" 全赔 or 不赔 \"之外的第三条路—— 按比例判 。在死因鉴定无法明确、或疾病与意外难分主次时，这是非常实用的请求方式。 实战动作 1. 争取司法鉴定 （死因鉴定、伤病关系鉴定、参与度鉴定）。把\"谁是近因\"从保险公司的一句话，变成一个鉴定结论。 2. 保险人 不申请鉴定 的，主张其承担举证不能的不利后果。 3. 鉴定结论给出\"参与度\"（如外力参与度 40%）时，正是 §25 的适用场景。 A4 · 伤残评定标准之争（最高频的\"暗亏\"） 场景 ：买了 100 万意外险，伤残后只赔 20 万。 两套标准的差别 标准 适用 特点 《 人身保险伤残评定标准及代码 》（保险行业标准，中保协发〔2013〕88 号） 意外险合同通常约定 分 10 级 281 项，赔付比例 100%→10% 《 人体损伤致残程度分级 》（最高法、最高检、公安部、国安部、司法部 2016 年联合发布） 人身损害赔偿案件 分 10 级，但 分级门槛与项目不同 关键 ：同一处伤残，用行标可能评 10 级（赔 10%），用《分级》可能评 9 级甚至更高。差一级就是 10 万。 破解路径 1. 比例赔付属免责条款 ：解释二 §9 明确列举\"比例赔付或者给付\"→ 保险人必须 提示 + 明确说明 ，否则不生效。这是最有力的攻击点。 2. 标准选择本身 减轻保险人责任的，同样需提示说明。 3. 鉴定机构的选择 ：合同中常约定\"由双方认可的司法鉴定机构\"或指定机构。对鉴定结论有异议的，可申请 重新鉴定 。 4. 评定时机 ：条款通常约定\"事故发生之日起 180 日 内\"或\"治疗结束后\"。过早评定会低估伤残程度—— 注意不要被催着早评 。 证据 ：完整病历、影像资料、康复记录、鉴定意见书、条款中伤残评定标准全文（ 投保时是否向你展示过？ ）。 比喻 ：你买了\"按损坏程度赔\"的手机险，但合同规定\"损坏程度由厂家的尺子量\"。而市面上还有一把更宽的尺子。 厂家的尺子没在卖你的时候拿出来给你看过，就不能用。 A5 · 职业类别不实 规则 ：意外险按职业风险分为 1 6 类（有的 1 4 类），高风险职业保费高或拒保。 争点 情形 处理 投保时报低了类别 看保险人是否 具体询问 职业（工种、工作内容），还是只问行业 投保后 换了工作 多属\"危险程度显著增加\"，参照保险法 §52 与解释四 §4（主要适用于财产险，人身意外险中看条款约定） 出险时从事的活动 超出 申报职业范围 看条款是否将\"从事高风险职业期间\"列为免责 职业分类表本身模糊 该职业属于哪一类存在歧义 → §30 不利解释 关键 ：职业类别条款若实质限制赔付（如\"从事 5 类及以上职业期间出险，按 50% 赔付\"），属 比例给付条款 → 需提示说明。 证据 ：投保时的职业申报页面截屏、劳动合同、社保缴纳记录、单位出具的工作内容证明、事故时的现场记录。 A6 · 高风险运动免责 典型条款 ：被保险人从事 潜水、滑水、滑雪、攀岩、探险、武术、摔跤、特技、赛马、赛车 等高风险运动期间，保险人不承担责任。 破解路径 1. 范围不明 → §30 ：什么叫\"潜水\"？浮潜算不算？\"探险\"的定义是什么？条款未界定、无清单的，作有利于被保险人的解释。 2. \"许可经营项目\"限定 ：有的条款限定为\"未经许可经营的\"\"非营业性的\"\"竞技性的\"。在 正规经营场所 （如持证滑雪场、有资质的潜水机构）参与的项目，可主张不属于免责范围。 3. 提示说明义务 ：该免责条款须提示 + 明确说明（§17）。 4. 因果关系 ：即使从事了免责活动，若伤亡由 与该活动无关 的原因造成，主张不应适用免责（如滑雪场缆车事故、更衣室滑倒）。 A7 · 意外医疗的补偿原则 意外医疗是 费用补偿型 ，适用损失补偿原则， 不能重复获利 。 已在医保、其他商业险、第三人处获赔的部分不能重复索赔。 意外住院津贴 是定额给付，可以叠加。 免赔额、给付比例同样属解释二 §9 的\"免赔额、免赔率、比例赔付\"→ 需提示说明。 A8 · 免责条款的常规战场 免责事由 要点 自杀 / 自伤 保险人以自杀拒赔的， 由保险人举证 （解释三 §21）。两年后自杀的寿险仍需赔付（保险法 §44）——但意外险不适用该规则 故意犯罪 认定须以 刑事侦查、检察、审判机关的生效文书或结论性意见 为依据（解释三 §22）；且须证明 死亡伤残结果与犯罪行为存在因果关系 （解释三 §23） 醉酒 / 吸毒 属法律禁止性规定情形的，保险人 提示后 即可生效（解释二 §10），但仍须证明 已提示 。注意：须有血液酒精检测等客观证据 无合法有效驾驶证 / 车辆未年检 车险高频，意外险中若涉及驾驶亦需注意；属禁止性规定的，提示即生效 战争、核、恐怖活动 一般无争议 妊娠、分娩、整容、牙科 看是否属免责范围 A9 · 保险人的举证责任清单 待证事实 谁举证 保险事故发生（意外伤害的存在） 索赔方（以\"所能提供\"为限，§22） 存在免责事由 （如自杀、犯罪、醉酒） 保险人 自杀 保险人 （解释三 §21） 已履行提示和明确说明义务 保险人 （解释二 §13①） 健康/职业告知的询问范围与内容 保险人 （解释二 §6①） 不符合承保条件 保险人 （解释二 §4②） 实战 ：答辩阶段第一件事就是 逐项要求保险人举证 。很多时候保险人只甩一句\"属于免责范围\"，拿不出证据。 A10 · 无证驾驶免责：电子签名不够，且人身意外险不适用损失补偿 \" 仅提交带有周某丁电子签名的投保单 ，但无任何证据证明投保人签名前页面完整展示保险条款、无弹窗单独提示免责内容…… 电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务 \" \"案涉意外伤害意外保险属于人身保险， 原则上不适用'损害填补'原则 ，交通事故的侵权人是否已赔偿……医疗费，不影响……应承担的赔付意外伤害医疗费保险金的责任\" \"对于保险合同约定的 免赔3天属于免责条款 ，……免责条款不生效，……应按照42天计算意外伤害住院津贴\" ——湛江中院 (2026)粤08民终2074号 三条一次到手 ：① 电子签名不够；② 侵权人赔过了意外医疗照样赔；③ 免赔天数也是免责条款 。 A11 · 平台自动投保 = 纯格式条款；\"必须尸检\"也是免责条款 \"投保流程中 骑手接单后系统自动扣收保费并生成保单 ，并无证据显示投保人及被保险人对合同条款有协商或修改的权利…… 符合格式条款的特征 。某深圳分公司主张……经过合意磋商做出的个性化约定，但未能提供证据证明…… 不予采信 \" \"特别约定的 尸检义务及相关责任条款，属于减免保险人责任的格式条款 ，……应当作出 有利于被保险人的解释 \" \"其猝死处于工作时间、工作岗位 具有高度盖然性 \" ——深圳中院 (2026)粤03民终2970号（外卖骑手猝死，判赔 60 万） 要点 ：① 保险人\"这是协商达成的个性化约定\"抗辩，在自动投保场景直接无效；② \"必须尸检\"\"须在工作岗位\"这类义务性/限定性规定也是免责条款 ；③ 事实认定可用 高度盖然性 （最后接单 15:45、急救通知 16:30 → 认定工作时间）。 A12 · 免责内容本身违反公平原则（新就业形态） \"案涉免责条款 将已从人社部门获得职业伤害保障作为免除自身赔付责任的情形，不当排除了新就业形态劳动者的合法权利，有违公平原则 \" ——阳江中院 (2026)粤17民终14号 双保险 ：① 没提示说明 → 不生效；② 即使提示了，内容违反公平 → 再打保险法 §19 / 民法典 §497。 另： 向平台、经纪公司发邮件告知 ≠ 向被保险人（骑手）说明 。 3. 投保前 checklist [ ] 是否含猝死责任 ？定义（发病后几小时内身故）？ [ ] 意外医疗 是否含？免赔额、给付比例、是否限社保目录 [ ] 伤残评定标准 是哪一套？比例表（1 级 100% → 10 级 10%） [ ] 是否 只保身故/伤残 而无医疗（很多低价产品只有身故伤残） [ ] 职业类别要求与自己的实际职业是否匹配 [ ] 高风险运动免责清单 [ ] 是否有 特定交通意外额外赔付 （航空、公共交通、自驾） [ ] 就诊医院要求 [ ] 生效时间（有的 T+3 日或 T+7 日生效） [ ] 保险期间（一年期？长期？保证续保？） [ ] 职业变更是否需要通知保险人 [ ] 健康告知页与投保页面 截屏 4. 出险后动作清单 1. 立即报案 （注意条款约定的通知期限，通常 10 日内）。 2. 固定现场证据 ：事故现场照片/视频、目击证人联系方式、报警记录与笔录、监控录像（ 尽早申请调取，监控通常只保留 30 天 ）。 3. 医疗记录 ：门急诊病历、住院病案、诊断证明。注意 医生对受伤原因的记录 （\"高处坠落\"\"车祸伤\"等），这直接决定能否证明\"外来的\"。 4. 死亡案件 ：争取尸检与死因鉴定；家属拒绝尸检的，说明理由并保留沟通记录。 5. 伤残评定 ：不要过早评定。按条款约定的时点（通常 180 日后或治疗终结后）评，选择有资质的司法鉴定机构；对结论不服的申请重新鉴定。 6. 书面提交理赔，索取 书面 拒赔/核定通知。 7. 保险人主张免责的， 书面要求其说明依据条款与证据 。 5. 四个常见误解 误解 正解 \"意外险什么都保\" 只保四要件齐备的意外；疾病（含猝死）不保 \"100 万保额就是赔 100 万\" 伤残按比例，10 级只赔 10% \"摔倒致死肯定是意外\" 若主要死因是自身疾病（如心梗），可能被认定非意外；但可走解释三 §25 按比例 \"保险公司说不赔就没办法\" 免责事由由 保险人举证 ；很多拒赔在举证环节就垮了 6. 与其他页面的关系 通用打法 ：见L0 打法层/01 八把通用武器（武器三 隐性免责、武器四 不利解释、武器七 近因原则） 流程与时效 ：见L0 打法层/02 维权操作全流程 广东案例 ：见L2 案例库/广东案例 意外寿险与互联网投保 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L1-险种层/04-寿险与人身险", "group": "2 · 险种深挖", "groupKey": "L1-险种层", "title": "寿险与其他人身险 · 纠纷全解", "order": 2, "file": "04-寿险与人身险.md", "html": "<h1 id=\"s0\">寿险与其他人身险 · 纠纷全解</h1>\n<blockquote><strong>本页自包含</strong>——读这一页不需要翻其他文件。<br><br><strong>一句话定位</strong>：寿险的纠纷<strong>不在\"赔不赔\"，而在\"赔给谁\"和\"要不要赔\"</strong>——自杀、犯罪、受益人、保险利益、宣告死亡，是它的五个主战场。<br>覆盖范围：<strong>定期寿险 / 终身寿险 / 两全保险 / 年金保险 / 增额终身寿</strong>。</blockquote>\n<hr>\n<h2 id=\"s1\">0. 速查卡片（本页最重要的 12 条）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>要点</th><th>依据</th></tr></thead><tbody>\n<tr><td>1</td><td>以死亡为给付条件的合同，<strong>未经被保险人同意并认可保险金额的，合同无效</strong></td><td>保险法 §34①</td></tr>\n<tr><td>2</td><td>\"被保险人同意并认可保险金额\"可采<strong>书面、口头或其他形式</strong>，可在<strong>合同订立后追认</strong></td><td>解释三 §1</td></tr>\n<tr><td>3</td><td>法院审理人身保险案件应<strong>主动审查</strong>保险利益与死亡险被保险人同意</td><td>解释三 §3</td></tr>\n<tr><td>4</td><td>合同订立后投保人<strong>丧失</strong>保险利益的，合同<strong>不因此无效</strong></td><td>解释三 §4</td></tr>\n<tr><td>5</td><td>自杀：合同成立或复效起 <strong>2 年内</strong>自杀的，保险人不赔但<strong>应退还保单现金价值</strong>；<strong>满 2 年后</strong>自杀的应赔</td><td>保险法 §44</td></tr>\n<tr><td>6</td><td>保险人以自杀拒赔的，<strong>由保险人承担举证责任</strong></td><td>解释三 §21</td></tr>\n<tr><td>7</td><td>自杀的例外：<strong>无民事行为能力人</strong>在 2 年内自杀的，保险人<strong>应赔</strong></td><td>保险法 §44②</td></tr>\n<tr><td>8</td><td>故意犯罪免责的认定须以<strong>刑事司法机关生效文书</strong>为依据</td><td>解释三 §22</td></tr>\n<tr><td>9</td><td>且须证明<strong>死亡伤残结果与犯罪行为有因果关系</strong></td><td>解释三 §23</td></tr>\n<tr><td>10</td><td>被保险人被<strong>宣告死亡</strong>的，保险人应按约给付</td><td>解释三 §24</td></tr>\n<tr><td>11</td><td><strong>诉讼时效 5 年</strong>（人寿保险），明显长于非寿险的 2 年</td><td>保险法 §26②</td></tr>\n<tr><td>12</td><td>中止后复效：除危险程度在中止期间<strong>显著增加</strong>外，保险人<strong>不得拒绝复效</strong></td><td>解释三 §8</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">1. 险种地图</h2>\n<pre><code>\n人身保险（非意外/健康）\n\n├── 定期寿险（保 20 年 / 保至 60 岁，纯保障，杠杆最高）\n\n├── 终身寿险（必赔，带储蓄/传承功能）\n\n│     └── 增额终身寿（保额与现金价值按约定利率逐年递增 → 常被当理财卖）\n\n├── 两全保险（生存返本 + 身故赔付）\n\n├── 年金保险（按约定时间开始按年/月领取）\n\n└── 投资连结 / 分红 / 万能险（投资属性，纠纷多集中在销售误导与收益演示）\n\n</code></pre>\n<p><strong><span class=\"warn\">!</span> 提醒</strong>：近年<strong>增额终身寿、年金险</strong>的纠纷主要不是\"拒赔\"，而是<strong>销售误导</strong>——把演示利率当承诺利率、把\"保额 3% 复利递增\"说成\"收益 3% 复利\"（<strong>保额递增 ≠ 收益率</strong>）。这类纠纷走<strong>销售误导 / 虚假宣传</strong>路径，不走保险合同的免责条款路径。</p>\n<hr>\n<h2 id=\"s3\">2. 争点逐解</h2>\n<h3 id=\"s4\">L1 · 死亡险未经被保险人同意 → 合同无效</h3>\n<p><strong>规则（保险法 §34①）</strong>：以死亡为给付保险金条件的合同，<strong>未经被保险人同意并认可保险金额的，合同无效</strong>。</p>\n<p><strong>关键补充（解释三）</strong></p>\n<ul>\n<li><strong>§1</strong>：同意可采<strong>书面、口头或其他形式</strong>；可在<strong>合同订立时</strong>作出，也可在<strong>合同订立后追认</strong>。</li>\n<li><strong>§3</strong>：法院应<strong>主动审查</strong>（即使当事人未提出）。</li>\n<li><strong>§6</strong>：未成年人的父母之外、其他履行监护职责的人（如祖父母）为其订立死亡险的，<strong>不予支持</strong>，但<strong>经未成年人父母同意</strong>的除外。</li>\n</ul>\n<p><strong>实务</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>情形</th><th>处理</th></tr></thead><tbody>\n<tr><td><strong>代签名</strong>（配偶代签被保险人名字）</td><td>合同可能无效。但被保险人<strong>事后追认</strong>（如持续缴费、配合体检、理赔时主张权利）的，可认定有效</td></tr>\n<tr><td>父母为未成年子女投保</td><td>受保险法 §33 限制（死亡给付保险金总和不得超过监管规定的限额）</td></tr>\n<tr><td>保单质押贷款、减保等需被保险人同意的</td><td>注意程序要求</td></tr>\n</tbody></table></div>\n<p><strong>后果</strong>：合同无效的，保险人应<strong>返还保险费</strong>；有过错的一方应赔偿对方损失（保险代理人明知代签仍办理的，可主张保险人过错）。</p>\n<p><strong>比喻</strong>：给别人投保身故险，必须让那个人<strong>点头并知道赔多少</strong>。这是防止\"拿别人命做交易\"的底线规则。形式可以很宽松（口头都行，事后追认也行），但<strong>这一步不能省</strong>。</p>\n<hr>\n<h3 id=\"s5\">L2 · 保险利益</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>规则</th><th>依据</th></tr></thead><tbody>\n<tr><td>人身保险的投保人在<strong>合同订立时</strong>对被保险人应具有保险利益；<strong>订立后丧失的，合同不因此无效</strong></td><td>保险法 §12、§31 + 解释三 §4</td></tr>\n<tr><td>具有保险利益的亲属范围：本人；配偶、子女、父母；前项以外与投保人有<strong>扶养、赡养或者扶养关系</strong>的家庭成员、近亲属</td><td>保险法 §31②</td></tr>\n<tr><td>被保险人<strong>同意</strong>投保人为其订立合同的，视为投保人对被保险人具有保险利益</td><td>保险法 §31③</td></tr>\n<tr><td>人身保险中因<strong>不具有保险利益</strong>导致合同无效的，投保人可主张退还<strong>扣减相应手续费后</strong>的保险费</td><td>解释二 §2</td></tr>\n<tr><td>法院应<strong>主动审查</strong>是否存在保险利益</td><td>解释三 §3</td></tr>\n</tbody></table></div>\n<p><strong>实务提示</strong>：夫妻<strong>离婚后</strong>为对方投保的寿险是否有效？→ 订立时有保险利益（配偶关系）→ 依据解释三 §4，离婚后合同<strong>不因此无效</strong>。</p>\n<hr>\n<h3 id=\"s6\">L3 · 自杀条款</h3>\n<p><strong>规则（保险法 §44）</strong></p>\n<blockquote>以被保险人死亡为给付保险金条件的合同，<strong>自合同成立或者合同效力恢复之日起二年内</strong>，被保险人自杀的，保险人不承担给付保险金的责任，但被保险人自杀时为<strong>无民事行为能力人</strong>的除外。<br>保险人依照前款规定不承担给付保险金责任的，应当按照合同约定<strong>退还保险单的现金价值</strong>。</blockquote>\n<p><strong>要点</strong></p>\n<ol>\n<li><strong>二年起算点</strong>：合同成立日 <strong>或 合同效力恢复日（复效日）</strong>——复效会<strong>重新起算</strong>二年。这是实务中最容易忽略的坑。</li>\n<li><strong>保险人举证</strong>：以自杀拒赔的，<strong>由保险人承担举证责任</strong>（解释三 §21）。</li>\n<li><strong>无民事行为能力人例外</strong>：如严重精神障碍患者、重度智力残疾者、婴幼儿，2 年内自杀的保险人<strong>仍应赔</strong>。</li>\n<li><strong>意外险不适用</strong>本条——意外险下自杀属\"非本意\"要件不成立，本就不赔，与 2 年无关。</li>\n</ol>\n<p><strong>\"自杀\"的认定</strong>：需要有<strong>故意结束自己生命</strong>的主观意图。取证通常包括遗书、现场情况、既往精神科就诊记录、公安机关结论。争议案件中可申请精神状态鉴定或死因重建。</p>\n<p><strong>比喻</strong>：自杀条款是一道\"两年冷静期\"。立法逻辑是：真想骗保的人熬不过两年；熬过两年的，通常不是为骗保。所以复效重置这个时钟，是因为<strong>复效相当于重新签了一次合同</strong>。</p>\n<hr>\n<h3 id=\"s7\">L4 · 故意犯罪与违法行为免责</h3>\n<p><strong>规则（解释三 §22、§23）</strong></p>\n<ul>\n<li><strong>§22</strong>：保险法第 45 条\"被保险人<strong>故意犯罪</strong>\"的认定，应当以<strong>刑事侦查机关、检察机关和审判机关的生效法律文书或者其他结论性意见</strong>为依据。</li>\n<li><strong>§23</strong>：保险人主张依第 45 条不担责的，应当证明被保险人的<strong>死亡、伤残结果与其实施的故意犯罪或者抗拒依法采取的刑事强制措施的行为之间存在因果关系</strong>。</li>\n</ul>\n<p><strong>破解要点</strong></p>\n<ol>\n<li><strong>没有生效刑事文书</strong> = 不能认定故意犯罪。嫌疑人死亡导致刑事程序终结（撤销案件、不起诉）的，保险人<strong>无法</strong>主张该免责。</li>\n<li><strong>因果关系</strong>：即使存在犯罪行为，若死亡结果与犯罪行为<strong>无因果关系</strong>（如在犯罪过程中被第三人杀害、在羁押期间因病死亡），不当然免责。</li>\n<li><strong>\"抗拒依法采取的刑事强制措施\"</strong>：须为\"<strong>依法</strong>\"采取的；违法执法导致伤亡的不适用。</li>\n</ol>\n<hr>\n<h3 id=\"s8\">L5 · 受益人：赔给谁</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>规则</th><th>依据</th></tr></thead><tbody>\n<tr><td>受益人由<strong>被保险人或投保人</strong>指定；投保人指定须经<strong>被保险人同意</strong></td><td>保险法 §39</td></tr>\n<tr><td>投保人指定受益人<strong>未经被保险人同意</strong>的，<strong>指定行为无效</strong></td><td>解释三 §9</td></tr>\n<tr><td>投保人/被保险人变更受益人，自<strong>变更意思表示发出时</strong>生效</td><td>解释三 §10</td></tr>\n<tr><td>被保险人可<strong>书面通知</strong>撤销其依 §34① 作出的同意意思表示，视为<strong>合同解除</strong></td><td>解释三 §2</td></tr>\n<tr><td>事故发生后<strong>变更</strong>受益人的，变更后的受益人<strong>无权</strong>请求保险金</td><td>解释三 §11</td></tr>\n<tr><td>数名受益人之一先于被保险人死亡/放弃/丧失受益权的，其份额按合同约定；无约定的按解释三 §12 处理</td><td>解释三 §12</td></tr>\n<tr><td>事故发生后，受益人可将保险金请求权<strong>转让</strong>给第三人</td><td>解释三 §13</td></tr>\n</tbody></table></div>\n<p><strong>未指定受益人的后果（保险法 §42）</strong>：保险金作为被保险人的<strong>遗产</strong>，由保险人依《民法典》继承编的规定履行给付义务 → 需办理<strong>继承手续</strong>（继承权公证或法院判决），周期长、成本高。</p>\n<p><strong>防范</strong>：<strong>务必指定受益人并写明比例</strong>，且随婚姻、家庭状况变化及时更新。</p>\n<p><strong>比喻</strong>：不指定受益人，等于把赔款扔进遗产池——要先分清楚谁有权来捞，捞之前还得先证明自己是继承人。<strong>指定受益人就是直接写好收件人地址。</strong></p>\n<hr>\n<h3 id=\"s9\">L6 · 宣告死亡</h3>\n<p><strong>规则（解释三 §24）</strong>：投保人为被保险人订立以死亡为给付保险金条件的人身保险合同，被保险人<strong>被宣告死亡</strong>后，当事人要求保险人按照保险合同约定给付保险金的，人民法院<strong>应予支持</strong>。</p>\n<p><strong>要点</strong></p>\n<ol>\n<li>依《民法典》第 46 条宣告死亡的条件：下落不明满 <strong>4 年</strong>；因意外事件下落不明满 <strong>2 年</strong>；因意外事件下落不明且经有关机关证明不可能生存的，不受 2 年限制。</li>\n<li>宣告死亡<strong>只是推定</strong>，被保险人生还的：依《民法典》第 49-50 条，本人或利害关系人可申请<strong>撤销死亡宣告</strong>；保险人可请求返还已给付的保险金（需看条款约定与具体情形）。</li>\n<li>实务中保险人常以\"未实际证明死亡\"抗辩 → 直接引解释三 §24。</li>\n</ol>\n<hr>\n<h3 id=\"s10\">L7 · 中止、复效与欠缴</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>规则</th><th>依据</th></tr></thead><tbody>\n<tr><td>约定分期缴费，投保人支付首期后，除合同另有约定外，超过约定期限 <strong>60 日</strong>未付当期保费的，合同<strong>效力中止</strong>，或由保险人按约定<strong>减少保险金额</strong></td><td>保险法 §36</td></tr>\n<tr><td>中止后经保险人与投保人协商并达成协议、投保人补交保费的，合同<strong>恢复效力</strong>；自中止之日起 <strong>2 年</strong>内双方未达成协议的，保险人有权<strong>解除合同</strong></td><td>保险法 §37</td></tr>\n<tr><td>投保人申请复效并同意补交保费的，除被保险人的<strong>危险程度在中止期间显著增加</strong>外，保险人<strong>拒绝复效</strong>的，法院不予支持</td><td>解释三 §8</td></tr>\n<tr><td>投保人<strong>解除</strong>合同的，保险人应自收到解除通知起 <strong>30 日内</strong>退还保单<strong>现金价值</strong></td><td>保险法 §47</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 复效的两个坑</strong></p>\n<ol>\n<li>复效通常要求<strong>重新如实告知</strong>（健康告知）。此时若被保险人已患病，保险人可能拒保或除外。</li>\n<li>复效会<strong>重置</strong>自杀条款的两年期间（§44）。</li>\n</ol>\n<p><strong>保险法 §37 的保险人解除权</strong>：中止满 2 年未达成复效协议的，保险人解除合同，应退还<strong>保单现金价值</strong>。</p>\n<hr>\n<h3 id=\"s11\">L8 · 销售误导（理财型人身险的高频战场）</h3>\n<p><strong>典型情形</strong>（增额终身寿 / 年金 / 分红 / 万能险）</p>\n<div class=\"tablewrap\"><table><thead><tr><th>误导手法</th><th>破解</th></tr></thead><tbody>\n<tr><td>把\"<strong>保额 3% 复利递增</strong>\"说成\"<strong>收益 3% 复利</strong>\"</td><td>保额递增 ≠ 投资收益率。看<strong>现金价值表</strong>（合同中必附）</td></tr>\n<tr><td>用<strong>高档演示利率</strong>宣传，合同只保<strong>保证利率</strong>（通常 1.75%-2.5%）</td><td>演示利益不是承诺。看条款\"保证利益\"栏</td></tr>\n<tr><td>\"<strong>随时可取</strong>\"\"<strong>和存款一样</strong>\"</td><td>提前退保只退<strong>现金价值</strong>，前几年可能远低于已缴保费</td></tr>\n<tr><td>隐瞒<strong>缴费期长、退保损失大</strong></td><td>要求销售书面说明\"第 N 年退保能拿回多少\"</td></tr>\n<tr><td><strong>夸大收益、隐瞒费用</strong>（初始费用、管理费）</td><td>保留聊天记录、宣传材料、录音</td></tr>\n</tbody></table></div>\n<p><strong>救济路径</strong></p>\n<ol>\n<li><strong>犹豫期内无条件退保</strong>（通常签收保单后 <strong>10 日或 15 日</strong>，以条款为准）——这是最干净的解法，<strong>发现不对立刻退</strong>。</li>\n<li>犹豫期外：主张<strong>欺诈/重大误解</strong>撤销合同（民法典 §147-148），或主张保险人未尽说明义务；举证销售过程中的具体承诺。</li>\n<li><strong>投诉</strong>：12378（金融监管总局）、12315、当地银保监局。</li>\n<li><strong>保险销售行为可回溯管理办法</strong>：要求对销售过程<strong>录音录像</strong>（尤其线下销售、以及部分互联网场景）。可<strong>要求保险人提供销售过程的双录资料</strong>——这是被严重低估的取证手段。</li>\n</ol>\n<p><strong>证据</strong>：宣传材料、微信聊天记录、录音（本人参与的单方录音一般可采）、双录资料（<strong>要求保险人提供</strong>）、现金价值表、投保提示书。</p>\n<hr>\n<h3 id=\"s12\">L9 · 如实告知与两年不可抗辩（寿险场景）</h3>\n<p>规则与重疾险相同（见<a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F01-%E9%87%8D%E7%96%BE%E9%99%A9\">《重疾险 · 纠纷全解》</a>C5-C7）。寿险场景的两个特点：</p>\n<ol>\n<li><strong>合同期间长</strong>（终身），两年不可抗辩的实际价值更大。</li>\n<li><strong>保额高</strong>，保险人调查力度更大（可能调取多年就诊记录、医保结算记录、体检报告、甚至同业投保记录）。</li>\n</ol>\n<p><strong>防范</strong>：投保前<strong>自查医保卡使用记录</strong>——<strong>医保卡外借给他人购药/就诊</strong>是巨大隐患，记录会被记在你名下，成为\"未如实告知\"的证据。</p>\n<hr>\n<h3 id=\"s13\">L10 · 时效与其他程序要点</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>要点</th><th>说明</th></tr></thead><tbody>\n<tr><td><strong>诉讼时效 5 年</strong>（人寿保险），自知道或应当知道保险事故发生之日起算</td><td>保险法 §26②</td></tr>\n<tr><td>死亡案件中的<strong>保险金请求权</strong>与<strong>继承权</strong>的区分</td><td>指定了受益人 → 受益人直接取得，不属遗产</td></tr>\n<tr><td>保险人已向<strong>持有保单的其他继承人</strong>给付的，对其他继承人抗辩有效</td><td>解释三 §14</td></tr>\n<tr><td>受益人与被保险人在同一事件中死亡、顺序不明的，<strong>推定受益人死亡在先</strong></td><td>解释三 §15</td></tr>\n<tr><td>保单<strong>现金价值</strong>归属：投保人解除合同的，退投保人；被保险人/受益人无权要求退现金价值</td><td>保险法 §47 / 解释三 §16、§17</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s14\">3. 投保前 checklist</h2>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>被保险人本人签名/确认</strong>（死亡险必须同意并认可金额）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>明确指定受益人</strong>及比例（不要\"法定\"）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 定期 or 终身？<strong>保到多少岁</strong>？家庭责任期（房贷 + 子女独立）是否覆盖</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保额测算：房贷余额 + 子女教育 + 父母赡养 + 5-10 年家庭生活开支</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 免责条款逐条读过（通常 3-7 条：故意犯罪、2 年内自杀、吸毒、战争、核等）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 若是<strong>理财型</strong>：只看<strong>现金价值表</strong>的保证利益，不看演示</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>犹豫期</strong>多少天？退保损失多少？</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 缴费期与收入匹配（中途断缴的复效成本高）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 健康告知页截屏</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 若有<strong>双录</strong>，确认自己理解了提问并如实作答</div>\n<hr>\n<h2 id=\"s15\">4. 出险后动作清单</h2>\n<ol>\n<li>及时报案（注意条款约定的通知期限；§21 的后果限于\"致使事故难以确定的部分\"）。</li>\n<li>固定<strong>死亡证明、户籍注销证明、殡葬证明</strong>（或宣告死亡判决书）。</li>\n<li>若涉刑案：取得<strong>公安机关结论 / 检察机关文书</strong>，明确事故性质。</li>\n<li>若涉自杀争议：注意保险人负<strong>举证责任</strong>；收集被保险人精神状态相关证据。</li>\n<li>受益人身份证明与关系证明；未指定受益人的，准备<strong>继承关系证明</strong>（继承权公证或法院判决）。</li>\n<li>书面提交理赔，索取<strong>书面</strong>核定/拒赔通知。</li>\n<li>理财型产品的销售误导：先查<strong>犹豫期</strong>，再决定退保或维权。</li>\n</ol>\n<hr>\n<h2 id=\"s16\">5. 四个常见误解</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody>\n<tr><td>\"寿险两年内自杀一律不赔\"</td><td>无民事行为能力人除外；且保险人负举证责任</td></tr>\n<tr><td>\"只要没指定受益人，钱就给配偶\"</td><td>无 → 变<strong>遗产</strong>，按法定继承分配，且需继承手续</td></tr>\n<tr><td>\"离婚了保单就失效\"</td><td>订立时有保险利益的，事后丧失<strong>不影响合同效力</strong>（解释三 §4）</td></tr>\n<tr><td>\"增额终身寿的 3% 是收益率\"</td><td>那是<strong>保额递增率</strong>，真实收益率看<strong>现金价值表</strong></td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s17\">6. 与其他页面的关系</h2>\n<ul>\n<li><strong>通用打法</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a></li>\n<li><strong>流程与文书</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>广东案例</strong>：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E6%84%8F%E5%A4%96%E5%AF%BF%E9%99%A9%E4%B8%8E%E4%BA%92%E8%81%94%E7%BD%91%E6%8A%95%E4%BF%9D\">《意外险 / 寿险 / 互联网平台投保 · 案例库》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "0. 速查卡片（本页最重要的 12 条）"}, {"id": "s2", "lv": 2, "t": "1. 险种地图"}, {"id": "s3", "lv": 2, "t": "2. 争点逐解"}, {"id": "s4", "lv": 3, "t": "L1 · 死亡险未经被保险人同意 → 合同无效"}, {"id": "s5", "lv": 3, "t": "L2 · 保险利益"}, {"id": "s6", "lv": 3, "t": "L3 · 自杀条款"}, {"id": "s7", "lv": 3, "t": "L4 · 故意犯罪与违法行为免责"}, {"id": "s8", "lv": 3, "t": "L5 · 受益人：赔给谁"}, {"id": "s9", "lv": 3, "t": "L6 · 宣告死亡"}, {"id": "s10", "lv": 3, "t": "L7 · 中止、复效与欠缴"}, {"id": "s11", "lv": 3, "t": "L8 · 销售误导（理财型人身险的高频战场）"}, {"id": "s12", "lv": 3, "t": "L9 · 如实告知与两年不可抗辩（寿险场景）"}, {"id": "s13", "lv": 3, "t": "L10 · 时效与其他程序要点"}, {"id": "s14", "lv": 2, "t": "3. 投保前 checklist"}, {"id": "s15", "lv": 2, "t": "4. 出险后动作清单"}, {"id": "s16", "lv": 2, "t": "5. 四个常见误解"}, {"id": "s17", "lv": 2, "t": "6. 与其他页面的关系"}], "text": "寿险与其他人身险 · 纠纷全解 本页自包含 ——读这一页不需要翻其他文件。 一句话定位 ：寿险的纠纷 不在\"赔不赔\"，而在\"赔给谁\"和\"要不要赔\" ——自杀、犯罪、受益人、保险利益、宣告死亡，是它的五个主战场。 覆盖范围： 定期寿险 / 终身寿险 / 两全保险 / 年金保险 / 增额终身寿 。 0. 速查卡片（本页最重要的 12 条） 要点 依据 1 以死亡为给付条件的合同， 未经被保险人同意并认可保险金额的，合同无效 保险法 §34① 2 \"被保险人同意并认可保险金额\"可采 书面、口头或其他形式 ，可在 合同订立后追认 解释三 §1 3 法院审理人身保险案件应 主动审查 保险利益与死亡险被保险人同意 解释三 §3 4 合同订立后投保人 丧失 保险利益的，合同 不因此无效 解释三 §4 5 自杀：合同成立或复效起 2 年内 自杀的，保险人不赔但 应退还保单现金价值 ； 满 2 年后 自杀的应赔 保险法 §44 6 保险人以自杀拒赔的， 由保险人承担举证责任 解释三 §21 7 自杀的例外： 无民事行为能力人 在 2 年内自杀的，保险人 应赔 保险法 §44② 8 故意犯罪免责的认定须以 刑事司法机关生效文书 为依据 解释三 §22 9 且须证明 死亡伤残结果与犯罪行为有因果关系 解释三 §23 10 被保险人被 宣告死亡 的，保险人应按约给付 解释三 §24 11 诉讼时效 5 年 （人寿保险），明显长于非寿险的 2 年 保险法 §26② 12 中止后复效：除危险程度在中止期间 显著增加 外，保险人 不得拒绝复效 解释三 §8 1. 险种地图 ⚠️ 提醒 ：近年 增额终身寿、年金险 的纠纷主要不是\"拒赔\"，而是 销售误导 ——把演示利率当承诺利率、把\"保额 3% 复利递增\"说成\"收益 3% 复利\"（ 保额递增 ≠ 收益率 ）。这类纠纷走 销售误导 / 虚假宣传 路径，不走保险合同的免责条款路径。 2. 争点逐解 L1 · 死亡险未经被保险人同意 → 合同无效 规则（保险法 §34①） ：以死亡为给付保险金条件的合同， 未经被保险人同意并认可保险金额的，合同无效 。 关键补充（解释三） §1 ：同意可采 书面、口头或其他形式 ；可在 合同订立时 作出，也可在 合同订立后追认 。 §3 ：法院应 主动审查 （即使当事人未提出）。 §6 ：未成年人的父母之外、其他履行监护职责的人（如祖父母）为其订立死亡险的， 不予支持 ，但 经未成年人父母同意 的除外。 实务 情形 处理 代签名 （配偶代签被保险人名字） 合同可能无效。但被保险人 事后追认 （如持续缴费、配合体检、理赔时主张权利）的，可认定有效 父母为未成年子女投保 受保险法 §33 限制（死亡给付保险金总和不得超过监管规定的限额） 保单质押贷款、减保等需被保险人同意的 注意程序要求 后果 ：合同无效的，保险人应 返还保险费 ；有过错的一方应赔偿对方损失（保险代理人明知代签仍办理的，可主张保险人过错）。 比喻 ：给别人投保身故险，必须让那个人 点头并知道赔多少 。这是防止\"拿别人命做交易\"的底线规则。形式可以很宽松（口头都行，事后追认也行），但 这一步不能省 。 L2 · 保险利益 规则 依据 人身保险的投保人在 合同订立时 对被保险人应具有保险利益； 订立后丧失的，合同不因此无效 保险法 §12、§31 + 解释三 §4 具有保险利益的亲属范围：本人；配偶、子女、父母；前项以外与投保人有 扶养、赡养或者扶养关系 的家庭成员、近亲属 保险法 §31② 被保险人 同意 投保人为其订立合同的，视为投保人对被保险人具有保险利益 保险法 §31③ 人身保险中因 不具有保险利益 导致合同无效的，投保人可主张退还 扣减相应手续费后 的保险费 解释二 §2 法院应 主动审查 是否存在保险利益 解释三 §3 实务提示 ：夫妻 离婚后 为对方投保的寿险是否有效？→ 订立时有保险利益（配偶关系）→ 依据解释三 §4，离婚后合同 不因此无效 。 L3 · 自杀条款 规则（保险法 §44） 以被保险人死亡为给付保险金条件的合同， 自合同成立或者合同效力恢复之日起二年内 ，被保险人自杀的，保险人不承担给付保险金的责任，但被保险人自杀时为 无民事行为能力人 的除外。 保险人依照前款规定不承担给付保险金责任的，应当按照合同约定 退还保险单的现金价值 。 要点 1. 二年起算点 ：合同成立日 或 合同效力恢复日（复效日） ——复效会 重新起算 二年。这是实务中最容易忽略的坑。 2. 保险人举证 ：以自杀拒赔的， 由保险人承担举证责任 （解释三 §21）。 3. 无民事行为能力人例外 ：如严重精神障碍患者、重度智力残疾者、婴幼儿，2 年内自杀的保险人 仍应赔 。 4. 意外险不适用 本条——意外险下自杀属\"非本意\"要件不成立，本就不赔，与 2 年无关。 \"自杀\"的认定 ：需要有 故意结束自己生命 的主观意图。取证通常包括遗书、现场情况、既往精神科就诊记录、公安机关结论。争议案件中可申请精神状态鉴定或死因重建。 比喻 ：自杀条款是一道\"两年冷静期\"。立法逻辑是：真想骗保的人熬不过两年；熬过两年的，通常不是为骗保。所以复效重置这个时钟，是因为 复效相当于重新签了一次合同 。 L4 · 故意犯罪与违法行为免责 规则（解释三 §22、§23） §22 ：保险法第 45 条\"被保险人 故意犯罪 \"的认定，应当以 刑事侦查机关、检察机关和审判机关的生效法律文书或者其他结论性意见 为依据。 §23 ：保险人主张依第 45 条不担责的，应当证明被保险人的 死亡、伤残结果与其实施的故意犯罪或者抗拒依法采取的刑事强制措施的行为之间存在因果关系 。 破解要点 1. 没有生效刑事文书 = 不能认定故意犯罪。嫌疑人死亡导致刑事程序终结（撤销案件、不起诉）的，保险人 无法 主张该免责。 2. 因果关系 ：即使存在犯罪行为，若死亡结果与犯罪行为 无因果关系 （如在犯罪过程中被第三人杀害、在羁押期间因病死亡），不当然免责。 3. \"抗拒依法采取的刑事强制措施\" ：须为\" 依法 \"采取的；违法执法导致伤亡的不适用。 L5 · 受益人：赔给谁 规则 依据 受益人由 被保险人或投保人 指定；投保人指定须经 被保险人同意 保险法 §39 投保人指定受益人 未经被保险人同意 的， 指定行为无效 解释三 §9 投保人/被保险人变更受益人，自 变更意思表示发出时 生效 解释三 §10 被保险人可 书面通知 撤销其依 §34① 作出的同意意思表示，视为 合同解除 解释三 §2 事故发生后 变更 受益人的，变更后的受益人 无权 请求保险金 解释三 §11 数名受益人之一先于被保险人死亡/放弃/丧失受益权的，其份额按合同约定；无约定的按解释三 §12 处理 解释三 §12 事故发生后，受益人可将保险金请求权 转让 给第三人 解释三 §13 未指定受益人的后果（保险法 §42） ：保险金作为被保险人的 遗产 ，由保险人依《民法典》继承编的规定履行给付义务 → 需办理 继承手续 （继承权公证或法院判决），周期长、成本高。 防范 ： 务必指定受益人并写明比例 ，且随婚姻、家庭状况变化及时更新。 比喻 ：不指定受益人，等于把赔款扔进遗产池——要先分清楚谁有权来捞，捞之前还得先证明自己是继承人。 指定受益人就是直接写好收件人地址。 L6 · 宣告死亡 规则（解释三 §24） ：投保人为被保险人订立以死亡为给付保险金条件的人身保险合同，被保险人 被宣告死亡 后，当事人要求保险人按照保险合同约定给付保险金的，人民法院 应予支持 。 要点 1. 依《民法典》第 46 条宣告死亡的条件：下落不明满 4 年 ；因意外事件下落不明满 2 年 ；因意外事件下落不明且经有关机关证明不可能生存的，不受 2 年限制。 2. 宣告死亡 只是推定 ，被保险人生还的：依《民法典》第 49 50 条，本人或利害关系人可申请 撤销死亡宣告 ；保险人可请求返还已给付的保险金（需看条款约定与具体情形）。 3. 实务中保险人常以\"未实际证明死亡\"抗辩 → 直接引解释三 §24。 L7 · 中止、复效与欠缴 规则 依据 约定分期缴费，投保人支付首期后，除合同另有约定外，超过约定期限 60 日 未付当期保费的，合同 效力中止 ，或由保险人按约定 减少保险金额 保险法 §36 中止后经保险人与投保人协商并达成协议、投保人补交保费的，合同 恢复效力 ；自中止之日起 2 年 内双方未达成协议的，保险人有权 解除合同 保险法 §37 投保人申请复效并同意补交保费的，除被保险人的 危险程度在中止期间显著增加 外，保险人 拒绝复效 的，法院不予支持 解释三 §8 投保人 解除 合同的，保险人应自收到解除通知起 30 日内 退还保单 现金价值 保险法 §47 ⚠️ 复效的两个坑 1. 复效通常要求 重新如实告知 （健康告知）。此时若被保险人已患病，保险人可能拒保或除外。 2. 复效会 重置 自杀条款的两年期间（§44）。 保险法 §37 的保险人解除权 ：中止满 2 年未达成复效协议的，保险人解除合同，应退还 保单现金价值 。 L8 · 销售误导（理财型人身险的高频战场） 典型情形 （增额终身寿 / 年金 / 分红 / 万能险） 误导手法 破解 把\" 保额 3% 复利递增 \"说成\" 收益 3% 复利 \" 保额递增 ≠ 投资收益率。看 现金价值表 （合同中必附） 用 高档演示利率 宣传，合同只保 保证利率 （通常 1.75% 2.5%） 演示利益不是承诺。看条款\"保证利益\"栏 \" 随时可取 \"\" 和存款一样 \" 提前退保只退 现金价值 ，前几年可能远低于已缴保费 隐瞒 缴费期长、退保损失大 要求销售书面说明\"第 N 年退保能拿回多少\" 夸大收益、隐瞒费用 （初始费用、管理费） 保留聊天记录、宣传材料、录音 救济路径 1. 犹豫期内无条件退保 （通常签收保单后 10 日或 15 日 ，以条款为准）——这是最干净的解法， 发现不对立刻退 。 2. 犹豫期外：主张 欺诈/重大误解 撤销合同（民法典 §147 148），或主张保险人未尽说明义务；举证销售过程中的具体承诺。 3. 投诉 ：12378（金融监管总局）、12315、当地银保监局。 4. 保险销售行为可回溯管理办法 ：要求对销售过程 录音录像 （尤其线下销售、以及部分互联网场景）。可 要求保险人提供销售过程的双录资料 ——这是被严重低估的取证手段。 证据 ：宣传材料、微信聊天记录、录音（本人参与的单方录音一般可采）、双录资料（ 要求保险人提供 ）、现金价值表、投保提示书。 L9 · 如实告知与两年不可抗辩（寿险场景） 规则与重疾险相同（见L1 险种层/01 重疾险C5 C7）。寿险场景的两个特点： 1. 合同期间长 （终身），两年不可抗辩的实际价值更大。 2. 保额高 ，保险人调查力度更大（可能调取多年就诊记录、医保结算记录、体检报告、甚至同业投保记录）。 防范 ：投保前 自查医保卡使用记录 —— 医保卡外借给他人购药/就诊 是巨大隐患，记录会被记在你名下，成为\"未如实告知\"的证据。 L10 · 时效与其他程序要点 要点 说明 诉讼时效 5 年 （人寿保险），自知道或应当知道保险事故发生之日起算 保险法 §26② 死亡案件中的 保险金请求权 与 继承权 的区分 指定了受益人 → 受益人直接取得，不属遗产 保险人已向 持有保单的其他继承人 给付的，对其他继承人抗辩有效 解释三 §14 受益人与被保险人在同一事件中死亡、顺序不明的， 推定受益人死亡在先 解释三 §15 保单 现金价值 归属：投保人解除合同的，退投保人；被保险人/受益人无权要求退现金价值 保险法 §47 / 解释三 §16、§17 3. 投保前 checklist [ ] 被保险人本人签名/确认 （死亡险必须同意并认可金额） [ ] 明确指定受益人 及比例（不要\"法定\"） [ ] 定期 or 终身？ 保到多少岁 ？家庭责任期（房贷 + 子女独立）是否覆盖 [ ] 保额测算：房贷余额 + 子女教育 + 父母赡养 + 5 10 年家庭生活开支 [ ] 免责条款逐条读过（通常 3 7 条：故意犯罪、2 年内自杀、吸毒、战争、核等） [ ] 若是 理财型 ：只看 现金价值表 的保证利益，不看演示 [ ] 犹豫期 多少天？退保损失多少？ [ ] 缴费期与收入匹配（中途断缴的复效成本高） [ ] 健康告知页截屏 [ ] 若有 双录 ，确认自己理解了提问并如实作答 4. 出险后动作清单 1. 及时报案（注意条款约定的通知期限；§21 的后果限于\"致使事故难以确定的部分\"）。 2. 固定 死亡证明、户籍注销证明、殡葬证明 （或宣告死亡判决书）。 3. 若涉刑案：取得 公安机关结论 / 检察机关文书 ，明确事故性质。 4. 若涉自杀争议：注意保险人负 举证责任 ；收集被保险人精神状态相关证据。 5. 受益人身份证明与关系证明；未指定受益人的，准备 继承关系证明 （继承权公证或法院判决）。 6. 书面提交理赔，索取 书面 核定/拒赔通知。 7. 理财型产品的销售误导：先查 犹豫期 ，再决定退保或维权。 5. 四个常见误解 误解 正解 \"寿险两年内自杀一律不赔\" 无民事行为能力人除外；且保险人负举证责任 \"只要没指定受益人，钱就给配偶\" 无 → 变 遗产 ，按法定继承分配，且需继承手续 \"离婚了保单就失效\" 订立时有保险利益的，事后丧失 不影响合同效力 （解释三 §4） \"增额终身寿的 3% 是收益率\" 那是 保额递增率 ，真实收益率看 现金价值表 6. 与其他页面的关系 通用打法 ：见L0 打法层/01 八把通用武器 流程与文书 ：见L0 打法层/02 维权操作全流程 广东案例 ：见L2 案例库/广东案例 意外寿险与互联网投保 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L1-险种层/05-车险", "group": "2 · 险种深挖", "groupKey": "L1-险种层", "title": "车险 · 纠纷全解", "order": 2, "file": "05-车险.md", "html": "<h1 id=\"s0\">车险 · 纠纷全解</h1>\n<blockquote><strong>本页自包含</strong>——读这一页不需要翻其他文件。<br><br><strong>一句话定位</strong>：车险是普通人接触最多、也最容易在\"<strong>我以为能赔</strong>\"上栽跟头的险种。它的两大主战场：<strong>① 免责情形（酒驾、无证、逃逸、营运）；② 赔多少（高保低赔、免赔率、停运损失）</strong>。</blockquote>\n<hr>\n<h2 id=\"s1\">0. 速查卡片（本页最重要的 14 条）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>要点</th><th>依据</th></tr></thead><tbody>\n<tr><td>1</td><td><strong>交强险</strong>优先赔付（有责限额内），<strong>不赔本车人员和被保险人财产损失</strong></td><td>《机动车交通事故责任强制保险条例》</td></tr>\n<tr><td>2</td><td>交强险<strong>垫付后追偿</strong>的情形：无证、醉酒、被盗抢期间肇事、故意制造事故</td><td>条例 §22</td></tr>\n<tr><td>3</td><td>商业险免责条款涉及的若是<strong>法律、行政法规的禁止性规定</strong>（酒驾、无证、逃逸），保险人<strong>提示后</strong>即可生效，无需\"明确说明\"</td><td>解释二 §10</td></tr>\n<tr><td>4</td><td><strong>但仍须证明\"已提示\"</strong>——这是保险人最容易失守的一环</td></tr>\n<tr><td>5</td><td><strong>危险程度显著增加</strong>（改变使用性质、改装等）未通知的，因此发生事故不赔</td><td>保险法 §52</td></tr>\n<tr><td>6</td><td>是否构成\"显著增加\"，综合判断：<strong>用途、使用范围、所处环境、改装、使用人/管理人改变、持续时间</strong>等</td><td>解释四 §4</td></tr>\n<tr><td>7</td><td>增加的危险<strong>属于订约时保险人预见或应当预见的承保范围</strong>的，<strong>不构成</strong>显著增加</td><td>解释四 §4</td></tr>\n<tr><td>8</td><td>广东口径：<strong>不是\"只要跑过顺风车就拒赔\"</strong>，看接单频率、路线匹配度、收费性质、是否以营运为目的</td></tr>\n<tr><td>9</td><td><strong>代位求偿</strong>：保险人赔付后在赔偿金额范围内代位行使被保险人对第三者的请求权</td><td>保险法 §60</td></tr>\n<tr><td>10</td><td>保险人<strong>不得</strong>对被保险人的<strong>家庭成员或其组成人员</strong>行使代位权，<strong>故意</strong>造成的除外</td><td>保险法 §62</td></tr>\n<tr><td>11</td><td>未及时核定的（复杂情形 <strong>30 日</strong>），应赔偿因此受到的<strong>损失</strong></td><td>保险法 §23③</td></tr>\n<tr><td>12</td><td>未及时通知的后果，限于\"致使事故性质、原因、损失程度<strong>难以确定</strong>\"的<strong>部分</strong></td><td>保险法 §21</td></tr>\n<tr><td>13</td><td><strong>诉讼时效 3 年</strong>（§26 写 2 年，法院按民法典适用 3 年），自知道或应当知道保险事故发生之日起算</td><td>保险法 §26① + 民法典 §188</td></tr>\n<tr><td>14</td><td>事故发生后被保险人/受益人<strong>起诉保险人</strong>的，保险人不得以\"未先向第三者索赔\"抗辩</td><td>解释二 §19</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">1. 险种地图</h2>\n<pre><code>\n车险\n\n├── 交强险（法定强制，赔第三方）\n\n│     有责限额 / 无责限额；人身伤亡 + 财产损失\n\n│     特点：无过错也赔（无责限额内）；违法情形下垫付后可追偿\n\n├── 商业第三者责任险（赔第三方，补充交强险不足部分）\n\n│     保额自选（通常 100 万-300 万，建议 200 万起 / 一线城市 300 万）\n\n├── 机动车损失险（车损险，赔自己的车）\n\n│     2020 年车险综合改革后已并入：盗抢、玻璃、自燃、涉水、不计免赔、无法找到第三方\n\n├── 车上人员责任险（司机/乘客座位险）\n\n└── 附加险（医保外用药、精神损害、法定节假日翻倍、增值服务等）\n\n</code></pre>\n<p><strong><span class=\"warn\">!</span> 2020 年车险综合改革要点</strong>：车损险主险已<strong>整合</strong>盗抢险、玻璃单独破碎险、自燃损失险、发动机涉水损失险、不计免赔率险、无法找到第三方特约险等。所以<strong>老保单与新保单的责任结构不同</strong>——看保单年度。</p>\n<p><strong>比喻</strong>：交强险像\"最低工资\"——法律强制、人人都有，但出了大事远远不够。商业三者险才是真正兜底的那笔钱。<strong>省那几百块保费把三者险买成 50 万，是拿全家的房子赌一次事故。</strong></p>\n<hr>\n<h2 id=\"s3\">2. 争点逐解</h2>\n<h3 id=\"s4\">V1 · 酒驾、醉驾、无证驾驶、逃逸</h3>\n<p><strong>规则</strong></p>\n<ul>\n<li>这类情形属<strong>法律、行政法规的禁止性规定</strong>。依<strong>解释二 §10</strong>：保险人将法律、行政法规中的禁止性规定情形作为免责事由的，保险人<strong>作出提示后</strong>，投保人、被保险人以\"未明确说明\"为由主张该条款不生效的，<strong>法院不予支持</strong>。</li>\n<li><strong>所以</strong>：这类条款只需<strong>提示</strong>，不需\"明确说明\"。</li>\n<li><strong>但是</strong>——<strong>保险人仍须证明自己\"提示\"过</strong>（加粗、加黑、单独印制、投保人签字确认等）。这是最常被攻破的环节。</li>\n</ul>\n<p><strong>破解检查清单</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>检查项</th><th>说明</th></tr></thead><tbody>\n<tr><td>保险人是否提交了<strong>有投保人签名确认</strong>的投保单/免责事项说明书？</td><td>没有 → 提示未完成</td></tr>\n<tr><td>电子投保的，是否展示了免责条款页面、有无强制阅读/勾选？</td><td>网页未做的，认定未提示（解释二 §12 的反向推论）</td></tr>\n<tr><td>该情形是否<strong>确属</strong>法律、行政法规的禁止性规定？</td><td>例如\"未按规定年检\"是<strong>规章/管理条例</strong>层面的义务，性质有争议</td></tr>\n<tr><td>是否属于<strong>醉酒</strong>还是仅\"饮酒后驾驶\"？</td><td>免责条款的射程以条文表述为准，表述不明的 → §30</td></tr>\n<tr><td><strong>逃逸</strong>的认定</td><td>须有交通事故认定书的认定，或生效刑事文书；主观上须为<strong>逃避法律追究</strong></td></tr>\n<tr><td>因果关系</td><td>逃逸与事故发生、损失扩大之间是否有因果关系</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 重要区分</strong>：交强险与商业险的处理不同。</p>\n<ul>\n<li><strong>交强险</strong>：条例 §22 情形下，保险人<strong>在交强险责任限额内垫付</strong>抢救费用，并<strong>有权向致害人追偿</strong>；对<strong>财产损失</strong>，交强险<strong>不承担</strong>赔偿责任。</li>\n<li><strong>商业三者险</strong>：依免责条款拒赔（需提示）。</li>\n</ul>\n<hr>\n<h3 id=\"s5\">V2 · 改变使用性质 / 营运（网约车、顺风车、货拉拉）</h3>\n<p><strong>这是近年车险最高频的争议，也是广东判例最集中的地方。<span class=\"warn\">!</span> 本节的通说在 2025-2026 年判例中被部分修正，务必按新版打。</strong></p>\n<p><strong>规则</strong></p>\n<ul>\n<li>保险法 §52：保险标的的<strong>危险程度显著增加</strong>的，被保险人应按合同约定<strong>及时通知</strong>保险人；未履行通知义务，因危险程度显著增加而发生的保险事故，保险人<strong>不承担赔偿责任</strong>。</li>\n<li><strong>解释四 §4</strong> 综合判断因素：<strong>用途改变、使用范围改变、所处环境变化、改装、使用人或管理人改变、持续时间</strong>，以及其他可能导致危险程度显著增加的因素。</li>\n<li><strong>关键但书</strong>：增加的危险<strong>属于订立合同时保险人预见或者应当预见的承保范围</strong>的，<strong>不构成</strong>危险程度显著增加。</li>\n</ul>\n<h4 id=\"s6\">🔥 修正一：§52 的通知义务是<strong>法定义务</strong>，提示说明义务这张牌打不了</h4>\n<p>湛江中院 (2025)粤08民终951号（顺风车 + 特惠快车，接单 1895 次）：</p>\n<blockquote>保险标的物的危险程度显著增加的，被保险人应当按照合同约定及时通知保险人，<strong>该通知义务是被保险人的法定义务，并不是根据双方在保险合同中的约定而产生的义务</strong>。</blockquote>\n<blockquote>周某上诉主张……未就免责条款向其履行提示和明确说明义务，不能免除赔偿责任。<strong>如前所述，车辆危险程度显著增加时，被保险人的通知义务属于法定义务，不是约定义务，周某该主张系其理解错误，于法无据，本院不予支持。</strong></blockquote>\n<p><strong>→ 营运车案件只剩两张牌</strong>：① 证明<strong>没有</strong>改变使用性质；② 证明危险程度<strong>未显著增加</strong>。不要再花力气打提示说明义务。</p>\n<h4 id=\"s7\">🔥 修正二：\"事故发生时没在接单\"不构成抗辩</h4>\n<blockquote>事发前该车辆用于营运导致被保险车辆危险程度显著增加的事实<strong>并不因其事发当时未进行运营而改变</strong>。（中山中院 (2025)粤20民终1136号）</blockquote>\n<p>（此前通说把\"出险时是否在营运\"当第一分水岭，该说法已被本判例否定，<strong>以本节为准</strong>。）</p>\n<h4 id=\"s8\">顺风车 vs 营运：法院的四项判定标准（四案归纳）</h4>\n<div class=\"tablewrap\"><table><thead><tr><th>要素</th><th>仍属顺风车（不营运）</th><th>已构成营运（保险人免责）</th></tr></thead><tbody>\n<tr><td><strong>接单次数</strong></td><td>偶发、个位数</td><td>47 次 / 1548 次 / 1895 次 / 2271 单</td></tr>\n<tr><td><strong>路线</strong></td><td>相对固定、以既定目的地为终点</td><td>起点终点不固定、跨市、跨多区县</td></tr>\n<tr><td><strong>时间跨度</strong></td><td>短期</td><td>154 天 / 785 天</td></tr>\n<tr><td><strong>目的</strong></td><td>分摊出行成本、免费互助</td><td>收取报酬、营利</td></tr>\n</tbody></table></div>\n<blockquote>A 公司关于该车用于营运的主张已达到<strong>高度盖然性</strong>，可予以认定。（中山 (2025)粤20民终2567号，47 单跨市即认定）</blockquote>\n<p><strong><span class=\"warn\">!</span> 特别提示</strong>：<strong>\"特惠快车\" = 营运</strong>。湛江中院 (2025)粤08民终951号：</p>\n<blockquote>特惠快车业务是完全按照乘客的需求意愿提供的<strong>独立的非拼车的搭乘收费服务</strong>，已属于营运性质。</blockquote>\n<h4 id=\"s9\">破解路径（保险人举证，标准很高）</h4>\n<p>东莞中院 (2026)粤19民终1493号——保险人<strong>举证不足</strong>，营运主张不成立：</p>\n<blockquote>粤SXXX<strong>汽车外观没有明显营运标识……举证的手机截图</strong>没有具体身份、车辆牌号等平台注册信息<strong>，……缺乏营运的外观特征……平台记录并未反映可以</strong>确定与简某存在直接联系<strong>的内容……事故调查也</strong>未询问简某**关于手机截图、平台记录的情况。</blockquote>\n<p><strong>质证三问（答不上来即主张不成立）</strong></p>\n<ol>\n<li>截图里的<strong>账号注册人是谁</strong>？有没有身份证信息？</li>\n<li>截图里的<strong>车牌号</strong>是多少？</li>\n<li>有没有就这些截图<strong>向当事人做过询问笔录</strong>？当事人是否确认过？</li>\n</ol>\n<p><strong>另外</strong>：该案保险人搬出\"车险电子化实名投保系统由监管部门统一开发、行业协会已发文明确即视为已履行提示说明义务\"，<strong>法院未采纳</strong>。这个挡箭牌以后可以直接顶回去。</p>\n<h4 id=\"s10\">防范</h4>\n<p><strong>真跑营运就按营运投保。</strong> 四案口径完全一致（中山 2、湛江 1、揭阳 1），接单量一旦过百、路线跨市，基本必输。营运保费差额远低于商业险整体拒赔的代价。</p>\n<p><strong><span class=\"warn\">!</span> 还有一个不利因素</strong>：揭阳中院 (2026)粤52民终425号认定——</p>\n<blockquote>在……已提供有投保人陈某甲签名的投保单，且<strong>陈某甲连续多年在同一保险公司投保</strong>的情况下，应认定……已对免责条款尽到明确说明义务。</blockquote>\n<p>即<strong>\"连续多年在同一家投保\"会被当作对你不利的证据</strong>。</p>\n<hr>\n<h3 id=\"s11\">V3 · 车辆未年检、改装</h3>\n<p><strong>未年检</strong></p>\n<ul>\n<li>属行政违法行为，但<strong>是否属\"法律、行政法规的禁止性规定\"</strong>存在争议（道交法层面有要求，但\"未经检验合格不得上路\"的表述与免责条款的对应关系需具体审查）。</li>\n<li>关键抗辩：<strong>未年检与事故之间有无因果关系</strong>。若事故纯由他方造成、车辆机械状况无问题，可主张不适用免责。</li>\n<li>条款表述若过于宽泛（\"未按规定检验或检验不合格，保险人均不赔\"），可主张加重责任（§19）+ 不利解释（§30）。</li>\n</ul>\n<p><strong>改装</strong></p>\n<ul>\n<li>属解释四 §4 列举的\"危险程度显著增加\"因素之一，但要看<strong>改装的性质</strong>（外观贴膜 vs 动力系统改装 vs 改变车辆结构）。</li>\n<li>轻微改装、不影响安全性能的，主张不构成显著增加。</li>\n<li>保险人须证明改装与事故的因果关系。</li>\n</ul>\n<hr>\n<h3 id=\"s12\">V4 · 高保低赔</h3>\n<p><strong>场景</strong>：按新车购置价（或约定的较高保险金额）收取保费，出险全损时按<strong>出险时的实际价值（折旧后）</strong>赔偿。</p>\n<p><strong>争议实质</strong>：保险金额高于保险价值的部分，投保人付了保费却得不到保障。</p>\n<p><strong>规则</strong></p>\n<ul>\n<li>保险法 §55：投保人和保险人<strong>约定</strong>保险标的的保险价值并在合同中载明的，以<strong>约定保险价值</strong>为赔偿计算标准；未约定保险价值的，以<strong>保险事故发生时保险标的的实际价值</strong>为赔偿计算标准。</li>\n<li><strong>保险金额不得超过保险价值</strong>；超过的部分无效，保险人应<strong>退还</strong>相应的保险费（§55③）。</li>\n</ul>\n<p><strong>破解路径</strong></p>\n<ol>\n<li>看合同是否<strong>约定并载明了保险价值</strong>。约定了 → 按约定赔；没约定 → 按实际价值。</li>\n<li>按新车价收保费、按折旧价赔付的，主张<strong>违反对价平衡与诚实信用</strong>，且违反 §55 的\"超过部分无效并退费\"规则。</li>\n<li>主张保险人未尽说明义务（对\"保险金额/保险价值/赔偿计算方式\"这一核心条款未明确说明）。</li>\n<li>监管层面：车险条款由行业统一制定（中国保险行业协会条款），仍应适用上述规则。</li>\n</ol>\n<hr>\n<h3 id=\"s13\">V5 · 免赔率与不计免赔</h3>\n<p><strong>改革背景</strong>：2020 年车险综合改革后，<strong>不计免赔率险已并入主险</strong>，通常默认包含。但仍需注意：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody>\n<tr><td>绝对免赔额（如\"每次事故免赔 2000 元\"）</td><td>若约定，属<strong>免赔额</strong>条款 → 需提示说明（解释二 §9）</td></tr>\n<tr><td>无法找到第三方的免赔率</td><td>改革后已并入主险，通常不再单独扣减</td></tr>\n<tr><td>违反安全装载规定</td><td>部分条款约定因此增加免赔率 → 属比例给付条款 → 需提示说明</td></tr>\n</tbody></table></div>\n<hr>\n<h3 id=\"s14\">V6 · 停运损失与迟延定损</h3>\n<p><strong>停运损失</strong>（营运车辆常见）</p>\n<ul>\n<li>保险法 §23③：保险人未及时履行赔付义务的，<strong>除支付保险金外，应当赔偿被保险人或者受益人因此受到的损失</strong>。</li>\n<li>因保险人<strong>拖延定损、拖延赔付</strong>导致车辆被修理厂留置、无法营运的，停运损失可主张由保险人赔偿。</li>\n<li><strong>举证</strong>：营运资质（道路运输证、网约车运输证）、事故前 <strong>3-6 个月的平均营运收入</strong>、维修时长、停运期间的银行流水/平台流水。</li>\n</ul>\n<p><strong>迟延定损</strong></p>\n<ul>\n<li>情形复杂的 <strong>30 日内</strong>核定（§23①），自<strong>初次收到索赔请求及资料之日</strong>起算（解释二 §15）。</li>\n<li>实务打法：<strong>书面催告 + 固定时间节点</strong>。每一次沟通都留书面记录（快递单、邮件、有时间戳的聊天记录）。</li>\n<li>车辆被长期留置的，可考虑<strong>先行提车</strong>（自付维修费后索赔），避免损失扩大（同时注意 §57 的施救减损义务，被保险人也有减损义务）。</li>\n</ul>\n<p><strong><span class=\"warn\">!</span> 减损义务（保险法 §57）</strong>：保险事故发生后，被保险人应尽力采取必要措施防止或减少损失；所支付的<strong>必要、合理费用</strong>由保险人承担。解释四 §6：<strong>措施未产生实际效果</strong>不能作为保险人的抗辩。</p>\n<hr>\n<h3 id=\"s15\">V7 · 代位求偿</h3>\n<p><strong>规则（保险法 §60-63）</strong></p>\n<ol>\n<li>因<strong>第三者</strong>对保险标的的损害造成保险事故的，保险人自<strong>向被保险人赔偿保险金之日起</strong>，在<strong>赔偿金额范围内</strong>代位行使被保险人对第三者的请求权。</li>\n<li>被保险人<strong>已获赔部分</strong>之外，仍可向第三者索赔（§60③）。</li>\n<li><strong>不得</strong>对被保险人的<strong>家庭成员或其组成人员</strong>行使代位权，<strong>故意</strong>造成的除外（§62）。</li>\n<li>被保险人<strong>弃权</strong>的后果见解释四 §9。</li>\n</ol>\n<p><strong>被保险人视角的实战要点</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>情形</th><th>处理</th></tr></thead><tbody>\n<tr><td>己方无责，对方全责但对方不赔/找不到</td><td>向<strong>自己的保险公司</strong>申请代位求偿（车损险项下），由保险公司先赔再去追对方</td></tr>\n<tr><td>担心代位后影响自己</td><td>代位求偿<strong>不算出险</strong>的认定看条款与监管口径；实务中无责方申请代位通常不影响</td></tr>\n<tr><td>保险人赔付后向自己追偿</td><td>检查自己是否属 §62 的排除对象；是否有 §61 的情形（被保险人放弃对第三者的请求权）</td></tr>\n<tr><td>被保险人<strong>已放弃</strong>对第三者的权利</td><td>解释四 §9：订立合同前已放弃的，保险人相应部分不能代位；订立时保险人已询问而未告知的，可请求返还相应保险金</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 关键提示</strong>：事故后<strong>不要随便签\"一次性了结、放弃追偿\"的协议</strong>——可能触发 §61，导致保险人扣减或要求返还保险金。</p>\n<p><strong>代位求偿中的保险人抗辩（东莞中院 (2026)粤19民终1493号）</strong>：保险人向第三者代位求偿时，第三者一方的保险公司常以\"被保险人改变使用性质从事营运\"拒赔。<strong>该抗辩由主张方举证，且标准很高</strong>——须能锁定到具体的人、车、订单。该案保险人举证不足，判赔。详见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7-%E7%AC%AC%E4%BA%8C%E8%BE%91\">《广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）》</a> V-A4。</p>\n<hr>\n<h3 id=\"s16\">V8 · 责任保险与第三者的直接请求权</h3>\n<p><strong>规则（保险法 §65 + 解释四 §14-§20）</strong></p>\n<ol>\n<li>被保险人<strong>怠于请求</strong>的，第三者有权<strong>直接</strong>向保险人请求赔偿保险金（§65②）。</li>\n<li>\"怠于请求\"的认定（解释四 §15）：被保险人对第三者的赔偿责任<strong>已经确定</strong>（如生效判决确认），被保险人<strong>不履行</strong>赔偿，且第三者起诉保险人时被保险人<strong>尚未</strong>向保险人提出直接向第三者赔偿的请求。</li>\n<li><strong>连带责任</strong>（解释四 §16）：共同侵权下保险人以连带责任超出被保险人责任份额为由拒赔的，<strong>不予支持</strong>；保险人赔付后可向其他连带责任人追偿。</li>\n<li>赔偿责任经生效判决确认并进入执行、<strong>未获清偿</strong>的，第三者请求保险人赔偿的，保险人以\"已进入执行程序\"抗辩的，<strong>不予支持</strong>（解释四 §17）。</li>\n<li>责任保险的<strong>诉讼时效</strong>自被保险人对第三者应负的赔偿责任<strong>确定之日</strong>起算（解释四 §18）——这是一个容易算错的时效。</li>\n</ol>\n<hr>\n<h3 id=\"s17\">V9 · 新能源汽车专属条款</h3>\n<p><strong>要点</strong>（2021 年中国保险行业协会发布新能源车专属条款）</p>\n<div class=\"tablewrap\"><table><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody>\n<tr><td><strong>三电系统</strong>（电池、电机、电控）</td><td>纳入车损险保障范围</td></tr>\n<tr><td><strong>自燃</strong></td><td>含起火燃烧（传统车险的\"自燃\"定义与新能源条款不同）</td></tr>\n<tr><td><strong>电池衰减</strong></td><td>通常属<strong>除外</strong>（自然损耗不属于保险事故），这是主要争议点</td></tr>\n<tr><td><strong>充电期间</strong>的损失</td><td>专属条款通常纳入保障，注意条款表述与除外</td></tr>\n<tr><td><strong>涉水</strong></td><td>新能源车涉水的定损与电池安全性评估争议较多</td></tr>\n</tbody></table></div>\n<p><strong>争议预判</strong>：电池衰减 vs 意外损坏的区分（需鉴定）、充电自燃的责任归属（车损险 vs 产品责任）、涉水后电池隐性损伤的定损。</p>\n<hr>\n<h3 id=\"s18\">V10 · 未及时报案 / 未及时通知</h3>\n<p><strong>规则（保险法 §21）</strong>：故意或者因<strong>重大过失</strong>未及时通知，致使保险事故的性质、原因、损失程度等<strong>难以确定</strong>的，保险人对<strong>无法确定的部分</strong>不承担责任。</p>\n<p><strong>注意三个限定</strong>（这是重要的抗辩武器）：</p>\n<ol>\n<li>须为<strong>故意或重大过失</strong>（一般过失不适用）；</li>\n<li>须<strong>致使事故难以确定</strong>；</li>\n<li>责任范围限于\"<strong>无法确定的部分</strong>\"，不是全部。</li>\n</ol>\n<p><strong>实务</strong>：单方事故未报警、未保留现场的，容易被保险人主张\"无法核定\"。所以<strong>事故后第一件事是报警 + 报保险 + 拍照</strong>。</p>\n<hr>\n<h3 id=\"s19\">V11 · 特殊主体与情形</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>情形</th><th>要点</th></tr></thead><tbody>\n<tr><td><strong>借车给他人</strong></td><td>看条款对\"被保险人允许的合格驾驶人\"的约定；使用人变更属解释四 §4 的因素之一</td></tr>\n<tr><td><strong>车辆转让未过户</strong></td><td>解释四 §1：保险标的已交付受让人但未办过户登记，承担风险的受让人可主张行使被保险人权利</td></tr>\n<tr><td><strong>转让后未通知保险人</strong></td><td>保险法 §49；解释四 §5：依法及时发出转让通知后、保险人答复前发生事故的，被保险人/受让人可主张赔付</td></tr>\n<tr><td><strong>驾驶证逾期未换证 / 准驾车型不符</strong></td><td>看是否属免责条款射程、是否属\"法律、行政法规的禁止性规定\"、表述是否明确</td></tr>\n<tr><td><strong>实习期上高速</strong></td><td>属规章层面要求，是否构成免责事由常引发争议 → §30 不利解释</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s20\">3. 投保前 checklist</h2>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>三者险保额</strong>：建议 200 万起（一线城市/经常跑高速 300 万）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 车损险是否投保（旧车、残值低的可权衡）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>座位险</strong>（司机/乘客）保额——常被人忽略，但撞了亲友时是最实用的</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> <strong>医保外用药责任</strong>（三者险不赔医保目录外费用，附加险很便宜）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 保单适用的是<strong>改革前还是改革后</strong>的条款（看保单年度）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否含<strong>不计免赔</strong>（改革后通常并入主险）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 使用性质：<strong>营运 / 非营运</strong>——如实申报，<strong>真跑营运就按营运投保</strong></div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 是否有<strong>绝对免赔额</strong>约定</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 车辆改装情况是否申报</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 续保时的<strong>无赔款优待系数（NCD）</strong>是否正确</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 免责条款页面<strong>截屏 / 拍照</strong>（尤其电子投保）</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 增值服务（道路救援、代驾、年检代办）</div>\n<hr>\n<h2 id=\"s21\">4. 事故后 60 分钟动作清单</h2>\n<ol>\n<li><strong>先救人、再报警</strong>（122 / 110），有人伤的叫 120。</li>\n<li><strong>保护现场、拍照取证</strong>：车辆位置、碰撞部位、路面标线、交通标志、刹车痕迹、对方车牌、周边环境、行车记录仪视频（<strong>立即导出，会被覆盖</strong>）。</li>\n<li><strong>立即报保险</strong>（多数条款约定 48 小时内，及时报案最稳妥）。</li>\n<li><strong>取得交通事故认定书</strong>——这是后续一切争议的基础文件。对认定书有异议的，在法定期限内申请复核。</li>\n<li><strong>不要随便认责、不要随便签\"一次性了结\"协议</strong>。</li>\n<li>定损时<strong>在场</strong>，对定损项目与金额有异议的<strong>当场书面提出</strong>；必要时自行委托评估。</li>\n<li>维修期间保留<strong>维修工单、进场与交车时间</strong>（停运损失的关键证据）。</li>\n<li>人伤案件：保留医疗费票据、误工证明、护理证明、伤残鉴定。</li>\n<li>所有沟通<strong>留痕</strong>，索取<strong>书面</strong>拒赔/核定通知。</li>\n</ol>\n<hr>\n<h2 id=\"s22\">5. 五个常见误解</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody>\n<tr><td>\"我买了全险，什么都赔\"</td><td>没有\"全险\"这回事。每个险种各有责任范围与免责</td></tr>\n<tr><td>\"酒驾商业险一定不赔\"</td><td>通常如此，但保险人<strong>仍须证明已提示</strong>；且交强险对人身损害仍有垫付规则</td></tr>\n<tr><td>\"跑了几次顺风车就会被拒赔\"</td><td>广东口径综合判断，低频真实合乘一般不构成危险程度显著增加</td></tr>\n<tr><td>\"对方全责，我的保险公司不管\"</td><td>可以申请<strong>代位求偿</strong>（车损险项下）</td></tr>\n<tr><td>\"保险公司说多少就是多少\"</td><td>定损可争议、可委托评估；拖延定损造成的可主张<strong>损失赔偿</strong>（§23③）</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s23\">6. 与其他页面的关系</h2>\n<ul>\n<li><strong>通用打法</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a>（武器一 提示说明、武器三 隐性免责、武器八 代位求偿）</li>\n<li><strong>流程与文书</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>广东案例</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E8%BD%A6%E9%99%A9%E4%B8%8E%E8%B4%A2%E4%BA%A7%E9%99%A9\">《车险 / 财产险 / 责任险 · 案例库（广东）》</a>；<strong>A 级判例精读</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7-%E7%AC%AC%E4%BA%8C%E8%BE%91\">《广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "0. 速查卡片（本页最重要的 14 条）"}, {"id": "s2", "lv": 2, "t": "1. 险种地图"}, {"id": "s3", "lv": 2, "t": "2. 争点逐解"}, {"id": "s4", "lv": 3, "t": "V1 · 酒驾、醉驾、无证驾驶、逃逸"}, {"id": "s5", "lv": 3, "t": "V2 · 改变使用性质 / 营运（网约车、顺风车、货拉拉）"}, {"id": "s11", "lv": 3, "t": "V3 · 车辆未年检、改装"}, {"id": "s12", "lv": 3, "t": "V4 · 高保低赔"}, {"id": "s13", "lv": 3, "t": "V5 · 免赔率与不计免赔"}, {"id": "s14", "lv": 3, "t": "V6 · 停运损失与迟延定损"}, {"id": "s15", "lv": 3, "t": "V7 · 代位求偿"}, {"id": "s16", "lv": 3, "t": "V8 · 责任保险与第三者的直接请求权"}, {"id": "s17", "lv": 3, "t": "V9 · 新能源汽车专属条款"}, {"id": "s18", "lv": 3, "t": "V10 · 未及时报案 / 未及时通知"}, {"id": "s19", "lv": 3, "t": "V11 · 特殊主体与情形"}, {"id": "s20", "lv": 2, "t": "3. 投保前 checklist"}, {"id": "s21", "lv": 2, "t": "4. 事故后 60 分钟动作清单"}, {"id": "s22", "lv": 2, "t": "5. 五个常见误解"}, {"id": "s23", "lv": 2, "t": "6. 与其他页面的关系"}], "text": "车险 · 纠纷全解 本页自包含 ——读这一页不需要翻其他文件。 一句话定位 ：车险是普通人接触最多、也最容易在\" 我以为能赔 \"上栽跟头的险种。它的两大主战场： ① 免责情形（酒驾、无证、逃逸、营运）；② 赔多少（高保低赔、免赔率、停运损失） 。 0. 速查卡片（本页最重要的 14 条） 要点 依据 1 交强险 优先赔付（有责限额内）， 不赔本车人员和被保险人财产损失 《机动车交通事故责任强制保险条例》 2 交强险 垫付后追偿 的情形：无证、醉酒、被盗抢期间肇事、故意制造事故 条例 §22 3 商业险免责条款涉及的若是 法律、行政法规的禁止性规定 （酒驾、无证、逃逸），保险人 提示后 即可生效，无需\"明确说明\" 解释二 §10 4 但仍须证明\"已提示\" ——这是保险人最容易失守的一环 5 危险程度显著增加 （改变使用性质、改装等）未通知的，因此发生事故不赔 保险法 §52 6 是否构成\"显著增加\"，综合判断： 用途、使用范围、所处环境、改装、使用人/管理人改变、持续时间 等 解释四 §4 7 增加的危险 属于订约时保险人预见或应当预见的承保范围 的， 不构成 显著增加 解释四 §4 8 广东口径： 不是\"只要跑过顺风车就拒赔\" ，看接单频率、路线匹配度、收费性质、是否以营运为目的 9 代位求偿 ：保险人赔付后在赔偿金额范围内代位行使被保险人对第三者的请求权 保险法 §60 10 保险人 不得 对被保险人的 家庭成员或其组成人员 行使代位权， 故意 造成的除外 保险法 §62 11 未及时核定的（复杂情形 30 日 ），应赔偿因此受到的 损失 保险法 §23③ 12 未及时通知的后果，限于\"致使事故性质、原因、损失程度 难以确定 \"的 部分 保险法 §21 13 诉讼时效 3 年 （§26 写 2 年，法院按民法典适用 3 年），自知道或应当知道保险事故发生之日起算 保险法 §26① + 民法典 §188 14 事故发生后被保险人/受益人 起诉保险人 的，保险人不得以\"未先向第三者索赔\"抗辩 解释二 §19 1. 险种地图 ⚠️ 2020 年车险综合改革要点 ：车损险主险已 整合 盗抢险、玻璃单独破碎险、自燃损失险、发动机涉水损失险、不计免赔率险、无法找到第三方特约险等。所以 老保单与新保单的责任结构不同 ——看保单年度。 比喻 ：交强险像\"最低工资\"——法律强制、人人都有，但出了大事远远不够。商业三者险才是真正兜底的那笔钱。 省那几百块保费把三者险买成 50 万，是拿全家的房子赌一次事故。 2. 争点逐解 V1 · 酒驾、醉驾、无证驾驶、逃逸 规则 这类情形属 法律、行政法规的禁止性规定 。依 解释二 §10 ：保险人将法律、行政法规中的禁止性规定情形作为免责事由的，保险人 作出提示后 ，投保人、被保险人以\"未明确说明\"为由主张该条款不生效的， 法院不予支持 。 所以 ：这类条款只需 提示 ，不需\"明确说明\"。 但是 —— 保险人仍须证明自己\"提示\"过 （加粗、加黑、单独印制、投保人签字确认等）。这是最常被攻破的环节。 破解检查清单 检查项 说明 保险人是否提交了 有投保人签名确认 的投保单/免责事项说明书？ 没有 → 提示未完成 电子投保的，是否展示了免责条款页面、有无强制阅读/勾选？ 网页未做的，认定未提示（解释二 §12 的反向推论） 该情形是否 确属 法律、行政法规的禁止性规定？ 例如\"未按规定年检\"是 规章/管理条例 层面的义务，性质有争议 是否属于 醉酒 还是仅\"饮酒后驾驶\"？ 免责条款的射程以条文表述为准，表述不明的 → §30 逃逸 的认定 须有交通事故认定书的认定，或生效刑事文书；主观上须为 逃避法律追究 因果关系 逃逸与事故发生、损失扩大之间是否有因果关系 ⚠️ 重要区分 ：交强险与商业险的处理不同。 交强险 ：条例 §22 情形下，保险人 在交强险责任限额内垫付 抢救费用，并 有权向致害人追偿 ；对 财产损失 ，交强险 不承担 赔偿责任。 商业三者险 ：依免责条款拒赔（需提示）。 V2 · 改变使用性质 / 营运（网约车、顺风车、货拉拉） 这是近年车险最高频的争议，也是广东判例最集中的地方。⚠️ 本节的通说在 2025 2026 年判例中被部分修正，务必按新版打。 规则 保险法 §52：保险标的的 危险程度显著增加 的，被保险人应按合同约定 及时通知 保险人；未履行通知义务，因危险程度显著增加而发生的保险事故，保险人 不承担赔偿责任 。 解释四 §4 综合判断因素： 用途改变、使用范围改变、所处环境变化、改装、使用人或管理人改变、持续时间 ，以及其他可能导致危险程度显著增加的因素。 关键但书 ：增加的危险 属于订立合同时保险人预见或者应当预见的承保范围 的， 不构成 危险程度显著增加。 🔥 修正一：§52 的通知义务是 法定义务 ，提示说明义务这张牌打不了 湛江中院 (2025)粤08民终951号（顺风车 + 特惠快车，接单 1895 次）： 保险标的物的危险程度显著增加的，被保险人应当按照合同约定及时通知保险人， 该通知义务是被保险人的法定义务，并不是根据双方在保险合同中的约定而产生的义务 。 周某上诉主张……未就免责条款向其履行提示和明确说明义务，不能免除赔偿责任。 如前所述，车辆危险程度显著增加时，被保险人的通知义务属于法定义务，不是约定义务，周某该主张系其理解错误，于法无据，本院不予支持。 → 营运车案件只剩两张牌 ：① 证明 没有 改变使用性质；② 证明危险程度 未显著增加 。不要再花力气打提示说明义务。 🔥 修正二：\"事故发生时没在接单\"不构成抗辩 事发前该车辆用于营运导致被保险车辆危险程度显著增加的事实 并不因其事发当时未进行运营而改变 。（中山中院 (2025)粤20民终1136号） （此前通说把\"出险时是否在营运\"当第一分水岭，该说法已被本判例否定， 以本节为准 。） 顺风车 vs 营运：法院的四项判定标准（四案归纳） 要素 仍属顺风车（不营运） 已构成营运（保险人免责） 接单次数 偶发、个位数 47 次 / 1548 次 / 1895 次 / 2271 单 路线 相对固定、以既定目的地为终点 起点终点不固定、跨市、跨多区县 时间跨度 短期 154 天 / 785 天 目的 分摊出行成本、免费互助 收取报酬、营利 A 公司关于该车用于营运的主张已达到 高度盖然性 ，可予以认定。（中山 (2025)粤20民终2567号，47 单跨市即认定） ⚠️ 特别提示 ： \"特惠快车\" = 营运 。湛江中院 (2025)粤08民终951号： 特惠快车业务是完全按照乘客的需求意愿提供的 独立的非拼车的搭乘收费服务 ，已属于营运性质。 破解路径（保险人举证，标准很高） 东莞中院 (2026)粤19民终1493号——保险人 举证不足 ，营运主张不成立： 粤SXXX 汽车外观没有明显营运标识……举证的手机截图 没有具体身份、车辆牌号等平台注册信息 ，……缺乏营运的外观特征……平台记录并未反映可以 确定与简某存在直接联系 的内容……事故调查也 未询问简某 关于手机截图、平台记录的情况。 质证三问（答不上来即主张不成立） 1. 截图里的 账号注册人是谁 ？有没有身份证信息？ 2. 截图里的 车牌号 是多少？ 3. 有没有就这些截图 向当事人做过询问笔录 ？当事人是否确认过？ 另外 ：该案保险人搬出\"车险电子化实名投保系统由监管部门统一开发、行业协会已发文明确即视为已履行提示说明义务\"， 法院未采纳 。这个挡箭牌以后可以直接顶回去。 防范 真跑营运就按营运投保。 四案口径完全一致（中山 2、湛江 1、揭阳 1），接单量一旦过百、路线跨市，基本必输。营运保费差额远低于商业险整体拒赔的代价。 ⚠️ 还有一个不利因素 ：揭阳中院 (2026)粤52民终425号认定—— 在……已提供有投保人陈某甲签名的投保单，且 陈某甲连续多年在同一保险公司投保 的情况下，应认定……已对免责条款尽到明确说明义务。 即 \"连续多年在同一家投保\"会被当作对你不利的证据 。 V3 · 车辆未年检、改装 未年检 属行政违法行为，但 是否属\"法律、行政法规的禁止性规定\" 存在争议（道交法层面有要求，但\"未经检验合格不得上路\"的表述与免责条款的对应关系需具体审查）。 关键抗辩： 未年检与事故之间有无因果关系 。若事故纯由他方造成、车辆机械状况无问题，可主张不适用免责。 条款表述若过于宽泛（\"未按规定检验或检验不合格，保险人均不赔\"），可主张加重责任（§19）+ 不利解释（§30）。 改装 属解释四 §4 列举的\"危险程度显著增加\"因素之一，但要看 改装的性质 （外观贴膜 vs 动力系统改装 vs 改变车辆结构）。 轻微改装、不影响安全性能的，主张不构成显著增加。 保险人须证明改装与事故的因果关系。 V4 · 高保低赔 场景 ：按新车购置价（或约定的较高保险金额）收取保费，出险全损时按 出险时的实际价值（折旧后） 赔偿。 争议实质 ：保险金额高于保险价值的部分，投保人付了保费却得不到保障。 规则 保险法 §55：投保人和保险人 约定 保险标的的保险价值并在合同中载明的，以 约定保险价值 为赔偿计算标准；未约定保险价值的，以 保险事故发生时保险标的的实际价值 为赔偿计算标准。 保险金额不得超过保险价值 ；超过的部分无效，保险人应 退还 相应的保险费（§55③）。 破解路径 1. 看合同是否 约定并载明了保险价值 。约定了 → 按约定赔；没约定 → 按实际价值。 2. 按新车价收保费、按折旧价赔付的，主张 违反对价平衡与诚实信用 ，且违反 §55 的\"超过部分无效并退费\"规则。 3. 主张保险人未尽说明义务（对\"保险金额/保险价值/赔偿计算方式\"这一核心条款未明确说明）。 4. 监管层面：车险条款由行业统一制定（中国保险行业协会条款），仍应适用上述规则。 V5 · 免赔率与不计免赔 改革背景 ：2020 年车险综合改革后， 不计免赔率险已并入主险 ，通常默认包含。但仍需注意： 项目 说明 绝对免赔额（如\"每次事故免赔 2000 元\"） 若约定，属 免赔额 条款 → 需提示说明（解释二 §9） 无法找到第三方的免赔率 改革后已并入主险，通常不再单独扣减 违反安全装载规定 部分条款约定因此增加免赔率 → 属比例给付条款 → 需提示说明 V6 · 停运损失与迟延定损 停运损失 （营运车辆常见） 保险法 §23③：保险人未及时履行赔付义务的， 除支付保险金外，应当赔偿被保险人或者受益人因此受到的损失 。 因保险人 拖延定损、拖延赔付 导致车辆被修理厂留置、无法营运的，停运损失可主张由保险人赔偿。 举证 ：营运资质（道路运输证、网约车运输证）、事故前 3 6 个月的平均营运收入 、维修时长、停运期间的银行流水/平台流水。 迟延定损 情形复杂的 30 日内 核定（§23①），自 初次收到索赔请求及资料之日 起算（解释二 §15）。 实务打法： 书面催告 + 固定时间节点 。每一次沟通都留书面记录（快递单、邮件、有时间戳的聊天记录）。 车辆被长期留置的，可考虑 先行提车 （自付维修费后索赔），避免损失扩大（同时注意 §57 的施救减损义务，被保险人也有减损义务）。 ⚠️ 减损义务（保险法 §57） ：保险事故发生后，被保险人应尽力采取必要措施防止或减少损失；所支付的 必要、合理费用 由保险人承担。解释四 §6： 措施未产生实际效果 不能作为保险人的抗辩。 V7 · 代位求偿 规则（保险法 §60 63） 1. 因 第三者 对保险标的的损害造成保险事故的，保险人自 向被保险人赔偿保险金之日起 ，在 赔偿金额范围内 代位行使被保险人对第三者的请求权。 2. 被保险人 已获赔部分 之外，仍可向第三者索赔（§60③）。 3. 不得 对被保险人的 家庭成员或其组成人员 行使代位权， 故意 造成的除外（§62）。 4. 被保险人 弃权 的后果见解释四 §9。 被保险人视角的实战要点 情形 处理 己方无责，对方全责但对方不赔/找不到 向 自己的保险公司 申请代位求偿（车损险项下），由保险公司先赔再去追对方 担心代位后影响自己 代位求偿 不算出险 的认定看条款与监管口径；实务中无责方申请代位通常不影响 保险人赔付后向自己追偿 检查自己是否属 §62 的排除对象；是否有 §61 的情形（被保险人放弃对第三者的请求权） 被保险人 已放弃 对第三者的权利 解释四 §9：订立合同前已放弃的，保险人相应部分不能代位；订立时保险人已询问而未告知的，可请求返还相应保险金 ⚠️ 关键提示 ：事故后 不要随便签\"一次性了结、放弃追偿\"的协议 ——可能触发 §61，导致保险人扣减或要求返还保险金。 代位求偿中的保险人抗辩（东莞中院 (2026)粤19民终1493号） ：保险人向第三者代位求偿时，第三者一方的保险公司常以\"被保险人改变使用性质从事营运\"拒赔。 该抗辩由主张方举证，且标准很高 ——须能锁定到具体的人、车、订单。该案保险人举证不足，判赔。详见L2 案例库/广东二审判决原文精读 A级 第二辑 V A4。 V8 · 责任保险与第三者的直接请求权 规则（保险法 §65 + 解释四 §14 §20） 1. 被保险人 怠于请求 的，第三者有权 直接 向保险人请求赔偿保险金（§65②）。 2. \"怠于请求\"的认定（解释四 §15）：被保险人对第三者的赔偿责任 已经确定 （如生效判决确认），被保险人 不履行 赔偿，且第三者起诉保险人时被保险人 尚未 向保险人提出直接向第三者赔偿的请求。 3. 连带责任 （解释四 §16）：共同侵权下保险人以连带责任超出被保险人责任份额为由拒赔的， 不予支持 ；保险人赔付后可向其他连带责任人追偿。 4. 赔偿责任经生效判决确认并进入执行、 未获清偿 的，第三者请求保险人赔偿的，保险人以\"已进入执行程序\"抗辩的， 不予支持 （解释四 §17）。 5. 责任保险的 诉讼时效 自被保险人对第三者应负的赔偿责任 确定之日 起算（解释四 §18）——这是一个容易算错的时效。 V9 · 新能源汽车专属条款 要点 （2021 年中国保险行业协会发布新能源车专属条款） 项目 说明 三电系统 （电池、电机、电控） 纳入车损险保障范围 自燃 含起火燃烧（传统车险的\"自燃\"定义与新能源条款不同） 电池衰减 通常属 除外 （自然损耗不属于保险事故），这是主要争议点 充电期间 的损失 专属条款通常纳入保障，注意条款表述与除外 涉水 新能源车涉水的定损与电池安全性评估争议较多 争议预判 ：电池衰减 vs 意外损坏的区分（需鉴定）、充电自燃的责任归属（车损险 vs 产品责任）、涉水后电池隐性损伤的定损。 V10 · 未及时报案 / 未及时通知 规则（保险法 §21） ：故意或者因 重大过失 未及时通知，致使保险事故的性质、原因、损失程度等 难以确定 的，保险人对 无法确定的部分 不承担责任。 注意三个限定 （这是重要的抗辩武器）： 1. 须为 故意或重大过失 （一般过失不适用）； 2. 须 致使事故难以确定 ； 3. 责任范围限于\" 无法确定的部分 \"，不是全部。 实务 ：单方事故未报警、未保留现场的，容易被保险人主张\"无法核定\"。所以 事故后第一件事是报警 + 报保险 + 拍照 。 V11 · 特殊主体与情形 情形 要点 借车给他人 看条款对\"被保险人允许的合格驾驶人\"的约定；使用人变更属解释四 §4 的因素之一 车辆转让未过户 解释四 §1：保险标的已交付受让人但未办过户登记，承担风险的受让人可主张行使被保险人权利 转让后未通知保险人 保险法 §49；解释四 §5：依法及时发出转让通知后、保险人答复前发生事故的，被保险人/受让人可主张赔付 驾驶证逾期未换证 / 准驾车型不符 看是否属免责条款射程、是否属\"法律、行政法规的禁止性规定\"、表述是否明确 实习期上高速 属规章层面要求，是否构成免责事由常引发争议 → §30 不利解释 3. 投保前 checklist [ ] 三者险保额 ：建议 200 万起（一线城市/经常跑高速 300 万） [ ] 车损险是否投保（旧车、残值低的可权衡） [ ] 座位险 （司机/乘客）保额——常被人忽略，但撞了亲友时是最实用的 [ ] 医保外用药责任 （三者险不赔医保目录外费用，附加险很便宜） [ ] 保单适用的是 改革前还是改革后 的条款（看保单年度） [ ] 是否含 不计免赔 （改革后通常并入主险） [ ] 使用性质： 营运 / 非营运 ——如实申报， 真跑营运就按营运投保 [ ] 是否有 绝对免赔额 约定 [ ] 车辆改装情况是否申报 [ ] 续保时的 无赔款优待系数（NCD） 是否正确 [ ] 免责条款页面 截屏 / 拍照 （尤其电子投保） [ ] 增值服务（道路救援、代驾、年检代办） 4. 事故后 60 分钟动作清单 1. 先救人、再报警 （122 / 110），有人伤的叫 120。 2. 保护现场、拍照取证 ：车辆位置、碰撞部位、路面标线、交通标志、刹车痕迹、对方车牌、周边环境、行车记录仪视频（ 立即导出，会被覆盖 ）。 3. 立即报保险 （多数条款约定 48 小时内，及时报案最稳妥）。 4. 取得交通事故认定书 ——这是后续一切争议的基础文件。对认定书有异议的，在法定期限内申请复核。 5. 不要随便认责、不要随便签\"一次性了结\"协议 。 6. 定损时 在场 ，对定损项目与金额有异议的 当场书面提出 ；必要时自行委托评估。 7. 维修期间保留 维修工单、进场与交车时间 （停运损失的关键证据）。 8. 人伤案件：保留医疗费票据、误工证明、护理证明、伤残鉴定。 9. 所有沟通 留痕 ，索取 书面 拒赔/核定通知。 5. 五个常见误解 误解 正解 \"我买了全险，什么都赔\" 没有\"全险\"这回事。每个险种各有责任范围与免责 \"酒驾商业险一定不赔\" 通常如此，但保险人 仍须证明已提示 ；且交强险对人身损害仍有垫付规则 \"跑了几次顺风车就会被拒赔\" 广东口径综合判断，低频真实合乘一般不构成危险程度显著增加 \"对方全责，我的保险公司不管\" 可以申请 代位求偿 （车损险项下） \"保险公司说多少就是多少\" 定损可争议、可委托评估；拖延定损造成的可主张 损失赔偿 （§23③） 6. 与其他页面的关系 通用打法 ：见L0 打法层/01 八把通用武器（武器一 提示说明、武器三 隐性免责、武器八 代位求偿） 流程与文书 ：见L0 打法层/02 维权操作全流程 广东案例 ：L2 案例库/广东案例 车险与财产险； A 级判例精读 ：L2 案例库/广东二审判决原文精读 A级 第二辑 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L1-险种层/06-财产险与责任险", "group": "2 · 险种深挖", "groupKey": "L1-险种层", "title": "财产险与责任险 · 纠纷全解", "order": 2, "file": "06-财产险与责任险.md", "html": "<h1 id=\"s0\">财产险与责任险 · 纠纷全解</h1>\n<blockquote><strong>本页自包含</strong>——读这一页不需要翻其他文件。<br><br><strong>一句话定位</strong>：财产险讲的是\"<strong>损失多少赔多少</strong>\"（损失补偿原则贯穿始终）；责任险讲的是\"<strong>你该赔别人的钱，保险公司替你赔</strong>\"。前者争\"定损\"，后者争\"责任是否成立、范围多大\"。<br>覆盖：<strong>家庭财产险 / 企业财产险 / 货运险 / 责任险（雇主责任、公众责任、产品责任、职业责任、诉讼保全责任）/ 宠物险等新型险种</strong>。</blockquote>\n<hr>\n<h2 id=\"s1\">0. 速查卡片（本页最重要的 12 条）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>要点</th><th>依据</th></tr></thead><tbody>\n<tr><td>1</td><td>财产保险的<strong>保险标的</strong>是财产及其有关利益；<strong>保险事故发生时被保险人对保险标的不具有保险利益的，不得请求赔偿</strong></td><td>保险法 §12、§48</td></tr>\n<tr><td>2</td><td><strong>保险价值 / 保险金额</strong>：约定保险价值的按约定；未约定的按<strong>出险时实际价值</strong></td><td>保险法 §55</td></tr>\n<tr><td>3</td><td>保险金额<strong>超过</strong>保险价值的部分<strong>无效</strong>，保险人应<strong>退还相应保费</strong></td><td>保险法 §55③</td></tr>\n<tr><td>4</td><td><strong>重复保险</strong>：各保险人赔偿总和不得超过保险价值，按比例分摊（另有约定除外）</td><td>保险法 §56</td></tr>\n<tr><td>5</td><td><strong>施救费用</strong>：防止或减少损失的<strong>必要、合理</strong>费用由保险人承担，与保险标的赔偿额<strong>分别计算</strong></td><td>保险法 §57</td></tr>\n<tr><td>6</td><td>施救措施<strong>未产生实际效果</strong>不能作为保险人抗辩理由</td><td>解释四 §6</td></tr>\n<tr><td>7</td><td><strong>代位求偿</strong>：赔付后在赔偿金额范围内代位行使对第三者的请求权</td><td>保险法 §60</td></tr>\n<tr><td>8</td><td>被保险人<strong>故意或重大过失</strong>致使保险人不能行使代位权的，保险人可<strong>扣减或要求返还</strong></td><td>解释四 §11</td></tr>\n<tr><td>9</td><td><strong>责任保险</strong>：被保险人怠于请求的，第三者可<strong>直接</strong>向保险人请求赔偿</td><td>保险法 §65②</td></tr>\n<tr><td>10</td><td>责任保险诉讼时效自<strong>被保险人对第三者的赔偿责任确定之日</strong>起算（2 年）</td><td>解释四 §18</td></tr>\n<tr><td>11</td><td>共同侵权下保险人以<strong>连带责任超份额</strong>拒赔的，不予支持；赔付后可向其他责任人追偿</td><td>解释四 §16</td></tr>\n<tr><td>12</td><td><strong>危险程度显著增加</strong>未通知的，因此发生的事故不赔</td><td>保险法 §52 + 解释四 §4</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">1. 险种地图</h2>\n<pre><code>\n财产保险\n\n├── 家庭财产险（房屋主体、装修、室内财产、盗抢、管道爆裂、居家责任）\n\n├── 企业财产险（建筑物、机器设备、存货；基本险/综合险/一切险）\n\n├── 货物运输险（陆运/水运/航空；国内水路陆路货物运输险条款）\n\n├── 工程险 / 农业险 / 信用保证保险\n\n└── 责任保险\n\n     ├── 雇主责任险（工伤之外的补充，赔企业）\n\n     ├── 公众责任险（经营场所内第三者人身/财产损害）\n\n     ├── 产品责任险（产品缺陷致害）\n\n     ├── 职业责任险（医疗、律师、会计师、董事高管责任 D&amp;O）\n\n     ├── 诉讼保全责任险（申请保全提供担保）\n\n     └── 机动车第三者责任险（见<a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F05-%E8%BD%A6%E9%99%A9\">《车险 · 纠纷全解》</a>）\n\n</code></pre>\n<hr>\n<h2 id=\"s3\">2. 财产保险争点</h2>\n<h3 id=\"s4\">P1 · 保险价值与保险金额（定值 vs 不定值）</h3>\n<p><strong>规则（保险法 §55）</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>情形</th><th>赔偿计算标准</th></tr></thead><tbody>\n<tr><td><strong>定值保险</strong>（约定保险价值并<strong>载明于合同</strong>）</td><td>以约定的保险价值为赔偿计算标准</td></tr>\n<tr><td><strong>不定值保险</strong>（未约定保险价值）</td><td>以<strong>保险事故发生时保险标的的实际价值</strong>为赔偿计算标准</td></tr>\n<tr><td><strong>保险金额 &gt; 保险价值</strong></td><td>超过部分<strong>无效</strong>，保险人应退还相应保费</td></tr>\n<tr><td><strong>保险金额 &lt; 保险价值</strong>（不足额投保）</td><td>除合同另有约定外，按<strong>保险金额与保险价值的比例</strong>承担赔偿责任</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 实务坑</strong>：不足额投保 → <strong>比例赔付</strong>。投保时为了省保费少报保额，出险时按比例打折，得不偿失。</p>\n<p><strong>家财险特别注意</strong>：房屋主体与装修的保险价值如何确定（重置价值 vs 出险时实际价值）？条款通常约定按<strong>重置价值</strong>或<strong>实际价值</strong>，差别巨大。条款表述不明的 → §30 不利解释。</p>\n<hr>\n<h3 id=\"s5\">P2 · 损失补偿原则与重复保险</h3>\n<ul>\n<li>财产保险<strong>严格适用</strong>损失补偿原则，被保险人不得因保险获利。</li>\n<li><strong>重复保险（§56）</strong>：投保人就同一保险标的、同一保险利益、同一保险事故分别与两个以上保险人订立合同，且保险金额总和超过保险价值的，各保险人赔偿总和<strong>不得超过保险价值</strong>；除合同另有约定外，各保险人按<strong>保险金额与保险金额总和的比例</strong>承担赔偿责任；投保人可就超出部分请求<strong>按比例退还保费</strong>。</li>\n<li><strong>重复投保的告知义务</strong>：重复保险的投保人应当<strong>通知</strong>各保险人。</li>\n</ul>\n<hr>\n<h3 id=\"s6\">P3 · 施救费用</h3>\n<p><strong>规则（保险法 §57）</strong>：保险事故发生时，被保险人应当尽力采取必要的措施，防止或者减少损失。保险事故发生后，被保险人为防止或者减少保险标的的损失所支付的<strong>必要的、合理的费用</strong>，由保险人承担；保险人所承担的<strong>数额在保险标的损失赔偿金额以外另行计算，最高不超过保险金额的数额</strong>。</p>\n<p><strong>要点</strong></p>\n<ol>\n<li>施救费用<strong>单独计算</strong>，不占用赔偿限额（以保险金额为上限）。</li>\n<li><strong>措施未产生实际效果</strong>不能作为保险人抗辩理由（解释四 §6）——即\"救了但没救回来，费用照样报\"。</li>\n<li>费用须<strong>必要、合理</strong>：明显过度的救援费用可能被酌减。</li>\n</ol>\n<hr>\n<h3 id=\"s7\">P4 · 危险程度显著增加（§52 + 解释四 §4）</h3>\n<p><strong>判断因素（解释四 §4）</strong>：用途改变、使用范围改变、所处环境变化、改装、使用人或管理人改变、危险程度增加持续的时间，以及其他可能导致危险程度显著增加的因素。</p>\n<p><strong><span class=\"warn\">!</span> 关键但书</strong>：增加的危险属于<strong>订立合同时保险人预见或者应当预见的承保范围</strong>的，<strong>不构成</strong>危险程度显著增加。</p>\n<p><strong>典型场景</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>场景</th><th>判断</th></tr></thead><tbody>\n<tr><td>住宅改为经营性用房（民宿、餐饮）</td><td>通常构成</td></tr>\n<tr><td>仓库内存放的物品由普通货物改为<strong>危险品</strong></td><td>构成</td></tr>\n<tr><td>出租给他人使用</td><td>看条款与是否改变用途；使用人改变是法定考虑因素</td></tr>\n<tr><td>长期空置</td><td>部分条款将其列为免责或加费情形</td></tr>\n<tr><td>装修改造</td><td>看是否显著改变风险</td></tr>\n</tbody></table></div>\n<p><strong>家财险高频争议</strong>：房屋<strong>长期无人居住</strong>（超过条款约定的天数，如 30 天/60 天）→ 很多家财险条款对此免责或减赔。这是典型的\"隐性免责\"攻击对象（提示说明义务 + 因果关系：无人居住与本次损失有无因果关系？）。</p>\n<hr>\n<h3 id=\"s8\">P5 · 🔥 \"保险标的 / 责任范围条款\"的单方限缩 = 实质免责条款</h3>\n<p><strong>这是保险人最常扛的挡箭牌</strong>：\"这不是免责条款，这是保险标的条款 / 保险责任范围条款，所以我不需要提示说明。\"</p>\n<p><strong>江门中院 (2026)粤07民终1377号（家财险把金银珠宝排除出\"室内财产\"）直接击穿</strong>：</p>\n<blockquote>案涉保险条款已明确约定保险标的为室内财产，虽然保险标的条款部分将金银、珠宝、首饰等物品排除在保险范围之外，但<strong>该部分内容实际上系对保险责任范围中的室内财产范围单方进行了限缩，限制了被保险人的权利及保险人的义务，该约定已实质上构成免责条款</strong>，除非保险公司已就该部分内容尽到提示说明义务，否则对投保人不发生法律约束力。</blockquote>\n<p><strong>判定公式</strong>：<strong>单方限缩 + 限制被保险人权利/保险人义务 = 实质免责条款 → 照样要提示说明，否则不生效。</strong></p>\n<p><strong>怎么用</strong>：拿到拒赔通知，先看保险人援引的条款在合同的哪一章。只要它说\"这是责任范围不是免责\"，直接引这段。</p>\n<h3 id=\"s9\">P6 · 🔥 损失金额无法确定时，可请求法院酌定</h3>\n<p>江门中院 (2026)粤07民终1377号（入室盗窃，金器首饰被盗，无完整购买凭证）：</p>\n<blockquote>由于盗窃事实确实存在，但因相关实物被盗使陈某不能提供更为详尽的证明材料，一审法院综合考虑<strong>举证责任分配、双方当事人利益衡平</strong>等问题，根据在案证据<strong>酌定</strong>财产损失为 5 万元，符合公平原则。</blockquote>\n<p><strong>要旨</strong>：被盗、被毁导致的举证不能 <strong>≠ 败诉</strong>。但<strong>必须主动提</strong>——\"请法院依举证责任分配与利益衡平原则酌定损失\"，别等法院自己想起来。反过来，主张超出保险金额的部分也要有证据（该案被保险人另提交金价网截图想证明超过 10 万保额，因无法查明失窃数量被驳回）。</p>\n<h3 id=\"s10\">P7 · 近因与除外责任（家财险高频）</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>损失原因</th><th>争议</th></tr></thead><tbody>\n<tr><td><strong>管道爆裂 / 渗漏</strong></td><td>是否属保障责任（有的需附加）；\"<strong>渐渐劣化、自然磨损</strong>\"除外条款的适用</td></tr>\n<tr><td><strong>暴雨 / 洪水</strong></td><td>是否达到条款定义的\"暴雨\"（气象标准）；\"<strong>进水 vs 浸泡</strong>\"的区分</td></tr>\n<tr><td><strong>台风</strong></td><td>需达到约定等级（如中心风力 8 级以上）；需气象部门证明</td></tr>\n<tr><td><strong>地震 / 海啸</strong></td><td>多数家财险<strong>除外</strong>，需单独附加</td></tr>\n<tr><td><strong>盗窃</strong></td><td>需有公安报案证明；\"<strong>无明显暴力痕迹</strong>\"除外条款</td></tr>\n<tr><td><strong>火灾 / 爆炸</strong></td><td>需消防部门的认定</td></tr>\n<tr><td><strong>自然损耗、固有瑕疵、霉变、虫蛀</strong></td><td>通常除外（属\"必然发生\"，不是保险事故）</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> \"除外但书\"攻击法</strong>：除外条款中常带但书，例如\"因<strong>地震</strong>及其次生灾害造成的损失不赔，但<strong>因此引起的火灾、爆炸</strong>造成的损失按约定赔偿\"。逐字读但书，往往是突破口。</p>\n<hr>\n<h2 id=\"s11\">3. 责任保险争点</h2>\n<h3 id=\"s12\">R1 · 责任保险的第三者直接请求权</h3>\n<p><strong>规则（保险法 §65）</strong></p>\n<ol>\n<li>保险人对<strong>被保险人给第三者造成的损害</strong>，可以依法律的规定或合同的约定，直接向该第三者赔偿保险金。</li>\n<li>被保险人<strong>怠于请求</strong>的，第三者有权<strong>直接</strong>向保险人请求赔偿保险金。</li>\n<li><strong>\"怠于请求\"的认定</strong>（解释四 §15）：被保险人对第三者的赔偿责任<strong>已确定</strong> → 被保险人<strong>不履行</strong>赔偿 → 第三者起诉保险人时，被保险人<strong>尚未</strong>向保险人提出直接向第三者赔偿的请求。</li>\n</ol>\n<p><strong>可请求的情形（解释四 §14）</strong>——被保险人可以请求保险人直接向第三者赔偿保险金的情形（如经生效判决/仲裁确定、经被保险人请求、被保险人已实际赔偿等，以条文为准）。</p>\n<p><strong>诉讼时效（解释四 §18）</strong>：商业责任险的被保险人向保险人请求赔偿保险金的诉讼时效，自<strong>被保险人对第三者应负的赔偿责任确定之日</strong>起算。<span class=\"warn\">!</span> 这与一般财产险\"自保险事故发生之日起算\"不同——<strong>责任险的时钟起算点更晚</strong>。</p>\n<hr>\n<h3 id=\"s13\">R2 · 雇主责任险</h3>\n<p><strong>要点</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>争点</th><th>说明</th></tr></thead><tbody>\n<tr><td><strong>与工伤保险的关系</strong></td><td>雇主责任险赔的是雇主依法应承担的<strong>赔偿责任</strong>；认定工伤的，工伤保险已支付部分通常<strong>不重复赔</strong>（看条款）</td></tr>\n<tr><td><strong>未参保工伤的情形</strong></td><td>未参保的雇主须自行承担工伤待遇 → 正落入雇主责任险的保障范围（这也是很多小微企业买的理由）</td></tr>\n<tr><td><strong>\"雇员\"的认定</strong></td><td>劳动关系、劳务关系、实习、劳务派遣、退休返聘——看条款对\"被保险人雇员\"的定义</td></tr>\n<tr><td><strong>职业类别与人数申报</strong></td><td>高危行业（建筑、物流、制造）常见\"未如实申报工种/人数\"拒赔，按<strong>比例赔付</strong>条款处理（需提示说明）</td></tr>\n<tr><td><strong>\"在工作过程中\"</strong></td><td>通勤、出差、团建、宿舍内受伤是否属于；看条款定义与 §30</td></tr>\n<tr><td><strong>猝死 / 职业病</strong></td><td>是否属于保障范围，看条款是否单列</td></tr>\n</tbody></table></div>\n<hr>\n<h3 id=\"s14\">R3 · 公众责任险 / 产品责任险 / 职业责任险</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>险种</th><th>核心争点</th></tr></thead><tbody>\n<tr><td><strong>公众责任险</strong>（场所责任）</td><td>\"被保险人<strong>经营/管理</strong>的场所\"的界定；\"<strong>在其经营活动中</strong>\"的界定；免责（故意、污染、食品中毒、专业服务）</td></tr>\n<tr><td><strong>产品责任险</strong></td><td>\"<strong>产品缺陷</strong>\"的认定（设计/制造/警示缺陷）；\"<strong>意外事故</strong>\"要件；<strong>召回费用</strong>通常除外；\"<strong>质量保证 vs 产品责任</strong>\"的区分（修换退属于质保，不属于责任险）</td></tr>\n<tr><td><strong>职业责任险</strong></td><td>\"<strong>专业服务中的过失/疏忽</strong>\"；<strong>故意行为</strong>绝对除外；<strong>索赔发生制 vs 事故发生制</strong>（claims-made vs occurrence，关键！）；<strong>追溯日</strong>与<strong>延长报告期</strong></td></tr>\n<tr><td><strong>董事高管责任险（D&amp;O）</strong></td><td>不当行为的界定；监管调查费用；<strong>可分性条款</strong>（故意行为是否影响其他被保险人的保障）</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 索赔发生制（claims-made）</strong>是职业责任险最大的坑：保单只保\"<strong>保险期间内首次提出索赔</strong>\"的案件，而不管事故何时发生。所以<strong>保单到期后不再续保 = 之前的业务敞口全裸</strong>。续保时注意<strong>追溯日</strong>（retroactive date）是否延续。</p>\n<hr>\n<h3 id=\"s15\">R4 · 诉讼保全责任险</h3>\n<p><strong>要点</strong>：申请人申请财产保全时提供担保的一种形式。保险公司出具保函，若保全错误造成被申请人损失，由保险公司赔偿。</p>\n<p><strong>争点</strong></p>\n<ol>\n<li><strong>\"保全错误\"的认定</strong>：以<strong>生效判决</strong>为准——申请人的诉讼请求未获支持，是否即构成保全错误？实务主流观点：须结合申请时是否尽到<strong>合理注意义务</strong>判断，并非\"败诉即错误\"。但存在裁判分歧。</li>\n<li><strong>保险责任的触发</strong>：通常需生效法律文书确认保全错误。</li>\n<li><strong>追偿</strong>：保险公司赔偿后是否可向申请人追偿（看条款与是否存在故意或重大过失）。</li>\n<li><strong>保费的承担</strong>：诉讼中，保全担保费用是否属\"合理损失\"可由败诉方承担，各地裁判不一。</li>\n</ol>\n<hr>\n<h3 id=\"s16\">R5 · 新型险种（宠物险、退货运费险、航班延误险、碎屏险等）</h3>\n<p><strong>共同特征</strong>：<strong>金额小、条款简、纠纷走投诉而非诉讼</strong>。</p>\n<p><strong>争点与打法</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>险种</th><th>高频争点</th><th>打法</th></tr></thead><tbody>\n<tr><td><strong>宠物险</strong></td><td>既往症、等待期、品种与年龄限制、指定医院、疫苗要求</td><td>同医疗险逻辑（既往症定义、紧急就医）；金额小，走 12378 投诉效率高</td></tr>\n<tr><td><strong>退货运费险</strong></td><td>理赔触发条件、赔付额与实际运费差额</td><td>平台规则 + 12315</td></tr>\n<tr><td><strong>航班延误险</strong></td><td>\"延误\"的起算（起飞 vs 到达）、取消是否算延误、天气/流量控制/机械故障的区别</td><td>看条款定义；主张保险人就\"取消不算延误\"未尽明确说明</td></tr>\n<tr><td><strong>碎屏险 / 延保</strong></td><td>\"意外损坏\"的界定、人为损坏的认定、维修方式</td><td>提示说明义务 + 不利解释</td></tr>\n<tr><td><strong>共享单车/电动车骑行险</strong></td><td>是否属营运、头盔与载人要求、免责情形</td><td>提示说明义务</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 小额纠纷的现实路径</strong>：金额几百至几千元，<strong>诉讼成本高于收益</strong>。最有效的是 <strong>12378（金融监管总局消费者投诉热线）+ 12315 + 平台投诉 + 社交媒体曝光</strong>组合拳。投诉时<strong>引用具体条款与法条</strong>（如\"依司法解释二第 9 条，该比例赔付条款未向我提示说明\"），处理效率明显高于单纯抱怨。</p>\n<hr>\n<h2 id=\"s17\">4. 与其他页面的关系</h2>\n<ul>\n<li><strong>通用打法</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a></li>\n<li><strong>流程与文书</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>广东案例</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E8%BD%A6%E9%99%A9%E4%B8%8E%E8%B4%A2%E4%BA%A7%E9%99%A9\">《车险 / 财产险 / 责任险 · 案例库（广东）》</a>；<strong>A 级判例精读</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7-%E7%AC%AC%E4%BA%8C%E8%BE%91\">《广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "0. 速查卡片（本页最重要的 12 条）"}, {"id": "s2", "lv": 2, "t": "1. 险种地图"}, {"id": "s3", "lv": 2, "t": "2. 财产保险争点"}, {"id": "s4", "lv": 3, "t": "P1 · 保险价值与保险金额（定值 vs 不定值）"}, {"id": "s5", "lv": 3, "t": "P2 · 损失补偿原则与重复保险"}, {"id": "s6", "lv": 3, "t": "P3 · 施救费用"}, {"id": "s7", "lv": 3, "t": "P4 · 危险程度显著增加（§52 + 解释四 §4）"}, {"id": "s8", "lv": 3, "t": "P5 · 🔥 \"保险标的 / 责任范围条款\"的单方限缩 = 实质免责条款"}, {"id": "s9", "lv": 3, "t": "P6 · 🔥 损失金额无法确定时，可请求法院酌定"}, {"id": "s10", "lv": 3, "t": "P7 · 近因与除外责任（家财险高频）"}, {"id": "s11", "lv": 2, "t": "3. 责任保险争点"}, {"id": "s12", "lv": 3, "t": "R1 · 责任保险的第三者直接请求权"}, {"id": "s13", "lv": 3, "t": "R2 · 雇主责任险"}, {"id": "s14", "lv": 3, "t": "R3 · 公众责任险 / 产品责任险 / 职业责任险"}, {"id": "s15", "lv": 3, "t": "R4 · 诉讼保全责任险"}, {"id": "s16", "lv": 3, "t": "R5 · 新型险种（宠物险、退货运费险、航班延误险、碎屏险等）"}, {"id": "s17", "lv": 2, "t": "4. 与其他页面的关系"}], "text": "财产险与责任险 · 纠纷全解 本页自包含 ——读这一页不需要翻其他文件。 一句话定位 ：财产险讲的是\" 损失多少赔多少 \"（损失补偿原则贯穿始终）；责任险讲的是\" 你该赔别人的钱，保险公司替你赔 \"。前者争\"定损\"，后者争\"责任是否成立、范围多大\"。 覆盖： 家庭财产险 / 企业财产险 / 货运险 / 责任险（雇主责任、公众责任、产品责任、职业责任、诉讼保全责任）/ 宠物险等新型险种 。 0. 速查卡片（本页最重要的 12 条） 要点 依据 1 财产保险的 保险标的 是财产及其有关利益； 保险事故发生时被保险人对保险标的不具有保险利益的，不得请求赔偿 保险法 §12、§48 2 保险价值 / 保险金额 ：约定保险价值的按约定；未约定的按 出险时实际价值 保险法 §55 3 保险金额 超过 保险价值的部分 无效 ，保险人应 退还相应保费 保险法 §55③ 4 重复保险 ：各保险人赔偿总和不得超过保险价值，按比例分摊（另有约定除外） 保险法 §56 5 施救费用 ：防止或减少损失的 必要、合理 费用由保险人承担，与保险标的赔偿额 分别计算 保险法 §57 6 施救措施 未产生实际效果 不能作为保险人抗辩理由 解释四 §6 7 代位求偿 ：赔付后在赔偿金额范围内代位行使对第三者的请求权 保险法 §60 8 被保险人 故意或重大过失 致使保险人不能行使代位权的，保险人可 扣减或要求返还 解释四 §11 9 责任保险 ：被保险人怠于请求的，第三者可 直接 向保险人请求赔偿 保险法 §65② 10 责任保险诉讼时效自 被保险人对第三者的赔偿责任确定之日 起算（2 年） 解释四 §18 11 共同侵权下保险人以 连带责任超份额 拒赔的，不予支持；赔付后可向其他责任人追偿 解释四 §16 12 危险程度显著增加 未通知的，因此发生的事故不赔 保险法 §52 + 解释四 §4 1. 险种地图 2. 财产保险争点 P1 · 保险价值与保险金额（定值 vs 不定值） 规则（保险法 §55） 情形 赔偿计算标准 定值保险 （约定保险价值并 载明于合同 ） 以约定的保险价值为赔偿计算标准 不定值保险 （未约定保险价值） 以 保险事故发生时保险标的的实际价值 为赔偿计算标准 保险金额 保险价值 超过部分 无效 ，保险人应退还相应保费 保险金额 < 保险价值 （不足额投保） 除合同另有约定外，按 保险金额与保险价值的比例 承担赔偿责任 ⚠️ 实务坑 ：不足额投保 → 比例赔付 。投保时为了省保费少报保额，出险时按比例打折，得不偿失。 家财险特别注意 ：房屋主体与装修的保险价值如何确定（重置价值 vs 出险时实际价值）？条款通常约定按 重置价值 或 实际价值 ，差别巨大。条款表述不明的 → §30 不利解释。 P2 · 损失补偿原则与重复保险 财产保险 严格适用 损失补偿原则，被保险人不得因保险获利。 重复保险（§56） ：投保人就同一保险标的、同一保险利益、同一保险事故分别与两个以上保险人订立合同，且保险金额总和超过保险价值的，各保险人赔偿总和 不得超过保险价值 ；除合同另有约定外，各保险人按 保险金额与保险金额总和的比例 承担赔偿责任；投保人可就超出部分请求 按比例退还保费 。 重复投保的告知义务 ：重复保险的投保人应当 通知 各保险人。 P3 · 施救费用 规则（保险法 §57） ：保险事故发生时，被保险人应当尽力采取必要的措施，防止或者减少损失。保险事故发生后，被保险人为防止或者减少保险标的的损失所支付的 必要的、合理的费用 ，由保险人承担；保险人所承担的 数额在保险标的损失赔偿金额以外另行计算，最高不超过保险金额的数额 。 要点 1. 施救费用 单独计算 ，不占用赔偿限额（以保险金额为上限）。 2. 措施未产生实际效果 不能作为保险人抗辩理由（解释四 §6）——即\"救了但没救回来，费用照样报\"。 3. 费用须 必要、合理 ：明显过度的救援费用可能被酌减。 P4 · 危险程度显著增加（§52 + 解释四 §4） 判断因素（解释四 §4） ：用途改变、使用范围改变、所处环境变化、改装、使用人或管理人改变、危险程度增加持续的时间，以及其他可能导致危险程度显著增加的因素。 ⚠️ 关键但书 ：增加的危险属于 订立合同时保险人预见或者应当预见的承保范围 的， 不构成 危险程度显著增加。 典型场景 场景 判断 住宅改为经营性用房（民宿、餐饮） 通常构成 仓库内存放的物品由普通货物改为 危险品 构成 出租给他人使用 看条款与是否改变用途；使用人改变是法定考虑因素 长期空置 部分条款将其列为免责或加费情形 装修改造 看是否显著改变风险 家财险高频争议 ：房屋 长期无人居住 （超过条款约定的天数，如 30 天/60 天）→ 很多家财险条款对此免责或减赔。这是典型的\"隐性免责\"攻击对象（提示说明义务 + 因果关系：无人居住与本次损失有无因果关系？）。 P5 · 🔥 \"保险标的 / 责任范围条款\"的单方限缩 = 实质免责条款 这是保险人最常扛的挡箭牌 ：\"这不是免责条款，这是保险标的条款 / 保险责任范围条款，所以我不需要提示说明。\" 江门中院 (2026)粤07民终1377号（家财险把金银珠宝排除出\"室内财产\"）直接击穿 ： 案涉保险条款已明确约定保险标的为室内财产，虽然保险标的条款部分将金银、珠宝、首饰等物品排除在保险范围之外，但 该部分内容实际上系对保险责任范围中的室内财产范围单方进行了限缩，限制了被保险人的权利及保险人的义务，该约定已实质上构成免责条款 ，除非保险公司已就该部分内容尽到提示说明义务，否则对投保人不发生法律约束力。 判定公式 ： 单方限缩 + 限制被保险人权利/保险人义务 = 实质免责条款 → 照样要提示说明，否则不生效。 怎么用 ：拿到拒赔通知，先看保险人援引的条款在合同的哪一章。只要它说\"这是责任范围不是免责\"，直接引这段。 P6 · 🔥 损失金额无法确定时，可请求法院酌定 江门中院 (2026)粤07民终1377号（入室盗窃，金器首饰被盗，无完整购买凭证）： 由于盗窃事实确实存在，但因相关实物被盗使陈某不能提供更为详尽的证明材料，一审法院综合考虑 举证责任分配、双方当事人利益衡平 等问题，根据在案证据 酌定 财产损失为 5 万元，符合公平原则。 要旨 ：被盗、被毁导致的举证不能 ≠ 败诉 。但 必须主动提 ——\"请法院依举证责任分配与利益衡平原则酌定损失\"，别等法院自己想起来。反过来，主张超出保险金额的部分也要有证据（该案被保险人另提交金价网截图想证明超过 10 万保额，因无法查明失窃数量被驳回）。 P7 · 近因与除外责任（家财险高频） 损失原因 争议 管道爆裂 / 渗漏 是否属保障责任（有的需附加）；\" 渐渐劣化、自然磨损 \"除外条款的适用 暴雨 / 洪水 是否达到条款定义的\"暴雨\"（气象标准）；\" 进水 vs 浸泡 \"的区分 台风 需达到约定等级（如中心风力 8 级以上）；需气象部门证明 地震 / 海啸 多数家财险 除外 ，需单独附加 盗窃 需有公安报案证明；\" 无明显暴力痕迹 \"除外条款 火灾 / 爆炸 需消防部门的认定 自然损耗、固有瑕疵、霉变、虫蛀 通常除外（属\"必然发生\"，不是保险事故） ⚠️ \"除外但书\"攻击法 ：除外条款中常带但书，例如\"因 地震 及其次生灾害造成的损失不赔，但 因此引起的火灾、爆炸 造成的损失按约定赔偿\"。逐字读但书，往往是突破口。 3. 责任保险争点 R1 · 责任保险的第三者直接请求权 规则（保险法 §65） 1. 保险人对 被保险人给第三者造成的损害 ，可以依法律的规定或合同的约定，直接向该第三者赔偿保险金。 2. 被保险人 怠于请求 的，第三者有权 直接 向保险人请求赔偿保险金。 3. \"怠于请求\"的认定 （解释四 §15）：被保险人对第三者的赔偿责任 已确定 → 被保险人 不履行 赔偿 → 第三者起诉保险人时，被保险人 尚未 向保险人提出直接向第三者赔偿的请求。 可请求的情形（解释四 §14） ——被保险人可以请求保险人直接向第三者赔偿保险金的情形（如经生效判决/仲裁确定、经被保险人请求、被保险人已实际赔偿等，以条文为准）。 诉讼时效（解释四 §18） ：商业责任险的被保险人向保险人请求赔偿保险金的诉讼时效，自 被保险人对第三者应负的赔偿责任确定之日 起算。⚠️ 这与一般财产险\"自保险事故发生之日起算\"不同—— 责任险的时钟起算点更晚 。 R2 · 雇主责任险 要点 争点 说明 与工伤保险的关系 雇主责任险赔的是雇主依法应承担的 赔偿责任 ；认定工伤的，工伤保险已支付部分通常 不重复赔 （看条款） 未参保工伤的情形 未参保的雇主须自行承担工伤待遇 → 正落入雇主责任险的保障范围（这也是很多小微企业买的理由） \"雇员\"的认定 劳动关系、劳务关系、实习、劳务派遣、退休返聘——看条款对\"被保险人雇员\"的定义 职业类别与人数申报 高危行业（建筑、物流、制造）常见\"未如实申报工种/人数\"拒赔，按 比例赔付 条款处理（需提示说明） \"在工作过程中\" 通勤、出差、团建、宿舍内受伤是否属于；看条款定义与 §30 猝死 / 职业病 是否属于保障范围，看条款是否单列 R3 · 公众责任险 / 产品责任险 / 职业责任险 险种 核心争点 公众责任险 （场所责任） \"被保险人 经营/管理 的场所\"的界定；\" 在其经营活动中 \"的界定；免责（故意、污染、食品中毒、专业服务） 产品责任险 \" 产品缺陷 \"的认定（设计/制造/警示缺陷）；\" 意外事故 \"要件； 召回费用 通常除外；\" 质量保证 vs 产品责任 \"的区分（修换退属于质保，不属于责任险） 职业责任险 \" 专业服务中的过失/疏忽 \"； 故意行为 绝对除外； 索赔发生制 vs 事故发生制 （claims made vs occurrence，关键！）； 追溯日 与 延长报告期 董事高管责任险（D&O） 不当行为的界定；监管调查费用； 可分性条款 （故意行为是否影响其他被保险人的保障） ⚠️ 索赔发生制（claims made） 是职业责任险最大的坑：保单只保\" 保险期间内首次提出索赔 \"的案件，而不管事故何时发生。所以 保单到期后不再续保 = 之前的业务敞口全裸 。续保时注意 追溯日 （retroactive date）是否延续。 R4 · 诉讼保全责任险 要点 ：申请人申请财产保全时提供担保的一种形式。保险公司出具保函，若保全错误造成被申请人损失，由保险公司赔偿。 争点 1. \"保全错误\"的认定 ：以 生效判决 为准——申请人的诉讼请求未获支持，是否即构成保全错误？实务主流观点：须结合申请时是否尽到 合理注意义务 判断，并非\"败诉即错误\"。但存在裁判分歧。 2. 保险责任的触发 ：通常需生效法律文书确认保全错误。 3. 追偿 ：保险公司赔偿后是否可向申请人追偿（看条款与是否存在故意或重大过失）。 4. 保费的承担 ：诉讼中，保全担保费用是否属\"合理损失\"可由败诉方承担，各地裁判不一。 R5 · 新型险种（宠物险、退货运费险、航班延误险、碎屏险等） 共同特征 ： 金额小、条款简、纠纷走投诉而非诉讼 。 争点与打法 险种 高频争点 打法 宠物险 既往症、等待期、品种与年龄限制、指定医院、疫苗要求 同医疗险逻辑（既往症定义、紧急就医）；金额小，走 12378 投诉效率高 退货运费险 理赔触发条件、赔付额与实际运费差额 平台规则 + 12315 航班延误险 \"延误\"的起算（起飞 vs 到达）、取消是否算延误、天气/流量控制/机械故障的区别 看条款定义；主张保险人就\"取消不算延误\"未尽明确说明 碎屏险 / 延保 \"意外损坏\"的界定、人为损坏的认定、维修方式 提示说明义务 + 不利解释 共享单车/电动车骑行险 是否属营运、头盔与载人要求、免责情形 提示说明义务 ⚠️ 小额纠纷的现实路径 ：金额几百至几千元， 诉讼成本高于收益 。最有效的是 12378（金融监管总局消费者投诉热线）+ 12315 + 平台投诉 + 社交媒体曝光 组合拳。投诉时 引用具体条款与法条 （如\"依司法解释二第 9 条，该比例赔付条款未向我提示说明\"），处理效率明显高于单纯抱怨。 4. 与其他页面的关系 通用打法 ：见L0 打法层/01 八把通用武器 流程与文书 ：见L0 打法层/02 维权操作全流程 广东案例 ：L2 案例库/广东案例 车险与财产险； A 级判例精读 ：L2 案例库/广东二审判决原文精读 A级 第二辑 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L1-险种层/07-互联网投保专章", "group": "2 · 险种深挖", "groupKey": "L1-险种层", "title": "互联网投保专章 · 支付宝 / 微信 / App 买保险的坑与打法", "order": 2, "file": "07-互联网投保专章.md", "html": "<h1 id=\"s0\">互联网投保专章 · 支付宝 / 微信 / App 买保险的坑与打法</h1>\n<blockquote><strong>本页自包含</strong>——读这一页不需要翻其他文件。<br><br><strong>一句话定位</strong>：互联网投保和线下投保<strong>适用同一套法律规则</strong>，但举证方式完全不同。线下靠\"他有没有让你签字\"，线上靠\"<strong>页面有没有做、后台记录能不能拿出来</strong>\"。<br>覆盖：支付宝（蚂蚁保）、微信（微保）、各保险公司 App/小程序、抖音/小红书引流投保、平台搭售。</blockquote>\n<hr>\n<h2 id=\"s1\">0. 速查卡片（本页最重要的 12 条）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>要点</th><th>依据</th></tr></thead><tbody>\n<tr><td>0</td><td>🔥 <strong>电子合同：仅以\"设置勾选、弹窗\"为由主张已履行提示说明义务的，法院不予支持</strong></td><td><strong>合同编通则解释 §10③</strong></td></tr>\n<tr><td>1</td><td>网络投保的提示说明义务<strong>不降低</strong>：保险人以<strong>网页、音频、视频</strong>形式提示和明确说明的，可以认定履行了义务</td><td>解释二 §12</td></tr>\n<tr><td>2</td><td>反过来讲——<strong>网页上没做，就是没做</strong></td><td>解释二 §12 反向推论</td></tr>\n<tr><td>3</td><td><strong>举证责任仍在保险人</strong>（对其履行了明确说明义务负举证责任）</td><td>解释二 §13①</td></tr>\n<tr><td>4</td><td><span class=\"warn\">!</span> <strong>签字确认的推定</strong>：投保人在相关文书上<strong>签字、盖章或以其他形式确认</strong>的，<strong>应当认定</strong>保险人履行了义务，<strong>但有其他证据证明未履行的除外</strong></td><td>解释二 §13②</td></tr>\n<tr><td>5</td><td>所以\"我只是点了同意\"<strong>往往不够</strong>——要拿<strong>其他证据</strong>推翻该推定</td></tr>\n<tr><td>6</td><td><strong>电子数据由保险人掌握</strong>（后台页面版本、勾选状态、停留时长）→ 可申请法院责令其提交</td></tr>\n<tr><td>7</td><td><strong>投保全程录屏</strong>是最高效的自保手段，成本几乎为零</td></tr>\n<tr><td>8</td><td>禁止性规定情形的免责条款，保险人<strong>提示后</strong>即可生效（无需明确说明）</td><td>解释二 §10</td></tr>\n<tr><td>9</td><td>保险人对<strong>非保险专业术语</strong>的解释符合专业意义、或有利于投保人的，法院认可</td><td>解释二 §17</td></tr>\n<tr><td>10</td><td>合同<strong>记载内容不一致</strong>的，按解释二 §14 的规则认定（通常作有利于投保人/被保险人的认定，以条文为准）</td></tr>\n<tr><td>11</td><td><strong>首月 1 元、自动续费</strong>属需重点提示的内容；未充分提示的可主张退费</td></tr>\n<tr><td>12</td><td>投诉热线 <strong>12378</strong>（金融监管总局）+ <strong>12315</strong> + 平台投诉，小额纠纷最有效的组合</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">1. 互联网投保的法律框架</h2>\n<h3 id=\"s3\">🔥 第一武器：合同编通则司法解释第 10 条（2023-12-05 施行）</h3>\n<blockquote><strong>第十条</strong> 提供格式条款的一方在合同订立时采用<strong>通常足以引起对方注意的文字、符号、字体等明显标识</strong>，提示对方注意免除或者减轻其责任、排除或者限制对方权利等与对方有重大利害关系的<strong>异常条款</strong>的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的<strong>提示义务</strong>。<br><br>提供格式条款的一方按照对方的要求，就与对方有重大利害关系的异常条款的<strong>概念、内容及其法律后果</strong>以书面或者口头形式向对方作出<strong>通常能够理解的解释说明</strong>的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的<strong>说明义务</strong>。<br><br>提供格式条款的一方对其已经尽到提示义务或者说明义务<strong>承担举证责任</strong>。<strong>对于通过互联网等信息网络订立的电子合同，提供格式条款的一方仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持</strong>，但是其举证符合前两款规定的除外。</blockquote>\n<p><strong><span class=\"warn\">!</span> 这一条改变了互联网投保的攻防格局。</strong> 在它之前，保险人只要证明\"你勾了已阅读\"就能过关；在它之后，<strong>勾选和弹窗本身不再是有效抗辩</strong>。</p>\n<p><strong>两个真实案例已经落地这条规则</strong>（详见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E4%B8%93%E9%A2%98-%E6%8F%90%E7%A4%BA%E8%AF%B4%E6%98%8E%E4%B9%89%E5%8A%A1%E4%B8%8E%E7%94%B5%E5%AD%90%E6%8A%95%E4%BF%9D\">《专题案例 · 提示说明义务与电子投保格式条款》</a>）：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>案例</th><th>结论</th></tr></thead><tbody>\n<tr><td><strong>北京金融法院</strong>（2026-05 发布，货物运输险）</td><td>\"仅通过投保页面的勾选确认方式提示免赔额内容，该方式<strong>不足以引起投保人的合理注意</strong>，不能认定已履行法定的提示义务\"</td></tr>\n<tr><td><strong>湖南益阳赫山区法院</strong>（2024，旅游意外险，<strong>二审维持</strong>）</td><td>\"电子投保更便捷，但<strong>不能因此而降低保险人的保险义务</strong>，将免责事项与其他保险条款并列设置勾选、弹窗等方式的选项，<strong>不能认定为已尽到提示说明义务</strong>\"</td></tr>\n</tbody></table></div>\n<p><strong>用法</strong>：保险人说\"他勾选了\" → 你引 §10③ → 要求它按 §10② 举证<strong>对概念、内容、法律后果三项都作了解释说明</strong>。</p>\n<h3 id=\"s4\">旧武器仍然有效：解释二的三条</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>规则</th><th>内容</th></tr></thead><tbody>\n<tr><td><strong>解释二 §12</strong></td><td>通过网络、电话等方式订立的保险合同，保险人以<strong>网页、音频、视频</strong>等形式对免除保险人责任条款予以提示和明确说明的，人民法院<strong>可以认定</strong>其履行了提示和明确说明义务。</td></tr>\n<tr><td><strong>解释二 §13①</strong></td><td>保险人对其履行了明确说明义务<strong>负举证责任</strong>。</td></tr>\n<tr><td><strong>解释二 §13②</strong></td><td>投保人在相关文书上签字、盖章或者以其他形式确认的，<strong>应当认定</strong>保险人履行了该项义务。<strong>但另有证据证明保险人未履行的除外。</strong></td></tr>\n</tbody></table></div>\n<p><strong>读懂 §13② 的两层意思</strong></p>\n<ol>\n<li><span class=\"warn\">!</span> 投保人\"点了确认/勾选了已阅读\"→ <strong>推定</strong>保险人已履行。<strong>这一条对投保人不利，必须正视。</strong></li>\n<li>✅ 但书留下了一扇门：<strong>只要有其他证据证明保险人实际未说明，推定就可以被推翻。</strong></li>\n</ol>\n<p><strong><span class=\"warn\">!</span> 但 2023 年之后，这扇门被进一步推开了。</strong> 解释二（2013）§13② 只对\"签字/盖章/其他形式确认\"作推定；而合同编通则解释（2023）§10③ 明确规定：<strong>电子合同仅以勾选、弹窗为由的，法院不予支持</strong>。</p>\n<p><strong>实战中两条规则的张力，这样处理：</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>保险人援引</th><th>你援引</th><th>论证</th></tr></thead><tbody>\n<tr><td>解释二 §13②\"他签字/勾选确认了，应认定已履行\"</td><td><strong>合同编通则解释 §10③</strong></td><td>通则解释（2023）<strong>晚于</strong>解释二（2013），且专门针对<strong>电子合同这一具体场景</strong>作出更严格规定，网络投保应适用之</td></tr>\n<tr><td>同上</td><td><strong>解释二 §13② 但书</strong></td><td>\"另有证据证明保险人未履行的除外\" → 提交录屏、页面设计证据</td></tr>\n<tr><td>\"我们在页面做了加粗提示\"</td><td><strong>合同编通则解释 §10②</strong></td><td>提示 ≠ 说明。还须就<strong>概念、内容、法律后果</strong>三项作\"通常能够理解\"的解释说明</td></tr>\n</tbody></table></div>\n<p><strong>所以互联网投保维权，本质上是两件事：① 用 §10③ 打掉\"勾选\"抗辩；② 用录屏等证据坐实\"实际未说明\"。</strong></p>\n<p><strong>比喻</strong>：保险公司手里有一张\"他说他看过了\"的签名。法律默认这张签名有效。你要做的不是否认签名，而是<strong>拿出监控录像</strong>——证明他当时根本没有机会看。<strong>2023 年之后，法官会倾向于接受\"签字不等于看过\"这件事本身。</strong></p>\n<hr>\n<h2 id=\"s5\">2. 可以推翻推定的\"其他证据\"清单</h2>\n<p>按获取难度从低到高排列：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>证据</th><th>怎么拿</th><th>证明力</th></tr></thead><tbody>\n<tr><td><strong>投保全程录屏</strong>（手机自带屏幕录制）</td><td>投保时随手开，存云端</td><td>★★★★★ 最直接</td></tr>\n<tr><td><strong>销售页面完整快照</strong>（整页截图 + 存档链接）</td><td>截图 + 网页归档工具</td><td>★★★★★</td></tr>\n<tr><td><strong>健康告知页的逐条截图</strong></td><td>逐条截，含滚动位置</td><td>★★★★☆</td></tr>\n<tr><td><strong>与在线客服的聊天记录</strong>（追问\"这条什么意思\"）</td><td>主动提问并截图</td><td>★★★★☆</td></tr>\n<tr><td><strong>电话回访录音</strong></td><td>回访时反问\"这个免责条款是什么意思\"，保险人客服往往答不上来</td><td>★★★★☆</td></tr>\n<tr><td><strong>页面交互设计证据</strong>（是否可跳过、是否默认勾选、停留时长）</td><td>重新走一遍流程（不付款）并录屏；或申请保险人提交后台日志</td><td>★★★★☆</td></tr>\n<tr><td><strong>保险人的后台记录</strong>（页面版本、勾选状态、停留时长）</td><td><strong>申请法院责令保险人提交</strong></td><td>★★★★★</td></tr>\n<tr><td><strong>宣传页面与实际条款的差异</strong></td><td>宣传页快照 vs 条款 PDF</td><td>★★★★☆</td></tr>\n<tr><td><strong>他人同期投保的相同页面公证</strong></td><td>公证处保全证据</td><td>★★★★☆</td></tr>\n<tr><td><strong>监管部门认定</strong>（投诉后监管出具的意见）</td><td>12378 投诉</td><td>★★★☆☆</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 关键战术：申请法院责令保险人提交后台数据。</strong> 电子投保的页面版本、勾选记录、停留时长、点击流都在保险人的服务器上。依解释二 §13①，举证责任在保险人；其不提交的，主张<strong>举证不能的不利后果</strong>。</p>\n<hr>\n<h2 id=\"s6\">3. 平台页面设计的六个典型坑</h2>\n<h3 id=\"s7\">坑 1 · 健康告知<strong>默认勾选\"否\"</strong></h3>\n<p><strong>表现</strong>：健康告知一页几十个问题，全部默认\"否\"，用户一路点\"下一步\"即可完成投保。</p>\n<p><strong>打法</strong></p>\n<ol>\n<li><strong>解释二 §12</strong>：以网页形式提示和明确说明的才认定履行。默认勾选 ≠ 主动确认 ≠ 已阅读。</li>\n<li><strong>司法解释二 §6①</strong>：告知义务限于<strong>保险人询问的范围和内容</strong>，对询问范围有争议的<strong>保险人举证</strong>。默认勾选的询问，是否构成\"有效询问\"存疑。</li>\n<li>举证推翻 §13② 的推定：录屏 + 页面设计证据（证明可以不经阅读完成投保）。</li>\n<li><strong><span class=\"warn\">!</span> 但要注意</strong>：如果用户在默认\"否\"的情况下未作修改即提交，保险人仍会主张\"投保人确认了\"。所以<strong>投保时逐条核对并修改</strong>是最根本的自保。</li>\n</ol>\n<p><strong>比喻</strong>：一份体检问卷，医生替你把 50 个问题全勾了\"没有\"，让你直接签字。这份问卷在医学上没有意义，在法律上同样可疑。</p>\n<hr>\n<h3 id=\"s8\">坑 2 · \"已阅读并同意\"一行小字</h3>\n<p><strong>表现</strong>：《保险条款》《投保须知》《服务协议》《免责声明》等折叠在一条小字链接里，勾选框与正文默认关联。</p>\n<p><strong>打法</strong>：与坑 1 相同，核心是<strong>证明\"可以不阅读即完成投保\"</strong>。录屏是最有力的证据。</p>\n<hr>\n<h3 id=\"s9\">坑 3 · <strong>首月 1 元 / 首月 0.1 元 / 自动续费</strong></h3>\n<p><strong>表现</strong>：首月极低价吸引投保，次月起按正常费率扣费；默认开通自动续费/免密支付。</p>\n<p><strong>打法</strong></p>\n<ol>\n<li>这是<strong>格式条款 + 需重点提示的内容</strong>（涉及价格与持续性扣费），未显著提示的，可主张不生效。</li>\n<li>未明确告知后续费率、扣费周期的 → 主张未尽明确说明义务。</li>\n<li><strong>救济</strong>：要求退还未充分告知期间的保费；同步 12378 投诉 + 关闭免密支付。</li>\n<li>监管层面：保险销售行为管理办法对<strong>自动续费、续期扣费</strong>有明确的信息披露要求。</li>\n</ol>\n<p><strong>防范</strong>：投保后立即关闭免密支付/自动续费，改用手动续费。</p>\n<hr>\n<h3 id=\"s10\">坑 4 · <strong>宣传页承诺 ≠ 合同条款</strong></h3>\n<p><strong>表现</strong>：页面大字写\"<strong>癌症全额赔</strong>\"\"<strong>可续保至 100 岁</strong>\"\"<strong>住院即赔</strong>\"，条款里是另一套。</p>\n<p><strong>打法</strong></p>\n<ol>\n<li><strong>保存宣传页面快照</strong>（整页截图 + 时间戳/网页归档）。</li>\n<li><strong>解释二 §14</strong>：保险合同中<strong>记载的内容不一致</strong>的，按该条规定的规则认定（以条文为准，通常倾向于保护投保人/被保险人）。</li>\n<li>保险法 §30：条款有歧义的，作有利于被保险人的解释。</li>\n<li>主张<strong>销售误导</strong>/虚假宣传，同步走监管投诉。</li>\n<li><strong>保险人的代理人/合作平台</strong>在销售过程中的承诺，可主张归入保险人行为（视具体合作模式与授权关系）。</li>\n</ol>\n<hr>\n<h3 id=\"s11\">坑 5 · <strong>平台责任 vs 保险人责任互相踢皮球</strong></h3>\n<p><strong>法律框架</strong>：互联网保险业务中，存在<strong>保险人</strong>（保险公司）与<strong>互联网保险销售平台/营销宣传机构</strong>两类主体。</p>\n<div class=\"tablewrap\"><table><thead><tr><th>主体</th><th>责任</th></tr></thead><tbody>\n<tr><td><strong>保险公司</strong></td><td>保险合同的当事人，承担保险责任与说明义务</td></tr>\n<tr><td><strong>平台</strong>（如大型互联网平台的保险代理/经纪主体）</td><td>若持有<strong>保险代理/经纪牌照</strong>，承担销售环节的义务（信息披露、适当性、可回溯）</td></tr>\n</tbody></table></div>\n<p><strong>打法</strong></p>\n<ol>\n<li><strong>同时对平台与保险人主张</strong>，不要被\"这不是我们公司的事\"打发。</li>\n<li>查看页面底部/投保须知中的<strong>经营主体名称与许可证编号</strong>——确定被告。</li>\n<li>平台页面作出的承诺，可主张构成<strong>缔约过程中的意思表示</strong>；保险人接受投保并承保的，视为其对该销售行为的认可。</li>\n<li>诉讼时可将平台与保险人<strong>列为共同被告</strong>或申请追加第三人。</li>\n</ol>\n<hr>\n<h3 id=\"s12\">坑 6 · <strong>\"智能核保\"的留痕缺失</strong></h3>\n<p><strong>表现</strong>：智能核保（在线回答健康问题后系统给出承保结论）过程没有书面凭证，出险后保险人称\"你未如实告知\"。</p>\n<p><strong>打法</strong>：<strong>智能核保的每一步都截图</strong>（问题、选项、结论页面、结论编号）。日后这是证明\"已履行告知义务\"的关键证据。</p>\n<hr>\n<h2 id=\"s13\">4. 主流平台产品的常见坑（按类型，不针对特定公司）</h2>\n<blockquote><span class=\"warn\">!</span> 以下按<strong>产品类型</strong>归纳，不指向任何具体公司或平台。购买任何产品前请以<strong>当次投保时展示的条款与页面</strong>为准。</blockquote>\n<div class=\"tablewrap\"><table><thead><tr><th>产品类型</th><th>常见坑</th><th>投保前看什么</th></tr></thead><tbody>\n<tr><td><strong>百万医疗险</strong>（长期/一年期）</td><td>保证续保年限被宣传语模糊化；免赔额口径；院外特药清单</td><td>条款中\"<strong>保证续保</strong>\"四字与年限；特药清单</td></tr>\n<tr><td><strong>一年期重疾险</strong></td><td>不保证续保；停售即失效；健康告知严</td><td>续保条款、停售处理</td></tr>\n<tr><td><strong>长期重疾险</strong></td><td>疾病定义版本（2007 vs 2020）；轻症比例；三同条款</td><td>定义条款、比例表</td></tr>\n<tr><td><strong>定期寿险</strong></td><td>受益人默认\"法定\"；职业类别</td><td>指定受益人</td></tr>\n<tr><td><strong>意外险</strong></td><td>只保身故伤残不含医疗；不含猝死</td><td>责任清单</td></tr>\n<tr><td><strong>门诊/小额医疗险</strong></td><td>免赔额高、限额低、社保目录限制</td><td>免赔额与限额</td></tr>\n<tr><td><strong>宠物险</strong></td><td>既往症、品种年龄限制、指定医院、疫苗要求</td><td>除外清单</td></tr>\n<tr><td><strong>养老/年金</strong></td><td>演示利率 vs 保证利率；退保现金价值低</td><td><strong>现金价值表</strong>的保证利益栏</td></tr>\n<tr><td><strong>航班延误险</strong></td><td>延误起算时点；取消是否算延误</td><td>定义条款</td></tr>\n<tr><td><strong>退货运费险</strong></td><td>赔付额与实际运费的差额</td><td>赔付规则</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s14\">5. 互联网投保的\"证据包\"标准动作</h2>\n<p><strong>投保时（5 分钟）</strong></p>\n<ol>\n<li><strong>开启手机屏幕录制</strong>，从打开产品页开始，到支付成功、收到电子保单为止，<strong>全程录屏</strong>。</li>\n<li>逐条<strong>截图健康告知页</strong>（每一条的原文表述）。</li>\n<li><strong>下载并保存</strong>电子保单 PDF + 保险条款 PDF + 投保须知。（<span class=\"warn\">!</span> 平台上的条款链接<strong>随时会变</strong>，必须在投保当天下载本地留存。）</li>\n<li><strong>截图宣传页面</strong>整页（含\"癌症全额赔\"这类大字承诺）。</li>\n<li>与在线<strong>客服文字对话</strong>确认关键问题（\"这个病的赔付比例是多少？\"\"停售了还能续吗？\"），截图保存。</li>\n<li>收到<strong>电话回访</strong>时录音，并<strong>反问</strong>关键条款的含义。</li>\n</ol>\n<p><strong>投保后（1 分钟）</strong></p>\n<ol>\n<li>核对电子保单的<strong>保险期间、保额、受益人、缴费方式</strong>。</li>\n<li>关闭<strong>免密支付 / 自动续费</strong>（如需继续投保，改为手动）。</li>\n<li>把上述材料打包存云盘 + 本地，命名\"险种+投保日期\"。</li>\n</ol>\n<p><strong><span class=\"warn\">!</span> 为什么必须下载条款 PDF</strong>：平台上展示的条款链接指向的是<strong>当前版本</strong>。三年后发生纠纷时，保险人提交的是<strong>新版本条款</strong>。你手里的<strong>投保当天的版本</strong>才是决定性的。</p>\n<hr>\n<h2 id=\"s15\">6. 互联网投保纠纷的分级维权路径</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>金额 / 情形</th><th>推荐路径</th></tr></thead><tbody>\n<tr><td><strong>小额（&lt; 5000 元）</strong></td><td>平台投诉 → 12378 → 12315 → 黑猫投诉/社交媒体曝光。诉讼成本高于收益</td></tr>\n<tr><td><strong>中额（5000 - 5 万）</strong></td><td>12378 投诉（监管压力对持牌机构作用明显）+ 消费者协会/金融纠纷调解组织 → 调解不成再起诉</td></tr>\n<tr><td><strong>大额（&gt; 5 万）</strong></td><td>直接准备诉讼：固定证据包 → 律师函 → 起诉（注意时效与管辖）</td></tr>\n<tr><td><strong>涉及人身伤亡、重大疾病</strong></td><td>优先诉讼；同步申请<strong>先予执行</strong>或依 §25 主张<strong>先予支付</strong></td></tr>\n</tbody></table></div>\n<p><strong>投诉时的写法（决定处理效率）</strong></p>\n<blockquote>❌ 无效写法：\"你们乱扣费，保险是骗人的。\"<br><br>✅ 有效写法：\"本人于 X 年 X 月 X 日在 XX 平台投保 XX 产品（保单号 XXXX）。投保页面健康告知各项<strong>默认勾选项为'否'</strong>，本人可不经阅读直接完成投保，保险人未以网页形式对免责条款进行提示和明确说明，违反《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（二）》第 12 条。现保险人以 XX 条款拒赔。请求：① 责令保险人说明并重新核定；② 提供投保当日的页面版本与后台操作日志。附件：投保录屏、健康告知页截图、条款 PDF。\"</blockquote>\n<p><strong>要点</strong>：<strong>引具体法条 + 附证据 + 提出具体请求</strong>。泛泛抱怨会被当作普通客诉处理；引用法条的会被转给合规部门。</p>\n<hr>\n<h2 id=\"s16\">7. 监管框架速览</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>规范</th><th>要点</th></tr></thead><tbody>\n<tr><td><strong>《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》</strong>（法释〔2023〕13 号，2023 年 12 月 5 日施行）</td><td><strong>§10</strong>：提示义务（明显标识）/ 说明义务（概念、内容、法律后果）/ 举证责任在提供方 / <strong>§10③ 电子合同仅勾选弹窗不足以认定已履行</strong>。这是当前互联网投保<strong>最锋利的一条</strong></td></tr>\n<tr><td><strong>《民法典》§496-498</strong></td><td>格式条款的提示说明义务（不履行的 → 该条款<strong>不成为合同内容</strong>）、无效情形（不合理免除责任/排除对方主要权利）、<strong>不利解释 + 非格式条款优先</strong></td></tr>\n<tr><td><strong>《互联网保险业务监管办法》</strong>（银保监会，2021 年 2 月 1 日施行）</td><td>明确互联网保险业务的经营主体资质、销售行为规范、信息披露、可回溯要求。<strong>无牌机构不得从事互联网保险销售</strong></td></tr>\n<tr><td><strong>《保险销售行为管理办法》</strong>（国家金融监督管理总局，2024 年 3 月 1 日施行）</td><td>将销售行为分为<strong>售前、售中、售后</strong>三段管理；要求<strong>销售过程可回溯</strong>；规范自动续费、销售误导、适当性管理</td></tr>\n<tr><td><strong>可回溯管理相关要求</strong></td><td>要求对销售页面、操作轨迹、告知确认过程进行记录与保存，保存期限有明确要求。<strong>这是要求保险人提交后台数据的规范依据</strong></td></tr>\n<tr><td><strong>《保险法》及解释二</strong></td><td>提示说明义务、举证责任的核心依据</td></tr>\n</tbody></table></div>\n<blockquote><span class=\"warn\">!</span> 上述规范的名称与施行日期以官方发布为准；具体条文请以官方文本核对。文件路径：<code>法条与司法解释原文</code>。</blockquote>\n<p><strong>战术价值</strong>：监管规范的作用在于——<strong>当保险人声称\"我们系统没有保存当时的页面版本\"时，你可以指出这本身就违反了可回溯管理的法定义务</strong>，应作出不利于保险人的认定。</p>\n<hr>\n<h2 id=\"s17\">7.5 广东法院怎么说（A 级判例，2026）</h2>\n<p>这一节的每一条都可以直接写进代理词——<strong>广东本地法院的原话，不是外地判例</strong>。</p>\n<p><strong>① 判准是\"投保人是否了解\"，不是\"有没有做动作\"</strong></p>\n<blockquote>\"应以保险人有进行提示与解释说明的作为<strong>且该作为达到使投保人了解免责条款内容的程度</strong>……<strong>因视频直接跳转</strong>而未能达到使投保人了解免责条款内容之认定标准\"<br>——深圳中院 (2025)粤03民终8930号</blockquote>\n<p><strong>② 电子签名只证明\"投保操作完成\"</strong></p>\n<blockquote>\"上诉人<strong>仅提交带有周某丁电子签名的投保单</strong>，但<strong>无任何证据证明投保人签名前页面完整展示保险条款、无弹窗单独提示免责内容、无线上确认阅读免责条款的操作记录、无任何针对免责条款的解释说明记录</strong>。<strong>电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务。</strong>\"<br>——湛江中院 (2026)粤08民终2074号</blockquote>\n<p><strong>③ 拿\"通用演示视频\"当证据的，一句话击穿</strong></p>\n<blockquote>\"<strong>提交的投保示范视频并非张某甲父亲代投保时的视频轨迹</strong>，仅凭投保单上的签名字样尚不足以证明\"<br>——广州中院 (2025)粤01民终24935号</blockquote>\n<p><strong>④ 系统没给入口 = 保险人没问</strong></p>\n<blockquote>\"<strong>投保环节中也没有任何可供被保险人专门告知'住院治疗超5天、或做过手术、或遵医嘱需要连续服药超过30天'的环节。</strong>\"<br>——湛江中院 (2026)粤08民终2416号</blockquote>\n<p><strong>⑤ <span class=\"warn\">!</span> 反面案例：三件套齐备会输</strong></p>\n<blockquote>\"提交了投保单及<strong>投保人通过电子形式投保驾乘意外险时的照片</strong>……<strong>在投保单上'投保人声明'处签名确认</strong>……<strong>相关保险条款中也进行了加黑加粗</strong>，足以证实……<strong>本院认定平某公司已……履行了提示和明确说明义务</strong>\"<br>——汕尾中院 (2025)粤15民终501号</blockquote>\n<p><strong>结论</strong>：广东法院的口径已经很清楚——<strong>看实质，不看形式；看本次投保轨迹，不看通用演示。</strong> 但<strong>\"投保照片 + 声明签名 + 加黑加粗\"三件套齐备时，法院会认定已履行</strong>，别把全部筹码押在这一张牌上。</p>\n<h2 id=\"s18\">8. 与其他页面的关系</h2>\n<ul>\n<li><strong>通用打法</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a>（武器一 提示说明义务尤其重要）</li>\n<li><strong>专题案例</strong>：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E4%B8%93%E9%A2%98-%E6%8F%90%E7%A4%BA%E8%AF%B4%E6%98%8E%E4%B9%89%E5%8A%A1%E4%B8%8E%E7%94%B5%E5%AD%90%E6%8A%95%E4%BF%9D\">《专题案例 · 提示说明义务与电子投保格式条款》</a>（北京金融法院 + 湖南益阳二审维持案）</li>\n<li><strong>条文原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F02-%E6%B0%91%E6%B3%95%E5%85%B8%E6%A0%BC%E5%BC%8F%E6%9D%A1%E6%AC%BE%E4%B8%8E%E5%90%88%E5%90%8C%E7%BC%96%E9%80%9A%E5%88%99%E8%A7%A3%E9%87%8A\">《民法典格式条款 + 合同编通则司法解释（保险维权核心条文）》</a>（含 §10 全文与新旧规则对照）</li>\n<li><strong>流程与文书</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "0. 速查卡片（本页最重要的 12 条）"}, {"id": "s2", "lv": 2, "t": "1. 互联网投保的法律框架"}, {"id": "s3", "lv": 3, "t": "🔥 第一武器：合同编通则司法解释第 10 条（2023-12-05 施行）"}, {"id": "s4", "lv": 3, "t": "旧武器仍然有效：解释二的三条"}, {"id": "s5", "lv": 2, "t": "2. 可以推翻推定的\"其他证据\"清单"}, {"id": "s6", "lv": 2, "t": "3. 平台页面设计的六个典型坑"}, {"id": "s7", "lv": 3, "t": "坑 1 · 健康告知默认勾选\"否\""}, {"id": "s8", "lv": 3, "t": "坑 2 · \"已阅读并同意\"一行小字"}, {"id": "s9", "lv": 3, "t": "坑 3 · 首月 1 元 / 首月 0.1 元 / 自动续费"}, {"id": "s10", "lv": 3, "t": "坑 4 · 宣传页承诺 ≠ 合同条款"}, {"id": "s11", "lv": 3, "t": "坑 5 · 平台责任 vs 保险人责任互相踢皮球"}, {"id": "s12", "lv": 3, "t": "坑 6 · \"智能核保\"的留痕缺失"}, {"id": "s13", "lv": 2, "t": "4. 主流平台产品的常见坑（按类型，不针对特定公司）"}, {"id": "s14", "lv": 2, "t": "5. 互联网投保的\"证据包\"标准动作"}, {"id": "s15", "lv": 2, "t": "6. 互联网投保纠纷的分级维权路径"}, {"id": "s16", "lv": 2, "t": "7. 监管框架速览"}, {"id": "s17", "lv": 2, "t": "7.5 广东法院怎么说（A 级判例，2026）"}, {"id": "s18", "lv": 2, "t": "8. 与其他页面的关系"}], "text": "互联网投保专章 · 支付宝 / 微信 / App 买保险的坑与打法 本页自包含 ——读这一页不需要翻其他文件。 一句话定位 ：互联网投保和线下投保 适用同一套法律规则 ，但举证方式完全不同。线下靠\"他有没有让你签字\"，线上靠\" 页面有没有做、后台记录能不能拿出来 \"。 覆盖：支付宝（蚂蚁保）、微信（微保）、各保险公司 App/小程序、抖音/小红书引流投保、平台搭售。 0. 速查卡片（本页最重要的 12 条） 要点 依据 0 🔥 电子合同：仅以\"设置勾选、弹窗\"为由主张已履行提示说明义务的，法院不予支持 合同编通则解释 §10③ 1 网络投保的提示说明义务 不降低 ：保险人以 网页、音频、视频 形式提示和明确说明的，可以认定履行了义务 解释二 §12 2 反过来讲—— 网页上没做，就是没做 解释二 §12 反向推论 3 举证责任仍在保险人 （对其履行了明确说明义务负举证责任） 解释二 §13① 4 ⚠️ 签字确认的推定 ：投保人在相关文书上 签字、盖章或以其他形式确认 的， 应当认定 保险人履行了义务， 但有其他证据证明未履行的除外 解释二 §13② 5 所以\"我只是点了同意\" 往往不够 ——要拿 其他证据 推翻该推定 6 电子数据由保险人掌握 （后台页面版本、勾选状态、停留时长）→ 可申请法院责令其提交 7 投保全程录屏 是最高效的自保手段，成本几乎为零 8 禁止性规定情形的免责条款，保险人 提示后 即可生效（无需明确说明） 解释二 §10 9 保险人对 非保险专业术语 的解释符合专业意义、或有利于投保人的，法院认可 解释二 §17 10 合同 记载内容不一致 的，按解释二 §14 的规则认定（通常作有利于投保人/被保险人的认定，以条文为准） 11 首月 1 元、自动续费 属需重点提示的内容；未充分提示的可主张退费 12 投诉热线 12378 （金融监管总局）+ 12315 + 平台投诉，小额纠纷最有效的组合 1. 互联网投保的法律框架 🔥 第一武器：合同编通则司法解释第 10 条（2023 12 05 施行） 第十条 提供格式条款的一方在合同订立时采用 通常足以引起对方注意的文字、符号、字体等明显标识 ，提示对方注意免除或者减轻其责任、排除或者限制对方权利等与对方有重大利害关系的 异常条款 的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的 提示义务 。 提供格式条款的一方按照对方的要求，就与对方有重大利害关系的异常条款的 概念、内容及其法律后果 以书面或者口头形式向对方作出 通常能够理解的解释说明 的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的 说明义务 。 提供格式条款的一方对其已经尽到提示义务或者说明义务 承担举证责任 。 对于通过互联网等信息网络订立的电子合同，提供格式条款的一方仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持 ，但是其举证符合前两款规定的除外。 ⚠️ 这一条改变了互联网投保的攻防格局。 在它之前，保险人只要证明\"你勾了已阅读\"就能过关；在它之后， 勾选和弹窗本身不再是有效抗辩 。 两个真实案例已经落地这条规则 （详见L2 案例库/专题 提示说明义务与电子投保）： 案例 结论 北京金融法院 （2026 05 发布，货物运输险） \"仅通过投保页面的勾选确认方式提示免赔额内容，该方式 不足以引起投保人的合理注意 ，不能认定已履行法定的提示义务\" 湖南益阳赫山区法院 （2024，旅游意外险， 二审维持 ） \"电子投保更便捷，但 不能因此而降低保险人的保险义务 ，将免责事项与其他保险条款并列设置勾选、弹窗等方式的选项， 不能认定为已尽到提示说明义务 \" 用法 ：保险人说\"他勾选了\" → 你引 §10③ → 要求它按 §10② 举证 对概念、内容、法律后果三项都作了解释说明 。 旧武器仍然有效：解释二的三条 规则 内容 解释二 §12 通过网络、电话等方式订立的保险合同，保险人以 网页、音频、视频 等形式对免除保险人责任条款予以提示和明确说明的，人民法院 可以认定 其履行了提示和明确说明义务。 解释二 §13① 保险人对其履行了明确说明义务 负举证责任 。 解释二 §13② 投保人在相关文书上签字、盖章或者以其他形式确认的， 应当认定 保险人履行了该项义务。 但另有证据证明保险人未履行的除外。 读懂 §13② 的两层意思 1. ⚠️ 投保人\"点了确认/勾选了已阅读\"→ 推定 保险人已履行。 这一条对投保人不利，必须正视。 2. ✅ 但书留下了一扇门： 只要有其他证据证明保险人实际未说明，推定就可以被推翻。 ⚠️ 但 2023 年之后，这扇门被进一步推开了。 解释二（2013）§13② 只对\"签字/盖章/其他形式确认\"作推定；而合同编通则解释（2023）§10③ 明确规定： 电子合同仅以勾选、弹窗为由的，法院不予支持 。 实战中两条规则的张力，这样处理： 保险人援引 你援引 论证 解释二 §13②\"他签字/勾选确认了，应认定已履行\" 合同编通则解释 §10③ 通则解释（2023） 晚于 解释二（2013），且专门针对 电子合同这一具体场景 作出更严格规定，网络投保应适用之 同上 解释二 §13② 但书 \"另有证据证明保险人未履行的除外\" → 提交录屏、页面设计证据 \"我们在页面做了加粗提示\" 合同编通则解释 §10② 提示 ≠ 说明。还须就 概念、内容、法律后果 三项作\"通常能够理解\"的解释说明 所以互联网投保维权，本质上是两件事：① 用 §10③ 打掉\"勾选\"抗辩；② 用录屏等证据坐实\"实际未说明\"。 比喻 ：保险公司手里有一张\"他说他看过了\"的签名。法律默认这张签名有效。你要做的不是否认签名，而是 拿出监控录像 ——证明他当时根本没有机会看。 2023 年之后，法官会倾向于接受\"签字不等于看过\"这件事本身。 2. 可以推翻推定的\"其他证据\"清单 按获取难度从低到高排列： 证据 怎么拿 证明力 投保全程录屏 （手机自带屏幕录制） 投保时随手开，存云端 ★★★★★ 最直接 销售页面完整快照 （整页截图 + 存档链接） 截图 + 网页归档工具 ★★★★★ 健康告知页的逐条截图 逐条截，含滚动位置 ★★★★☆ 与在线客服的聊天记录 （追问\"这条什么意思\"） 主动提问并截图 ★★★★☆ 电话回访录音 回访时反问\"这个免责条款是什么意思\"，保险人客服往往答不上来 ★★★★☆ 页面交互设计证据 （是否可跳过、是否默认勾选、停留时长） 重新走一遍流程（不付款）并录屏；或申请保险人提交后台日志 ★★★★☆ 保险人的后台记录 （页面版本、勾选状态、停留时长） 申请法院责令保险人提交 ★★★★★ 宣传页面与实际条款的差异 宣传页快照 vs 条款 PDF ★★★★☆ 他人同期投保的相同页面公证 公证处保全证据 ★★★★☆ 监管部门认定 （投诉后监管出具的意见） 12378 投诉 ★★★☆☆ ⚠️ 关键战术：申请法院责令保险人提交后台数据。 电子投保的页面版本、勾选记录、停留时长、点击流都在保险人的服务器上。依解释二 §13①，举证责任在保险人；其不提交的，主张 举证不能的不利后果 。 3. 平台页面设计的六个典型坑 坑 1 · 健康告知 默认勾选\"否\" 表现 ：健康告知一页几十个问题，全部默认\"否\"，用户一路点\"下一步\"即可完成投保。 打法 1. 解释二 §12 ：以网页形式提示和明确说明的才认定履行。默认勾选 ≠ 主动确认 ≠ 已阅读。 2. 司法解释二 §6① ：告知义务限于 保险人询问的范围和内容 ，对询问范围有争议的 保险人举证 。默认勾选的询问，是否构成\"有效询问\"存疑。 3. 举证推翻 §13② 的推定：录屏 + 页面设计证据（证明可以不经阅读完成投保）。 4. ⚠️ 但要注意 ：如果用户在默认\"否\"的情况下未作修改即提交，保险人仍会主张\"投保人确认了\"。所以 投保时逐条核对并修改 是最根本的自保。 比喻 ：一份体检问卷，医生替你把 50 个问题全勾了\"没有\"，让你直接签字。这份问卷在医学上没有意义，在法律上同样可疑。 坑 2 · \"已阅读并同意\"一行小字 表现 ：《保险条款》《投保须知》《服务协议》《免责声明》等折叠在一条小字链接里，勾选框与正文默认关联。 打法 ：与坑 1 相同，核心是 证明\"可以不阅读即完成投保\" 。录屏是最有力的证据。 坑 3 · 首月 1 元 / 首月 0.1 元 / 自动续费 表现 ：首月极低价吸引投保，次月起按正常费率扣费；默认开通自动续费/免密支付。 打法 1. 这是 格式条款 + 需重点提示的内容 （涉及价格与持续性扣费），未显著提示的，可主张不生效。 2. 未明确告知后续费率、扣费周期的 → 主张未尽明确说明义务。 3. 救济 ：要求退还未充分告知期间的保费；同步 12378 投诉 + 关闭免密支付。 4. 监管层面：保险销售行为管理办法对 自动续费、续期扣费 有明确的信息披露要求。 防范 ：投保后立即关闭免密支付/自动续费，改用手动续费。 坑 4 · 宣传页承诺 ≠ 合同条款 表现 ：页面大字写\" 癌症全额赔 \"\" 可续保至 100 岁 \"\" 住院即赔 \"，条款里是另一套。 打法 1. 保存宣传页面快照 （整页截图 + 时间戳/网页归档）。 2. 解释二 §14 ：保险合同中 记载的内容不一致 的，按该条规定的规则认定（以条文为准，通常倾向于保护投保人/被保险人）。 3. 保险法 §30：条款有歧义的，作有利于被保险人的解释。 4. 主张 销售误导 /虚假宣传，同步走监管投诉。 5. 保险人的代理人/合作平台 在销售过程中的承诺，可主张归入保险人行为（视具体合作模式与授权关系）。 坑 5 · 平台责任 vs 保险人责任互相踢皮球 法律框架 ：互联网保险业务中，存在 保险人 （保险公司）与 互联网保险销售平台/营销宣传机构 两类主体。 主体 责任 保险公司 保险合同的当事人，承担保险责任与说明义务 平台 （如大型互联网平台的保险代理/经纪主体） 若持有 保险代理/经纪牌照 ，承担销售环节的义务（信息披露、适当性、可回溯） 打法 1. 同时对平台与保险人主张 ，不要被\"这不是我们公司的事\"打发。 2. 查看页面底部/投保须知中的 经营主体名称与许可证编号 ——确定被告。 3. 平台页面作出的承诺，可主张构成 缔约过程中的意思表示 ；保险人接受投保并承保的，视为其对该销售行为的认可。 4. 诉讼时可将平台与保险人 列为共同被告 或申请追加第三人。 坑 6 · \"智能核保\"的留痕缺失 表现 ：智能核保（在线回答健康问题后系统给出承保结论）过程没有书面凭证，出险后保险人称\"你未如实告知\"。 打法 ： 智能核保的每一步都截图 （问题、选项、结论页面、结论编号）。日后这是证明\"已履行告知义务\"的关键证据。 4. 主流平台产品的常见坑（按类型，不针对特定公司） ⚠️ 以下按 产品类型 归纳，不指向任何具体公司或平台。购买任何产品前请以 当次投保时展示的条款与页面 为准。 产品类型 常见坑 投保前看什么 百万医疗险 （长期/一年期） 保证续保年限被宣传语模糊化；免赔额口径；院外特药清单 条款中\" 保证续保 \"四字与年限；特药清单 一年期重疾险 不保证续保；停售即失效；健康告知严 续保条款、停售处理 长期重疾险 疾病定义版本（2007 vs 2020）；轻症比例；三同条款 定义条款、比例表 定期寿险 受益人默认\"法定\"；职业类别 指定受益人 意外险 只保身故伤残不含医疗；不含猝死 责任清单 门诊/小额医疗险 免赔额高、限额低、社保目录限制 免赔额与限额 宠物险 既往症、品种年龄限制、指定医院、疫苗要求 除外清单 养老/年金 演示利率 vs 保证利率；退保现金价值低 现金价值表 的保证利益栏 航班延误险 延误起算时点；取消是否算延误 定义条款 退货运费险 赔付额与实际运费的差额 赔付规则 5. 互联网投保的\"证据包\"标准动作 投保时（5 分钟） 1. 开启手机屏幕录制 ，从打开产品页开始，到支付成功、收到电子保单为止， 全程录屏 。 2. 逐条 截图健康告知页 （每一条的原文表述）。 3. 下载并保存 电子保单 PDF + 保险条款 PDF + 投保须知。（⚠️ 平台上的条款链接 随时会变 ，必须在投保当天下载本地留存。） 4. 截图宣传页面 整页（含\"癌症全额赔\"这类大字承诺）。 5. 与在线 客服文字对话 确认关键问题（\"这个病的赔付比例是多少？\"\"停售了还能续吗？\"），截图保存。 6. 收到 电话回访 时录音，并 反问 关键条款的含义。 投保后（1 分钟） 7. 核对电子保单的 保险期间、保额、受益人、缴费方式 。 8. 关闭 免密支付 / 自动续费 （如需继续投保，改为手动）。 9. 把上述材料打包存云盘 + 本地，命名\"险种+投保日期\"。 ⚠️ 为什么必须下载条款 PDF ：平台上展示的条款链接指向的是 当前版本 。三年后发生纠纷时，保险人提交的是 新版本条款 。你手里的 投保当天的版本 才是决定性的。 6. 互联网投保纠纷的分级维权路径 金额 / 情形 推荐路径 小额（< 5000 元） 平台投诉 → 12378 → 12315 → 黑猫投诉/社交媒体曝光。诉讼成本高于收益 中额（5000 5 万） 12378 投诉（监管压力对持牌机构作用明显）+ 消费者协会/金融纠纷调解组织 → 调解不成再起诉 大额（ 5 万） 直接准备诉讼：固定证据包 → 律师函 → 起诉（注意时效与管辖） 涉及人身伤亡、重大疾病 优先诉讼；同步申请 先予执行 或依 §25 主张 先予支付 投诉时的写法（决定处理效率） ❌ 无效写法：\"你们乱扣费，保险是骗人的。\" ✅ 有效写法：\"本人于 X 年 X 月 X 日在 XX 平台投保 XX 产品（保单号 XXXX）。投保页面健康告知各项 默认勾选项为'否' ，本人可不经阅读直接完成投保，保险人未以网页形式对免责条款进行提示和明确说明，违反《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（二）》第 12 条。现保险人以 XX 条款拒赔。请求：① 责令保险人说明并重新核定；② 提供投保当日的页面版本与后台操作日志。附件：投保录屏、健康告知页截图、条款 PDF。\" 要点 ： 引具体法条 + 附证据 + 提出具体请求 。泛泛抱怨会被当作普通客诉处理；引用法条的会被转给合规部门。 7. 监管框架速览 规范 要点 《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》 （法释〔2023〕13 号，2023 年 12 月 5 日施行） §10 ：提示义务（明显标识）/ 说明义务（概念、内容、法律后果）/ 举证责任在提供方 / §10③ 电子合同仅勾选弹窗不足以认定已履行 。这是当前互联网投保 最锋利的一条 《民法典》§496 498 格式条款的提示说明义务（不履行的 → 该条款 不成为合同内容 ）、无效情形（不合理免除责任/排除对方主要权利）、 不利解释 + 非格式条款优先 《互联网保险业务监管办法》 （银保监会，2021 年 2 月 1 日施行） 明确互联网保险业务的经营主体资质、销售行为规范、信息披露、可回溯要求。 无牌机构不得从事互联网保险销售 《保险销售行为管理办法》 （国家金融监督管理总局，2024 年 3 月 1 日施行） 将销售行为分为 售前、售中、售后 三段管理；要求 销售过程可回溯 ；规范自动续费、销售误导、适当性管理 可回溯管理相关要求 要求对销售页面、操作轨迹、告知确认过程进行记录与保存，保存期限有明确要求。 这是要求保险人提交后台数据的规范依据 《保险法》及解释二 提示说明义务、举证责任的核心依据 ⚠️ 上述规范的名称与施行日期以官方发布为准；具体条文请以官方文本核对。文件路径： 法条与司法解释原文 。 战术价值 ：监管规范的作用在于—— 当保险人声称\"我们系统没有保存当时的页面版本\"时，你可以指出这本身就违反了可回溯管理的法定义务 ，应作出不利于保险人的认定。 7.5 广东法院怎么说（A 级判例，2026） 这一节的每一条都可以直接写进代理词—— 广东本地法院的原话，不是外地判例 。 ① 判准是\"投保人是否了解\"，不是\"有没有做动作\" \"应以保险人有进行提示与解释说明的作为 且该作为达到使投保人了解免责条款内容的程度 …… 因视频直接跳转 而未能达到使投保人了解免责条款内容之认定标准\" ——深圳中院 (2025)粤03民终8930号 ② 电子签名只证明\"投保操作完成\" \"上诉人 仅提交带有周某丁电子签名的投保单 ，但 无任何证据证明投保人签名前页面完整展示保险条款、无弹窗单独提示免责内容、无线上确认阅读免责条款的操作记录、无任何针对免责条款的解释说明记录 。 电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务。 \" ——湛江中院 (2026)粤08民终2074号 ③ 拿\"通用演示视频\"当证据的，一句话击穿 \" 提交的投保示范视频并非张某甲父亲代投保时的视频轨迹 ，仅凭投保单上的签名字样尚不足以证明\" ——广州中院 (2025)粤01民终24935号 ④ 系统没给入口 = 保险人没问 \" 投保环节中也没有任何可供被保险人专门告知'住院治疗超5天、或做过手术、或遵医嘱需要连续服药超过30天'的环节。 \" ——湛江中院 (2026)粤08民终2416号 ⑤ ⚠️ 反面案例：三件套齐备会输 \"提交了投保单及 投保人通过电子形式投保驾乘意外险时的照片 …… 在投保单上'投保人声明'处签名确认 …… 相关保险条款中也进行了加黑加粗 ，足以证实…… 本院认定平某公司已……履行了提示和明确说明义务 \" ——汕尾中院 (2025)粤15民终501号 结论 ：广东法院的口径已经很清楚—— 看实质，不看形式；看本次投保轨迹，不看通用演示。 但 \"投保照片 + 声明签名 + 加黑加粗\"三件套齐备时，法院会认定已履行 ，别把全部筹码押在这一张牌上。 8. 与其他页面的关系 通用打法 ：见L0 打法层/01 八把通用武器（武器一 提示说明义务尤其重要） 专题案例 ：见L2 案例库/专题 提示说明义务与电子投保（北京金融法院 + 湖南益阳二审维持案） 条文原文 ：见L4 法条库/02 民法典格式条款与合同编通则解释（含 §10 全文与新旧规则对照） 流程与文书 ：见L0 打法层/02 维权操作全流程 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L2-案例库/专题-提示说明义务与电子投保", "group": "3 · 广东案例库", "groupKey": "L2-案例库", "title": "专题案例 · 提示说明义务与电子投保格式条款", "order": 3, "file": "专题-提示说明义务与电子投保.md", "html": "<h1 id=\"s0\">专题案例 · 提示说明义务与电子投保格式条款</h1>\n<blockquote><strong>采集日期</strong>：2026-09-16 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手待核验<br><strong>本页自包含</strong>：读这一页不需要翻其他文件。<br><br><strong>为什么单列一题</strong>：这是保险纠纷里<strong>出现频率最高、也最容易被保险人用格式条款压死</strong>的一个争点。<br>2023 年 12 月《民法典合同编通则司法解释》施行后，电子投保的\"勾选/弹窗\"抗辩被直接击穿，<br>各地法院（含北京金融法院、湖南法院）已形成明确裁判倾向。<strong>这是近年最重要的变化。</strong></blockquote>\n<hr>\n<h2 id=\"s1\">案例 1 · 北京金融法院「金融案鉴」：免赔额条款仅勾选确认，不生效</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（法院官方发布的典型案例）</li>\n<li><strong>审理法院 / 审级</strong>：北京金融法院（「金融案鉴」栏目发布）</li>\n<li><strong>发布日期</strong>：2026 年 5 月 28 日</li>\n<li><strong>来源 URL</strong>：https://bjfc.bjcourt.gov.cn/cac/1780043234767.html</li>\n<li><strong>可信度</strong>：<strong>B</strong>（法院官网原文）</li>\n<li><strong>关键词标签</strong>：电子投保 / APP 投保 / 免赔额 / 勾选确认 / 提示义务 / 货物运输险</li>\n</ul>\n<p><strong>基本事实</strong></p>\n<p>2019 年 5 月，李某通过 APP 向某保险公司投保货物运输险，为 73 吨货物投保，保险金额 499 万元，保费 1497 元，保险期间 2019-05-18 至 06-17，运输工具为挂车并明确运输路线。2019 年 5 月 23 日，承运车辆后部轮胎起火，货物毁损，李某申请理赔。</p>\n<p>保险人主张：投保页面尾部的免责声明已约定免赔额规则（非超限货物绝对免赔额为 2000 元或损失金额的 10%，<strong>以高者为准</strong>；超限货物为 2000 元或损失金额的 <strong>25%</strong>），且页面设有\"我已阅读并同意《投保协议》\"勾选选项，案涉货物属超限货物，应按 25% 享有免赔额。</p>\n<p><strong>争议焦点</strong></p>\n<p>以电子投保页面的<strong>勾选确认方式</strong>提示免赔额内容，能否认定保险人已履行法定提示义务？</p>\n<p><strong>裁判理由（原文摘录）</strong></p>\n<blockquote>法院经审理认为，案涉保险条款系某保险公司提供的格式条款，其<strong>仅通过投保页面的勾选确认方式提示免赔额内容，该方式不足以引起投保人李某的合理注意，不能认定某保险公司已履行法定的提示义务</strong>，故对其主张的免赔额意见未予采信。</blockquote>\n<p><strong>法院援引的规范（原文摘录于该文）</strong></p>\n<blockquote>《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条第三款：<br>\"提供格式条款的一方对其已经尽到提示义务或者说明义务承担举证责任。<strong>对于通过互联网等信息网络订立的电子合同，提供格式条款的一方仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持</strong>，但是其举证符合前两款规定的除外。\"</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong></p>\n<p><strong>免赔额、免赔率、比例赔付本身就是\"异常条款\"，必须单独、显著提示。</strong> 把它们塞在页面尾部的免责声明里 + 一个勾选框，<strong>不构成提示义务</strong>。这一条可以直接引用于任何互联网投保的免赔额/比例赔付争议。</p>\n<p><strong>关联法条</strong>：民法典 §496、§497；合同编通则解释 §10；保险法 §17；保险法解释二 §9、§11、§13</p>\n<hr>\n<h2 id=\"s2\">案例 2 · 湖南益阳赫山区法院：旅游意外险，二审维持全额赔付</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（法院官网发布的普法案例）</li>\n<li><strong>审理法院 / 审级</strong>：湖南省益阳市赫山区人民法院 · <strong>一审，二审维持原判</strong></li>\n<li><strong>发布日期</strong>：2024 年 10 月</li>\n<li><strong>来源 URL</strong>：http://hsqfy.hunancourt.gov.cn/article/detail/2024/10/id/8157786.shtml</li>\n<li><strong>可信度</strong>：<strong>B</strong>（法院官网原文，含「法官说法」）</li>\n<li><strong>关键词标签</strong>：电子投保 / 勾选弹窗 / 旅游意外险 / 意外身故 / 遗体送返费用 / 二审维持</li>\n</ul>\n<p><strong>基本事实</strong></p>\n<p>2024 年 3 月 24 日，王某某在旅游活动期间于景区坠崖意外死亡。其亲属（原告石某、王某）前往事发地接送骨灰，产生火葬费用五千余元、往返路费一千五百余元。事故发生前，旅行社曾为王某某向保险公司投保<strong>人身意外伤害保险</strong>，约定意外身故保额 10 万元、遗体或骨灰送返（含丧葬费）保额 7000 元。事故发生在保险期限内。</p>\n<p><strong>争议焦点</strong></p>\n<ol>\n<li>电子投保中，将免责事项与其他条款并列设置勾选、弹窗，能否认定已尽提示说明义务？</li>\n<li>\"遗体或骨灰送返\"条款中\"保险人安排运送\"应如何理解？实际发生的火化费与自行运送费用是否属于保险范围？</li>\n</ol>\n<p><strong>裁判理由（原文摘录）</strong></p>\n<blockquote>第一、电子投保是缔结保险合同的合法形式之一，区别于传统的纸质合同通过黑体加粗等方式，电子投保更便捷，<strong>但不能因此而降低保险人的保险义务，将免责事项与其他保险条款并列设置勾选、弹窗等方式的选项，不能认定为已尽到提示说明义务</strong>；<br><br>第二、根据《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条第三款之规定……<strong>保险公司主张已就免责条款履行了提示告知义务的，应举证证明在电子投保流程中对免除保险人责任条款的概念、内容及其法律后果以书面或者口头的方式向投保人作出常人能够理解的解释说明，被告提交的证据不足以证明其主张，故对其抗辩不予采信</strong>，其应在人身意外伤害险限额内全额依法承担赔偿责任；<br><br>第三、原告主张的火葬及骨灰送返费用应属于保险范畴，对合同条款\"安排把被保险人的遗体或者骨灰送至……保险人承担相关运送费用\"<strong>不应仅限于字面意义里的运送主体</strong>，本案中王某某在旅游途中死亡，<strong>必然存在运输费用</strong>，原告提供的火化收款凭单及发票可予以证实，且其骨灰从外地运回益阳也实际产生了运输费用，<strong>原告的主张属于合理损失费用</strong>，对被告辩称不承担赔偿责任的抗辩理由不予采纳。<br><br>本案最终支持了原告的<strong>全部诉讼请求</strong>，并经<strong>二审法院维持原判</strong>。</blockquote>\n<p><strong>法官说法（原文摘录）</strong></p>\n<blockquote>合同编通则司法解释第十条规定了提供格式条款方的提示与说明义务。值得注意的有以下几点：<br>1、进一步细化了\"<strong>异常条款</strong>\"的类型，不仅包括免除或减轻提供方责任，还包括<strong>排除或限制对方权利</strong>等，与对方有重大利害关系的条款；<br>2、提示义务的履行，要求采取<strong>通常足以引起对方注意的明显标识</strong>，而说明义务则需对异常条款的<strong>概念、内容及其法律后果</strong>等作出解释说明；<br>3、新增了对于以互联网等信息网络订立的电子合同，提供格式条款方<strong>仅以采取了设置勾选、弹窗等方式，一般不能作为已经履行提示或说明义务的有效抗辩</strong>。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong></p>\n<ol>\n<li><strong>\"电子投保不能降低保险人义务\"</strong>——这句话可以直接引用。便捷性不是降低保护标准的理由。</li>\n<li><strong>举证标准的明确化</strong>：保险人须证明自己<strong>对概念、内容、法律后果</strong>作了常人能理解的解释说明。只是把条款挂在网上 = 不够。</li>\n<li><strong>条款解释不拘泥字面</strong>（第三点）：这是保险法 §30 不利解释的生动运用——\"安排运送\"不等于\"只赔由保险公司安排的运送\"，实际发生的合理费用照样赔。<strong>遇到保险人抠字眼时，直接引这一段。</strong></li>\n<li><strong>二审维持</strong>，说明这个裁判倾向在湖南当地是稳定的。</li>\n</ol>\n<p><strong>关联法条</strong>：民法典 §496-498；合同编通则解释 §1①、§10③；保险法 §17、§30</p>\n<hr>\n<h2 id=\"s3\">本案群提炼的通用打法（可直接套用）</h2>\n<p><strong>当保险人主张\"投保人已勾选/签字确认\"时，按以下顺序反击：</strong></p>\n<ol>\n<li><strong>引合同编通则解释 §10③</strong>：电子合同仅以勾选、弹窗为由主张已履行义务的，<strong>法院不予支持</strong>。</li>\n<li><strong>要求保险人按 §10② 举证</strong>：证明其就异常条款的<strong>概念、内容、法律后果</strong>作了常人能够理解的解释说明——注意是三项都要，缺一不可。</li>\n<li><strong>引解释二 §13② 但书</strong>：即便存在签字/勾选确认，<strong>另有证据证明未实际说明的除外</strong>（→ 提交录屏、页面设计证据、客服聊天记录、回访录音）。</li>\n<li><strong>区分提示与说明</strong>：加粗加黑只完成\"提示\"，还要有\"说明\"。保险人常把两者混为一谈。</li>\n<li><strong>锁定\"异常条款\"范围</strong>（解释二 §9）：免赔额、免赔率、比例赔付、伤残比例表、疾病定义限定，全都是。</li>\n<li><strong>配套主张</strong>：民法典 §496②（主张该条款<strong>不成为合同内容</strong>）+ §497（不合理免除责任 / 排除对方主要权利的<strong>无效</strong>）。两条路与保险法 §17、§19 并列主张，不要单挂。</li>\n</ol>\n<p><strong><span class=\"warn\">!</span> 反向提示</strong>：这两条规则是<strong>双向</strong>的。如果你是被保险人一方，<strong>务必在投保时录屏</strong>——因为一旦保险人拿出了\"页面有强制阅读 30 秒 + 逐条弹窗 + 语音讲解\"的证据，你这一枪就哑火了。<strong>证据优势要靠自己留痕。</strong></p>\n<hr>\n<h2 id=\"s4\">检索缺口</h2>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 广东法院（尤其广州、深圳）适用<strong>合同编通则解释 §10③</strong> 的公开判例——目前找到的是北京、湖南案例，广东本地的直接判例尚未检索到，需补</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 上述两个案例的<strong>案号</strong>未公开，只能作为裁判倾向引用，不能作为判例直接援引</div>\n<div class=\"chk\"><input type=\"checkbox\" disabled> 电子投保\"强制阅读停留时长\"达到多少秒才算履行提示义务——目前无明确标准，各地裁判可能不一</div>", "toc": [{"id": "s1", "lv": 2, "t": "案例 1 · 北京金融法院「金融案鉴」：免赔额条款仅勾选确认，不生效"}, {"id": "s2", "lv": 2, "t": "案例 2 · 湖南益阳赫山区法院：旅游意外险，二审维持全额赔付"}, {"id": "s3", "lv": 2, "t": "本案群提炼的通用打法（可直接套用）"}, {"id": "s4", "lv": 2, "t": "检索缺口"}], "text": "专题案例 · 提示说明义务与电子投保格式条款 采集日期 ：2026 09 16 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手待核验 本页自包含 ：读这一页不需要翻其他文件。 为什么单列一题 ：这是保险纠纷里 出现频率最高、也最容易被保险人用格式条款压死 的一个争点。 2023 年 12 月《民法典合同编通则司法解释》施行后，电子投保的\"勾选/弹窗\"抗辩被直接击穿， 各地法院（含北京金融法院、湖南法院）已形成明确裁判倾向。 这是近年最重要的变化。 案例 1 · 北京金融法院「金融案鉴」：免赔额条款仅勾选确认，不生效 案号 ：未公开案号（法院官方发布的典型案例） 审理法院 / 审级 ：北京金融法院（「金融案鉴」栏目发布） 发布日期 ：2026 年 5 月 28 日 来源 URL ：https://bjfc.bjcourt.gov.cn/cac/1780043234767.html 可信度 ： B （法院官网原文） 关键词标签 ：电子投保 / APP 投保 / 免赔额 / 勾选确认 / 提示义务 / 货物运输险 基本事实 2019 年 5 月，李某通过 APP 向某保险公司投保货物运输险，为 73 吨货物投保，保险金额 499 万元，保费 1497 元，保险期间 2019 05 18 至 06 17，运输工具为挂车并明确运输路线。2019 年 5 月 23 日，承运车辆后部轮胎起火，货物毁损，李某申请理赔。 保险人主张：投保页面尾部的免责声明已约定免赔额规则（非超限货物绝对免赔额为 2000 元或损失金额的 10%， 以高者为准 ；超限货物为 2000 元或损失金额的 25% ），且页面设有\"我已阅读并同意《投保协议》\"勾选选项，案涉货物属超限货物，应按 25% 享有免赔额。 争议焦点 以电子投保页面的 勾选确认方式 提示免赔额内容，能否认定保险人已履行法定提示义务？ 裁判理由（原文摘录） 法院经审理认为，案涉保险条款系某保险公司提供的格式条款，其 仅通过投保页面的勾选确认方式提示免赔额内容，该方式不足以引起投保人李某的合理注意，不能认定某保险公司已履行法定的提示义务 ，故对其主张的免赔额意见未予采信。 法院援引的规范（原文摘录于该文） 《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条第三款： \"提供格式条款的一方对其已经尽到提示义务或者说明义务承担举证责任。 对于通过互联网等信息网络订立的电子合同，提供格式条款的一方仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持 ，但是其举证符合前两款规定的除外。\" 裁判要旨 / 对我的用处 免赔额、免赔率、比例赔付本身就是\"异常条款\"，必须单独、显著提示。 把它们塞在页面尾部的免责声明里 + 一个勾选框， 不构成提示义务 。这一条可以直接引用于任何互联网投保的免赔额/比例赔付争议。 关联法条 ：民法典 §496、§497；合同编通则解释 §10；保险法 §17；保险法解释二 §9、§11、§13 案例 2 · 湖南益阳赫山区法院：旅游意外险，二审维持全额赔付 案号 ：未公开案号（法院官网发布的普法案例） 审理法院 / 审级 ：湖南省益阳市赫山区人民法院 · 一审，二审维持原判 发布日期 ：2024 年 10 月 来源 URL ：http://hsqfy.hunancourt.gov.cn/article/detail/2024/10/id/8157786.shtml 可信度 ： B （法院官网原文，含「法官说法」） 关键词标签 ：电子投保 / 勾选弹窗 / 旅游意外险 / 意外身故 / 遗体送返费用 / 二审维持 基本事实 2024 年 3 月 24 日，王某某在旅游活动期间于景区坠崖意外死亡。其亲属（原告石某、王某）前往事发地接送骨灰，产生火葬费用五千余元、往返路费一千五百余元。事故发生前，旅行社曾为王某某向保险公司投保 人身意外伤害保险 ，约定意外身故保额 10 万元、遗体或骨灰送返（含丧葬费）保额 7000 元。事故发生在保险期限内。 争议焦点 1. 电子投保中，将免责事项与其他条款并列设置勾选、弹窗，能否认定已尽提示说明义务？ 2. \"遗体或骨灰送返\"条款中\"保险人安排运送\"应如何理解？实际发生的火化费与自行运送费用是否属于保险范围？ 裁判理由（原文摘录） 第一、电子投保是缔结保险合同的合法形式之一，区别于传统的纸质合同通过黑体加粗等方式，电子投保更便捷， 但不能因此而降低保险人的保险义务，将免责事项与其他保险条款并列设置勾选、弹窗等方式的选项，不能认定为已尽到提示说明义务 ； 第二、根据《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条第三款之规定…… 保险公司主张已就免责条款履行了提示告知义务的，应举证证明在电子投保流程中对免除保险人责任条款的概念、内容及其法律后果以书面或者口头的方式向投保人作出常人能够理解的解释说明，被告提交的证据不足以证明其主张，故对其抗辩不予采信 ，其应在人身意外伤害险限额内全额依法承担赔偿责任； 第三、原告主张的火葬及骨灰送返费用应属于保险范畴，对合同条款\"安排把被保险人的遗体或者骨灰送至……保险人承担相关运送费用\" 不应仅限于字面意义里的运送主体 ，本案中王某某在旅游途中死亡， 必然存在运输费用 ，原告提供的火化收款凭单及发票可予以证实，且其骨灰从外地运回益阳也实际产生了运输费用， 原告的主张属于合理损失费用 ，对被告辩称不承担赔偿责任的抗辩理由不予采纳。 本案最终支持了原告的 全部诉讼请求 ，并经 二审法院维持原判 。 法官说法（原文摘录） 合同编通则司法解释第十条规定了提供格式条款方的提示与说明义务。值得注意的有以下几点： 1、进一步细化了\" 异常条款 \"的类型，不仅包括免除或减轻提供方责任，还包括 排除或限制对方权利 等，与对方有重大利害关系的条款； 2、提示义务的履行，要求采取 通常足以引起对方注意的明显标识 ，而说明义务则需对异常条款的 概念、内容及其法律后果 等作出解释说明； 3、新增了对于以互联网等信息网络订立的电子合同，提供格式条款方 仅以采取了设置勾选、弹窗等方式，一般不能作为已经履行提示或说明义务的有效抗辩 。 裁判要旨 / 对我的用处 1. \"电子投保不能降低保险人义务\" ——这句话可以直接引用。便捷性不是降低保护标准的理由。 2. 举证标准的明确化 ：保险人须证明自己 对概念、内容、法律后果 作了常人能理解的解释说明。只是把条款挂在网上 = 不够。 3. 条款解释不拘泥字面 （第三点）：这是保险法 §30 不利解释的生动运用——\"安排运送\"不等于\"只赔由保险公司安排的运送\"，实际发生的合理费用照样赔。 遇到保险人抠字眼时，直接引这一段。 4. 二审维持 ，说明这个裁判倾向在湖南当地是稳定的。 关联法条 ：民法典 §496 498；合同编通则解释 §1①、§10③；保险法 §17、§30 本案群提炼的通用打法（可直接套用） 当保险人主张\"投保人已勾选/签字确认\"时，按以下顺序反击： 1. 引合同编通则解释 §10③ ：电子合同仅以勾选、弹窗为由主张已履行义务的， 法院不予支持 。 2. 要求保险人按 §10② 举证 ：证明其就异常条款的 概念、内容、法律后果 作了常人能够理解的解释说明——注意是三项都要，缺一不可。 3. 引解释二 §13② 但书 ：即便存在签字/勾选确认， 另有证据证明未实际说明的除外 （→ 提交录屏、页面设计证据、客服聊天记录、回访录音）。 4. 区分提示与说明 ：加粗加黑只完成\"提示\"，还要有\"说明\"。保险人常把两者混为一谈。 5. 锁定\"异常条款\"范围 （解释二 §9）：免赔额、免赔率、比例赔付、伤残比例表、疾病定义限定，全都是。 6. 配套主张 ：民法典 §496②（主张该条款 不成为合同内容 ）+ §497（不合理免除责任 / 排除对方主要权利的 无效 ）。两条路与保险法 §17、§19 并列主张，不要单挂。 ⚠️ 反向提示 ：这两条规则是 双向 的。如果你是被保险人一方， 务必在投保时录屏 ——因为一旦保险人拿出了\"页面有强制阅读 30 秒 + 逐条弹窗 + 语音讲解\"的证据，你这一枪就哑火了。 证据优势要靠自己留痕。 检索缺口 [ ] 广东法院（尤其广州、深圳）适用 合同编通则解释 §10③ 的公开判例——目前找到的是北京、湖南案例，广东本地的直接判例尚未检索到，需补 [ ] 上述两个案例的 案号 未公开，只能作为裁判倾向引用，不能作为判例直接援引 [ ] 电子投保\"强制阅读停留时长\"达到多少秒才算履行提示义务——目前无明确标准，各地裁判可能不一"}, {"id": "L2-案例库/广东二审判决原文精读-A级-第二辑", "group": "3 · 广东案例库", "groupKey": "L2-案例库", "title": "广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）", "order": 3, "file": "广东二审判决原文精读-A级-第二辑.md", "html": "<h1 id=\"s0\">广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）</h1>\n<blockquote>采集日期：2026-09-17 ｜ 来源：裁判文书网导出文书原文（.doc），逐字提取<br><strong>可信度：A 级</strong> —— 全部为判决书原文，含一审案号、二审案号、本院认为逐字摘录<br>共 9 个案例：广州 2、中山 2、佛山 1、江门 1、东莞 1、揭阳 1、湛江 1</blockquote>\n<p><strong><span class=\"warn\">!</span> 本辑最重要的两条，会改变你原有的判断：</strong></p>\n<ol>\n<li><strong>非寿险诉讼时效是 3 年，不是 2 年</strong>（广州中院 (2025)粤01民终19766号明确认定保险法 §26 两年规定系照准民法通则，属一般性规定，应适用民法典三年）。</li>\n<li><strong>危险程度显著增加（§52）的通知义务是法定义务，不是约定义务</strong>——所以\"保险人没对这条免责条款提示说明\"这个抗辩，在营运车拒赔案件里<strong>无效</strong>（湛江中院 (2025)粤08民终951号）。</li>\n</ol>\n<hr>\n<h2 id=\"s1\">一、保险人败诉组（可直接援引）</h2>\n<h3 id=\"s2\">V-A1 · 广州中院 (2026)粤01民终446号 —— 疾病定义有歧义，按有利被保险人解释，赔 85.9 万</h3>\n<ul>\n<li><strong>二审案号</strong>：(2026)粤01民终446号　<strong>一审</strong>：(2025)粤0106民初922号</li>\n<li><strong>法院</strong>：广东省广州市中级人民法院</li>\n<li><strong>争议</strong>：罕见病（鸟氨酸氨甲酰基转移酶缺乏症）是否属于\"遗传性疾病\"免责范围</li>\n<li><strong>结果</strong>：保险人免责主张不成立，判赔 858,984.5 元</li>\n</ul>\n<p><strong>攻防结构（值得照抄）</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>保险人</th><th>被保险人</th></tr></thead><tbody>\n<tr><td>提供《罕见病诊疗指南（2019年版）》《诊治专家共识》，证明该病由基因突变导致</td><td>紧扣<strong>合同释义本身</strong>：合同把\"遗传性疾病\"定义为\"……通常具有<strong>由亲代传至后代的垂直传递</strong>的特征\"</td></tr>\n<tr><td>—</td><td>提交《测序报告》：<strong>致病基因未在父母中检出</strong> → 不符合垂直传递特征</td></tr>\n</tbody></table></div>\n<p><strong>裁判理由（原文摘录）</strong></p>\n<blockquote>案涉保险合同属于某保险广东分公司提供的格式合同，在黄某某与某保险广东分公司对合同约定的遗传性疾病产生不同的理解时，依法应当作出有利于被保险人黄某某的解释。现《测序报告》载明，黄某某的致病基因并未在其父母中检出，一审法院结合保险合同的释义，认定黄某某所患鸟氨酸氨甲酰转移酶缺乏症不属于合同约定的\"遗传性疾病\"……并无不当，本院予以认可。</blockquote>\n<p><strong>要旨</strong>：保险人拿权威医学资料证明\"这在医学上属于遗传病\"是<strong>打错战场</strong>。法院只看<strong>合同自己写的释义</strong>——释义里写了\"垂直传递\"，就拿出基因检测证明没有垂直传递。</p>\n<p><strong>关联法条</strong>：保险法 §30（不利解释）</p>\n<hr>\n<h3 id=\"s3\">V-A2 · 佛山中院 (2026)粤06民终4139号 —— 🔥 可回溯管理的举证标准：\"阅读时长、点击路径\"</h3>\n<ul>\n<li><strong>二审案号</strong>：(2026)粤06民终4139号　<strong>一审</strong>：(2025)粤0606民初26938号</li>\n<li><strong>法院</strong>：广东省佛山市中级人民法院</li>\n<li><strong>争议</strong>：车损险，保险人以\"超载 / 违反安全装载规定\"拒赔</li>\n<li><strong>结果</strong>：保险人败诉，判赔 59,662 元</li>\n</ul>\n<p><strong>裁判理由（原文摘录）</strong></p>\n<blockquote>根据某监会关于互联网保险销售行为可回溯管理的要求，保险人应当完整保存投保人在销售页面的操作轨迹，<strong>包括阅读时长、点击路径等关键节点</strong>。然某保险公司顺德中心支公司未提交可验证的操作记录，<strong>仅以投保人签字的格式化声明主张已履行说明义务</strong>，此证据不足以证明其履行了对相应免责条款的提示说明义务。</blockquote>\n<blockquote>另一方面……案涉保险条款仅有机动车损失保险的责任免除条款部分载明\"违反安全装载规定\"免赔，并未明确为\"超载\"，该条款足以造成对格式条款的理解发生争议。从有利于非格式条款提供方（即沈某甲）出发，一审法院认定由某保险公司顺德中心支公司承担理赔责任并无不当。</blockquote>\n<blockquote>该验码单仅系复印件，未提供原始载体供核对，且无其他同步形成的运输单据、监控录像等证据佐证……交警部门在事故责任认定书及后续处理中均未提及超载情节。</blockquote>\n<p><strong>三条可直接用的规则</strong></p>\n<ol>\n<li><strong>举证标准被量化了</strong>：保险人必须提交<strong>可验证的操作轨迹</strong>（阅读时长、点击路径）。只有签字的格式化声明 = 不够。庭审上直接照这个口径要求对方举证。</li>\n<li><strong>\"违反安全装载规定\" ≠ \"超载\"</strong>：条款表述宽泛、未明确指向具体情形 → 保险法 §30 有利解释。所有车险免责条款都可以查一遍\"它写的词，和它拒赔用的词，是不是同一个词\"。</li>\n<li><strong>保险人主张的事实也要举证</strong>：仅复印件、无原始载体、交警认定书未提及 → 事实不成立。</li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §17、§30；解释二 §11②、§12；《互联网保险业务监管办法》、可回溯管理通知</p>\n<hr>\n<h3 id=\"s4\">V-A3 · 江门中院 (2026)粤07民终1377号 —— 🔥 \"保险标的条款\"限缩责任范围 = 实质免责条款</h3>\n<ul>\n<li><strong>二审案号</strong>：(2026)粤07民终1377号　<strong>一审</strong>：(2025)粤0784民初9019号</li>\n<li><strong>法院</strong>：广东省江门市中级人民法院</li>\n<li><strong>争议</strong>：家财险，室内金银珠宝被盗；条款把金银珠宝排除在\"室内财产\"之外</li>\n<li><strong>结果</strong>：保险人败诉</li>\n</ul>\n<p><strong>裁判理由（原文摘录）</strong></p>\n<blockquote>案涉保险条款已明确约定保险标的为室内财产，虽然保险标的条款部分将金银、珠宝、首饰等物品排除在保险范围之外，但<strong>该部分内容实际上系对保险责任范围中的室内财产范围单方进行了限缩，限制了被保险人的权利及保险人的义务，该约定已实质上构成免责条款</strong>，除非保险公司已就该部分内容尽到提示说明义务，否则对投保人不发生法律约束力。</blockquote>\n<blockquote>陈某通过案外人卢某甲投保，投保人陈某否认其曾在案涉电子保单中签名，也否认投保过程中看到过关于保险标的、投保人声明等相关条款，陈某提交的其与卢某乙的某平台聊天记录可以证明其主张，在此情况下无法认定保险公司已经履行说明义务。</blockquote>\n<p><strong>另一条实用规则：损失金额无法确定时的酌定</strong></p>\n<blockquote>由于盗窃事实确实存在，但因相关实物被盗使陈某不能提供更为详尽的证明材料，一审法院综合考虑<strong>举证责任分配、双方当事人利益衡平</strong>等问题，根据在案证据<strong>酌定</strong>财产损失为 5 万元，符合公平原则。</blockquote>\n<p><strong>要旨</strong></p>\n<ul>\n<li>\"这不是免责条款，这是保险标的/责任范围条款\"——这是保险人最常扛的挡箭牌。<strong>本判例直接击穿</strong>：只要<strong>单方限缩、限制被保险人权利</strong>，就是实质免责条款，照样要提示说明。</li>\n<li>被盗、被毁导致的举证不能 ≠ 败诉。法院可以<strong>酌定</strong>。但要主动提\"请法院依举证责任分配与利益衡平原则酌定\"，别等法院自己想起来。</li>\n</ul>\n<p><strong>关联法条</strong>：保险法 §17②；解释二 §12</p>\n<hr>\n<h3 id=\"s5\">V-A4 · 东莞中院 (2026)粤19民终1493号 —— 🔥 营运拒赔：保险人举证标准很高</h3>\n<ul>\n<li><strong>二审案号</strong>：(2026)粤19民终1493号　<strong>一审</strong>：(2025)粤1971民初12351号</li>\n<li><strong>法院</strong>：广东省东莞市中级人民法院</li>\n<li><strong>争议</strong>：代位求偿中，保险人以\"非营运车辆从事营运、危险程度显著增加\"拒赔</li>\n<li><strong>结果</strong>：保险人败诉</li>\n</ul>\n<p><strong>保险人搬出的挡箭牌（很有代表性，务必记住）</strong></p>\n<blockquote>车险电子化实名投保系统是某监会、交警、各某甲公司、某公会等共同开发的实名投保系统……全国各地方的保险行业协会均已发文明确车险电子化投保即应认定保险人已履行提示说明义务。</blockquote>\n<p><strong>法院的态度：不认。</strong> 判决直接认定保险人应承担赔偿责任，未采纳该抗辩。</p>\n<p><strong>营运事实的举证标准（原文摘录）</strong></p>\n<blockquote>粤SXXX<strong>汽车外观没有明显营运标识，某保险公司东莞分公司举证的手机截图</strong>没有具体身份、车辆牌号等平台注册信息<strong>，粤SXXX</strong>汽车缺乏营运的外观特征……平台记录并未反映可以<strong>确定与简某存在直接联系</strong>的内容，某保险公司东莞分公司事故调查也<strong>未询问简某</strong>关于手机截图、平台记录的情况，简某从未确认驾驶粤SXXX**汽车从事营运工作。</blockquote>\n<p><strong>要旨</strong>：保险人要证明\"你营运了\"，得<strong>锁定到具体的人 + 具体的车 + 具体的订单</strong>。只有一张没有身份信息、车牌信息的平台截图，法院不认。</p>\n<p><strong>抗辩话术</strong>：要求保险人说明——截图里的账号是谁的？车牌是多少？注册人身份证号呢？有没有就截图向当事人做过询问笔录？三问答不上来，主张即不成立。</p>\n<p><strong>判决里还有一句可引用的\"法官寄语\"</strong></p>\n<blockquote>保险人接受商用汽车投保时也应审慎注意，核实被保险汽车的实际使用性质，清楚明确告知被保险人改变汽车使用性质、增加危险程度免除保险责任的规则，减少被保险人不能预见的风险。</blockquote>\n<hr>\n<h3 id=\"s6\">V-A5 · 广州中院 (2025)粤01民终19766号 —— 🔥🔥 诉讼时效是 3 年；\"同类产品公证书\"不算证据</h3>\n<ul>\n<li><strong>二审案号</strong>：(2025)粤01民终19766号　<strong>一审</strong>：(2025)粤0112民初3470号</li>\n<li><strong>法院</strong>：广东省广州市中级人民法院</li>\n<li><strong>结果</strong>：保险人败诉，按保单载明金额赔付意外身故 50 万 + 额外给付 100 万 = 150 万</li>\n</ul>\n<p><strong>规则一：非寿险诉讼时效 3 年（这条改写通说）</strong></p>\n<blockquote>《中华人民共和国保险法》第二十六条规定：\"人寿保险以外的其他保险的……诉讼时效期间为二年……\"《中华人民共和国民法典》第一百八十条第一款规定：\"向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定，依照其规定。\"<strong>保险法作为特别法的规定应当优先于作为一般法的民法典的规定而适用。但是，保险法关于两年诉讼时效的规定与当时有效的民法通则关于两年诉讼时效期间的规定是一致的。因此，保险法的该项规定系对民法通则关于普通诉讼时效期间的照准适用，适用法律的一般性规定，故本案人身保险合同应适用三年诉讼时效。</strong></blockquote>\n<p><strong>怎么用</strong></p>\n<ul>\n<li>被保险人是 2020 年出险、2025 年起诉，距离出险已 4 年半，但法院起算点是<strong>\"知道或应当知道保险事故发生之日\"</strong>——本案中保险公司一直没告知保单内容，直到 2024 年 11 月 8 日电话询问才得知，故从该日起算。</li>\n<li><strong>实务双保险</strong>：先主张 3 年时效（引本案）；再主张起算点应从\"实际知道可理赔、知道承保公司\"之日起算。</li>\n</ul>\n<p><strong>规则二：举\"同类产品\"的证 = 没举</strong></p>\n<blockquote>某保险公司主张其在投保人投保时就保险条款已尽提示说明义务，但<strong>其仅提交同类保险产品的投保流程公证书，未能举证证明已向投保人本人对《投保须知》中保险特别条款内容作出提示说明</strong>。因此……等内容，对于投保人不发生法律效力。</blockquote>\n<p><strong>效果</strong>：《投保须知》中\"年收入不足 15 万则保额调整为年收入 10 倍\"的限制条款不生效 → 按保单载明的 150 万全额赔付。这是<strong>隐性免责条款被击穿后直接按表面保额赔</strong>的教科书案例。</p>\n<p><strong>关联法条</strong>：保险法 §17、§26；民法典 §188；《最高人民法院关于适用时间效力的若干规定》§1③</p>\n<hr>\n<h2 id=\"s7\">二、投保人败诉组（<span class=\"warn\">!</span> 必读，别把筹码全押在一张牌上）</h2>\n<h3 id=\"s8\">V-D1 · 湛江中院 (2025)粤08民终951号 —— 🔥 §52 通知义务是<strong>法定</strong>义务，提示说明抗辩无效</h3>\n<ul>\n<li><strong>二审案号</strong>：(2025)粤08民终951号</li>\n<li><strong>法院</strong>：广东省湛江市中级人民法院</li>\n<li><strong>事实</strong>：接单 1895 次（登记注册至事发约 13 个月，日均约 4.52 次），接单地点涵盖多个区县</li>\n</ul>\n<p><strong>裁判理由（原文摘录，这段要背下来）</strong></p>\n<blockquote>保险标的物的危险程度显著增加的，被保险人应当按照合同约定及时通知保险人，<strong>该通知义务是被保险人的法定义务，并不是根据双方在保险合同中的约定而产生的义务</strong>。当保险标的的危险程度显著增加，被保险人未履行通知义务的，发生保险事故，保险人不承担赔偿保险金的责任。</blockquote>\n<blockquote>周某上诉主张……未就免责条款向其履行提示和明确说明义务，不能免除赔偿责任。<strong>如前所述，车辆危险程度显著增加时，被保险人的通知义务属于法定义务，不是约定义务，周某该主张系其理解错误，于法无据，本院不予支持。</strong></blockquote>\n<blockquote>特惠快车业务是完全按照乘客的需求意愿提供的<strong>独立的非拼车的搭乘收费服务，已属于营运性质</strong>。</blockquote>\n<p><strong>要旨（重要）</strong>：提示说明义务这张牌，<strong>打不了 §52</strong>。因为 §52 的通知义务来自法律本身，不是来自免责条款——条款有没有说明，不影响法定义务的存在。</p>\n<p><strong>所以营运车案件的牌只有两张</strong>：① 证明<strong>没有</strong>改变使用性质（次数少、路线固定、确属顺路分摊成本）；② 证明危险程度<strong>未显著增加</strong>。别浪费时间打提示说明。</p>\n<p><strong>\"顺风车\"是否被认定为营运的判断标准（三案归纳）</strong></p>\n<div class=\"tablewrap\"><table><thead><tr><th>要素</th><th>顺风车（不营运）</th><th>营运（被认定）</th></tr></thead><tbody>\n<tr><td>接单次数</td><td>偶发、极少</td><td>47 次 / 1548 次 / 1895 次 / 2271 单</td></tr>\n<tr><td>路线</td><td>相对固定、以既定目的地为终点</td><td>起点终点不固定、跨市、多区县</td></tr>\n<tr><td>时间跨度</td><td>短</td><td>785 天 / 154 天</td></tr>\n<tr><td>目的</td><td>分摊出行成本、免费互助</td><td>收取报酬、营利</td></tr>\n</tbody></table></div>\n<hr>\n<h3 id=\"s9\">V-D2 · 揭阳中院 (2026)粤52民终425号 —— 连续多年同司投保 + 签名投保单 = 已履行</h3>\n<ul>\n<li><strong>二审案号</strong>：(2026)粤52民终425号　<strong>一审</strong>：(2025)粤5281民初4136号</li>\n<li><strong>事实</strong>：滴滴注册 785 天、累计完单 2271 单、30 天流水 1108.86 元</li>\n<li><strong>结果</strong>：保险人免责成立</li>\n</ul>\n<blockquote>在某保险公司揭阳市分公司在一审已提供有投保人陈某甲签名的投保单，且<strong>陈某甲连续多年在同一保险公司投保</strong>的情况下，应认定某保险公司揭阳市分公司已对免责条款尽到明确说明义务。</blockquote>\n<p><strong>要旨</strong>：<strong>\"连续多年在同一家投保\"会被用作对投保人不利的证据</strong>——法院认为你年复一年签同样的保单，不可能不知道免责条款。这一点对维权方很不利，要提前有心理准备。</p>\n<hr>\n<h3 id=\"s10\">V-D3 · 中山中院 (2025)粤20民终2567号 —— 强制停留阅读 + 勾选 + 加粗 = 已履行</h3>\n<ul>\n<li><strong>二审案号</strong>：(2025)粤20民终2567号　<strong>一审</strong>：(2024)粤2071民初34629号</li>\n<li><strong>事实</strong>：哈啰平台注册顺风车，2023-09-01 至 2024-03-13 接单 47 次，多笔省内跨市</li>\n<li><strong>结果</strong>：保险人免责成立</li>\n</ul>\n<p><strong>法院采信的\"充分履行\"证据组合（记住这套，反向用来审查对方）</strong></p>\n<blockquote>A 公司对于……免责条款有进行<strong>加粗加黑</strong>，并设置了保证投保人在合理时间内<strong>强制阅读</strong>投保相关内容的<strong>强制停留阅读程序</strong>及阅读后，<strong>勾选</strong>\"保险人已明确说明免除保险人责任条款的内容及法律后果\"才能进行下一步的操作，且免责条款内容明确、不存在歧义、常人能够理解。以上事实足以认定 A 公司已就免责条款尽到提示和明确说明义务。</blockquote>\n<p><strong>另一条：代签的追认</strong></p>\n<blockquote>根据其关于购买车辆的总费用包含保险费、与 A 公司建立保险合同关系等陈述，可认定蚁某东已按照合同约定按期交纳了保险费，具有投保的意思表示，应视为其对代理投保行为的追认。（解释二 §3）</blockquote>\n<p><strong>要旨</strong>：✅ <strong>\"加粗 + 强制停留阅读 + 勾选 + 内容无歧义\"四件套齐备时，法院会认定已履行。</strong> 这套组合是保险人的标准防御工事（对比 V-A2 佛山案：只有签字声明、没有操作轨迹 → 不够）。</p>\n<p><span class=\"warn\">!</span> 但注意：<strong>这四件套中的每一项都可以单独质证</strong>——加粗了但没强制停留？停留了但可跳过？勾选了但页面没显示条款全文？逐项打。</p>\n<hr>\n<h3 id=\"s11\">V-D4 · 中山中院 (2025)粤20民终1136号 —— 与 V-D3 同口径</h3>\n<ul>\n<li><strong>二审案号</strong>：(2025)粤20民终1136号　<strong>一审</strong>：(2024)粤2071民初23188号</li>\n<li><strong>事实</strong>：哈啰顺风车，已完成 154 天、顺风出行 1548 次，2024-04-01 至 04-08 有多起接单，路线不固定</li>\n<li><strong>结果</strong>：保险人免责成立（理由与 V-D3 一致）</li>\n</ul>\n<p><strong>值得记的一句</strong>：</p>\n<blockquote>事发前该车辆用于营运导致被保险车辆危险程度显著增加的事实<strong>并不因其事发当时未进行运营而改变</strong>。</blockquote>\n<p>即：<strong>\"出险那一刻我没在接单\"不构成抗辩。</strong></p>\n<hr>\n<h2 id=\"s12\">三、本辑提炼的硬规则（速查）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>规则</th><th>判例</th><th>用法</th></tr></thead><tbody>\n<tr><td>1</td><td>🔥 <strong>非寿险诉讼时效 3 年</strong>（§26 两年系照准民法通则，属一般性规定）</td><td>广州 (2025)粤01民终19766</td><td>保险人提时效抗辩时</td></tr>\n<tr><td>2</td><td>🔥 <strong>时效起算点 = 实际知道保险事故及承保公司之日</strong>，非客观出险日</td><td>同上</td><td>时效看似已过时</td></tr>\n<tr><td>3</td><td>🔥 <strong>§52 通知义务是法定义务</strong>，提示说明义务抗辩对其无效</td><td>湛江 (2025)粤08民终951</td><td>营运车案件，别打错牌</td></tr>\n<tr><td>4</td><td>🔥 <strong>可回溯：保险人须提交阅读时长、点击路径等操作轨迹</strong>，仅签字声明不够</td><td>佛山 (2026)粤06民终4139</td><td>要求对方举证的标准</td></tr>\n<tr><td>5</td><td><strong>\"违反安全装载规定\" ≠ \"超载\"</strong>：条款用词与拒赔用词不一致 → §30</td><td>佛山 (2026)粤06民终4139</td><td>所有车险免责条款逐词比对</td></tr>\n<tr><td>6</td><td><strong>限缩保险标的/责任范围 = 实质免责条款</strong>，照样要提示说明</td><td>江门 (2026)粤07民终1377</td><td>破解\"这是责任范围不是免责\"</td></tr>\n<tr><td>7</td><td><strong>营运举证须锁定人、车、订单</strong>；无身份/车牌信息的截图不认</td><td>东莞 (2026)粤19民终1493</td><td>质证保险人证据</td></tr>\n<tr><td>8</td><td><strong>\"行业协会发文/全国统一样式\"不能替代本案履行</strong></td><td>东莞 (2026)粤19民终1493</td><td>反驳保险人挡箭牌</td></tr>\n<tr><td>9</td><td><strong>损失因被盗等客观原因无法精确举证 → 可请求法院酌定</strong></td><td>江门 (2026)粤07民终1377</td><td>主动提，别等法院</td></tr>\n<tr><td>10</td><td><strong>保险人只提交\"同类产品\"投保流程公证书 = 未举证</strong></td><td>广州 (2025)粤01民终19766</td><td>反驳示范视频/公证书</td></tr>\n<tr><td>11</td><td><strong>疾病定义之争只看合同释义</strong>：释义写了\"垂直传递\"就证明无垂直传递</td><td>广州 (2026)粤01民终446</td><td>重疾/罕见病定义争议</td></tr>\n<tr><td>12</td><td><strong>出险时未在接单 ≠ 未改变使用性质</strong></td><td>中山 (2025)粤20民终1136</td><td>勿作抗辩</td></tr>\n<tr><td>13</td><td><strong>特惠快车 = 营运</strong>（独立非拼车收费服务）</td><td>湛江 (2025)粤08民终951</td><td>网约车定性</td></tr>\n</tbody></table></div>\n<h2 id=\"s13\">四、三个\"别踩\"</h2>\n<ol>\n<li><strong>营运车案件不要再打提示说明义务。</strong> 湛江案已明确 §52 是法定义务。你的牌只有\"没改变使用性质\"和\"危险程度未显著增加\"。</li>\n<li><strong>\"连续多年在同一家保险公司投保\"是双刃剑。</strong> 揭阳案用它认定保险人已履行说明义务。如果你的当事人是多年续保，说明义务这条路基本堵死，转向其他争点。</li>\n<li><strong>顺风车接单量一旦过百、路线跨市，基本必输。</strong> 中山两案、湛江案、揭阳案四案口径完全一致。真想保住理赔，投保时就按营运性质投保——这是唯一稳妥解。</li>\n</ol>\n<hr>\n<h2 id=\"s14\">与其他页面的关系</h2>\n<ul>\n<li><strong>车险逐争点打法</strong>：<a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F05-%E8%BD%A6%E9%99%A9\">《车险 · 纠纷全解》</a></li>\n<li><strong>财产险与责任险</strong>：<a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F06-%E8%B4%A2%E4%BA%A7%E9%99%A9%E4%B8%8E%E8%B4%A3%E4%BB%BB%E9%99%A9\">《财产险与责任险 · 纠纷全解》</a></li>\n<li><strong>第一辑（人身险 A 级判例）</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7\">《广东二审判决原文精读 · 第一辑（人身险）》</a></li>\n<li><strong>提示说明义务专题</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E4%B8%93%E9%A2%98-%E6%8F%90%E7%A4%BA%E8%AF%B4%E6%98%8E%E4%B9%89%E5%8A%A1%E4%B8%8E%E7%94%B5%E5%AD%90%E6%8A%95%E4%BF%9D\">《专题案例 · 提示说明义务与电子投保格式条款》</a></li>\n<li><strong>时效速查表</strong>：<a class=\"dlink\" href=\"#/README\">《开始这里 · 怎么用这套东西》</a></li>\n<li><strong>法条原文</strong>：<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "一、保险人败诉组（可直接援引）"}, {"id": "s2", "lv": 3, "t": "V-A1 · 广州中院 (2026)粤01民终446号 —— 疾病定义有歧义，按有利被保险人解释，赔 85.9 万"}, {"id": "s3", "lv": 3, "t": "V-A2 · 佛山中院 (2026)粤06民终4139号 —— 🔥 可回溯管理的举证标准：\"阅读时长、点击路径\""}, {"id": "s4", "lv": 3, "t": "V-A3 · 江门中院 (2026)粤07民终1377号 —— 🔥 \"保险标的条款\"限缩责任范围 = 实质免责条款"}, {"id": "s5", "lv": 3, "t": "V-A4 · 东莞中院 (2026)粤19民终1493号 —— 🔥 营运拒赔：保险人举证标准很高"}, {"id": "s6", "lv": 3, "t": "V-A5 · 广州中院 (2025)粤01民终19766号 —— 🔥🔥 诉讼时效是 3 年；\"同类产品公证书\"不算证据"}, {"id": "s7", "lv": 2, "t": "二、投保人败诉组（! 必读，别把筹码全押在一张牌上）"}, {"id": "s8", "lv": 3, "t": "V-D1 · 湛江中院 (2025)粤08民终951号 —— 🔥 §52 通知义务是法定义务，提示说明抗辩无效"}, {"id": "s9", "lv": 3, "t": "V-D2 · 揭阳中院 (2026)粤52民终425号 —— 连续多年同司投保 + 签名投保单 = 已履行"}, {"id": "s10", "lv": 3, "t": "V-D3 · 中山中院 (2025)粤20民终2567号 —— 强制停留阅读 + 勾选 + 加粗 = 已履行"}, {"id": "s11", "lv": 3, "t": "V-D4 · 中山中院 (2025)粤20民终1136号 —— 与 V-D3 同口径"}, {"id": "s12", "lv": 2, "t": "三、本辑提炼的硬规则（速查）"}, {"id": "s13", "lv": 2, "t": "四、三个\"别踩\""}, {"id": "s14", "lv": 2, "t": "与其他页面的关系"}], "text": "广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿） 采集日期：2026 09 17 ｜ 来源：裁判文书网导出文书原文（.doc），逐字提取 可信度：A 级 —— 全部为判决书原文，含一审案号、二审案号、本院认为逐字摘录 共 9 个案例：广州 2、中山 2、佛山 1、江门 1、东莞 1、揭阳 1、湛江 1 ⚠️ 本辑最重要的两条，会改变你原有的判断： 1. 非寿险诉讼时效是 3 年，不是 2 年 （广州中院 (2025)粤01民终19766号明确认定保险法 §26 两年规定系照准民法通则，属一般性规定，应适用民法典三年）。 2. 危险程度显著增加（§52）的通知义务是法定义务，不是约定义务 ——所以\"保险人没对这条免责条款提示说明\"这个抗辩，在营运车拒赔案件里 无效 （湛江中院 (2025)粤08民终951号）。 一、保险人败诉组（可直接援引） V A1 · 广州中院 (2026)粤01民终446号 —— 疾病定义有歧义，按有利被保险人解释，赔 85.9 万 二审案号 ：(2026)粤01民终446号 一审 ：(2025)粤0106民初922号 法院 ：广东省广州市中级人民法院 争议 ：罕见病（鸟氨酸氨甲酰基转移酶缺乏症）是否属于\"遗传性疾病\"免责范围 结果 ：保险人免责主张不成立，判赔 858,984.5 元 攻防结构（值得照抄） 保险人 被保险人 提供《罕见病诊疗指南（2019年版）》《诊治专家共识》，证明该病由基因突变导致 紧扣 合同释义本身 ：合同把\"遗传性疾病\"定义为\"……通常具有 由亲代传至后代的垂直传递 的特征\" — 提交《测序报告》： 致病基因未在父母中检出 → 不符合垂直传递特征 裁判理由（原文摘录） 案涉保险合同属于某保险广东分公司提供的格式合同，在黄某某与某保险广东分公司对合同约定的遗传性疾病产生不同的理解时，依法应当作出有利于被保险人黄某某的解释。现《测序报告》载明，黄某某的致病基因并未在其父母中检出，一审法院结合保险合同的释义，认定黄某某所患鸟氨酸氨甲酰转移酶缺乏症不属于合同约定的\"遗传性疾病\"……并无不当，本院予以认可。 要旨 ：保险人拿权威医学资料证明\"这在医学上属于遗传病\"是 打错战场 。法院只看 合同自己写的释义 ——释义里写了\"垂直传递\"，就拿出基因检测证明没有垂直传递。 关联法条 ：保险法 §30（不利解释） V A2 · 佛山中院 (2026)粤06民终4139号 —— 🔥 可回溯管理的举证标准：\"阅读时长、点击路径\" 二审案号 ：(2026)粤06民终4139号 一审 ：(2025)粤0606民初26938号 法院 ：广东省佛山市中级人民法院 争议 ：车损险，保险人以\"超载 / 违反安全装载规定\"拒赔 结果 ：保险人败诉，判赔 59,662 元 裁判理由（原文摘录） 根据某监会关于互联网保险销售行为可回溯管理的要求，保险人应当完整保存投保人在销售页面的操作轨迹， 包括阅读时长、点击路径等关键节点 。然某保险公司顺德中心支公司未提交可验证的操作记录， 仅以投保人签字的格式化声明主张已履行说明义务 ，此证据不足以证明其履行了对相应免责条款的提示说明义务。 另一方面……案涉保险条款仅有机动车损失保险的责任免除条款部分载明\"违反安全装载规定\"免赔，并未明确为\"超载\"，该条款足以造成对格式条款的理解发生争议。从有利于非格式条款提供方（即沈某甲）出发，一审法院认定由某保险公司顺德中心支公司承担理赔责任并无不当。 该验码单仅系复印件，未提供原始载体供核对，且无其他同步形成的运输单据、监控录像等证据佐证……交警部门在事故责任认定书及后续处理中均未提及超载情节。 三条可直接用的规则 1. 举证标准被量化了 ：保险人必须提交 可验证的操作轨迹 （阅读时长、点击路径）。只有签字的格式化声明 = 不够。庭审上直接照这个口径要求对方举证。 2. \"违反安全装载规定\" ≠ \"超载\" ：条款表述宽泛、未明确指向具体情形 → 保险法 §30 有利解释。所有车险免责条款都可以查一遍\"它写的词，和它拒赔用的词，是不是同一个词\"。 3. 保险人主张的事实也要举证 ：仅复印件、无原始载体、交警认定书未提及 → 事实不成立。 关联法条 ：保险法 §17、§30；解释二 §11②、§12；《互联网保险业务监管办法》、可回溯管理通知 V A3 · 江门中院 (2026)粤07民终1377号 —— 🔥 \"保险标的条款\"限缩责任范围 = 实质免责条款 二审案号 ：(2026)粤07民终1377号 一审 ：(2025)粤0784民初9019号 法院 ：广东省江门市中级人民法院 争议 ：家财险，室内金银珠宝被盗；条款把金银珠宝排除在\"室内财产\"之外 结果 ：保险人败诉 裁判理由（原文摘录） 案涉保险条款已明确约定保险标的为室内财产，虽然保险标的条款部分将金银、珠宝、首饰等物品排除在保险范围之外，但 该部分内容实际上系对保险责任范围中的室内财产范围单方进行了限缩，限制了被保险人的权利及保险人的义务，该约定已实质上构成免责条款 ，除非保险公司已就该部分内容尽到提示说明义务，否则对投保人不发生法律约束力。 陈某通过案外人卢某甲投保，投保人陈某否认其曾在案涉电子保单中签名，也否认投保过程中看到过关于保险标的、投保人声明等相关条款，陈某提交的其与卢某乙的某平台聊天记录可以证明其主张，在此情况下无法认定保险公司已经履行说明义务。 另一条实用规则：损失金额无法确定时的酌定 由于盗窃事实确实存在，但因相关实物被盗使陈某不能提供更为详尽的证明材料，一审法院综合考虑 举证责任分配、双方当事人利益衡平 等问题，根据在案证据 酌定 财产损失为 5 万元，符合公平原则。 要旨 \"这不是免责条款，这是保险标的/责任范围条款\"——这是保险人最常扛的挡箭牌。 本判例直接击穿 ：只要 单方限缩、限制被保险人权利 ，就是实质免责条款，照样要提示说明。 被盗、被毁导致的举证不能 ≠ 败诉。法院可以 酌定 。但要主动提\"请法院依举证责任分配与利益衡平原则酌定\"，别等法院自己想起来。 关联法条 ：保险法 §17②；解释二 §12 V A4 · 东莞中院 (2026)粤19民终1493号 —— 🔥 营运拒赔：保险人举证标准很高 二审案号 ：(2026)粤19民终1493号 一审 ：(2025)粤1971民初12351号 法院 ：广东省东莞市中级人民法院 争议 ：代位求偿中，保险人以\"非营运车辆从事营运、危险程度显著增加\"拒赔 结果 ：保险人败诉 保险人搬出的挡箭牌（很有代表性，务必记住） 车险电子化实名投保系统是某监会、交警、各某甲公司、某公会等共同开发的实名投保系统……全国各地方的保险行业协会均已发文明确车险电子化投保即应认定保险人已履行提示说明义务。 法院的态度：不认。 判决直接认定保险人应承担赔偿责任，未采纳该抗辩。 营运事实的举证标准（原文摘录） 粤SXXX 汽车外观没有明显营运标识，某保险公司东莞分公司举证的手机截图 没有具体身份、车辆牌号等平台注册信息 ，粤SXXX 汽车缺乏营运的外观特征……平台记录并未反映可以 确定与简某存在直接联系 的内容，某保险公司东莞分公司事故调查也 未询问简某 关于手机截图、平台记录的情况，简某从未确认驾驶粤SXXX 汽车从事营运工作。 要旨 ：保险人要证明\"你营运了\"，得 锁定到具体的人 + 具体的车 + 具体的订单 。只有一张没有身份信息、车牌信息的平台截图，法院不认。 抗辩话术 ：要求保险人说明——截图里的账号是谁的？车牌是多少？注册人身份证号呢？有没有就截图向当事人做过询问笔录？三问答不上来，主张即不成立。 判决里还有一句可引用的\"法官寄语\" 保险人接受商用汽车投保时也应审慎注意，核实被保险汽车的实际使用性质，清楚明确告知被保险人改变汽车使用性质、增加危险程度免除保险责任的规则，减少被保险人不能预见的风险。 V A5 · 广州中院 (2025)粤01民终19766号 —— 🔥🔥 诉讼时效是 3 年；\"同类产品公证书\"不算证据 二审案号 ：(2025)粤01民终19766号 一审 ：(2025)粤0112民初3470号 法院 ：广东省广州市中级人民法院 结果 ：保险人败诉，按保单载明金额赔付意外身故 50 万 + 额外给付 100 万 = 150 万 规则一：非寿险诉讼时效 3 年（这条改写通说） 《中华人民共和国保险法》第二十六条规定：\"人寿保险以外的其他保险的……诉讼时效期间为二年……\"《中华人民共和国民法典》第一百八十条第一款规定：\"向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定，依照其规定。\" 保险法作为特别法的规定应当优先于作为一般法的民法典的规定而适用。但是，保险法关于两年诉讼时效的规定与当时有效的民法通则关于两年诉讼时效期间的规定是一致的。因此，保险法的该项规定系对民法通则关于普通诉讼时效期间的照准适用，适用法律的一般性规定，故本案人身保险合同应适用三年诉讼时效。 怎么用 被保险人是 2020 年出险、2025 年起诉，距离出险已 4 年半，但法院起算点是 \"知道或应当知道保险事故发生之日\" ——本案中保险公司一直没告知保单内容，直到 2024 年 11 月 8 日电话询问才得知，故从该日起算。 实务双保险 ：先主张 3 年时效（引本案）；再主张起算点应从\"实际知道可理赔、知道承保公司\"之日起算。 规则二：举\"同类产品\"的证 = 没举 某保险公司主张其在投保人投保时就保险条款已尽提示说明义务，但 其仅提交同类保险产品的投保流程公证书，未能举证证明已向投保人本人对《投保须知》中保险特别条款内容作出提示说明 。因此……等内容，对于投保人不发生法律效力。 效果 ：《投保须知》中\"年收入不足 15 万则保额调整为年收入 10 倍\"的限制条款不生效 → 按保单载明的 150 万全额赔付。这是 隐性免责条款被击穿后直接按表面保额赔 的教科书案例。 关联法条 ：保险法 §17、§26；民法典 §188；《最高人民法院关于适用时间效力的若干规定》§1③ 二、投保人败诉组（⚠️ 必读，别把筹码全押在一张牌上） V D1 · 湛江中院 (2025)粤08民终951号 —— 🔥 §52 通知义务是 法定 义务，提示说明抗辩无效 二审案号 ：(2025)粤08民终951号 法院 ：广东省湛江市中级人民法院 事实 ：接单 1895 次（登记注册至事发约 13 个月，日均约 4.52 次），接单地点涵盖多个区县 裁判理由（原文摘录，这段要背下来） 保险标的物的危险程度显著增加的，被保险人应当按照合同约定及时通知保险人， 该通知义务是被保险人的法定义务，并不是根据双方在保险合同中的约定而产生的义务 。当保险标的的危险程度显著增加，被保险人未履行通知义务的，发生保险事故，保险人不承担赔偿保险金的责任。 周某上诉主张……未就免责条款向其履行提示和明确说明义务，不能免除赔偿责任。 如前所述，车辆危险程度显著增加时，被保险人的通知义务属于法定义务，不是约定义务，周某该主张系其理解错误，于法无据，本院不予支持。 特惠快车业务是完全按照乘客的需求意愿提供的 独立的非拼车的搭乘收费服务，已属于营运性质 。 要旨（重要） ：提示说明义务这张牌， 打不了 §52 。因为 §52 的通知义务来自法律本身，不是来自免责条款——条款有没有说明，不影响法定义务的存在。 所以营运车案件的牌只有两张 ：① 证明 没有 改变使用性质（次数少、路线固定、确属顺路分摊成本）；② 证明危险程度 未显著增加 。别浪费时间打提示说明。 \"顺风车\"是否被认定为营运的判断标准（三案归纳） 要素 顺风车（不营运） 营运（被认定） 接单次数 偶发、极少 47 次 / 1548 次 / 1895 次 / 2271 单 路线 相对固定、以既定目的地为终点 起点终点不固定、跨市、多区县 时间跨度 短 785 天 / 154 天 目的 分摊出行成本、免费互助 收取报酬、营利 V D2 · 揭阳中院 (2026)粤52民终425号 —— 连续多年同司投保 + 签名投保单 = 已履行 二审案号 ：(2026)粤52民终425号 一审 ：(2025)粤5281民初4136号 事实 ：滴滴注册 785 天、累计完单 2271 单、30 天流水 1108.86 元 结果 ：保险人免责成立 在某保险公司揭阳市分公司在一审已提供有投保人陈某甲签名的投保单，且 陈某甲连续多年在同一保险公司投保 的情况下，应认定某保险公司揭阳市分公司已对免责条款尽到明确说明义务。 要旨 ： \"连续多年在同一家投保\"会被用作对投保人不利的证据 ——法院认为你年复一年签同样的保单，不可能不知道免责条款。这一点对维权方很不利，要提前有心理准备。 V D3 · 中山中院 (2025)粤20民终2567号 —— 强制停留阅读 + 勾选 + 加粗 = 已履行 二审案号 ：(2025)粤20民终2567号 一审 ：(2024)粤2071民初34629号 事实 ：哈啰平台注册顺风车，2023 09 01 至 2024 03 13 接单 47 次，多笔省内跨市 结果 ：保险人免责成立 法院采信的\"充分履行\"证据组合（记住这套，反向用来审查对方） A 公司对于……免责条款有进行 加粗加黑 ，并设置了保证投保人在合理时间内 强制阅读 投保相关内容的 强制停留阅读程序 及阅读后， 勾选 \"保险人已明确说明免除保险人责任条款的内容及法律后果\"才能进行下一步的操作，且免责条款内容明确、不存在歧义、常人能够理解。以上事实足以认定 A 公司已就免责条款尽到提示和明确说明义务。 另一条：代签的追认 根据其关于购买车辆的总费用包含保险费、与 A 公司建立保险合同关系等陈述，可认定蚁某东已按照合同约定按期交纳了保险费，具有投保的意思表示，应视为其对代理投保行为的追认。（解释二 §3） 要旨 ：✅ \"加粗 + 强制停留阅读 + 勾选 + 内容无歧义\"四件套齐备时，法院会认定已履行。 这套组合是保险人的标准防御工事（对比 V A2 佛山案：只有签字声明、没有操作轨迹 → 不够）。 ⚠️ 但注意： 这四件套中的每一项都可以单独质证 ——加粗了但没强制停留？停留了但可跳过？勾选了但页面没显示条款全文？逐项打。 V D4 · 中山中院 (2025)粤20民终1136号 —— 与 V D3 同口径 二审案号 ：(2025)粤20民终1136号 一审 ：(2024)粤2071民初23188号 事实 ：哈啰顺风车，已完成 154 天、顺风出行 1548 次，2024 04 01 至 04 08 有多起接单，路线不固定 结果 ：保险人免责成立（理由与 V D3 一致） 值得记的一句 ： 事发前该车辆用于营运导致被保险车辆危险程度显著增加的事实 并不因其事发当时未进行运营而改变 。 即： \"出险那一刻我没在接单\"不构成抗辩。 三、本辑提炼的硬规则（速查） 规则 判例 用法 1 🔥 非寿险诉讼时效 3 年 （§26 两年系照准民法通则，属一般性规定） 广州 (2025)粤01民终19766 保险人提时效抗辩时 2 🔥 时效起算点 = 实际知道保险事故及承保公司之日 ，非客观出险日 同上 时效看似已过时 3 🔥 §52 通知义务是法定义务 ，提示说明义务抗辩对其无效 湛江 (2025)粤08民终951 营运车案件，别打错牌 4 🔥 可回溯：保险人须提交阅读时长、点击路径等操作轨迹 ，仅签字声明不够 佛山 (2026)粤06民终4139 要求对方举证的标准 5 \"违反安全装载规定\" ≠ \"超载\" ：条款用词与拒赔用词不一致 → §30 佛山 (2026)粤06民终4139 所有车险免责条款逐词比对 6 限缩保险标的/责任范围 = 实质免责条款 ，照样要提示说明 江门 (2026)粤07民终1377 破解\"这是责任范围不是免责\" 7 营运举证须锁定人、车、订单 ；无身份/车牌信息的截图不认 东莞 (2026)粤19民终1493 质证保险人证据 8 \"行业协会发文/全国统一样式\"不能替代本案履行 东莞 (2026)粤19民终1493 反驳保险人挡箭牌 9 损失因被盗等客观原因无法精确举证 → 可请求法院酌定 江门 (2026)粤07民终1377 主动提，别等法院 10 保险人只提交\"同类产品\"投保流程公证书 = 未举证 广州 (2025)粤01民终19766 反驳示范视频/公证书 11 疾病定义之争只看合同释义 ：释义写了\"垂直传递\"就证明无垂直传递 广州 (2026)粤01民终446 重疾/罕见病定义争议 12 出险时未在接单 ≠ 未改变使用性质 中山 (2025)粤20民终1136 勿作抗辩 13 特惠快车 = 营运 （独立非拼车收费服务） 湛江 (2025)粤08民终951 网约车定性 四、三个\"别踩\" 1. 营运车案件不要再打提示说明义务。 湛江案已明确 §52 是法定义务。你的牌只有\"没改变使用性质\"和\"危险程度未显著增加\"。 2. \"连续多年在同一家保险公司投保\"是双刃剑。 揭阳案用它认定保险人已履行说明义务。如果你的当事人是多年续保，说明义务这条路基本堵死，转向其他争点。 3. 顺风车接单量一旦过百、路线跨市，基本必输。 中山两案、湛江案、揭阳案四案口径完全一致。真想保住理赔，投保时就按营运性质投保——这是唯一稳妥解。 与其他页面的关系 车险逐争点打法 ：L1 险种层/05 车险 财产险与责任险 ：L1 险种层/06 财产险与责任险 第一辑（人身险 A 级判例） ：L2 案例库/广东二审判决原文精读 A级 提示说明义务专题 ：L2 案例库/专题 提示说明义务与电子投保 时效速查表 ：README 法条原文 ：L4 法条库/00 法条与司法解释原文"}, {"id": "L2-案例库/广东二审判决原文精读-A级", "group": "3 · 广东案例库", "groupKey": "L2-案例库", "title": "广东二审判决原文精读 · 第一辑（人身险）", "order": 3, "file": "广东二审判决原文精读-A级.md", "html": "<h1 id=\"s0\">广东二审判决原文精读 · 第一辑（人身险）</h1>\n<blockquote>📌 <strong>另有第二辑（车险 / 财产险 / 代位求偿）</strong>：<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7-%E7%AC%AC%E4%BA%8C%E8%BE%91\">《广东二审判决原文精读 · 第二辑（车险 / 财产险 / 代位求偿）》</a>（A 级）</blockquote>\n<blockquote><strong>可信度：A 级。</strong> 本文全部案例来自裁判文书网<strong>判决书原文</strong>（2026-09-16 导出），<br>含案号、审理法院、一审案号、裁判理由原文摘录。括号引用均为判决书<strong>逐字原文</strong>。<br>当事人名称按裁判文书网公开脱敏规则以\"某\"代称，非本站改动的脱敏。<br><br><strong>使用说明</strong>：引用时写\"广东省××市中级人民法院（20××）粤××民终××××号民事判决\"，<br>与本站其他 B 级案例（法院官网/官媒发布）区分开。<strong>A 级可直接写进代理词。</strong></blockquote>\n<h2 id=\"s1\">本文案例总览</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>案号</th><th>法院</th><th>险种</th><th>核心争点</th><th>结果</th></tr></thead><tbody>\n<tr><td>A1</td><td>(2025)粤03民终8930号</td><td>深圳中院</td><td>重疾险</td><td>免责说明视频\"直接跳转\"</td><td>投保人胜</td></tr>\n<tr><td>A2</td><td>(2026)粤01民终10449号</td><td>广州中院</td><td>团体重疾</td><td>ICD-10 未列明 + 团体盖章</td><td>投保人胜</td></tr>\n<tr><td>A3</td><td>(2024)粤01民终28133号</td><td>广州中院</td><td>少儿重疾</td><td>加黑加粗 ≠ 明确说明</td><td>投保人胜</td></tr>\n<tr><td>A4</td><td>(2025)粤14民终795号</td><td>梅州中院</td><td>重疾险</td><td>疾病定义限缩 = 隐性免责</td><td>投保人胜</td></tr>\n<tr><td>A5</td><td>(2026)粤08民终2074号</td><td>湛江中院</td><td>意外险</td><td>无证驾驶免责 + 免赔天数</td><td>投保人胜</td></tr>\n<tr><td>A6</td><td>(2026)粤17民终14号</td><td>阳江中院</td><td>骑手意外</td><td>职业伤害保障免责</td><td>投保人胜</td></tr>\n<tr><td>B1</td><td>(2026)粤03民终9578号</td><td>深圳中院</td><td>重疾险</td><td>原位癌伴微浸润</td><td>投保人胜</td></tr>\n<tr><td>B2</td><td>(2026)粤08民终2416号</td><td>湛江中院</td><td>重疾险</td><td>交界性肿瘤排除条款</td><td>投保人胜</td></tr>\n<tr><td>B3</td><td>(2025)粤01民终24935号</td><td>广州中院</td><td>百万医疗</td><td>既往症 + 示范视频</td><td>条款胜/金额受限</td></tr>\n<tr><td>C1</td><td>(2025)粤06民终13672号</td><td>佛山中院</td><td>重疾险</td><td>如实告知两要件</td><td>投保人胜</td></tr>\n<tr><td>C2</td><td>(2026)粤01民终4391号</td><td>广州中院</td><td>团体重疾</td><td>概括性勾选表格</td><td>投保人胜</td></tr>\n<tr><td>C3</td><td>(2026)粤03民终3156号</td><td>深圳中院</td><td>重疾险</td><td>代理人已知 = 保险人已知</td><td>投保人胜</td></tr>\n<tr><td>C4</td><td>(2026)粤08民终2416号</td><td>湛江中院</td><td>重疾险</td><td>页面没有的病无告知义务</td><td>投保人胜</td></tr>\n<tr><td>C5</td><td>(2024)粤03民终12700号</td><td>深圳中院</td><td>重疾险</td><td>拒赔后继续扣保费</td><td>投保人胜</td></tr>\n<tr><td>D1</td><td>(2025)粤15民终501号</td><td>汕尾中院</td><td>驾乘意外</td><td>提示说明已履行（反面案例）</td><td><strong>保险人胜</strong></td></tr>\n<tr><td>D2</td><td>(2026)粤03民终2970号</td><td>深圳中院</td><td>骑手意外</td><td>猝死 + 自动投保格式条款</td><td>投保人胜</td></tr>\n</tbody></table></div>\n<hr>\n<h1 id=\"s2\">一、提示说明义务：什么才算\"说清楚了\"</h1>\n<h2 id=\"s3\">A1 · 深圳中院 (2025)粤03民终8930号 —— 可跳过的视频 = 没说明</h2>\n<ul>\n<li><strong>一审</strong>：广东省深圳市福田区人民法院 (2024)粤0304民初53008号</li>\n<li><strong>案由</strong>：人身保险合同纠纷（重大疾病保险金 35 万元）</li>\n<li><strong>结果</strong>：驳回上诉，维持原判 → 保险人给付</li>\n</ul>\n<p><strong>保险人做了什么</strong>：投保流程里有免责条款的说明视频，投保人也完成了电子签名。 <strong>法院怎么看</strong>：</p>\n<blockquote>\"对于保险人履行免责条款提示与说明义务的认定标准，根据《最高人民法院关于适用《中华人民共和国保险法》若干问题的解释（二）（2020年修正）》第十二、十三条之立法精神，应以保险人有进行提示与解释说明的作为<strong>且该作为达到使投保人了解免责条款内容的程度</strong>。本案中，某深圳分公司对于免责条款的提示与说明虽有作为，但<strong>因视频直接跳转而未能达到使投保人了解免责条款内容之认定标准</strong>，一审判决某深圳分公司未尽到提示与明确说明义务，涉案免责条款无效，该裁判结论正确，本院依法予以维持。\"</blockquote>\n<p><strong>要旨 🔑</strong>：说明义务的判准是<strong>结果</strong>不是<strong>动作</strong>。做了视频 ≠ 履行了义务；视频能被跳过、自动跳转、默认勾选，就等于没说。</p>\n<p><strong>怎么用</strong></p>\n<ol>\n<li>把保险人提交的\"投保流程演示\"拿过来，<strong>逐帧看能不能跳过</strong>——可跳过即命中本条。</li>\n<li>主张：保险人须证明该视频<strong>实际播放完成</strong>且不可跳过，否则\"作为\"未达\"使投保人了解\"的程度。</li>\n<li>这是广东法院对合同编通则解释 §10③（仅勾选、弹窗不足以认定）的<strong>本地呼应</strong>，可以并列援引。</li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §17②、解释二 §12–13、合同编通则解释 §10③</p>\n<hr>\n<h2 id=\"s4\">A2 · 广州中院 (2026)粤01民终10449号 —— 引 ICD-10 却不列明 = 未说明</h2>\n<ul>\n<li><strong>一审</strong>：广东省广州市天河区人民法院 (2024)粤0106民初33199号</li>\n<li><strong>裁判日期</strong>：2026 年 6 月 11 日</li>\n<li><strong>案由</strong>：团体人身保险（重大疾病），主动脉手术</li>\n</ul>\n<p><strong>保险人抗辩</strong>：免责条款含\"遗传性疾病、先天性畸形、变形或染色体异常\"；被保险人患\"先天性主动脉瓣二叶瓣畸形\"，属先天性疾病；团体投保单已盖章。</p>\n<blockquote>\"某保险公司<strong>并未将《疾病和有关健康问题的国际统计分类》（ICD-10）中关于'遗传性疾病、先天性畸形、变形或染色体异常'的定义和分类在案涉《保险合同》中列明，亦未提供证据证明已就前述疾病向某银行作出了常人能够理解的解释说明</strong>。而关于'先天性畸形'等疾病属于专业的医学术语，在保险人不作特别说明的情况下，投保人难以准确理解该等疾病的具体内涵以及该等疾病作为免责条款对投保人权益产生的影响，故《保险合同》着重列明的概括性条款并不意味着保险人已履行前述免责条款的明确说明义务，<strong>更不能以投保人的签章行为推定其已完全理解前述免责条款及相应的法律后果，否则对投保人而言明显不公</strong>。\"</blockquote>\n<p><strong>要旨 🔑</strong>：① 条款引用外部分类标准（ICD-10/ICD-O-3）的，<strong>必须把具体内容列进合同或另行说明</strong>；② <strong>盖章 ≠ 理解</strong>——明确否定了\"签章推定\"的绝对效力。</p>\n<p><strong>怎么用</strong>：遇到免责条款写着\"××依照 ICD-10 确定\"的，直接问：<strong>ICD-10 那几页在哪？给我看。</strong> 拿不出来就是未说明。</p>\n<p><strong>关联法条</strong>：保险法 §17②、解释二 §11</p>\n<hr>\n<h2 id=\"s5\">A3 · 广州中院 (2024)粤01民终28133号 —— 加黑加粗 ≠ 明确说明</h2>\n<ul>\n<li><strong>一审</strong>：广东省广州市增城区人民法院 (2024)粤0118民初3216号</li>\n<li><strong>裁判日期</strong>：2024 年 12 月 12 日</li>\n<li><strong>案由</strong>：少儿重疾 + 住院医疗，\"先天性疾病\"免责</li>\n</ul>\n<blockquote>\"上述条款<strong>虽然采用加黑、加粗方式提醒投保人注意</strong>，但鉴于合同中仅明确对于先天性畸形的概念符合《疾病和有关健康问题的国际统计分类》（ICD-10）确定的'先天性畸形、变更或染色体异常'的分类和定义，<strong>保险公司未能举证说明其对于先天性畸形的概念、内容作出具体解释，且为一般人能够知晓和理解</strong>，陈某、欧阳某作为不具有医学专业知识的自然人，显然无法充分理解该免责条款适用的疾病范围，一审法院据此认定某保险公司未对免责条款进行充分解释说明义务且该免责条款对于案涉被保险人不产生效力正确，本院予以维持。\"</blockquote>\n<p><strong>要旨 🔑</strong>：<strong>\"提示\"和\"明确说明\"是两项独立义务，加黑加粗只完成前者。</strong> 法官原话逻辑很干净：加黑加粗 = 提示 ✓；但\"概念、内容作出具体解释，且为一般人能够知晓和理解\" = 明确说明 ✗。</p>\n<p><strong>同案另外两条实用规则</strong></p>\n<ul>\n<li><strong>少儿特定重疾保险金 + 少儿特定重疾陪护保险金可以同时主张</strong>。保险人主张\"已发生重大疾病则不再付少儿特定重疾保险金\"的，法院以\"缺乏合同依据\"驳回。</li>\n<li><strong>\"同一次住院\"的认定</strong>：因同一原因再次住院、与前次出院间隔未超 30 日的，视为同一次住院，<strong>只适用一次赔付限额</strong>。（这条对投保人不友好，算医疗费时要先自己算一遍。）</li>\n</ul>\n<p><strong>关联法条</strong>：保险法 §17②、解释二 §11</p>\n<hr>\n<h2 id=\"s6\">A4 · 梅州中院 (2025)粤14民终795号 —— 疾病定义限缩 = 隐性免责（含取证技巧）</h2>\n<ul>\n<li><strong>一审</strong>：广东省丰顺县人民法院 (2025)粤1423民初239号（注：粤1423 为丰顺县）</li>\n<li><strong>裁判日期</strong>：2025 年 7 月 22 日</li>\n<li><strong>案由</strong>：重大疾病保险，\"严重Ⅰ型糖尿病\"</li>\n</ul>\n<p><strong>条款</strong>：要求同时满足①持续依赖外源胰岛素 180 天以上；②血胰岛素/C 肽测定异常；③出现三种并发症之一（增殖性视网膜病变 / 心脏病并植入起搏器 / 至少一个脚趾坏疽达切除指征）。</p>\n<blockquote>\"显然，上诉人保险公司的上述糖尿病定义应满足的多种并发症情形<strong>已超出一般人对'严重Ⅰ型糖尿病'的理解，极大缩小了一般医学标准，直接影响是否符合理赔标准</strong>。上诉人保险公司在签订案涉保险合同时有义务向投保人释明所涉疾病的具体情形，<strong>不论是在释义部分还是免责条款中</strong>……<br>案涉的保险合同为电子保单，且<strong>合同第33-34页中77点对'严重Ⅰ型糖尿病'并发症的定义部分并未有加粗加重或其他足以提醒投保人慎重阅读、理解的标识，与同页上诉人保险公司提醒标识加粗加黑及灰色的其他重要条款字体的背景明显不一致，不足以引起投保人注意</strong>。<br>再者，上诉人保险公司免责条款2.2条<strong>仅是指引投保人应注意其他条款，并非直接免责的内容</strong>……上诉人辩称案涉合同主要是通过电话回访履行告知提醒及免责义务，但根据现有证据不足以证实……\"</blockquote>\n<p><strong>要旨 🔑（三条，条条是武器）</strong></p>\n<ol>\n<li><strong>疾病定义只要限缩了常人理解，就是免责条款，写在\"释义\"里也一样。</strong></li>\n<li>🔥 <strong>取证技巧：同一页上，别的条款加粗加黑、争议条款没加粗 → 对比本身就是\"未提示\"的证据。</strong> 打印条款那一页，做标注，胜过一个小时的口头论证。</li>\n<li><strong>\"请投保人注意其他条款\"的指引条款 ≠ 免责条款本身</strong>，不能替代说明义务；<strong>电话回访不能替代投保时的说明</strong>。</li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §17②、解释二 §9（隐性免责）、§11</p>\n<hr>\n<h2 id=\"s7\">A5 · 湛江中院 (2026)粤08民终2074号 —— 电子签名 ≠ 已说明；免赔天数也是免责条款</h2>\n<ul>\n<li><strong>一审</strong>：广东省廉江市人民法院 (2026)粤0881民初42号</li>\n<li><strong>案由</strong>：意外伤害保险（身故 20 万 + 意外医疗 1 万 + 住院津贴），驾驶人无证驾驶</li>\n</ul>\n<blockquote>\"上诉人<strong>仅提交带有周某丁电子签名的投保单，但无任何证据证明投保人签名前页面完整展示保险条款、无弹窗单独提示免责内容、无线上确认阅读免责条款的操作记录、无任何针对免责条款的解释说明记录</strong>。<strong>电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务。</strong>\"<br><br>\"案涉意外伤害意外保险属于人身保险，<strong>原则上不适用'损害填补'原则</strong>，交通事故的侵权人是否已赔偿周某丁的医疗费，不影响……应承担的赔付意外伤害医疗费保险金的责任\"<br><br>\"对于保险合同约定的<strong>免赔3天属于免责条款</strong>，如前所述，免责条款不生效，……应按照42天计算意外伤害住院津贴\"</blockquote>\n<p><strong>要旨 🔑</strong></p>\n<ol>\n<li><strong>\"电子签名只证明投保操作完成\"</strong> —— 一句话击穿保险人最常举的证据。</li>\n<li><strong>免赔天数、免赔额、免赔率、比例赔付统统是免责条款</strong>（解释二 §9 明文），未提示说明即不生效。本案住院津贴因此从 1950 元变 2100 元。</li>\n<li><strong>人身意外险不适用损失补偿原则</strong>：第三方（侵权人）赔过了，意外医疗照样赔。</li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §17②、解释二 §9、§12</p>\n<hr>\n<h2 id=\"s8\">A6 · 阳江中院 (2026)粤17民终14号 —— 免责内容本身违反公平原则，双重打击</h2>\n<ul>\n<li><strong>一审</strong>：广东省阳江市江城区人民法院 (2025)粤1702民初9088号</li>\n<li><strong>案由</strong>：新就业形态骑手意外伤害保险（伤残 6 万）</li>\n</ul>\n<p><strong>保险人抗辩</strong>：已向投保人（平台/劳务公司）发送邮件告知免责条款，投保人回复确认已阅读。</p>\n<blockquote>\"某保险公司杭州中心支公司据以主张免于赔偿责任的前述保险条款是为免除……赔付责任的情况作出约定，根据解释（二）第九条第一款关于'……<strong>免赔额、免赔率、比例赔付或者给付等免除或者减轻保险人责任条款</strong>，可以认定为保险法第十七条第二款规定的免除保险人责任的条款'之规定，该条款应被认定为免责条款。<br>但是……<strong>并未在保单中用特别的文字、符号或其他明显标识对该条款另以标明以引起投保人冯某的注意，亦未提供证据证明其向冯某就此问题作出常人能够理解的解释说明</strong>，因此应当认定……该免责条款对冯某不产生效力。<br><strong>另外，案涉免责条款将已从人社部门获得职业伤害保障作为免除自身赔付责任的情形，不当排除了新就业形态劳动者的合法权利，有违公平原则</strong>……\"</blockquote>\n<p><strong>要旨 🔑</strong>：双保险打法——① 没提示说明 → 条款不生效；② <strong>即使提示了，内容本身\"不当排除新就业形态劳动者权利、有违公平\"</strong>，可以再用 §19（格式条款无效）打一遍。 另：<strong>向平台/经纪公司发邮件告知，不等于向被保险人（骑手）说明</strong>。被保险人不是邮件接收方。</p>\n<p><strong>关联法条</strong>：保险法 §17②、§19、解释二 §9；民法典 §497</p>\n<hr>\n<h1 id=\"s9\">二、疾病定义与赔付范围</h1>\n<h2 id=\"s10\">B1 · 深圳中院 (2026)粤03民终9578号 —— ICD 编码不能否定病理报告</h2>\n<ul>\n<li><strong>一审</strong>：广东省深圳市罗湖区人民法院 (2025)粤0303民初20428号</li>\n<li><strong>裁判日期</strong>：2026 年 3 月 30 日</li>\n<li><strong>争点</strong>：\"（左乳）导管原位癌，局灶间质微浸润\"是否属\"恶性肿瘤——重度\"（条款排除 ICD-O-3 编码 0/1/2）</li>\n</ul>\n<blockquote>\"被上诉人仇某某的《临床病理诊断补充报告书》载明其病理诊断为'（左乳）导管原位癌，局灶间质微浸润'，其中'微浸润'在医学上指癌细胞突破基底膜并侵入周围间质组织，符合恶性肿瘤浸润性生长的生物学特性。<strong>尽管原位癌的形态学编码为2，但该编码系基于主要病理特征的整体归类，不能否定病理诊断中已明确记载的浸润性病变事实。</strong>保险合同条款未明确将'局灶间质微浸润'排除在'恶性肿瘤——重度'定义之外，且该病变已实质满足'恶性细胞浸润周围正常组织'的合同约定要件。另外，保险合同作为格式合同，在合同相关条款约定不明确，双方有争议的情况下，依法亦应当作出<strong>有利于被保险人的解释</strong>。\"</blockquote>\n<p><strong>要旨 🔑</strong>：条款的定义用的是\"浸润和破坏周围正常组织\"这样的<strong>实质特征</strong>，ICD 编码只是归类工具。<strong>病理报告写\"微浸润\"就满足了实质特征，编码不能反过来否定病理事实。</strong></p>\n<p><strong>怎么用</strong>：拿到病理报告先找\"浸润\"\"侵犯\"\"突破基底膜\"字样；有之，即主张满足实质要件 → §30 不利解释兜底。</p>\n<p><strong>关联法条</strong>：保险法 §30；重疾定义规范 2020（3.3.2）</p>\n<hr>\n<h2 id=\"s11\">B2 · 湛江中院 (2026)粤08民终2416号 —— 写在\"释义\"里的排除列举，也是免责条款</h2>\n<ul>\n<li><strong>一审</strong>：广东省廉江市人民法院 (2026)粤0881民初1687号</li>\n<li><strong>裁判日期</strong>：2026 年 8 月 7 日</li>\n<li><strong>案由</strong>：重疾险（卵巢交界性肿瘤），保险金 499,416 元</li>\n</ul>\n<p><strong>条款</strong>：重度疾病释义 7.20 将\"恶性肿瘤——重度\"限定为 ICD-O-3 形态学编码 3、6、9；并单列\"下列疾病不属于恶性肿瘤重度……b.交界性肿瘤……\"。</p>\n<blockquote>\"案涉保险合同条款7.20还约定'下列疾病不属于\"恶性肿瘤重度\"，不在保障范围内：1）ICD-O-3肿瘤形态学编码属于0（良性肿瘤）、1（动态未定性肿瘤）、2（原位癌和非侵袭性癌）范畴的疾病，如：……b.交界性肿瘤……'，<strong>但该约定实质限缩了恶性肿瘤的理赔范围、减轻了保险人的保险赔付责任，依法属于免除保险人责任的条款</strong>。依照保险法第十七条第二款……的规定，某保险公司深圳分公司在投保前的电子投保环节未依法向投保人明确说明该免责条款内容，<strong>该免责条款依法不产生效力</strong>。\"</blockquote>\n<p><strong>要旨 🔑</strong>：<strong>\"不在保障范围内\"的排除列举，即便放在\"释义/定义\"章节，只要实质限缩责任，就是免责条款，未说明即不生效。</strong> 保险人最爱说\"这是责任范围条款不是免责条款，所以我不用提示说明\"——本案直接驳回这个说法。</p>\n<p><strong>同案第二条（迟延赔付利息）</strong></p>\n<blockquote>\"依照保险法第二十三条第一、第二款……保险人未及时履行前款规定义务的，除支付保险金外，应当赔偿被保险人或者受益人因此受到的损失……一审法院判令……按照全国银行间同业拆借中心公布的贷款市场报价利率向沈某赔付资金占用损失合理合法，本院予以维持。\"</blockquote>\n<p>→ <strong>迟延赔付的利息（LPR）法院支持，一定要一并主张。</strong></p>\n<p><strong>关联法条</strong>：保险法 §17②、§23、解释二 §9</p>\n<hr>\n<h2 id=\"s12\">B3 · 广州中院 (2025)粤01民终24935号 —— \"示范视频\"不是你的投保轨迹（附反面教训）</h2>\n<ul>\n<li><strong>一审</strong>：广东省广州市番禺区人民法院 (2025)粤0113民初4611号</li>\n<li><strong>二审判决日期</strong>：2026 年 4 月 9 日</li>\n<li><strong>案由</strong>：百万医疗保险（互联网专属），既往症免责</li>\n</ul>\n<p><strong>一审原文（二审维持）</strong>：</p>\n<blockquote>\"因本案为互联网保险产品，解释（二）第十二条规定，通过网络、电话等方式订立的保险合同，保险人以网页、音频、视频等形式对免除保险人责任条款予以提示和明确说明的，人民法院可以认定其履行了提示和明确说明义务。本案中，张某甲主张其父张某乙代其手机自助投保，但<strong>某公司广州分公司提交的投保示范视频并非张某甲父亲代投保时的视频轨迹，仅凭投保单上'张某甲'的签名字样尚不足以证明</strong>某公司广州分公司已通过人工、网页、音频、视频等任何形式说明免责条款的内容及法律后果。\"</blockquote>\n<p><strong>要旨 🔑</strong>：保险人常拿<strong>通用\"投保流程演示视频\"</strong>（甚至是可回溯管理里别人的轨迹）当证据。<strong>一句话击穿：这不是本案投保人的投保轨迹。</strong> 要求其提供<strong>本次投保的可回溯记录</strong>（监管要求互联网保险可回溯，拿不出来就是没做）。</p>\n<p><strong><span class=\"warn\">!</span> 同案反面教训（必须知道）</strong></p>\n<ul>\n<li>法院认定<strong>百万医疗险属补偿性保险合同，适用损失补偿原则</strong>：医保统筹基金已支付的 40,947.49 元要从理赔中扣除 → 5,378.84 元诉求扣完只剩 1,231.35 元。</li>\n<li>一般医疗保额 200 万未赔满前，不能跳到\"恶性肿瘤——重度医疗\"责任项下重复主张。</li>\n<li><strong>教训</strong>：赢了免责条款，也可能输在金额上。投保时看清\"是否限社保范围内\"\"免赔额多少\"。</li>\n</ul>\n<p><strong>关联法条</strong>：保险法 §17②、解释二 §12</p>\n<hr>\n<h1 id=\"s13\">三、如实告知义务</h1>\n<h2 id=\"s14\">C1 · 佛山中院 (2025)粤06民终13672号 —— 保险人必须证明\"足以影响承保\"</h2>\n<ul>\n<li><strong>一审</strong>：广东省佛山市顺德区人民法院 (2025)粤0606民初37706号</li>\n<li><strong>案由</strong>：重疾险（甲状腺乳头状癌），保险人以\"曾因胸痛就医未告知\"拒赔</li>\n</ul>\n<blockquote>\"保险人以投保人未履行如实告知义务为由解除合同需满足<strong>两个条件</strong>：投保人因故意或重大过失未如实告知；<strong>未告知事项足以影响保险人决定是否同意承保或者提高保险费率</strong>。张某虽曾因胸痛就医，但相关检查结果（如心电图、DR检查）均未发现明确异常，张某主观上不具有刻意隐瞒的故意或重大过失，且现有证据不能证明胸痛与后续确诊的甲状腺乳头状癌存在关联，<strong>某公司未举证证明上述未告知事项按照一般的核保规则足以影响其是否同意承保或者提高保险费率</strong>。\"</blockquote>\n<p><strong>要旨 🔑</strong>：保险人必须<strong>按\"一般核保规则\"举证</strong>，不是嘴上说\"影响了\"就行。要求其出示<strong>核保手册/核保规则</strong>，证明该情形在正常核保中会导致拒保或加费。多数保险人拿不出来。</p>\n<p><strong>关联法条</strong>：保险法 §16①②</p>\n<hr>\n<h2 id=\"s15\">C2 · 广州中院 (2026)粤01民终4391号 —— 概括性勾选表格 = 没询问；迟延利息可主张，律师费不行</h2>\n<ul>\n<li><strong>一审</strong>：广东省广州市越秀区人民法院 (2025)粤0104民初42006号</li>\n<li><strong>案由</strong>：团体重疾（300 多名职工），乳腺结节 → 乳腺癌，保额 15 万</li>\n</ul>\n<blockquote>\"案涉保险是团体险，投保人为某乙公司，被保险人有300多名职工，且之前由某公司珠海分公司进行连续投保。<strong>某保险公司广东分公司既无对被保险人的健康进行询问，也无要求某乙公司对所有职工的健康情况进行调查，其仅以一个表格要求某乙公司对所有职工的既往病史进行概括性的勾选，不能认定其已尽到应有的询问义务。</strong>某乙公司无法了解每个员工体检中出现的问题，在此情况下进行概况性的勾选，<strong>不能认定其作为投保人有故意或者重大过失</strong>……<br>且被保险人李某仅是因在连续投保的体检中发现存在结节，该结节也并不会必然导致乳腺癌的发生，故不能认定其存在故意隐瞒重大疾病的情形。<strong>另外，某保险公司广东分公司也从未要求解除合同。</strong><br>考虑到李某于2024年12月5日申请理赔，保险合同约定核保最长时间为30天，本院酌定……应支付从2025年1月4日起至实际支付保险金之日止<strong>逾期理赔的利息</strong>（按照同期全国银行间同业拆借中心公布的贷款市场报价利率标准计算）。<strong>由于律师费不是维权必须产生的费用，且无合同依据，故本院不予支持。</strong>\"</blockquote>\n<p><strong>要旨 🔑（四条）</strong></p>\n<ol>\n<li><strong>团体险的\"一张表格概括性勾选\"不构成有效询问</strong> → 未询问即无告知义务。</li>\n<li><strong>\"结节不必然导致癌症\"</strong> → 因果关系要保险人证明。</li>\n<li><strong>保险人\"从未要求解除合同\"本身是抗辩点</strong>（未行使解除权，直接拒赔无依据）。</li>\n<li><strong>迟延利息：可主张，从核定期届满次日起按 LPR 算。律师费：不支持</strong>，别浪费一个诉请。</li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §16、§23；解释二 §6</p>\n<hr>\n<h2 id=\"s16\">C3 · 深圳中院 (2026)粤03民终3156号 —— 跟代理人说了 = 跟保险公司说了</h2>\n<ul>\n<li><strong>一审</strong>：广东省深圳市宝安区人民法院 (2025)粤0306民初22941号</li>\n<li><strong>案由</strong>：重疾险，甲状腺结节 → 甲状腺癌</li>\n</ul>\n<p><strong>事实</strong>：投保书\"甲状腺病史\"栏勾选了\"否\"，但<strong>投保当日投保人已通过微信向保险代理人披露</strong>\"2022 年存在甲状腺结节、定期复查无需治疗\"。</p>\n<blockquote>\"<strong>保险代理人作为上诉人某保险公司深圳分公司的职务代理人，其知晓投保人告知的甲状腺结节病史应视为上诉人已知晓该事实。</strong>投保人后续根据上诉人要求提交的2023年4月甲状腺检查报告及2022年肛周脓肿病历中，亦明确载明'常规体检发现甲状腺结节，医生叮嘱定期复查，无需治疗'，<strong>进一步履行了补充告知义务</strong>。<strong>上诉人收到上述资料后未提出异议并签发保险合同，表明其已接受投保人披露的病史信息并作出承保决定。</strong><br>此外，上诉人于2023年6月6日发出的《补充健康状况资料通知函》中，<strong>仅要求提供2023年4月甲状腺检查史及既往病史，未明确要求提交2022年5月11日超声检查报告</strong>……投保人未主动提交该报告不构成重大遗漏。<br><strong>上诉人主张被上诉人作为医生应承担更高注意义务，但法律未因被保险人的职业背景而加重投保人的告知义务</strong>……\"</blockquote>\n<p><strong>要旨 🔑（三条，都极实用）</strong></p>\n<ol>\n<li>🔥 <strong>向代理人披露 = 向保险人披露</strong>（职务代理 + 保险法 §16⑥\"保险人在合同订立时已经知道\"）。<strong>微信聊天记录留好，这是救命证据。</strong></li>\n<li><strong>保险人收到资料后未提异议并签发保单 = 接受披露、作出承保决定。</strong></li>\n<li><strong>职业背景（医生、护士等）不加重告知义务。</strong></li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §16①②⑥、解释二 §6</p>\n<hr>\n<h2 id=\"s17\">C4 · 湛江中院 (2026)粤08民终2416号 —— 页面上没有的病，投保人没有义务自己发明</h2>\n<ul>\n<li><strong>事实</strong>：健康告知页面\"肿瘤\"项下未包含\"交界性肿瘤\"；\"肿物/结节/占位\"项下也无该选项；投保人选择了\"卵巢囊肿\"（与手术名称\"腹腔镜下右侧卵巢囊肿切除术\"一致）。</li>\n<li>另：保险人问了\"是否患乙肝\"，但投保人投保前<strong>从无乙肝的正式诊疗结论</strong>，仅有一次检验指标超标 + CT\"考虑血管瘤\"。</li>\n<li>又：系统问\"过去2年内住院超5天/手术/连续服药超30天\"，但<strong>进入下一环节后系统根本没再问住院天数</strong>。</li>\n</ul>\n<blockquote>\"沈某按照操作指引进入'有部分问题快速评估能否投保'环节，在页面中出现的选项中并无'卵巢交界性肿瘤'，沈某在多个选项中选择'卵巢囊肿'，<strong>系其作为非医学专业人士凭借常识选择最接近选项进行评估</strong>，且与沈某此前手术名称……相符合，故<strong>沈某已经向某保险公司深圳分公司主动告知其患病情况，而非恶意隐瞒患病情况</strong>。\"<br><br>\"并无证据证实沈某投保前被确诊乙肝的正式诊疗结论，亦无证据证实沈某曾因乙肝相关病症就诊、用药，故<strong>沈某作为非医学专业人士，不能苛责其对检验报告作出专业医学判断</strong>。\"<br><br>\"<strong>投保环节中也没有任何可供被保险人专门告知'住院治疗超5天、或做过手术、或遵医嘱需要连续服药超过30天'的环节。</strong>据此，沈某不存在未如实告知2年内住院、手术及连续服药史的情况。\"</blockquote>\n<p><strong>要旨 🔑（三条）</strong></p>\n<ol>\n<li><strong>告知义务以\"保险人询问的范围和内容\"为限</strong>（解释二 §6）。<strong>页面选项里没有的病，投保人没义务凭医学知识自己填。</strong></li>\n<li><strong>\"不能苛责非医学专业人士对检验报告作出专业医学判断\"</strong> —— 指标异常 ≠ 患有该疾病。</li>\n<li><strong>系统没给入口 = 保险人没问。</strong> 问了前半句、没给后半句入口的，视为未询问。</li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §16①、解释二 §6</p>\n<hr>\n<h2 id=\"s18\">C5 · 深圳中院 (2024)粤03民终12700号 —— 拒赔之后还在扣保费 = 解除不成立</h2>\n<ul>\n<li><strong>一审</strong>：广东省深圳市罗湖区人民法院 (2023)粤0303民初7703号</li>\n<li><strong>裁判日期</strong>：2025 年 3 月 21 日</li>\n</ul>\n<blockquote>\"《最高人民法院关于适用若干问题的解释（二）（2020年修正）》第七条规定，保险人在保险合同成立后知道或者应当知道投保人未履行如实告知义务，<strong>仍然收取保险费</strong>，又依照保险法第十六条第二款的规定主张解除合同的，<strong>人民法院不予支持</strong>。<br>本案中，上诉人某公司在2023年2月10日作出拒赔通知书，决定解除合同，但<strong>在此之后，上诉人仍于2023年2月25日、3月21日收取了投保人的苏某·重疾险的保险费每期56.25元</strong>……上诉人主张因系统处理存在延迟导致错误收取保费，但<strong>未能提供充分证据证明其在发现投保人未履行如实告知义务后及时关闭了扣费系统或扣费链接</strong>。因此……<strong>应视为其尚未解除合同</strong>，现其在诉讼中再以同一理由主张合同解除，本院不予支持。\"</blockquote>\n<p><strong>要旨 🔑（杀手锏级）</strong>：<strong>拿到拒赔通知书后，第一件事是去查银行流水/扣费记录——保险人还在扣费吗？</strong> 还在扣 = 依解释二 §7 视为未解除合同，解除主张直接被否。保险人\"系统延迟\"的抗辩，法院要求它<strong>举证已关闭扣费链接</strong>，通常拿不出来。</p>\n<p><strong>关联法条</strong>：保险法 §16②、解释二 §7</p>\n<hr>\n<h1 id=\"s19\">四、格式条款、赔付范围与\"反面案例\"</h1>\n<h2 id=\"s20\">D1 · 汕尾中院 (2025)粤15民终501号 —— <span class=\"warn\">!</span> 提示说明义务不是必胜（必读反面案例）</h2>\n<ul>\n<li><strong>一审</strong>：广东省陆丰市人民法院 (2024)粤1581民初2742号</li>\n<li><strong>裁判日期</strong>：2025 年 8 月 20 日</li>\n<li><strong>案由</strong>：驾乘意外伤害保险（60 万）</li>\n</ul>\n<blockquote>\"二审期间，平某公司向本院提交了投保单及<strong>投保人通过电子形式投保驾乘意外险时的照片</strong>，以及……<strong>黄某甲在投保单上'投保人声明'处签名确认收到保险条款并确认平某公司已向其本人介绍了条款的内容，特别就保险条款中免除保险人责任的条款内容和手写或打印版的特别约定内容做了明确说明。相关保险条款中也进行了加黑加粗</strong>，足以证实黄某甲在投保时已确认知悉了保险条款内容……<br>根据解释（二）第十二条……<strong>本院认定平某公司已在投保时向黄某甲对上述责任免责条款履行了提示和明确说明义务。</strong>\"</blockquote>\n<p><strong>后果</strong>（对投保人不利的部分，必须知道）：</p>\n<ul>\n<li>伤残按合同比例：十级 10% = 6 万；九级 20% = 12 万（不是按交通事故标准全额）</li>\n<li>医疗费<strong>扣减第三方已赔的 30% 份额 + 免赔额 100 元</strong></li>\n<li>住院伙食补助费、营养费、护理费、交通费、误工费、伤残赔偿金（按侵权口径）、精神损害抚慰金、被扶养人生活费 → <strong>均不支持</strong></li>\n<li>✅ <strong>唯一对投保人有利的</strong>：鉴定费 4,872 元由保险人承担</li>\n</ul>\n<blockquote>\"根据《中华人民共和国保险法》第六十四条：'保险人、被保险人为查明和确定保险事故的性质、原因和保险标的的损失程度所支付的必要的、合理的费用，由保险人承担'的规定，该鉴定费应由平某公司承担\"</blockquote>\n<p><strong>要旨 <span class=\"warn\">!</span></strong></p>\n<ol>\n<li><strong>\"电子投保照片 + 投保人声明签名 + 加黑加粗\"三件套齐备时，法院会认定已履行。</strong> 提示说明义务不是必胜牌——<strong>别把全部筹码押在这一张牌上。</strong></li>\n<li><strong>鉴定费（§64）几乎必支持</strong>，是很稳的小额诉请。</li>\n<li><strong>驾乘意外险是按合同比例定额给付的</strong>，不是按交通事故赔偿标准算。买之前要看清比例表。</li>\n</ol>\n<hr>\n<h2 id=\"s21\">D2 · 深圳中院 (2026)粤03民终2970号 —— 平台自动投保 = 纯格式条款；\"必须尸检\"也是免责条款</h2>\n<ul>\n<li><strong>一审</strong>：广东省深圳市罗湖区人民法院 (2025)粤0303民初3354号</li>\n<li><strong>裁判日期</strong>：2026 年 2 月 11 日</li>\n<li><strong>案由</strong>：外卖骑手意外险，猝死，保额 60 万</li>\n</ul>\n<blockquote>\"某公司作为投保人，通过电子投保方式与某深圳分公司订立保险合同，<strong>投保流程中骑手接单后系统自动扣收保费并生成保单，并无证据显示投保人及被保险人对合同条款有协商或修改的权利</strong>。特别约定中关于'猝死'的界定及赔付条件，包括'工作时间''工作岗位'的限制性要求以及'<strong>必须尸检</strong>'等义务性规定，均系某深圳分公司为重复使用而预先设定的标准化内容。该条款的适用对象为不特定骑手群体，具有普遍适用性和不可变更性，<strong>符合格式条款的特征</strong>。某深圳分公司主张特别约定为其与某公司经过合意磋商做出的个性化约定，<strong>但未能提供证据证明该条款系与投保人协商达成，亦未举证证明其通过显著方式提请对方注意或已就条款内容进行说明，本院不予采信</strong>。<br>本案中，被保险人郑某乙为专职外卖配送员，事发日从早上7点左右开始配送，最后完成的订单送达时间为15时45分，急救中心载明的通知时间为16时30分，时间间隔较近，结合其往日的工作时间，<strong>其猝死处于工作时间、工作岗位具有高度盖然性</strong>。<br>保险合同中特别约定的<strong>尸检义务及相关责任条款，属于减免保险人责任的格式条款</strong>，某深圳分公司并未提交证据证明其履行充分提示说明义务，<strong>应当作出有利于被保险人的解释</strong>。\"</blockquote>\n<p><strong>要旨 🔑（三条）</strong></p>\n<ol>\n<li><strong>平台/系统自动扣费生成保单的，保险人\"这是协商达成的个性化约定\"的抗辩直接无效</strong> —— 拿不出协商证据就是格式条款。</li>\n<li>🔥 <strong>\"必须尸检\"\"须在工作岗位\"这类义务性/限定性规定，也是减免保险人责任的格式条款</strong>，未提示说明就作不利于保险人解释。</li>\n<li><strong>事实认定可用\"高度盖然性\"</strong>：最后接单时间 15:45，急救通知 16:30 → 认定处于工作时间岗位。不用直接证据。</li>\n</ol>\n<p><strong>关联法条</strong>：保险法 §17②、§30；民法典 §496–498</p>\n<hr>\n<h1 id=\"s22\">五、从这 16 份判决里提炼的 12 条硬规则</h1>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>规则</th><th>依据案例</th><th>一句话打法</th></tr></thead><tbody>\n<tr><td>1</td><td>说明义务判<strong>结果</strong>不判<strong>动作</strong>：可跳过的视频 = 没说明</td><td>A1 粤03民终8930</td><td>\"视频能跳过，怎么证明他看了？\"</td></tr>\n<tr><td>2</td><td>引用 ICD-10/ICD-O-3 却不列明内容 = 未说明</td><td>A2 粤01民终10449</td><td>\"把 ICD-10 那几页拿出来\"</td></tr>\n<tr><td>3</td><td>加黑加粗只完成<strong>提示</strong>，不完成<strong>明确说明</strong></td><td>A3 粤01民终28133</td><td>\"加粗是提示，解释在哪？\"</td></tr>\n<tr><td>4</td><td>疾病定义限缩常人理解 = 隐性免责，写在释义里也一样</td><td>A4、B2</td><td>\"这条实质限缩了理赔范围\"</td></tr>\n<tr><td>5</td><td>同页其他条款加粗、争议条款没加粗 → 对比即证据</td><td>A4 粤14民终795</td><td>打印那页，做标注</td></tr>\n<tr><td>6</td><td>电子签名<strong>只证明投保操作完成</strong></td><td>A5 粤08民终2074</td><td>\"签名 ≠ 已阅读 ≠ 已理解\"</td></tr>\n<tr><td>7</td><td>免赔天数/免赔额/比例赔付<strong>全是免责条款</strong></td><td>A5、A6</td><td>未提示说明即不生效</td></tr>\n<tr><td>8</td><td>保险人提交的<strong>通用演示视频不是本案投保轨迹</strong></td><td>B3 粤01民终24935</td><td>\"请提供本次投保的可回溯记录\"</td></tr>\n<tr><td>9</td><td>告知义务以<strong>询问范围</strong>为限；页面没有的病不用自己填</td><td>C4 粤08民终2416</td><td>\"系统根本没问\"</td></tr>\n<tr><td>10</td><td>向<strong>代理人</strong>披露 = 向保险人披露；职业不加重义务</td><td>C3 粤03民终3156</td><td>留微信记录</td></tr>\n<tr><td>11</td><td>拒赔后<strong>仍在扣保费</strong> = 视为未解除合同</td><td>C5 粤03民终12700</td><td>查银行流水</td></tr>\n<tr><td>12</td><td>保险人须按<strong>一般核保规则</strong>举证\"足以影响承保\"</td><td>C1 粤06民终13672</td><td>\"请出示核保手册\"</td></tr>\n</tbody></table></div>\n<hr>\n<h1 id=\"s23\">六、反面提醒（别踩的坑）</h1>\n<ol>\n<li><strong>提示说明义务不是必胜。</strong> D1（汕尾）证明：电子投保照片 + 投保人声明签名 + 加黑加粗三件套齐备，法院会认定已履行。起诉前先客观评估。</li>\n<li><strong>医疗险/意外医疗适用损失补偿原则，医保已付部分要扣除</strong>（B3、D1）。赢了条款也可能只剩零头。</li>\n<li><strong>律师费一般不支持</strong>（C2 明说\"不是维权必须产生的费用\"）。别为一个不支持的诉请多交受理费。</li>\n<li><strong>迟延利息（LPR）法院支持</strong>（B2、C2）——这个诉请一定要加，成本为零。</li>\n<li><strong>鉴定费由保险人承担</strong>（D1，保险法 §64）——稳的。</li>\n</ol>\n<hr>\n<h2 id=\"s24\">与其他页面的关系</h2>\n<ul>\n<li><strong>武器层面的系统论证</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a></li>\n<li><strong>完整流程与时效</strong>：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F02-%E7%BB%B4%E6%9D%83%E6%93%8D%E4%BD%9C%E5%85%A8%E6%B5%81%E7%A8%8B\">《维权操作全流程（从拒赔到执行）》</a></li>\n<li><strong>重疾险争点全解</strong>：见<a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F01-%E9%87%8D%E7%96%BE%E9%99%A9\">《重疾险 · 纠纷全解》</a></li>\n<li><strong>互联网投保专章</strong>：见<a class=\"dlink\" href=\"#/L1-%E9%99%A9%E7%A7%8D%E5%B1%82%2F07-%E4%BA%92%E8%81%94%E7%BD%91%E6%8A%95%E4%BF%9D%E4%B8%93%E7%AB%A0\">《互联网投保专章 · 支付宝 / 微信 / App 买保险的坑与打法》</a></li>\n<li><strong>B 级案例（法院官网/官媒）</strong>：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E9%87%8D%E7%96%BE%E5%8C%BB%E7%96%97\">《重疾险 / 医疗险 · 案例库》</a>、<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E6%84%8F%E5%A4%96%E5%AF%BF%E9%99%A9%E4%B8%8E%E4%BA%92%E8%81%94%E7%BD%91%E6%8A%95%E4%BF%9D\">《意外险 / 寿险 / 互联网平台投保 · 案例库》</a>、<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E6%A1%88%E4%BE%8B-%E8%BD%A6%E9%99%A9%E4%B8%8E%E8%B4%A2%E4%BA%A7%E9%99%A9\">《车险 / 财产险 / 责任险 · 案例库（广东）》</a></li>\n<li><strong>法条原文</strong>：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "本文案例总览"}, {"id": "s3", "lv": 2, "t": "A1 · 深圳中院 (2025)粤03民终8930号 —— 可跳过的视频 = 没说明"}, {"id": "s4", "lv": 2, "t": "A2 · 广州中院 (2026)粤01民终10449号 —— 引 ICD-10 却不列明 = 未说明"}, {"id": "s5", "lv": 2, "t": "A3 · 广州中院 (2024)粤01民终28133号 —— 加黑加粗 ≠ 明确说明"}, {"id": "s6", "lv": 2, "t": "A4 · 梅州中院 (2025)粤14民终795号 —— 疾病定义限缩 = 隐性免责（含取证技巧）"}, {"id": "s7", "lv": 2, "t": "A5 · 湛江中院 (2026)粤08民终2074号 —— 电子签名 ≠ 已说明；免赔天数也是免责条款"}, {"id": "s8", "lv": 2, "t": "A6 · 阳江中院 (2026)粤17民终14号 —— 免责内容本身违反公平原则，双重打击"}, {"id": "s10", "lv": 2, "t": "B1 · 深圳中院 (2026)粤03民终9578号 —— ICD 编码不能否定病理报告"}, {"id": "s11", "lv": 2, "t": "B2 · 湛江中院 (2026)粤08民终2416号 —— 写在\"释义\"里的排除列举，也是免责条款"}, {"id": "s12", "lv": 2, "t": "B3 · 广州中院 (2025)粤01民终24935号 —— \"示范视频\"不是你的投保轨迹（附反面教训）"}, {"id": "s14", "lv": 2, "t": "C1 · 佛山中院 (2025)粤06民终13672号 —— 保险人必须证明\"足以影响承保\""}, {"id": "s15", "lv": 2, "t": "C2 · 广州中院 (2026)粤01民终4391号 —— 概括性勾选表格 = 没询问；迟延利息可主张，律师费不行"}, {"id": "s16", "lv": 2, "t": "C3 · 深圳中院 (2026)粤03民终3156号 —— 跟代理人说了 = 跟保险公司说了"}, {"id": "s17", "lv": 2, "t": "C4 · 湛江中院 (2026)粤08民终2416号 —— 页面上没有的病，投保人没有义务自己发明"}, {"id": "s18", "lv": 2, "t": "C5 · 深圳中院 (2024)粤03民终12700号 —— 拒赔之后还在扣保费 = 解除不成立"}, {"id": "s20", "lv": 2, "t": "D1 · 汕尾中院 (2025)粤15民终501号 —— ! 提示说明义务不是必胜（必读反面案例）"}, {"id": "s21", "lv": 2, "t": "D2 · 深圳中院 (2026)粤03民终2970号 —— 平台自动投保 = 纯格式条款；\"必须尸检\"也是免责条款"}, {"id": "s24", "lv": 2, "t": "与其他页面的关系"}], "text": "广东二审判决原文精读 · 第一辑（人身险） 📌 另有第二辑（车险 / 财产险 / 代位求偿） ：L2 案例库/广东二审判决原文精读 A级 第二辑（A 级） 可信度：A 级。 本文全部案例来自裁判文书网 判决书原文 （2026 09 16 导出）， 含案号、审理法院、一审案号、裁判理由原文摘录。括号引用均为判决书 逐字原文 。 当事人名称按裁判文书网公开脱敏规则以\"某\"代称，非本站改动的脱敏。 使用说明 ：引用时写\"广东省××市中级人民法院（20××）粤××民终××××号民事判决\"， 与本站其他 B 级案例（法院官网/官媒发布）区分开。 A 级可直接写进代理词。 本文案例总览 案号 法院 险种 核心争点 结果 A1 (2025)粤03民终8930号 深圳中院 重疾险 免责说明视频\"直接跳转\" 投保人胜 A2 (2026)粤01民终10449号 广州中院 团体重疾 ICD 10 未列明 + 团体盖章 投保人胜 A3 (2024)粤01民终28133号 广州中院 少儿重疾 加黑加粗 ≠ 明确说明 投保人胜 A4 (2025)粤14民终795号 梅州中院 重疾险 疾病定义限缩 = 隐性免责 投保人胜 A5 (2026)粤08民终2074号 湛江中院 意外险 无证驾驶免责 + 免赔天数 投保人胜 A6 (2026)粤17民终14号 阳江中院 骑手意外 职业伤害保障免责 投保人胜 B1 (2026)粤03民终9578号 深圳中院 重疾险 原位癌伴微浸润 投保人胜 B2 (2026)粤08民终2416号 湛江中院 重疾险 交界性肿瘤排除条款 投保人胜 B3 (2025)粤01民终24935号 广州中院 百万医疗 既往症 + 示范视频 条款胜/金额受限 C1 (2025)粤06民终13672号 佛山中院 重疾险 如实告知两要件 投保人胜 C2 (2026)粤01民终4391号 广州中院 团体重疾 概括性勾选表格 投保人胜 C3 (2026)粤03民终3156号 深圳中院 重疾险 代理人已知 = 保险人已知 投保人胜 C4 (2026)粤08民终2416号 湛江中院 重疾险 页面没有的病无告知义务 投保人胜 C5 (2024)粤03民终12700号 深圳中院 重疾险 拒赔后继续扣保费 投保人胜 D1 (2025)粤15民终501号 汕尾中院 驾乘意外 提示说明已履行（反面案例） 保险人胜 D2 (2026)粤03民终2970号 深圳中院 骑手意外 猝死 + 自动投保格式条款 投保人胜 一、提示说明义务：什么才算\"说清楚了\" A1 · 深圳中院 (2025)粤03民终8930号 —— 可跳过的视频 = 没说明 一审 ：广东省深圳市福田区人民法院 (2024)粤0304民初53008号 案由 ：人身保险合同纠纷（重大疾病保险金 35 万元） 结果 ：驳回上诉，维持原判 → 保险人给付 保险人做了什么 ：投保流程里有免责条款的说明视频，投保人也完成了电子签名。 法院怎么看 ： \"对于保险人履行免责条款提示与说明义务的认定标准，根据《最高人民法院关于适用《中华人民共和国保险法》若干问题的解释（二）（2020年修正）》第十二、十三条之立法精神，应以保险人有进行提示与解释说明的作为 且该作为达到使投保人了解免责条款内容的程度 。本案中，某深圳分公司对于免责条款的提示与说明虽有作为，但 因视频直接跳转而未能达到使投保人了解免责条款内容之认定标准 ，一审判决某深圳分公司未尽到提示与明确说明义务，涉案免责条款无效，该裁判结论正确，本院依法予以维持。\" 要旨 🔑 ：说明义务的判准是 结果 不是 动作 。做了视频 ≠ 履行了义务；视频能被跳过、自动跳转、默认勾选，就等于没说。 怎么用 1. 把保险人提交的\"投保流程演示\"拿过来， 逐帧看能不能跳过 ——可跳过即命中本条。 2. 主张：保险人须证明该视频 实际播放完成 且不可跳过，否则\"作为\"未达\"使投保人了解\"的程度。 3. 这是广东法院对合同编通则解释 §10③（仅勾选、弹窗不足以认定）的 本地呼应 ，可以并列援引。 关联法条 ：保险法 §17②、解释二 §12–13、合同编通则解释 §10③ A2 · 广州中院 (2026)粤01民终10449号 —— 引 ICD 10 却不列明 = 未说明 一审 ：广东省广州市天河区人民法院 (2024)粤0106民初33199号 裁判日期 ：2026 年 6 月 11 日 案由 ：团体人身保险（重大疾病），主动脉手术 保险人抗辩 ：免责条款含\"遗传性疾病、先天性畸形、变形或染色体异常\"；被保险人患\"先天性主动脉瓣二叶瓣畸形\"，属先天性疾病；团体投保单已盖章。 \"某保险公司 并未将《疾病和有关健康问题的国际统计分类》（ICD 10）中关于'遗传性疾病、先天性畸形、变形或染色体异常'的定义和分类在案涉《保险合同》中列明，亦未提供证据证明已就前述疾病向某银行作出了常人能够理解的解释说明 。而关于'先天性畸形'等疾病属于专业的医学术语，在保险人不作特别说明的情况下，投保人难以准确理解该等疾病的具体内涵以及该等疾病作为免责条款对投保人权益产生的影响，故《保险合同》着重列明的概括性条款并不意味着保险人已履行前述免责条款的明确说明义务， 更不能以投保人的签章行为推定其已完全理解前述免责条款及相应的法律后果，否则对投保人而言明显不公 。\" 要旨 🔑 ：① 条款引用外部分类标准（ICD 10/ICD O 3）的， 必须把具体内容列进合同或另行说明 ；② 盖章 ≠ 理解 ——明确否定了\"签章推定\"的绝对效力。 怎么用 ：遇到免责条款写着\"××依照 ICD 10 确定\"的，直接问： ICD 10 那几页在哪？给我看。 拿不出来就是未说明。 关联法条 ：保险法 §17②、解释二 §11 A3 · 广州中院 (2024)粤01民终28133号 —— 加黑加粗 ≠ 明确说明 一审 ：广东省广州市增城区人民法院 (2024)粤0118民初3216号 裁判日期 ：2024 年 12 月 12 日 案由 ：少儿重疾 + 住院医疗，\"先天性疾病\"免责 \"上述条款 虽然采用加黑、加粗方式提醒投保人注意 ，但鉴于合同中仅明确对于先天性畸形的概念符合《疾病和有关健康问题的国际统计分类》（ICD 10）确定的'先天性畸形、变更或染色体异常'的分类和定义， 保险公司未能举证说明其对于先天性畸形的概念、内容作出具体解释，且为一般人能够知晓和理解 ，陈某、欧阳某作为不具有医学专业知识的自然人，显然无法充分理解该免责条款适用的疾病范围，一审法院据此认定某保险公司未对免责条款进行充分解释说明义务且该免责条款对于案涉被保险人不产生效力正确，本院予以维持。\" 要旨 🔑 ： \"提示\"和\"明确说明\"是两项独立义务，加黑加粗只完成前者。 法官原话逻辑很干净：加黑加粗 = 提示 ✓；但\"概念、内容作出具体解释，且为一般人能够知晓和理解\" = 明确说明 ✗。 同案另外两条实用规则 少儿特定重疾保险金 + 少儿特定重疾陪护保险金可以同时主张 。保险人主张\"已发生重大疾病则不再付少儿特定重疾保险金\"的，法院以\"缺乏合同依据\"驳回。 \"同一次住院\"的认定 ：因同一原因再次住院、与前次出院间隔未超 30 日的，视为同一次住院， 只适用一次赔付限额 。（这条对投保人不友好，算医疗费时要先自己算一遍。） 关联法条 ：保险法 §17②、解释二 §11 A4 · 梅州中院 (2025)粤14民终795号 —— 疾病定义限缩 = 隐性免责（含取证技巧） 一审 ：广东省丰顺县人民法院 (2025)粤1423民初239号（注：粤1423 为丰顺县） 裁判日期 ：2025 年 7 月 22 日 案由 ：重大疾病保险，\"严重Ⅰ型糖尿病\" 条款 ：要求同时满足①持续依赖外源胰岛素 180 天以上；②血胰岛素/C 肽测定异常；③出现三种并发症之一（增殖性视网膜病变 / 心脏病并植入起搏器 / 至少一个脚趾坏疽达切除指征）。 \"显然，上诉人保险公司的上述糖尿病定义应满足的多种并发症情形 已超出一般人对'严重Ⅰ型糖尿病'的理解，极大缩小了一般医学标准，直接影响是否符合理赔标准 。上诉人保险公司在签订案涉保险合同时有义务向投保人释明所涉疾病的具体情形， 不论是在释义部分还是免责条款中 …… 案涉的保险合同为电子保单，且 合同第33 34页中77点对'严重Ⅰ型糖尿病'并发症的定义部分并未有加粗加重或其他足以提醒投保人慎重阅读、理解的标识，与同页上诉人保险公司提醒标识加粗加黑及灰色的其他重要条款字体的背景明显不一致，不足以引起投保人注意 。 再者，上诉人保险公司免责条款2.2条 仅是指引投保人应注意其他条款，并非直接免责的内容 ……上诉人辩称案涉合同主要是通过电话回访履行告知提醒及免责义务，但根据现有证据不足以证实……\" 要旨 🔑（三条，条条是武器） 1. 疾病定义只要限缩了常人理解，就是免责条款，写在\"释义\"里也一样。 2. 🔥 取证技巧：同一页上，别的条款加粗加黑、争议条款没加粗 → 对比本身就是\"未提示\"的证据。 打印条款那一页，做标注，胜过一个小时的口头论证。 3. \"请投保人注意其他条款\"的指引条款 ≠ 免责条款本身 ，不能替代说明义务； 电话回访不能替代投保时的说明 。 关联法条 ：保险法 §17②、解释二 §9（隐性免责）、§11 A5 · 湛江中院 (2026)粤08民终2074号 —— 电子签名 ≠ 已说明；免赔天数也是免责条款 一审 ：广东省廉江市人民法院 (2026)粤0881民初42号 案由 ：意外伤害保险（身故 20 万 + 意外医疗 1 万 + 住院津贴），驾驶人无证驾驶 \"上诉人 仅提交带有周某丁电子签名的投保单，但无任何证据证明投保人签名前页面完整展示保险条款、无弹窗单独提示免责内容、无线上确认阅读免责条款的操作记录、无任何针对免责条款的解释说明记录 。 电子签名仅能证明完成投保操作，不能等同于保险公司已履行法定提示与说明义务。 \" \"案涉意外伤害意外保险属于人身保险， 原则上不适用'损害填补'原则 ，交通事故的侵权人是否已赔偿周某丁的医疗费，不影响……应承担的赔付意外伤害医疗费保险金的责任\" \"对于保险合同约定的 免赔3天属于免责条款 ，如前所述，免责条款不生效，……应按照42天计算意外伤害住院津贴\" 要旨 🔑 1. \"电子签名只证明投保操作完成\" —— 一句话击穿保险人最常举的证据。 2. 免赔天数、免赔额、免赔率、比例赔付统统是免责条款 （解释二 §9 明文），未提示说明即不生效。本案住院津贴因此从 1950 元变 2100 元。 3. 人身意外险不适用损失补偿原则 ：第三方（侵权人）赔过了，意外医疗照样赔。 关联法条 ：保险法 §17②、解释二 §9、§12 A6 · 阳江中院 (2026)粤17民终14号 —— 免责内容本身违反公平原则，双重打击 一审 ：广东省阳江市江城区人民法院 (2025)粤1702民初9088号 案由 ：新就业形态骑手意外伤害保险（伤残 6 万） 保险人抗辩 ：已向投保人（平台/劳务公司）发送邮件告知免责条款，投保人回复确认已阅读。 \"某保险公司杭州中心支公司据以主张免于赔偿责任的前述保险条款是为免除……赔付责任的情况作出约定，根据解释（二）第九条第一款关于'…… 免赔额、免赔率、比例赔付或者给付等免除或者减轻保险人责任条款 ，可以认定为保险法第十七条第二款规定的免除保险人责任的条款'之规定，该条款应被认定为免责条款。 但是…… 并未在保单中用特别的文字、符号或其他明显标识对该条款另以标明以引起投保人冯某的注意，亦未提供证据证明其向冯某就此问题作出常人能够理解的解释说明 ，因此应当认定……该免责条款对冯某不产生效力。 另外，案涉免责条款将已从人社部门获得职业伤害保障作为免除自身赔付责任的情形，不当排除了新就业形态劳动者的合法权利，有违公平原则 ……\" 要旨 🔑 ：双保险打法——① 没提示说明 → 条款不生效；② 即使提示了，内容本身\"不当排除新就业形态劳动者权利、有违公平\" ，可以再用 §19（格式条款无效）打一遍。 另： 向平台/经纪公司发邮件告知，不等于向被保险人（骑手）说明 。被保险人不是邮件接收方。 关联法条 ：保险法 §17②、§19、解释二 §9；民法典 §497 二、疾病定义与赔付范围 B1 · 深圳中院 (2026)粤03民终9578号 —— ICD 编码不能否定病理报告 一审 ：广东省深圳市罗湖区人民法院 (2025)粤0303民初20428号 裁判日期 ：2026 年 3 月 30 日 争点 ：\"（左乳）导管原位癌，局灶间质微浸润\"是否属\"恶性肿瘤——重度\"（条款排除 ICD O 3 编码 0/1/2） \"被上诉人仇某某的《临床病理诊断补充报告书》载明其病理诊断为'（左乳）导管原位癌，局灶间质微浸润'，其中'微浸润'在医学上指癌细胞突破基底膜并侵入周围间质组织，符合恶性肿瘤浸润性生长的生物学特性。 尽管原位癌的形态学编码为2，但该编码系基于主要病理特征的整体归类，不能否定病理诊断中已明确记载的浸润性病变事实。 保险合同条款未明确将'局灶间质微浸润'排除在'恶性肿瘤——重度'定义之外，且该病变已实质满足'恶性细胞浸润周围正常组织'的合同约定要件。另外，保险合同作为格式合同，在合同相关条款约定不明确，双方有争议的情况下，依法亦应当作出 有利于被保险人的解释 。\" 要旨 🔑 ：条款的定义用的是\"浸润和破坏周围正常组织\"这样的 实质特征 ，ICD 编码只是归类工具。 病理报告写\"微浸润\"就满足了实质特征，编码不能反过来否定病理事实。 怎么用 ：拿到病理报告先找\"浸润\"\"侵犯\"\"突破基底膜\"字样；有之，即主张满足实质要件 → §30 不利解释兜底。 关联法条 ：保险法 §30；重疾定义规范 2020（3.3.2） B2 · 湛江中院 (2026)粤08民终2416号 —— 写在\"释义\"里的排除列举，也是免责条款 一审 ：广东省廉江市人民法院 (2026)粤0881民初1687号 裁判日期 ：2026 年 8 月 7 日 案由 ：重疾险（卵巢交界性肿瘤），保险金 499,416 元 条款 ：重度疾病释义 7.20 将\"恶性肿瘤——重度\"限定为 ICD O 3 形态学编码 3、6、9；并单列\"下列疾病不属于恶性肿瘤重度……b.交界性肿瘤……\"。 \"案涉保险合同条款7.20还约定'下列疾病不属于\"恶性肿瘤重度\"，不在保障范围内：1）ICD O 3肿瘤形态学编码属于0（良性肿瘤）、1（动态未定性肿瘤）、2（原位癌和非侵袭性癌）范畴的疾病，如：……b.交界性肿瘤……'， 但该约定实质限缩了恶性肿瘤的理赔范围、减轻了保险人的保险赔付责任，依法属于免除保险人责任的条款 。依照保险法第十七条第二款……的规定，某保险公司深圳分公司在投保前的电子投保环节未依法向投保人明确说明该免责条款内容， 该免责条款依法不产生效力 。\" 要旨 🔑 ： \"不在保障范围内\"的排除列举，即便放在\"释义/定义\"章节，只要实质限缩责任，就是免责条款，未说明即不生效。 保险人最爱说\"这是责任范围条款不是免责条款，所以我不用提示说明\"——本案直接驳回这个说法。 同案第二条（迟延赔付利息） \"依照保险法第二十三条第一、第二款……保险人未及时履行前款规定义务的，除支付保险金外，应当赔偿被保险人或者受益人因此受到的损失……一审法院判令……按照全国银行间同业拆借中心公布的贷款市场报价利率向沈某赔付资金占用损失合理合法，本院予以维持。\" → 迟延赔付的利息（LPR）法院支持，一定要一并主张。 关联法条 ：保险法 §17②、§23、解释二 §9 B3 · 广州中院 (2025)粤01民终24935号 —— \"示范视频\"不是你的投保轨迹（附反面教训） 一审 ：广东省广州市番禺区人民法院 (2025)粤0113民初4611号 二审判决日期 ：2026 年 4 月 9 日 案由 ：百万医疗保险（互联网专属），既往症免责 一审原文（二审维持） ： \"因本案为互联网保险产品，解释（二）第十二条规定，通过网络、电话等方式订立的保险合同，保险人以网页、音频、视频等形式对免除保险人责任条款予以提示和明确说明的，人民法院可以认定其履行了提示和明确说明义务。本案中，张某甲主张其父张某乙代其手机自助投保，但 某公司广州分公司提交的投保示范视频并非张某甲父亲代投保时的视频轨迹，仅凭投保单上'张某甲'的签名字样尚不足以证明 某公司广州分公司已通过人工、网页、音频、视频等任何形式说明免责条款的内容及法律后果。\" 要旨 🔑 ：保险人常拿 通用\"投保流程演示视频\" （甚至是可回溯管理里别人的轨迹）当证据。 一句话击穿：这不是本案投保人的投保轨迹。 要求其提供 本次投保的可回溯记录 （监管要求互联网保险可回溯，拿不出来就是没做）。 ⚠️ 同案反面教训（必须知道） 法院认定 百万医疗险属补偿性保险合同，适用损失补偿原则 ：医保统筹基金已支付的 40,947.49 元要从理赔中扣除 → 5,378.84 元诉求扣完只剩 1,231.35 元。 一般医疗保额 200 万未赔满前，不能跳到\"恶性肿瘤——重度医疗\"责任项下重复主张。 教训 ：赢了免责条款，也可能输在金额上。投保时看清\"是否限社保范围内\"\"免赔额多少\"。 关联法条 ：保险法 §17②、解释二 §12 三、如实告知义务 C1 · 佛山中院 (2025)粤06民终13672号 —— 保险人必须证明\"足以影响承保\" 一审 ：广东省佛山市顺德区人民法院 (2025)粤0606民初37706号 案由 ：重疾险（甲状腺乳头状癌），保险人以\"曾因胸痛就医未告知\"拒赔 \"保险人以投保人未履行如实告知义务为由解除合同需满足 两个条件 ：投保人因故意或重大过失未如实告知； 未告知事项足以影响保险人决定是否同意承保或者提高保险费率 。张某虽曾因胸痛就医，但相关检查结果（如心电图、DR检查）均未发现明确异常，张某主观上不具有刻意隐瞒的故意或重大过失，且现有证据不能证明胸痛与后续确诊的甲状腺乳头状癌存在关联， 某公司未举证证明上述未告知事项按照一般的核保规则足以影响其是否同意承保或者提高保险费率 。\" 要旨 🔑 ：保险人必须 按\"一般核保规则\"举证 ，不是嘴上说\"影响了\"就行。要求其出示 核保手册/核保规则 ，证明该情形在正常核保中会导致拒保或加费。多数保险人拿不出来。 关联法条 ：保险法 §16①② C2 · 广州中院 (2026)粤01民终4391号 —— 概括性勾选表格 = 没询问；迟延利息可主张，律师费不行 一审 ：广东省广州市越秀区人民法院 (2025)粤0104民初42006号 案由 ：团体重疾（300 多名职工），乳腺结节 → 乳腺癌，保额 15 万 \"案涉保险是团体险，投保人为某乙公司，被保险人有300多名职工，且之前由某公司珠海分公司进行连续投保。 某保险公司广东分公司既无对被保险人的健康进行询问，也无要求某乙公司对所有职工的健康情况进行调查，其仅以一个表格要求某乙公司对所有职工的既往病史进行概括性的勾选，不能认定其已尽到应有的询问义务。 某乙公司无法了解每个员工体检中出现的问题，在此情况下进行概况性的勾选， 不能认定其作为投保人有故意或者重大过失 …… 且被保险人李某仅是因在连续投保的体检中发现存在结节，该结节也并不会必然导致乳腺癌的发生，故不能认定其存在故意隐瞒重大疾病的情形。 另外，某保险公司广东分公司也从未要求解除合同。 考虑到李某于2024年12月5日申请理赔，保险合同约定核保最长时间为30天，本院酌定……应支付从2025年1月4日起至实际支付保险金之日止 逾期理赔的利息 （按照同期全国银行间同业拆借中心公布的贷款市场报价利率标准计算）。 由于律师费不是维权必须产生的费用，且无合同依据，故本院不予支持。 \" 要旨 🔑（四条） 1. 团体险的\"一张表格概括性勾选\"不构成有效询问 → 未询问即无告知义务。 2. \"结节不必然导致癌症\" → 因果关系要保险人证明。 3. 保险人\"从未要求解除合同\"本身是抗辩点 （未行使解除权，直接拒赔无依据）。 4. 迟延利息：可主张，从核定期届满次日起按 LPR 算。律师费：不支持 ，别浪费一个诉请。 关联法条 ：保险法 §16、§23；解释二 §6 C3 · 深圳中院 (2026)粤03民终3156号 —— 跟代理人说了 = 跟保险公司说了 一审 ：广东省深圳市宝安区人民法院 (2025)粤0306民初22941号 案由 ：重疾险，甲状腺结节 → 甲状腺癌 事实 ：投保书\"甲状腺病史\"栏勾选了\"否\"，但 投保当日投保人已通过微信向保险代理人披露 \"2022 年存在甲状腺结节、定期复查无需治疗\"。 \" 保险代理人作为上诉人某保险公司深圳分公司的职务代理人，其知晓投保人告知的甲状腺结节病史应视为上诉人已知晓该事实。 投保人后续根据上诉人要求提交的2023年4月甲状腺检查报告及2022年肛周脓肿病历中，亦明确载明'常规体检发现甲状腺结节，医生叮嘱定期复查，无需治疗'， 进一步履行了补充告知义务 。 上诉人收到上述资料后未提出异议并签发保险合同，表明其已接受投保人披露的病史信息并作出承保决定。 此外，上诉人于2023年6月6日发出的《补充健康状况资料通知函》中， 仅要求提供2023年4月甲状腺检查史及既往病史，未明确要求提交2022年5月11日超声检查报告 ……投保人未主动提交该报告不构成重大遗漏。 上诉人主张被上诉人作为医生应承担更高注意义务，但法律未因被保险人的职业背景而加重投保人的告知义务 ……\" 要旨 🔑（三条，都极实用） 1. 🔥 向代理人披露 = 向保险人披露 （职务代理 + 保险法 §16⑥\"保险人在合同订立时已经知道\"）。 微信聊天记录留好，这是救命证据。 2. 保险人收到资料后未提异议并签发保单 = 接受披露、作出承保决定。 3. 职业背景（医生、护士等）不加重告知义务。 关联法条 ：保险法 §16①②⑥、解释二 §6 C4 · 湛江中院 (2026)粤08民终2416号 —— 页面上没有的病，投保人没有义务自己发明 事实 ：健康告知页面\"肿瘤\"项下未包含\"交界性肿瘤\"；\"肿物/结节/占位\"项下也无该选项；投保人选择了\"卵巢囊肿\"（与手术名称\"腹腔镜下右侧卵巢囊肿切除术\"一致）。 另：保险人问了\"是否患乙肝\"，但投保人投保前 从无乙肝的正式诊疗结论 ，仅有一次检验指标超标 + CT\"考虑血管瘤\"。 又：系统问\"过去2年内住院超5天/手术/连续服药超30天\"，但 进入下一环节后系统根本没再问住院天数 。 \"沈某按照操作指引进入'有部分问题快速评估能否投保'环节，在页面中出现的选项中并无'卵巢交界性肿瘤'，沈某在多个选项中选择'卵巢囊肿'， 系其作为非医学专业人士凭借常识选择最接近选项进行评估 ，且与沈某此前手术名称……相符合，故 沈某已经向某保险公司深圳分公司主动告知其患病情况，而非恶意隐瞒患病情况 。\" \"并无证据证实沈某投保前被确诊乙肝的正式诊疗结论，亦无证据证实沈某曾因乙肝相关病症就诊、用药，故 沈某作为非医学专业人士，不能苛责其对检验报告作出专业医学判断 。\" \" 投保环节中也没有任何可供被保险人专门告知'住院治疗超5天、或做过手术、或遵医嘱需要连续服药超过30天'的环节。 据此，沈某不存在未如实告知2年内住院、手术及连续服药史的情况。\" 要旨 🔑（三条） 1. 告知义务以\"保险人询问的范围和内容\"为限 （解释二 §6）。 页面选项里没有的病，投保人没义务凭医学知识自己填。 2. \"不能苛责非医学专业人士对检验报告作出专业医学判断\" —— 指标异常 ≠ 患有该疾病。 3. 系统没给入口 = 保险人没问。 问了前半句、没给后半句入口的，视为未询问。 关联法条 ：保险法 §16①、解释二 §6 C5 · 深圳中院 (2024)粤03民终12700号 —— 拒赔之后还在扣保费 = 解除不成立 一审 ：广东省深圳市罗湖区人民法院 (2023)粤0303民初7703号 裁判日期 ：2025 年 3 月 21 日 \"《最高人民法院关于适用若干问题的解释（二）（2020年修正）》第七条规定，保险人在保险合同成立后知道或者应当知道投保人未履行如实告知义务， 仍然收取保险费 ，又依照保险法第十六条第二款的规定主张解除合同的， 人民法院不予支持 。 本案中，上诉人某公司在2023年2月10日作出拒赔通知书，决定解除合同，但 在此之后，上诉人仍于2023年2月25日、3月21日收取了投保人的苏某·重疾险的保险费每期56.25元 ……上诉人主张因系统处理存在延迟导致错误收取保费，但 未能提供充分证据证明其在发现投保人未履行如实告知义务后及时关闭了扣费系统或扣费链接 。因此…… 应视为其尚未解除合同 ，现其在诉讼中再以同一理由主张合同解除，本院不予支持。\" 要旨 🔑（杀手锏级） ： 拿到拒赔通知书后，第一件事是去查银行流水/扣费记录——保险人还在扣费吗？ 还在扣 = 依解释二 §7 视为未解除合同，解除主张直接被否。保险人\"系统延迟\"的抗辩，法院要求它 举证已关闭扣费链接 ，通常拿不出来。 关联法条 ：保险法 §16②、解释二 §7 四、格式条款、赔付范围与\"反面案例\" D1 · 汕尾中院 (2025)粤15民终501号 —— ⚠️ 提示说明义务不是必胜（必读反面案例） 一审 ：广东省陆丰市人民法院 (2024)粤1581民初2742号 裁判日期 ：2025 年 8 月 20 日 案由 ：驾乘意外伤害保险（60 万） \"二审期间，平某公司向本院提交了投保单及 投保人通过电子形式投保驾乘意外险时的照片 ，以及…… 黄某甲在投保单上'投保人声明'处签名确认收到保险条款并确认平某公司已向其本人介绍了条款的内容，特别就保险条款中免除保险人责任的条款内容和手写或打印版的特别约定内容做了明确说明。相关保险条款中也进行了加黑加粗 ，足以证实黄某甲在投保时已确认知悉了保险条款内容…… 根据解释（二）第十二条…… 本院认定平某公司已在投保时向黄某甲对上述责任免责条款履行了提示和明确说明义务。 \" 后果 （对投保人不利的部分，必须知道）： 伤残按合同比例：十级 10% = 6 万；九级 20% = 12 万（不是按交通事故标准全额） 医疗费 扣减第三方已赔的 30% 份额 + 免赔额 100 元 住院伙食补助费、营养费、护理费、交通费、误工费、伤残赔偿金（按侵权口径）、精神损害抚慰金、被扶养人生活费 → 均不支持 ✅ 唯一对投保人有利的 ：鉴定费 4,872 元由保险人承担 \"根据《中华人民共和国保险法》第六十四条：'保险人、被保险人为查明和确定保险事故的性质、原因和保险标的的损失程度所支付的必要的、合理的费用，由保险人承担'的规定，该鉴定费应由平某公司承担\" 要旨 ⚠️ 1. \"电子投保照片 + 投保人声明签名 + 加黑加粗\"三件套齐备时，法院会认定已履行。 提示说明义务不是必胜牌—— 别把全部筹码押在这一张牌上。 2. 鉴定费（§64）几乎必支持 ，是很稳的小额诉请。 3. 驾乘意外险是按合同比例定额给付的 ，不是按交通事故赔偿标准算。买之前要看清比例表。 D2 · 深圳中院 (2026)粤03民终2970号 —— 平台自动投保 = 纯格式条款；\"必须尸检\"也是免责条款 一审 ：广东省深圳市罗湖区人民法院 (2025)粤0303民初3354号 裁判日期 ：2026 年 2 月 11 日 案由 ：外卖骑手意外险，猝死，保额 60 万 \"某公司作为投保人，通过电子投保方式与某深圳分公司订立保险合同， 投保流程中骑手接单后系统自动扣收保费并生成保单，并无证据显示投保人及被保险人对合同条款有协商或修改的权利 。特别约定中关于'猝死'的界定及赔付条件，包括'工作时间''工作岗位'的限制性要求以及' 必须尸检 '等义务性规定，均系某深圳分公司为重复使用而预先设定的标准化内容。该条款的适用对象为不特定骑手群体，具有普遍适用性和不可变更性， 符合格式条款的特征 。某深圳分公司主张特别约定为其与某公司经过合意磋商做出的个性化约定， 但未能提供证据证明该条款系与投保人协商达成，亦未举证证明其通过显著方式提请对方注意或已就条款内容进行说明，本院不予采信 。 本案中，被保险人郑某乙为专职外卖配送员，事发日从早上7点左右开始配送，最后完成的订单送达时间为15时45分，急救中心载明的通知时间为16时30分，时间间隔较近，结合其往日的工作时间， 其猝死处于工作时间、工作岗位具有高度盖然性 。 保险合同中特别约定的 尸检义务及相关责任条款，属于减免保险人责任的格式条款 ，某深圳分公司并未提交证据证明其履行充分提示说明义务， 应当作出有利于被保险人的解释 。\" 要旨 🔑（三条） 1. 平台/系统自动扣费生成保单的，保险人\"这是协商达成的个性化约定\"的抗辩直接无效 —— 拿不出协商证据就是格式条款。 2. 🔥 \"必须尸检\"\"须在工作岗位\"这类义务性/限定性规定，也是减免保险人责任的格式条款 ，未提示说明就作不利于保险人解释。 3. 事实认定可用\"高度盖然性\" ：最后接单时间 15:45，急救通知 16:30 → 认定处于工作时间岗位。不用直接证据。 关联法条 ：保险法 §17②、§30；民法典 §496–498 五、从这 16 份判决里提炼的 12 条硬规则 规则 依据案例 一句话打法 1 说明义务判 结果 不判 动作 ：可跳过的视频 = 没说明 A1 粤03民终8930 \"视频能跳过，怎么证明他看了？\" 2 引用 ICD 10/ICD O 3 却不列明内容 = 未说明 A2 粤01民终10449 \"把 ICD 10 那几页拿出来\" 3 加黑加粗只完成 提示 ，不完成 明确说明 A3 粤01民终28133 \"加粗是提示，解释在哪？\" 4 疾病定义限缩常人理解 = 隐性免责，写在释义里也一样 A4、B2 \"这条实质限缩了理赔范围\" 5 同页其他条款加粗、争议条款没加粗 → 对比即证据 A4 粤14民终795 打印那页，做标注 6 电子签名 只证明投保操作完成 A5 粤08民终2074 \"签名 ≠ 已阅读 ≠ 已理解\" 7 免赔天数/免赔额/比例赔付 全是免责条款 A5、A6 未提示说明即不生效 8 保险人提交的 通用演示视频不是本案投保轨迹 B3 粤01民终24935 \"请提供本次投保的可回溯记录\" 9 告知义务以 询问范围 为限；页面没有的病不用自己填 C4 粤08民终2416 \"系统根本没问\" 10 向 代理人 披露 = 向保险人披露；职业不加重义务 C3 粤03民终3156 留微信记录 11 拒赔后 仍在扣保费 = 视为未解除合同 C5 粤03民终12700 查银行流水 12 保险人须按 一般核保规则 举证\"足以影响承保\" C1 粤06民终13672 \"请出示核保手册\" 六、反面提醒（别踩的坑） 1. 提示说明义务不是必胜。 D1（汕尾）证明：电子投保照片 + 投保人声明签名 + 加黑加粗三件套齐备，法院会认定已履行。起诉前先客观评估。 2. 医疗险/意外医疗适用损失补偿原则，医保已付部分要扣除 （B3、D1）。赢了条款也可能只剩零头。 3. 律师费一般不支持 （C2 明说\"不是维权必须产生的费用\"）。别为一个不支持的诉请多交受理费。 4. 迟延利息（LPR）法院支持 （B2、C2）——这个诉请一定要加，成本为零。 5. 鉴定费由保险人承担 （D1，保险法 §64）——稳的。 与其他页面的关系 武器层面的系统论证 ：见L0 打法层/01 八把通用武器 完整流程与时效 ：见L0 打法层/02 维权操作全流程 重疾险争点全解 ：见L1 险种层/01 重疾险 互联网投保专章 ：见L1 险种层/07 互联网投保专章 B 级案例（法院官网/官媒） ：见L2 案例库/广东案例 重疾医疗、L2 案例库/广东案例 意外寿险与互联网投保、L2 案例库/广东案例 车险与财产险 法条原文 ：见L4 法条库/00 法条与司法解释原文"}, {"id": "L2-案例库/广东案例-意外寿险与互联网投保", "group": "3 · 广东案例库", "groupKey": "L2-案例库", "title": "意外险 / 寿险 / 互联网平台投保 · 案例库", "order": 3, "file": "广东案例-意外寿险与互联网投保.md", "html": "<h1 id=\"s0\">意外险 / 寿险 / 互联网平台投保 · 案例库</h1>\n<blockquote>采集日期：2026-09-16 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手来源待核验<br>B 级 = 法院官方 / 官媒来源（法院官网、人民法院报、省级党报及其新媒体、检察日报等）；C 级 = 律所 / 自媒体转述，仅作线索，标\"待核验\"，不得直接引用为裁判规则。<br>说明：本库聚焦广东法院裁判。互联网平台投保部分均系广东（广州、深圳、江门）法院案例。C 级案例均注明\"据律所文章转述，未核到裁判文书原文\"。</blockquote>\n<hr>\n<h2 id=\"s1\">一、意外险 / 寿险</h2>\n<h3 id=\"s2\">案例 1：众包骑手猝死——\"工作时间 / 工作岗位\"猝死赔付条件被认定为隐性免责条款</h3>\n<ul>\n<li><strong>案号</strong>：未检索到公开案号（连州法院一审，清远中院二审维持）</li>\n<li><strong>审理法院 / 审级</strong>：连州市人民法院（一审）；广东省清远市中级人民法院（二审，驳回上诉、维持原判）</li>\n<li><strong>裁判日期</strong>：未注明（报道时\"判决现已生效\"）</li>\n<li><strong>来源 URL</strong>：https://lz.gdqyfy.gov.cn/qyzynet/fyxw/16003.jhtml （连州市人民法院官网\"法院新闻\"栏目）</li>\n<li><strong>可信度</strong>：B（法院官网原文，含法官说法）</li>\n<li><strong>关键词标签</strong>：猝死、意外险、众包骑手、隐性免责条款、提示说明义务、受益人认定</li>\n</ul>\n<p><strong>基本事实</strong>： 邓某于 2017 年在美团众包 APP 注册成为网约配送员。2023 年 3 月 2 日，邓某接首单时自动扣除每日 2.5 元保费，投保\"众包骑手意外险\"并附加\"猝死保险\"，意外险保额 60 万、猝死保额 60 万，未指定受益人。保单特别约定：\"猝死保险金：在工作时间和工作岗位，身体急性症状发生后即刻或 48 小时内经抢救无效死亡。\"当日 17 时许邓某被发现俯卧路面，抢救无效死亡，公安机关死亡证明载明死因为急性冠脉综合症（猝死）。平台跑单记录显示当日 4 时 34 分有 1 次派送任务，此后无派送记录。邓某父母理赔遭拒（保险公司称死亡时间不在工作期间、地点不在工作岗位，且已通过邮件向平台公司提示说明），诉至法院。</p>\n<p><strong>争议焦点</strong>：</p>\n<ol>\n<li>猝死保险金条款中\"工作时间和工作岗位\"赔付条件是否为隐性免责条款；</li>\n<li>保险公司向平台公司（而非实际投保人骑手）进行提示说明，能否认定为已向实际投保人履责。</li>\n</ol>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"众包骑手意外险保障的是骑手的人身权益，而非其他主体权益。投保操作、保费实际负担主体均为骑手，故实际投保人应穿透认定为骑手。猝死保险金条款中有关事故发生于'工作时间、工作岗位'的赔付条件应穿透认定为隐性免责条款。\"<br>\"骑手意外险投保模式特殊，保险公司对投保模式应系明知，保险公司向某信息科技有限公司进行免责提示告知，并不能据此认定为已向实际投保人履责到位。\"<br>\"众包骑手具有工作时间碎片化、工作地点自由化的特征，将邓某死亡前的平台接单、日常工作规律进行对比，结合逻辑推理和日常生活经验，可以认定邓某的猝死事件发生在工作时间内具有高度盖然性。\"<br>\"保险公司作为保险人，负有向邓某明示具体保险责任范围和除外责任范围的义务，并未举证证明其在邓某投保前就该条款进行了明示，投保完成后邓某在平台保单详情页亦不能一目了然地阅读或注意到该内容，因此该条款对邓某不产生效力，且案涉事故发生在保险期间内。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 连州法院判决保险公司 15 日内支付保险金 60 万元；清远中院二审驳回上诉、维持原判。要点：① 众包骑手\"一日险\"应穿透认定实际投保人；② 向平台而非骑手提示，不视为对实际投保人尽到说明义务；③ \"工作时间和工作岗位\"猝死赔付条件属隐性免责，未对骑手明示则不生效；④ 骑手工作碎片化特征下，\"工作时间\"应结合接单规律综合认定。对港资企业法务办理骑手类灵活用工保险极具参考价值。</p>\n<p><strong>关联法条</strong>：《保险法》第十七条（提示说明义务）；关于\"猝死\"\"意外\"定义之争，另见案例 2、3。</p>\n<hr>\n<h3 id=\"s3\">案例 2：猝死是否属\"意外伤害\"——猝死的近因须鉴定，不能一概拒赔</h3>\n<ul>\n<li><strong>案号</strong>：(2008) 惠中法民一终字第 19 号</li>\n<li><strong>审理法院 / 审级</strong>：广东省惠州市中级人民法院（二审）；撤销惠州市惠城区人民法院 (2007) 惠城法民一初字第 1625 号</li>\n<li><strong>裁判日期</strong>：2008-03-05</li>\n<li><strong>来源 URL</strong>：https://zyzk.jcrb.com/alyz/content.html?gid=C1355307 （检察日报·正义智库\"案例要旨\"栏目）</li>\n<li><strong>可信度</strong>：B（官媒案例要旨 + 判决书正文节录）</li>\n<li><strong>关键词标签</strong>：猝死、意外险、意外伤害定义、近因、尸体鉴定</li>\n</ul>\n<p><strong>基本事实</strong>： 正泰公司向某保险公司惠州中心支公司投保团体意外伤害保险，被保险人含关某、刘某之子。条款释义\"意外伤害\"为：外来的、突然的、非本意的、非疾病的使身体受到伤害的客观事件。2007 年 3 月 31 日，关某之子就餐后突然倒地，送医抢救无效身亡，死亡证明书诊断\"猝死\"。保险公司提出尸检被拒，作出理赔结论：猝死不符合意外险条件，不予给付。关某诉至法院。</p>\n<p><strong>争议焦点</strong>： 猝死是否属于意外险责任范围；受益人拒绝尸检致死因不明时举证责任如何分配。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"猝死只是死亡的表现形式，而非死亡的原因。导致猝死的原因，可能是疾病，也有可能是非疾病，需要对猝死的原因进行进一步鉴定或分析，才能最终确定是否属于意外伤害的范围；猝死虽然属于日常生活经验中的'意外'死亡，但它与保险条款的'意外'定义是不同的，前者强调的是出乎预料、没有预见，具有突然性，后者则应具备外来的、突然的、非本意的、非疾病四个要素。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 检察日报正义智库仅刊载案例要旨与部分判决书正文，未给出完整二审主文金额。要点：猝死≠意外，但猝死本身只是死亡形式，须查明近因（疾病或非疾病外来因素）；保险公司以\"猝死即非意外\"直接拒赔不成立，应进一步举证死因。对\"猝死附加险 / 主险是否赔付\"系列争议（案例 3）提供底层定义框架。</p>\n<p><strong>关联法条</strong>：《保险法》相关；意外伤害\"四要件\"（外来的、突然的、非本意的、非疾病的）。</p>\n<hr>\n<h3 id=\"s4\">案例 3：团体意外险附加猝死责任——\"表面健康的人\"并非指\"没有任何疾病\"</h3>\n<ul>\n<li><strong>案号</strong>：广州法院保险纠纷十大典型案例之八（未单列案号；黄某与某保险公司意外伤害保险合同纠纷案）</li>\n<li><strong>审理法院 / 审级</strong>：广州市法院（典型案例发布，2021-07-08）</li>\n<li><strong>裁判日期</strong>：2021-07-08（发布日）</li>\n<li><strong>来源 URL</strong>：https://ycpai.ycwb.com/ycppad/content/2021-07/08/content_40128595.html （羊城派 / 羊城晚报，广州中院发布）</li>\n<li><strong>可信度</strong>：B（官媒刊载广州法院十大典型案例，含法官说法）</li>\n<li><strong>关键词标签</strong>：猝死、团体意外险、附加猝死责任、条款释义、表面健康</li>\n</ul>\n<p><strong>基本事实</strong>： 黄某的工作单位为包括身患鼻咽癌的黄某在内的员工投保团体人身意外伤害险，适用条款含附加猝死责任条款。猝死释义：\"指表面健康的人因潜在疾病、机能障碍或其他原因在出现症状后 24 小时内发生的非暴力性突然死亡。\"后黄某猝死，受益人主张理赔；保险公司抗辩黄某身患癌症，不属于猝死释义中的\"表面健康的人\"，故不赔。</p>\n<p><strong>争议焦点</strong>： \"表面健康的人\"应作何种解释；患癌被保险人死亡是否符合合同约定的猝死情形。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"依据通常解释和生活常识，猝死的定义中的'表面健康'，显然不是指没有任何疾病，而应当是指未患有能够导致患者突然死亡的疾病。虽然被保险人患有鼻咽癌，但并无证据显示癌症已发展到终末期，且保险公司也未能提交此类癌症会导致患者突然死亡的证据。所以被保险人死亡原因符合合同约定的猝死情形，保险公司应当承担给付相应保险金的责任。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 广州法院认为被保险人死亡原因符合约定猝死情形，保险公司应给付保险金。要点：猝死释义中的\"表面健康\"应作限缩、合理解释，不能将\"曾患病\"一律排除；保险公司主张\"患病即非表面健康\"须举证该疾病足以导致突然死亡。可直接用于反驳保险人以\"投保前病史\"否定猝死责任的抗辩。</p>\n<p><strong>关联法条</strong>：《保险法》第三十条（格式条款争议作有利于被保险人和受益人解释）；条款释义解释规则。</p>\n<hr>\n<h3 id=\"s5\">案例 4：死因不明时意外险不能免责——法院可酌定按比例赔偿</h3>\n<ul>\n<li><strong>案号</strong>：广州法院保险纠纷十大典型案例之七（未单列案号；冯某与某保险公司保险合同纠纷案）</li>\n<li><strong>审理法院 / 审级</strong>：广州市法院（典型案例发布）</li>\n<li><strong>裁判日期</strong>：2021-07-08（发布日）</li>\n<li><strong>来源 URL</strong>：https://ycpai.ycwb.com/ycppad/content/2021-07/08/content_40128595.html （羊城派）</li>\n<li><strong>可信度</strong>：B</li>\n<li><strong>关键词标签</strong>：意外险、死因不明、举证、酌定赔偿比例</li>\n</ul>\n<p><strong>基本事实</strong>： 冯某投保意外险后不幸摔倒死亡。医疗机构认为其死亡原因为脑血管疾病导致脑出血，或者是脑挫伤。受益人主张摔倒致脑挫伤（意外伤害）死亡应理赔；保险公司抗辩系脑血管疾病，非意外，不在保险范围。</p>\n<p><strong>争议焦点</strong>： 死因无法确定为疾病还是意外时，意外险保险公司能否一概免责。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"在无法确定冯某死因是疾病还是意外的情况下，可以酌定保险公司按照一定比例赔偿部分保险金。\"<br>\"意外险以被保险人发生合同约定范围内的意外伤害作为理赔的前提，但如果被保险人是因为疾病导致损害，保险公司不负赔偿责任。而在现实生活中，有的被保险人突然死亡的具体原因难以确定，无法准确认定死因是突发疾病还是意外伤害致死。在此情况下，人民法院可以根据具体情形，酌定保险公司支付部分保险金。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 广州法院明确：死因不明时并非当然免责，法院可结合证据酌定按比例赔付。对受益人而言，死因鉴定与报案留证是关键；对保险人而言，\"死因不明\"不等于\"拒赔成立\"。可结合案例 2 的近因规则使用。</p>\n<p><strong>关联法条</strong>：《保险法》第二十二条（理赔举证责任）；民事诉讼举证责任分配。</p>\n<hr>\n<h3 id=\"s6\">案例 5：职业类别未询问 + 30 日解除权——网络意外险不得以\"职业不符\"超期拒赔</h3>\n<ul>\n<li><strong>案号</strong>：广州法院保险纠纷十大典型案例之六（未单列案号；刘某与某保险公司保险合同纠纷案）</li>\n<li><strong>审理法院 / 审级</strong>：广州市法院（典型案例发布）</li>\n<li><strong>裁判日期</strong>：2021-07-08（发布日）</li>\n<li><strong>来源 URL</strong>：https://ycpai.ycwb.com/ycppad/content/2021-07/08/content_40128595.html （羊城派）</li>\n<li><strong>可信度</strong>：B</li>\n<li><strong>关键词标签</strong>：意外险、职业类别、如实告知、解除权除斥期间、网络投保</li>\n</ul>\n<p><strong>基本事实</strong>： 刘某通过网络向保险公司购买人身意外伤害保险，承保职业范围 1-3 类。刘某填写投保信息时选择职业为\"外务员\"（属第 2 类）。2018 年 1 月底刘某工作中意外受伤。2018 年 2 月 1 日保险公司调查得知刘某实际从事职业与投保类型不符，以未如实告知职业为由拒赔，但保险公司在 30 日内未行使解除权。</p>\n<p><strong>争议焦点</strong>： 保险人已知投保人职业不符后，未在法定 30 日除斥期间内行使解除权，能否直接拒赔。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"保险公司在 2018 年 2 月 1 日即已知道刘某投保职业与实际职业不符，但未在 30 日内行使解除权，其关于后续调查报批流程需要花更长时间的解释亦不足以成为可超过法定期限行使解除权的理由，故判令保险公司承担保险责任。\"<br>\"保险公司调查报批流程需要花更长时间，不足以成为保险公司可超过法定期限行使解除权的理由。保险公司未在法定期限内行使解除权，直接以投保人未履行如实告知义务拒赔的，人民法院不予支持。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 广州法院判决保险公司承担保险责任。要点：① 保险人解除权受 30 日除斥期间限制，内部流程不能突破；② 超期未解除即不得再以未如实告知拒赔。可与\"职业类别询问范围\"结合（见互联网投保部分张家港案思路，及本案提示：未询问则不负告知义务）。</p>\n<p><strong>关联法条</strong>：《保险法》第十六条第三款（解除权 30 日除斥期间）；《保险法司法解释（二）》第六条（询问告知主义）。</p>\n<hr>\n<h3 id=\"s7\">案例 6：高处作业除外条款未提示说明——免责条款不生效（广东高院再审）</h3>\n<ul>\n<li><strong>案号</strong>：(2026) 粤民申 3209 号</li>\n<li><strong>审理法院 / 审级</strong>：广东省高级人民法院（再审审查，驳回保险公司再审申请）</li>\n<li><strong>裁判日期</strong>：2026-05-09（据今日头条文章标注）</li>\n<li><strong>来源 URL</strong>：https://www.insulaw.cn/newsinfo/9230705.html （广东知险律师事务所，转述）；https://www.toutiao.com/article/7676341306696466990/ （今日头条，转述）</li>\n<li><strong>可信度</strong>：C（待核验——仅律所 / 自媒体转述，未核到裁判文书原文；案号、日期据转述）</li>\n<li><strong>关键词标签</strong>：意外险、高处作业除外、特别约定、免责条款、提示说明义务</li>\n</ul>\n<p><strong>基本事实（据转述）</strong>： 保单\"特别约定\"载有《附加高处作业除外保险（2022 版）条款》，约定被保险人在高处作业过程中发生的人身伤害，保险人不承担给付保险金责任。事故发生在被保险人作业过程中。保险公司以高处作业除外条款拒赔，投保人 / 被保险人抗辩该条款未提示说明。</p>\n<p><strong>争议焦点（据转述）</strong>： \"特别约定\"中的高处作业除外条款，实质是免责条款还是保险责任条款；保险人是否尽到提示和明确说明义务。</p>\n<p><strong>裁判理由（【转述，非原文】据律所文章）</strong>：</p>\n<blockquote>\"案涉'高处作业除外保险'特别约定，免除了保险公司在被保险人发生人身伤害时本应承担的保险责任，因此被认定为免责条款，而不是保险责任条款。\"<br>\"投保单上的'投保人声明'如果只是格式文本，没有写明保险公司对'高处作业除外'做过说明，就不能单独证明已尽说明义务；销售人员的聊天记录反而可能证明并未履行。\"<br>\"案涉免责条款因未履行提示和明确说明义务而不发生法律效力，保险公司以高处作业除外条款拒赔依据不足。\"</blockquote>\n<p><strong>裁判结果（据转述）</strong>： 广东高院维持一审、二审认定，该高处作业除外免责条款不发生效力，驳回保险公司再审申请。</p>\n<p><strong>对我的用处 / 注意</strong>： C 级，仅作线索。可作为\"特别约定型隐性免责条款\"的攻防素材：将\"除外情形\"包装进特别约定，仍可能被认定为实质免责，须单独提示说明。正式引用前务必通过裁判文书网 / 法院案例库核到 (2026) 粤民申 3209 号原文。</p>\n<p><strong>关联法条</strong>：《保险法》第十七条第二款；高处作业定义参照《高处作业分级》（坠落高度基准面 2m 以上）。</p>\n<hr>\n<h3 id=\"s8\">案例 7：受益人未及时通知 + 火化致死因不明——自行承担不利后果（广东高院再审）</h3>\n<ul>\n<li><strong>案号</strong>：(2020) 粤民申 11974 号</li>\n<li><strong>审理法院 / 审级</strong>：广东省高级人民法院（再审审查）</li>\n<li><strong>裁判日期</strong>：未注明（据律所文章）</li>\n<li><strong>来源 URL</strong>：http://www.kxlawfirm.com/doc_30813736.html （广东凯行律师事务所，转述）</li>\n<li><strong>可信度</strong>：C（待核验——仅律所文章转述，未核到裁判文书原文）</li>\n<li><strong>关键词标签</strong>：意外险、猝死、受益人、及时通知义务、死因鉴定、举证</li>\n</ul>\n<p><strong>基本事实（据转述）</strong>： 被保险人猝死后，受益人未及时通知保险公司，亦未申请死因鉴定，直接将遗体火化，导致死因无法查明。保险公司据此拒赔，受益人诉至法院。</p>\n<p><strong>争议焦点（据转述）</strong>： 受益人未履行及时通知义务、致死因无法查明时，不利后果由谁承担。</p>\n<p><strong>裁判理由（【转述，非原文】据律所文章）</strong>：</p>\n<blockquote>\"广东高院认为，受益人未履行及时通知义务，导致死因无法查明，应自行承担不利后果，保险公司无需赔付。\"</blockquote>\n<p><strong>对我的用处 / 注意</strong>： C 级，仅作线索。与案例 2、4 对照使用：死因不明时，若受益人一方存在未及时报案、未做尸检即火化的过错，可能承担举证不能后果；反之（案例 4）法院仍可在一定证据下酌定赔付。强调理赔环节\"及时报案 + 死因鉴定\"的取证动作。正式引用前须核到 (2020) 粤民申 11974 号原文。</p>\n<p><strong>关联法条</strong>：《保险法》第二十一条（投保人、被保险人、受益人及时通知义务）；第二十二条（理赔资料提供）。</p>\n<hr>\n<h3 id=\"s9\">案例 8：心源性猝死 + 饮酒应酬——若能证明外部诱因且非疾病直接引起，可认定属意外险责任</h3>\n<ul>\n<li><strong>案号</strong>：(2025) 粤 04 民终 1579 号</li>\n<li><strong>审理法院 / 审级</strong>：广东省珠海市中级人民法院（二审）</li>\n<li><strong>裁判日期</strong>：未注明（据律所文章，标注 2025）</li>\n<li><strong>来源 URL</strong>：http://www.kxlawfirm.com/doc_30813736.html （广东凯行律师事务所，转述）</li>\n<li><strong>可信度</strong>：C（待核验——仅律所文章转述，未核到裁判文书原文）</li>\n<li><strong>关键词标签</strong>：意外险、猝死、心源性猝死、外部诱因、近因</li>\n</ul>\n<p><strong>基本事实（据转述）</strong>： 被保险人郭某乙周末加班后参加公司团建聚餐，随后约见客户到酒吧应酬，次日凌晨返回住处，当晚被发现死亡，诊断为\"心源性猝死\"。保险公司以\"疾病\"\"酗酒\"等免责事由拒赔。</p>\n<p><strong>争议焦点（据转述）</strong>： 心源性猝死是否必然属\"疾病\"免责；外部诱因（高强度工作、饮酒）与死亡的近因关系如何认定。</p>\n<p><strong>裁判理由（【转述，非原文】据律所文章）</strong>：</p>\n<blockquote>\"郭某乙在工作聚餐及约见客户饮酒后短时间内出现心源性猝死，符合意外事故'外来的、突发的、非本意的'特征，且无证据证明系由疾病直接引起、可被预见或存在主观故意。同时，保险公司未能举证证明郭某乙存在酗酒行为或死亡与饮酒存在因果关系。最终认定属于附加 24 小时意外险的保险责任范围，判决保险公司全额赔付 60 万元。\"</blockquote>\n<p><strong>对我的用处 / 注意</strong>： C 级，仅作线索。可与案例 2（猝死≠意外，须查近因）形成攻防两面：若能证明超常工作负荷、外伤等外来诱因直接诱发死亡，且保险公司不能证明确系疾病直接引起，法院可能认定属意外。正式引用前须核到 (2025) 粤 04 民终 1579 号原文。</p>\n<p><strong>关联法条</strong>：《保险法》第十七条（免责条款）；意外伤害\"四要件\"。</p>\n<hr>\n<h2 id=\"s10\">二、互联网平台投保（支付宝 / 微信 / App）</h2>\n<h3 id=\"s11\">案例 9：网络投保重疾险——\"他司投保记录\"询问隐藏过深，保险公司未尽提示说明义务判赔 9 万</h3>\n<ul>\n<li><strong>案号</strong>：未检索到公开案号（广州市天河区人民法院一审，已生效、服判息诉）</li>\n<li><strong>审理法院 / 审级</strong>：广州市天河区人民法院（一审）</li>\n<li><strong>裁判日期</strong>：报道于 2025-07（判决已生效）</li>\n<li><strong>来源 URL</strong>：https://static.nfnews.com/content/202507/17/c11518394.html （南方 +，南方报业；另见花城 + https://huacheng.gz-cmc.com/pages/2025/07/14/SF141173040e949c2af99145998e7c6a.html ）</li>\n<li><strong>可信度</strong>：B（官媒刊载法院生效判决 + 法官说法）</li>\n<li><strong>平台</strong>：某网络支付平台（报道未具名，属支付宝 / 蚂蚁保类网络投保场景）</li>\n<li><strong>关键词标签</strong>：重疾险、网络投保、提示说明义务、健康告知、隐藏条款、解除期</li>\n</ul>\n<p><strong>基本事实</strong>： 2023 年 5 月，周某通过某平台购买一年期重疾险，保障\"100 种重疾 30 万 + 20 种轻症 9 万\"，保费 400 余元。2023 年 11 月周某确诊甲状腺左叶乳头状癌，申请理赔。保险公司以周某隐瞒\"一年内曾在其他公司投保重疾险保额超 50 万\"、不符合投保条件为由拒赔，并于 2024 年 1 月 29 日出具《解除保险合同通知书》。周某诉请支付 9 万元轻症保险金。</p>\n<p><strong>争议焦点</strong>： 线上投保\"告知询问事项\"设置是否合理；保险公司是否尽到提示说明义务；解除合同是否超期。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"涉案重疾保险的承保条件被设置成'如实告知'询问问题形式，并将多个不同性质的问题堆砌在同一页面进行概括性提问。而保险公司在本案中用作拒绝理赔的依据条款：'被保险人最近一年是否已在其他保险公司申请累计重大疾病保险保额达 50 万元以上'，更是被隐藏在了第 1 条提问中的后半段，极易被投保人忽略。\"<br>\"根据投保回溯视频，周某网络投保的整个过程仅用时 3 分 10 秒，并用了 25 秒快速完成浏览'免责说明 - 责任免除'内容。期间，保险公司的免责条款既未进行加粗加黑提示，也未设置最短阅读时长，难以保证投保人已经有效、实质性地阅读了该些条款。\"<br>\"保险公司在受理周某理赔后 35 天才出具《解除合同通知书》，已超过了合同约定的 30 天解除期。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 天河法院判决保险公司支付保险金 9 万元，已生效。法官黄思铭（天河法院兴华人民法庭庭长）指出：网络投保法院对提示说明义务采取更严格标准；保险人应以强制阅读时长、独立弹窗、算法分析、AI 客服等技术手段确保投保人了解免责条款。可直接用于反驳\"已加黑加粗即尽到义务\"的惯常抗辩。</p>\n<p><strong>关联法条</strong>：《保险法司法解释（二）》第十二条（网络 / 电话订立保险合同，以网页、音频、视频等形式提示说明可认定尽到义务）；《保险法》第十六条（解除权期限）。</p>\n<hr>\n<h3 id=\"s12\">案例 10：支付宝\"擅自\"投保重疾险——\"等待期\"免责条款未说明，静默转保不影响合同效力但免责条款无效，判赔 10 万</h3>\n<ul>\n<li><strong>案号</strong>：未检索到公开案号（广州市黄埔区人民法院一审；报道称\"终审生效判决\"）</li>\n<li><strong>审理法院 / 审级</strong>：广州市黄埔区人民法院（一审）；报道表述为广州法院终审生效</li>\n<li><strong>裁判日期</strong>：未注明</li>\n<li><strong>来源 URL</strong>：https://so.html5.qq.com/page/real/search_news?docid=70000021_42968e23adc87752 （腾讯搜一搜，来源：信网 / 青岛新闻网，记者耿润）</li>\n<li><strong>可信度</strong>：B（媒体检索报道广州黄埔法院生效判决，含法院认为、法官提醒原文；建议以裁判文书进一步核实）</li>\n<li><strong>平台</strong>：支付宝（中国）网络技术有限公司 / 蚂蚁保保险代理有限公司 / 国泰财产保险有限责任公司（承保）</li>\n<li><strong>关键词标签</strong>：重疾险、支付宝、蚂蚁保、自动转保、默认勾选、等待期、提示说明义务、平台责任</li>\n</ul>\n<p><strong>基本事实</strong>： 李先生 2019 年通过支付宝加入\"相互宝\"，2022 年关停后系统自动转投\"健康福·重疾 1 号（大病版）\"。2023 年 5 月 7 日李先生补缴原保单保费时，支付宝另扣 11.61 元为其投保国泰财险\"健康福·重疾险（保 1 年）\"（重疾保额 10 万），全程无主动确认、无投保提示。李先生后续连续缴纳 6 期。2023 年 6 月李先生确诊慢性肾衰竭 CKD5 期（属重疾），完成 90 天透析后申请理赔，国泰财险以\"等待期\"拒赔并解约。李先生将国泰财险诉至黄埔法院，并把蚂蚁保、支付宝列为第三人。</p>\n<p><strong>争议焦点</strong>：</p>\n<ol>\n<li>非本人操作的\"被投保\"合同是否有效；</li>\n<li>\"等待期\"免责条款是否生效；</li>\n<li>支付宝 / 蚂蚁保是否担责。</li>\n</ol>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"虽李先生主张投保操作非本人所为，但他后续连续缴纳 6 期保费的行为，已构成对保险合同效力的追认，因此认定李先生与国泰财险之间的保险合同合法有效。\"<br>\"结合李先生银行卡余额仅够支付原'重疾 1 号'保费（11.32 元）、未主动点击投保界面等事实，法院认为支付宝公司存在擅自划扣资金为李先生投保新保险的高度可能性。\"<br>\"依据《中华人民共和国保险法》第十七条规定，'等待期'条款属于'免除保险人责任的条款'，国泰财险作为格式条款提供方，负有以显著方式提示投保人，并对条款内容作出明确说明的法定义务。尤其在网络投保场景中，保险人需通过网页、视频等形式主动履行提示说明义务，且需对已履行义务承担举证责任。\"<br>\"国泰财险未以明显方式提示'等待期'条款，未设置强制阅读环节，也未解释条款内容，未依法履行提示和明确说明义务，因此该'等待期'条款对李先生无效。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 黄埔法院判决：确认国泰财险解除行为无效，7 日内支付重大疾病保险金 10 万元，受理费由国泰财险负担。法院提醒：支付宝、蚂蚁保作为大型网络平台应严格规范操作流程，保障用户知情权、选择权；保险公司应完善线上免责条款提示机制，避免以\"默认勾选\"\"小字链接\"规避说明义务。要点：① 保险人提示说明义务不可转嫁，平台静默转保的合规漏洞由平台承担行政 / 流程责任，但免责条款无效的核心仍在保险人未说明；② 网络场景适用举证责任倒置（保险人证明确已提示说明）。</p>\n<p><strong>关联法条</strong>：《保险法》第十七条；《保险法司法解释（二）》第十二条；互联网保险业务监管相关规定。</p>\n<hr>\n<h3 id=\"s13\">案例 11：网上投保等待期出险——保险公司主张\"等待期内确诊\"的举证责任在保险人</h3>\n<ul>\n<li><strong>案号</strong>：广州法院保险纠纷十大典型案例之九（未单列案号；投保人以李某为被保险人网上投保人身保险案）</li>\n<li><strong>审理法院 / 审级</strong>：广州市法院（典型案例发布）</li>\n<li><strong>裁判日期</strong>：2021-07-08（发布日）</li>\n<li><strong>来源 URL</strong>：https://ycpai.ycwb.com/ycppad/content/2021-07/08/content_40128595.html （羊城派）</li>\n<li><strong>可信度</strong>：B</li>\n<li><strong>平台</strong>：网上保险公司（互联网投保）</li>\n<li><strong>关键词标签</strong>：重疾险、网络投保、等待期、举证责任、确诊时间</li>\n</ul>\n<p><strong>基本事实</strong>： 投保人以李某为被保险人通过网上保险公司投保人身保险，生效日 2019-05-10，等待期 180 天。李某 2019 年 10 月就乳腺不适就诊，报告单载\"左乳低回声包块 BI-RADS 3 级，左侧腋下淋巴结肿大\"；2020 年 1 月入院确诊乳腺癌。2020 年 4 月 8 日保险公司出具《不予赔付通知书》，称属等待期内出险。</p>\n<p><strong>争议焦点</strong>： 被保险人是否在等待期内确诊患病；该事实的举证责任分配。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"医院出具的《彩色超声检查报告单》是李某投保后作出的，仅显示'左乳低回声包块 BI-RADS 3 级，左侧腋下淋巴结肿大'。保险公司确认 BI-RADS 3 级不是确诊乳腺癌的标准，同时也表示没有证据证明李某在 2020 年 1 月之前已经确诊乳腺癌。保险公司未提交证据证明李某在案涉保险合同等待期内确诊患病，应承担举证不能的不利后果。\"<br>\"李某系在保险合同等待期满后确诊乳腺癌，属于案涉保险合同约定的理赔范围，保险公司应向李某全额赔付保险赔偿金。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 广州法院判决保险公司全额赔付。要点：等待期内出险的免责抗辩，须由保险人举证\"等待期内已确诊\"；BI-RADS 3 级等未达确诊标准的检查，不足以认定为等待期内患病。与案例 9、10 的等待期 / 提示说明争议互补。</p>\n<p><strong>关联法条</strong>：《民事诉讼法》第六十四条、第九十条（举证责任）；《保险法》相关。</p>\n<hr>\n<h3 id=\"s14\">案例 12：骑手商业意外险 vs 职业伤害保障——\"获职伤赔偿即免赔\"格式条款无效，应双赔</h3>\n<ul>\n<li><strong>案号</strong>：深圳市中级人民法院公布案例（深圳特区报报道；与 (2025) 粤 03 民终 14755 号疑为同一案，详见下方说明）</li>\n<li><strong>审理法院 / 审级</strong>：广东省深圳市中级人民法院（公布案例，报道称\"判决已生效\"）</li>\n<li><strong>裁判日期</strong>：报道于 2025-12-26</li>\n<li><strong>来源 URL</strong>：https://sztqb.sznews.com/MB/content/202512/26/content_3414612.html （深圳特区报，深圳市委机关报）</li>\n<li><strong>可信度</strong>：B（官媒刊载深圳中院公布案例，含裁判理由）</li>\n<li><strong>平台</strong>：外卖平台（B 公司通过系统为骑手自动投保商业意外险，接单时自动扣费）</li>\n<li><strong>关键词标签</strong>：意外险、骑手、职业伤害保障、双赔、格式条款无效、网络平台投保</li>\n</ul>\n<p><strong>基本事实</strong>： 杨某为外卖骑手，其就职的外卖平台 B 公司为其在 A 保险公司投保商业意外险（接单时系统自动投保、从账户扣费，实际投保人为杨某）。2024 年 1 月 15 日杨某派单途中交通事故，胫骨骨折；同年 2 月社保部门认定属职业伤害保障范围，杨某申领职伤赔偿；同年 7 月评定十级伤残，支出鉴定费 2730 元。杨某向 A 保险公司申请意外险 6 万元，保险公司称已获职伤赔偿、依保单约定不再重复赔付。</p>\n<p><strong>争议焦点</strong>： 职业伤害保障与商业意外险能否\"双赔\"；\"获职业伤害保障即拒赔\"格式条款效力。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>\"B 公司为杨某投保的意外险属于商业险，扣费触发条件为当骑手接单时，系统会自动完成意外险的投保，并从其账户中扣除保费，即意外险的实际投保人为杨某；由人社部发布并于 2022 年 7 月起在全国各地试点的《新就业形态就业人员职业伤害保障办法（试行）》，本质上属于职业伤害保险，不同于商业意外险，二者不存在冲突，即使杨某已获得职业伤害保障的赔偿，也不影响其向 A 保险公司申请保险赔偿的权利。\"<br>\"A 保险公司以格式条款的方式强调获得职业伤害保障就拒赔，实则是不合理地免除或者减轻其责任、加重对方责任、应认定为无效。因此，A 保险公司主张免赔事由不成立。\"</blockquote>\n<p><strong>裁判结果 / 对我的用处</strong>： 深圳中院判决 A 保险公司支付意外险保险金 6 万元、鉴定费 2730 元，已生效。要点：职业伤害保障（试点，具社保属性）与商业意外险并行不悖；平台以格式条款将\"已享职伤待遇\"设为免赔条件，属不合理免除自身责任，无效。另可参见广东知险律师事务所整理的 (2025) 粤 03 民终 14755 号（廖某案，众包骑手意外险，同样认定\"获新职伤赔偿则免赔\"条款无效，判 6 万 + 鉴定费）——该案由律所转述、未核到原文（C 级待核验），名称\"廖某\"与本报载\"杨某\"疑为化名差异，建议以裁判文书核实是否为同一案。</p>\n<p><strong>关联法条</strong>：《新就业形态就业人员职业伤害保障办法（试行）》；《保险法》第十九条（格式条款无效）；第十七条（提示说明义务）。</p>\n<hr>\n<h3 id=\"s15\">案例 13：骑手意外险\"新职伤免责\"条款未提示说明——条款不生效，判赔 18 万</h3>\n<ul>\n<li><strong>案号</strong>：(2024) 粤 07 民终 4851 号</li>\n<li><strong>审理法院 / 审级</strong>：广东省江门市中级人民法院（二审）</li>\n<li><strong>裁判日期</strong>：2024（据律所文章）</li>\n<li><strong>来源 URL</strong>：https://www.everwinlawyer.cn/lwzz_details/84.html （广东法制盛邦律师事务所，转述）</li>\n<li><strong>可信度</strong>：C（待核验——仅律所文章转述，未核到裁判文书原文；与另案 (2024) 粤 07 民终 2935 号同类）</li>\n<li><strong>平台</strong>：外卖平台投保的\"众包骑手意外险\"（某浙江分公司承保，通过保险经纪人销售）</li>\n<li><strong>关键词标签</strong>：意外险、骑手、新职伤免责、提示说明义务、保险经纪人、格式条款</li>\n</ul>\n<p><strong>基本事实（据转述）</strong>： 杨某配送期间因交通事故受伤，获新职伤一次性伤残补助金后，向某浙江分公司主张意外险理赔。保险公司以事故在\"扣除职伤保障时间\"内、且特别约定\"若被保险人符合职业伤害情形，保险人不承担本人人身伤亡保险金给付责任\"为由拒赔。</p>\n<p><strong>争议焦点（据转述）</strong>： \"扣除职伤保障时间\"及\"新职伤免责\"特别约定是否属免责条款；保险人是否履行提示说明义务。</p>\n<p><strong>裁判理由（【转述，非原文】据律所文章）</strong>：</p>\n<blockquote>\"涉案保险单所载'保障时间'中关于'扣除职伤保障时间'的约定以及'特别约定'中第 3(7) 条中关于'若被保险人符合《新就业形态就业人员职业伤害保障办法》中约定的职业伤害情形，保险人不承担被保险人本人人身伤亡的保险金给付责任……'的约定，在内容和性质上均属于免除保险人责任的条款。\"<br>\"根据《中华人民共和国保险法》第十七条第二款，某浙江分公司未能举证证明向投保人履行提示说明义务，条款不生效，法院判决某浙江分公司支付 18 万元保险金。\"</blockquote>\n<p><strong>裁判结果（据转述）</strong>： 江门中院二审认定相关约定属免除保险人责任条款，保险公司未能举证履行提示说明义务，条款不生效，判令支付 18 万元保险金。同所文章另列 (2024) 粤 07 民终 2935 号（谢某财案，保险经纪人告知不足、保单无投保人盖章，提示说明义务未履行，判 86814.24 元）——均 C 级待核验。</p>\n<p><strong>对我的用处 / 注意</strong>： C 级，仅作线索。补充案例 12 的\"骑手职伤双赔\"攻防：即便条款被认定有效，\"未提示说明\"亦可使其不生效。注意\"保险经纪人代告知\"不当然视为对投保人履行说明义务（须有授权）。正式引用前须核到 (2024) 粤 07 民终 4851 号 / 2935 号原文。</p>\n<p><strong>关联法条</strong>：《保险法》第十七条第二款；保险经纪人相关规则。</p>\n<hr>\n<h2 id=\"s16\">检索缺口</h2>\n<p>以下问题类型本次未检索到可用的广东法院原文（B 级）或仅有线索（C 级），建议后续补强：</p>\n<ol>\n<li><strong>伤残评定标准之争（人身保险伤残评定标准 vs 工伤标准 / 人体损伤致残程度分级）</strong>：仅检索到标准文本（JR/T 0083—2013 及 GB/T 44893-2024），未找到广东法院就\"意外险伤残等级应按哪种标准评定\"作出裁判的可用案例。本库案例 1（连州骑手猝死）涉及伤残但为死亡赔付，未触及评定标准冲突。</li>\n<li><strong>高风险运动 / 探险免责</strong>：同方全球\"臻爱 2022\"等互联网定寿将赛车、攀岩、潜水等列为危险活动询问项，但未检索到广东法院就\"高风险运动免责条款提示说明\"作出裁判的原文。</li>\n<li><strong>自杀条款 / 两年不可抗辩条款</strong>：未检索到广东法院就《保险法》第四十四条（自杀免责，但合同成立满二年除外）作出裁判的可用案例；案例 8 涉及的\"附加猝死责任\"产品含自杀免责但非本案焦点。</li>\n<li><strong>微信（微保）渠道专属案例</strong>：本次互联网板块以支付宝 / 蚂蚁保、外卖平台、网上保险公司为主；微信\"微保\"渠道仅见外地法院案例（江西武宁法院微医保、成都青羊法院微医保重疾险）及一份无公开 URL 的江门新会法院\"微保\"定期寿险案（孙某丙案，C 级且 URL 未检索到，故未收录），建议后续补检索广东法院\"微保\"裁判文书。</li>\n<li><strong>可回溯管理专门裁判</strong>：本次案例多从\"提示说明义务\"角度切入，但未检索到以\"互联网保险可回溯管理\"为独立争议焦点的广东法院原文。</li>\n<li><strong>平台责任（蚂蚁保 / 支付宝）与保险人责任区分的终审定性</strong>：案例 10（黄埔）明确平台合规漏洞，但免责条款无效的核心归责仍在保险人；未检索到就\"平台（代理方）独立赔偿责任\"作出终局认定的广东法院原文。</li>\n</ol>", "toc": [{"id": "s1", "lv": 2, "t": "一、意外险 / 寿险"}, {"id": "s2", "lv": 3, "t": "案例 1：众包骑手猝死——\"工作时间 / 工作岗位\"猝死赔付条件被认定为隐性免责条款"}, {"id": "s3", "lv": 3, "t": "案例 2：猝死是否属\"意外伤害\"——猝死的近因须鉴定，不能一概拒赔"}, {"id": "s4", "lv": 3, "t": "案例 3：团体意外险附加猝死责任——\"表面健康的人\"并非指\"没有任何疾病\""}, {"id": "s5", "lv": 3, "t": "案例 4：死因不明时意外险不能免责——法院可酌定按比例赔偿"}, {"id": "s6", "lv": 3, "t": "案例 5：职业类别未询问 + 30 日解除权——网络意外险不得以\"职业不符\"超期拒赔"}, {"id": "s7", "lv": 3, "t": "案例 6：高处作业除外条款未提示说明——免责条款不生效（广东高院再审）"}, {"id": "s8", "lv": 3, "t": "案例 7：受益人未及时通知 + 火化致死因不明——自行承担不利后果（广东高院再审）"}, {"id": "s9", "lv": 3, "t": "案例 8：心源性猝死 + 饮酒应酬——若能证明外部诱因且非疾病直接引起，可认定属意外险责任"}, {"id": "s10", "lv": 2, "t": "二、互联网平台投保（支付宝 / 微信 / App）"}, {"id": "s11", "lv": 3, "t": "案例 9：网络投保重疾险——\"他司投保记录\"询问隐藏过深，保险公司未尽提示说明义务判赔 9 万"}, {"id": "s12", "lv": 3, "t": "案例 10：支付宝\"擅自\"投保重疾险——\"等待期\"免责条款未说明，静默转保不影响合同效力但免责条款无效，判赔 10 万"}, {"id": "s13", "lv": 3, "t": "案例 11：网上投保等待期出险——保险公司主张\"等待期内确诊\"的举证责任在保险人"}, {"id": "s14", "lv": 3, "t": "案例 12：骑手商业意外险 vs 职业伤害保障——\"获职伤赔偿即免赔\"格式条款无效，应双赔"}, {"id": "s15", "lv": 3, "t": "案例 13：骑手意外险\"新职伤免责\"条款未提示说明——条款不生效，判赔 18 万"}, {"id": "s16", "lv": 2, "t": "检索缺口"}], "text": "意外险 / 寿险 / 互联网平台投保 · 案例库 采集日期：2026 09 16 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手来源待核验 B 级 = 法院官方 / 官媒来源（法院官网、人民法院报、省级党报及其新媒体、检察日报等）；C 级 = 律所 / 自媒体转述，仅作线索，标\"待核验\"，不得直接引用为裁判规则。 说明：本库聚焦广东法院裁判。互联网平台投保部分均系广东（广州、深圳、江门）法院案例。C 级案例均注明\"据律所文章转述，未核到裁判文书原文\"。 一、意外险 / 寿险 案例 1：众包骑手猝死——\"工作时间 / 工作岗位\"猝死赔付条件被认定为隐性免责条款 案号 ：未检索到公开案号（连州法院一审，清远中院二审维持） 审理法院 / 审级 ：连州市人民法院（一审）；广东省清远市中级人民法院（二审，驳回上诉、维持原判） 裁判日期 ：未注明（报道时\"判决现已生效\"） 来源 URL ：https://lz.gdqyfy.gov.cn/qyzynet/fyxw/16003.jhtml （连州市人民法院官网\"法院新闻\"栏目） 可信度 ：B（法院官网原文，含法官说法） 关键词标签 ：猝死、意外险、众包骑手、隐性免责条款、提示说明义务、受益人认定 基本事实 ： 邓某于 2017 年在美团众包 APP 注册成为网约配送员。2023 年 3 月 2 日，邓某接首单时自动扣除每日 2.5 元保费，投保\"众包骑手意外险\"并附加\"猝死保险\"，意外险保额 60 万、猝死保额 60 万，未指定受益人。保单特别约定：\"猝死保险金：在工作时间和工作岗位，身体急性症状发生后即刻或 48 小时内经抢救无效死亡。\"当日 17 时许邓某被发现俯卧路面，抢救无效死亡，公安机关死亡证明载明死因为急性冠脉综合症（猝死）。平台跑单记录显示当日 4 时 34 分有 1 次派送任务，此后无派送记录。邓某父母理赔遭拒（保险公司称死亡时间不在工作期间、地点不在工作岗位，且已通过邮件向平台公司提示说明），诉至法院。 争议焦点 ： 1. 猝死保险金条款中\"工作时间和工作岗位\"赔付条件是否为隐性免责条款； 2. 保险公司向平台公司（而非实际投保人骑手）进行提示说明，能否认定为已向实际投保人履责。 裁判理由（原文摘录） ： \"众包骑手意外险保障的是骑手的人身权益，而非其他主体权益。投保操作、保费实际负担主体均为骑手，故实际投保人应穿透认定为骑手。猝死保险金条款中有关事故发生于'工作时间、工作岗位'的赔付条件应穿透认定为隐性免责条款。\" \"骑手意外险投保模式特殊，保险公司对投保模式应系明知，保险公司向某信息科技有限公司进行免责提示告知，并不能据此认定为已向实际投保人履责到位。\" \"众包骑手具有工作时间碎片化、工作地点自由化的特征，将邓某死亡前的平台接单、日常工作规律进行对比，结合逻辑推理和日常生活经验，可以认定邓某的猝死事件发生在工作时间内具有高度盖然性。\" \"保险公司作为保险人，负有向邓某明示具体保险责任范围和除外责任范围的义务，并未举证证明其在邓某投保前就该条款进行了明示，投保完成后邓某在平台保单详情页亦不能一目了然地阅读或注意到该内容，因此该条款对邓某不产生效力，且案涉事故发生在保险期间内。\" 裁判结果 / 对我的用处 ： 连州法院判决保险公司 15 日内支付保险金 60 万元；清远中院二审驳回上诉、维持原判。要点：① 众包骑手\"一日险\"应穿透认定实际投保人；② 向平台而非骑手提示，不视为对实际投保人尽到说明义务；③ \"工作时间和工作岗位\"猝死赔付条件属隐性免责，未对骑手明示则不生效；④ 骑手工作碎片化特征下，\"工作时间\"应结合接单规律综合认定。对港资企业法务办理骑手类灵活用工保险极具参考价值。 关联法条 ：《保险法》第十七条（提示说明义务）；关于\"猝死\"\"意外\"定义之争，另见案例 2、3。 案例 2：猝死是否属\"意外伤害\"——猝死的近因须鉴定，不能一概拒赔 案号 ：(2008) 惠中法民一终字第 19 号 审理法院 / 审级 ：广东省惠州市中级人民法院（二审）；撤销惠州市惠城区人民法院 (2007) 惠城法民一初字第 1625 号 裁判日期 ：2008 03 05 来源 URL ：https://zyzk.jcrb.com/alyz/content.html?gid=C1355307 （检察日报·正义智库\"案例要旨\"栏目） 可信度 ：B（官媒案例要旨 + 判决书正文节录） 关键词标签 ：猝死、意外险、意外伤害定义、近因、尸体鉴定 基本事实 ： 正泰公司向某保险公司惠州中心支公司投保团体意外伤害保险，被保险人含关某、刘某之子。条款释义\"意外伤害\"为：外来的、突然的、非本意的、非疾病的使身体受到伤害的客观事件。2007 年 3 月 31 日，关某之子就餐后突然倒地，送医抢救无效身亡，死亡证明书诊断\"猝死\"。保险公司提出尸检被拒，作出理赔结论：猝死不符合意外险条件，不予给付。关某诉至法院。 争议焦点 ： 猝死是否属于意外险责任范围；受益人拒绝尸检致死因不明时举证责任如何分配。 裁判理由（原文摘录） ： \"猝死只是死亡的表现形式，而非死亡的原因。导致猝死的原因，可能是疾病，也有可能是非疾病，需要对猝死的原因进行进一步鉴定或分析，才能最终确定是否属于意外伤害的范围；猝死虽然属于日常生活经验中的'意外'死亡，但它与保险条款的'意外'定义是不同的，前者强调的是出乎预料、没有预见，具有突然性，后者则应具备外来的、突然的、非本意的、非疾病四个要素。\" 裁判结果 / 对我的用处 ： 检察日报正义智库仅刊载案例要旨与部分判决书正文，未给出完整二审主文金额。要点：猝死≠意外，但猝死本身只是死亡形式，须查明近因（疾病或非疾病外来因素）；保险公司以\"猝死即非意外\"直接拒赔不成立，应进一步举证死因。对\"猝死附加险 / 主险是否赔付\"系列争议（案例 3）提供底层定义框架。 关联法条 ：《保险法》相关；意外伤害\"四要件\"（外来的、突然的、非本意的、非疾病的）。 案例 3：团体意外险附加猝死责任——\"表面健康的人\"并非指\"没有任何疾病\" 案号 ：广州法院保险纠纷十大典型案例之八（未单列案号；黄某与某保险公司意外伤害保险合同纠纷案） 审理法院 / 审级 ：广州市法院（典型案例发布，2021 07 08） 裁判日期 ：2021 07 08（发布日） 来源 URL ：https://ycpai.ycwb.com/ycppad/content/2021 07/08/content 40128595.html （羊城派 / 羊城晚报，广州中院发布） 可信度 ：B（官媒刊载广州法院十大典型案例，含法官说法） 关键词标签 ：猝死、团体意外险、附加猝死责任、条款释义、表面健康 基本事实 ： 黄某的工作单位为包括身患鼻咽癌的黄某在内的员工投保团体人身意外伤害险，适用条款含附加猝死责任条款。猝死释义：\"指表面健康的人因潜在疾病、机能障碍或其他原因在出现症状后 24 小时内发生的非暴力性突然死亡。\"后黄某猝死，受益人主张理赔；保险公司抗辩黄某身患癌症，不属于猝死释义中的\"表面健康的人\"，故不赔。 争议焦点 ： \"表面健康的人\"应作何种解释；患癌被保险人死亡是否符合合同约定的猝死情形。 裁判理由（原文摘录） ： \"依据通常解释和生活常识，猝死的定义中的'表面健康'，显然不是指没有任何疾病，而应当是指未患有能够导致患者突然死亡的疾病。虽然被保险人患有鼻咽癌，但并无证据显示癌症已发展到终末期，且保险公司也未能提交此类癌症会导致患者突然死亡的证据。所以被保险人死亡原因符合合同约定的猝死情形，保险公司应当承担给付相应保险金的责任。\" 裁判结果 / 对我的用处 ： 广州法院认为被保险人死亡原因符合约定猝死情形，保险公司应给付保险金。要点：猝死释义中的\"表面健康\"应作限缩、合理解释，不能将\"曾患病\"一律排除；保险公司主张\"患病即非表面健康\"须举证该疾病足以导致突然死亡。可直接用于反驳保险人以\"投保前病史\"否定猝死责任的抗辩。 关联法条 ：《保险法》第三十条（格式条款争议作有利于被保险人和受益人解释）；条款释义解释规则。 案例 4：死因不明时意外险不能免责——法院可酌定按比例赔偿 案号 ：广州法院保险纠纷十大典型案例之七（未单列案号；冯某与某保险公司保险合同纠纷案） 审理法院 / 审级 ：广州市法院（典型案例发布） 裁判日期 ：2021 07 08（发布日） 来源 URL ：https://ycpai.ycwb.com/ycppad/content/2021 07/08/content 40128595.html （羊城派） 可信度 ：B 关键词标签 ：意外险、死因不明、举证、酌定赔偿比例 基本事实 ： 冯某投保意外险后不幸摔倒死亡。医疗机构认为其死亡原因为脑血管疾病导致脑出血，或者是脑挫伤。受益人主张摔倒致脑挫伤（意外伤害）死亡应理赔；保险公司抗辩系脑血管疾病，非意外，不在保险范围。 争议焦点 ： 死因无法确定为疾病还是意外时，意外险保险公司能否一概免责。 裁判理由（原文摘录） ： \"在无法确定冯某死因是疾病还是意外的情况下，可以酌定保险公司按照一定比例赔偿部分保险金。\" \"意外险以被保险人发生合同约定范围内的意外伤害作为理赔的前提，但如果被保险人是因为疾病导致损害，保险公司不负赔偿责任。而在现实生活中，有的被保险人突然死亡的具体原因难以确定，无法准确认定死因是突发疾病还是意外伤害致死。在此情况下，人民法院可以根据具体情形，酌定保险公司支付部分保险金。\" 裁判结果 / 对我的用处 ： 广州法院明确：死因不明时并非当然免责，法院可结合证据酌定按比例赔付。对受益人而言，死因鉴定与报案留证是关键；对保险人而言，\"死因不明\"不等于\"拒赔成立\"。可结合案例 2 的近因规则使用。 关联法条 ：《保险法》第二十二条（理赔举证责任）；民事诉讼举证责任分配。 案例 5：职业类别未询问 + 30 日解除权——网络意外险不得以\"职业不符\"超期拒赔 案号 ：广州法院保险纠纷十大典型案例之六（未单列案号；刘某与某保险公司保险合同纠纷案） 审理法院 / 审级 ：广州市法院（典型案例发布） 裁判日期 ：2021 07 08（发布日） 来源 URL ：https://ycpai.ycwb.com/ycppad/content/2021 07/08/content 40128595.html （羊城派） 可信度 ：B 关键词标签 ：意外险、职业类别、如实告知、解除权除斥期间、网络投保 基本事实 ： 刘某通过网络向保险公司购买人身意外伤害保险，承保职业范围 1 3 类。刘某填写投保信息时选择职业为\"外务员\"（属第 2 类）。2018 年 1 月底刘某工作中意外受伤。2018 年 2 月 1 日保险公司调查得知刘某实际从事职业与投保类型不符，以未如实告知职业为由拒赔，但保险公司在 30 日内未行使解除权。 争议焦点 ： 保险人已知投保人职业不符后，未在法定 30 日除斥期间内行使解除权，能否直接拒赔。 裁判理由（原文摘录） ： \"保险公司在 2018 年 2 月 1 日即已知道刘某投保职业与实际职业不符，但未在 30 日内行使解除权，其关于后续调查报批流程需要花更长时间的解释亦不足以成为可超过法定期限行使解除权的理由，故判令保险公司承担保险责任。\" \"保险公司调查报批流程需要花更长时间，不足以成为保险公司可超过法定期限行使解除权的理由。保险公司未在法定期限内行使解除权，直接以投保人未履行如实告知义务拒赔的，人民法院不予支持。\" 裁判结果 / 对我的用处 ： 广州法院判决保险公司承担保险责任。要点：① 保险人解除权受 30 日除斥期间限制，内部流程不能突破；② 超期未解除即不得再以未如实告知拒赔。可与\"职业类别询问范围\"结合（见互联网投保部分张家港案思路，及本案提示：未询问则不负告知义务）。 关联法条 ：《保险法》第十六条第三款（解除权 30 日除斥期间）；《保险法司法解释（二）》第六条（询问告知主义）。 案例 6：高处作业除外条款未提示说明——免责条款不生效（广东高院再审） 案号 ：(2026) 粤民申 3209 号 审理法院 / 审级 ：广东省高级人民法院（再审审查，驳回保险公司再审申请） 裁判日期 ：2026 05 09（据今日头条文章标注） 来源 URL ：https://www.insulaw.cn/newsinfo/9230705.html （广东知险律师事务所，转述）；https://www.toutiao.com/article/7676341306696466990/ （今日头条，转述） 可信度 ：C（待核验——仅律所 / 自媒体转述，未核到裁判文书原文；案号、日期据转述） 关键词标签 ：意外险、高处作业除外、特别约定、免责条款、提示说明义务 基本事实（据转述） ： 保单\"特别约定\"载有《附加高处作业除外保险（2022 版）条款》，约定被保险人在高处作业过程中发生的人身伤害，保险人不承担给付保险金责任。事故发生在被保险人作业过程中。保险公司以高处作业除外条款拒赔，投保人 / 被保险人抗辩该条款未提示说明。 争议焦点（据转述） ： \"特别约定\"中的高处作业除外条款，实质是免责条款还是保险责任条款；保险人是否尽到提示和明确说明义务。 裁判理由（【转述，非原文】据律所文章） ： \"案涉'高处作业除外保险'特别约定，免除了保险公司在被保险人发生人身伤害时本应承担的保险责任，因此被认定为免责条款，而不是保险责任条款。\" \"投保单上的'投保人声明'如果只是格式文本，没有写明保险公司对'高处作业除外'做过说明，就不能单独证明已尽说明义务；销售人员的聊天记录反而可能证明并未履行。\" \"案涉免责条款因未履行提示和明确说明义务而不发生法律效力，保险公司以高处作业除外条款拒赔依据不足。\" 裁判结果（据转述） ： 广东高院维持一审、二审认定，该高处作业除外免责条款不发生效力，驳回保险公司再审申请。 对我的用处 / 注意 ： C 级，仅作线索。可作为\"特别约定型隐性免责条款\"的攻防素材：将\"除外情形\"包装进特别约定，仍可能被认定为实质免责，须单独提示说明。正式引用前务必通过裁判文书网 / 法院案例库核到 (2026) 粤民申 3209 号原文。 关联法条 ：《保险法》第十七条第二款；高处作业定义参照《高处作业分级》（坠落高度基准面 2m 以上）。 案例 7：受益人未及时通知 + 火化致死因不明——自行承担不利后果（广东高院再审） 案号 ：(2020) 粤民申 11974 号 审理法院 / 审级 ：广东省高级人民法院（再审审查） 裁判日期 ：未注明（据律所文章） 来源 URL ：http://www.kxlawfirm.com/doc 30813736.html （广东凯行律师事务所，转述） 可信度 ：C（待核验——仅律所文章转述，未核到裁判文书原文） 关键词标签 ：意外险、猝死、受益人、及时通知义务、死因鉴定、举证 基本事实（据转述） ： 被保险人猝死后，受益人未及时通知保险公司，亦未申请死因鉴定，直接将遗体火化，导致死因无法查明。保险公司据此拒赔，受益人诉至法院。 争议焦点（据转述） ： 受益人未履行及时通知义务、致死因无法查明时，不利后果由谁承担。 裁判理由（【转述，非原文】据律所文章） ： \"广东高院认为，受益人未履行及时通知义务，导致死因无法查明，应自行承担不利后果，保险公司无需赔付。\" 对我的用处 / 注意 ： C 级，仅作线索。与案例 2、4 对照使用：死因不明时，若受益人一方存在未及时报案、未做尸检即火化的过错，可能承担举证不能后果；反之（案例 4）法院仍可在一定证据下酌定赔付。强调理赔环节\"及时报案 + 死因鉴定\"的取证动作。正式引用前须核到 (2020) 粤民申 11974 号原文。 关联法条 ：《保险法》第二十一条（投保人、被保险人、受益人及时通知义务）；第二十二条（理赔资料提供）。 案例 8：心源性猝死 + 饮酒应酬——若能证明外部诱因且非疾病直接引起，可认定属意外险责任 案号 ：(2025) 粤 04 民终 1579 号 审理法院 / 审级 ：广东省珠海市中级人民法院（二审） 裁判日期 ：未注明（据律所文章，标注 2025） 来源 URL ：http://www.kxlawfirm.com/doc 30813736.html （广东凯行律师事务所，转述） 可信度 ：C（待核验——仅律所文章转述，未核到裁判文书原文） 关键词标签 ：意外险、猝死、心源性猝死、外部诱因、近因 基本事实（据转述） ： 被保险人郭某乙周末加班后参加公司团建聚餐，随后约见客户到酒吧应酬，次日凌晨返回住处，当晚被发现死亡，诊断为\"心源性猝死\"。保险公司以\"疾病\"\"酗酒\"等免责事由拒赔。 争议焦点（据转述） ： 心源性猝死是否必然属\"疾病\"免责；外部诱因（高强度工作、饮酒）与死亡的近因关系如何认定。 裁判理由（【转述，非原文】据律所文章） ： \"郭某乙在工作聚餐及约见客户饮酒后短时间内出现心源性猝死，符合意外事故'外来的、突发的、非本意的'特征，且无证据证明系由疾病直接引起、可被预见或存在主观故意。同时，保险公司未能举证证明郭某乙存在酗酒行为或死亡与饮酒存在因果关系。最终认定属于附加 24 小时意外险的保险责任范围，判决保险公司全额赔付 60 万元。\" 对我的用处 / 注意 ： C 级，仅作线索。可与案例 2（猝死≠意外，须查近因）形成攻防两面：若能证明超常工作负荷、外伤等外来诱因直接诱发死亡，且保险公司不能证明确系疾病直接引起，法院可能认定属意外。正式引用前须核到 (2025) 粤 04 民终 1579 号原文。 关联法条 ：《保险法》第十七条（免责条款）；意外伤害\"四要件\"。 二、互联网平台投保（支付宝 / 微信 / App） 案例 9：网络投保重疾险——\"他司投保记录\"询问隐藏过深，保险公司未尽提示说明义务判赔 9 万 案号 ：未检索到公开案号（广州市天河区人民法院一审，已生效、服判息诉） 审理法院 / 审级 ：广州市天河区人民法院（一审） 裁判日期 ：报道于 2025 07（判决已生效） 来源 URL ：https://static.nfnews.com/content/202507/17/c11518394.html （南方 +，南方报业；另见花城 + https://huacheng.gz cmc.com/pages/2025/07/14/SF141173040e949c2af99145998e7c6a.html ） 可信度 ：B（官媒刊载法院生效判决 + 法官说法） 平台 ：某网络支付平台（报道未具名，属支付宝 / 蚂蚁保类网络投保场景） 关键词标签 ：重疾险、网络投保、提示说明义务、健康告知、隐藏条款、解除期 基本事实 ： 2023 年 5 月，周某通过某平台购买一年期重疾险，保障\"100 种重疾 30 万 + 20 种轻症 9 万\"，保费 400 余元。2023 年 11 月周某确诊甲状腺左叶乳头状癌，申请理赔。保险公司以周某隐瞒\"一年内曾在其他公司投保重疾险保额超 50 万\"、不符合投保条件为由拒赔，并于 2024 年 1 月 29 日出具《解除保险合同通知书》。周某诉请支付 9 万元轻症保险金。 争议焦点 ： 线上投保\"告知询问事项\"设置是否合理；保险公司是否尽到提示说明义务；解除合同是否超期。 裁判理由（原文摘录） ： \"涉案重疾保险的承保条件被设置成'如实告知'询问问题形式，并将多个不同性质的问题堆砌在同一页面进行概括性提问。而保险公司在本案中用作拒绝理赔的依据条款：'被保险人最近一年是否已在其他保险公司申请累计重大疾病保险保额达 50 万元以上'，更是被隐藏在了第 1 条提问中的后半段，极易被投保人忽略。\" \"根据投保回溯视频，周某网络投保的整个过程仅用时 3 分 10 秒，并用了 25 秒快速完成浏览'免责说明 责任免除'内容。期间，保险公司的免责条款既未进行加粗加黑提示，也未设置最短阅读时长，难以保证投保人已经有效、实质性地阅读了该些条款。\" \"保险公司在受理周某理赔后 35 天才出具《解除合同通知书》，已超过了合同约定的 30 天解除期。\" 裁判结果 / 对我的用处 ： 天河法院判决保险公司支付保险金 9 万元，已生效。法官黄思铭（天河法院兴华人民法庭庭长）指出：网络投保法院对提示说明义务采取更严格标准；保险人应以强制阅读时长、独立弹窗、算法分析、AI 客服等技术手段确保投保人了解免责条款。可直接用于反驳\"已加黑加粗即尽到义务\"的惯常抗辩。 关联法条 ：《保险法司法解释（二）》第十二条（网络 / 电话订立保险合同，以网页、音频、视频等形式提示说明可认定尽到义务）；《保险法》第十六条（解除权期限）。 案例 10：支付宝\"擅自\"投保重疾险——\"等待期\"免责条款未说明，静默转保不影响合同效力但免责条款无效，判赔 10 万 案号 ：未检索到公开案号（广州市黄埔区人民法院一审；报道称\"终审生效判决\"） 审理法院 / 审级 ：广州市黄埔区人民法院（一审）；报道表述为广州法院终审生效 裁判日期 ：未注明 来源 URL ：https://so.html5.qq.com/page/real/search news?docid=70000021 42968e23adc87752 （腾讯搜一搜，来源：信网 / 青岛新闻网，记者耿润） 可信度 ：B（媒体检索报道广州黄埔法院生效判决，含法院认为、法官提醒原文；建议以裁判文书进一步核实） 平台 ：支付宝（中国）网络技术有限公司 / 蚂蚁保保险代理有限公司 / 国泰财产保险有限责任公司（承保） 关键词标签 ：重疾险、支付宝、蚂蚁保、自动转保、默认勾选、等待期、提示说明义务、平台责任 基本事实 ： 李先生 2019 年通过支付宝加入\"相互宝\"，2022 年关停后系统自动转投\"健康福·重疾 1 号（大病版）\"。2023 年 5 月 7 日李先生补缴原保单保费时，支付宝另扣 11.61 元为其投保国泰财险\"健康福·重疾险（保 1 年）\"（重疾保额 10 万），全程无主动确认、无投保提示。李先生后续连续缴纳 6 期。2023 年 6 月李先生确诊慢性肾衰竭 CKD5 期（属重疾），完成 90 天透析后申请理赔，国泰财险以\"等待期\"拒赔并解约。李先生将国泰财险诉至黄埔法院，并把蚂蚁保、支付宝列为第三人。 争议焦点 ： 1. 非本人操作的\"被投保\"合同是否有效； 2. \"等待期\"免责条款是否生效； 3. 支付宝 / 蚂蚁保是否担责。 裁判理由（原文摘录） ： \"虽李先生主张投保操作非本人所为，但他后续连续缴纳 6 期保费的行为，已构成对保险合同效力的追认，因此认定李先生与国泰财险之间的保险合同合法有效。\" \"结合李先生银行卡余额仅够支付原'重疾 1 号'保费（11.32 元）、未主动点击投保界面等事实，法院认为支付宝公司存在擅自划扣资金为李先生投保新保险的高度可能性。\" \"依据《中华人民共和国保险法》第十七条规定，'等待期'条款属于'免除保险人责任的条款'，国泰财险作为格式条款提供方，负有以显著方式提示投保人，并对条款内容作出明确说明的法定义务。尤其在网络投保场景中，保险人需通过网页、视频等形式主动履行提示说明义务，且需对已履行义务承担举证责任。\" \"国泰财险未以明显方式提示'等待期'条款，未设置强制阅读环节，也未解释条款内容，未依法履行提示和明确说明义务，因此该'等待期'条款对李先生无效。\" 裁判结果 / 对我的用处 ： 黄埔法院判决：确认国泰财险解除行为无效，7 日内支付重大疾病保险金 10 万元，受理费由国泰财险负担。法院提醒：支付宝、蚂蚁保作为大型网络平台应严格规范操作流程，保障用户知情权、选择权；保险公司应完善线上免责条款提示机制，避免以\"默认勾选\"\"小字链接\"规避说明义务。要点：① 保险人提示说明义务不可转嫁，平台静默转保的合规漏洞由平台承担行政 / 流程责任，但免责条款无效的核心仍在保险人未说明；② 网络场景适用举证责任倒置（保险人证明确已提示说明）。 关联法条 ：《保险法》第十七条；《保险法司法解释（二）》第十二条；互联网保险业务监管相关规定。 案例 11：网上投保等待期出险——保险公司主张\"等待期内确诊\"的举证责任在保险人 案号 ：广州法院保险纠纷十大典型案例之九（未单列案号；投保人以李某为被保险人网上投保人身保险案） 审理法院 / 审级 ：广州市法院（典型案例发布） 裁判日期 ：2021 07 08（发布日） 来源 URL ：https://ycpai.ycwb.com/ycppad/content/2021 07/08/content 40128595.html （羊城派） 可信度 ：B 平台 ：网上保险公司（互联网投保） 关键词标签 ：重疾险、网络投保、等待期、举证责任、确诊时间 基本事实 ： 投保人以李某为被保险人通过网上保险公司投保人身保险，生效日 2019 05 10，等待期 180 天。李某 2019 年 10 月就乳腺不适就诊，报告单载\"左乳低回声包块 BI RADS 3 级，左侧腋下淋巴结肿大\"；2020 年 1 月入院确诊乳腺癌。2020 年 4 月 8 日保险公司出具《不予赔付通知书》，称属等待期内出险。 争议焦点 ： 被保险人是否在等待期内确诊患病；该事实的举证责任分配。 裁判理由（原文摘录） ： \"医院出具的《彩色超声检查报告单》是李某投保后作出的，仅显示'左乳低回声包块 BI RADS 3 级，左侧腋下淋巴结肿大'。保险公司确认 BI RADS 3 级不是确诊乳腺癌的标准，同时也表示没有证据证明李某在 2020 年 1 月之前已经确诊乳腺癌。保险公司未提交证据证明李某在案涉保险合同等待期内确诊患病，应承担举证不能的不利后果。\" \"李某系在保险合同等待期满后确诊乳腺癌，属于案涉保险合同约定的理赔范围，保险公司应向李某全额赔付保险赔偿金。\" 裁判结果 / 对我的用处 ： 广州法院判决保险公司全额赔付。要点：等待期内出险的免责抗辩，须由保险人举证\"等待期内已确诊\"；BI RADS 3 级等未达确诊标准的检查，不足以认定为等待期内患病。与案例 9、10 的等待期 / 提示说明争议互补。 关联法条 ：《民事诉讼法》第六十四条、第九十条（举证责任）；《保险法》相关。 案例 12：骑手商业意外险 vs 职业伤害保障——\"获职伤赔偿即免赔\"格式条款无效，应双赔 案号 ：深圳市中级人民法院公布案例（深圳特区报报道；与 (2025) 粤 03 民终 14755 号疑为同一案，详见下方说明） 审理法院 / 审级 ：广东省深圳市中级人民法院（公布案例，报道称\"判决已生效\"） 裁判日期 ：报道于 2025 12 26 来源 URL ：https://sztqb.sznews.com/MB/content/202512/26/content 3414612.html （深圳特区报，深圳市委机关报） 可信度 ：B（官媒刊载深圳中院公布案例，含裁判理由） 平台 ：外卖平台（B 公司通过系统为骑手自动投保商业意外险，接单时自动扣费） 关键词标签 ：意外险、骑手、职业伤害保障、双赔、格式条款无效、网络平台投保 基本事实 ： 杨某为外卖骑手，其就职的外卖平台 B 公司为其在 A 保险公司投保商业意外险（接单时系统自动投保、从账户扣费，实际投保人为杨某）。2024 年 1 月 15 日杨某派单途中交通事故，胫骨骨折；同年 2 月社保部门认定属职业伤害保障范围，杨某申领职伤赔偿；同年 7 月评定十级伤残，支出鉴定费 2730 元。杨某向 A 保险公司申请意外险 6 万元，保险公司称已获职伤赔偿、依保单约定不再重复赔付。 争议焦点 ： 职业伤害保障与商业意外险能否\"双赔\"；\"获职业伤害保障即拒赔\"格式条款效力。 裁判理由（原文摘录） ： \"B 公司为杨某投保的意外险属于商业险，扣费触发条件为当骑手接单时，系统会自动完成意外险的投保，并从其账户中扣除保费，即意外险的实际投保人为杨某；由人社部发布并于 2022 年 7 月起在全国各地试点的《新就业形态就业人员职业伤害保障办法（试行）》，本质上属于职业伤害保险，不同于商业意外险，二者不存在冲突，即使杨某已获得职业伤害保障的赔偿，也不影响其向 A 保险公司申请保险赔偿的权利。\" \"A 保险公司以格式条款的方式强调获得职业伤害保障就拒赔，实则是不合理地免除或者减轻其责任、加重对方责任、应认定为无效。因此，A 保险公司主张免赔事由不成立。\" 裁判结果 / 对我的用处 ： 深圳中院判决 A 保险公司支付意外险保险金 6 万元、鉴定费 2730 元，已生效。要点：职业伤害保障（试点，具社保属性）与商业意外险并行不悖；平台以格式条款将\"已享职伤待遇\"设为免赔条件，属不合理免除自身责任，无效。另可参见广东知险律师事务所整理的 (2025) 粤 03 民终 14755 号（廖某案，众包骑手意外险，同样认定\"获新职伤赔偿则免赔\"条款无效，判 6 万 + 鉴定费）——该案由律所转述、未核到原文（C 级待核验），名称\"廖某\"与本报载\"杨某\"疑为化名差异，建议以裁判文书核实是否为同一案。 关联法条 ：《新就业形态就业人员职业伤害保障办法（试行）》；《保险法》第十九条（格式条款无效）；第十七条（提示说明义务）。 案例 13：骑手意外险\"新职伤免责\"条款未提示说明——条款不生效，判赔 18 万 案号 ：(2024) 粤 07 民终 4851 号 审理法院 / 审级 ：广东省江门市中级人民法院（二审） 裁判日期 ：2024（据律所文章） 来源 URL ：https://www.everwinlawyer.cn/lwzz details/84.html （广东法制盛邦律师事务所，转述） 可信度 ：C（待核验——仅律所文章转述，未核到裁判文书原文；与另案 (2024) 粤 07 民终 2935 号同类） 平台 ：外卖平台投保的\"众包骑手意外险\"（某浙江分公司承保，通过保险经纪人销售） 关键词标签 ：意外险、骑手、新职伤免责、提示说明义务、保险经纪人、格式条款 基本事实（据转述） ： 杨某配送期间因交通事故受伤，获新职伤一次性伤残补助金后，向某浙江分公司主张意外险理赔。保险公司以事故在\"扣除职伤保障时间\"内、且特别约定\"若被保险人符合职业伤害情形，保险人不承担本人人身伤亡保险金给付责任\"为由拒赔。 争议焦点（据转述） ： \"扣除职伤保障时间\"及\"新职伤免责\"特别约定是否属免责条款；保险人是否履行提示说明义务。 裁判理由（【转述，非原文】据律所文章） ： \"涉案保险单所载'保障时间'中关于'扣除职伤保障时间'的约定以及'特别约定'中第 3(7) 条中关于'若被保险人符合《新就业形态就业人员职业伤害保障办法》中约定的职业伤害情形，保险人不承担被保险人本人人身伤亡的保险金给付责任……'的约定，在内容和性质上均属于免除保险人责任的条款。\" \"根据《中华人民共和国保险法》第十七条第二款，某浙江分公司未能举证证明向投保人履行提示说明义务，条款不生效，法院判决某浙江分公司支付 18 万元保险金。\" 裁判结果（据转述） ： 江门中院二审认定相关约定属免除保险人责任条款，保险公司未能举证履行提示说明义务，条款不生效，判令支付 18 万元保险金。同所文章另列 (2024) 粤 07 民终 2935 号（谢某财案，保险经纪人告知不足、保单无投保人盖章，提示说明义务未履行，判 86814.24 元）——均 C 级待核验。 对我的用处 / 注意 ： C 级，仅作线索。补充案例 12 的\"骑手职伤双赔\"攻防：即便条款被认定有效，\"未提示说明\"亦可使其不生效。注意\"保险经纪人代告知\"不当然视为对投保人履行说明义务（须有授权）。正式引用前须核到 (2024) 粤 07 民终 4851 号 / 2935 号原文。 关联法条 ：《保险法》第十七条第二款；保险经纪人相关规则。 检索缺口 以下问题类型本次未检索到可用的广东法院原文（B 级）或仅有线索（C 级），建议后续补强： 1. 伤残评定标准之争（人身保险伤残评定标准 vs 工伤标准 / 人体损伤致残程度分级） ：仅检索到标准文本（JR/T 0083—2013 及 GB/T 44893 2024），未找到广东法院就\"意外险伤残等级应按哪种标准评定\"作出裁判的可用案例。本库案例 1（连州骑手猝死）涉及伤残但为死亡赔付，未触及评定标准冲突。 2. 高风险运动 / 探险免责 ：同方全球\"臻爱 2022\"等互联网定寿将赛车、攀岩、潜水等列为危险活动询问项，但未检索到广东法院就\"高风险运动免责条款提示说明\"作出裁判的原文。 3. 自杀条款 / 两年不可抗辩条款 ：未检索到广东法院就《保险法》第四十四条（自杀免责，但合同成立满二年除外）作出裁判的可用案例；案例 8 涉及的\"附加猝死责任\"产品含自杀免责但非本案焦点。 4. 微信（微保）渠道专属案例 ：本次互联网板块以支付宝 / 蚂蚁保、外卖平台、网上保险公司为主；微信\"微保\"渠道仅见外地法院案例（江西武宁法院微医保、成都青羊法院微医保重疾险）及一份无公开 URL 的江门新会法院\"微保\"定期寿险案（孙某丙案，C 级且 URL 未检索到，故未收录），建议后续补检索广东法院\"微保\"裁判文书。 5. 可回溯管理专门裁判 ：本次案例多从\"提示说明义务\"角度切入，但未检索到以\"互联网保险可回溯管理\"为独立争议焦点的广东法院原文。 6. 平台责任（蚂蚁保 / 支付宝）与保险人责任区分的终审定性 ：案例 10（黄埔）明确平台合规漏洞，但免责条款无效的核心归责仍在保险人；未检索到就\"平台（代理方）独立赔偿责任\"作出终局认定的广东法院原文。"}, {"id": "L2-案例库/广东案例-车险与财产险", "group": "3 · 广东案例库", "groupKey": "L2-案例库", "title": "车险 / 财产险 / 责任险 · 案例库（广东）", "order": 3, "file": "广东案例-车险与财产险.md", "html": "<h1 id=\"s0\">车险 / 财产险 / 责任险 · 案例库（广东）</h1>\n<blockquote>采集日期：2026-09-16 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手来源待核验<br>B 级 = 法院官方 / 官媒来源；C 级 = 二手来源，待核验，不得直接引用为裁判要旨。<br>说明：本库仅收录检索中实际看到的案号、法院、原文摘录；案号未披露的，标注「未披露（来源未刊载）」，不作推测。</blockquote>\n<hr>\n<h2 id=\"s1\">一、机动车辆保险</h2>\n<h3 id=\"s2\">案例 1：顺风车高频率接单，被认定改变使用性质、危险程度显著增加（拒赔）</h3>\n<ul>\n<li><strong>案号</strong>：一审（2024）粤5102民初471号；二审（2024）粤51民终873号</li>\n<li><strong>审理法院 / 审级</strong>：广东省潮州市中级人民法院（二审）</li>\n<li><strong>裁判日期</strong>：一审 2024-09-10；二审 2024-11-12</li>\n<li><strong>来源 URL</strong>：http://czcourt.gov.cn/detail/4629</li>\n<li><strong>可信度</strong>：B（潮州市中级人民法院官网「潮州法院2024年度十佳案例」）</li>\n<li><strong>关键词标签</strong>：#顺风车 #改变使用性质 #危险程度显著增加 #保险法第52条 #拒赔</li>\n</ul>\n<p><strong>基本事实</strong>： 张某为其小型客车以非营运性质投保交强险及商业险。2023年其在「哈啰出行」平台出行 1.3 万公里、179 天、接单 325 次；在「嘀嗒出行」接单 1228 次。2023-10-19 事故中，张某负主要责任，车辆损失预估 58399 元，保险公司定损 33000 元。保险公司以「非营运投保后实际从事客运营运、危险程度显著增加且未通知」为由拒赔车损险。</p>\n<p><strong>争议焦点</strong>： 从事网约顺风车业务是否构成改变车辆使用性质、显著增加保险标的危险程度。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>裁判要旨：认定从事网约顺风车业务是否属于改变车辆使用性质，显著增加保险标的的危险程度，应围绕车主是否具有分摊运输成本的主观意图及具有明确的客观出行需求，综合考虑车主接单时间段、行程范围、乘客与车主出行路线的匹配度、收取的费用、事发前及事发时的使用情况、出行信息发布频次或单数是否合理等因素审查判断。<br>相关法条：《中华人民共和国保险法》第五十二条；《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（四）》第四条第一款。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 法院以「接单频率、行程范围、路线匹配度、收费」综合审查，高频次（年接单逾 1500 次）被认定实质营运。可用于反驳保险公司「凡顺风车即拒赔」，也提示车主：低频、路线固定、分摊成本才是安全区。</p>\n<p><strong>关联法条</strong>：《保险法》第 52 条；《保险法司法解释（四）》第 4 条。</p>\n<hr>\n<h3 id=\"s3\">案例 2：非营运车跑「货拉拉」接单 100 次，商业三者险免赔（仅交强险赔）</h3>\n<ul>\n<li><strong>案号</strong>：未披露（一审丰顺县人民法院；二审梅州市中级人民法院维持）</li>\n<li><strong>审理法院 / 审级</strong>：广东省梅州市中级人民法院（二审，维持原判）</li>\n<li><strong>裁判日期</strong>：未检索到（南方+ 刊载于 2025-03-30，来源广东省高级人民法院）</li>\n<li><strong>来源 URL</strong>：https://static.nfnews.com/content/202503/30/c11135381.html?enterColumnId=13601</li>\n<li><strong>可信度</strong>：B（广东高院通过「南方+」发布，汕头政法供稿）</li>\n<li><strong>关键词标签</strong>：#货拉拉 #非营运货运 #改变使用性质 #商业三者险免赔 #提示义务</li>\n</ul>\n<p><strong>基本事实</strong>： 2023-01，张某驾驶轻型栏板货车撞死行人金某，全责。该车投保交强险及 100 万商业三者险，保单注明使用性质「非营业货运」，但平时在「货拉拉」接单，自 2022-10 至事发接单达 100 次、车身贴「货拉拉APP」标识。金某家属诉请赔偿。</p>\n<p><strong>争议焦点</strong>： 以非营运性质投保的车辆在营运中出险，保险公司应否在商业三者险范围内赔偿。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>丰顺县人民法院一审认为，案涉车辆在投保时登记为「非营业货运」的情况下从事营运活动，提高了车辆使用频率和扩大了车辆使用范围，造成车辆使用频率与事故风险显著增加，又未向保险人履行法定通知义务，故某保险公司依法在商业第三者责任险限额内免除赔偿责任。判决某保险公司赔偿金某家人 18.71 万元，张某赔偿 100.25 万元。<br>梅州市中级人民法院二审认为，张某使用案涉车辆在货拉拉平台注册认证，从 2022 年 10 月起至事故发生日期间共接单达 100 次，且车身明显张贴有「货拉拉 APP」标识……案涉保单载明的条款内容和形式显示某保险公司就法定免责事由履行了提示义务，应认定免责条款发生法律效力。根据合同约定，一审判决某保险公司仅在交强险范围内承担赔偿责任并无不当，故二审维持原判。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 「非营业货运」≠ 可随意接单营运；高频接单 + 平台标识 + 未通知 = 危险程度显著增加 + 免责条款生效。提示：营运车必须按营运性质投保，否则三者险可能落空。</p>\n<p><strong>关联法条</strong>：《保险法》第 52 条（危险程度增加通知义务）；第 17 条（免责条款提示说明）。</p>\n<hr>\n<h3 id=\"s4\">案例 3：私家车注册网约车接单，按比例赔付保险金（条款约定「变更性质未通知按保费比例赔」）</h3>\n<ul>\n<li><strong>案号</strong>：未披露（一审佛山市顺德区人民法院；二审维持）</li>\n<li><strong>审理法院 / 审级</strong>：佛山市顺德区人民法院一审，佛山中院二审维持</li>\n<li><strong>裁判日期</strong>：未检索到（佛山中院官网刊载）</li>\n<li><strong>来源 URL</strong>：https://www.fszjfy.gov.cn/xwzx/mtjj/content/post_1001606.html</li>\n<li><strong>可信度</strong>：B（佛山市中级人民法院官网「法院+金融」典型案例）</li>\n<li><strong>关键词标签</strong>：#网约车 #非营运变更营运 #保费比例赔付 #格式条款</li>\n</ul>\n<p><strong>基本事实</strong>： 刘某以家庭自用汽车投保并按非营运性质交费，保险期间在某网约车平台注册司机账户接单，变更车辆为营运性质且未通知保险人。出险后保险公司主张减免赔偿。</p>\n<p><strong>争议焦点</strong>： 保险条款约定「非营运变更营运未通知，按非营运与营运应收保费比例计算给付」，该约定能否适用。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>佛山市顺德区人民法院生效判决认为，保险公司是保险规则的制定者，保险条款第 3.4 条约定可视为保险人在法律规定情形外对车辆非营运性质改变为营运性质，且被保险人未作出通知时自愿给付约定比例保险金的意思表示，该意思表示未违反法律强制性规定，合法有效。张某以家庭自用汽车向某保险公司投保，并按非营运汽车性质交付保险费，但保险期间，却在某网约车平台注册司机账户接单，变更车辆为营运性质，且未通知保险人。该情形可适用保险条款第 3.4 条约定。故根据非营运性质与营运性质车辆应收保费比例，结合某保险公司确认的基准费率，判决保险公司向刘某支付保险金。二审法院予以维持。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 并非所有「改变性质」都全免——若条款明确保留「按比例赔付」，法院支持按比例赔而非拒赔。投保时务必核对保单有无类似第 3.4 条约定，主张按比例理赔。</p>\n<p><strong>关联法条</strong>：《保险法》第 52 条；《民法典》格式条款效力规则。</p>\n<hr>\n<h3 id=\"s5\">案例 4：顺风车频率不高、路线固定，不属于营运，三者险应予赔偿</h3>\n<ul>\n<li><strong>案号</strong>：未披露（一审未刊载；二审广东省揭阳市中级人民法院，改判）</li>\n<li><strong>审理法院 / 审级</strong>：广东省揭阳市中级人民法院（二审，改判）</li>\n<li><strong>裁判日期</strong>：未检索到（揭阳中院官网刊载于 2026-04-22）</li>\n<li><strong>来源 URL</strong>：http://www.gdjyfy.gov.cn/jyzycourt/web/content?gid=399179&amp;lmdm=1050</li>\n<li><strong>可信度</strong>：B（揭阳市中级人民法院官网「法庭内外」）</li>\n<li><strong>关键词标签</strong>：#顺风车 #低频接单 #路线固定 #三者险赔偿 #善意反例</li>\n</ul>\n<p><strong>基本事实</strong>： 郭某驾驶私家车从深圳返普宁，出发前通过顺风车平台接单搭载同路线乘客，途中撞伤行人温某，郭某全责。车辆投保交强险及三者险。一审判保险公司在交强险内赔近 12 万、郭某赔 3 万余；郭某上诉。</p>\n<p><strong>争议焦点</strong>： 接单顺风车是否改变车辆使用性质、致危险程度显著增加。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>揭阳中院二审查明，保险期间该车累计接单顺风车数十单，路线主要往返于郭某工作地与户籍地普宁市及周边城市，郭某自身有其他稳定工作收入。<br>揭阳中院审理认为，郭某接单顺风车频率不高，路线较为固定，且郭某自身有其他工作收入，能体现出郭某目的在于分摊出行成本而非营运，未实质上改变车辆的使用性质，不会导致车辆危险程度增加，故保险公司仍应在三者险范围内承担赔偿责任。法院遂改判保险公司赔偿温某 15 万余元。<br>【法官说法】区分顺风车和营运，应结合驾驶人职业状况、接单频率、行驶路线、收费情况等多重因素综合判断……郭某有稳定工作收入，接单频率处于合理区间，顺风车接单路线相对固定，接单行为未形成持续性、规模化运输服务，符合顺风车「顺路合乘、成本分摊」的本质特征，不属于营运行为。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 与案例 1 形成对照：低频、路线固定、有稳定工作 = 顺风车不被认定营运，三者险照赔。维权时重点收集「接单频率 / 路线 / 工作收入」证据。</p>\n<p><strong>关联法条</strong>：《保险法》第 52 条。</p>\n<hr>\n<h3 id=\"s6\">案例 5：肇事逃逸，商业险免责条款因未交付、未提示而不生效（交强险+商业险均赔）</h3>\n<ul>\n<li><strong>案号</strong>：未披露（刑事附带民事，深圳市坪山区人民法院审理）</li>\n<li><strong>审理法院 / 审级</strong>：深圳市坪山区人民法院（一审，已生效）</li>\n<li><strong>裁判日期</strong>：未检索到（坪山法院官网刊载）</li>\n<li><strong>来源 URL</strong>：https://szpsfy.gov.cn/pfkx/index_81.html</li>\n<li><strong>可信度</strong>：B（深圳市坪山区人民法院官网「普法课堂」）</li>\n<li><strong>关键词标签</strong>：#肇事逃逸 #免责条款无效 #未提示说明 #交强险+商业险</li>\n</ul>\n<p><strong>基本事实</strong>： 牟某、叶某分别驾车碰撞行人刘某后均逃逸，刘某当场死亡。两车均在 A、B 两家保险公司投保交强险和 100 万商业三者险（不计免赔）。家属诉请赔偿，两保险公司以「逃逸属免责条款」拒赔商业险。</p>\n<p><strong>争议焦点</strong>： 逃逸情形下商业三者险免责条款是否生效。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>坪山法院经审理认为，A 保险公司虽然提供了车辆保险单以及机动车综合商业保险示范条款，但该保险单以及保险条款均无投保人的签名，保险单中亦无列举保险条款中免责条款的内容。B 保险公司虽然提供了车辆保险单以及机动车综合商业保险条款，但仅有保险单上有投保人的签名，而保险条款中并无投保人的签名，且保险单中并未列举保险条款中免责条款的内容。即现有证据不能证明 A、B 两家保险公司已经将上述商业保险条款交付给了投保人，以及就商业保险条款中的免责事项告知了投保人……综上，本案中 A、B 两家保险公司主张的商业保险条款中的免责条款不产生效力。依照相关法律规定，坪山法院判决 A、B 两家保险公司在交强险和商业三者险范围内承担相应的赔偿责任。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 逃逸≠必然商业险免赔。关键在保险公司能否证明「交付条款 + 提示说明」。若保单/条款无投保人签名、未列明免责内容，免责条款不生效，商业险仍赔。逃逸情形应重点攻「提示说明义务」瑕疵。</p>\n<p><strong>关联法条</strong>：《保险法》第 17 条第 2 款（免责条款提示说明）；《民法典》相关侵权责任规定。</p>\n<hr>\n<h3 id=\"s7\">案例 6：有偿代驾肇事，保险人赔付后向代驾平台代位求偿（最高法涉互联网典型案例）</h3>\n<ul>\n<li><strong>案号</strong>：一审（2016）粤0103民初5327号；二审（2017）粤01民终13837号</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院（二审）</li>\n<li><strong>裁判日期</strong>：二审 2017-10-11</li>\n<li><strong>来源 URL</strong>：https://www.ssfb86.com/index/News/detail/newsid/10155.html （转引自最高人民法院发布第一批涉互联网典型案例，2018-08-16）</li>\n<li><strong>可信度</strong>：B（最高人民法院发布典型案例，第三方网站转引；核心内容为最高法发布）</li>\n<li><strong>关键词标签</strong>：#代位求偿 #有偿代驾 #e代驾 #车损险 #第三者</li>\n</ul>\n<p><strong>基本事实</strong>： 王司政饮酒不能驾驶，通过「e代驾」平台指派吴春田提供有偿代驾；代驾中吴春田全责出险。平安保险公司定损并赔付被保险人 159194 元后，向吴春田及平台公司亿心公司追偿。</p>\n<p><strong>争议焦点</strong>： 有偿代驾人能否成为车损险被保险人；保险人赔付后能否代位求偿。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>广州市中级人民法院于 2017 年 10 月 11 日作出（2017）粤01民终13837号民事判决：一、撤销广州市荔湾区人民法院（2016）粤0103民初5327号民事判决第二项；二、变更第一项为：北京亿心宜行汽车技术开发服务有限公司于判决发生法律效力之日起十日内向中国平安财产保险股份有限公司广东分公司支付赔偿款 124834 元；三、驳回中国平安财产保险股份有限公司广东分公司的其他诉讼请求。<br>典型意义：不同于日常生活中亲朋借车或友情代驾行为，本案中代驾人系有偿提供代驾服务，并非为被保险人利益所为，对保险标的车辆也不存在占有利益，因此代驾人不能成为涉案保险合同的被保险人。代驾人作为第三人在提供有偿服务过程中造成投保车辆受损并负全责，对被保险人的财产构成侵权，被保险人有权请求赔偿，保险公司亦可代位行使求偿权。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 代驾肇事，车损险先赔车主，再代位向「有偿代驾平台/司机」追偿（友情代驾则不同）。提示车主：代驾场景下保险仍保自己车，但追偿对象是有偿代驾方。</p>\n<p><strong>关联法条</strong>：《保险法》第 60 条（代位求偿权）。</p>\n<hr>\n<h3 id=\"s8\">案例 7：旧车按新车价投保、出险按实际价值赔——「高保低赔」的司法立场（法院调研）</h3>\n<ul>\n<li><strong>案号</strong>：未披露（韶关市武江区人民法院调研，文中提及 2015 年上半年受理同类案件 3 件，均按保险法支持按实际价值理赔）</li>\n<li><strong>审理法院 / 审级</strong>：韶关市武江区人民法院（调研文章，非单一编号判决）</li>\n<li><strong>裁判日期</strong>：未检索到（武江法院官网刊载）</li>\n<li><strong>来源 URL</strong>：https://sgwjfy.gov.cn/web/content?gid=493</li>\n<li><strong>可信度</strong>：B（韶关市武江区法院官网调研「机动车高保低赔现象亟需引起重视」）</li>\n<li><strong>关键词标签</strong>：#高保低赔 #旧车投保 #实际价值 #损失补偿原则</li>\n</ul>\n<p><strong>基本事实</strong>： 武江法院调研指出：受损车辆均按新车购置价投保车损险，出险时保险公司以维修费超出实际价值为由仅按实际价值理赔，法院根据保险法支持保险公司主张（车主不满）。</p>\n<p><strong>争议焦点</strong>： 「高保低赔」（按新车价收保费、按折旧后实际价值赔）是否合理。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>发生保险事故，按车辆实际价值理赔，符合保险法的损失补偿原则，按新车价格投保多交的保费，属于超额保险，超额部分无效，保险公司多收保费的现象，应当引起重视。2015 年上半年，武江区法院共受理此类案件 3 件，受损车辆均按新车购置价投保车辆损失险，但发生保险事故时，保险公司均以维修费用超出了实际价值为由，仅同意按实际价值理赔，法院根据保险法的规定，支持保险公司的主张。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 法院立场：旧车投保超额部分无效，全损时按实际价值赔（损失补偿原则）。但提示：2017 年广东商车改革后「实保实赔」，保额按实际价值确定，「高保低赔」在制度层面已弱化；2012 版示范条款后多地判「高保」条款为免责条款需提示说明。本案中法院支持保险人，与部分外地判决相反，需向客户说明地域/时间差异。</p>\n<p><strong>关联法条</strong>：《保险法》第 55 条第 3 款（超额保险无效）；第 23 条。</p>\n<hr>\n<h3 id=\"s9\">案例 8：新能源汽车充电时电瓶起火，保险公司以「故障」拒赔被驳回（认定属自燃）</h3>\n<ul>\n<li><strong>案号</strong>：未披露（深圳中院罗湖法院审理，来源广东高院「法官说法」案例）</li>\n<li><strong>审理法院 / 审级</strong>：深圳市罗湖区人民法院（一审，来源广东省高级人民法院转发）</li>\n<li><strong>裁判日期</strong>：未检索到（南方+ 刊载于 2023-11-24，来源广东省高级人民法院）</li>\n<li><strong>来源 URL</strong>：https://static.nfapp.southcn.com/content/202311/24/c8333291.html?enterColumnId=2138</li>\n<li><strong>可信度</strong>：B（广东省高级人民法院通过南方+发布，深圳中院罗湖法院审理）</li>\n<li><strong>关键词标签</strong>：#新能源汽车 #充电自燃 #格式条款不利解释 #专属条款</li>\n</ul>\n<p><strong>基本事实</strong>： 2020 年某公司购新能源车办公。2021-05 车辆在停车场充电时电瓶起火全毁。消防认定「充电过程中由电瓶引发火灾」。公司主张自燃理赔 7 万余元；保险公司称电瓶自身故障属免赔。</p>\n<p><strong>争议焦点</strong>： 充电起火属「自燃」还是「故障」。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>事故发生时，原告对案涉车辆进行充电，属于车辆使用状态，起火的原因为车辆储能装置发生故障，而非电瓶丧失功能；同时，案涉车辆不存在非法改装、私改线路、增加外部火源的客观情况，故认定车辆电瓶未散失功能。被告主张起火原因系电瓶本身故障，属于免赔范畴，但未举证对「电瓶故障」作进一步解释说明，法院依法对被告作出不利解释。<br>综上，法院认定事故原因为自燃，属于保险责任的范畴，依法判决被告应向原告支付理赔款 7 万余元。<br>【法官说法】2021 年 12 月 14 日，中国保险行业协会公布的《中国保险行业协会新能源汽车商业保险专属条款（试行）》显示，新能源汽车的自燃属于保险责任范围。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 新能源车充电起火，若保险公司主张「故障」免赔却未作明确解释说明，法院作不利解释、认定属自燃赔付。结合新能源专属条款，自燃在保障范围内。维权要点：要求保险公司对「故障」免责作具体说明并举证。</p>\n<p><strong>关联法条</strong>：《保险法》第 30 条（格式条款不利解释）；《民法典》第 496、498 条；《新能源商业保险专属条款（试行）》。</p>\n<hr>\n<h2 id=\"s10\">二、财产保险 / 家财险 / 责任险 / 新型险种</h2>\n<h3 id=\"s11\">案例 9：雇主责任险「空白投保单」隐瞒差额赔付条款，保险公司拒赔被驳回</h3>\n<ul>\n<li><strong>案号</strong>：未披露（广州市中级人民法院生效判决，载广东高院第二批典型案例）</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院（二审）</li>\n<li><strong>裁判日期</strong>：未检索到（广东高院 2025-10-09 发布）</li>\n<li><strong>来源 URL</strong>：https://www.gdcourts.gov.cn/gsxx/quanweifabu/anlihuicui/content/post_1843544.html</li>\n<li><strong>可信度</strong>：B（广东省高级人民法院官网「服务保障民营经济高质量发展典型案例」）</li>\n<li><strong>关键词标签</strong>：#雇主责任险 #空白投保单 #未提示说明 #差额赔付 #免责无效</li>\n</ul>\n<p><strong>基本事实</strong>： 某物流公司（小微民企）投保雇主责任险，保险公司仅提供空白《投保单》要求盖章，未提供《保险条款》；投保单载明雇员死亡责任限额 50 万、未载明免赔范围。缴费后保险公司才邮寄条款，载明「如有工伤保险，保险人仅承担差额责任」。后雇员因工死亡，物流公司赔家属 50 万后索赔，保险公司以工伤已赔为由拒付。</p>\n<p><strong>争议焦点</strong>： 投保单与保险条款不一致时，免责「差额赔付」条款是否生效。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>广州市中级人民法院生效判决认为，物流公司确认投保时，保险公司未提供《保险条款》并对赔付范围进行提示说明。缴费后，保险公司提供的《保险条款》内容与《投保单》不一致，且在保险事故发生后亦未提示说明赔付范围，应以投保单为准确定双方权利义务。保险公司在物流公司实际赔付 50 万元后才主张物流公司无须在工伤保险之外承担责任并以此拒赔，属于不当免除自身责任，于法无据，判决保险公司支付保险金 50 万元。<br>典型意义：保险公司应当客观介绍雇主责任险赔付范围，不得故意隐瞒其仅在工伤保险之外承担差额赔偿责任等免责条款诱导投保……企业据此向雇员先行赔付的，保险公司应承担保险责任。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 投保单未载免赔、条款后补且不一致 → 以投保单为准，免责不生效。企业投保雇主责任险务必同步拿到条款、要求书面说明「差额赔付」等关键免责。</p>\n<p><strong>关联法条</strong>：《保险法》第 17 条；《保险法司法解释（二）》第 14 条（投保单与保险单不一致以投保单为准）。</p>\n<hr>\n<h3 id=\"s12\">案例 10：雇员死亡后补办批改，雇主责任险仍赔 50 万</h3>\n<ul>\n<li><strong>案号</strong>：未披露（历经一审、二审，东莞市中级人民法院终审）</li>\n<li><strong>审理法院 / 审级</strong>：广东省东莞市中级人民法院（终审）</li>\n<li><strong>裁判日期</strong>：未检索到（东莞中院官网刊载）</li>\n<li><strong>来源 URL</strong>：https://www.dgcourt.gov.cn/News/Show.asp?id=5027</li>\n<li><strong>可信度</strong>：B（东莞市中级人民法院官网）</li>\n<li><strong>关键词标签</strong>：#雇主责任险 #新增雇员批改 #生效日 #射幸合同</li>\n</ul>\n<p><strong>基本事实</strong>： 劳务派遣公司雇员小黄工作中死亡。公司申请将小黄加入保险名单时间晚于其死亡时间。保险公司以「死亡时不在保险期内、保单不成立」拒赔；公司主张按特别约定新员工生效日以入职日为准、且已在约定期限内报批。</p>\n<p><strong>争议焦点</strong>： 死亡后批改新增雇员，雇主责任险合同是否成立、应否赔付。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>法院认为，劳务派遣公司在保险条款约定期限内履行了报批手续，且没有证据证明小黄的死亡与工作无关，因此保险公司应承担保险责任。劳务派遣公司在提交新增员工名单时虽然小黄已经死亡，但依照约定因保险对新员工的生效时间均是从新员工入职当天开始，因此保险仍对小黄生效。劳务派遣公司在增加员工名单时没有如实向保险公司告知实情有不妥，但保险公司作为保险合同的制定方，当出现不可预见的情形时，应当由保险公司承担不利后果。东莞市中级人民法院终审认定双方的保险合同成立，依法判令保险公司向劳务派遣公司赔偿 50 万元。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 保单特别约定「新员工生效日=入职日」优先；在约定期限内报批即受保障。用人单位应及时沟通批改，保险公司不得以「未实时告知」一刀切拒赔。</p>\n<p><strong>关联法条</strong>：保险合同特别约定优先；不利解释规则。</p>\n<hr>\n<h3 id=\"s13\">案例 11：燃气热水器产品缺陷致死亡，产品责任险优先赔付（每人伤亡限额内）</h3>\n<ul>\n<li><strong>案号</strong>：未披露（丰顺县人民法院 2018-10-29 一审判决；载司法部案例库）</li>\n<li><strong>审理法院 / 审级</strong>：广东省丰顺县人民法院（一审）</li>\n<li><strong>裁判日期</strong>：2018-10-29</li>\n<li><strong>来源 URL</strong>：https://alk.12348.gov.cn/Detail?dbID=46&amp;dbName=FYGL&amp;sysID=15372</li>\n<li><strong>可信度</strong>：B（司法部司法行政（法律服务）案例库，丰顺县法律援助处案例）</li>\n<li><strong>关键词标签</strong>：#产品责任险 #产品缺陷 #燃气热水器 #每人伤亡限额 #连带责任</li>\n</ul>\n<p><strong>基本事实</strong>： 张某某使用缺陷燃气热水器一氧化碳中毒死亡。生产者中山某公司（投保永诚财保顺德支公司产品责任险，每次事故每人伤亡限额 10 万）、销售者、安装人蔡某按过错分担责任。</p>\n<p><strong>争议焦点</strong>： 产品责任险在缺陷产品致害赔偿中的赔付顺序与限额。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>合议庭结合原、被告和第三人提供的证据，确定原告损失合计 1721776.77 元，被告中山某公司为其公司生产的热水器系列产品在永诚财保顺德某支公司投保了每次事故每人伤亡限额为 100000 元的产品责任险，故被告永诚财保顺德某支公司应优先赔偿原告 100000 元，剩余 1621776.77 元，由原告自负 30% 即 486533.03 元，剩余 1135243.74 元由被告中山某公司和蔡某各承担 567621.87 元，并互负连带赔偿责任，被告兴宁某家电配件部承担连带责任。<br>2018 年 10 月 29 日，丰顺县人民法院作出一审判决，被告永诚财保某支公司赔偿两原告 100000 元……</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 产品责任险在「每次事故每人伤亡限额」内优先赔付，不足部分再由生产者/销售者/过错方按份或连带承担。提示企业：产品责任险保额有限，须关注「每次事故/每人」限额是否覆盖风险。</p>\n<p><strong>关联法条</strong>：《产品质量法》第 41、43 条；《保险法》第 65 条（责任保险直接赔付第三者）。</p>\n<hr>\n<h3 id=\"s14\">案例 12：无合法产权证的自建房投保家财险，洪灾受损仍获赔</h3>\n<ul>\n<li><strong>案号</strong>：一审（2023）粤0222民初734号；二审维持（案号未披露）</li>\n<li><strong>审理法院 / 审级</strong>：广东省始兴县人民法院（一审），韶关中院二审维持</li>\n<li><strong>裁判日期</strong>：一审 2023-10-30</li>\n<li><strong>来源 URL</strong>：https://sgmsw.cn/v/info?id=124689 （来源：韶关市中级人民法院）</li>\n<li><strong>可信度</strong>：B（韶关新闻网，来源韶关市中级人民法院；维基文库另载一审判决书全文 (2023)粤0222民初734号）</li>\n<li><strong>关键词标签</strong>：#家庭财产险 #无产权证 #保险利益 #承保审查义务 #洪灾</li>\n</ul>\n<p><strong>基本事实</strong>： 2022-09 凌某为自建房屋投保「平安逸家·家财宝」家财险（含室内财产损失 20 万）。2023-04 房屋遭洪涝，室内物品被泡。保险公司以「无合法产权证明、不符合承保对象」拒赔；保单特别约定「仅承保被保险人拥有合法产权的居住房屋」。</p>\n<p><strong>争议焦点</strong>： 无产权登记的自建房，投保人是否享有保险利益；保险公司承保后能否以无产权证拒赔。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>始兴法院经审理认为，双方达成的财产保险合同合法有效。首先，投保人是否具备合法产权证明，是保险公司在承保时就应当审查的内容。保险公司未尽审查义务便接受投保，事后无权以此为由拒赔。其次，凌某提交的电费缴交发票、银行流水以及村委会证明，足以证实凌某是该自建房屋的权利人，即便未办理产权登记，也对房屋及屋内财产享有保险利益。最后，凌某提交受灾当日视频可知，房屋内生活用品、家电、家具齐全，符合居住的条件和事实。且灾害发生在保险责任期限内，保险公司理应予以赔偿。最终，法院依法判决被告保险公司赔偿原告凌某室内财产损失 37910 元及鉴定评估费 10000 元。被告不服判决提起上诉，二审判决维持原判。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 承保时未尽审查、仍收保费 → 禁反言，不得以「无产权证」拒赔；事实居住+村委会证明可证保险利益。家财险理赔遇「产权」门槛时，可主张保险公司承保审查义务。</p>\n<p><strong>关联法条</strong>：《保险法》第 12 条（保险利益）；第 64 条（鉴定费由保险人承担）。</p>\n<hr>\n<h3 id=\"s15\">案例 13：物业公司保洁不当致业主摔伤，公众责任险保险人代位求偿获支持</h3>\n<ul>\n<li><strong>案号</strong>：未披露（一审，审判员 罗晔，2023-10-23；维基文库载一审判决书全文）</li>\n<li><strong>审理法院 / 审级</strong>：基层人民法院一审（判决书署名审判员 罗晔，二〇二三年十月二十三日）</li>\n<li><strong>裁判日期</strong>：2023-10-23</li>\n<li><strong>来源 URL</strong>：https://zh.wikisource.org/zh-hans/中国人某财产保险深圳市分公司、广州心某物业管理有限公司保险人代位求偿权纠纷民事一审民事判决书</li>\n<li><strong>可信度</strong>：C（维基文库转录裁判文书，非法院官网首发；仅作线索，裁判要旨待核验）</li>\n<li><strong>关键词标签</strong>：#公众责任险 #物业保洁 #代位求偿 #第三者损害</li>\n</ul>\n<p><strong>基本事实</strong>： 豪某花园小区保洁委托心某物业公司。雷某妹在小区因心某物业不当保洁行为摔倒受伤。人保深圳市分公司承保该小区公众责任险，已在责任限额内赔付 50287.04 元，取得豪某公司《权益转让书》后向心某物业代位求偿。</p>\n<p><strong>争议焦点</strong>： 公众责任险保险人赔付后，能否向有过错的保洁服务方代位求偿。</p>\n<p><strong>裁判理由（原文摘录，转录自维基文库）</strong>：</p>\n<blockquote>人保深圳市分公司系承保了涉案小区的公众责任险，现已在该公众责任险损失险责任限额范围内赔付了 50287.04 元，该公司依法有权代位行使豪某公司对侵权方请求赔偿的权利……心某公司的不当保洁行为导致此事件的发生，因此心某公司为该事件的侵权方，人保深圳市分公司依据豪某公司出具的《权益转让书》，取得向心某公司的代位求偿权。故原告请求被告支付赔偿款 50287.04 元合法有据，本院予以支持。<br>判决如下：一、被告广州心某物业管理有限公司于本判决发生法律效力之日起十日内向原告中国人某财产保险股份有限公司深圳市分公司赔偿 50287.04 元；二、驳回原告其他诉讼请求。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 公众责任险赔付小区第三者损害后，可向实际侵权方（如保洁外包公司）代位追偿。物业企业应注意外包合同中的责任划分。</p>\n<p><strong>关联法条</strong>：《保险法》第 60 条（代位求偿权）。</p>\n<hr>\n<h3 id=\"s16\">案例 14：诉讼保全责任险——保险公司向投保人追偿/主张反担保被驳回（反担保条款无效）</h3>\n<ul>\n<li><strong>案号</strong>：未披露（企业官网「以案说险」案例，来源广东省能源集团）</li>\n<li><strong>审理法院 / 审级</strong>：未披露（载企业普法案例，二审生效）</li>\n<li><strong>裁判日期</strong>：未检索到</li>\n<li><strong>来源 URL</strong>：https://www.geg.com.cn/qywh/yasx/content/post_4263.html</li>\n<li><strong>可信度</strong>：C（广东省能源集团官网普法文章，非法院官网；仅作线索，裁判要旨待核验）</li>\n<li><strong>关键词标签</strong>：#诉讼保全责任险 #追偿 #反担保条款无效 #过错责任</li>\n</ul>\n<p><strong>基本事实</strong>： 张某诉 A 公司建设工程施工合同案中，张某购诉讼保全责任险，B 保险公司出具保函担保，法院查封 A 公司账户。后张某败诉，A 公司诉张某及 B 保险公司保全损害责任，生效判决认定张某未尽审慎注意义务、赔 A 公司利息损失，B 保险公司连带；B 保险公司赔付 29.67 万后，向张某追偿/主张反担保赔偿。</p>\n<p><strong>争议焦点</strong>： 诉责险保险公司赔付后，能否向投保人追偿或依保证条款/承诺函主张反担保赔偿。</p>\n<p><strong>裁判理由（原文摘录，转述自企业普法文章）</strong>：</p>\n<blockquote>法院审理认为：B 保险公司以张某存在重大过失未履行如实告知义务拒绝赔偿诉讼保全责任险保险金的意见不能成立。该义务对应的是 B 保险公司的合同解除权，现 B 保险公司既未在法律规定的合同解除权行使期间内主张解除保险合同，又未举证证明存在其他保险除外责任情形，故而保险合同仍然成立并有效，B 保险公司应当按照保险合同的约定向张某履行赔偿义务……B 保险公司依据保证条款要求投保人对诉讼保全责任险中 B 保险公司的赔偿责任提供反担保，改变了责任保险不能向被保险人进行追偿的性质，应属无效条款。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 诉责险本质为责任保险，保险公司赔付被申请人损失后，一般不能向投保人/被保险人追偿；要求反担保的条款因改变责任险性质而无效。投保人遇保险公司「代位/追偿」主张时可据此抗辩。</p>\n<p><strong>关联法条</strong>：《民事诉讼法》第 108 条（保全错误赔偿）；《保险法》第 65 条（责任保险）；过错责任原则。</p>\n<hr>\n<h3 id=\"s17\">案例 15：锂电池产品责任险——充电起火致损，保险公司按限额减免赔率赔付</h3>\n<ul>\n<li><strong>案号</strong>：未披露（白云法院一审；广州中院二审维持，载羊城晚报）</li>\n<li><strong>审理法院 / 审级</strong>：广州市白云区人民法院一审，广州中院二审维持</li>\n<li><strong>裁判日期</strong>：未检索到（羊城晚报 2021-08-04 刊载）</li>\n<li><strong>来源 URL</strong>：https://ep.ycwb.com/epaper/ycwb/html/2021-08/04/content_118_414996.htm</li>\n<li><strong>可信度</strong>：C（羊城晚报记者报道，转述判决；仅作线索，裁判要旨待核验）</li>\n<li><strong>关键词标签</strong>：#产品责任险 #锂电池 #免赔率 #财产损失限额 #二审维持</li>\n</ul>\n<p><strong>基本事实</strong>： 动某公司售电动车锂电池，2020-12 一锂电池充电起火致菲某公司财产损失 130 万余元。动某公司已投保产品责任险（每次事故财产损失限额 800 万）。消防/法院认定动某公司承担 80% 责任（菲某未二次消防验收等自担 20%）。</p>\n<p><strong>争议焦点</strong>： 产品责任险在锂电池缺陷致他人财产损害时的赔付计算。</p>\n<p><strong>裁判理由（原文摘录，转述自报道）</strong>：</p>\n<blockquote>因动某公司已向保险公司投保产品责任险，每次事故财产损失限额 800 万元，因保险公司的免赔率为 10% 即 104406.4 元，故保险公司实际应赔偿 93 万余元，由动某公司赔偿 10 万余元。白云法院一审判决：保险公司在产品责任保险财产损失限额内赔偿菲某公司财产损失 93 万余元；动某公司赔偿菲某公司财产损失 10 万余元。菲某公司上诉后，广州中院二审维持原判。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 产品责任险按「责任比例 × 损失 − 免赔率」在限额内赔付，余额由被保险人自担。提示：投保时关注免赔率与限额是否足额；缺陷产品致第三人损害时，险企依约赔、生产者补差。</p>\n<p><strong>关联法条</strong>：《保险法》第 65 条；《产品质量法》第 41、43 条。</p>\n<hr>\n<h2 id=\"s18\">检索缺口</h2>\n<p>以下争议类型本次未检索到广东辖区、且来源可信（B 级）的明确案例，列为后续补强方向：</p>\n<ol>\n<li><strong>无证驾驶 / 醉酒驾驶拒赔的商业三者险纠纷（广东具体案号）</strong>：检索到深圳坪山「逃逸免责无效」案（案例 5），但「酒驾/醉驾」免责的广东具体判决未见官方刊载，仅有外地/律所转述，未收录。</li>\n<li><strong>车辆未年检 / 未按规定检验拒赔</strong>：未检索到广东法院官方典型案例，仅有保险条款层面的讨论。</li>\n<li><strong>不计免赔率条款效力争议</strong>：本批案例多涉及免责/免赔，但专门就「不计免赔率」条款争议（如未投保不计免赔如何扣减）的广东判决未单独检索到。</li>\n<li><strong>代位求偿中「被保险人与家庭成员」限制（保险法第 62 条）的广东案例</strong>：检索到代驾、逃逸等代位求偿案，但家庭成员/组成人员限制的广东判例未检索到。</li>\n<li><strong>新能源汽车「外部电网故障损失险」「自用充电桩责任险」理赔争议</strong>：仅检索到专属条款出台新闻与充电自燃案例，具体充电桩附加险理赔诉讼未见广东判决。</li>\n<li><strong>宠物险 / 其他新型险种（如试管婴儿险、网络账户安全险）的广东纠纷</strong>：未检索到广东辖区司法案例。</li>\n<li><strong>公众责任险中「绝对免赔额/免赔率」条款争议的具体广东判决</strong>：案例 13 仅见代位求偿，免赔额抗辩的广东判决未单独检索到。</li>\n</ol>", "toc": [{"id": "s1", "lv": 2, "t": "一、机动车辆保险"}, {"id": "s2", "lv": 3, "t": "案例 1：顺风车高频率接单，被认定改变使用性质、危险程度显著增加（拒赔）"}, {"id": "s3", "lv": 3, "t": "案例 2：非营运车跑「货拉拉」接单 100 次，商业三者险免赔（仅交强险赔）"}, {"id": "s4", "lv": 3, "t": "案例 3：私家车注册网约车接单，按比例赔付保险金（条款约定「变更性质未通知按保费比例赔」）"}, {"id": "s5", "lv": 3, "t": "案例 4：顺风车频率不高、路线固定，不属于营运，三者险应予赔偿"}, {"id": "s6", "lv": 3, "t": "案例 5：肇事逃逸，商业险免责条款因未交付、未提示而不生效（交强险+商业险均赔）"}, {"id": "s7", "lv": 3, "t": "案例 6：有偿代驾肇事，保险人赔付后向代驾平台代位求偿（最高法涉互联网典型案例）"}, {"id": "s8", "lv": 3, "t": "案例 7：旧车按新车价投保、出险按实际价值赔——「高保低赔」的司法立场（法院调研）"}, {"id": "s9", "lv": 3, "t": "案例 8：新能源汽车充电时电瓶起火，保险公司以「故障」拒赔被驳回（认定属自燃）"}, {"id": "s10", "lv": 2, "t": "二、财产保险 / 家财险 / 责任险 / 新型险种"}, {"id": "s11", "lv": 3, "t": "案例 9：雇主责任险「空白投保单」隐瞒差额赔付条款，保险公司拒赔被驳回"}, {"id": "s12", "lv": 3, "t": "案例 10：雇员死亡后补办批改，雇主责任险仍赔 50 万"}, {"id": "s13", "lv": 3, "t": "案例 11：燃气热水器产品缺陷致死亡，产品责任险优先赔付（每人伤亡限额内）"}, {"id": "s14", "lv": 3, "t": "案例 12：无合法产权证的自建房投保家财险，洪灾受损仍获赔"}, {"id": "s15", "lv": 3, "t": "案例 13：物业公司保洁不当致业主摔伤，公众责任险保险人代位求偿获支持"}, {"id": "s16", "lv": 3, "t": "案例 14：诉讼保全责任险——保险公司向投保人追偿/主张反担保被驳回（反担保条款无效）"}, {"id": "s17", "lv": 3, "t": "案例 15：锂电池产品责任险——充电起火致损，保险公司按限额减免赔率赔付"}, {"id": "s18", "lv": 2, "t": "检索缺口"}], "text": "车险 / 财产险 / 责任险 · 案例库（广东） 采集日期：2026 09 16 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手来源待核验 B 级 = 法院官方 / 官媒来源；C 级 = 二手来源，待核验，不得直接引用为裁判要旨。 说明：本库仅收录检索中实际看到的案号、法院、原文摘录；案号未披露的，标注「未披露（来源未刊载）」，不作推测。 一、机动车辆保险 案例 1：顺风车高频率接单，被认定改变使用性质、危险程度显著增加（拒赔） 案号 ：一审（2024）粤5102民初471号；二审（2024）粤51民终873号 审理法院 / 审级 ：广东省潮州市中级人民法院（二审） 裁判日期 ：一审 2024 09 10；二审 2024 11 12 来源 URL ：http://czcourt.gov.cn/detail/4629 可信度 ：B（潮州市中级人民法院官网「潮州法院2024年度十佳案例」） 关键词标签 ： 顺风车 改变使用性质 危险程度显著增加 保险法第52条 拒赔 基本事实 ： 张某为其小型客车以非营运性质投保交强险及商业险。2023年其在「哈啰出行」平台出行 1.3 万公里、179 天、接单 325 次；在「嘀嗒出行」接单 1228 次。2023 10 19 事故中，张某负主要责任，车辆损失预估 58399 元，保险公司定损 33000 元。保险公司以「非营运投保后实际从事客运营运、危险程度显著增加且未通知」为由拒赔车损险。 争议焦点 ： 从事网约顺风车业务是否构成改变车辆使用性质、显著增加保险标的危险程度。 裁判理由（原文摘录） ： 裁判要旨：认定从事网约顺风车业务是否属于改变车辆使用性质，显著增加保险标的的危险程度，应围绕车主是否具有分摊运输成本的主观意图及具有明确的客观出行需求，综合考虑车主接单时间段、行程范围、乘客与车主出行路线的匹配度、收取的费用、事发前及事发时的使用情况、出行信息发布频次或单数是否合理等因素审查判断。 相关法条：《中华人民共和国保险法》第五十二条；《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（四）》第四条第一款。 裁判要旨 / 对我的用处 ： 法院以「接单频率、行程范围、路线匹配度、收费」综合审查，高频次（年接单逾 1500 次）被认定实质营运。可用于反驳保险公司「凡顺风车即拒赔」，也提示车主：低频、路线固定、分摊成本才是安全区。 关联法条 ：《保险法》第 52 条；《保险法司法解释（四）》第 4 条。 案例 2：非营运车跑「货拉拉」接单 100 次，商业三者险免赔（仅交强险赔） 案号 ：未披露（一审丰顺县人民法院；二审梅州市中级人民法院维持） 审理法院 / 审级 ：广东省梅州市中级人民法院（二审，维持原判） 裁判日期 ：未检索到（南方+ 刊载于 2025 03 30，来源广东省高级人民法院） 来源 URL ：https://static.nfnews.com/content/202503/30/c11135381.html?enterColumnId=13601 可信度 ：B（广东高院通过「南方+」发布，汕头政法供稿） 关键词标签 ： 货拉拉 非营运货运 改变使用性质 商业三者险免赔 提示义务 基本事实 ： 2023 01，张某驾驶轻型栏板货车撞死行人金某，全责。该车投保交强险及 100 万商业三者险，保单注明使用性质「非营业货运」，但平时在「货拉拉」接单，自 2022 10 至事发接单达 100 次、车身贴「货拉拉APP」标识。金某家属诉请赔偿。 争议焦点 ： 以非营运性质投保的车辆在营运中出险，保险公司应否在商业三者险范围内赔偿。 裁判理由（原文摘录） ： 丰顺县人民法院一审认为，案涉车辆在投保时登记为「非营业货运」的情况下从事营运活动，提高了车辆使用频率和扩大了车辆使用范围，造成车辆使用频率与事故风险显著增加，又未向保险人履行法定通知义务，故某保险公司依法在商业第三者责任险限额内免除赔偿责任。判决某保险公司赔偿金某家人 18.71 万元，张某赔偿 100.25 万元。 梅州市中级人民法院二审认为，张某使用案涉车辆在货拉拉平台注册认证，从 2022 年 10 月起至事故发生日期间共接单达 100 次，且车身明显张贴有「货拉拉 APP」标识……案涉保单载明的条款内容和形式显示某保险公司就法定免责事由履行了提示义务，应认定免责条款发生法律效力。根据合同约定，一审判决某保险公司仅在交强险范围内承担赔偿责任并无不当，故二审维持原判。 裁判要旨 / 对我的用处 ： 「非营业货运」≠ 可随意接单营运；高频接单 + 平台标识 + 未通知 = 危险程度显著增加 + 免责条款生效。提示：营运车必须按营运性质投保，否则三者险可能落空。 关联法条 ：《保险法》第 52 条（危险程度增加通知义务）；第 17 条（免责条款提示说明）。 案例 3：私家车注册网约车接单，按比例赔付保险金（条款约定「变更性质未通知按保费比例赔」） 案号 ：未披露（一审佛山市顺德区人民法院；二审维持） 审理法院 / 审级 ：佛山市顺德区人民法院一审，佛山中院二审维持 裁判日期 ：未检索到（佛山中院官网刊载） 来源 URL ：https://www.fszjfy.gov.cn/xwzx/mtjj/content/post 1001606.html 可信度 ：B（佛山市中级人民法院官网「法院+金融」典型案例） 关键词标签 ： 网约车 非营运变更营运 保费比例赔付 格式条款 基本事实 ： 刘某以家庭自用汽车投保并按非营运性质交费，保险期间在某网约车平台注册司机账户接单，变更车辆为营运性质且未通知保险人。出险后保险公司主张减免赔偿。 争议焦点 ： 保险条款约定「非营运变更营运未通知，按非营运与营运应收保费比例计算给付」，该约定能否适用。 裁判理由（原文摘录） ： 佛山市顺德区人民法院生效判决认为，保险公司是保险规则的制定者，保险条款第 3.4 条约定可视为保险人在法律规定情形外对车辆非营运性质改变为营运性质，且被保险人未作出通知时自愿给付约定比例保险金的意思表示，该意思表示未违反法律强制性规定，合法有效。张某以家庭自用汽车向某保险公司投保，并按非营运汽车性质交付保险费，但保险期间，却在某网约车平台注册司机账户接单，变更车辆为营运性质，且未通知保险人。该情形可适用保险条款第 3.4 条约定。故根据非营运性质与营运性质车辆应收保费比例，结合某保险公司确认的基准费率，判决保险公司向刘某支付保险金。二审法院予以维持。 裁判要旨 / 对我的用处 ： 并非所有「改变性质」都全免——若条款明确保留「按比例赔付」，法院支持按比例赔而非拒赔。投保时务必核对保单有无类似第 3.4 条约定，主张按比例理赔。 关联法条 ：《保险法》第 52 条；《民法典》格式条款效力规则。 案例 4：顺风车频率不高、路线固定，不属于营运，三者险应予赔偿 案号 ：未披露（一审未刊载；二审广东省揭阳市中级人民法院，改判） 审理法院 / 审级 ：广东省揭阳市中级人民法院（二审，改判） 裁判日期 ：未检索到（揭阳中院官网刊载于 2026 04 22） 来源 URL ：http://www.gdjyfy.gov.cn/jyzycourt/web/content?gid=399179&lmdm=1050 可信度 ：B（揭阳市中级人民法院官网「法庭内外」） 关键词标签 ： 顺风车 低频接单 路线固定 三者险赔偿 善意反例 基本事实 ： 郭某驾驶私家车从深圳返普宁，出发前通过顺风车平台接单搭载同路线乘客，途中撞伤行人温某，郭某全责。车辆投保交强险及三者险。一审判保险公司在交强险内赔近 12 万、郭某赔 3 万余；郭某上诉。 争议焦点 ： 接单顺风车是否改变车辆使用性质、致危险程度显著增加。 裁判理由（原文摘录） ： 揭阳中院二审查明，保险期间该车累计接单顺风车数十单，路线主要往返于郭某工作地与户籍地普宁市及周边城市，郭某自身有其他稳定工作收入。 揭阳中院审理认为，郭某接单顺风车频率不高，路线较为固定，且郭某自身有其他工作收入，能体现出郭某目的在于分摊出行成本而非营运，未实质上改变车辆的使用性质，不会导致车辆危险程度增加，故保险公司仍应在三者险范围内承担赔偿责任。法院遂改判保险公司赔偿温某 15 万余元。 【法官说法】区分顺风车和营运，应结合驾驶人职业状况、接单频率、行驶路线、收费情况等多重因素综合判断……郭某有稳定工作收入，接单频率处于合理区间，顺风车接单路线相对固定，接单行为未形成持续性、规模化运输服务，符合顺风车「顺路合乘、成本分摊」的本质特征，不属于营运行为。 裁判要旨 / 对我的用处 ： 与案例 1 形成对照：低频、路线固定、有稳定工作 = 顺风车不被认定营运，三者险照赔。维权时重点收集「接单频率 / 路线 / 工作收入」证据。 关联法条 ：《保险法》第 52 条。 案例 5：肇事逃逸，商业险免责条款因未交付、未提示而不生效（交强险+商业险均赔） 案号 ：未披露（刑事附带民事，深圳市坪山区人民法院审理） 审理法院 / 审级 ：深圳市坪山区人民法院（一审，已生效） 裁判日期 ：未检索到（坪山法院官网刊载） 来源 URL ：https://szpsfy.gov.cn/pfkx/index 81.html 可信度 ：B（深圳市坪山区人民法院官网「普法课堂」） 关键词标签 ： 肇事逃逸 免责条款无效 未提示说明 交强险+商业险 基本事实 ： 牟某、叶某分别驾车碰撞行人刘某后均逃逸，刘某当场死亡。两车均在 A、B 两家保险公司投保交强险和 100 万商业三者险（不计免赔）。家属诉请赔偿，两保险公司以「逃逸属免责条款」拒赔商业险。 争议焦点 ： 逃逸情形下商业三者险免责条款是否生效。 裁判理由（原文摘录） ： 坪山法院经审理认为，A 保险公司虽然提供了车辆保险单以及机动车综合商业保险示范条款，但该保险单以及保险条款均无投保人的签名，保险单中亦无列举保险条款中免责条款的内容。B 保险公司虽然提供了车辆保险单以及机动车综合商业保险条款，但仅有保险单上有投保人的签名，而保险条款中并无投保人的签名，且保险单中并未列举保险条款中免责条款的内容。即现有证据不能证明 A、B 两家保险公司已经将上述商业保险条款交付给了投保人，以及就商业保险条款中的免责事项告知了投保人……综上，本案中 A、B 两家保险公司主张的商业保险条款中的免责条款不产生效力。依照相关法律规定，坪山法院判决 A、B 两家保险公司在交强险和商业三者险范围内承担相应的赔偿责任。 裁判要旨 / 对我的用处 ： 逃逸≠必然商业险免赔。关键在保险公司能否证明「交付条款 + 提示说明」。若保单/条款无投保人签名、未列明免责内容，免责条款不生效，商业险仍赔。逃逸情形应重点攻「提示说明义务」瑕疵。 关联法条 ：《保险法》第 17 条第 2 款（免责条款提示说明）；《民法典》相关侵权责任规定。 案例 6：有偿代驾肇事，保险人赔付后向代驾平台代位求偿（最高法涉互联网典型案例） 案号 ：一审（2016）粤0103民初5327号；二审（2017）粤01民终13837号 审理法院 / 审级 ：广东省广州市中级人民法院（二审） 裁判日期 ：二审 2017 10 11 来源 URL ：https://www.ssfb86.com/index/News/detail/newsid/10155.html （转引自最高人民法院发布第一批涉互联网典型案例，2018 08 16） 可信度 ：B（最高人民法院发布典型案例，第三方网站转引；核心内容为最高法发布） 关键词标签 ： 代位求偿 有偿代驾 e代驾 车损险 第三者 基本事实 ： 王司政饮酒不能驾驶，通过「e代驾」平台指派吴春田提供有偿代驾；代驾中吴春田全责出险。平安保险公司定损并赔付被保险人 159194 元后，向吴春田及平台公司亿心公司追偿。 争议焦点 ： 有偿代驾人能否成为车损险被保险人；保险人赔付后能否代位求偿。 裁判理由（原文摘录） ： 广州市中级人民法院于 2017 年 10 月 11 日作出（2017）粤01民终13837号民事判决：一、撤销广州市荔湾区人民法院（2016）粤0103民初5327号民事判决第二项；二、变更第一项为：北京亿心宜行汽车技术开发服务有限公司于判决发生法律效力之日起十日内向中国平安财产保险股份有限公司广东分公司支付赔偿款 124834 元；三、驳回中国平安财产保险股份有限公司广东分公司的其他诉讼请求。 典型意义：不同于日常生活中亲朋借车或友情代驾行为，本案中代驾人系有偿提供代驾服务，并非为被保险人利益所为，对保险标的车辆也不存在占有利益，因此代驾人不能成为涉案保险合同的被保险人。代驾人作为第三人在提供有偿服务过程中造成投保车辆受损并负全责，对被保险人的财产构成侵权，被保险人有权请求赔偿，保险公司亦可代位行使求偿权。 裁判要旨 / 对我的用处 ： 代驾肇事，车损险先赔车主，再代位向「有偿代驾平台/司机」追偿（友情代驾则不同）。提示车主：代驾场景下保险仍保自己车，但追偿对象是有偿代驾方。 关联法条 ：《保险法》第 60 条（代位求偿权）。 案例 7：旧车按新车价投保、出险按实际价值赔——「高保低赔」的司法立场（法院调研） 案号 ：未披露（韶关市武江区人民法院调研，文中提及 2015 年上半年受理同类案件 3 件，均按保险法支持按实际价值理赔） 审理法院 / 审级 ：韶关市武江区人民法院（调研文章，非单一编号判决） 裁判日期 ：未检索到（武江法院官网刊载） 来源 URL ：https://sgwjfy.gov.cn/web/content?gid=493 可信度 ：B（韶关市武江区法院官网调研「机动车高保低赔现象亟需引起重视」） 关键词标签 ： 高保低赔 旧车投保 实际价值 损失补偿原则 基本事实 ： 武江法院调研指出：受损车辆均按新车购置价投保车损险，出险时保险公司以维修费超出实际价值为由仅按实际价值理赔，法院根据保险法支持保险公司主张（车主不满）。 争议焦点 ： 「高保低赔」（按新车价收保费、按折旧后实际价值赔）是否合理。 裁判理由（原文摘录） ： 发生保险事故，按车辆实际价值理赔，符合保险法的损失补偿原则，按新车价格投保多交的保费，属于超额保险，超额部分无效，保险公司多收保费的现象，应当引起重视。2015 年上半年，武江区法院共受理此类案件 3 件，受损车辆均按新车购置价投保车辆损失险，但发生保险事故时，保险公司均以维修费用超出了实际价值为由，仅同意按实际价值理赔，法院根据保险法的规定，支持保险公司的主张。 裁判要旨 / 对我的用处 ： 法院立场：旧车投保超额部分无效，全损时按实际价值赔（损失补偿原则）。但提示：2017 年广东商车改革后「实保实赔」，保额按实际价值确定，「高保低赔」在制度层面已弱化；2012 版示范条款后多地判「高保」条款为免责条款需提示说明。本案中法院支持保险人，与部分外地判决相反，需向客户说明地域/时间差异。 关联法条 ：《保险法》第 55 条第 3 款（超额保险无效）；第 23 条。 案例 8：新能源汽车充电时电瓶起火，保险公司以「故障」拒赔被驳回（认定属自燃） 案号 ：未披露（深圳中院罗湖法院审理，来源广东高院「法官说法」案例） 审理法院 / 审级 ：深圳市罗湖区人民法院（一审，来源广东省高级人民法院转发） 裁判日期 ：未检索到（南方+ 刊载于 2023 11 24，来源广东省高级人民法院） 来源 URL ：https://static.nfapp.southcn.com/content/202311/24/c8333291.html?enterColumnId=2138 可信度 ：B（广东省高级人民法院通过南方+发布，深圳中院罗湖法院审理） 关键词标签 ： 新能源汽车 充电自燃 格式条款不利解释 专属条款 基本事实 ： 2020 年某公司购新能源车办公。2021 05 车辆在停车场充电时电瓶起火全毁。消防认定「充电过程中由电瓶引发火灾」。公司主张自燃理赔 7 万余元；保险公司称电瓶自身故障属免赔。 争议焦点 ： 充电起火属「自燃」还是「故障」。 裁判理由（原文摘录） ： 事故发生时，原告对案涉车辆进行充电，属于车辆使用状态，起火的原因为车辆储能装置发生故障，而非电瓶丧失功能；同时，案涉车辆不存在非法改装、私改线路、增加外部火源的客观情况，故认定车辆电瓶未散失功能。被告主张起火原因系电瓶本身故障，属于免赔范畴，但未举证对「电瓶故障」作进一步解释说明，法院依法对被告作出不利解释。 综上，法院认定事故原因为自燃，属于保险责任的范畴，依法判决被告应向原告支付理赔款 7 万余元。 【法官说法】2021 年 12 月 14 日，中国保险行业协会公布的《中国保险行业协会新能源汽车商业保险专属条款（试行）》显示，新能源汽车的自燃属于保险责任范围。 裁判要旨 / 对我的用处 ： 新能源车充电起火，若保险公司主张「故障」免赔却未作明确解释说明，法院作不利解释、认定属自燃赔付。结合新能源专属条款，自燃在保障范围内。维权要点：要求保险公司对「故障」免责作具体说明并举证。 关联法条 ：《保险法》第 30 条（格式条款不利解释）；《民法典》第 496、498 条；《新能源商业保险专属条款（试行）》。 二、财产保险 / 家财险 / 责任险 / 新型险种 案例 9：雇主责任险「空白投保单」隐瞒差额赔付条款，保险公司拒赔被驳回 案号 ：未披露（广州市中级人民法院生效判决，载广东高院第二批典型案例） 审理法院 / 审级 ：广东省广州市中级人民法院（二审） 裁判日期 ：未检索到（广东高院 2025 10 09 发布） 来源 URL ：https://www.gdcourts.gov.cn/gsxx/quanweifabu/anlihuicui/content/post 1843544.html 可信度 ：B（广东省高级人民法院官网「服务保障民营经济高质量发展典型案例」） 关键词标签 ： 雇主责任险 空白投保单 未提示说明 差额赔付 免责无效 基本事实 ： 某物流公司（小微民企）投保雇主责任险，保险公司仅提供空白《投保单》要求盖章，未提供《保险条款》；投保单载明雇员死亡责任限额 50 万、未载明免赔范围。缴费后保险公司才邮寄条款，载明「如有工伤保险，保险人仅承担差额责任」。后雇员因工死亡，物流公司赔家属 50 万后索赔，保险公司以工伤已赔为由拒付。 争议焦点 ： 投保单与保险条款不一致时，免责「差额赔付」条款是否生效。 裁判理由（原文摘录） ： 广州市中级人民法院生效判决认为，物流公司确认投保时，保险公司未提供《保险条款》并对赔付范围进行提示说明。缴费后，保险公司提供的《保险条款》内容与《投保单》不一致，且在保险事故发生后亦未提示说明赔付范围，应以投保单为准确定双方权利义务。保险公司在物流公司实际赔付 50 万元后才主张物流公司无须在工伤保险之外承担责任并以此拒赔，属于不当免除自身责任，于法无据，判决保险公司支付保险金 50 万元。 典型意义：保险公司应当客观介绍雇主责任险赔付范围，不得故意隐瞒其仅在工伤保险之外承担差额赔偿责任等免责条款诱导投保……企业据此向雇员先行赔付的，保险公司应承担保险责任。 裁判要旨 / 对我的用处 ： 投保单未载免赔、条款后补且不一致 → 以投保单为准，免责不生效。企业投保雇主责任险务必同步拿到条款、要求书面说明「差额赔付」等关键免责。 关联法条 ：《保险法》第 17 条；《保险法司法解释（二）》第 14 条（投保单与保险单不一致以投保单为准）。 案例 10：雇员死亡后补办批改，雇主责任险仍赔 50 万 案号 ：未披露（历经一审、二审，东莞市中级人民法院终审） 审理法院 / 审级 ：广东省东莞市中级人民法院（终审） 裁判日期 ：未检索到（东莞中院官网刊载） 来源 URL ：https://www.dgcourt.gov.cn/News/Show.asp?id=5027 可信度 ：B（东莞市中级人民法院官网） 关键词标签 ： 雇主责任险 新增雇员批改 生效日 射幸合同 基本事实 ： 劳务派遣公司雇员小黄工作中死亡。公司申请将小黄加入保险名单时间晚于其死亡时间。保险公司以「死亡时不在保险期内、保单不成立」拒赔；公司主张按特别约定新员工生效日以入职日为准、且已在约定期限内报批。 争议焦点 ： 死亡后批改新增雇员，雇主责任险合同是否成立、应否赔付。 裁判理由（原文摘录） ： 法院认为，劳务派遣公司在保险条款约定期限内履行了报批手续，且没有证据证明小黄的死亡与工作无关，因此保险公司应承担保险责任。劳务派遣公司在提交新增员工名单时虽然小黄已经死亡，但依照约定因保险对新员工的生效时间均是从新员工入职当天开始，因此保险仍对小黄生效。劳务派遣公司在增加员工名单时没有如实向保险公司告知实情有不妥，但保险公司作为保险合同的制定方，当出现不可预见的情形时，应当由保险公司承担不利后果。东莞市中级人民法院终审认定双方的保险合同成立，依法判令保险公司向劳务派遣公司赔偿 50 万元。 裁判要旨 / 对我的用处 ： 保单特别约定「新员工生效日=入职日」优先；在约定期限内报批即受保障。用人单位应及时沟通批改，保险公司不得以「未实时告知」一刀切拒赔。 关联法条 ：保险合同特别约定优先；不利解释规则。 案例 11：燃气热水器产品缺陷致死亡，产品责任险优先赔付（每人伤亡限额内） 案号 ：未披露（丰顺县人民法院 2018 10 29 一审判决；载司法部案例库） 审理法院 / 审级 ：广东省丰顺县人民法院（一审） 裁判日期 ：2018 10 29 来源 URL ：https://alk.12348.gov.cn/Detail?dbID=46&dbName=FYGL&sysID=15372 可信度 ：B（司法部司法行政（法律服务）案例库，丰顺县法律援助处案例） 关键词标签 ： 产品责任险 产品缺陷 燃气热水器 每人伤亡限额 连带责任 基本事实 ： 张某某使用缺陷燃气热水器一氧化碳中毒死亡。生产者中山某公司（投保永诚财保顺德支公司产品责任险，每次事故每人伤亡限额 10 万）、销售者、安装人蔡某按过错分担责任。 争议焦点 ： 产品责任险在缺陷产品致害赔偿中的赔付顺序与限额。 裁判理由（原文摘录） ： 合议庭结合原、被告和第三人提供的证据，确定原告损失合计 1721776.77 元，被告中山某公司为其公司生产的热水器系列产品在永诚财保顺德某支公司投保了每次事故每人伤亡限额为 100000 元的产品责任险，故被告永诚财保顺德某支公司应优先赔偿原告 100000 元，剩余 1621776.77 元，由原告自负 30% 即 486533.03 元，剩余 1135243.74 元由被告中山某公司和蔡某各承担 567621.87 元，并互负连带赔偿责任，被告兴宁某家电配件部承担连带责任。 2018 年 10 月 29 日，丰顺县人民法院作出一审判决，被告永诚财保某支公司赔偿两原告 100000 元…… 裁判要旨 / 对我的用处 ： 产品责任险在「每次事故每人伤亡限额」内优先赔付，不足部分再由生产者/销售者/过错方按份或连带承担。提示企业：产品责任险保额有限，须关注「每次事故/每人」限额是否覆盖风险。 关联法条 ：《产品质量法》第 41、43 条；《保险法》第 65 条（责任保险直接赔付第三者）。 案例 12：无合法产权证的自建房投保家财险，洪灾受损仍获赔 案号 ：一审（2023）粤0222民初734号；二审维持（案号未披露） 审理法院 / 审级 ：广东省始兴县人民法院（一审），韶关中院二审维持 裁判日期 ：一审 2023 10 30 来源 URL ：https://sgmsw.cn/v/info?id=124689 （来源：韶关市中级人民法院） 可信度 ：B（韶关新闻网，来源韶关市中级人民法院；维基文库另载一审判决书全文 (2023)粤0222民初734号） 关键词标签 ： 家庭财产险 无产权证 保险利益 承保审查义务 洪灾 基本事实 ： 2022 09 凌某为自建房屋投保「平安逸家·家财宝」家财险（含室内财产损失 20 万）。2023 04 房屋遭洪涝，室内物品被泡。保险公司以「无合法产权证明、不符合承保对象」拒赔；保单特别约定「仅承保被保险人拥有合法产权的居住房屋」。 争议焦点 ： 无产权登记的自建房，投保人是否享有保险利益；保险公司承保后能否以无产权证拒赔。 裁判理由（原文摘录） ： 始兴法院经审理认为，双方达成的财产保险合同合法有效。首先，投保人是否具备合法产权证明，是保险公司在承保时就应当审查的内容。保险公司未尽审查义务便接受投保，事后无权以此为由拒赔。其次，凌某提交的电费缴交发票、银行流水以及村委会证明，足以证实凌某是该自建房屋的权利人，即便未办理产权登记，也对房屋及屋内财产享有保险利益。最后，凌某提交受灾当日视频可知，房屋内生活用品、家电、家具齐全，符合居住的条件和事实。且灾害发生在保险责任期限内，保险公司理应予以赔偿。最终，法院依法判决被告保险公司赔偿原告凌某室内财产损失 37910 元及鉴定评估费 10000 元。被告不服判决提起上诉，二审判决维持原判。 裁判要旨 / 对我的用处 ： 承保时未尽审查、仍收保费 → 禁反言，不得以「无产权证」拒赔；事实居住+村委会证明可证保险利益。家财险理赔遇「产权」门槛时，可主张保险公司承保审查义务。 关联法条 ：《保险法》第 12 条（保险利益）；第 64 条（鉴定费由保险人承担）。 案例 13：物业公司保洁不当致业主摔伤，公众责任险保险人代位求偿获支持 案号 ：未披露（一审，审判员 罗晔，2023 10 23；维基文库载一审判决书全文） 审理法院 / 审级 ：基层人民法院一审（判决书署名审判员 罗晔，二〇二三年十月二十三日） 裁判日期 ：2023 10 23 来源 URL ：https://zh.wikisource.org/zh hans/中国人某财产保险深圳市分公司、广州心某物业管理有限公司保险人代位求偿权纠纷民事一审民事判决书 可信度 ：C（维基文库转录裁判文书，非法院官网首发；仅作线索，裁判要旨待核验） 关键词标签 ： 公众责任险 物业保洁 代位求偿 第三者损害 基本事实 ： 豪某花园小区保洁委托心某物业公司。雷某妹在小区因心某物业不当保洁行为摔倒受伤。人保深圳市分公司承保该小区公众责任险，已在责任限额内赔付 50287.04 元，取得豪某公司《权益转让书》后向心某物业代位求偿。 争议焦点 ： 公众责任险保险人赔付后，能否向有过错的保洁服务方代位求偿。 裁判理由（原文摘录，转录自维基文库） ： 人保深圳市分公司系承保了涉案小区的公众责任险，现已在该公众责任险损失险责任限额范围内赔付了 50287.04 元，该公司依法有权代位行使豪某公司对侵权方请求赔偿的权利……心某公司的不当保洁行为导致此事件的发生，因此心某公司为该事件的侵权方，人保深圳市分公司依据豪某公司出具的《权益转让书》，取得向心某公司的代位求偿权。故原告请求被告支付赔偿款 50287.04 元合法有据，本院予以支持。 判决如下：一、被告广州心某物业管理有限公司于本判决发生法律效力之日起十日内向原告中国人某财产保险股份有限公司深圳市分公司赔偿 50287.04 元；二、驳回原告其他诉讼请求。 裁判要旨 / 对我的用处 ： 公众责任险赔付小区第三者损害后，可向实际侵权方（如保洁外包公司）代位追偿。物业企业应注意外包合同中的责任划分。 关联法条 ：《保险法》第 60 条（代位求偿权）。 案例 14：诉讼保全责任险——保险公司向投保人追偿/主张反担保被驳回（反担保条款无效） 案号 ：未披露（企业官网「以案说险」案例，来源广东省能源集团） 审理法院 / 审级 ：未披露（载企业普法案例，二审生效） 裁判日期 ：未检索到 来源 URL ：https://www.geg.com.cn/qywh/yasx/content/post 4263.html 可信度 ：C（广东省能源集团官网普法文章，非法院官网；仅作线索，裁判要旨待核验） 关键词标签 ： 诉讼保全责任险 追偿 反担保条款无效 过错责任 基本事实 ： 张某诉 A 公司建设工程施工合同案中，张某购诉讼保全责任险，B 保险公司出具保函担保，法院查封 A 公司账户。后张某败诉，A 公司诉张某及 B 保险公司保全损害责任，生效判决认定张某未尽审慎注意义务、赔 A 公司利息损失，B 保险公司连带；B 保险公司赔付 29.67 万后，向张某追偿/主张反担保赔偿。 争议焦点 ： 诉责险保险公司赔付后，能否向投保人追偿或依保证条款/承诺函主张反担保赔偿。 裁判理由（原文摘录，转述自企业普法文章） ： 法院审理认为：B 保险公司以张某存在重大过失未履行如实告知义务拒绝赔偿诉讼保全责任险保险金的意见不能成立。该义务对应的是 B 保险公司的合同解除权，现 B 保险公司既未在法律规定的合同解除权行使期间内主张解除保险合同，又未举证证明存在其他保险除外责任情形，故而保险合同仍然成立并有效，B 保险公司应当按照保险合同的约定向张某履行赔偿义务……B 保险公司依据保证条款要求投保人对诉讼保全责任险中 B 保险公司的赔偿责任提供反担保，改变了责任保险不能向被保险人进行追偿的性质，应属无效条款。 裁判要旨 / 对我的用处 ： 诉责险本质为责任保险，保险公司赔付被申请人损失后，一般不能向投保人/被保险人追偿；要求反担保的条款因改变责任险性质而无效。投保人遇保险公司「代位/追偿」主张时可据此抗辩。 关联法条 ：《民事诉讼法》第 108 条（保全错误赔偿）；《保险法》第 65 条（责任保险）；过错责任原则。 案例 15：锂电池产品责任险——充电起火致损，保险公司按限额减免赔率赔付 案号 ：未披露（白云法院一审；广州中院二审维持，载羊城晚报） 审理法院 / 审级 ：广州市白云区人民法院一审，广州中院二审维持 裁判日期 ：未检索到（羊城晚报 2021 08 04 刊载） 来源 URL ：https://ep.ycwb.com/epaper/ycwb/html/2021 08/04/content 118 414996.htm 可信度 ：C（羊城晚报记者报道，转述判决；仅作线索，裁判要旨待核验） 关键词标签 ： 产品责任险 锂电池 免赔率 财产损失限额 二审维持 基本事实 ： 动某公司售电动车锂电池，2020 12 一锂电池充电起火致菲某公司财产损失 130 万余元。动某公司已投保产品责任险（每次事故财产损失限额 800 万）。消防/法院认定动某公司承担 80% 责任（菲某未二次消防验收等自担 20%）。 争议焦点 ： 产品责任险在锂电池缺陷致他人财产损害时的赔付计算。 裁判理由（原文摘录，转述自报道） ： 因动某公司已向保险公司投保产品责任险，每次事故财产损失限额 800 万元，因保险公司的免赔率为 10% 即 104406.4 元，故保险公司实际应赔偿 93 万余元，由动某公司赔偿 10 万余元。白云法院一审判决：保险公司在产品责任保险财产损失限额内赔偿菲某公司财产损失 93 万余元；动某公司赔偿菲某公司财产损失 10 万余元。菲某公司上诉后，广州中院二审维持原判。 裁判要旨 / 对我的用处 ： 产品责任险按「责任比例 × 损失 − 免赔率」在限额内赔付，余额由被保险人自担。提示：投保时关注免赔率与限额是否足额；缺陷产品致第三人损害时，险企依约赔、生产者补差。 关联法条 ：《保险法》第 65 条；《产品质量法》第 41、43 条。 检索缺口 以下争议类型本次未检索到广东辖区、且来源可信（B 级）的明确案例，列为后续补强方向： 1. 无证驾驶 / 醉酒驾驶拒赔的商业三者险纠纷（广东具体案号） ：检索到深圳坪山「逃逸免责无效」案（案例 5），但「酒驾/醉驾」免责的广东具体判决未见官方刊载，仅有外地/律所转述，未收录。 2. 车辆未年检 / 未按规定检验拒赔 ：未检索到广东法院官方典型案例，仅有保险条款层面的讨论。 3. 不计免赔率条款效力争议 ：本批案例多涉及免责/免赔，但专门就「不计免赔率」条款争议（如未投保不计免赔如何扣减）的广东判决未单独检索到。 4. 代位求偿中「被保险人与家庭成员」限制（保险法第 62 条）的广东案例 ：检索到代驾、逃逸等代位求偿案，但家庭成员/组成人员限制的广东判例未检索到。 5. 新能源汽车「外部电网故障损失险」「自用充电桩责任险」理赔争议 ：仅检索到专属条款出台新闻与充电自燃案例，具体充电桩附加险理赔诉讼未见广东判决。 6. 宠物险 / 其他新型险种（如试管婴儿险、网络账户安全险）的广东纠纷 ：未检索到广东辖区司法案例。 7. 公众责任险中「绝对免赔额/免赔率」条款争议的具体广东判决 ：案例 13 仅见代位求偿，免赔额抗辩的广东判决未单独检索到。"}, {"id": "L2-案例库/广东案例-重疾医疗", "group": "3 · 广东案例库", "groupKey": "L2-案例库", "title": "重疾险 / 医疗险 · 案例库", "order": 3, "file": "广东案例-重疾医疗.md", "html": "<h1 id=\"s0\">重疾险 / 医疗险 · 案例库</h1>\n<blockquote>采集日期：2026-09-16 ｜ 采集人：AI 检索 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手来源待核验<br>本节共 12 个案例。B 级 = 法院官方/官媒来源（可直接采用）；C 级 = 二手来源，待核验，不得直接引用裁判要旨。<br>其中：广东案例 11 个，北京案例 1 个（北京金融法院\"金融案鉴\"，属优先来源，作区域外参考）；B 级 11 个，C 级 1 个。<br>有二审（含中院二审）的案例：案例 1、2、3、4、5、7、11、12，共 8 个。</blockquote>\n<hr>\n<h2 id=\"s1\">案例 1：互联网投保重疾险，\"隐藏式询问\"不构成未如实告知，保险公司败诉</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（广州中院发布典型案例时隐名）</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院 · 二审（一审：广州市基层法院；来源页面未列明一审具体法院）</li>\n<li><strong>裁判日期</strong>：未检索到（广州中院于 2023-09-14 发布该典型案例）</li>\n<li><strong>来源 URL</strong>：https://www.gzcourt.gov.cn/yqfkdt/ck597/2023/09/14114347831.html</li>\n<li><strong>可信度</strong>：B（广州市中级人民法院官网发布之\"广州法院保险纠纷典型案例\"）</li>\n<li><strong>关键词标签</strong>：如实告知、互联网投保、乳腺囊肿、询问方式、有问方有答</li>\n</ul>\n<p><strong>基本事实</strong>： 2019 年，李某通过互联网为自己购买重大疾病保险，条款涵盖恶性肿瘤。投保页面中，关于乳腺类疾病的询问需多次点击缺乏明确指示意义的向下箭头\"∨\"才能看到，李某因而未看到该项询问。李某曾明确询问投保客服是否需上传体检报告，客服表示不用。李某体检报告中有乳腺囊肿记录，但投保时未勾选告知。2021 年 2 月 7 日李某确诊\"右乳浸润性癌\"，申请理赔被拒（理由：不实告知）。李某起诉要求支付 65 万元。一审判决保险公司赔付；保险公司上诉，广州中院二审驳回上诉、维持原判。</p>\n<p><strong>争议焦点</strong>： 投保页面将乳腺疾病询问隐藏于折叠箭头之后，是否足以认定投保人\"未如实告知\"；网络投保场景下保险人询问是否应\"易于识别\"。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>《中华人民共和国保险法》第十六条第一款规定：\"订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。\"据此，投保人履行如实告知义务以保险人提出询问为前提。有问方有答，保险公司提出的询问，应当易于识别，否则不应轻易认定投保人未尽到如实告知义务。<br>本案中，根据李某提供的投保页面，并无法直接看到关于乳腺类疾病的询问或选项，投保人需多次点击缺乏明确指示意义的向下箭头\"∨\"才能看到乳腺疾病包括乳腺结节、包块、囊肿或肿物的内容。该投保流程的设置较为隐蔽，很容易导致投保人漏看或跳过。因此，从保险公司关于案涉争议告知事项的询问设置来看，不足以认定李某未勾选乳腺囊肿选项构成不如实告知相关事项的故意或重大过失。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 网络投保中，保险人询问须\"易于识别\"；将关键健康询问隐藏于折叠页面，不能轻易认定投保人未尽告知义务。代理互联网投保拒赔案件时，第一步即固定投保页面流程证据。</p>\n<p><strong>关联法条</strong>：保险法 §16（如实告知，有问方有答）、§17（提示说明）</p>\n<hr>\n<h2 id=\"s2\">案例 2：医疗险投保前已确诊高血压 2 级未告知，投保人败诉</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（广州中院发布典型案例时隐名）</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院 · 二审（一审同前隐名）</li>\n<li><strong>裁判日期</strong>：未检索到（广州中院于 2023-09-14 发布）</li>\n<li><strong>来源 URL</strong>：https://www.gzcourt.gov.cn/yqfkdt/ck597/2023/09/14114347831.html</li>\n<li><strong>可信度</strong>：B（广州市中级人民法院官网）</li>\n<li><strong>关键词标签</strong>：如实告知、医疗险、高血压、故意不告知、投保人败诉</li>\n</ul>\n<p><strong>基本事实</strong>： 2018 年 10 月王某被诊断为高血压 2 级。2019 年 2 月，投保人张某（为王某）在线购买医疗保险，询问项含\"是否曾有 2 级或以上高血压（收缩压&gt;160mmHg，舒张压&gt;100mmHg）\"，张某勾选\"否\"。保险期内王某因脑出血、高血压 2 级住院，保险公司以未告知高血压 2 级为由拒赔并拟解除合同。王某诉请确认解除无效并赔付。一审驳回；广州中院二审驳回上诉、维持原判。</p>\n<p><strong>争议焦点</strong>： 投保前已被医疗机构明确诊断\"高血压 2 级\"并治疗，投保人主张\"血压值未达询问标准故无须告知\"是否成立。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>如实告知义务是最大诚信原则在保险法中的重要体现，是保险合同有效成立的基础，也是保险合同的基本行为准则。对保险人就被保险人的有关情况提出的询问，投保人应当如实告知。<br>本案中，针对被保险人有无\"2级及以上高血压（收缩压大于160mmHg，舒张压大于100mmHg）\"的疾病或症状，保险公司已提出了明确易懂的询问。一般人均可理解，该询问需要投保人如实回答。在已被医疗机构明确诊断为高血压2级并进行治疗的情况下，王某以其血压值未达到\"收缩压大于160mmHg，舒张压大于100mmHg\"为由，主张其不属于高血压2级，故无须告知高血压2级的事实。该主张与医疗机构已作出的诊断及实际治疗情况明显不符，张某投保时隐瞒了王某在投保前不久被诊断为高血压2级的事实，明显与案涉保单询问的要求不符，违反了如实告知义务，故本案判决驳回了王某的诉讼请求。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 与案例 1 相反：保险人已作\"明确易懂\"的询问且医疗机构已有明确诊断的，未告知即构成违反如实告知义务，投保人败诉。可用于对比说明\"询问是否清晰\"是胜负分界。</p>\n<p><strong>关联法条</strong>：保险法 §16（如实告知义务）</p>\n<hr>\n<h2 id=\"s3\">案例 3：限定\"开胸/开腹\"手术方式的重疾险格式条款无效，二审改判赔付</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（广州中院发布典型案例时隐名）</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院 · 二审（一审驳回，二审改判）</li>\n<li><strong>裁判日期</strong>：未检索到（广州中院于 2023-09-14 发布）</li>\n<li><strong>来源 URL</strong>：https://www.gzcourt.gov.cn/yqfkdt/ck597/2023/09/14114347831.html</li>\n<li><strong>可信度</strong>：B（广州市中级人民法院官网）</li>\n<li><strong>关键词标签</strong>：疾病释义/手术方式限定、主动脉夹层、格式条款无效、微创介入、免责条款</li>\n</ul>\n<p><strong>基本事实</strong>： 2014 年张某投保，条款约定主动脉手术赔付须\"实际实施了开胸或开腹进行的切除、置换、修补病损主动脉血管的手术\"。2021 年张某确诊主动脉夹层，行\"主动脉覆膜支架腔内隔绝术\"（微创，非开胸开腹）。保险公司以手术方式不符拒赔。一审驳回；广州中院二审改判保险公司支付保险金 111,750 元。</p>\n<p><strong>争议焦点</strong>： 限定手术方式为\"开胸或开腹\"的格式条款，是否属于免责条款；未充分提示说明时是否对被保险人不生效。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>对保险合同中免除保险人责任的条款，保险人应当履行提示说明义务。保险合同中限定疾病治疗手术方式的格式条款，排除了被保险人选择合理医疗服务的权利，属于免责条款。保险人未就此进行充分提示说明的，该条款对被保险人不发生法律效力。<br>案涉保险合同的相关条款将手术方式限定为开胸或者开腹，限制了被保险人在紧急情况下接受合理医疗服务的权利，也超出了一般人在订立合同时的合理预期范围，背离了一般人的通常认知和通行的治疗方法，实际免除或者减轻了保险人的保险责任，故应视为免责条款。本案中保险公司未能举证其已就此履行提示和明确说明义务，因此保险合同中限定手术方式的条款对张某不发生效力，故保险公司应向张某支付保险金。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： \"开胸/开腹\"等限定手术方式的条款，因排除合理医疗选择权、背离通行诊疗标准，应视为免责条款；保险人未尽提示说明义务的，条款不生效。代理微创手术（支架、介入）拒赔案件的核心武器。</p>\n<p><strong>关联法条</strong>：保险法 §17（免责条款提示说明）、司法解释二 §9（免责条款界定）、§11（明确说明）</p>\n<hr>\n<h2 id=\"s4\">案例 4：重疾险\"疾病释义\"条款限缩理赔范围，应视为免责条款</h2>\n<ul>\n<li><strong>案号</strong>：一审 (2021)粤0104民初3622号；二审 (2021)粤01民终12850号</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院 · 二审（一审：广州市越秀区人民法院）</li>\n<li><strong>裁判日期</strong>：二审 2021-09-06（一审 2021-04-06）</li>\n<li><strong>来源 URL</strong>：https://www.guangzhou315.com/html/web/anlifenxi/26243.html （中消协 2021-2022 年度\"全国消费维权十大典型司法案例\"；原判载《人民法院案例选》2023 年第 3 辑，编写人：广州中院 李杰、白云区法院 段静楠）</li>\n<li><strong>可信度</strong>：B（中国消费者协会发布十大典型司法案例；原始刊载于《人民法院案例选》）</li>\n<li><strong>关键词标签</strong>：疾病释义、下腔静脉滤器、限缩理赔、免责条款、明确说明</li>\n</ul>\n<p><strong>基本事实</strong>： 2019 年温某向百年人寿广东分公司投保重疾险（保额 20 万）。2020 年温某因左下肢深静脉血栓入院，行\"下腔静脉滤器植入术\"等。保险公司以该手术不满足条款中\"反复肺栓塞发作\"条件为由拒赔。温某起诉。一审判决（越秀法院）支持赔付；广州中院二审维持，判保险公司支付保险金 70,000 元、退还保费 5,350 元并豁免后续保费。</p>\n<p><strong>争议焦点</strong>： \"疾病释义\"条款（将理赔限于特定手术/症状条件）背离通常认知与通行诊疗标准、限缩理赔范围的，是否应视为免责条款。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>保险合同中的\"疾病释义\"条款如背离了一般人的通常认知和通行的诊疗标准，限缩了疾病的理赔范围，实际免除或者减轻了保险人的保险责任，应视为免责条款，保险人应向投保人履行提示说明义务，否则该条款不成为保险合同的内容，对投保人不发生效力。<br>法院判决认为，保险合同中的\"疾病释义\"条款背离了一般人的通常认知和通行的诊疗标准，限缩了疾病的理赔范围，实际免除或者减轻了保险人的保险责任，应视为免责条款，而被告未就该条款的概念、内容和法律后果对原告作出解释说明，故该条款对原告不发生效力，被告应向原告支付保险金 70000 元，向温某退还保险费 5350 元，豁免温某 2020 年 2 月 7 日后的各期保险费。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 重疾险条款中各种\"释义/附加条件\"（如要求特定手术、特定症状持续时间）若限缩保障范围，按司法解释二 §9 视为免责条款，保险人未尽明确说明则不生效。此案为最高参考价值的\"疾病释义\"标杆案。</p>\n<p><strong>关联法条</strong>：保险法 §17、司法解释二 §9（免责条款界定）、民法典 §496（格式条款）、健康保险管理办法 §23</p>\n<hr>\n<h2 id=\"s5\">案例 5：等待期内发现疑似、等待期后病理确诊癌症，保险公司不得拒赔</h2>\n<ul>\n<li><strong>案号</strong>：一审 (2018)粤0104民初3661号；二审 (2018)粤01民终11900号</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院 · 二审（一审：广州市越秀区人民法院）</li>\n<li><strong>裁判日期</strong>：二审 2018-08-22（一审 2018-04-03）</li>\n<li><strong>来源 URL</strong>：https://court.yuexiu.gov.cn/index.php?s=/Show/index/cid/213/id/1461.html （广州市越秀区人民法院官网\"典型案例\"）</li>\n<li><strong>可信度</strong>：B（广州市越秀区人民法院官网）</li>\n<li><strong>关键词标签</strong>：等待期、确诊时间、病理报告、防癌险、胶质母细胞瘤</li>\n</ul>\n<p><strong>基本事实</strong>： 2016 年 8 月陈某为妻子钟某珍投保国寿防癌疾病保险及附加防癌两全保险（保额各 10 万，45 年）。等待期一年。2016 年 8 月 16 日（等待期内）钟某珍做检查，2016 年 8 月 23 日（等待期内）病理确诊为胶质母细胞瘤 WHO IV 级。2017 年 9 月申请理赔，保险公司以\"等待期内发现恶性肿瘤\"只退保费、终止合同。钟某珍诉请赔付并继续履行。一审支持；广州中院二审维持。</p>\n<p><strong>争议焦点</strong>： 重大疾病\"确诊时间\"应以病理报告出具日为准，还是以等待期内发现疑似/初诊日为准。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>【裁判要旨】保险合同以一年为界限设立等待期，确定保险责任……当被保险人因重大疾病就诊并接受医院相关检查出具初诊报告的事实的发生在等待期内，但主张在合同生效一年后才确诊的，如何认定重大疾病确诊时间成为了本案的关键。确诊时间根据病理报告单出具日来进行确定的，保险公司不能以被保险人在等待期内已经发现恶性肿瘤为由拒绝理赔。<br>保险公司不能以被保险人在等待期内已经发现疑似恶性肿瘤为由拒绝理赔。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 等待期争议的\"确诊时间\"认定标准——以病理报告出具日为准，而非等待期内初诊/疑似日。代理等待期临界案件时，紧扣\"确诊\"的医学定义与病理报告日期。</p>\n<p><strong>关联法条</strong>：保险法 §13、§30（格式条款不利解释）；原判决引用合同法 §60、§107</p>\n<hr>\n<h2 id=\"s6\">案例 6：百万医疗险未告知\"早搏\"，法院以保险人未尽术语解释义务判赔</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（广州市荔湾区人民法院官网发布时未列明）</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市荔湾区人民法院 · 一审（判决已生效）</li>\n<li><strong>裁判日期</strong>：未检索到（荔湾法院于 2026-03 发布）</li>\n<li><strong>来源 URL</strong>：http://lwfy.gzcourt.gov.cn/fhys/2026/03/500546209344734.html</li>\n<li><strong>可信度</strong>：B（广州市荔湾区人民法院官网）</li>\n<li><strong>关键词标签</strong>：百万医疗险、如实告知、专业术语、心律失常、早搏、解释义务</li>\n</ul>\n<p><strong>基本事实</strong>： 2019 年陈先生为妻子何女士投保百万医疗险及住院费用补偿医疗险，连续续保。2024 年初何女士因乙流致胸闷住院，诊断\"频发性室性期前收缩\"（早搏），个人自付 1.1 万余元。理赔时保险公司以\"投保前存在多年早搏病史、早搏属心律失常却未告知\"拒赔。何女士称医生从未告知\"早搏属心律失常\"，投保时保险公司也未解释。荔湾法院判决保险公司支付理赔款 1.1 万余元，已生效。</p>\n<p><strong>争议焦点</strong>： \"心律失常\"作为专业医学术语，保险人未向投保人解释其涵盖\"早搏\"的，能否以投保人未告知\"早搏\"为由拒赔。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>本案是一起因专业术语理解偏差引发的人身保险合同纠纷。根据保险法相关规定，投保人的如实告知义务，以保险公司的明确询问为前提，投保人只需在保险公司询问的范围内如实作答。若双方对询问内容存在争议，举证责任由保险公司承担。<br>本案中，投保单的病史询问仅提及\"心律失常\"，但\"心律失常\"作为一个专业医学术语，其具体涵盖范围并非普通消费者能够准确理解。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 专业医学术语（如\"心律失常\"）的询问范围存在争议时，举证责任在保险人；保险人未解释术语涵义的，不能将\"未告知\"归责于投保人。百万医疗险健康告知纠纷的常用抗辩。</p>\n<p><strong>关联法条</strong>：保险法 §16、§17；司法解释二 §11（明确说明）、§6（询问范围举证）</p>\n<hr>\n<h2 id=\"s7\">案例 7：百万医疗险鼻咽癌，投保前两年外的病史不属告知范围，二审维持赔付</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（开平法院、江门中院发布时未列明）</li>\n<li><strong>审理法院 / 审级</strong>：广东省江门市中级人民法院 · 二审（一审：开平市人民法院；二审维持）</li>\n<li><strong>裁判日期</strong>：未检索到（开平法院于 2024-09 发布）</li>\n<li><strong>来源 URL</strong>：https://www.kpcourt.gov.cn/fydt/dxal/202409/t987716.html</li>\n<li><strong>可信度</strong>：B（开平市人民法院官网，二审由江门中院维持）</li>\n<li><strong>关键词标签</strong>：百万医疗险、如实告知、两年期限、鼻咽癌、询问范围</li>\n</ul>\n<p><strong>基本事实</strong>： 2021 年 4 月刘某芳为父亲刘某网上投保百万医疗保险和住院保（各 1 年）。2021 年 6 月刘某确诊鼻咽癌，申请理赔被拒（理由：未告知两年内健康异常），保险公司单方解除合同。刘某芳起诉请求确认解除无效并赔付 5 万余元。开平法院一审支持；保险公司上诉，江门中院二审驳回上诉、维持原判。</p>\n<p><strong>争议焦点</strong>： 保险人询问限于\"最近两年\"健康异常，投保人既往（2012、2016 年）已痊愈病史是否属告知范围。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>法院审理认为：刘某芳向某保险公司投保的两份人身保险合同中，保险人询问的范围是被保险人最近两年因健康异常住院、手术或检查发现异常的情况……而刘某过往的病史发生在2012年和2016年，均在刘某芳投保涉案保险两年前发生且已痊愈，故不属于涉案保险合同要求投保人必须告知的范围。某保险公司以刘某上述诊疗记录主张刘某芳知道或者应当知道刘某在投保时存在相关健康异常依据不足。<br>人民法院对\"健康告知\"中\"投保前两年内\"这一期限严格把控，即投保人的告知义务限于保险人询问的范围，保险人没有询问的内容，投保人无需主动告知，并结合投保人并非医学专业人士的实际情况和保险公司的举证情况，确认投保人和被保险人并未违反如实告知义务，该保险合同仍然有效。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 健康告知的\"期限\"（如\"近两年\"）应严格按询问把控；超期且已痊愈的病史不属告知范围，保险人不能倒查多年旧病史主张解除。反驳\"带病投保\"拒赔的利器。</p>\n<p><strong>关联法条</strong>：保险法 §16；司法解释二 §6（告知限于询问范围及内容）</p>\n<hr>\n<h2 id=\"s8\">案例 8：抑郁病史重疾险，\"抑郁状态\"≠\"抑郁症\"，概括性条款不得作拒赔依据</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（人民法院报/广东省高院微博发布时未列明）</li>\n<li><strong>审理法院 / 审级</strong>：广东省深圳市罗湖区人民法院 · 一审（判决已生效）</li>\n<li><strong>裁判日期</strong>：未检索到（发布渠道为\"人民法院报\"\"广东省高级人民法院\"官方微博\"身边的鹏法\"）</li>\n<li><strong>来源 URL</strong>：https://weibo.com/2187110962/OiErl1Q0I?type=repost</li>\n<li><strong>可信度</strong>：B（人民法院报、广东省高级人民法院、深圳市罗湖区法院官方微博联合发布）</li>\n<li><strong>关键词标签</strong>：重疾险、如实告知、概括性条款、抑郁状态、精神疾病</li>\n</ul>\n<p><strong>基本事实</strong>： 2021 年吴女士分两次投保同一重疾险（各 10 万，20 年）。2021 年 11 月确诊\"神经上皮肿瘤\"申请理赔。保险公司核查第一份合同发现其 2019 年曾被诊断\"抑郁状态\"，以违反\"精神疾病\"健康告知为由解除第一份合同；第二份合同以\"90 天等待期内出险\"拒赔。吴女士诉请赔付 20 万。法院判决：第一份合同\"抑郁状态\"与询问的\"抑郁症\"性质不同，未违反告知，且\"精神疾病\"属概括性条款未明确说明，解除无效，判赔 10 万；第二份合同处于等待期，不赔。判决生效。</p>\n<p><strong>争议焦点</strong>： \"抑郁状态\"是否等同于健康告知所列\"抑郁症\"；\"精神疾病\"等概括性条款未明确说明时，能否作为解除/拒赔依据。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>关于第一份保险，虽然吴女士曾被医院诊断为\"抑郁状态\"，但这与保险公司在投保时被询问的\"抑郁症\"不属于同一性质，二者存在明显差别。吴女士的告知义务限于保险公司询问的范围和内容，故吴女士并未违反如实告知义务。且保险合同中的健康告知义务中所列有\"精神疾病\"，精神疾病范围宽泛、程度不一，A保险公司未对该定义予以明确说明，属于概括性条款。A保险公司以吴女士违反概括性条款的如实告知义务为由解除合同，于法无据，法院不予支持。<br>保险合同中的概括性条款是指缺乏具体内涵、外延难以界定，又未进行具体、明确的细化列举的条款。保险实践中，概括性条款常常以\"其他\"\"除上述以外\"等兜底条款的形式出现，例如\"近三年内是否患有其他疾病\"等。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： \"抑郁状态\"不等于\"抑郁症\"；健康告知中\"精神疾病\"等概括性/兜底条款，保险人未明确说明的，不得作为解除依据（司法解释二 §6 第二款）。抗辩概括性询问的权威素材。</p>\n<p><strong>关联法条</strong>：保险法 §16；司法解释二 §6（概括性条款）</p>\n<hr>\n<h2 id=\"s9\">案例 9：重疾险\"遗传性疾病\"免责，仅黑体字印刷不构成明确说明，判赔 25 万</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（媒体报道未披露；白云区法院一审、广州中院二审）</li>\n<li><strong>审理法院 / 审级</strong>：广东省广州市中级人民法院 · 二审（一审：广州市白云区人民法院；二审驳回上诉维持）</li>\n<li><strong>裁判日期</strong>：未检索到（南方都市报报道于 2026-07-09）</li>\n<li><strong>来源 URL</strong>：https://so.html5.qq.com/page/real/search_news?docid=70000021_3636a4f77d761152 （原始报道：南方都市报，记者赵青，通讯员池锐燕、吴彤彤、姚晓琳）</li>\n<li><strong>可信度</strong>：B（媒体对广州法院公开审结案例的报道，含承办法官\"白云区法院法官吴彤彤\"说法原文）</li>\n<li><strong>关键词标签</strong>：重疾险、遗传性疾病、免责条款、明确说明、双目失明</li>\n</ul>\n<p><strong>基本事实</strong>： 2016 年 11 月金女士为幼子投保重疾险（保额 25 万，终身）。2019 年起孩子双眼发病，2023 年 6 月确诊\"双眼家族性渗出性玻璃体视网膜病变\"，视力达\"双目失明\"理赔标准。保险公司以属免责条款\"遗传性疾病\"拒赔。2025 年诉至白云区法院，一审判决赔付 25 万；保险公司上诉，广州中院二审驳回上诉、维持原判。</p>\n<p><strong>争议焦点</strong>： \"遗传性疾病\"作为专业医学概念，保险人仅以黑体字印刷、电话回访笼统提及，是否构成\"明确说明\"，免责条款是否生效。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>根据《中华人民共和国保险法》第十七条、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（二）》第十三条的规定，保险人负有举证证明自身已向投保人充分履行条款说明义务的法定责任。<br>\"遗传性疾病\"是一个专业性极强的医学概念，其涵盖范围、具体种类均非普通投保人所能知晓。保险人仅在合同中用黑体字印刷该词语，或仅在电话回访中笼统提及，并不足以构成\"明确说明\"。保险人必须就\"遗传性疾病\"的具体指向、概念、种类以及免责的法律后果等内容，向投保人作出常人能够理解的解释说明。本案中，保险公司未能提供充分证据证明其已履行此项义务，故该免责条款依法对小豆子不产生效力。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： 专业医学概念（遗传性疾病、先天性疾病等）免责，仅黑体印刷/回访笼统提及 ≠ 明确说明；保险人须就概念、种类、后果作常人可理解解释，否则免责不生效。对接案例 3、4 的\"明确说明\"体系。</p>\n<p><strong>关联法条</strong>：保险法 §17；司法解释二 §11（明确说明）、§13（说明义务举证责任）</p>\n<hr>\n<h2 id=\"s10\">案例 10：故意隐瞒糖尿病投保医疗险，保险公司解除合同拒赔获支持（反面）</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（韶关市浈江区法院官网发布时未列明）</li>\n<li><strong>审理法院 / 审级</strong>：广东省韶关市浈江区人民法院 · 一审</li>\n<li><strong>裁判日期</strong>：未检索到（浈江法院官网发布）</li>\n<li><strong>来源 URL</strong>：https://sgzjfy.gov.cn/web/content?gid=1961&amp;lmdm=1004</li>\n<li><strong>可信度</strong>：B（韶关市浈江区人民法院官网）</li>\n<li><strong>关键词标签</strong>：医疗险、故意不告知、糖尿病、合同解除、投保人败诉</li>\n</ul>\n<p><strong>基本事实</strong>： 2017 年 10 月老冉确诊糖尿病并住院。2018 年 6 月其为减少医疗开支投保医疗保险（保额 205 万），在保险人询问糖尿病病史时隐瞒。2019 年 12 月老冉因糖尿病及并发症住院花 18.5 万，申请理赔被拒并解除合同。老冉起诉请求确认解除无效并赔付 10.27 万。法院审理认为其故意隐瞒，判决驳回诉讼请求。</p>\n<p><strong>争议焦点</strong>： 投保人明知患病、保险人询问时故意不告知的，保险人是否享有解除权并免责。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>《中华人民共和国保险法》第十六条规定：\"订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。投保人故意或者因重大过失未履行前款规定的如实告知义务，足以影响保险人决定是否同意承保或者提高保险费率的，保险人有权解除合同……投保人故意不履行如实告知义务的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，并不退还保险费。\"<br>本案中，老冉在投保时明知自己患有糖尿病，但在保险人询问该情况时未如实告知，属于故意不履行如实告知义务的情形。而老冉未如实告知的行为足以影响保险人决定是否同意承保或者提高保险费率，因此，保险公司享有合同解除权，并不承担给付保险金以及退还保险费的责任。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： （反面教材）投保人\"明知+询问+故意不告\"构成故意违反告知义务，保险人解除权成立并免责不退费。用于向客户提示如实告知红线，也用于识别\"不可代理\"的恶意带病投保案件。</p>\n<p><strong>关联法条</strong>：保险法 §16（故意不告知后果）</p>\n<hr>\n<h2 id=\"s11\">案例 11：甲状腺癌带病投保，保险人在体检已知情后超 30 日未解除合同，须赔付</h2>\n<ul>\n<li><strong>案号</strong>：(2018)粤03民终19925号（二审）；一审未检索到具体案号</li>\n<li><strong>审理法院 / 审级</strong>：广东省深圳市中级人民法院 · 二审（来源标注\"经本网站编辑整理\"）</li>\n<li><strong>裁判日期</strong>：未检索到（二审案号显示 2018 年审结）</li>\n<li><strong>来源 URL</strong>：http://www.mslaw0755.com/artcile/817.html</li>\n<li><strong>可信度</strong>：C（深圳保险律师网整理，非法院原文；标\"待核验\"，裁判要旨不得直接引用，仅供线索）</li>\n<li><strong>关键词标签</strong>：甲状腺癌、如实告知、解除权 30 日、体检、待核验</li>\n</ul>\n<p><strong>基本事实</strong>： 林某某投保后，保险公司在指定医院为其体检，结果显示甲状腺双侧叶多发结节（2016-11-09）。保险公司知悉该结果后未在法定期限内解除合同。后林某某确诊甲状腺癌申请理赔，保险公司以\"未如实告知甲状腺/甲状旁腺疾病、原因不明包块\"拒赔。本案进入二审（深圳中院）。</p>\n<p><strong>争议焦点</strong>： 保险人在投保人投保前体检中已发现甲状腺结节却未在 30 日内解除合同的，能否再以\"未如实告知\"拒赔。</p>\n<p><strong>裁判理由（原文摘录）【转述，非原文（律所整理）】</strong>：</p>\n<blockquote>二审法院认为，依据《中华人民共和国保险法》第十六条的规定，投保人在订立保险合同时负有如实告知义务，若投保人故意或重大过失未履行前述义务，足以影响保险人是否同意承保或者提高保险费率的，保险人有权解除合同，但该解除权自保险人知道有解除事由之日起，超过三十日不行使而消灭，发生保险事故的，保险人应当承担赔偿或者给付保险金的责任。本案中，林某某2016年11月9日在保险公司指定的广东省第二人民医院进行体检，体检结果显示甲状腺双侧叶多发结节。保险公司在知悉林某某上述体检结果后并未在法定期限内解除合同。<br>裁判结果：判决保险公司承担保险责任。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： （待核验）保险人于投保前体检已掌握异常、却未在 30 日解除权期限内行使的，解除权消灭，仍须赔付。可作为\"解除权期间抗辩\"的线索，但须以裁判文书网/深圳中院原文核验后再引用。</p>\n<p><strong>关联法条</strong>：保险法 §16（解除权 30 日/二年除斥期间）</p>\n<hr>\n<h2 id=\"s12\">案例 12（区域外参考 · 北京）：少儿重疾险\"基因检测确诊\"罕见病，格式条款滞后不得拒赔</h2>\n<ul>\n<li><strong>案号</strong>：未公开案号（北京金融法院\"金融案鉴\"栏目发布，未列明）</li>\n<li><strong>审理法院 / 审级</strong>：北京金融法院 · 二审（一审支持赔付，二审维持）</li>\n<li><strong>裁判日期</strong>：二审 2025-09（报道载明\"2025年9月北京金融法院二审驳回保险公司上诉，维持原判\"）</li>\n<li><strong>来源 URL</strong>：https://bjfc.bjcourt.gov.cn/cac/1780976087973.html （北京金融法院官网\"金融案鉴\"；另见 bjfc.bjcourt.gov.cn/cac/1780469803225.html）</li>\n<li><strong>可信度</strong>：B（北京金融法院官网\"金融案鉴\"栏目，属任务指定优先来源）</li>\n<li><strong>关键词标签</strong>：重疾险、罕见病、杜氏肌营养不良、基因检测、健康保险管理办法§23、免责条款</li>\n</ul>\n<p><strong>基本事实</strong>： 幼童小浩（化名）投保少儿重疾险。两岁多确诊为杜氏肌营养不良症（严重肌营养不良）。保险公司以\"未提交合同约定的肌电图、肌肉活检报告\"为由拒赔。家长以血液基因检测确诊报告主张理赔，诉至法院。一审法院判赔，保险公司上诉。北京金融法院二审维持，患儿获赔 100 万元。</p>\n<p><strong>争议焦点</strong>： 重疾险条款要求以\"肌电图/肌肉活检\"等传统方式确诊，与现行医学\"基因检测金标准\"冲突时，应否以格式条款滞后为由支持理赔。</p>\n<p><strong>裁判理由（原文摘录）</strong>：</p>\n<blockquote>我国《健康保险管理办法》规定，保险公司在健康保险产品条款中约定的疾病诊断标准，应当符合通行的医学诊断标准，并考虑到医疗技术条件发展的趋势。健康保险合同生效后，被保险人根据通行的医学诊断标准被确诊疾病的，保险公司不得以该诊断标准与保险合同约定不符为由拒绝给付保险金。<br>北京金融法院认为，健康险条款需参照医学共识动态更新，与诊疗实践同步发展。保险公司不得以格式条款的滞后性为由，拒绝基于现行医学标准的合理理赔。这既是法律的要求，也是行业诚信经营的基本准则。<br>二审判决书中写道：商业保险既要严格遵循契约精神，恪守合同约定，也要蕴含必要的人文关怀，兼顾公平正义。</blockquote>\n<p><strong>裁判要旨 / 对我的用处</strong>： （北京参考）健康保险管理办法 §23 是直接武器：被保险人依通行医学标准（如基因检测）确诊的，保险人不得以\"诊断方式与合同不符\"拒赔。格式条款滞后于医学发展的，不阻却赔付。广东案件可类比援引该部门规章与裁判说理。</p>\n<p><strong>关联法条</strong>：保险法 §17；健康保险管理办法 §23（诊断标准须符合通行医学标准）</p>\n<hr>\n<h2 id=\"s13\">检索缺口</h2>\n<p>以下争议类型本次<strong>想找但未检索到可靠来源（广东优先）</strong>，供后续补采：</p>\n<ol>\n<li><strong>重疾险\"微创/介入手术 vs 开胸开腹条款\"的广东判例</strong>：案例 3（广州中院）已覆盖主动脉支架，但<strong>冠状动脉介入（支架）、心脏瓣膜微创、腹腔镜</strong>等细分术式在广东的判例尚未单独检索到，建议补采。</li>\n<li><strong>\"质子重离子治疗\"拒赔</strong>：仅检索到深圳人保健康医疗险含质子重离子责任（案例线索见杨以轩案，C 级待核验），但未见广东法院就该责任拒赔的明确判例。</li>\n<li><strong>百万医疗险\"院外特效药/ CAR-T 药\"拒赔</strong>：未检索到广东法院典型判例。</li>\n<li><strong>\"两年不可抗辩条款\"在广东重疾险中的直接适用判例</strong>：案例 11 涉及解除权期间，但未检索到直接以\"合同成立超二年不得解除\"判赔的广东公开判例（多在律师文章中被提及，需以裁判文书网核验）。</li>\n<li><strong>\"等待期内的检查、等待期后确诊\"在医疗险中的广东判例</strong>：案例 5 为防癌险（重疾类），普通百万医疗险的等待期临界认定未见专门广东判例。</li>\n<li><strong>\"既往症\"条款在广东法院被认定有效的正面判例（保险公司胜诉）</strong>：本次多为投保人胜诉，缺保险公司胜诉的\"既往症\"广东判例对照（仅老冉为故意不告知胜诉，非典型既往症）。</li>\n<li><strong>团体重疾险\"投保人=单位、员工未告知\"的广东中院原文判例</strong>：检索到律所文章引 (2026)粤01民终4391号、(2026)粤01民终10449号，但均为律所营销文（C 级），需以广州中院官网/裁判文书网核验后补采。</li>\n<li><strong>佛山、东莞、珠海等地中院原创重疾/医疗险典型案例</strong>：本次广东案例集中广州、深圳、江门、韶关、开平；佛山仅检索到 (2022)粤06民终10101号、(2015)佛中法民二终字第612号（均 C 级待核验），东莞仅检索到癫痫相关一审（C 级），建议定向补采佛、莞、珠中院官网。</li>\n</ol>", "toc": [{"id": "s1", "lv": 2, "t": "案例 1：互联网投保重疾险，\"隐藏式询问\"不构成未如实告知，保险公司败诉"}, {"id": "s2", "lv": 2, "t": "案例 2：医疗险投保前已确诊高血压 2 级未告知，投保人败诉"}, {"id": "s3", "lv": 2, "t": "案例 3：限定\"开胸/开腹\"手术方式的重疾险格式条款无效，二审改判赔付"}, {"id": "s4", "lv": 2, "t": "案例 4：重疾险\"疾病释义\"条款限缩理赔范围，应视为免责条款"}, {"id": "s5", "lv": 2, "t": "案例 5：等待期内发现疑似、等待期后病理确诊癌症，保险公司不得拒赔"}, {"id": "s6", "lv": 2, "t": "案例 6：百万医疗险未告知\"早搏\"，法院以保险人未尽术语解释义务判赔"}, {"id": "s7", "lv": 2, "t": "案例 7：百万医疗险鼻咽癌，投保前两年外的病史不属告知范围，二审维持赔付"}, {"id": "s8", "lv": 2, "t": "案例 8：抑郁病史重疾险，\"抑郁状态\"≠\"抑郁症\"，概括性条款不得作拒赔依据"}, {"id": "s9", "lv": 2, "t": "案例 9：重疾险\"遗传性疾病\"免责，仅黑体字印刷不构成明确说明，判赔 25 万"}, {"id": "s10", "lv": 2, "t": "案例 10：故意隐瞒糖尿病投保医疗险，保险公司解除合同拒赔获支持（反面）"}, {"id": "s11", "lv": 2, "t": "案例 11：甲状腺癌带病投保，保险人在体检已知情后超 30 日未解除合同，须赔付"}, {"id": "s12", "lv": 2, "t": "案例 12（区域外参考 · 北京）：少儿重疾险\"基因检测确诊\"罕见病，格式条款滞后不得拒赔"}, {"id": "s13", "lv": 2, "t": "检索缺口"}], "text": "重疾险 / 医疗险 · 案例库 采集日期：2026 09 16 ｜ 采集人：AI 检索 ｜ 可信度分级：A=裁判文书原文 / B=法院官网或官媒 / C=二手来源待核验 本节共 12 个案例。B 级 = 法院官方/官媒来源（可直接采用）；C 级 = 二手来源，待核验，不得直接引用裁判要旨。 其中：广东案例 11 个，北京案例 1 个（北京金融法院\"金融案鉴\"，属优先来源，作区域外参考）；B 级 11 个，C 级 1 个。 有二审（含中院二审）的案例：案例 1、2、3、4、5、7、11、12，共 8 个。 案例 1：互联网投保重疾险，\"隐藏式询问\"不构成未如实告知，保险公司败诉 案号 ：未公开案号（广州中院发布典型案例时隐名） 审理法院 / 审级 ：广东省广州市中级人民法院 · 二审（一审：广州市基层法院；来源页面未列明一审具体法院） 裁判日期 ：未检索到（广州中院于 2023 09 14 发布该典型案例） 来源 URL ：https://www.gzcourt.gov.cn/yqfkdt/ck597/2023/09/14114347831.html 可信度 ：B（广州市中级人民法院官网发布之\"广州法院保险纠纷典型案例\"） 关键词标签 ：如实告知、互联网投保、乳腺囊肿、询问方式、有问方有答 基本事实 ： 2019 年，李某通过互联网为自己购买重大疾病保险，条款涵盖恶性肿瘤。投保页面中，关于乳腺类疾病的询问需多次点击缺乏明确指示意义的向下箭头\"∨\"才能看到，李某因而未看到该项询问。李某曾明确询问投保客服是否需上传体检报告，客服表示不用。李某体检报告中有乳腺囊肿记录，但投保时未勾选告知。2021 年 2 月 7 日李某确诊\"右乳浸润性癌\"，申请理赔被拒（理由：不实告知）。李某起诉要求支付 65 万元。一审判决保险公司赔付；保险公司上诉，广州中院二审驳回上诉、维持原判。 争议焦点 ： 投保页面将乳腺疾病询问隐藏于折叠箭头之后，是否足以认定投保人\"未如实告知\"；网络投保场景下保险人询问是否应\"易于识别\"。 裁判理由（原文摘录） ： 《中华人民共和国保险法》第十六条第一款规定：\"订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。\"据此，投保人履行如实告知义务以保险人提出询问为前提。有问方有答，保险公司提出的询问，应当易于识别，否则不应轻易认定投保人未尽到如实告知义务。 本案中，根据李某提供的投保页面，并无法直接看到关于乳腺类疾病的询问或选项，投保人需多次点击缺乏明确指示意义的向下箭头\"∨\"才能看到乳腺疾病包括乳腺结节、包块、囊肿或肿物的内容。该投保流程的设置较为隐蔽，很容易导致投保人漏看或跳过。因此，从保险公司关于案涉争议告知事项的询问设置来看，不足以认定李某未勾选乳腺囊肿选项构成不如实告知相关事项的故意或重大过失。 裁判要旨 / 对我的用处 ： 网络投保中，保险人询问须\"易于识别\"；将关键健康询问隐藏于折叠页面，不能轻易认定投保人未尽告知义务。代理互联网投保拒赔案件时，第一步即固定投保页面流程证据。 关联法条 ：保险法 §16（如实告知，有问方有答）、§17（提示说明） 案例 2：医疗险投保前已确诊高血压 2 级未告知，投保人败诉 案号 ：未公开案号（广州中院发布典型案例时隐名） 审理法院 / 审级 ：广东省广州市中级人民法院 · 二审（一审同前隐名） 裁判日期 ：未检索到（广州中院于 2023 09 14 发布） 来源 URL ：https://www.gzcourt.gov.cn/yqfkdt/ck597/2023/09/14114347831.html 可信度 ：B（广州市中级人民法院官网） 关键词标签 ：如实告知、医疗险、高血压、故意不告知、投保人败诉 基本事实 ： 2018 年 10 月王某被诊断为高血压 2 级。2019 年 2 月，投保人张某（为王某）在线购买医疗保险，询问项含\"是否曾有 2 级或以上高血压（收缩压 160mmHg，舒张压 100mmHg）\"，张某勾选\"否\"。保险期内王某因脑出血、高血压 2 级住院，保险公司以未告知高血压 2 级为由拒赔并拟解除合同。王某诉请确认解除无效并赔付。一审驳回；广州中院二审驳回上诉、维持原判。 争议焦点 ： 投保前已被医疗机构明确诊断\"高血压 2 级\"并治疗，投保人主张\"血压值未达询问标准故无须告知\"是否成立。 裁判理由（原文摘录） ： 如实告知义务是最大诚信原则在保险法中的重要体现，是保险合同有效成立的基础，也是保险合同的基本行为准则。对保险人就被保险人的有关情况提出的询问，投保人应当如实告知。 本案中，针对被保险人有无\"2级及以上高血压（收缩压大于160mmHg，舒张压大于100mmHg）\"的疾病或症状，保险公司已提出了明确易懂的询问。一般人均可理解，该询问需要投保人如实回答。在已被医疗机构明确诊断为高血压2级并进行治疗的情况下，王某以其血压值未达到\"收缩压大于160mmHg，舒张压大于100mmHg\"为由，主张其不属于高血压2级，故无须告知高血压2级的事实。该主张与医疗机构已作出的诊断及实际治疗情况明显不符，张某投保时隐瞒了王某在投保前不久被诊断为高血压2级的事实，明显与案涉保单询问的要求不符，违反了如实告知义务，故本案判决驳回了王某的诉讼请求。 裁判要旨 / 对我的用处 ： 与案例 1 相反：保险人已作\"明确易懂\"的询问且医疗机构已有明确诊断的，未告知即构成违反如实告知义务，投保人败诉。可用于对比说明\"询问是否清晰\"是胜负分界。 关联法条 ：保险法 §16（如实告知义务） 案例 3：限定\"开胸/开腹\"手术方式的重疾险格式条款无效，二审改判赔付 案号 ：未公开案号（广州中院发布典型案例时隐名） 审理法院 / 审级 ：广东省广州市中级人民法院 · 二审（一审驳回，二审改判） 裁判日期 ：未检索到（广州中院于 2023 09 14 发布） 来源 URL ：https://www.gzcourt.gov.cn/yqfkdt/ck597/2023/09/14114347831.html 可信度 ：B（广州市中级人民法院官网） 关键词标签 ：疾病释义/手术方式限定、主动脉夹层、格式条款无效、微创介入、免责条款 基本事实 ： 2014 年张某投保，条款约定主动脉手术赔付须\"实际实施了开胸或开腹进行的切除、置换、修补病损主动脉血管的手术\"。2021 年张某确诊主动脉夹层，行\"主动脉覆膜支架腔内隔绝术\"（微创，非开胸开腹）。保险公司以手术方式不符拒赔。一审驳回；广州中院二审改判保险公司支付保险金 111,750 元。 争议焦点 ： 限定手术方式为\"开胸或开腹\"的格式条款，是否属于免责条款；未充分提示说明时是否对被保险人不生效。 裁判理由（原文摘录） ： 对保险合同中免除保险人责任的条款，保险人应当履行提示说明义务。保险合同中限定疾病治疗手术方式的格式条款，排除了被保险人选择合理医疗服务的权利，属于免责条款。保险人未就此进行充分提示说明的，该条款对被保险人不发生法律效力。 案涉保险合同的相关条款将手术方式限定为开胸或者开腹，限制了被保险人在紧急情况下接受合理医疗服务的权利，也超出了一般人在订立合同时的合理预期范围，背离了一般人的通常认知和通行的治疗方法，实际免除或者减轻了保险人的保险责任，故应视为免责条款。本案中保险公司未能举证其已就此履行提示和明确说明义务，因此保险合同中限定手术方式的条款对张某不发生效力，故保险公司应向张某支付保险金。 裁判要旨 / 对我的用处 ： \"开胸/开腹\"等限定手术方式的条款，因排除合理医疗选择权、背离通行诊疗标准，应视为免责条款；保险人未尽提示说明义务的，条款不生效。代理微创手术（支架、介入）拒赔案件的核心武器。 关联法条 ：保险法 §17（免责条款提示说明）、司法解释二 §9（免责条款界定）、§11（明确说明） 案例 4：重疾险\"疾病释义\"条款限缩理赔范围，应视为免责条款 案号 ：一审 (2021)粤0104民初3622号；二审 (2021)粤01民终12850号 审理法院 / 审级 ：广东省广州市中级人民法院 · 二审（一审：广州市越秀区人民法院） 裁判日期 ：二审 2021 09 06（一审 2021 04 06） 来源 URL ：https://www.guangzhou315.com/html/web/anlifenxi/26243.html （中消协 2021 2022 年度\"全国消费维权十大典型司法案例\"；原判载《人民法院案例选》2023 年第 3 辑，编写人：广州中院 李杰、白云区法院 段静楠） 可信度 ：B（中国消费者协会发布十大典型司法案例；原始刊载于《人民法院案例选》） 关键词标签 ：疾病释义、下腔静脉滤器、限缩理赔、免责条款、明确说明 基本事实 ： 2019 年温某向百年人寿广东分公司投保重疾险（保额 20 万）。2020 年温某因左下肢深静脉血栓入院，行\"下腔静脉滤器植入术\"等。保险公司以该手术不满足条款中\"反复肺栓塞发作\"条件为由拒赔。温某起诉。一审判决（越秀法院）支持赔付；广州中院二审维持，判保险公司支付保险金 70,000 元、退还保费 5,350 元并豁免后续保费。 争议焦点 ： \"疾病释义\"条款（将理赔限于特定手术/症状条件）背离通常认知与通行诊疗标准、限缩理赔范围的，是否应视为免责条款。 裁判理由（原文摘录） ： 保险合同中的\"疾病释义\"条款如背离了一般人的通常认知和通行的诊疗标准，限缩了疾病的理赔范围，实际免除或者减轻了保险人的保险责任，应视为免责条款，保险人应向投保人履行提示说明义务，否则该条款不成为保险合同的内容，对投保人不发生效力。 法院判决认为，保险合同中的\"疾病释义\"条款背离了一般人的通常认知和通行的诊疗标准，限缩了疾病的理赔范围，实际免除或者减轻了保险人的保险责任，应视为免责条款，而被告未就该条款的概念、内容和法律后果对原告作出解释说明，故该条款对原告不发生效力，被告应向原告支付保险金 70000 元，向温某退还保险费 5350 元，豁免温某 2020 年 2 月 7 日后的各期保险费。 裁判要旨 / 对我的用处 ： 重疾险条款中各种\"释义/附加条件\"（如要求特定手术、特定症状持续时间）若限缩保障范围，按司法解释二 §9 视为免责条款，保险人未尽明确说明则不生效。此案为最高参考价值的\"疾病释义\"标杆案。 关联法条 ：保险法 §17、司法解释二 §9（免责条款界定）、民法典 §496（格式条款）、健康保险管理办法 §23 案例 5：等待期内发现疑似、等待期后病理确诊癌症，保险公司不得拒赔 案号 ：一审 (2018)粤0104民初3661号；二审 (2018)粤01民终11900号 审理法院 / 审级 ：广东省广州市中级人民法院 · 二审（一审：广州市越秀区人民法院） 裁判日期 ：二审 2018 08 22（一审 2018 04 03） 来源 URL ：https://court.yuexiu.gov.cn/index.php?s=/Show/index/cid/213/id/1461.html （广州市越秀区人民法院官网\"典型案例\"） 可信度 ：B（广州市越秀区人民法院官网） 关键词标签 ：等待期、确诊时间、病理报告、防癌险、胶质母细胞瘤 基本事实 ： 2016 年 8 月陈某为妻子钟某珍投保国寿防癌疾病保险及附加防癌两全保险（保额各 10 万，45 年）。等待期一年。2016 年 8 月 16 日（等待期内）钟某珍做检查，2016 年 8 月 23 日（等待期内）病理确诊为胶质母细胞瘤 WHO IV 级。2017 年 9 月申请理赔，保险公司以\"等待期内发现恶性肿瘤\"只退保费、终止合同。钟某珍诉请赔付并继续履行。一审支持；广州中院二审维持。 争议焦点 ： 重大疾病\"确诊时间\"应以病理报告出具日为准，还是以等待期内发现疑似/初诊日为准。 裁判理由（原文摘录） ： 【裁判要旨】保险合同以一年为界限设立等待期，确定保险责任……当被保险人因重大疾病就诊并接受医院相关检查出具初诊报告的事实的发生在等待期内，但主张在合同生效一年后才确诊的，如何认定重大疾病确诊时间成为了本案的关键。确诊时间根据病理报告单出具日来进行确定的，保险公司不能以被保险人在等待期内已经发现恶性肿瘤为由拒绝理赔。 保险公司不能以被保险人在等待期内已经发现疑似恶性肿瘤为由拒绝理赔。 裁判要旨 / 对我的用处 ： 等待期争议的\"确诊时间\"认定标准——以病理报告出具日为准，而非等待期内初诊/疑似日。代理等待期临界案件时，紧扣\"确诊\"的医学定义与病理报告日期。 关联法条 ：保险法 §13、§30（格式条款不利解释）；原判决引用合同法 §60、§107 案例 6：百万医疗险未告知\"早搏\"，法院以保险人未尽术语解释义务判赔 案号 ：未公开案号（广州市荔湾区人民法院官网发布时未列明） 审理法院 / 审级 ：广东省广州市荔湾区人民法院 · 一审（判决已生效） 裁判日期 ：未检索到（荔湾法院于 2026 03 发布） 来源 URL ：http://lwfy.gzcourt.gov.cn/fhys/2026/03/500546209344734.html 可信度 ：B（广州市荔湾区人民法院官网） 关键词标签 ：百万医疗险、如实告知、专业术语、心律失常、早搏、解释义务 基本事实 ： 2019 年陈先生为妻子何女士投保百万医疗险及住院费用补偿医疗险，连续续保。2024 年初何女士因乙流致胸闷住院，诊断\"频发性室性期前收缩\"（早搏），个人自付 1.1 万余元。理赔时保险公司以\"投保前存在多年早搏病史、早搏属心律失常却未告知\"拒赔。何女士称医生从未告知\"早搏属心律失常\"，投保时保险公司也未解释。荔湾法院判决保险公司支付理赔款 1.1 万余元，已生效。 争议焦点 ： \"心律失常\"作为专业医学术语，保险人未向投保人解释其涵盖\"早搏\"的，能否以投保人未告知\"早搏\"为由拒赔。 裁判理由（原文摘录） ： 本案是一起因专业术语理解偏差引发的人身保险合同纠纷。根据保险法相关规定，投保人的如实告知义务，以保险公司的明确询问为前提，投保人只需在保险公司询问的范围内如实作答。若双方对询问内容存在争议，举证责任由保险公司承担。 本案中，投保单的病史询问仅提及\"心律失常\"，但\"心律失常\"作为一个专业医学术语，其具体涵盖范围并非普通消费者能够准确理解。 裁判要旨 / 对我的用处 ： 专业医学术语（如\"心律失常\"）的询问范围存在争议时，举证责任在保险人；保险人未解释术语涵义的，不能将\"未告知\"归责于投保人。百万医疗险健康告知纠纷的常用抗辩。 关联法条 ：保险法 §16、§17；司法解释二 §11（明确说明）、§6（询问范围举证） 案例 7：百万医疗险鼻咽癌，投保前两年外的病史不属告知范围，二审维持赔付 案号 ：未公开案号（开平法院、江门中院发布时未列明） 审理法院 / 审级 ：广东省江门市中级人民法院 · 二审（一审：开平市人民法院；二审维持） 裁判日期 ：未检索到（开平法院于 2024 09 发布） 来源 URL ：https://www.kpcourt.gov.cn/fydt/dxal/202409/t987716.html 可信度 ：B（开平市人民法院官网，二审由江门中院维持） 关键词标签 ：百万医疗险、如实告知、两年期限、鼻咽癌、询问范围 基本事实 ： 2021 年 4 月刘某芳为父亲刘某网上投保百万医疗保险和住院保（各 1 年）。2021 年 6 月刘某确诊鼻咽癌，申请理赔被拒（理由：未告知两年内健康异常），保险公司单方解除合同。刘某芳起诉请求确认解除无效并赔付 5 万余元。开平法院一审支持；保险公司上诉，江门中院二审驳回上诉、维持原判。 争议焦点 ： 保险人询问限于\"最近两年\"健康异常，投保人既往（2012、2016 年）已痊愈病史是否属告知范围。 裁判理由（原文摘录） ： 法院审理认为：刘某芳向某保险公司投保的两份人身保险合同中，保险人询问的范围是被保险人最近两年因健康异常住院、手术或检查发现异常的情况……而刘某过往的病史发生在2012年和2016年，均在刘某芳投保涉案保险两年前发生且已痊愈，故不属于涉案保险合同要求投保人必须告知的范围。某保险公司以刘某上述诊疗记录主张刘某芳知道或者应当知道刘某在投保时存在相关健康异常依据不足。 人民法院对\"健康告知\"中\"投保前两年内\"这一期限严格把控，即投保人的告知义务限于保险人询问的范围，保险人没有询问的内容，投保人无需主动告知，并结合投保人并非医学专业人士的实际情况和保险公司的举证情况，确认投保人和被保险人并未违反如实告知义务，该保险合同仍然有效。 裁判要旨 / 对我的用处 ： 健康告知的\"期限\"（如\"近两年\"）应严格按询问把控；超期且已痊愈的病史不属告知范围，保险人不能倒查多年旧病史主张解除。反驳\"带病投保\"拒赔的利器。 关联法条 ：保险法 §16；司法解释二 §6（告知限于询问范围及内容） 案例 8：抑郁病史重疾险，\"抑郁状态\"≠\"抑郁症\"，概括性条款不得作拒赔依据 案号 ：未公开案号（人民法院报/广东省高院微博发布时未列明） 审理法院 / 审级 ：广东省深圳市罗湖区人民法院 · 一审（判决已生效） 裁判日期 ：未检索到（发布渠道为\"人民法院报\"\"广东省高级人民法院\"官方微博\"身边的鹏法\"） 来源 URL ：https://weibo.com/2187110962/OiErl1Q0I?type=repost 可信度 ：B（人民法院报、广东省高级人民法院、深圳市罗湖区法院官方微博联合发布） 关键词标签 ：重疾险、如实告知、概括性条款、抑郁状态、精神疾病 基本事实 ： 2021 年吴女士分两次投保同一重疾险（各 10 万，20 年）。2021 年 11 月确诊\"神经上皮肿瘤\"申请理赔。保险公司核查第一份合同发现其 2019 年曾被诊断\"抑郁状态\"，以违反\"精神疾病\"健康告知为由解除第一份合同；第二份合同以\"90 天等待期内出险\"拒赔。吴女士诉请赔付 20 万。法院判决：第一份合同\"抑郁状态\"与询问的\"抑郁症\"性质不同，未违反告知，且\"精神疾病\"属概括性条款未明确说明，解除无效，判赔 10 万；第二份合同处于等待期，不赔。判决生效。 争议焦点 ： \"抑郁状态\"是否等同于健康告知所列\"抑郁症\"；\"精神疾病\"等概括性条款未明确说明时，能否作为解除/拒赔依据。 裁判理由（原文摘录） ： 关于第一份保险，虽然吴女士曾被医院诊断为\"抑郁状态\"，但这与保险公司在投保时被询问的\"抑郁症\"不属于同一性质，二者存在明显差别。吴女士的告知义务限于保险公司询问的范围和内容，故吴女士并未违反如实告知义务。且保险合同中的健康告知义务中所列有\"精神疾病\"，精神疾病范围宽泛、程度不一，A保险公司未对该定义予以明确说明，属于概括性条款。A保险公司以吴女士违反概括性条款的如实告知义务为由解除合同，于法无据，法院不予支持。 保险合同中的概括性条款是指缺乏具体内涵、外延难以界定，又未进行具体、明确的细化列举的条款。保险实践中，概括性条款常常以\"其他\"\"除上述以外\"等兜底条款的形式出现，例如\"近三年内是否患有其他疾病\"等。 裁判要旨 / 对我的用处 ： \"抑郁状态\"不等于\"抑郁症\"；健康告知中\"精神疾病\"等概括性/兜底条款，保险人未明确说明的，不得作为解除依据（司法解释二 §6 第二款）。抗辩概括性询问的权威素材。 关联法条 ：保险法 §16；司法解释二 §6（概括性条款） 案例 9：重疾险\"遗传性疾病\"免责，仅黑体字印刷不构成明确说明，判赔 25 万 案号 ：未公开案号（媒体报道未披露；白云区法院一审、广州中院二审） 审理法院 / 审级 ：广东省广州市中级人民法院 · 二审（一审：广州市白云区人民法院；二审驳回上诉维持） 裁判日期 ：未检索到（南方都市报报道于 2026 07 09） 来源 URL ：https://so.html5.qq.com/page/real/search news?docid=70000021 3636a4f77d761152 （原始报道：南方都市报，记者赵青，通讯员池锐燕、吴彤彤、姚晓琳） 可信度 ：B（媒体对广州法院公开审结案例的报道，含承办法官\"白云区法院法官吴彤彤\"说法原文） 关键词标签 ：重疾险、遗传性疾病、免责条款、明确说明、双目失明 基本事实 ： 2016 年 11 月金女士为幼子投保重疾险（保额 25 万，终身）。2019 年起孩子双眼发病，2023 年 6 月确诊\"双眼家族性渗出性玻璃体视网膜病变\"，视力达\"双目失明\"理赔标准。保险公司以属免责条款\"遗传性疾病\"拒赔。2025 年诉至白云区法院，一审判决赔付 25 万；保险公司上诉，广州中院二审驳回上诉、维持原判。 争议焦点 ： \"遗传性疾病\"作为专业医学概念，保险人仅以黑体字印刷、电话回访笼统提及，是否构成\"明确说明\"，免责条款是否生效。 裁判理由（原文摘录） ： 根据《中华人民共和国保险法》第十七条、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（二）》第十三条的规定，保险人负有举证证明自身已向投保人充分履行条款说明义务的法定责任。 \"遗传性疾病\"是一个专业性极强的医学概念，其涵盖范围、具体种类均非普通投保人所能知晓。保险人仅在合同中用黑体字印刷该词语，或仅在电话回访中笼统提及，并不足以构成\"明确说明\"。保险人必须就\"遗传性疾病\"的具体指向、概念、种类以及免责的法律后果等内容，向投保人作出常人能够理解的解释说明。本案中，保险公司未能提供充分证据证明其已履行此项义务，故该免责条款依法对小豆子不产生效力。 裁判要旨 / 对我的用处 ： 专业医学概念（遗传性疾病、先天性疾病等）免责，仅黑体印刷/回访笼统提及 ≠ 明确说明；保险人须就概念、种类、后果作常人可理解解释，否则免责不生效。对接案例 3、4 的\"明确说明\"体系。 关联法条 ：保险法 §17；司法解释二 §11（明确说明）、§13（说明义务举证责任） 案例 10：故意隐瞒糖尿病投保医疗险，保险公司解除合同拒赔获支持（反面） 案号 ：未公开案号（韶关市浈江区法院官网发布时未列明） 审理法院 / 审级 ：广东省韶关市浈江区人民法院 · 一审 裁判日期 ：未检索到（浈江法院官网发布） 来源 URL ：https://sgzjfy.gov.cn/web/content?gid=1961&lmdm=1004 可信度 ：B（韶关市浈江区人民法院官网） 关键词标签 ：医疗险、故意不告知、糖尿病、合同解除、投保人败诉 基本事实 ： 2017 年 10 月老冉确诊糖尿病并住院。2018 年 6 月其为减少医疗开支投保医疗保险（保额 205 万），在保险人询问糖尿病病史时隐瞒。2019 年 12 月老冉因糖尿病及并发症住院花 18.5 万，申请理赔被拒并解除合同。老冉起诉请求确认解除无效并赔付 10.27 万。法院审理认为其故意隐瞒，判决驳回诉讼请求。 争议焦点 ： 投保人明知患病、保险人询问时故意不告知的，保险人是否享有解除权并免责。 裁判理由（原文摘录） ： 《中华人民共和国保险法》第十六条规定：\"订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。投保人故意或者因重大过失未履行前款规定的如实告知义务，足以影响保险人决定是否同意承保或者提高保险费率的，保险人有权解除合同……投保人故意不履行如实告知义务的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，并不退还保险费。\" 本案中，老冉在投保时明知自己患有糖尿病，但在保险人询问该情况时未如实告知，属于故意不履行如实告知义务的情形。而老冉未如实告知的行为足以影响保险人决定是否同意承保或者提高保险费率，因此，保险公司享有合同解除权，并不承担给付保险金以及退还保险费的责任。 裁判要旨 / 对我的用处 ： （反面教材）投保人\"明知+询问+故意不告\"构成故意违反告知义务，保险人解除权成立并免责不退费。用于向客户提示如实告知红线，也用于识别\"不可代理\"的恶意带病投保案件。 关联法条 ：保险法 §16（故意不告知后果） 案例 11：甲状腺癌带病投保，保险人在体检已知情后超 30 日未解除合同，须赔付 案号 ：(2018)粤03民终19925号（二审）；一审未检索到具体案号 审理法院 / 审级 ：广东省深圳市中级人民法院 · 二审（来源标注\"经本网站编辑整理\"） 裁判日期 ：未检索到（二审案号显示 2018 年审结） 来源 URL ：http://www.mslaw0755.com/artcile/817.html 可信度 ：C（深圳保险律师网整理，非法院原文；标\"待核验\"，裁判要旨不得直接引用，仅供线索） 关键词标签 ：甲状腺癌、如实告知、解除权 30 日、体检、待核验 基本事实 ： 林某某投保后，保险公司在指定医院为其体检，结果显示甲状腺双侧叶多发结节（2016 11 09）。保险公司知悉该结果后未在法定期限内解除合同。后林某某确诊甲状腺癌申请理赔，保险公司以\"未如实告知甲状腺/甲状旁腺疾病、原因不明包块\"拒赔。本案进入二审（深圳中院）。 争议焦点 ： 保险人在投保人投保前体检中已发现甲状腺结节却未在 30 日内解除合同的，能否再以\"未如实告知\"拒赔。 裁判理由（原文摘录）【转述，非原文（律所整理）】 ： 二审法院认为，依据《中华人民共和国保险法》第十六条的规定，投保人在订立保险合同时负有如实告知义务，若投保人故意或重大过失未履行前述义务，足以影响保险人是否同意承保或者提高保险费率的，保险人有权解除合同，但该解除权自保险人知道有解除事由之日起，超过三十日不行使而消灭，发生保险事故的，保险人应当承担赔偿或者给付保险金的责任。本案中，林某某2016年11月9日在保险公司指定的广东省第二人民医院进行体检，体检结果显示甲状腺双侧叶多发结节。保险公司在知悉林某某上述体检结果后并未在法定期限内解除合同。 裁判结果：判决保险公司承担保险责任。 裁判要旨 / 对我的用处 ： （待核验）保险人于投保前体检已掌握异常、却未在 30 日解除权期限内行使的，解除权消灭，仍须赔付。可作为\"解除权期间抗辩\"的线索，但须以裁判文书网/深圳中院原文核验后再引用。 关联法条 ：保险法 §16（解除权 30 日/二年除斥期间） 案例 12（区域外参考 · 北京）：少儿重疾险\"基因检测确诊\"罕见病，格式条款滞后不得拒赔 案号 ：未公开案号（北京金融法院\"金融案鉴\"栏目发布，未列明） 审理法院 / 审级 ：北京金融法院 · 二审（一审支持赔付，二审维持） 裁判日期 ：二审 2025 09（报道载明\"2025年9月北京金融法院二审驳回保险公司上诉，维持原判\"） 来源 URL ：https://bjfc.bjcourt.gov.cn/cac/1780976087973.html （北京金融法院官网\"金融案鉴\"；另见 bjfc.bjcourt.gov.cn/cac/1780469803225.html） 可信度 ：B（北京金融法院官网\"金融案鉴\"栏目，属任务指定优先来源） 关键词标签 ：重疾险、罕见病、杜氏肌营养不良、基因检测、健康保险管理办法§23、免责条款 基本事实 ： 幼童小浩（化名）投保少儿重疾险。两岁多确诊为杜氏肌营养不良症（严重肌营养不良）。保险公司以\"未提交合同约定的肌电图、肌肉活检报告\"为由拒赔。家长以血液基因检测确诊报告主张理赔，诉至法院。一审法院判赔，保险公司上诉。北京金融法院二审维持，患儿获赔 100 万元。 争议焦点 ： 重疾险条款要求以\"肌电图/肌肉活检\"等传统方式确诊，与现行医学\"基因检测金标准\"冲突时，应否以格式条款滞后为由支持理赔。 裁判理由（原文摘录） ： 我国《健康保险管理办法》规定，保险公司在健康保险产品条款中约定的疾病诊断标准，应当符合通行的医学诊断标准，并考虑到医疗技术条件发展的趋势。健康保险合同生效后，被保险人根据通行的医学诊断标准被确诊疾病的，保险公司不得以该诊断标准与保险合同约定不符为由拒绝给付保险金。 北京金融法院认为，健康险条款需参照医学共识动态更新，与诊疗实践同步发展。保险公司不得以格式条款的滞后性为由，拒绝基于现行医学标准的合理理赔。这既是法律的要求，也是行业诚信经营的基本准则。 二审判决书中写道：商业保险既要严格遵循契约精神，恪守合同约定，也要蕴含必要的人文关怀，兼顾公平正义。 裁判要旨 / 对我的用处 ： （北京参考）健康保险管理办法 §23 是直接武器：被保险人依通行医学标准（如基因检测）确诊的，保险人不得以\"诊断方式与合同不符\"拒赔。格式条款滞后于医学发展的，不阻却赔付。广东案件可类比援引该部门规章与裁判说理。 关联法条 ：保险法 §17；健康保险管理办法 §23（诊断标准须符合通行医学标准） 检索缺口 以下争议类型本次 想找但未检索到可靠来源（广东优先） ，供后续补采： 1. 重疾险\"微创/介入手术 vs 开胸开腹条款\"的广东判例 ：案例 3（广州中院）已覆盖主动脉支架，但 冠状动脉介入（支架）、心脏瓣膜微创、腹腔镜 等细分术式在广东的判例尚未单独检索到，建议补采。 2. \"质子重离子治疗\"拒赔 ：仅检索到深圳人保健康医疗险含质子重离子责任（案例线索见杨以轩案，C 级待核验），但未见广东法院就该责任拒赔的明确判例。 3. 百万医疗险\"院外特效药/ CAR T 药\"拒赔 ：未检索到广东法院典型判例。 4. \"两年不可抗辩条款\"在广东重疾险中的直接适用判例 ：案例 11 涉及解除权期间，但未检索到直接以\"合同成立超二年不得解除\"判赔的广东公开判例（多在律师文章中被提及，需以裁判文书网核验）。 5. \"等待期内的检查、等待期后确诊\"在医疗险中的广东判例 ：案例 5 为防癌险（重疾类），普通百万医疗险的等待期临界认定未见专门广东判例。 6. \"既往症\"条款在广东法院被认定有效的正面判例（保险公司胜诉） ：本次多为投保人胜诉，缺保险公司胜诉的\"既往症\"广东判例对照（仅老冉为故意不告知胜诉，非典型既往症）。 7. 团体重疾险\"投保人=单位、员工未告知\"的广东中院原文判例 ：检索到律所文章引 (2026)粤01民终4391号、(2026)粤01民终10449号，但均为律所营销文（C 级），需以广州中院官网/裁判文书网核验后补采。 8. 佛山、东莞、珠海等地中院原创重疾/医疗险典型案例 ：本次广东案例集中广州、深圳、江门、韶关、开平；佛山仅检索到 (2022)粤06民终10101号、(2015)佛中法民二终字第612号（均 C 级待核验），东莞仅检索到癫痫相关一审（C 级），建议定向补采佛、莞、珠中院官网。"}, {"id": "L3-输出层/01-风险点与防范点清单", "group": "4 · 工具箱", "groupKey": "L3-输出层", "title": "风险点与防范点清单（速查对照表）", "order": 4, "file": "01-风险点与防范点清单.md", "html": "<h1 id=\"s0\">风险点与防范点清单（速查对照表）</h1>\n<blockquote><strong>用法</strong>：左列是\"会出事的地方\"，右列是\"事先怎么防 / 事后怎么救\"。<br>打法细节见本站 <a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a> 篇。</blockquote>\n<hr>\n<h2 id=\"s1\">一、人身保险（重疾 / 医疗 / 寿险）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>风险点</th><th>触发场景</th><th>防范点</th><th>中招后救济</th></tr></thead><tbody>\n<tr><td>1</td><td><strong>疾病定义与条款不符</strong></td><td>确诊了，但手术方式/疾病状态不满足条款限定</td><td>投保前逐字读目标疾病的定义；注意\"确诊/手术/状态\"三类赔付条件</td><td>主张限定属隐性免责未说明（§17）；不利解释（§30）；§19 无效</td></tr>\n<tr><td>2</td><td><strong>恶性肿瘤除外清单</strong></td><td>原位癌、部分分期甲状腺癌被排除或降为轻症</td><td>看清定义使用的规范版本与除外项</td><td>同上 + 核查销售时是否有相反说明</td></tr>\n<tr><td>3</td><td><strong>健康告知未如实</strong></td><td>体检异常、既往病史未告知</td><td>问什么答什么；有异常走智能/人工核保；保留告知页截屏</td><td>攻击询问的<strong>具体性</strong>、投保人是否<strong>明知</strong>、有无<strong>因果关系</strong></td></tr>\n<tr><td>4</td><td><strong>概括性询问</strong></td><td>询问表写\"有无其他疾病\"\"身体是否异常\"</td><td>投保人侧：如实回答总没错；维权侧：概括性询问不能作为解除依据</td><td>引司法解释（二）§6②</td></tr>\n<tr><td>5</td><td><strong>等待期内出险</strong></td><td>投保后 90/180 天内确诊</td><td>有症状、已约检查时不要投保</td><td>核查等待期起算与条款约定是否一致</td></tr>\n<tr><td>6</td><td><strong>既往症定义过宽</strong></td><td>医疗险以\"投保前已患疾病\"拒赔</td><td>看清既往症定义是否限\"已明确诊断且未治愈\"</td><td>主张加重责任（§19）+ 不利解释（§30）</td></tr>\n<tr><td>7</td><td><strong>免赔额计算口径</strong></td><td>社保报销部分是否计入免赔额</td><td>投保前确认口径</td><td>按条款 + 不利解释</td></tr>\n<tr><td>8</td><td><strong>院外药/特药不报</strong></td><td>癌症院外购药</td><td>选含\"院外特药\"责任的产品或补充特药险</td><td>一般无解，重点在事前</td></tr>\n<tr><td>9</td><td><strong>非保证续保/停售</strong></td><td>一年期产品停售或理赔后拒续</td><td>优先保证续保产品，看清保证年限</td><td>若有\"可续保至X岁\"的书面承诺，主张销售误导</td></tr>\n<tr><td>10</td><td><strong>合同中止</strong></td><td>忘缴保费超过宽限期</td><td>自动扣款 + 留意通知</td><td>2 年内申请复效（需重新告知）</td></tr>\n<tr><td>11</td><td><strong>未指定受益人</strong></td><td>身故理赔变遗产、需继承程序</td><td>明确指定受益人与比例</td><td>事后只能走继承程序</td></tr>\n<tr><td>12</td><td><strong>死亡险未经被保险人同意</strong></td><td>代签名</td><td>被保险人本人确认并留痕</td><td>合同可能无效（§34），争取按解释（三）§1 认定追认</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s2\">二、意外伤害保险</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>风险点</th><th>触发场景</th><th>防范点</th><th>中招后救济</th></tr></thead><tbody>\n<tr><td>13</td><td><strong>猝死不属\"意外\"</strong></td><td>运动中猝死遭拒赔</td><td>选含猝死责任的产品</td><td>主张死亡原因属外来突发非本意；争取鉴定</td></tr>\n<tr><td>14</td><td><strong>伤残比例赔付</strong></td><td>100 万保额只赔 20 万</td><td>投保前看比例表</td><td><strong>比例赔付属免责条款</strong>（解释二§9），未提示说明不生效</td></tr>\n<tr><td>15</td><td><strong>伤残评定标准之争</strong></td><td>用行标还是人伤标准</td><td>看清合同约定的标准</td><td>标准选择本身减轻责任的，属免责条款</td></tr>\n<tr><td>16</td><td><strong>职业类别不实</strong></td><td>投保时报低类别</td><td>按实际职业投保；换工作要通知</td><td>争议时看保险人是否询问、是否提示</td></tr>\n<tr><td>17</td><td><strong>高风险运动免责</strong></td><td>潜水、攀岩、滑雪出险</td><td>看清免责范围与\"许可经营项目\"限定</td><td>主张条款范围不明 → 不利解释</td></tr>\n<tr><td>18</td><td><strong>近因之争</strong></td><td>自身疾病 + 意外共同导致</td><td>及时做因果关系鉴定</td><td>保险人不申请鉴定的，主张举证不能</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s3\">三、机动车辆保险</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>风险点</th><th>触发场景</th><th>防范点</th><th>中招后救济</th></tr></thead><tbody>\n<tr><td>19</td><td><strong>改变使用性质</strong></td><td>非营运车跑网约车/顺风车/货拉拉</td><td><strong>真跑营运就按营运投保</strong></td><td>广东口径：综合看接单频率、路线匹配度、收费性质、是否以营运为目的</td></tr>\n<tr><td>20</td><td><strong>危险程度显著增加未通知</strong></td><td>改装、长期外借、用途变更</td><td>及时书面通知保险人</td><td>司法解释（四）§4 综合判断；属订约时预见范围的不构成</td></tr>\n<tr><td>21</td><td><strong>酒驾/无证/逃逸</strong></td><td>法定免责</td><td>无</td><td>属法律禁止性规定，提示即生效（解释二§10），但仍需证明<strong>已提示</strong></td></tr>\n<tr><td>22</td><td><strong>高保低赔</strong></td><td>按新车价收保费、按折旧价赔</td><td>关注保险金额/保险价值约定</td><td>违反保险利益与诚信原则，有裁判规则支持\"高保应高赔\"</td></tr>\n<tr><td>23</td><td><strong>停运损失</strong></td><td>营运车维修期间</td><td>保留营运收入证明</td><td>因保险人拖延定损/赔付导致的，可主张（§23③）</td></tr>\n<tr><td>24</td><td><strong>定损拖延</strong></td><td>迟迟不定损、车辆被留置</td><td>书面催告 + 固定时间节点</td><td>主张核定期限违法 + 赔偿损失</td></tr>\n<tr><td>25</td><td><strong>代位求偿</strong></td><td>己方保险公司赔后追偿第三者</td><td>配合保险人；保留对第三者的权利</td><td>注意§62 对家庭成员的限制</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s4\">四、互联网平台投保（支付宝 / 微信 / 各 App）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>风险点</th><th>触发场景</th><th>防范点</th><th>中招后救济</th></tr></thead><tbody>\n<tr><td>26</td><td><strong>健康告知默认勾选\"否\"</strong></td><td>未逐条确认即完成投保</td><td>全程<strong>录屏</strong>；保存投保时页面版本</td><td>证明未完成提示说明（解释二§12）</td></tr>\n<tr><td>27</td><td><strong>一键\"已阅读并同意\"</strong></td><td>长条款一行小字</td><td>向在线客服提问具体条款含义并留痕；回访时追问</td><td>引解释二§13②<strong>但书</strong>：有其他证据证明未实际说明</td></tr>\n<tr><td>28</td><td><strong>首月 1 元/自动续费</strong></td><td>次月起高额扣费</td><td>关闭免密支付</td><td>主张未充分提示，要求退费 + 12378</td></tr>\n<tr><td>29</td><td><strong>平台与保险人的责任划分</strong></td><td>平台页面承诺与条款不一致</td><td>保存<strong>销售页面快照</strong></td><td>向平台与保险人同时主张；销售误导证据</td></tr>\n<tr><td>30</td><td><strong>电子数据由保险人掌握</strong></td><td>无法自证页面设计</td><td>申请法院责令保险人提交后台记录</td><td>举证责任在保险人（解释二§13①）</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s5\">五、程序性风险（最容易翻车，与实体理由无关）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>风险点</th><th>后果</th><th>防范点</th></tr></thead><tbody>\n<tr><td>31</td><td><strong>诉讼时效届满</strong>（非寿险 <strong>3 年</strong> / 寿险 5 年）</td><td>丧失胜诉权</td><td>谈判同时留催告证据、发律师函或起诉</td></tr>\n<tr><td>32</td><td><strong>保单约定仲裁</strong></td><td>去法院起诉被驳回</td><td><strong>起诉前先看争议解决条款</strong></td></tr>\n<tr><td>33</td><td><strong>保险人未先解除即拒赔</strong></td><td>——</td><td>这其实是<strong>我方武器</strong>：解释二§8，未行使解除权直接拒赔不予支持</td></tr>\n<tr><td>34</td><td><strong>解除权超期</strong></td><td>——</td><td>30 日（知道解除事由起）+ 2 年（合同成立起）双重限制</td></tr>\n<tr><td>35</td><td><strong>迟延损失未主张</strong></td><td>白丢一笔</td><td>依 §23③ 一并主张利息、停运损失等</td></tr>\n<tr><td>36</td><td><strong>签和解协议放弃全部权利</strong></td><td>不可逆</td><td>签字前算清全部损失，必要时先咨询</td></tr>\n<tr><td>37</td><td><strong>口头拒赔无书面文件</strong></td><td>维权无起点</td><td>坚持要求出具书面拒赔/解除通知</td></tr>\n<tr><td>38</td><td><strong>病历主诉写错</strong></td><td>被推定既往症</td><td>就诊时确认主诉准确；发现错误及时申请医院更正</td></tr>\n</tbody></table></div>\n<hr>\n<h2 id=\"s6\">六、2026 广东二审判例新增风险点（A 级）</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>风险点</th><th>后果</th><th>防范动作</th></tr></thead><tbody>\n<tr><td>56</td><td><strong>说明视频可跳过</strong></td><td>视为未说明（粤03民终8930）</td><td>投保人：投保后立刻确认视频无法跳过；维权时逐帧查勘</td></tr>\n<tr><td>57</td><td><strong>保险人拿\"通用演示视频\"当证据</strong></td><td>不是本案轨迹，无效（粤01民终24935）</td><td>要求提供<strong>本次投保可回溯记录</strong></td></tr>\n<tr><td>58</td><td><strong>免责条款引用 ICD-10 却不列明</strong></td><td>明确说明未完成（粤01民终10449）</td><td>当庭要求出示 ICD 分类具体条文</td></tr>\n<tr><td>59</td><td><strong>只加黑加粗、未解释概念</strong></td><td>只完成提示，未完成明确说明（粤01民终28133）</td><td>主张两项义务独立</td></tr>\n<tr><td>60</td><td><strong>拒赔后仍在扣保费</strong></td><td>视为未解除合同（粤03民终12700）</td><td>拿到拒赔通知立刻查银行流水</td></tr>\n<tr><td>61</td><td><strong>医疗险损失补偿 + 免赔额</strong></td><td>赢了条款只剩零头（粤01民终24935）</td><td>投保前算清\"社保内/外、免赔额\"</td></tr>\n<tr><td>62</td><td><strong>律师费诉请</strong></td><td>一般不支持（粤01民终4391）</td><td>别为不支持的诉请多交受理费</td></tr>\n<tr><td>63</td><td><strong>迟延利息未主张</strong></td><td>白丢（粤08民终2416、粤01民终4391）</td><td>一并主张 LPR 利息，成本为零</td></tr>\n<tr><td>64</td><td><strong>鉴定费未主张</strong></td><td>白丢（粤15民终501，§64）</td><td>一并主张，法院支持率高</td></tr>\n<tr><td>65</td><td><strong>保险人说\"这是保险标的/责任范围条款，不是免责\"</strong></td><td>被绕开提示说明义务</td><td>引江门 (2026)粤07民终1377号：单方限缩即实质免责，照样要说明</td></tr>\n<tr><td>66</td><td><strong>保险人只交\"示范流程/同类产品\"公证书</strong></td><td>被蒙混过关</td><td>要求其提交<strong>投保人本人</strong>的操作轨迹（阅读时长、点击路径）</td></tr>\n<tr><td>67</td><td><strong>保险人仅凭平台截图主张营运</strong></td><td>商业险整体拒赔</td><td>质证三问：谁注册的？车牌呢？问过当事人吗？</td></tr>\n<tr><td>68</td><td><strong>以为\"出险时没接单就没事\"</strong></td><td>抗辩无效</td><td>危险程度增加不因事发时未营运而改变</td></tr>\n<tr><td>69</td><td><strong>跑顺风车接单过百 / 跨市</strong></td><td>大概率被认定营运</td><td>真跑营运就按营运性质投保，唯一稳妥解</td></tr>\n<tr><td>70</td><td><strong>以为时效只有 2 年而放弃</strong></td><td>白丢权利</td><td>非寿险适用 <strong>3 年</strong>，且自实际知道之日起算</td></tr>\n<tr><td>71</td><td><strong>被盗/被毁后无法精确举证损失</strong></td><td>只赔一点或不赔</td><td>主动请求法院依举证责任分配与利益衡平<strong>酌定</strong></td></tr>\n<tr><td>72</td><td><strong>多年在同一家保险公司续保</strong></td><td>被认定\"早该知道免责条款\"</td><td>说明义务基本堵死，转向其他争点</td></tr>\n<tr><td>73</td><td><strong>保险人主张营运却拿不出可回溯记录</strong></td><td>说明义务抗辩可能奏效</td><td>佛山 (2026)粤06民终4139：仅签字声明不够</td></tr>\n</tbody></table></div>\n<h2 id=\"s7\">三个\"反直觉\"要点（最容易记反）</h2>\n<ol>\n<li><strong>不利解释不是万能钥匙。</strong> 第 30 条有顺序：先按<strong>通常理解</strong>解释，仍有两种以上解释的，才作有利于被保险人的解释。一上来就喊\"应作不利于保险人解释\"，会被法院驳回。</li>\n<li><strong>\"签字了\"确实对投保人不利。</strong> 司法解释（二）§13②规定，投保人签字/盖章确认的，<strong>应当认定</strong>保险人履行了明确说明义务。破解点在但书——要拿<strong>其他证据</strong>（聊天记录、回访录音、页面设计）证明未实际说明。</li>\n<li><strong>两年不可抗辩不是骗保保护伞。</strong> 它限制的是\"解除权\"，但对于<strong>合同成立前已发生保险事故</strong>的恶意投保，仍有争议空间；且保险人仍可在法定期间内行使解除权。</li>\n</ol>", "toc": [{"id": "s1", "lv": 2, "t": "一、人身保险（重疾 / 医疗 / 寿险）"}, {"id": "s2", "lv": 2, "t": "二、意外伤害保险"}, {"id": "s3", "lv": 2, "t": "三、机动车辆保险"}, {"id": "s4", "lv": 2, "t": "四、互联网平台投保（支付宝 / 微信 / 各 App）"}, {"id": "s5", "lv": 2, "t": "五、程序性风险（最容易翻车，与实体理由无关）"}, {"id": "s6", "lv": 2, "t": "六、2026 广东二审判例新增风险点（A 级）"}, {"id": "s7", "lv": 2, "t": "三个\"反直觉\"要点（最容易记反）"}], "text": "风险点与防范点清单（速查对照表） 用法 ：左列是\"会出事的地方\"，右列是\"事先怎么防 / 事后怎么救\"。 打法细节见本站 L0 打法层/01 八把通用武器 篇。 一、人身保险（重疾 / 医疗 / 寿险） 风险点 触发场景 防范点 中招后救济 1 疾病定义与条款不符 确诊了，但手术方式/疾病状态不满足条款限定 投保前逐字读目标疾病的定义；注意\"确诊/手术/状态\"三类赔付条件 主张限定属隐性免责未说明（§17）；不利解释（§30）；§19 无效 2 恶性肿瘤除外清单 原位癌、部分分期甲状腺癌被排除或降为轻症 看清定义使用的规范版本与除外项 同上 + 核查销售时是否有相反说明 3 健康告知未如实 体检异常、既往病史未告知 问什么答什么；有异常走智能/人工核保；保留告知页截屏 攻击询问的 具体性 、投保人是否 明知 、有无 因果关系 4 概括性询问 询问表写\"有无其他疾病\"\"身体是否异常\" 投保人侧：如实回答总没错；维权侧：概括性询问不能作为解除依据 引司法解释（二）§6② 5 等待期内出险 投保后 90/180 天内确诊 有症状、已约检查时不要投保 核查等待期起算与条款约定是否一致 6 既往症定义过宽 医疗险以\"投保前已患疾病\"拒赔 看清既往症定义是否限\"已明确诊断且未治愈\" 主张加重责任（§19）+ 不利解释（§30） 7 免赔额计算口径 社保报销部分是否计入免赔额 投保前确认口径 按条款 + 不利解释 8 院外药/特药不报 癌症院外购药 选含\"院外特药\"责任的产品或补充特药险 一般无解，重点在事前 9 非保证续保/停售 一年期产品停售或理赔后拒续 优先保证续保产品，看清保证年限 若有\"可续保至X岁\"的书面承诺，主张销售误导 10 合同中止 忘缴保费超过宽限期 自动扣款 + 留意通知 2 年内申请复效（需重新告知） 11 未指定受益人 身故理赔变遗产、需继承程序 明确指定受益人与比例 事后只能走继承程序 12 死亡险未经被保险人同意 代签名 被保险人本人确认并留痕 合同可能无效（§34），争取按解释（三）§1 认定追认 二、意外伤害保险 风险点 触发场景 防范点 中招后救济 13 猝死不属\"意外\" 运动中猝死遭拒赔 选含猝死责任的产品 主张死亡原因属外来突发非本意；争取鉴定 14 伤残比例赔付 100 万保额只赔 20 万 投保前看比例表 比例赔付属免责条款 （解释二§9），未提示说明不生效 15 伤残评定标准之争 用行标还是人伤标准 看清合同约定的标准 标准选择本身减轻责任的，属免责条款 16 职业类别不实 投保时报低类别 按实际职业投保；换工作要通知 争议时看保险人是否询问、是否提示 17 高风险运动免责 潜水、攀岩、滑雪出险 看清免责范围与\"许可经营项目\"限定 主张条款范围不明 → 不利解释 18 近因之争 自身疾病 + 意外共同导致 及时做因果关系鉴定 保险人不申请鉴定的，主张举证不能 三、机动车辆保险 风险点 触发场景 防范点 中招后救济 19 改变使用性质 非营运车跑网约车/顺风车/货拉拉 真跑营运就按营运投保 广东口径：综合看接单频率、路线匹配度、收费性质、是否以营运为目的 20 危险程度显著增加未通知 改装、长期外借、用途变更 及时书面通知保险人 司法解释（四）§4 综合判断；属订约时预见范围的不构成 21 酒驾/无证/逃逸 法定免责 无 属法律禁止性规定，提示即生效（解释二§10），但仍需证明 已提示 22 高保低赔 按新车价收保费、按折旧价赔 关注保险金额/保险价值约定 违反保险利益与诚信原则，有裁判规则支持\"高保应高赔\" 23 停运损失 营运车维修期间 保留营运收入证明 因保险人拖延定损/赔付导致的，可主张（§23③） 24 定损拖延 迟迟不定损、车辆被留置 书面催告 + 固定时间节点 主张核定期限违法 + 赔偿损失 25 代位求偿 己方保险公司赔后追偿第三者 配合保险人；保留对第三者的权利 注意§62 对家庭成员的限制 四、互联网平台投保（支付宝 / 微信 / 各 App） 风险点 触发场景 防范点 中招后救济 26 健康告知默认勾选\"否\" 未逐条确认即完成投保 全程 录屏 ；保存投保时页面版本 证明未完成提示说明（解释二§12） 27 一键\"已阅读并同意\" 长条款一行小字 向在线客服提问具体条款含义并留痕；回访时追问 引解释二§13② 但书 ：有其他证据证明未实际说明 28 首月 1 元/自动续费 次月起高额扣费 关闭免密支付 主张未充分提示，要求退费 + 12378 29 平台与保险人的责任划分 平台页面承诺与条款不一致 保存 销售页面快照 向平台与保险人同时主张；销售误导证据 30 电子数据由保险人掌握 无法自证页面设计 申请法院责令保险人提交后台记录 举证责任在保险人（解释二§13①） 五、程序性风险（最容易翻车，与实体理由无关） 风险点 后果 防范点 31 诉讼时效届满 （非寿险 3 年 / 寿险 5 年） 丧失胜诉权 谈判同时留催告证据、发律师函或起诉 32 保单约定仲裁 去法院起诉被驳回 起诉前先看争议解决条款 33 保险人未先解除即拒赔 —— 这其实是 我方武器 ：解释二§8，未行使解除权直接拒赔不予支持 34 解除权超期 —— 30 日（知道解除事由起）+ 2 年（合同成立起）双重限制 35 迟延损失未主张 白丢一笔 依 §23③ 一并主张利息、停运损失等 36 签和解协议放弃全部权利 不可逆 签字前算清全部损失，必要时先咨询 37 口头拒赔无书面文件 维权无起点 坚持要求出具书面拒赔/解除通知 38 病历主诉写错 被推定既往症 就诊时确认主诉准确；发现错误及时申请医院更正 六、2026 广东二审判例新增风险点（A 级） 风险点 后果 防范动作 56 说明视频可跳过 视为未说明（粤03民终8930） 投保人：投保后立刻确认视频无法跳过；维权时逐帧查勘 57 保险人拿\"通用演示视频\"当证据 不是本案轨迹，无效（粤01民终24935） 要求提供 本次投保可回溯记录 58 免责条款引用 ICD 10 却不列明 明确说明未完成（粤01民终10449） 当庭要求出示 ICD 分类具体条文 59 只加黑加粗、未解释概念 只完成提示，未完成明确说明（粤01民终28133） 主张两项义务独立 60 拒赔后仍在扣保费 视为未解除合同（粤03民终12700） 拿到拒赔通知立刻查银行流水 61 医疗险损失补偿 + 免赔额 赢了条款只剩零头（粤01民终24935） 投保前算清\"社保内/外、免赔额\" 62 律师费诉请 一般不支持（粤01民终4391） 别为不支持的诉请多交受理费 63 迟延利息未主张 白丢（粤08民终2416、粤01民终4391） 一并主张 LPR 利息，成本为零 64 鉴定费未主张 白丢（粤15民终501，§64） 一并主张，法院支持率高 65 保险人说\"这是保险标的/责任范围条款，不是免责\" 被绕开提示说明义务 引江门 (2026)粤07民终1377号：单方限缩即实质免责，照样要说明 66 保险人只交\"示范流程/同类产品\"公证书 被蒙混过关 要求其提交 投保人本人 的操作轨迹（阅读时长、点击路径） 67 保险人仅凭平台截图主张营运 商业险整体拒赔 质证三问：谁注册的？车牌呢？问过当事人吗？ 68 以为\"出险时没接单就没事\" 抗辩无效 危险程度增加不因事发时未营运而改变 69 跑顺风车接单过百 / 跨市 大概率被认定营运 真跑营运就按营运性质投保，唯一稳妥解 70 以为时效只有 2 年而放弃 白丢权利 非寿险适用 3 年 ，且自实际知道之日起算 71 被盗/被毁后无法精确举证损失 只赔一点或不赔 主动请求法院依举证责任分配与利益衡平 酌定 72 多年在同一家保险公司续保 被认定\"早该知道免责条款\" 说明义务基本堵死，转向其他争点 73 保险人主张营运却拿不出可回溯记录 说明义务抗辩可能奏效 佛山 (2026)粤06民终4139：仅签字声明不够 三个\"反直觉\"要点（最容易记反） 1. 不利解释不是万能钥匙。 第 30 条有顺序：先按 通常理解 解释，仍有两种以上解释的，才作有利于被保险人的解释。一上来就喊\"应作不利于保险人解释\"，会被法院驳回。 2. \"签字了\"确实对投保人不利。 司法解释（二）§13②规定，投保人签字/盖章确认的， 应当认定 保险人履行了明确说明义务。破解点在但书——要拿 其他证据 （聊天记录、回访录音、页面设计）证明未实际说明。 3. 两年不可抗辩不是骗保保护伞。 它限制的是\"解除权\"，但对于 合同成立前已发生保险事故 的恶意投保，仍有争议空间；且保险人仍可在法定期间内行使解除权。"}, {"id": "L3-输出层/02-普通人买保险的坑", "group": "4 · 工具箱", "groupKey": "L3-输出层", "title": "普通人买保险的常见坑（投保前 → 理赔后）", "order": 4, "file": "02-普通人买保险的坑.md", "html": "<h1 id=\"s0\">普通人买保险的常见坑（投保前 → 理赔后）</h1>\n<blockquote><strong>阅读对象</strong>：非专业人士。可直接转发给家人朋友。<br><strong>立场声明</strong>：本文不针对任何特定保险公司或平台，只讲<strong>产品结构与条款设计的共性风险</strong>。<br>具体以你手上的保单条款为准。看到\"支付宝 / 微信 / 某平台\"字样时，指的是<br>这类互联网渠道销售的<strong>产品形态</strong>，不是对该平台的评价。</blockquote>\n<hr>\n<h2 id=\"s1\">第一阶段 · 投保前（最容易埋雷，且不可逆）</h2>\n<h3 id=\"s2\">坑 1 · \"保费便宜\"就是好 —— 一年期重疾险的续保幻觉</h3>\n<p><strong>坑的形态</strong>：平台上 30 岁买 50 万保额的重疾险，一年只要三四百块，看着极划算。</p>\n<p><strong>为什么是坑</strong>：</p>\n<ul>\n<li>这类产品多为<strong>一年期非保证续保</strong>。今年买了，明年可能因为①产品停售 ②你理赔过 ③你身体变差 而买不上了。</li>\n<li>保费是<strong>自然费率</strong>，随年龄逐年上涨，50 岁后可能涨到几千。</li>\n<li>长期重疾险虽然贵，但锁定了<strong>保证续保 + 固定费率</strong>。</li>\n</ul>\n<p><strong>怎么防</strong>：问清三个问题——<strong>保证续保吗？保证多少年？停售后能不能转保？</strong> 答案必须写在条款里，不是销售页面上。</p>\n<p><strong>中招后怎么救</strong>：产品停售导致无法续保的，一般无解（属商业风险）。但若<strong>销售页面/客服承诺过\"可续保至 99 岁\"而条款写明\"非保证续保\"</strong>，可主张<strong>销售误导</strong>，保留页面截图投诉。</p>\n<hr>\n<h3 id=\"s3\">坑 2 · \"确诊即赔\"的误解</h3>\n<p><strong>坑的形态</strong>：以为拿到癌症诊断书就能拿到钱。</p>\n<p><strong>为什么是坑</strong>：重疾险的赔付条件通常分三类——</p>\n<ol>\n<li><strong>确诊即赔</strong>（如恶性肿瘤——注意仍有除外，见坑 3）</li>\n<li><strong>实施了特定手术才赔</strong>（如冠状动脉搭桥术——须\"实际实施了开胸手术\"）</li>\n<li><strong>达到特定状态才赔</strong>（如\"严重昏迷\"须持续 96 小时、\"脑中风后遗症\"须 180 天后仍遗留功能障碍）</li>\n</ol>\n<p>大部分纠纷出在第 2、3 类。</p>\n<p><strong>怎么防</strong>：翻到条款的\"重大疾病定义\"部分，找到你关心的病，<strong>逐字读赔付条件</strong>，特别注意括号里的限定。</p>\n<p><strong>中招后怎么救</strong>：手术方式（如微创 vs 开胸）与条款不一致时，可主张①该限定属<strong>隐性免责条款</strong>未提示说明；②按<strong>不利解释</strong>规则（§30）；③医学发展与条款滞后的，主张条款不合理免除保险人责任（§19）。</p>\n<hr>\n<h3 id=\"s4\">坑 3 · 恶性肿瘤的\"除外清单\"比你想的长</h3>\n<p><strong>坑的形态</strong>：条款把\"恶性肿瘤\"定义为重疾，但在注释里排除了好几种。</p>\n<p><strong>常见的除外</strong>：原位癌、皮肤癌（除恶性黑色素瘤）、前列腺癌 T1N0M0 期、甲状腺癌的分期限制（部分产品）、感染艾滋病期间的恶性肿瘤等。</p>\n<p><span class=\"warn\">!</span> <strong>注意</strong>：中国保险行业协会《重大疾病保险的疾病定义使用规范》会统一核心定义，<strong>2020 年后修订的版本对甲状腺癌等有分级赔付的调整</strong>。买之前看清用的是哪一版定义。</p>\n<p><strong>怎么防</strong>：不要只看\"保 120 种重疾\"这个数字，<strong>看清单里有没有你最担心的那种病，以及它被归为重疾、轻症还是除外</strong>。</p>\n<hr>\n<h3 id=\"s5\">坑 4 · 健康告知\"全填否\"的销售诱导</h3>\n<p><strong>坑的形态</strong>：代理人/客服说\"都填否就行，过了两年就赔\"\"小毛病不用管\"。</p>\n<p><strong>为什么是坑</strong>：</p>\n<ul>\n<li>两年不可抗辩条款（§16③）<strong>不是万能的</strong>，恶意不如实告知的仍有争议空间；</li>\n<li>出险后保险人查得到你的就诊记录、医保记录、体检记录；</li>\n<li>真被拒赔时，销售人员的口头承诺很难举证。</li>\n</ul>\n<p><strong>怎么防</strong>：</p>\n<ol>\n<li><strong>问什么答什么，问到的必须说实话。</strong>（法律上你只回答被问到的——见 L0 武器二）</li>\n<li>回答时<strong>保留证据</strong>：把健康告知页逐条截图，把与销售的对话保存下来。</li>\n<li>有些平台有<strong>智能核保 / 人工核保</strong>，有异常就走核保，别硬闯。</li>\n</ol>\n<p><strong>中招后怎么救</strong>：保险人拒赔时，先问它三个问题——<strong>你问了吗？问的具体吗？你问的和我的病有关系吗？</strong> 三个问题有一个答不上来，就有得打。</p>\n<hr>\n<h3 id=\"s6\">坑 5 · 等待期出险</h3>\n<p><strong>坑的形态</strong>：投保后 30–180 天（重疾常为 90 或 180 天）内确诊，保险公司不赔，只退保费。</p>\n<p><strong>怎么防</strong>：</p>\n<ul>\n<li>不要在<strong>已经出现症状、已经约了检查</strong>的时候投保——等待期内出险的争议很难打。</li>\n<li>体检和投保的<strong>顺序</strong>想清楚：先体检发现异常 → 要么如实告知，要么先别买。</li>\n</ul>\n<hr>\n<h3 id=\"s7\">坑 6 · 受益人没指定 / 写\"法定\"</h3>\n<p><strong>坑的形态</strong>：寿险、意外险身故理赔时，受益人栏默认\"法定\"。</p>\n<p><strong>后果</strong>：保险金变成<strong>遗产</strong>，要走继承程序（可能需要所有继承人到场公证），还可能被用于清偿被保险人生前债务。</p>\n<p><strong>怎么防</strong>：明确指定受益人 + 受益比例，并写明与被保险人的关系。</p>\n<hr>\n<h3 id=\"s8\">坑 7 · 给家人投保，忘了\"被保险人同意\"</h3>\n<p><strong>坑的形态</strong>：丈夫给妻子投保、父母给成年子女投保以死亡为给付条件的保险，没让被保险人签字。</p>\n<p><strong>法律后果</strong>：未经被保险人同意并认可保险金额的，<strong>合同无效</strong>（§34）。司法解释（三）第 1 条放宽了形式（可口头、可追认），但仍可能被保险人否定。</p>\n<p><strong>怎么防</strong>：死亡给付类保险，<strong>务必让被保险人本人确认</strong>并留痕。</p>\n<hr>\n<h2 id=\"s9\">第二阶段 · 投保中（互联网渠道特有）</h2>\n<h3 id=\"s10\">坑 8 · 健康告知页\"默认勾选否\"</h3>\n<p><strong>坑的形态</strong>：页面的健康告知<strong>默认全部为\"否\"</strong>，或者下一步按钮可<strong>不阅读直接点击</strong>。</p>\n<p><strong>法律后果</strong>：这正是司法解释（二）第 12 条要管的对象——<strong>网页必须真正完成提示和明确说明</strong>。没有强制阅读停留、没有逐条确认的，保险人未必尽到了义务。</p>\n<p><strong>怎么防（同时也是取证）</strong>：</p>\n<ol>\n<li><strong>全程录屏</strong>，从商品页到支付完成。</li>\n<li>故意在某条点\"是\"，看系统是否真的弹出核保流程——可以验证页面是否只是形式。</li>\n<li>保存<strong>投保时的页面版本</strong>（有的平台提供\"查看投保时页面\"入口）。</li>\n</ol>\n<hr>\n<h3 id=\"s11\">坑 9 · \"我已阅读并同意\"的一键勾选</h3>\n<p><strong>坑的形态</strong>：长长的条款链接躺在一行小字里，一个勾选框管所有。</p>\n<p><strong>法律风险点</strong>：司法解释（二）第 13 条第 2 款规定，投保人在相关文书上签字/盖章确认的，<strong>应当认定保险人履行了明确说明义务</strong>——这个规定对消费者不利。<strong>破解点是\"但书\"</strong>：有其他证据证明保险人未实际履行的除外。</p>\n<p><strong>怎么防</strong>：除了录屏，还可以①主动向在线客服提问\"这个免责条款是什么意思\"，<strong>留下对话记录</strong>；②电话回访时<strong>明确追问</strong>具体条款含义（回访是有录音的）。</p>\n<hr>\n<h3 id=\"s12\">坑 10 · 首月 1 元 / \"免费领取\"陷阱</h3>\n<p><strong>坑的形态</strong>：首月 1 元、0 元领保障，次月开始自动扣费几十上百元。</p>\n<p><strong>怎么防</strong>：关闭自动续费 / 免密支付；看清<strong>全年总保费</strong>而不是首月价格。中招的可主张<strong>未充分提示</strong>，要求退费并投诉 12378。</p>\n<hr>\n<h3 id=\"s13\">坑 11 · \"保证续保\"和\"可续保\"是两回事</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>表述</th><th>含义</th></tr></thead><tbody>\n<tr><td><strong>保证续保</strong></td><td>保险人<strong>必须</strong>按原条款、原费率续保（有的写\"保证续保 20 年\"）</td></tr>\n<tr><td><strong>可续保 / 续保需审核</strong></td><td>保险人<strong>可以拒绝</strong>续保，或重新核保、调整费率</td></tr>\n<tr><td><strong>不因健康状况变化而拒绝续保</strong></td><td>只锁定\"健康\"，<strong>没锁定停售和费率</strong></td></tr>\n</tbody></table></div>\n<p><strong>怎么防</strong>：只看条款正文，<strong>不看销售页面的大字广告</strong>。</p>\n<hr>\n<h3 id=\"s14\">坑 12 · 医疗险的\"既往症\"条款</h3>\n<p><strong>坑的形态</strong>：条款约定\"既往症\"不赔，但对\"既往症\"的定义极宽（有的写\"本合同生效前已患有的疾病及症状\"，甚至\"已知或应当知道的\"）。</p>\n<p><strong>怎么防</strong>：投保时如实告知并走核保；关注是否有限定（如\"已有明确诊断且未治愈\"）。中招后可主张该定义<strong>不合理加重投保人责任</strong>（§19）+ <strong>不利解释</strong>（§30）。</p>\n<hr>\n<h3 id=\"s15\">坑 13 · 百万医疗险的免赔额</h3>\n<p><strong>坑的形态</strong>：宣传\"最高报销 600 万\"，但有 <strong>1 万免赔额</strong>，且社保报销部分<strong>不计入</strong>免赔额。</p>\n<p><strong>实际影响</strong>：住院自付 1.5 万，社保报 8 千，免赔额 1 万，<strong>可能一分不报</strong>（取决于条款是否以\"自付部分\"计算）。</p>\n<p><strong>怎么防</strong>：看清免赔额的计算口径（社保支付是否计入）、是否有\"重大疾病 0 免赔\"、家庭共享免赔等。</p>\n<hr>\n<h3 id=\"s16\">坑 14 · 院外药、外购药、进口药不报</h3>\n<p><strong>坑的形态</strong>：癌症治疗常用院外购药（医院开处方，去院外药店买），条款只报\"<strong>医院内</strong>发生的医疗费用\"。</p>\n<p><strong>怎么防</strong>：看条款里有没有\"院外特定药品费用\"\"恶性肿瘤特药\"责任；没有的，考虑单独补充特药险。</p>\n<hr>\n<h3 id=\"s17\">坑 15 · 意外险的\"意外\"定义比你窄</h3>\n<p><strong>坑的形态</strong>：以下情形常引发争议——</p>\n<ul>\n<li><strong>猝死</strong>：多数意外险不赔（属疾病），除非有\"猝死责任\"附加险；</li>\n<li><strong>中暑、高原反应、食物中毒</strong>：是否属\"意外\"争议大；</li>\n<li><strong>高风险运动</strong>（潜水、攀岩、跳伞）：多在国家旅游局许可的经营项目内才保；</li>\n<li><strong>职业类别</strong>：投保时报 1-2 类，实际从事 4-6 类（如高空作业），出险后按比例或拒赔。</li>\n</ul>\n<p><strong>怎么防</strong>：看清职业类别表、高风险运动免责、是否含猝死责任。</p>\n<hr>\n<h3 id=\"s18\">坑 16 · 伤残按\"比例赔付\"而不是全额</h3>\n<p><strong>坑的形态</strong>：意外险保额 100 万，九级伤残只赔 20 万（按《人身保险伤残评定标准》1-10 级对应 100%-10%）。</p>\n<p><strong>法律要点</strong>：司法解释（二）第 9 条明确，<strong>比例赔付条款属于\"免除或减轻保险人责任的条款\"</strong>，必须提示说明，否则不生效。</p>\n<p><strong>中招后怎么救</strong>：直接问——<strong>这个比例表你给我看过、解释过吗？</strong> 没做过，条款不生效（人民法院案例库有同类裁判规则）。</p>\n<hr>\n<h2 id=\"s19\">第三阶段 · 投保后</h2>\n<h3 id=\"s20\">坑 17 · 缴费中断导致合同中止</h3>\n<p><strong>形态</strong>：忘缴保费 → 60 天宽限期 → 合同<strong>中止</strong>（2 年内可申请复效，需重新健康告知）。</p>\n<p><strong>怎么防</strong>：绑定自动扣款 + 留意保险公司通知。中止期间出险不赔。</p>\n<h3 id=\"s21\">坑 18 · 换手机号 / 换地址没通知保险公司</h3>\n<p><strong>后果</strong>：错过缴费提醒、错过续保通知、收不到理赔决定，有时直接导致权利受损。</p>\n<h3 id=\"s22\">坑 19 · 车辆改变使用性质（车险最贵的一个坑）</h3>\n<p><strong>形态</strong>：非营运车去跑网约车、顺风车、货拉拉，出险后保险人以\"危险程度显著增加未通知\"拒赔（§52）。</p>\n<p><strong>广东判例倾向</strong>：不是\"跑过一次就拒赔\"，而是综合看<strong>接单频率、路线匹配度、收费性质、是否以营运为目的</strong>。高频接单（年上千单）基本会被认定；低频真实分摊成本的，有争取空间。</p>\n<p><strong>怎么防</strong>：真的要跑营运，就<strong>按营运性质投保</strong>。省下的保费远小于拒赔损失。</p>\n<h3 id=\"s23\">坑 20 · 病历写错一句话，理赔全卡住</h3>\n<p><strong>形态</strong>：医生在病历里写\"<strong>反复头晕 3 年</strong>\"\"<strong>既往有 XX 病史</strong>\"，保险公司据此主张既往症或不如实告知。</p>\n<p><strong>怎么防</strong>：就诊时主动提醒医生——<strong>主诉要准确</strong>，不要把多年来的模糊不适写成明确病史；发现病历写错，<strong>及时申请更正</strong>（医院有病历更正程序），不要等理赔时才发现。</p>\n<hr>\n<h2 id=\"s24\">第四阶段 · 理赔时</h2>\n<h3 id=\"s25\">坑 21 · 口头拒赔，不出具书面文件</h3>\n<p><strong>怎么防</strong>：<strong>拒绝口头拒赔</strong>。要求出具书面《拒赔通知书》或《解除合同通知书》，并注明依据的条款编号和事实理由。这是后续所有维权的起点。</p>\n<h3 id=\"s26\">坑 22 · 被要求反复补充材料，拖到时效届满</h3>\n<p><strong>怎么防</strong>：</p>\n<ol>\n<li>每次提交材料<strong>留凭证</strong>（邮件、App 上传记录、回执）；</li>\n<li>保险人要求补充的，依法应\"<strong>及时一次性</strong>通知\"（§22②）；</li>\n<li>及时起诉或至少<strong>发律师函中断诉讼时效</strong>。</li>\n</ol>\n<h3 id=\"s27\">坑 23 · 签了\"和解协议\"才发现放弃了全部权利</h3>\n<p><strong>怎么防</strong>：签署任何和解、撤诉、放弃权利的文件前，<strong>先算清楚实际损失</strong>。金额明显不合理的，可主张<strong>显失公平</strong>或<strong>重大误解</strong>请求撤销，但难度很大。<strong>签之前先咨询。</strong></p>\n<h3 id=\"s28\">坑 24 · 只盯保险金，忘了主张迟延损失</h3>\n<p><strong>要点</strong>：保险人未及时核定、未及时赔付的，<strong>除支付保险金外还应赔偿损失</strong>（§23③）。这一项很多人白丢了。</p>\n<h3 id=\"s29\">坑 25 · 超过诉讼时效</h3>\n<p><strong>底线</strong>：非寿险 <strong>2 年</strong>、寿险 <strong>5 年</strong>，自知道或应当知道保险事故发生之日起算。跟保险公司\"谈\"<strong>不当然中断时效</strong>，要留催告证据或起诉。</p>\n<hr>\n<h2 id=\"s30\">补充：2026 广东判例暴露的三个新坑</h2>\n<p><strong>坑 26 · 以为\"有说明视频\"保险公司就赢了</strong> 深圳中院 (2025)粤03民终8930号：视频<strong>直接跳转</strong>（可跳过）→ 未达\"使投保人了解\"的标准 → 免责条款无效。 👉 反过来也提醒投保人：<strong>投保时你自己也别急着跳过</strong>——因为如果视频不可跳过且内容完整，法院可能认定已履行。</p>\n<p><strong>坑 27 · 拒赔后没查银行流水</strong> 深圳中院 (2024)粤03民终12700号：保险人 2 月 10 日发拒赔通知解除合同，<strong>2 月 25 日、3 月 21 日仍在扣保费</strong> → 依解释二 §7 视为<strong>尚未解除合同</strong>，解除主张被否。 👉 拿到拒赔通知，第一件事：<strong>查扣费记录</strong>。还在扣 = 免费的杀手锏。</p>\n<p><strong>坑 28 · 以为赢了条款就等于拿到钱</strong> 广州中院 (2025)粤01民终24935号：免责条款确实不生效，但百万医疗属<strong>补偿性合同</strong>，医保统筹已付的 4 万余元要扣除，再减 1 万免赔额 → 5.2 万诉求只剩 <strong>1,231 元</strong>。 👉 医疗险的价值 = 保额 × 赔付比例 − 医保已付 − 免赔额。投保前自己算一遍这个数。</p>\n<h2 id=\"s31\">一张图：投保前的 5 分钟自查清单</h2>\n<ol>\n<li>我要买的这个，<strong>保的是\"确诊\"、\"手术\"还是\"状态\"</strong>？</li>\n<li>我担心的那个病，<strong>在清单里吗？被除外了吗？</strong></li>\n<li><strong>保证续保吗？</strong> 保证几年？停售怎么办？</li>\n<li>健康告知的每一条我都能<strong>如实回答</strong>吗？有没有<strong>需要走核保</strong>的？</li>\n<li>免责条款里，<strong>有没有我的职业/爱好/生活习惯</strong>（高空作业、潜水、酒驾）？</li>\n<li>受益人<strong>指定</strong>了吗？</li>\n<li>页面/条款/录音，<strong>我留证据了吗？</strong>（录屏 + 保存投保时版本）</li>\n</ol>\n<h3 id=\"s32\">26 · \"我买的是家用车，偶尔跑跑顺风车没事\"</h3>\n<p><strong>这是近三年广东判决里输得最惨的一类。</strong></p>\n<p>四案口径完全一致（中山 (2025)粤20民终2567 / 中山 (2025)粤20民终1136 / 湛江 (2025)粤08民终951 / 揭阳 (2026)粤52民终425）：</p>\n<ul>\n<li>接单 <strong>47 次</strong>（跨市）就被认定营运；<strong>1548 次</strong>、<strong>1895 次</strong>、<strong>2271 单</strong>更不用说。</li>\n<li><strong>出险那一刻没在接单，也不救你</strong>——\"事发前该车辆用于营运导致危险程度显著增加的事实并不因其事发当时未进行运营而改变\"。</li>\n<li><strong>\"特惠快车\"是营运</strong>（独立非拼车收费服务），不是顺风车。</li>\n<li><strong>打不了\"保险公司没说明免责条款\"</strong>——§52 的通知义务是法定义务，提示说明抗辩法院明确不采纳。</li>\n</ul>\n<p><strong>唯一稳妥解</strong>：真跑营运就按营运性质投保。保费差额远低于商业险整体拒赔的代价。</p>\n<h3 id=\"s33\">27 · \"保险公司的免责条款写的是'违反安全装载规定'，我又不是超载\"</h3>\n<p>反过来用——<strong>这是你的武器</strong>。佛山中院 (2026)粤06民终4139号：</p>\n<blockquote>案涉保险条款……仅载明\"违反安全装载规定\"免赔，并未明确为\"超载\"，该条款足以造成对格式条款的理解发生争议。从有利于非格式条款提供方出发……</blockquote>\n<p><strong>通用打法</strong>：把<strong>拒赔通知书上用的词</strong>和<strong>合同免责条款里写的词</strong>逐字比对。不是一个词，就打 §30 不利解释。车险里这类\"宽泛条款 + 具体拒赔理由\"的组合非常多。</p>\n<h3 id=\"s34\">28 · \"金器首饰被偷了，没有发票，保险公司肯定不赔\"</h3>\n<p>江门中院 (2026)粤07民终1377号：法院综合考虑举证责任分配与利益衡平，<strong>酌定</strong>损失 5 万元。前提是<strong>你必须主动提出</strong>\"请求法院酌定\"，并且证明盗窃事实本身确实存在（报警记录、立案、监控）。</p>", "toc": [{"id": "s1", "lv": 2, "t": "第一阶段 · 投保前（最容易埋雷，且不可逆）"}, {"id": "s2", "lv": 3, "t": "坑 1 · \"保费便宜\"就是好 —— 一年期重疾险的续保幻觉"}, {"id": "s3", "lv": 3, "t": "坑 2 · \"确诊即赔\"的误解"}, {"id": "s4", "lv": 3, "t": "坑 3 · 恶性肿瘤的\"除外清单\"比你想的长"}, {"id": "s5", "lv": 3, "t": "坑 4 · 健康告知\"全填否\"的销售诱导"}, {"id": "s6", "lv": 3, "t": "坑 5 · 等待期出险"}, {"id": "s7", "lv": 3, "t": "坑 6 · 受益人没指定 / 写\"法定\""}, {"id": "s8", "lv": 3, "t": "坑 7 · 给家人投保，忘了\"被保险人同意\""}, {"id": "s9", "lv": 2, "t": "第二阶段 · 投保中（互联网渠道特有）"}, {"id": "s10", "lv": 3, "t": "坑 8 · 健康告知页\"默认勾选否\""}, {"id": "s11", "lv": 3, "t": "坑 9 · \"我已阅读并同意\"的一键勾选"}, {"id": "s12", "lv": 3, "t": "坑 10 · 首月 1 元 / \"免费领取\"陷阱"}, {"id": "s13", "lv": 3, "t": "坑 11 · \"保证续保\"和\"可续保\"是两回事"}, {"id": "s14", "lv": 3, "t": "坑 12 · 医疗险的\"既往症\"条款"}, {"id": "s15", "lv": 3, "t": "坑 13 · 百万医疗险的免赔额"}, {"id": "s16", "lv": 3, "t": "坑 14 · 院外药、外购药、进口药不报"}, {"id": "s17", "lv": 3, "t": "坑 15 · 意外险的\"意外\"定义比你窄"}, {"id": "s18", "lv": 3, "t": "坑 16 · 伤残按\"比例赔付\"而不是全额"}, {"id": "s19", "lv": 2, "t": "第三阶段 · 投保后"}, {"id": "s20", "lv": 3, "t": "坑 17 · 缴费中断导致合同中止"}, {"id": "s21", "lv": 3, "t": "坑 18 · 换手机号 / 换地址没通知保险公司"}, {"id": "s22", "lv": 3, "t": "坑 19 · 车辆改变使用性质（车险最贵的一个坑）"}, {"id": "s23", "lv": 3, "t": "坑 20 · 病历写错一句话，理赔全卡住"}, {"id": "s24", "lv": 2, "t": "第四阶段 · 理赔时"}, {"id": "s25", "lv": 3, "t": "坑 21 · 口头拒赔，不出具书面文件"}, {"id": "s26", "lv": 3, "t": "坑 22 · 被要求反复补充材料，拖到时效届满"}, {"id": "s27", "lv": 3, "t": "坑 23 · 签了\"和解协议\"才发现放弃了全部权利"}, {"id": "s28", "lv": 3, "t": "坑 24 · 只盯保险金，忘了主张迟延损失"}, {"id": "s29", "lv": 3, "t": "坑 25 · 超过诉讼时效"}, {"id": "s30", "lv": 2, "t": "补充：2026 广东判例暴露的三个新坑"}, {"id": "s31", "lv": 2, "t": "一张图：投保前的 5 分钟自查清单"}, {"id": "s32", "lv": 3, "t": "26 · \"我买的是家用车，偶尔跑跑顺风车没事\""}, {"id": "s33", "lv": 3, "t": "27 · \"保险公司的免责条款写的是'违反安全装载规定'，我又不是超载\""}, {"id": "s34", "lv": 3, "t": "28 · \"金器首饰被偷了，没有发票，保险公司肯定不赔\""}], "text": "普通人买保险的常见坑（投保前 → 理赔后） 阅读对象 ：非专业人士。可直接转发给家人朋友。 立场声明 ：本文不针对任何特定保险公司或平台，只讲 产品结构与条款设计的共性风险 。 具体以你手上的保单条款为准。看到\"支付宝 / 微信 / 某平台\"字样时，指的是 这类互联网渠道销售的 产品形态 ，不是对该平台的评价。 第一阶段 · 投保前（最容易埋雷，且不可逆） 坑 1 · \"保费便宜\"就是好 —— 一年期重疾险的续保幻觉 坑的形态 ：平台上 30 岁买 50 万保额的重疾险，一年只要三四百块，看着极划算。 为什么是坑 ： 这类产品多为 一年期非保证续保 。今年买了，明年可能因为①产品停售 ②你理赔过 ③你身体变差 而买不上了。 保费是 自然费率 ，随年龄逐年上涨，50 岁后可能涨到几千。 长期重疾险虽然贵，但锁定了 保证续保 + 固定费率 。 怎么防 ：问清三个问题—— 保证续保吗？保证多少年？停售后能不能转保？ 答案必须写在条款里，不是销售页面上。 中招后怎么救 ：产品停售导致无法续保的，一般无解（属商业风险）。但若 销售页面/客服承诺过\"可续保至 99 岁\"而条款写明\"非保证续保\" ，可主张 销售误导 ，保留页面截图投诉。 坑 2 · \"确诊即赔\"的误解 坑的形态 ：以为拿到癌症诊断书就能拿到钱。 为什么是坑 ：重疾险的赔付条件通常分三类—— 1. 确诊即赔 （如恶性肿瘤——注意仍有除外，见坑 3） 2. 实施了特定手术才赔 （如冠状动脉搭桥术——须\"实际实施了开胸手术\"） 3. 达到特定状态才赔 （如\"严重昏迷\"须持续 96 小时、\"脑中风后遗症\"须 180 天后仍遗留功能障碍） 大部分纠纷出在第 2、3 类。 怎么防 ：翻到条款的\"重大疾病定义\"部分，找到你关心的病， 逐字读赔付条件 ，特别注意括号里的限定。 中招后怎么救 ：手术方式（如微创 vs 开胸）与条款不一致时，可主张①该限定属 隐性免责条款 未提示说明；②按 不利解释 规则（§30）；③医学发展与条款滞后的，主张条款不合理免除保险人责任（§19）。 坑 3 · 恶性肿瘤的\"除外清单\"比你想的长 坑的形态 ：条款把\"恶性肿瘤\"定义为重疾，但在注释里排除了好几种。 常见的除外 ：原位癌、皮肤癌（除恶性黑色素瘤）、前列腺癌 T1N0M0 期、甲状腺癌的分期限制（部分产品）、感染艾滋病期间的恶性肿瘤等。 ⚠️ 注意 ：中国保险行业协会《重大疾病保险的疾病定义使用规范》会统一核心定义， 2020 年后修订的版本对甲状腺癌等有分级赔付的调整 。买之前看清用的是哪一版定义。 怎么防 ：不要只看\"保 120 种重疾\"这个数字， 看清单里有没有你最担心的那种病，以及它被归为重疾、轻症还是除外 。 坑 4 · 健康告知\"全填否\"的销售诱导 坑的形态 ：代理人/客服说\"都填否就行，过了两年就赔\"\"小毛病不用管\"。 为什么是坑 ： 两年不可抗辩条款（§16③） 不是万能的 ，恶意不如实告知的仍有争议空间； 出险后保险人查得到你的就诊记录、医保记录、体检记录； 真被拒赔时，销售人员的口头承诺很难举证。 怎么防 ： 1. 问什么答什么，问到的必须说实话。 （法律上你只回答被问到的——见 L0 武器二） 2. 回答时 保留证据 ：把健康告知页逐条截图，把与销售的对话保存下来。 3. 有些平台有 智能核保 / 人工核保 ，有异常就走核保，别硬闯。 中招后怎么救 ：保险人拒赔时，先问它三个问题—— 你问了吗？问的具体吗？你问的和我的病有关系吗？ 三个问题有一个答不上来，就有得打。 坑 5 · 等待期出险 坑的形态 ：投保后 30–180 天（重疾常为 90 或 180 天）内确诊，保险公司不赔，只退保费。 怎么防 ： 不要在 已经出现症状、已经约了检查 的时候投保——等待期内出险的争议很难打。 体检和投保的 顺序 想清楚：先体检发现异常 → 要么如实告知，要么先别买。 坑 6 · 受益人没指定 / 写\"法定\" 坑的形态 ：寿险、意外险身故理赔时，受益人栏默认\"法定\"。 后果 ：保险金变成 遗产 ，要走继承程序（可能需要所有继承人到场公证），还可能被用于清偿被保险人生前债务。 怎么防 ：明确指定受益人 + 受益比例，并写明与被保险人的关系。 坑 7 · 给家人投保，忘了\"被保险人同意\" 坑的形态 ：丈夫给妻子投保、父母给成年子女投保以死亡为给付条件的保险，没让被保险人签字。 法律后果 ：未经被保险人同意并认可保险金额的， 合同无效 （§34）。司法解释（三）第 1 条放宽了形式（可口头、可追认），但仍可能被保险人否定。 怎么防 ：死亡给付类保险， 务必让被保险人本人确认 并留痕。 第二阶段 · 投保中（互联网渠道特有） 坑 8 · 健康告知页\"默认勾选否\" 坑的形态 ：页面的健康告知 默认全部为\"否\" ，或者下一步按钮可 不阅读直接点击 。 法律后果 ：这正是司法解释（二）第 12 条要管的对象—— 网页必须真正完成提示和明确说明 。没有强制阅读停留、没有逐条确认的，保险人未必尽到了义务。 怎么防（同时也是取证） ： 1. 全程录屏 ，从商品页到支付完成。 2. 故意在某条点\"是\"，看系统是否真的弹出核保流程——可以验证页面是否只是形式。 3. 保存 投保时的页面版本 （有的平台提供\"查看投保时页面\"入口）。 坑 9 · \"我已阅读并同意\"的一键勾选 坑的形态 ：长长的条款链接躺在一行小字里，一个勾选框管所有。 法律风险点 ：司法解释（二）第 13 条第 2 款规定，投保人在相关文书上签字/盖章确认的， 应当认定保险人履行了明确说明义务 ——这个规定对消费者不利。 破解点是\"但书\" ：有其他证据证明保险人未实际履行的除外。 怎么防 ：除了录屏，还可以①主动向在线客服提问\"这个免责条款是什么意思\"， 留下对话记录 ；②电话回访时 明确追问 具体条款含义（回访是有录音的）。 坑 10 · 首月 1 元 / \"免费领取\"陷阱 坑的形态 ：首月 1 元、0 元领保障，次月开始自动扣费几十上百元。 怎么防 ：关闭自动续费 / 免密支付；看清 全年总保费 而不是首月价格。中招的可主张 未充分提示 ，要求退费并投诉 12378。 坑 11 · \"保证续保\"和\"可续保\"是两回事 表述 含义 保证续保 保险人 必须 按原条款、原费率续保（有的写\"保证续保 20 年\"） 可续保 / 续保需审核 保险人 可以拒绝 续保，或重新核保、调整费率 不因健康状况变化而拒绝续保 只锁定\"健康\"， 没锁定停售和费率 怎么防 ：只看条款正文， 不看销售页面的大字广告 。 坑 12 · 医疗险的\"既往症\"条款 坑的形态 ：条款约定\"既往症\"不赔，但对\"既往症\"的定义极宽（有的写\"本合同生效前已患有的疾病及症状\"，甚至\"已知或应当知道的\"）。 怎么防 ：投保时如实告知并走核保；关注是否有限定（如\"已有明确诊断且未治愈\"）。中招后可主张该定义 不合理加重投保人责任 （§19）+ 不利解释 （§30）。 坑 13 · 百万医疗险的免赔额 坑的形态 ：宣传\"最高报销 600 万\"，但有 1 万免赔额 ，且社保报销部分 不计入 免赔额。 实际影响 ：住院自付 1.5 万，社保报 8 千，免赔额 1 万， 可能一分不报 （取决于条款是否以\"自付部分\"计算）。 怎么防 ：看清免赔额的计算口径（社保支付是否计入）、是否有\"重大疾病 0 免赔\"、家庭共享免赔等。 坑 14 · 院外药、外购药、进口药不报 坑的形态 ：癌症治疗常用院外购药（医院开处方，去院外药店买），条款只报\" 医院内 发生的医疗费用\"。 怎么防 ：看条款里有没有\"院外特定药品费用\"\"恶性肿瘤特药\"责任；没有的，考虑单独补充特药险。 坑 15 · 意外险的\"意外\"定义比你窄 坑的形态 ：以下情形常引发争议—— 猝死 ：多数意外险不赔（属疾病），除非有\"猝死责任\"附加险； 中暑、高原反应、食物中毒 ：是否属\"意外\"争议大； 高风险运动 （潜水、攀岩、跳伞）：多在国家旅游局许可的经营项目内才保； 职业类别 ：投保时报 1 2 类，实际从事 4 6 类（如高空作业），出险后按比例或拒赔。 怎么防 ：看清职业类别表、高风险运动免责、是否含猝死责任。 坑 16 · 伤残按\"比例赔付\"而不是全额 坑的形态 ：意外险保额 100 万，九级伤残只赔 20 万（按《人身保险伤残评定标准》1 10 级对应 100% 10%）。 法律要点 ：司法解释（二）第 9 条明确， 比例赔付条款属于\"免除或减轻保险人责任的条款\" ，必须提示说明，否则不生效。 中招后怎么救 ：直接问—— 这个比例表你给我看过、解释过吗？ 没做过，条款不生效（人民法院案例库有同类裁判规则）。 第三阶段 · 投保后 坑 17 · 缴费中断导致合同中止 形态 ：忘缴保费 → 60 天宽限期 → 合同 中止 （2 年内可申请复效，需重新健康告知）。 怎么防 ：绑定自动扣款 + 留意保险公司通知。中止期间出险不赔。 坑 18 · 换手机号 / 换地址没通知保险公司 后果 ：错过缴费提醒、错过续保通知、收不到理赔决定，有时直接导致权利受损。 坑 19 · 车辆改变使用性质（车险最贵的一个坑） 形态 ：非营运车去跑网约车、顺风车、货拉拉，出险后保险人以\"危险程度显著增加未通知\"拒赔（§52）。 广东判例倾向 ：不是\"跑过一次就拒赔\"，而是综合看 接单频率、路线匹配度、收费性质、是否以营运为目的 。高频接单（年上千单）基本会被认定；低频真实分摊成本的，有争取空间。 怎么防 ：真的要跑营运，就 按营运性质投保 。省下的保费远小于拒赔损失。 坑 20 · 病历写错一句话，理赔全卡住 形态 ：医生在病历里写\" 反复头晕 3 年 \"\" 既往有 XX 病史 \"，保险公司据此主张既往症或不如实告知。 怎么防 ：就诊时主动提醒医生—— 主诉要准确 ，不要把多年来的模糊不适写成明确病史；发现病历写错， 及时申请更正 （医院有病历更正程序），不要等理赔时才发现。 第四阶段 · 理赔时 坑 21 · 口头拒赔，不出具书面文件 怎么防 ： 拒绝口头拒赔 。要求出具书面《拒赔通知书》或《解除合同通知书》，并注明依据的条款编号和事实理由。这是后续所有维权的起点。 坑 22 · 被要求反复补充材料，拖到时效届满 怎么防 ： 1. 每次提交材料 留凭证 （邮件、App 上传记录、回执）； 2. 保险人要求补充的，依法应\" 及时一次性 通知\"（§22②）； 3. 及时起诉或至少 发律师函中断诉讼时效 。 坑 23 · 签了\"和解协议\"才发现放弃了全部权利 怎么防 ：签署任何和解、撤诉、放弃权利的文件前， 先算清楚实际损失 。金额明显不合理的，可主张 显失公平 或 重大误解 请求撤销，但难度很大。 签之前先咨询。 坑 24 · 只盯保险金，忘了主张迟延损失 要点 ：保险人未及时核定、未及时赔付的， 除支付保险金外还应赔偿损失 （§23③）。这一项很多人白丢了。 坑 25 · 超过诉讼时效 底线 ：非寿险 2 年 、寿险 5 年 ，自知道或应当知道保险事故发生之日起算。跟保险公司\"谈\" 不当然中断时效 ，要留催告证据或起诉。 补充：2026 广东判例暴露的三个新坑 坑 26 · 以为\"有说明视频\"保险公司就赢了 深圳中院 (2025)粤03民终8930号：视频 直接跳转 （可跳过）→ 未达\"使投保人了解\"的标准 → 免责条款无效。 👉 反过来也提醒投保人： 投保时你自己也别急着跳过 ——因为如果视频不可跳过且内容完整，法院可能认定已履行。 坑 27 · 拒赔后没查银行流水 深圳中院 (2024)粤03民终12700号：保险人 2 月 10 日发拒赔通知解除合同， 2 月 25 日、3 月 21 日仍在扣保费 → 依解释二 §7 视为 尚未解除合同 ，解除主张被否。 👉 拿到拒赔通知，第一件事： 查扣费记录 。还在扣 = 免费的杀手锏。 坑 28 · 以为赢了条款就等于拿到钱 广州中院 (2025)粤01民终24935号：免责条款确实不生效，但百万医疗属 补偿性合同 ，医保统筹已付的 4 万余元要扣除，再减 1 万免赔额 → 5.2 万诉求只剩 1,231 元 。 👉 医疗险的价值 = 保额 × 赔付比例 − 医保已付 − 免赔额。投保前自己算一遍这个数。 一张图：投保前的 5 分钟自查清单 1. 我要买的这个， 保的是\"确诊\"、\"手术\"还是\"状态\" ？ 2. 我担心的那个病， 在清单里吗？被除外了吗？ 3. 保证续保吗？ 保证几年？停售怎么办？ 4. 健康告知的每一条我都能 如实回答 吗？有没有 需要走核保 的？ 5. 免责条款里， 有没有我的职业/爱好/生活习惯 （高空作业、潜水、酒驾）？ 6. 受益人 指定 了吗？ 7. 页面/条款/录音， 我留证据了吗？ （录屏 + 保存投保时版本） 26 · \"我买的是家用车，偶尔跑跑顺风车没事\" 这是近三年广东判决里输得最惨的一类。 四案口径完全一致（中山 (2025)粤20民终2567 / 中山 (2025)粤20民终1136 / 湛江 (2025)粤08民终951 / 揭阳 (2026)粤52民终425）： 接单 47 次 （跨市）就被认定营运； 1548 次 、 1895 次 、 2271 单 更不用说。 出险那一刻没在接单，也不救你 ——\"事发前该车辆用于营运导致危险程度显著增加的事实并不因其事发当时未进行运营而改变\"。 \"特惠快车\"是营运 （独立非拼车收费服务），不是顺风车。 打不了\"保险公司没说明免责条款\" ——§52 的通知义务是法定义务，提示说明抗辩法院明确不采纳。 唯一稳妥解 ：真跑营运就按营运性质投保。保费差额远低于商业险整体拒赔的代价。 27 · \"保险公司的免责条款写的是'违反安全装载规定'，我又不是超载\" 反过来用—— 这是你的武器 。佛山中院 (2026)粤06民终4139号： 案涉保险条款……仅载明\"违反安全装载规定\"免赔，并未明确为\"超载\"，该条款足以造成对格式条款的理解发生争议。从有利于非格式条款提供方出发…… 通用打法 ：把 拒赔通知书上用的词 和 合同免责条款里写的词 逐字比对。不是一个词，就打 §30 不利解释。车险里这类\"宽泛条款 + 具体拒赔理由\"的组合非常多。 28 · \"金器首饰被偷了，没有发票，保险公司肯定不赔\" 江门中院 (2026)粤07民终1377号：法院综合考虑举证责任分配与利益衡平， 酌定 损失 5 万元。前提是 你必须主动提出 \"请求法院酌定\"，并且证明盗窃事实本身确实存在（报警记录、立案、监控）。"}, {"id": "L3-输出层/03-生活比喻库", "group": "4 · 工具箱", "groupKey": "L3-输出层", "title": "生活比喻库", "order": 4, "file": "03-生活比喻库.md", "html": "<h1 id=\"s0\">生活比喻库</h1>\n<blockquote><strong>用途</strong>：给普通人讲保险法律知识时用的弹药库。<br>每个条目 = 法律概念 + 生活比喻 + 一句话内核 + 什么时候用。<br>比喻不追求法律严谨，追求<strong>第一次听就能懂</strong>。</blockquote>\n<hr>\n<h2 id=\"s1\">一、投保环节</h2>\n<h3 id=\"s2\">如实告知义务</h3>\n<p><strong>比喻</strong>：相亲时\"问什么答什么\"。对方没问你有没有房，你不用主动交代；但问了就得说实话。反过来，对方问一句\"你人应该没啥问题吧\"这种含糊问题，等于没问——法律上叫<strong>概括性询问</strong>，不能拿来当拒赔理由。 <strong>内核</strong>：告知义务以保险人的<strong>具体询问</strong>为边界。 <strong>什么时候用</strong>：保险人说\"你没如实告知\"时，先反问\"你问了吗？怎么问的？\"</p>\n<h3 id=\"s3\">最大诚信原则</h3>\n<p><strong>比喻</strong>：普通买卖是\"买方自行小心\"，保险是\"双方都得把牌摊开\"。尤其保险人，手里握着全部信息和条款，就必须多承担一分诚实的义务。 <strong>内核</strong>：保险合同的诚信要求<strong>高于</strong>一般合同。</p>\n<h3 id=\"s4\">保险利益</h3>\n<p><strong>比喻</strong>：你不能给邻居家的房子买火灾险然后盼着它着火。只有\"这东西出事你会真的心疼/真的损失\"的人，才能给它投保。 <strong>内核</strong>：防止把保险变成赌博和道德风险的工具。</p>\n<h3 id=\"s5\">等待期</h3>\n<p><strong>比喻</strong>：新员工的试用期。这段时间出事，公司（保险公司）可以说\"还没转正\"。重疾险常见 90 天或 180 天。 <strong>内核</strong>：防止带病投保的道德风险。</p>\n<h3 id=\"s6\">犹豫期</h3>\n<p><strong>比喻</strong>：网购的七天无理由退货。签收后十到十五天内反悔，全额退保费。 <strong>内核</strong>：给投保人一次\"后悔药\"。</p>\n<h3 id=\"s7\">核保</h3>\n<p><strong>比喻</strong>：入职体检。保险公司根据结果决定：正常录取 / 加钱录取 / 某个部位不保 / 不录取。</p>\n<h3 id=\"s8\">现金价值</h3>\n<p><strong>比喻</strong>：这张保单的\"二手残值\"。刚买的前两年退保，能拿回来的钱可能只有保费的零头——因为你交的钱里，大头被销售佣金、管理费、风险保费吃掉了。 <strong>内核</strong>：退保 ≠ 退保费。</p>\n<hr>\n<h2 id=\"s9\">二、条款环节</h2>\n<h3 id=\"s10\">提示说明义务</h3>\n<p><strong>比喻</strong>：药品说明书的\"黑框警告\"。药厂不能把严重不良反应塞在说明书第 38 页的小字里，然后说\"你自己没看\"。必须印在盒子最显眼的地方，还得让你看得懂。 <strong>内核</strong>：免责条款必须<strong>提示</strong>（看得见）+ <strong>明确说明</strong>（看得懂），缺一不可。</p>\n<h3 id=\"s11\">隐性免责条款</h3>\n<p><strong>比喻</strong>：菜单的\"推荐菜\"栏里写着\"本店不提供\"。它长得不像免责，效果却一模一样。 <strong>内核</strong>：写在\"保险责任\"章节里、实际免除保险人责任的条款，照样要提示说明。</p>\n<h3 id=\"s12\">免责条款的范围（免赔额、比例赔付也算）</h3>\n<p><strong>比喻</strong>：不光\"本店概不负责\"是免责，\"每单最高赔 20 元\"\"只赔八折\"同样是在减你的权利，也得说清楚。 <strong>内核</strong>：司法解释（二）第 9 条把免赔额、免赔率、比例赔付都纳入免责条款。</p>\n<h3 id=\"s13\">不利解释规则</h3>\n<p><strong>比喻</strong>：格式合同是出题人自己出的卷子。卷子出得含糊，分数判给考生，不判给出题人。 <strong>内核</strong>：有两种以上解释时，作有利于被保险人和受益人的解释。</p>\n<h3 id=\"s14\">格式条款无效（第 19 条）</h3>\n<p><strong>比喻</strong>：不是所有\"签字了就认\"的条款都算数。霸王条款签了字照样可以认定无效。 <strong>内核</strong>：免除保险人法定义务、加重投保人责任、排除投保人权利的条款无效。</p>\n<h3 id=\"s15\">伤残比例赔付</h3>\n<p><strong>比喻</strong>：不是\"伤了就赔全款\"，而是按等级打折：一级 100%，十级 10%。 <strong>内核</strong>：比例赔付属免责条款，未提示说明不生效。</p>\n<h3 id=\"s16\">既往症</h3>\n<p><strong>比喻</strong>：买二手车时的\"旧伤\"。卖家说\"这车之前碰过的地方我不负责\"，但得在合同里<strong>写清楚</strong>哪些算旧伤。 <strong>内核</strong>：既往症条款定义过宽的，可主张加重投保人责任而无效。</p>\n<h3 id=\"s17\">保证续保 vs 可续保</h3>\n<p><strong>比喻</strong>：<strong>保证续保</strong> = 铁饭碗，公司不能辞退你也不能涨你租；<strong>可续保</strong> = 一年一签的劳动合同，公司可以决定不续签。 <strong>内核</strong>：一字之差，保障天差地别。</p>\n<h3 id=\"s18\">免赔额</h3>\n<p><strong>比喻</strong>：手机套餐的\"超出部分才计费\"。1 万免赔额 = 一万块以内的部分自己扛。 <strong>内核</strong>：注意社保报销部分是否计入免赔额。</p>\n<hr>\n<h2 id=\"s19\">三、理赔环节</h2>\n<h3 id=\"s20\">近因原则</h3>\n<p><strong>比喻</strong>：一排骨牌倒下，最后倒的那张不是原因，第一张被推倒的才是。法官要找的是\"第一张牌\"，而且是<strong>最有力的那一张</strong>，不是时间上最近的那一张。 <strong>内核</strong>：看对损失起<strong>决定性作用</strong>的原因。</p>\n<h3 id=\"s21\">举证责任分配</h3>\n<p><strong>比喻</strong>：打牌时规则说明书在谁手里，谁就有义务把规则讲清楚。说明书在保险公司手里，所以\"规则没讲清楚\"的风险由它背。 <strong>内核</strong>：保险人对已履行提示说明义务、对询问范围负举证责任。</p>\n<h3 id=\"s22\">\"所能提供\"的限度</h3>\n<p><strong>比喻</strong>：你只要把你手上有的材料交出来就行，不需要你去变出你没有的材料。 <strong>内核</strong>：索赔方的举证以其所能提供为限（§22）。</p>\n<h3 id=\"s23\">核定期限（30 日）</h3>\n<p><strong>比喻</strong>：保险公司不能既当裁判又当计时员。法律给它设了闹钟（复杂案件 30 天），闹钟响了还没结果，它就得赔你等待期间的损失。 <strong>内核</strong>：迟延赔付要赔偿因此受到的损失（§23③）。</p>\n<h3 id=\"s24\">先予支付</h3>\n<p><strong>比喻</strong>：账还没算清，但先把没争议的那部分钱给你。不能说\"总额没谈拢所以一分不给\"。 <strong>内核</strong>：收到请求 60 日内不能确定数额的，先支付可确定的最低部分（§25）。</p>\n<h3 id=\"s25\">诉讼时效</h3>\n<p><strong>比喻</strong>：超市小票的保质期。过期了，东西是你买的也认不了。非寿险 <strong>2 年</strong>、寿险 <strong>5 年</strong>。 <strong>内核</strong>：<strong>跟保险公司谈判不中断时效</strong>，要留催告证据或起诉。</p>\n<h3 id=\"s26\">代位求偿</h3>\n<p><strong>比喻</strong>：保险公司先替你掏钱，然后\"穿上你的鞋\"去告那个撞你的人。但它只能站在你的位置上——<strong>权利不会比你更多</strong>，你放弃过的它也不能主张。 <strong>内核</strong>：在赔偿金额范围内代位行使被保险人对第三者的请求权（§60）。</p>\n<h3 id=\"s27\">责任保险</h3>\n<p><strong>比喻</strong>：一面替你挡刀的盾。但前提是<strong>有人真的朝你砍了一刀，而且法院认定你该赔钱</strong>——你自己承认的、私下赔的，保险公司未必认。 <strong>内核</strong>：保险人承担的是被保险人<strong>依法应负的赔偿责任</strong>。</p>\n<h3 id=\"s28\">危险程度显著增加</h3>\n<p><strong>比喻</strong>：你投保时说\"这是自家住房\"，后来改成了存放油漆的仓库。风险完全不是一个量级，当然要通知保险公司。 <strong>内核</strong>：未通知的，因危险程度显著增加而发生的事故不赔（§52）。</p>\n<h3 id=\"s29\">高保低赔</h3>\n<p><strong>比喻</strong>：按市场价收你保费，出事时按成本价赔你。收钱用\"新车价\"，赔钱用\"折旧价\"。 <strong>内核</strong>：违反保险利益原则和诚信原则，人民法院案例库有裁判规则支持\"高保应高赔\"。</p>\n<h3 id=\"s30\">和解协议</h3>\n<p><strong>比喻</strong>：签之前是你在跟保险公司谈，签之后你只剩协议上那几个字。<strong>签字前一定要算清楚全部损失</strong>，包括后续治疗费、收入损失。</p>\n<hr>\n<h2 id=\"s31\">四、制度层面</h2>\n<h3 id=\"s32\">道德风险</h3>\n<p><strong>比喻</strong>：给邻居的房子买了火灾险，然后你开始盼着它着火。所以法律要求：投保人对保险标的必须有<strong>保险利益</strong>。</p>\n<h3 id=\"s33\">逆向选择</h3>\n<p><strong>比喻</strong>：只有觉得自己会生病的人才积极买健康险——保险公司就知道，主动上门的客人平均风险更高，于是提高保费，健康的又退出了，形成恶性循环。 <strong>内核</strong>：这是<strong>如实告知义务</strong>存在的经济学理由。</p>\n<h3 id=\"s34\">保险法第 16 条第 3 款（两年不可抗辩）</h3>\n<p><strong>比喻</strong>：保险公司有<strong>两年时间</strong>来查你。查不出来，这页就永远翻不过去了。 <strong>内核</strong>：自合同成立之日起超过二年，保险人不得解除合同。</p>\n<h3 id=\"s35\">保险人 30 日解除权</h3>\n<p><strong>比喻</strong>：超市的退货窗口。发现问题的当天起算，30 天不提，过期作废。 <strong>内核</strong>：自保险人知道解除事由之日起 30 日不行使而消灭（§16③）。</p>\n<h3 id=\"s36\">合同中止与复效</h3>\n<p><strong>比喻</strong>：手机停机。欠费后先进入\"半停机\"（宽限期 60 天），再不缴费就\"停机\"（中止）。复机要补缴欠费，<strong>还要重新验证身份</strong>（重新健康告知）。 <strong>内核</strong>：中止期一般 2 年，期间出险不赔。</p>\n<h3 id=\"s37\">保费豁免</h3>\n<p><strong>比喻</strong>：你生病了，后面的房贷不用还了，房子还是你的。 <strong>内核</strong>：触发轻症/重疾后，后续保费免除，合同继续有效。</p>\n<h3 id=\"s38\">受益人\"法定\"</h3>\n<p><strong>比喻</strong>：不指定受益人，这笔钱就变成遗产——要走继承程序，所有继承人都要来签字，还可能先拿去还债。 <strong>内核</strong>：<strong>一定要指定受益人</strong>。</p>\n<h3 id=\"s39\">再保险</h3>\n<p><strong>比喻</strong>：保险公司给自己买的保险。它赔不起的时候，有人替它赔一部分。</p>\n<h3 id=\"s40\">保险法第 19 条（格式条款无效）</h3>\n<p><strong>比喻</strong>：不是所有\"白纸黑字签了字\"的条款都有效。有些条款从一开始就不算数，签了也不算。 <strong>内核</strong>：免除保险人法定义务 / 加重投保人责任 / 排除投保人法定权利的条款无效。</p>\n<h3 id=\"s41\">诉讼时效 3 年 vs 2 年</h3>\n<p>保险法白纸黑字写\"2 年\"，但法院按民法典判 <strong>3 年</strong>。 就像商场门口挂牌\"营业至 21:00\"，市政规定统一延长到 22:00——<strong>牌子没换，但实际关门时间已经变了</strong>。 而且起算点是\"你<strong>知道</strong>出事了\"，不是\"出事了\"。广州中院那个案子，2020 年出险，保险人一直没告知保单内容，被保险人 2024 年才打电话问出来，2025 年起诉照样赢。</p>\n<h3 id=\"s42\">§52 危险程度显著增加：法定义务 vs 约定义务</h3>\n<p>你签的合同里写没写这条，都不影响你要不要通知保险公司——<strong>因为这是法律直接规定的，不是合同给你的</strong>。 就像\"不能闯红灯\"：不是因为驾照背面印了这条你才要遵守，是《道交法》本来就规定了。 所以\"保险公司没给我解释过这条免责条款\"这个抗辩，在营运车拒赔案里<strong>没用</strong>——湛江中院明确说这是\"理解错误，于法无据\"。</p>\n<h3 id=\"s43\">保险标的条款限缩 = 实质免责条款</h3>\n<p>保险公司说：\"我没有免责啊，我只是说金银珠宝<strong>不算</strong>我保的'室内财产'。\" 这就像餐厅说：\"我没有拒绝接待你，我只是说你<strong>不算</strong>我们的'顾客'。\" 换了件马甲，干的是同一件事。江门中院：单方限缩、限制被保险人权利的，<strong>实质上就是免责条款</strong>，照样要提示说明。</p>\n<h3 id=\"s44\">保险人的举证标准：阅读时长、点击路径</h3>\n<p>保险人光拿一张你签字的\"我已阅读\"声明，法院说不够——<strong>你得把监控录像拿出来</strong>：他在页面上停了多久、点了哪里。 就像考场防作弊，光有\"我承诺没作弊\"的签名不行，要有<strong>监控录像和登录日志</strong>。</p>\n<h3 id=\"s45\">顺风车 vs 营运</h3>\n<p>真顺风车：你每天从 A 到 B 上班，顺路捎个人分摊油钱——<strong>路线是既定的，人只是搭便车</strong>。 被认定的营运：47 单跨市、1548 次出行、起点终点毫无规律——<strong>这不是顺路，这是开着车满世界接客</strong>。 分界线不在\"收没收钱\"，在\"<strong>你是在走自己的路，还是在走乘客的路</strong>\"。</p>\n<h3 id=\"s46\">\"违反安全装载规定\" ≠ \"超载\"</h3>\n<p>保险公司拒赔通知上写的理由，和合同免责条款里写的词，<strong>必须一个字一个字对</strong>。 它合同里写的是\"违反安全装载规定\"（一大类），拒赔时说的是\"你超载了\"（其中一种）。 这就像物业规定\"不得在小区内从事经营活动\"——你在家开了个线上会议，物业不能据此罚你。 词对不上，就打 §30 不利解释。</p>", "toc": [{"id": "s1", "lv": 2, "t": "一、投保环节"}, {"id": "s2", "lv": 3, "t": "如实告知义务"}, {"id": "s3", "lv": 3, "t": "最大诚信原则"}, {"id": "s4", "lv": 3, "t": "保险利益"}, {"id": "s5", "lv": 3, "t": "等待期"}, {"id": "s6", "lv": 3, "t": "犹豫期"}, {"id": "s7", "lv": 3, "t": "核保"}, {"id": "s8", "lv": 3, "t": "现金价值"}, {"id": "s9", "lv": 2, "t": "二、条款环节"}, {"id": "s10", "lv": 3, "t": "提示说明义务"}, {"id": "s11", "lv": 3, "t": "隐性免责条款"}, {"id": "s12", "lv": 3, "t": "免责条款的范围（免赔额、比例赔付也算）"}, {"id": "s13", "lv": 3, "t": "不利解释规则"}, {"id": "s14", "lv": 3, "t": "格式条款无效（第 19 条）"}, {"id": "s15", "lv": 3, "t": "伤残比例赔付"}, {"id": "s16", "lv": 3, "t": "既往症"}, {"id": "s17", "lv": 3, "t": "保证续保 vs 可续保"}, {"id": "s18", "lv": 3, "t": "免赔额"}, {"id": "s19", "lv": 2, "t": "三、理赔环节"}, {"id": "s20", "lv": 3, "t": "近因原则"}, {"id": "s21", "lv": 3, "t": "举证责任分配"}, {"id": "s22", "lv": 3, "t": "\"所能提供\"的限度"}, {"id": "s23", "lv": 3, "t": "核定期限（30 日）"}, {"id": "s24", "lv": 3, "t": "先予支付"}, {"id": "s25", "lv": 3, "t": "诉讼时效"}, {"id": "s26", "lv": 3, "t": "代位求偿"}, {"id": "s27", "lv": 3, "t": "责任保险"}, {"id": "s28", "lv": 3, "t": "危险程度显著增加"}, {"id": "s29", "lv": 3, "t": "高保低赔"}, {"id": "s30", "lv": 3, "t": "和解协议"}, {"id": "s31", "lv": 2, "t": "四、制度层面"}, {"id": "s32", "lv": 3, "t": "道德风险"}, {"id": "s33", "lv": 3, "t": "逆向选择"}, {"id": "s34", "lv": 3, "t": "保险法第 16 条第 3 款（两年不可抗辩）"}, {"id": "s35", "lv": 3, "t": "保险人 30 日解除权"}, {"id": "s36", "lv": 3, "t": "合同中止与复效"}, {"id": "s37", "lv": 3, "t": "保费豁免"}, {"id": "s38", "lv": 3, "t": "受益人\"法定\""}, {"id": "s39", "lv": 3, "t": "再保险"}, {"id": "s40", "lv": 3, "t": "保险法第 19 条（格式条款无效）"}, {"id": "s41", "lv": 3, "t": "诉讼时效 3 年 vs 2 年"}, {"id": "s42", "lv": 3, "t": "§52 危险程度显著增加：法定义务 vs 约定义务"}, {"id": "s43", "lv": 3, "t": "保险标的条款限缩 = 实质免责条款"}, {"id": "s44", "lv": 3, "t": "保险人的举证标准：阅读时长、点击路径"}, {"id": "s45", "lv": 3, "t": "顺风车 vs 营运"}, {"id": "s46", "lv": 3, "t": "\"违反安全装载规定\" ≠ \"超载\""}], "text": "生活比喻库 用途 ：给普通人讲保险法律知识时用的弹药库。 每个条目 = 法律概念 + 生活比喻 + 一句话内核 + 什么时候用。 比喻不追求法律严谨，追求 第一次听就能懂 。 一、投保环节 如实告知义务 比喻 ：相亲时\"问什么答什么\"。对方没问你有没有房，你不用主动交代；但问了就得说实话。反过来，对方问一句\"你人应该没啥问题吧\"这种含糊问题，等于没问——法律上叫 概括性询问 ，不能拿来当拒赔理由。 内核 ：告知义务以保险人的 具体询问 为边界。 什么时候用 ：保险人说\"你没如实告知\"时，先反问\"你问了吗？怎么问的？\" 最大诚信原则 比喻 ：普通买卖是\"买方自行小心\"，保险是\"双方都得把牌摊开\"。尤其保险人，手里握着全部信息和条款，就必须多承担一分诚实的义务。 内核 ：保险合同的诚信要求 高于 一般合同。 保险利益 比喻 ：你不能给邻居家的房子买火灾险然后盼着它着火。只有\"这东西出事你会真的心疼/真的损失\"的人，才能给它投保。 内核 ：防止把保险变成赌博和道德风险的工具。 等待期 比喻 ：新员工的试用期。这段时间出事，公司（保险公司）可以说\"还没转正\"。重疾险常见 90 天或 180 天。 内核 ：防止带病投保的道德风险。 犹豫期 比喻 ：网购的七天无理由退货。签收后十到十五天内反悔，全额退保费。 内核 ：给投保人一次\"后悔药\"。 核保 比喻 ：入职体检。保险公司根据结果决定：正常录取 / 加钱录取 / 某个部位不保 / 不录取。 现金价值 比喻 ：这张保单的\"二手残值\"。刚买的前两年退保，能拿回来的钱可能只有保费的零头——因为你交的钱里，大头被销售佣金、管理费、风险保费吃掉了。 内核 ：退保 ≠ 退保费。 二、条款环节 提示说明义务 比喻 ：药品说明书的\"黑框警告\"。药厂不能把严重不良反应塞在说明书第 38 页的小字里，然后说\"你自己没看\"。必须印在盒子最显眼的地方，还得让你看得懂。 内核 ：免责条款必须 提示 （看得见）+ 明确说明 （看得懂），缺一不可。 隐性免责条款 比喻 ：菜单的\"推荐菜\"栏里写着\"本店不提供\"。它长得不像免责，效果却一模一样。 内核 ：写在\"保险责任\"章节里、实际免除保险人责任的条款，照样要提示说明。 免责条款的范围（免赔额、比例赔付也算） 比喻 ：不光\"本店概不负责\"是免责，\"每单最高赔 20 元\"\"只赔八折\"同样是在减你的权利，也得说清楚。 内核 ：司法解释（二）第 9 条把免赔额、免赔率、比例赔付都纳入免责条款。 不利解释规则 比喻 ：格式合同是出题人自己出的卷子。卷子出得含糊，分数判给考生，不判给出题人。 内核 ：有两种以上解释时，作有利于被保险人和受益人的解释。 格式条款无效（第 19 条） 比喻 ：不是所有\"签字了就认\"的条款都算数。霸王条款签了字照样可以认定无效。 内核 ：免除保险人法定义务、加重投保人责任、排除投保人权利的条款无效。 伤残比例赔付 比喻 ：不是\"伤了就赔全款\"，而是按等级打折：一级 100%，十级 10%。 内核 ：比例赔付属免责条款，未提示说明不生效。 既往症 比喻 ：买二手车时的\"旧伤\"。卖家说\"这车之前碰过的地方我不负责\"，但得在合同里 写清楚 哪些算旧伤。 内核 ：既往症条款定义过宽的，可主张加重投保人责任而无效。 保证续保 vs 可续保 比喻 ： 保证续保 = 铁饭碗，公司不能辞退你也不能涨你租； 可续保 = 一年一签的劳动合同，公司可以决定不续签。 内核 ：一字之差，保障天差地别。 免赔额 比喻 ：手机套餐的\"超出部分才计费\"。1 万免赔额 = 一万块以内的部分自己扛。 内核 ：注意社保报销部分是否计入免赔额。 三、理赔环节 近因原则 比喻 ：一排骨牌倒下，最后倒的那张不是原因，第一张被推倒的才是。法官要找的是\"第一张牌\"，而且是 最有力的那一张 ，不是时间上最近的那一张。 内核 ：看对损失起 决定性作用 的原因。 举证责任分配 比喻 ：打牌时规则说明书在谁手里，谁就有义务把规则讲清楚。说明书在保险公司手里，所以\"规则没讲清楚\"的风险由它背。 内核 ：保险人对已履行提示说明义务、对询问范围负举证责任。 \"所能提供\"的限度 比喻 ：你只要把你手上有的材料交出来就行，不需要你去变出你没有的材料。 内核 ：索赔方的举证以其所能提供为限（§22）。 核定期限（30 日） 比喻 ：保险公司不能既当裁判又当计时员。法律给它设了闹钟（复杂案件 30 天），闹钟响了还没结果，它就得赔你等待期间的损失。 内核 ：迟延赔付要赔偿因此受到的损失（§23③）。 先予支付 比喻 ：账还没算清，但先把没争议的那部分钱给你。不能说\"总额没谈拢所以一分不给\"。 内核 ：收到请求 60 日内不能确定数额的，先支付可确定的最低部分（§25）。 诉讼时效 比喻 ：超市小票的保质期。过期了，东西是你买的也认不了。非寿险 2 年 、寿险 5 年 。 内核 ： 跟保险公司谈判不中断时效 ，要留催告证据或起诉。 代位求偿 比喻 ：保险公司先替你掏钱，然后\"穿上你的鞋\"去告那个撞你的人。但它只能站在你的位置上—— 权利不会比你更多 ，你放弃过的它也不能主张。 内核 ：在赔偿金额范围内代位行使被保险人对第三者的请求权（§60）。 责任保险 比喻 ：一面替你挡刀的盾。但前提是 有人真的朝你砍了一刀，而且法院认定你该赔钱 ——你自己承认的、私下赔的，保险公司未必认。 内核 ：保险人承担的是被保险人 依法应负的赔偿责任 。 危险程度显著增加 比喻 ：你投保时说\"这是自家住房\"，后来改成了存放油漆的仓库。风险完全不是一个量级，当然要通知保险公司。 内核 ：未通知的，因危险程度显著增加而发生的事故不赔（§52）。 高保低赔 比喻 ：按市场价收你保费，出事时按成本价赔你。收钱用\"新车价\"，赔钱用\"折旧价\"。 内核 ：违反保险利益原则和诚信原则，人民法院案例库有裁判规则支持\"高保应高赔\"。 和解协议 比喻 ：签之前是你在跟保险公司谈，签之后你只剩协议上那几个字。 签字前一定要算清楚全部损失 ，包括后续治疗费、收入损失。 四、制度层面 道德风险 比喻 ：给邻居的房子买了火灾险，然后你开始盼着它着火。所以法律要求：投保人对保险标的必须有 保险利益 。 逆向选择 比喻 ：只有觉得自己会生病的人才积极买健康险——保险公司就知道，主动上门的客人平均风险更高，于是提高保费，健康的又退出了，形成恶性循环。 内核 ：这是 如实告知义务 存在的经济学理由。 保险法第 16 条第 3 款（两年不可抗辩） 比喻 ：保险公司有 两年时间 来查你。查不出来，这页就永远翻不过去了。 内核 ：自合同成立之日起超过二年，保险人不得解除合同。 保险人 30 日解除权 比喻 ：超市的退货窗口。发现问题的当天起算，30 天不提，过期作废。 内核 ：自保险人知道解除事由之日起 30 日不行使而消灭（§16③）。 合同中止与复效 比喻 ：手机停机。欠费后先进入\"半停机\"（宽限期 60 天），再不缴费就\"停机\"（中止）。复机要补缴欠费， 还要重新验证身份 （重新健康告知）。 内核 ：中止期一般 2 年，期间出险不赔。 保费豁免 比喻 ：你生病了，后面的房贷不用还了，房子还是你的。 内核 ：触发轻症/重疾后，后续保费免除，合同继续有效。 受益人\"法定\" 比喻 ：不指定受益人，这笔钱就变成遗产——要走继承程序，所有继承人都要来签字，还可能先拿去还债。 内核 ： 一定要指定受益人 。 再保险 比喻 ：保险公司给自己买的保险。它赔不起的时候，有人替它赔一部分。 保险法第 19 条（格式条款无效） 比喻 ：不是所有\"白纸黑字签了字\"的条款都有效。有些条款从一开始就不算数，签了也不算。 内核 ：免除保险人法定义务 / 加重投保人责任 / 排除投保人法定权利的条款无效。 诉讼时效 3 年 vs 2 年 保险法白纸黑字写\"2 年\"，但法院按民法典判 3 年 。 就像商场门口挂牌\"营业至 21:00\"，市政规定统一延长到 22:00—— 牌子没换，但实际关门时间已经变了 。 而且起算点是\"你 知道 出事了\"，不是\"出事了\"。广州中院那个案子，2020 年出险，保险人一直没告知保单内容，被保险人 2024 年才打电话问出来，2025 年起诉照样赢。 §52 危险程度显著增加：法定义务 vs 约定义务 你签的合同里写没写这条，都不影响你要不要通知保险公司—— 因为这是法律直接规定的，不是合同给你的 。 就像\"不能闯红灯\"：不是因为驾照背面印了这条你才要遵守，是《道交法》本来就规定了。 所以\"保险公司没给我解释过这条免责条款\"这个抗辩，在营运车拒赔案里 没用 ——湛江中院明确说这是\"理解错误，于法无据\"。 保险标的条款限缩 = 实质免责条款 保险公司说：\"我没有免责啊，我只是说金银珠宝 不算 我保的'室内财产'。\" 这就像餐厅说：\"我没有拒绝接待你，我只是说你 不算 我们的'顾客'。\" 换了件马甲，干的是同一件事。江门中院：单方限缩、限制被保险人权利的， 实质上就是免责条款 ，照样要提示说明。 保险人的举证标准：阅读时长、点击路径 保险人光拿一张你签字的\"我已阅读\"声明，法院说不够—— 你得把监控录像拿出来 ：他在页面上停了多久、点了哪里。 就像考场防作弊，光有\"我承诺没作弊\"的签名不行，要有 监控录像和登录日志 。 顺风车 vs 营运 真顺风车：你每天从 A 到 B 上班，顺路捎个人分摊油钱—— 路线是既定的，人只是搭便车 。 被认定的营运：47 单跨市、1548 次出行、起点终点毫无规律—— 这不是顺路，这是开着车满世界接客 。 分界线不在\"收没收钱\"，在\" 你是在走自己的路，还是在走乘客的路 \"。 \"违反安全装载规定\" ≠ \"超载\" 保险公司拒赔通知上写的理由，和合同免责条款里写的词， 必须一个字一个字对 。 它合同里写的是\"违反安全装载规定\"（一大类），拒赔时说的是\"你超载了\"（其中一种）。 这就像物业规定\"不得在小区内从事经营活动\"——你在家开了个线上会议，物业不能据此罚你。 词对不上，就打 §30 不利解释。"}, {"id": "L3-输出层/04-AI协作指令库", "group": "4 · 工具箱", "groupKey": "L3-输出层", "title": "AI 协作指令库（可直接复制使用）", "order": 4, "file": "04-AI协作指令库.md", "html": "<h1 id=\"s0\">AI 协作指令库（可直接复制使用）</h1>\n<blockquote><strong>怎么用</strong>：每条指令都设计成\"复制粘贴即可跑\"。方括号 <code>【】</code> 里的内容替换成你的实际情况。<br><strong>建议</strong>：把\"零号指令\"存成你的常用前缀，每次开新对话先贴一遍，能显著减少胡说八道。</blockquote>\n<hr>\n<h2 id=\"s1\">零号指令 · 通用前置设定（每次开新对话先贴这个）</h2>\n<pre><code>\n你是一位中国大陆保险法方向的资深律师助手，服务对象是一位执业律师。\n\n\n\n工作规则（必须严格遵守）：\n\n1. 只依据现行有效的中国大陆法律、司法解释和**你实际检索到的**公开判例回答。\n\n2. 不得编造任何案号、法院名称、法官姓名、裁判日期或裁判理由。检索不到就明确说\n\n   \"未检索到\"，不要推测、不要补全、不要用相似案件代替。\n\n3. 引用法条时写明\"法律/司法解释名称 + 条文号\"，并给出条文原文；不确定原文时说\n\n   \"原文需核对\"，不要凭记忆默写。\n\n4. 区分三种情况并明确标注：\n\n   -【明文规定】：法律或司法解释有明确规定\n\n   -【裁判倾向】：无明文，但有可检索的判例支持\n\n   -【学理观点】：既无明文也无判例，属理论分析\n\n5. 涉及地域裁判差异时，优先给广东省（尤其广州、深圳、佛山、东莞）的口径，\n\n   并说明你的依据来源。\n\n6. 回答结构：结论先行 → 依据 → 分析 → 风险提示 → 下一步动作建议。\n\n7. 如果我给你的材料不充分，直接列出你还缺什么，不要自行假设事实。\n\n</code></pre>\n<p><strong>为什么这么写</strong>：第 2、3 条是防幻觉的核心。AI 编案号是这类工作里<strong>唯一的致命错误</strong>——内容写错可以改，引用一个不存在的判例在法庭上是灾难。第 4 条强迫 AI 区分\"有规定\"和\"它觉得\"，避免把学理当裁判规则。</p>\n<hr>\n<h2 id=\"s2\">一、案件诊断类</h2>\n<h3 id=\"s3\">1.1 拿到拒赔通知书后的 30 分钟定位</h3>\n<pre><code>\n我手上有一个保险理赔纠纷，材料如下：\n\n\n\n【保险公司拒赔理由（原文引用）】：\n\n【保险类型】（重疾/医疗/意外/寿险/车险/财产险/责任险）：\n\n【合同成立日】：【出险日】：【报案日】：\n\n【拒赔通知书发出日】：【解除通知书发出日（如有）】：\n\n【争议条款原文】：\n\n【我方主张】：\n\n\n\n请你按以下步骤分析：\n\n\n\n第一步 · 定性：保险公司依据的是\"未如实告知\"、\"免责条款\"、\"不符合保险责任定义\"、\n\n\"危险程度显著增加\"还是\"合同无效/解除\"？明确归类。\n\n\n\n第二步 · 逐项排查（每项给出结论 + 依据 + 强弱评估）：\n\n1. 保险人主张的条款，属于\"保险责任范围条款\"还是\"免责条款\"？\n\n   如果是写在责任范围章节里但实质免除责任的，是否构成\"隐性免责条款\"？\n\n2. 该条款是否履行了《保险法》第17条的提示义务和明确说明义务？\n\n   举证责任在谁？我方可以攻击的点是什么？\n\n3. 如果是未如实告知：保险人的询问是否具体明确？是否属概括性询问？\n\n   投保人是否\"明知\"？未告知事项与保险事故有无因果关系？\n\n4. 保险人解除权的行使是否超期（知道解除事由后30日 / 合同成立后2年）？\n\n   保险人是否先行使解除权再拒赔？\n\n5. 诉讼时效是否届满（非寿险2年 / 寿险5年）？\n\n6. 条款是否存在两种以上解释，可主张《保险法》第30条不利解释？\n\n7. 该条款是否属于《保险法》第19条无效格式条款？\n\n\n\n第三步 · 给出我的三个最强攻击点和两个最弱环节。\n\n\n\n第四步 · 列出我还缺哪些证据材料。\n\n\n\n第五步 · 建议诉讼请求怎么写（含我可能漏掉的请求项）。\n\n</code></pre>\n<p><strong>注意</strong>：把时间轴填全是关键。保险纠纷里，<strong>时间往往比道理更重要</strong>——30 日、2 年、60 日、诉讼时效，任何一个都可能直接决定胜负。</p>\n<hr>\n<h3 id=\"s4\">1.2 让 AI 扮演对方，做对抗式检验</h3>\n<pre><code>\n现在请你转换角色，担任保险公司一方的代理律师。\n\n\n\n背景材料：\n\n【我方（被保险人）的主张与证据】：\n\n【案件事实摘要】：\n\n\n\n请你站在保险公司立场，写出：\n\n1. 你会提出哪三个最有力的抗辩？每个抗辩的法条/条款依据是什么？\n\n2. 你会要求我方补充哪些证据？为什么？\n\n3. 我方证据链里最薄弱的一环是什么？你会怎么攻击它？\n\n4. 你认为我方最可能败诉的点在哪里？\n\n\n\n写完后再切回我的立场，针对上述每一项给出破解方案；\n\n如果某一条你确实找不到破解办法，明确说\"这条很难打，建议考虑和解\"，不要硬编。\n\n</code></pre>\n<p><strong>为什么这么写</strong>：单方推理会自我强化。让 AI 先当对手，能提前暴露你没想到的抗辩——尤其是保险人常用的\"第 9 条第 2 款反向规定\"（违反义务的解除权条款不算免责条款）这类冷门点。</p>\n<hr>\n<h2 id=\"s5\">二、条款审查类</h2>\n<h3 id=\"s6\">2.1 扫描一份保单里的\"地雷条款\"</h3>\n<pre><code>\n附件是我的一份保险条款/保单。请你做一次\"责任范围反向扫描\"：\n\n\n\n1. 找出所有**实质免除或减轻保险人责任**的条款，包括：\n\n   - 明确写在\"责任免除\"章节的\n\n   - 写在\"保险责任\"章节但含\"但\"\"除外\"\"仅限于\"\"须满足以下条件\"\"不包括\"\n\n     \"不承担\"等限定的（即隐性免责条款）\n\n   - 免赔额、免赔率、比例赔付、给付限额、赔付比例表\n\n   - 等待期、观察期、生存期要求\n\n   - 对疾病/手术/状态的定义中，与医学通说不一致的限定\n\n   - 保险金请求权的行使条件与期间限制\n\n\n\n2. 对每一条，用表格输出：\n\n   | 条款位置 | 原文摘录 | 性质（显性免责/隐性免责/责任范围） | 是否需提示说明 | 攻击难度（高/中/低） | 备注 |\n\n\n\n3. 挑出你认为最值得攻击的三条，说明理由。\n\n\n\n4. 指出这份条款里对投保人**最不利但最不显眼**的一处设计。\n\n</code></pre>\n<p><strong>注意</strong>：AI 读长 PDF 会丢内容。<strong>条款超过 30 页就分段喂</strong>，并且每次让它复述\"你读到了哪些章节\"确认没漏。</p>\n<hr>\n<h3 id=\"s7\">2.2 比对\"投保时条款\"与\"现行条款\"</h3>\n<pre><code>\n我有两份保险条款：A 是投保时的版本，B 是保险公司现在提供的版本。\n\n请逐条比对我关心的【某疾病/某责任】的定义差异，输出：\n\n1. 实质差异点（不是文字润色的那些）\n\n2. 哪个版本对被保险人更有利\n\n3. 理赔时应适用哪个版本，依据是什么\n\n</code></pre>\n<p><strong>为什么有用</strong>：保险公司常拿<strong>新版条款</strong>来抗辩，但合同成立时适用的是旧版。这个差异能成为独立攻击点。</p>\n<hr>\n<h2 id=\"s8\">三、检索类（防幻觉重点区）</h2>\n<h3 id=\"s9\">3.1 找判例（严格版）</h3>\n<pre><code>\n请帮我检索中国大陆（优先广东省：广州、深圳、佛山、东莞、珠海、广东高院、\n\n广州金融法院）关于【具体争议点，例如\"重疾险微创手术与条款要求开胸不符\"】的\n\n裁判案例。\n\n\n\n严格要求：\n\n1. 每一个案例必须给出：案号、审理法院、审级、裁判日期、来源链接。\n\n2. **检索不到案号的，明确说\"未找到可核验案号\"，不要用\"某法院\"\"一起案例\"这种\n\n   模糊表述，也不要用你推测的案子代替。**\n\n3. 区分来源可信度：\n\n   A 级 = 裁判文书原文 / 人民法院案例库原文\n\n   B 级 = 法院官网、官媒（中国法院网、人民法院报、省市高院发布）\n\n   C 级 = 律所网站、自媒体（标注\"待核验，不得直接引用\"）\n\n4. 对每个案例，摘录**法院说理的原文**（用引用块），而不是你的转述。\n\n5. 最后总结：这个争议点在广东的裁判倾向是什么？有多少案例支持？\n\n   如果只有零星案例，明确说\"样本不足，不构成稳定裁判规则\"。\n\n</code></pre>\n<p><strong><span class=\"warn\">!</span> 最重要的一条</strong>：AI 给的案号，<strong>用之前必须自己核一遍</strong>（中国裁判文书网、人民法院案例库、法院官网）。AI 编案号的概率不低，尤其是\"看起来很合理\"的那种。</p>\n<hr>\n<h3 id=\"s10\">3.2 核验一个已有案号</h3>\n<pre><code>\n我手上有一个案号：【（2025）粤01民终XXXXX号】。\n\n请帮我核这个案号的真实性，并说明：\n\n1. 你能否找到该案的原始来源？来源链接是什么？\n\n2. 如果找不到，明确告诉我\"无法核实\"，并说明需要哪些渠道去核实\n\n   （中国裁判文书网、人民法院案例库、广州中院官网、北大法宝等）。\n\n3. 不要根据案号格式猜测这个案子的内容。\n\n</code></pre>\n<hr>\n<h3 id=\"s11\">3.3 法条核对</h3>\n<pre><code>\n请核对《保险法》第【X】条的**现行有效原文**。\n\n\n\n要求：\n\n1. 给出条文全文（逐字）。\n\n2. 注明该条在 2009 年修订、2015 年修正中有无变化。\n\n3. 列出与该条配套的司法解释条文（写明司法解释名称与条文号 + 原文）。\n\n4. 列出最高人民法院发布的、与该条相关的指导性案例或公报案例（有则给案号，\n\n   没有就说没有）。\n\n5. 如果你无法访问权威来源，说\"原文需核对\"，不要凭记忆默写。\n\n</code></pre>\n<hr>\n<h2 id=\"s12\">四、文书生成类</h2>\n<h3 id=\"s13\">4.1 起诉状</h3>\n<pre><code>\n请为我起草一份保险合同纠纷民事起诉状。\n\n\n\n【当事人信息】：\n\n【保险类型与保单号】：\n\n【保险合同成立日 / 保险期间】：\n\n【保险事故发生经过】：\n\n【理赔与拒赔过程（含关键时间点）】：\n\n【我方主张的法律依据】：\n\n【诉讼请求】：\n\n\n\n要求：\n\n1. 按民事起诉状规范格式（当事人、诉讼请求、事实与理由、此致XX法院）。\n\n2. 事实部分按**时间轴**陈述，突出对我方有利的时间节点\n\n   （如保险人超期核定、超期行使解除权）。\n\n3. 理由部分按\"合同效力 → 条款效力 → 告知义务 → 举证责任 → 损失\"的逻辑推进。\n\n4. 诉讼请求不要只写保险金，考虑是否加入：迟延赔付损失（保险法第23条第3款）、\n\n   继续履行合同、保费豁免、诉讼费与鉴定费承担。\n\n5. 语气克制、事实化，不要情绪化表述，不要使用\"恶意拒赔\"\"欺压消费者\"这类词。\n\n6. 最后单列一段\"本文书需要核实的事项\"，列出所有我必须自己核对的内容\n\n   （法条原文、案号、金额计算、管辖法院）。\n\n</code></pre>\n<hr>\n<h3 id=\"s14\">4.2 保险消费者投诉信（给 12378 / 保险公司总部）</h3>\n<pre><code>\n请代我起草一封保险消费投诉信，收件方是【12378 / 保险公司总部投诉部门】。\n\n\n\n【保单信息】：\n\n【事实经过（时间轴）】：\n\n【保险公司的处理与我方不满之处】：\n\n【诉求】（如：全额赔付 / 恢复合同效力 / 书面说明拒赔依据）：\n\n\n\n要求：\n\n1. **一页纸以内**，条理清晰，情绪克制——投诉信越像法律文书，越容易被认真处理。\n\n2. 开头一句话说清诉求。\n\n3. 中间用编号列出事实节点，每个节点标注日期。\n\n4. 结尾明确要求：书面答复 + 答复期限 + 告知救济途径。\n\n5. 附一句：如未在【15】个工作日内获得书面答复，将向监管部门进一步反映并保留\n\n   诉讼权利。\n\n</code></pre>\n<hr>\n<h3 id=\"s15\">4.3 律师函（理赔催告，兼中断诉讼时效）</h3>\n<pre><code>\n请起草一份律师函，目的有三：\n\n① 正式催告赔付；② 指出保险公司已存在的程序瑕疵；③ **形成时效中断的证据**。\n\n\n\n【事实与时间点】：\n\n【保险公司的违约/违法之处】（如：未在30日内核定、未在60日内先予支付、\n\n未在10日内赔付、超期行使解除权）：\n\n【要求其在X日内履行的义务】：\n\n\n\n要求：\n\n1. 明确指出对方违反的具体法条（写清条文号）。\n\n2. 每一项主张后附上对应的事实与日期。\n\n3. 写明逾期将采取的法律行动（诉讼 + 主张迟延损失 + 向监管部门反映）。\n\n4. 结尾加一句：本函同时作为权利人主张权利的意思表示。\n\n5. 提醒我：寄送要用 EMS 并保留寄送凭证与签收记录（这是中断时效的关键证据）。\n\n</code></pre>\n<hr>\n<h2 id=\"s16\">五、对外输出类（给普通人看）</h2>\n<h3 id=\"s17\">5.1 把法律分析改写成大白话</h3>\n<pre><code>\n下面是我写的一段法律分析，请改写成**初中文化程度也能看懂**的版本。\n\n\n\n要求：\n\n1. 每一段先给一个**生活比喻**（比喻要贴切、常见，不要用\"就像法律上说的\"这种废话），\n\n   再用比喻解释法律规则。\n\n2. 避免法言法语；必须用到的，第一次出现时用括号解释。\n\n3. 法条引用保留，但放在文末\"依据\"部分，正文不出现条文号。\n\n4. 加一段\"你现在就可以做的三件事\"，要具体可操作。\n\n5. 保持原意准确，**不要为了通俗而扭曲法律结论**。\n\n6. 长度控制在原文的 1.2 倍以内。\n\n\n\n原文：\n\n【粘贴】\n\n</code></pre>\n<hr>\n<h3 id=\"s18\">5.2 生成一份\"给家人看的投保提醒\"</h3>\n<pre><code>\n我要给家人买【某类保险】，请写一份 500 字以内的提醒，说明：\n\n1. 这个保险到底保什么、不保什么（说人话）\n\n2. 投保时必须如实回答什么\n\n3. 出险后第一时间要做的三件事（含证据保全）\n\n4. 最容易踩的一个坑\n\n\n\n语气：像家里人说话，不要像广告，也不要吓唬人。\n\n</code></pre>\n<hr>\n<h2 id=\"s19\">六、学习与复盘类</h2>\n<h3 id=\"s20\">6.1 用费曼方式吃透一个概念</h3>\n<pre><code>\n请用费曼学习法帮我彻底理解【某个保险法概念，如\"隐性免责条款\"】。\n\n\n\n要求：\n\n1. 用一句话给出核心定义（不超过 30 字）。\n\n2. 给一个生活比喻。\n\n3. 说清它解决什么问题、为什么需要它（不这么规定会怎样）。\n\n4. 给出 3 个真实适用场景 + 1 个\"看起来适用但其实不适用\"的反例。\n\n5. 列出与它容易混淆的 2 个概念，并说明区别。\n\n6. 出 3 道题考我，我回答后你批改。\n\n</code></pre>\n<hr>\n<h3 id=\"s21\">6.2 案件复盘</h3>\n<pre><code>\n这个案子已经结束，结果：【胜诉/败诉/和解，具体情况】。\n\n\n\n请帮我复盘：\n\n1. 我做对的三个决策是什么？为什么对？\n\n2. 我做错或遗漏的地方是什么？如果重来，哪一步会改？\n\n3. 这个案子暴露了我知识结构里的哪个缺口？\n\n4. 从这个案子里能提炼出什么可复用的规则或清单条目？\n\n5. 给我三条\"下次遇到同类案件，开局就要做的事\"。\n\n\n\n请直接、具体，不要说\"总体做得不错\"这类客套话。\n\n</code></pre>\n<hr>\n<h2 id=\"s22\">七、反幻觉核验（每次生成重要内容后跑一遍）</h2>\n<pre><code>\n请检查你刚才生成的内容，逐项自查并回答：\n\n\n\n1. 其中出现的每一个**案号、法院名称、法官姓名、裁判日期**，你是否有明确来源？\n\n   请逐个列出来源；没有来源的，现在标出来并删除。\n\n2. 其中出现的每一处**法条引用**，你给的原文是否与现行有效版本一致？\n\n   哪些是你凭记忆写的？（标注出来，我会自己核对）\n\n3. 其中有没有把\"学理观点\"或\"你的判断\"表述成\"法律规定\"或\"法院认为\"？\n\n4. 有没有不确定的事实被你当作确定事实陈述？\n\n5. 有没有遗漏对我不利的法律规定或判例？（请主动补充）\n\n\n\n如发现上述问题，请直接修改后重新输出完整版本。\n\n</code></pre>\n<p><strong>为什么必须有这一步</strong>：这一步能拦掉大部分编造。AI 在被要求\"自证来源\"时，通常会承认哪些是编的。<strong>不要跳过。</strong></p>\n<hr>\n<h2 id=\"s23\">附：几个使用习惯建议</h2>\n<ol>\n<li><strong>重要内容让两个不同模型各写一遍</strong>，对比差异。差异点往往就是幻觉点。</li>\n<li><strong>法条和案号一律自己核一遍</strong>，尤其是要写进诉状的。</li>\n<li><strong>长文档分段喂</strong>，每段结束让 AI 复述它读到了什么，确认没丢内容。</li>\n<li><strong>让 AI 给\"最不利于我的点\"</strong>，比让它给\"支持我的点\"价值高得多。</li>\n<li><strong>不要问\"我能不能赢\"</strong>——问\"法院会怎么认定 X 这个问题\"，答案有用得多。</li>\n</ol>\n<hr>\n<h2 id=\"s24\">16 · 车险\"改变使用性质 / 营运\"拒赔案审查</h2>\n<blockquote>复制前先跑一次本库开头的「零号指令」前置设定。</blockquote>\n<pre><code>\n你是广东执业律师助理。我有一份车险拒赔案，保险公司以\"车辆改变使用性质从事营运、\n\n危险程度显著增加\"为由拒赔商业险。请按下列框架审查并输出报告。\n\n\n\n【已知广东裁判规则，必须遵守】\n\n1. 保险法 §52 的通知义务是【法定义务】，不是约定义务。\n\n   \"保险公司没对免责条款提示说明\"这个抗辩无效（湛江中院 (2025)粤08民终951号）。\n\n   不要把这个作为主要抗辩，最多作为备位。\n\n2. \"出险时没有在接单\"不构成抗辩（中山中院 (2025)粤20民终1136号）。\n\n3. 认定营运的四要素：接单次数（47 次即可能被认定）、路线是否固定、\n\n   时间跨度、是否以营利为目的。特惠快车 = 营运。\n\n4. 保险人举证标准：须能锁定到具体的【人 + 车 + 订单】。\n\n   只有无身份信息、无车牌的截图 = 举证不足（东莞中院 (2026)粤19民终1493号）。\n\n\n\n【请输出】\n\n一、营运事实认定：按四要素逐项给我方证据和对方证据的对比表，并给出\"是否构成营运\"的概率判断。\n\n二、如果大概率构成营运：告诉我还有哪些争点可以打（不要编造，没有就说没有）。\n\n三、如果可能不构成营运：给我三点论证主线，每点配一句可直接写进代理词的句子。\n\n四、给保险人的证据做质证清单：逐条列出可以质疑的点（注册人身份、车牌、有无询问笔录、\n\n   截图形成时间与事故时间的关联、有无原始载体）。\n\n五、提醒我这个案子最容易踩的坑。\n\n\n\n【硬约束】\n\n- 不得编造任何案号、法院名称、法条内容。\n\n- 引用判例只能用我上面给的四个，或明确标注\"需另行检索\"。\n\n- 不确定的地方直接写\"不确定\"，不要猜。\n\n</code></pre>\n<hr>\n<h2 id=\"s25\">17 · 免责条款用词比对（找 §30 不利解释的突破口）</h2>\n<blockquote>这条成本极低、命中率不低，建议每个拒赔案都跑一遍。</blockquote>\n<pre><code>\n你是保险法实务助理。我要做一件事：把保险公司的【拒赔通知书】和【保险合同免责条款原文】\n\n做逐字比对，找出可以打《保险法》第 30 条\"不利解释\"的突破口。\n\n\n\n背景判例（请据此理解任务）：\n\n佛山中院 (2026)粤06民终4139号：合同免责条款写的是\"违反安全装载规定\"，\n\n保险公司拒赔时说的是\"超载\"。法院认为两者并非同一概念，条款足以造成理解争议，\n\n从有利于非格式条款提供方出发，认定保险人应理赔。\n\n\n\n【请按以下步骤做】\n\n第一步：把拒赔通知书里用作拒赔依据的【关键词】全部摘出来（如\"超载\"\"改变使用性质\"\"既往症\"）。\n\n第二步：在合同免责条款里找到保险公司声称对应的条款，把条款原文整段贴出来。\n\n第三步：逐词比对，用表格列出：\n\n        | 拒赔通知用词 | 合同条款用词 | 是否同一概念 | 差异点 | 能否打 §30 |\n\n第四步：对每个\"能否打 §30 = 可能\"的条目，写一句可直接用于代理词/庭审的表述，\n\n        格式参考：\"保险人据以拒赔的'XX'与合同免责条款所载'YY'并非同一概念，\n\n        XX 是否属于 YY 存在两种以上解释，依法应作出有利于被保险人的解释。\"\n\n第五步：提醒我 §30 的适用顺序——先按通常理解解释，仍有两种以上解释的才作有利解释，\n\n        不要一上来就喊不利解释。\n\n\n\n【硬约束】\n\n- 合同原文我贴给你，你没有原文的地方写\"需贴入合同原文\"，不要臆测条款内容。\n\n- 不得编造案号。\n\n</code></pre>\n<hr>\n<h2 id=\"s26\">18 · 互联网投保可回溯证据质证清单生成器</h2>\n<pre><code>\n你是保险法实务助理。这是一起通过网页/App 电子投保的案件，保险公司主张已履行\n\n提示说明义务。请帮我生成一份【当庭质证清单】，用来击穿它的举证。\n\n\n\n【法律标准（必须引用）】\n\n1. 佛山中院 (2026)粤06民终4139号：保险人应当完整保存投保人在销售页面的操作轨迹，\n\n   包括【阅读时长、点击路径】等关键节点。仅以投保人签字的格式化声明主张已履行，\n\n   证据不足。\n\n2. 广州中院 (2025)粤01民终19766号：仅提交\"同类保险产品\"投保流程公证书，\n\n   未能证明已向【投保人本人】作出提示说明 → 不生效。\n\n3. 解释二 §12：网络投保可以网页/音频/视频形式履行，但须指向本次投保。\n\n4. 反面提醒：中山中院 (2025)粤20民终2567号认定\"加粗加黑 + 强制停留阅读 +\n\n   阅读后勾选 + 条款无歧义\"四件套齐备 = 已履行。所以别指望必胜。\n\n\n\n【请输出一份质证清单，逐项列出我应该当庭要求保险人说明的问题】\n\n按四类组织：\n\nA. 轨迹真实性：是不是本次投保的轨迹？有没有投保人账号、时间戳、设备信息？\n\nB. 完整性：有没有阅读时长？各页面停留多久？点击路径能不能还原？\n\nC. 可跳过性：强制停留能不能绕过？视频能不能快进/关闭？条款是否需要滚动才能看全？\n\nD. 内容匹配：加黑加粗的是不是本案争议的那一条？条款文本是否与保单所附一致？\n\n\n\n每项给出【一句话问法】，可以直接在庭上说。\n\n最后加一段：如果保险人答不上来，对应的法律后果是什么。\n\n</code></pre>\n<hr>\n<h2 id=\"s27\">19 · 诉讼时效自查（3 年还是 2 年）</h2>\n<pre><code>\n你是保险法实务助理。帮我判断这个案子的诉讼时效。\n\n\n\n【必须适用的规则】\n\n1. 《保险法》§26 写的是\"二年\"，但广州中院 (2025)粤01民终19766号认定：\n\n   该两年规定系对当时民法通则普通时效的照准适用，属一般性规定，\n\n   民法典施行后应适用【三年】诉讼时效。\n\n2. 起算点是\"知道或者应当知道保险事故发生之日\"，【不是客观出险日】。\n\n   该案中保险人一直未告知保单内容，被保险人 2024 年电话询问才得知，\n\n   时效从 2024 年起算，2025 年起诉仍获支持。\n\n3. 人寿保险是 5 年。责任保险自\"被保险人对第三者的赔偿责任确定之日\"起算（解释四 §18）。\n\n\n\n【请按此输出】\n\n一、本案适用几年时效？依据是什么？\n\n二、起算点应该是哪一天？如果有多个候选日期，逐一分析并给出最有利的一个及理由。\n\n三、有没有发生过时效中断/中止的事由（催告、律师函、投诉、协商记录）？\n\n    我给你时间线，你帮我找。\n\n四、如果时效看起来已经过了，还有没有补救路径？（如：主张保险人未告知导致不知情、\n\n    构成其他请求权基础等）——没有就说没有，不要编。\n\n五、给我一句可直接写进起诉状/答辩状的时效表述。\n\n\n\n【硬约束】\n\n- 不得编造案号、法条。\n\n- 时间线以外的事实，如果我没有提供，写\"需补充\"。\n\n</code></pre>", "toc": [{"id": "s1", "lv": 2, "t": "零号指令 · 通用前置设定（每次开新对话先贴这个）"}, {"id": "s2", "lv": 2, "t": "一、案件诊断类"}, {"id": "s3", "lv": 3, "t": "1.1 拿到拒赔通知书后的 30 分钟定位"}, {"id": "s4", "lv": 3, "t": "1.2 让 AI 扮演对方，做对抗式检验"}, {"id": "s5", "lv": 2, "t": "二、条款审查类"}, {"id": "s6", "lv": 3, "t": "2.1 扫描一份保单里的\"地雷条款\""}, {"id": "s7", "lv": 3, "t": "2.2 比对\"投保时条款\"与\"现行条款\""}, {"id": "s8", "lv": 2, "t": "三、检索类（防幻觉重点区）"}, {"id": "s9", "lv": 3, "t": "3.1 找判例（严格版）"}, {"id": "s10", "lv": 3, "t": "3.2 核验一个已有案号"}, {"id": "s11", "lv": 3, "t": "3.3 法条核对"}, {"id": "s12", "lv": 2, "t": "四、文书生成类"}, {"id": "s13", "lv": 3, "t": "4.1 起诉状"}, {"id": "s14", "lv": 3, "t": "4.2 保险消费者投诉信（给 12378 / 保险公司总部）"}, {"id": "s15", "lv": 3, "t": "4.3 律师函（理赔催告，兼中断诉讼时效）"}, {"id": "s16", "lv": 2, "t": "五、对外输出类（给普通人看）"}, {"id": "s17", "lv": 3, "t": "5.1 把法律分析改写成大白话"}, {"id": "s18", "lv": 3, "t": "5.2 生成一份\"给家人看的投保提醒\""}, {"id": "s19", "lv": 2, "t": "六、学习与复盘类"}, {"id": "s20", "lv": 3, "t": "6.1 用费曼方式吃透一个概念"}, {"id": "s21", "lv": 3, "t": "6.2 案件复盘"}, {"id": "s22", "lv": 2, "t": "七、反幻觉核验（每次生成重要内容后跑一遍）"}, {"id": "s23", "lv": 2, "t": "附：几个使用习惯建议"}, {"id": "s24", "lv": 2, "t": "16 · 车险\"改变使用性质 / 营运\"拒赔案审查"}, {"id": "s25", "lv": 2, "t": "17 · 免责条款用词比对（找 §30 不利解释的突破口）"}, {"id": "s26", "lv": 2, "t": "18 · 互联网投保可回溯证据质证清单生成器"}, {"id": "s27", "lv": 2, "t": "19 · 诉讼时效自查（3 年还是 2 年）"}], "text": "AI 协作指令库（可直接复制使用） 怎么用 ：每条指令都设计成\"复制粘贴即可跑\"。方括号 【】 里的内容替换成你的实际情况。 建议 ：把\"零号指令\"存成你的常用前缀，每次开新对话先贴一遍，能显著减少胡说八道。 零号指令 · 通用前置设定（每次开新对话先贴这个） 为什么这么写 ：第 2、3 条是防幻觉的核心。AI 编案号是这类工作里 唯一的致命错误 ——内容写错可以改，引用一个不存在的判例在法庭上是灾难。第 4 条强迫 AI 区分\"有规定\"和\"它觉得\"，避免把学理当裁判规则。 一、案件诊断类 1.1 拿到拒赔通知书后的 30 分钟定位 注意 ：把时间轴填全是关键。保险纠纷里， 时间往往比道理更重要 ——30 日、2 年、60 日、诉讼时效，任何一个都可能直接决定胜负。 1.2 让 AI 扮演对方，做对抗式检验 为什么这么写 ：单方推理会自我强化。让 AI 先当对手，能提前暴露你没想到的抗辩——尤其是保险人常用的\"第 9 条第 2 款反向规定\"（违反义务的解除权条款不算免责条款）这类冷门点。 二、条款审查类 2.1 扫描一份保单里的\"地雷条款\" 注意 ：AI 读长 PDF 会丢内容。 条款超过 30 页就分段喂 ，并且每次让它复述\"你读到了哪些章节\"确认没漏。 2.2 比对\"投保时条款\"与\"现行条款\" 为什么有用 ：保险公司常拿 新版条款 来抗辩，但合同成立时适用的是旧版。这个差异能成为独立攻击点。 三、检索类（防幻觉重点区） 3.1 找判例（严格版） ⚠️ 最重要的一条 ：AI 给的案号， 用之前必须自己核一遍 （中国裁判文书网、人民法院案例库、法院官网）。AI 编案号的概率不低，尤其是\"看起来很合理\"的那种。 3.2 核验一个已有案号 3.3 法条核对 四、文书生成类 4.1 起诉状 4.2 保险消费者投诉信（给 12378 / 保险公司总部） 4.3 律师函（理赔催告，兼中断诉讼时效） 五、对外输出类（给普通人看） 5.1 把法律分析改写成大白话 5.2 生成一份\"给家人看的投保提醒\" 六、学习与复盘类 6.1 用费曼方式吃透一个概念 6.2 案件复盘 七、反幻觉核验（每次生成重要内容后跑一遍） 为什么必须有这一步 ：这一步能拦掉大部分编造。AI 在被要求\"自证来源\"时，通常会承认哪些是编的。 不要跳过。 附：几个使用习惯建议 1. 重要内容让两个不同模型各写一遍 ，对比差异。差异点往往就是幻觉点。 2. 法条和案号一律自己核一遍 ，尤其是要写进诉状的。 3. 长文档分段喂 ，每段结束让 AI 复述它读到了什么，确认没丢内容。 4. 让 AI 给\"最不利于我的点\" ，比让它给\"支持我的点\"价值高得多。 5. 不要问\"我能不能赢\" ——问\"法院会怎么认定 X 这个问题\"，答案有用得多。 16 · 车险\"改变使用性质 / 营运\"拒赔案审查 复制前先跑一次本库开头的「零号指令」前置设定。 17 · 免责条款用词比对（找 §30 不利解释的突破口） 这条成本极低、命中率不低，建议每个拒赔案都跑一遍。 18 · 互联网投保可回溯证据质证清单生成器 19 · 诉讼时效自查（3 年还是 2 年）"}, {"id": "L4-法条库/00-法条与司法解释原文", "group": "5 · 法条原文", "groupKey": "L4-法条库", "title": "保险法 · 法条与司法解释原文留档", "order": 5, "file": "00-法条与司法解释原文.md", "html": "<h1 id=\"s0\">保险法 · 法条与司法解释原文留档</h1>\n<blockquote>抓取日期：2026-09-16 ｜ 生成脚本：<code>_work/gen_laws.py</code><br><strong>使用规则</strong>：本文件为原文留档。任何条文对外引用前，须与国家法律法规数据库最新版本核对一次。<br>标注说明：<code>【原文未获取，待补】</code> = 本次未抓到，禁止用记忆填充。</blockquote>\n<h2 id=\"s1\">一、《中华人民共和国保险法》（2009 年修订 / 2015 年修正）</h2>\n<blockquote>来源：郑州航空港经济综合实验区管委会转载全文（2020-09-24）<br>&lt;https://www.zzhkgq.gov.cn/2020/09-24/3379060.html&gt;</blockquote>\n<h3 id=\"s2\">第 10 条</h3>\n<p>【原文未获取，待补】</p>\n<h3 id=\"s3\">第 11 条</h3>\n<blockquote>订立保险合同，应当协商一致，遵循公平原则确定各方的权利和义务。 除法律、行政法规规定必须保险的外，保险合同自愿订立。</blockquote>\n<h3 id=\"s4\">第 12 条</h3>\n<blockquote>人身保险的投保人在保险合同订立时，对被保险人应当具有保险利益。 财产保险的被保险人在保险事故发生时，对保险标的应当具有保险利益。 人身保险是以人的寿命和身体为保险标的的保险。 财产保险是以财产及其有关利益为保险标的的保险。 被保险人是指其财产或者人身受保险合同保障，享有保险金请求权的人。投保人可以为被保险人。 保险利益是指投保人或者被保险人对保险标的具有的法律上承认的利益。</blockquote>\n<h3 id=\"s5\">第 13 条</h3>\n<blockquote>投保人提出保险要求，经保险人同意承保，保险合同成立。保险人应当及时向投保人签发保险单或者其他保险凭证。 保险单或者其他保险凭证应当载明当事人双方约定的合同内容。当事人也可以约定采用其他书面形式载明合同内容。 依法成立的保险合同，自成立时生效。投保人和保险人可以对合同的效力约定附条件或者附期限。</blockquote>\n<h3 id=\"s6\">第 14 条</h3>\n<blockquote>保险合同成立后，投保人按照约定交付保险费，保险人按照约定的时间开始承担保险责任。</blockquote>\n<h3 id=\"s7\">第 15 条</h3>\n<blockquote>除本法另有规定或者保险合同另有约定外，保险合同成立后，投保人可以解除合同，保险人不得解除合同。</blockquote>\n<h3 id=\"s8\">第 16 条【如实告知义务 · 两年不可抗辩 —— 保险纠纷第一战场】</h3>\n<blockquote>订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。 投保人故意或者因重大过失未履行前款规定的如实告知义务，足以影响保险人决定是否同意承保或者提高保险费率的，保险人有权解除合同。 前款规定的合同解除权，自保险人知道有解除事由之日起，超过三十日不行使而消灭。自合同成立之日起超过两年的，保险人不得解除合同；发生保险事故的，保险人应当承担赔偿或者给付保险金的责任。 投保人故意不履行如实告知义务的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，并不退还保险费。 投保人因重大过失未履行如实告知义务，对保险事故的发生有严重影响的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，但应当退还保险费。 保险人在合同订立时已经知道投保人未如实告知的情况的，保险人不得解除合同；发生保险事故的，保险人应当承担赔偿或者给付保险金的责任。 保险事故是指保险合同约定的保险责任范围内的事故。</blockquote>\n<h3 id=\"s9\">第 17 条【格式条款说明义务 · 免责条款提示与明确说明 —— 保险纠纷第二战场】</h3>\n<blockquote>订立保险合同，采用保险人提供的格式条款的，保险人向投保人提供的投保单应当附格式条款，保险人应当向投保人说明合同的内容。 对保险合同中免除保险人责任的条款，保险人在订立合同时应当在投保单、保险单或者其他保险凭证上作出足以引起投保人注意的提示，并对该条款的内容以书面或者口头形式向投保人作出明确说明；未作提示或者明确说明的，该条款不产生效力。</blockquote>\n<h3 id=\"s10\">第 18 条</h3>\n<blockquote>保险合同应当包括下列事项： （一）保险人的名称和住所； （二）投保人、被保险人的姓名或者名称、住所，以及人身保险的受益人的姓名或者名称、住所； （三）保险标的； （四）保险责任和责任免除； （五）保险期间和保险责任开始时间； （六）保险金额； （七）保险费以及支付办法； （八）保险金赔偿或者给付办法； （九）违约责任和争议处理； （十）订立合同的年、月、日。 投保人和保险人可以约定与保险有关的其他事项。 受益人是指人身保险合同中由被保险人或者投保人指定的享有保险金请求权的人。投保人、被保险人可以为受益人。 保险金额是指保险人承担赔偿或者给付保险金责任的最高限额。</blockquote>\n<h3 id=\"s11\">第 19 条【格式条款无效】</h3>\n<blockquote>采用保险人提供的格式条款订立的保险合同中的下列条款无效： （一）免除保险人依法应承担的义务或者加重投保人、被保险人责任的； （二）排除投保人、被保险人或者受益人依法享有的权利的。</blockquote>\n<h3 id=\"s12\">第 21 条</h3>\n<blockquote>投保人、被保险人或者受益人知道保险事故发生后，应当及时通知保险人。故意或者因重大过失未及时通知，致使保险事故的性质、原因、 损失程度等难以确定的，保险人对无法确定的部分，不承担赔偿或者给付保险金的责任，但保险人通过其他途径已经及时知道或者应当及时知道保险事故发生的除 外。</blockquote>\n<h3 id=\"s13\">第 22 条</h3>\n<blockquote>保险事故发生后，按照保险合同请求保险人赔偿或者给付保险金时，投保人、被保险人或者受益人应当向保险人提供其所能提供的与确认保险事故的性质、原因、损失程度等有关的证明和资料。 保险人按照合同的约定，认为有关的证明和资料不完整的，应当及时一次性通知投保人、被保险人或者受益人补充提供。</blockquote>\n<h3 id=\"s14\">第 23 条【核定与赔付期限（三十日）】</h3>\n<blockquote>保险人收到被保险人或者受益人的赔偿或者给付保险金的请求后，应当及时作出核定；情形复杂的，应当在三十日内作出核定，但合同另有 约定的除外。保险人应当将核定结果通知被保险人或者受益人；对属于保险责任的，在与被保险人或者受益人达成赔偿或者给付保险金的协议后十日内，履行赔偿或 者给付保险金义务。保险合同对赔偿或者给付保险金的期限有约定的，保险人应当按照约定履行赔偿或者给付保险金义务。 保险人未及时履行前款规定义务的，除支付保险金外，应当赔偿被保险人或者受益人因此受到的损失。 任何单位和个人不得非法干预保险人履行赔偿或者给付保险金的义务，也不得限制被保险人或者受益人取得保险金的权利。</blockquote>\n<h3 id=\"s15\">第 24 条</h3>\n<blockquote>保险人依照本法</blockquote>\n<h3 id=\"s16\">第 25 条</h3>\n<blockquote>保险人自收到赔偿或者给付保险金的请求和有关证明、资料之日起六十日内，对其赔偿或者给付保险金的数额不能确定的，应当根据已有证明和资料可以确定的数额先予支付；保险人最终确定赔偿或者给付保险金的数额后，应当支付相应的差额。</blockquote>\n<h3 id=\"s17\">第 26 条</h3>\n<blockquote>人寿保险以外的其他保险的被保险人或者受益人，向保险人请求赔偿或者给付保险金的诉讼时效期间为二年，自其知道或者应当知道保险事故发生之日起计算。 人寿保险的被保险人或者受益人向保险人请求给付保险金的诉讼时效期间为五年，自其知道或者应当知道保险事故发生之日起计算。</blockquote>\n<h3 id=\"s18\">第 30 条【不利解释规则（疑义利益解释）】</h3>\n<blockquote>采用保险人提供的格式条款订立的保险合同，保险人与投保人、被保险人或者受益人对合同条款有争议的，应当按照通常理解予以解释。对合同条款有两种以上解释的，人民法院或者仲裁机构应当作出有利于被保险人和受益人的解释。</blockquote>\n<h3 id=\"s19\">第 31 条</h3>\n<blockquote>投保人对下列人员具有保险利益： （一）本人； （二）配偶、子女、父母； （三）前项以外与投保人有抚养、赡养或者扶养关系的家庭其他成员、近亲属； （四）与投保人有劳动关系的劳动者。 除前款规定外，被保险人同意投保人为其订立合同的，视为投保人对被保险人具有保险利益。 订立合同时，投保人对被保险人不具有保险利益的，合同无效。</blockquote>\n<h3 id=\"s20\">第 34 条</h3>\n<blockquote>以死亡为给付保险金条件的合同，未经被保险人同意并认可保险金额的，合同无效。 按照以死亡为给付保险金条件的合同所签发的保险单，未经被保险人书面同意，不得转让或者质押。 父母为其未成年子女投保的人身保险，不受本条第一款规定限制。</blockquote>\n<h3 id=\"s21\">第 36 条</h3>\n<blockquote>合同约定分期支付保险费，投保人支付首期保险费后，除合同另有约定外，投保人自保险人催告之日起超过三十日未支付当期保险费，或者超过约定的期限六十日未支付当期保险费的，合同效力中止，或者由保险人按照合同约定的条件减少保险金额。 被保险人在前款规定期限内发生保险事故的，保险人应当按照合同约定给付保险金，但可以扣减欠交的保险费。</blockquote>\n<h3 id=\"s22\">第 37 条</h3>\n<blockquote>合同效力依照本法</blockquote>\n<h3 id=\"s23\">第 43 条</h3>\n<blockquote>规定外，不退还保险费。 保险事故发生后，投保人、被保险人或者受益人以伪造、变造的有关证明、资料或者其他证据，编造虚假的事故原因或者夸大损失程度的，保险人对其虚报的部分不承担赔偿或者给付保险金的责任。 投保人、被保险人或者受益人有前三款规定行为之一，致使保险人支付保险金或者支出费用的，应当退回或者赔偿。</blockquote>\n<h3 id=\"s24\">第 44 条</h3>\n<blockquote>以被保险人死亡为给付保险金条件的合同，自合同成立或者合同效力恢复之日起二年内，被保险人自杀的，保险人不承担给付保险金的责任，但被保险人自杀时为无民事行为能力人的除外。 保险人依照前款规定不承担给付保险金责任的，应当按照合同约定退还保险单的现金价值。</blockquote>\n<h3 id=\"s25\">第 45 条</h3>\n<blockquote>因被保险人故意犯罪或者抗拒依法采取的刑事强制措施导致其伤残或者死亡的，保险人不承担给付保险金的责任。投保人已交足二年以上保险费的，保险人应当按照合同约定退还保险单的现金价值。</blockquote>\n<h3 id=\"s26\">第 47 条</h3>\n<blockquote>投保人解除合同的，保险人应当自收到解除合同通知之日起三十日内，按照合同约定退还保险单的现金价值。</blockquote>\n<h3 id=\"s27\">第 52 条【危险程度显著增加的通知义务（车险营运争议核心）】</h3>\n<blockquote>在合同有效期内，保险标的的危险程度显著增加的，被保险人应当按照合同约定及时通知保险人，保险人可以按照合同约定增加保险费或者 解除合同。保险人解除合同的，应当将已收取的保险费，按照合同约定扣除自保险责任开始之日起至合同解除之日止应收的部分后，退还投保人。 被保险人未履行前款规定的通知义务的，因保险标的的危险程度显著增加而发生的保险事故，保险人不承担赔偿保险金的责任。</blockquote>\n<h3 id=\"s28\">第 55 条</h3>\n<blockquote>投保人和保险人约定保险标的的保险价值并在合同中载明的，保险标的发生损失时，以约定的保险价值为赔偿计算标准。 投保人和保险人未约定保险标的的保险价值的，保险标的发生损失时，以保险事故发生时保险标的的实际价值为赔偿计算标准。 保险金额不得超过保险价值。超过保险价值的，超过部分无效，保险人应当退还相应的保险费。 保险金额低于保险价值的，除合同另有约定外，保险人按照保险金额与保险价值的比例承担赔偿保险金的责任。</blockquote>\n<h3 id=\"s29\">第 57 条</h3>\n<blockquote>保险事故发生时，被保险人应当尽力采取必要的措施，防止或者减少损失。 保险事故发生后，被保险人为防止或者减少保险标的的损失所支付的必要的、合理的费用，由保险人承担；保险人所承担的费用数额在保险标的损失赔偿金额以外另行计算，最高不超过保险金额的数额。</blockquote>\n<h3 id=\"s30\">第 60 条【代位求偿权】</h3>\n<blockquote>因第三者对保险标的的损害而造成保险事故的，保险人自向被保险人赔偿保险金之日起，在赔偿金额范围内代位行使被保险人对第三者请求赔偿的权利。 前款规定的保险事故发生后，被保险人已经从第三者取得损害赔偿的，保险人赔偿保险金时，可以相应扣减被保险人从第三者已取得的赔偿金额。 保险人依照本条第一款规定行使代位请求赔偿的权利，不影响被保险人就未取得赔偿的部分向第三者请求赔偿的权利。</blockquote>\n<h3 id=\"s31\">第 61 条</h3>\n<blockquote>保险事故发生后，保险人未赔偿保险金之前，被保险人放弃对第三者请求赔偿的权利的，保险人不承担赔偿保险金的责任。 保险人向被保险人赔偿保险金后，被保险人未经保险人同意放弃对第三者请求赔偿的权利的，该行为无效。 被保险人故意或者因重大过失致使保险人不能行使代位请求赔偿的权利的，保险人可以扣减或者要求返还相应的保险金。</blockquote>\n<h3 id=\"s32\">第 62 条</h3>\n<blockquote>除被保险人的家庭成员或者其组成人员故意造成本法</blockquote>\n<h3 id=\"s33\">第 65 条</h3>\n<blockquote>保险人对责任保险的被保险人给第三者造成的损害，可以依照法律的规定或者合同的约定，直接向该第三者赔偿保险金。 责任保险的被保险人给第三者造成损害，被保险人对第三者应负的赔偿责任确定的，根据被保险人的请求，保险人应当直接向该第三者赔偿保险金。被保险人怠于请求的，第三者有权就其应获赔偿部分直接向保险人请求赔偿保险金。 责任保险的被保险人给第三者造成损害，被保险人未向该第三者赔偿的，保险人不得向被保险人赔偿保险金。 责任保险是指以被保险人对第三者依法应负的赔偿责任为保险标的的保险。</blockquote>\n<blockquote>本次从全文中成功提取 31 / 32 条。</blockquote>\n<h2 id=\"s34\">二、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（二）》法释〔2013〕14 号</h2>\n<blockquote>施行：2013-06-08 施行（2020 年修正） ｜ 来源：&lt;https://www.court.gov.cn/shenpan/xiangqing/5427.html&gt;</blockquote>\n<p><strong>第 十 条</strong></p>\n<blockquote>保险人将法律、行政法规中的禁止性规定情形作为保险合同免责条款的免责事由，保险人对该条款作出提示后，投保人、被保险人或者受益人以保险人未履行明确说明义务为由主张该条款不生效的，人民法院不予支持。</blockquote>\n<p><strong>第 一 条</strong></p>\n<blockquote>财产保险中，不同投保人就同一保险标的分别投保，保险事故发生后，被保险人在其保险利益范围内依据保险合同主张保险赔偿的，人民法院应予支持。</blockquote>\n<p><strong>第 二 条</strong></p>\n<blockquote>人身保险中，因投保人对被保险人不具有保险利益导致保险合同无效，投保人主张保险人退还扣减相应手续费后的保险费的，人民法院应予支持。</blockquote>\n<p><strong>第 三 条</strong></p>\n<blockquote>投保人或者投保人的代理人订立保险合同时没有亲自签字或者盖章，而由保险人或者保险人的代理人代为签字或者盖章的，对投保人不生效。但投保人已经交纳保险费的，视为其对代签字或者盖章行为的追认。<br>保险人或者保险人的代理人代为填写保险单证后经投保人签字或者盖章确认的，代为填写的内容视为投保人的真实意思表示。但有证据证明保险人或者保险人的代理人存在保险法第一百一十六条、第一百三十一条相关规定情形的除外。</blockquote>\n<p><strong>第 四 条</strong></p>\n<blockquote>保险人接受了投保人提交的投保单并收取了保险费, 尚未作出是否承保的意思表示，发生保险事故，被保险人或者受益人请求保险人按照保险合同承担赔偿或者给付保险金责任，符合承保条件的，人民法院应予支持；不符合承保条件的，保险人不承担保险责任，但应当退还已经收取的保险费。<br>保险人主张不符合承保条件的，应承担举证责任。</blockquote>\n<p><strong>第 五 条</strong></p>\n<blockquote>保险合同订立时，投保人明知的与保险标的或者被保险人有关的情况，属于保险法第十六条第一款规定的投保人“应当如实告知”的内容。</blockquote>\n<p><strong>第 六 条</strong></p>\n<blockquote>投保人的告知义务限于保险人询问的范围和内容。当事人对询问范围及内容有争议的，保险人负举证责任。<br>保险人以投保人违反了对投保单询问表中所列概括性条款的如实告知义务为由请求解除合同的，人民法院不予支持。但该概括性条款有具体内容的除外。</blockquote>\n<p><strong>第 七 条</strong></p>\n<blockquote>保险人在保险合同成立后知道或者应当知道投保人未履行如实告知义务，仍然收取保险费，又依照保险法第十六条第二款的规定主张解除合同的，人民法院不予支持。</blockquote>\n<p><strong>第 八 条</strong></p>\n<blockquote>保险人未行使合同解除权，直接以存在保险法第十六条第四款、第五款规定的情形为由拒绝赔偿的，人民法院不予支持。但当事人就拒绝赔偿事宜及保险合同存续另行达成一致的情况除外。</blockquote>\n<p><strong>第 九 条</strong></p>\n<blockquote>保险人提供的格式合同文本中的责任免除条款、免赔额、免赔率、比例赔付或者给付等免除或者减轻保险人责任的条款，可以认定为保险法第十七条第二款规定的“免除保险人责任的条款”。<br>保险人因投保人、被保险人违反法定或者约定义务，享有解除合同权利的条款，不属于保险法第十七条第二款规定的“免除保险人责任的条款”。</blockquote>\n<p><strong>第 十一 条</strong></p>\n<blockquote>保险合同订立时，保险人在投保单或者保险单等其他保险凭证上，对保险合同中免除保险人责任的条款，以足以引起投保人注意的文字、字体、符号或者其他明显标志作出提示的，人民法院应当认定其履行了保险法第十七条第二款规定的提示义务。<br>保险人对保险合同中有关免除保险人责任条款的概念、内容及其法律后果以书面或者口头形式向投保人作出常人能够理解的解释说明的，人民法院应当认定保险人履行了保险法第十七条第二款规定的明确说明义务。</blockquote>\n<p><strong>第 十二 条</strong></p>\n<blockquote>通过网络、电话等方式订立的保险合同，保险人以网页、音频、视频等形式对免除保险人责任条款予以提示和明确说明的，人民法院可以认定其履行了提示和明确说明义务。</blockquote>\n<p><strong>第 十三 条</strong></p>\n<blockquote>保险人对其履行了明确说明义务负举证责任。<br>投保人对保险人履行了符合本解释第十一条第二款要求的明确说明义务在相关文书上签字、盖章或者以其他形式予以确认的，应当认定保险人履行了该项义务。但另有证据证明保险人未履行明确说明义务的除外。</blockquote>\n<p><strong>第 十四 条</strong></p>\n<blockquote>保险合同中记载的内容不一致的，按照下列规则认定：<br>（一）投保单与保险单或者其他保险凭证不一致的，以投保单为准。但不一致的情形系经保险人说明并经投保人同意的，以投保人签收的保险单或者其他保险凭证载明的内容为准；<br>（二）非格式条款与格式条款不一致的，以非格式条款为准；<br>（三）保险凭证记载的时间不同的，以形成时间在后的为准；<br>（四）保险凭证存在手写和打印两种方式的，以双方签字、盖章的手写部分的内容为准。</blockquote>\n<p><strong>第 十五 条</strong></p>\n<blockquote>保险法第二十三条规定的三十日核定期间，应自保险人初次收到索赔请求及投保人、被保险人或者受益人提供的有关证明和资料之日起算。<br>保险人主张扣除投保人、被保险人或者受益人补充提供有关证明和资料期间的，人民法院应予支持。扣除期间自保险人根据保险法第二十二条规定作出的通知到达投保人、被保险人或者受益人之日起，至投保人、被保险人或者受益人按照通知要求补充提供的有关证明和资料到达保险人之日止。</blockquote>\n<p><strong>第 十六 条</strong></p>\n<blockquote>保险人应以自己的名义行使保险代位求偿权。<br>根据保险法第六十条第一款的规定，保险人代位求偿权的诉讼时效期间应自其取得代位求偿权之日起算。</blockquote>\n<p><strong>第 十七 条</strong></p>\n<blockquote>保险人在其提供的保险合同格式条款中对非保术语所作的解释符合专业意义，或者虽不符合专业意义，但有利于投保人、被保险人或者受益人的，人民法院应予认可。</blockquote>\n<p><strong>第 十八 条</strong></p>\n<blockquote>行政管理部门依据法律规定制作的交通事故认定书、火灾事故认定书等，人民法院应当依法审查并确认其相应的证明力，但有相反证据能够推翻的除外。</blockquote>\n<p><strong>第 十九 条</strong></p>\n<blockquote>保险事故发生后，被保险人或者受益人起诉保险人，保险人以被保险人或者受益人未要求第三者承担责任为由抗辩不承担保险责任的，人民法院不予支持。<br>财产保险事故发生后，被保险人就其所受损失从第三者取得赔偿后的不足部分提起诉讼，请求保险人赔偿的，人民法院应予依法受理。</blockquote>\n<p><strong>第 二十 条</strong></p>\n<blockquote>保险公司依法设立并取得营业执照的分支机构属于《中华人民共和国民事诉讼法》第四十八条规定的其他组织，可以作为保险合同纠纷案件的当事人参加诉讼。</blockquote>\n<p><strong>第 二十一 条</strong></p>\n<blockquote>本解释施行后尚未终审的保险合同纠纷案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。<br>--&gt;<br>--&gt;<br>相关报道--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>--&gt;<br>中国共产党新闻网<br>|<br>中国政府网<br>|<br>中国人大网<br>|<br>中国政协网<br>|<br>中国法院网<br>|<br>最高人民检察院<br>全国人民法庭信息网<br>|<br>人民法院诉讼资产网<br>地址：北京市东城区东交民巷27号<br>邮编：100745<br>总机：67550114<br>举报电话：67556131<br>中华人民共和国最高人民法院 版权所有<br>京公网安备<br>11040102700145号<br>|<br>京ICP备05023036号<br>f11e35f5e90c74fe8757ccd4505a3e89</blockquote>\n<blockquote>已提取 21 条。</blockquote>\n<h2 id=\"s35\">三、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（三）》法释〔2015〕21 号</h2>\n<blockquote>施行：2015-12-01 施行 ｜ 来源：&lt;https://sxszzy.shanxify.gov.cn/article/detail/2015/12/id/1760086.shtml（朔州中院转载最高法发布稿）&gt;</blockquote>\n<p><strong>第 十 条</strong></p>\n<blockquote>投保人或者被保险人变更受益人，当事人主张变更行为自变更意思表示发出时生效的，人民法院应予支持。<br>投保人或者被保险人变更受益人未通知保险人，保险人主张变更对其不发生效力的，人民法院应予支持。<br>投保人变更受益人未经被保险人同意，人民法院应认定变更行为无效。</blockquote>\n<p><strong>第 一 条</strong></p>\n<blockquote>当事人订立以死亡为给付保险金条件的合同，根据保险法第三十四条的规定，&amp;ldquo;被保险人同意并认可保险金额&amp;rdquo;可以采取书面形式、口头形式或者其他形式；可以在合同订立时作出，也可以在合同订立后追认。<br>有下列情形之一的，应认定为被保险人同意投保人为其订立保险合同并认可保险金额：<br>（一）被保险人明知他人代其签名同意而未表示异议的；<br>（二）被保险人同意投保人指定的受益人的；<br>（三）有证据足以认定被保险人同意投保人为其投保的其他情形。</blockquote>\n<p><strong>第 二 条</strong></p>\n<blockquote>被保险人以书面形式通知保险人和投保人撤销其依据保险法第三十四条第一款规定所作出的同意意思表示的，可认定为保险合同解除。</blockquote>\n<p><strong>第 三 条</strong></p>\n<blockquote>人民法院审理人身保险合同纠纷案件时，应主动审查投保人订立保险合同时是否具有保险利益，以及以死亡为给付保险金条件的合同是否经过被保险人同意并认可保险金额。</blockquote>\n<p><strong>第 四 条</strong></p>\n<blockquote>保险合同订立后，因投保人丧失对被保险人的保险利益，当事人主张保险合同无效的，人民法院不予支持。</blockquote>\n<p><strong>第 五 条</strong></p>\n<blockquote>保险人在合同订立时指定医疗机构对被保险人体检，当事人主张投保人如实告知义务免除的，人民法院不予支持。<br>保险人知道被保险人的体检结果，仍以投保人未就相关情况履行如实告知义务为由要求解除合同的，人民法院不予支持。</blockquote>\n<p><strong>第 六 条</strong></p>\n<blockquote>未成年人父母之外的其他履行监护职责的人为未成年人订立以死亡为给付保险金条件的合同，当事人主张参照保险法第三十三条第二款、第三十四条第三款的规定认定该合同有效的，人民法院不予支持，但经未成年人父母同意的除外。</blockquote>\n<p><strong>第 七 条</strong></p>\n<blockquote>当事人以被保险人、受益人或者他人已经代为支付保险费为由，主张投保人对应的交费义务已经履行的，人民法院应予支持。</blockquote>\n<p><strong>第 八 条</strong></p>\n<blockquote>保险合同效力依照保险法第三十六条规定中止，投保人提出恢复效力申请并同意补交保险费的，除被保险人的危险程度在中止期间显著增加外，保险人拒绝恢复效力的，人民法院不予支持。<br>保险人在收到恢复效力申请后，三十日内未明确拒绝的，应认定为同意恢复效力。<br>保险合同自投保人补交保险费之日恢复效力。保险人要求投保人补交相应利息的，人民法院应予支持。</blockquote>\n<p><strong>第 九 条</strong></p>\n<blockquote>投保人指定受益人未经被保险人同意的，人民法院应认定指定行为无效。<br>当事人对保险合同约定的受益人存在争议，除投保人、被保险人在保险合同之外另有约定外，按以下情形分别处理：<br>（一）受益人约定为&amp;ldquo;法定&amp;rdquo;或者&amp;ldquo;法定继承人&amp;rdquo;的，以继承法规定的法定继承人为受益人；<br>（二）受益人仅约定为身份关系的，投保人与被保险人为同一主体时，根据保险事故发生时与被保险人的身份关系确定受益人；投保人与被保险人为不同主体时，根据保险合同成立时与被保险人的身份关系确定受益人；<br>（三）约定的受益人包括姓名和身份关系，保险事故发生时身份关系发生变化的，认定为未指定受益人。</blockquote>\n<p><strong>第 十一 条</strong></p>\n<blockquote>投保人或者被保险人在保险事故发生后变更受益人，变更后的受益人请求保险人给付保险金的，人民法院不予支持。</blockquote>\n<p><strong>第 十二 条</strong></p>\n<blockquote>投保人或者被保险人指定数人为受益人，部分受益人在保险事故发生前死亡、放弃受益权或者依法丧失受益权的，该受益人应得的受益份额按照保险合同的约定处理；保险合同没有约定或者约定不明的，该受益人应得的受益份额按照以下情形分别处理：<br>（一）未约定受益顺序及受益份额的，由其他受益人平均享有；<br>（二）未约定受益顺序但约定受益份额的,由其他受益人按照相应比例享有；<br>（三）约定受益顺序但未约定受益份额的，由同顺序的其他受益人平均享有；同一顺序没有其他受益人的，由后一顺序的受益人平均享有；<br>（四）约定受益顺序及受益份额的，由同顺序的其他受益人按照相应比例享有；同一顺序没有其他受益人的，由后一顺序的受益人按照相应比例享有。</blockquote>\n<p><strong>第 十三 条</strong></p>\n<blockquote>保险事故发生后，受益人将与本次保险事故相对应的全部或者部分保险金请求权转让给第三人 ，当事人主张该转让行为有效的，人民法院应予支持，但根据合同性质、当事人约定或者法律规定不得转让的除外。</blockquote>\n<p><strong>第 十四 条</strong></p>\n<blockquote>保险金根据保险法第四十二条规定作为被保险人遗产，被保险人的继承人要求保险人给付保险金，保险人以其已向持有保险单的被保险人的其他继承人给付保险金为由抗辩的，人民法院应予支持。</blockquote>\n<p><strong>第 十五 条</strong></p>\n<blockquote>受益人与被保险人存在继承关系，在同一事件中死亡且不能确定死亡先后顺序的，人民法院应依据保险法第四十二条第二款推定受益人死亡在先，并按照保险法及本解释的相关规定确定保险金归属。</blockquote>\n<p><strong>第 十六 条</strong></p>\n<blockquote>人身保险合同解除时，投保人与被保险人、受益人为不同主体，被保险人或者受益人要求退还保险单的现金价值的，人民法院不予支持，但保险合同另有约定的除外。<br>投保人故意造成被保险人死亡、伤残或者疾病，保险人依照保险法第四十三条规定退还保险单的现金价值的，其他权利人按照被保险人、被保险人的继承人的顺序确定。</blockquote>\n<p><strong>第 十七 条</strong></p>\n<blockquote>投保人解除保险合同，当事人以其解除合同未经被保险人或者受益人同意为由主张解除行为无效的，人民法院不予支持，但被保险人或者受益人已向投保人支付相当于保险单现金价值的款项并通知保险人的除外。</blockquote>\n<p><strong>第 十八 条</strong></p>\n<blockquote>保险人给付费用补偿型的医疗费用保险金时，主张扣减被保险人从公费医疗或者社会医疗保险取得的赔偿金额的，应当证明该保险产品在厘定医疗费用保险费率时已经将公费医疗或者社会医疗保险部分相应扣除，并按照扣减后的标准收取保险费。</blockquote>\n<p><strong>第 十九 条</strong></p>\n<blockquote>保险合同约定按照基本医疗保险的标准核定医疗费用，保险人以被保险人的医疗支出超出基本医疗保险范围为由拒绝给付保险金的，人民法院不予支持；保险人有证据证明被保险人支出的费用超过基本医疗保险同类医疗费用标准，要求对超出部分拒绝给付保险金的，人民法院应予支持。</blockquote>\n<p><strong>第 二十 条</strong></p>\n<blockquote>保险人以被保险人未在保险合同约定的医疗服务机构接受治疗为由拒绝给付保险金的，人民法院应予支持，但被保险人因情况紧急必须立即就医的除外。</blockquote>\n<p><strong>第 二十一 条</strong></p>\n<blockquote>保险人以被保险人自杀为由拒绝承担给付保险金责任的，由保险人承担举证责任。<br>受益人或者被保险人的继承人以被保险人自杀时无民事行为能力为由抗辩的，由其承担举证责任。</blockquote>\n<p><strong>第 二十二 条</strong></p>\n<blockquote>保险法第四十五条规定的&amp;ldquo;被保险人故意犯罪&amp;rdquo;的认定，应当以刑事侦查机关、检察机关和审判机关的生效法律文书或者其他结论性意见为依据。</blockquote>\n<p><strong>第 二十三 条</strong></p>\n<blockquote>保险人主张根据保险法第四十五条的规定不承担给付保险金责任的，应当证明被保险人的死亡、伤残结果与其实施的故意犯罪或者抗拒依法采取的刑事强制措施的行为之间存在因果关系。<br>被保险人在羁押、服刑期间因意外或者疾病造成伤残或者死亡，保险人主张根据保险法第四十五条的规定不承担给付保险金责任的，人民法院不予支持。</blockquote>\n<p><strong>第 二十四 条</strong></p>\n<blockquote>投保人为被保险人订立以死亡为给付保险金条件的人身保险合同，被保险人被宣告死亡后，当事人要求保险人按照保险合同约定给付保险金的，人民法院应予支持。<br>被保险人被宣告死亡之日在保险责任期间之外，但有证据证明下落不明之日在保险责任期间之内，当事人要求保险人按照保险合同约定给付保险金的，人民法院应予支持。</blockquote>\n<p><strong>第 二十五 条</strong></p>\n<blockquote>被保险人的损失系由承保事故或者非承保事故、免责事由造成难以确定，当事人请求保险人给付保险金的，人民法院可以按照相应比例予以支持。</blockquote>\n<p><strong>第 二十六 条</strong></p>\n<blockquote>本解释施行后尚未终审的保险合同纠纷案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。<br>来源：中国法院网            责任编辑：中院研究室<br>您是第位访客       \"&gt;网站地图       采稿邮箱<br>山西省朔州市中级人民法院版权所有，未经协议授权禁止下载使用或建立镜像<br>中国法院网负责网站设计制作 网络安全和技术维护<br>Copyright © 2025 by www.chinacourt.cn All Rights Reserved.<br>浏 览 本 网 站 推 荐 您 使 用  IE 8 以 上 浏 览 器</blockquote>\n<blockquote>已提取 26 条。</blockquote>\n<h2 id=\"s36\">四、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（四）》法释〔2018〕13 号</h2>\n<blockquote>施行：2018-09-01 施行 ｜ 来源：&lt;http://gongbao.court.gov.cn/Details/442f0649e12a198e6f9701a9830f7a.html&gt;</blockquote>\n<p><strong>第 十 条</strong></p>\n<blockquote>因第三者对保险标的的损害而造成保险事故，保险人获得代位请求赔偿的权利的情况未通知第三者或者通知到达第三者前,第三者在被保险人已经从保险人处获赔的范围内又向被保险人作出赔偿，保险人主张代位行使被保险人对第三者请求赔偿的权利的，人民法院不予支持。保险人就相应保险金主张被保险人返还的，人民法院应予支持。<br>保险人获得代位请求赔偿的权利的情况已经通知到第三者，第三者又向被保险人作出赔偿，保险人主张代位行使请求赔偿的权利，第三者以其已经向被保险人赔偿为由抗辩的，人民法院不予支持。</blockquote>\n<p><strong>第 一 条</strong></p>\n<blockquote>保险标的已交付受让人，但尚未依法办理所有权变更登记，承担保险标的毁损灭失风险的受让人，依照保险法第四十八条、第四十九条的规定主张行使被保险人权利的，人民法院应予支持。</blockquote>\n<p><strong>第 二 条</strong></p>\n<blockquote>保险人已向投保人履行了保险法规定的提示和明确说明义务，保险标的受让人以保险标的转让后保险人未向其提示或者明确说明为由，主张免除保险人责任的条款不生效的，人民法院不予支持。</blockquote>\n<p><strong>第 三 条</strong></p>\n<blockquote>被保险人死亡，继承保险标的的当事人主张承继被保险人的权利和义务的，人民法院应予支持。</blockquote>\n<p><strong>第 四 条</strong></p>\n<blockquote>人民法院认定保险标的是否构成保险法第四十九条、第五十二条规定的“危险程度显著增加”时，应当综合考虑以下因素：<br>（一） 保险标的用途的改变；<br>（二） 保险标的使用范围的改变；<br>（三） 保险标的所处环境的变化；<br>（四） 保险标的因改装等原因引起的变化；<br>（五） 保险标的使用人或者管理人的改变；<br>（六） 危险程度增加持续的时间;<br>（七） 其他可能导致危险程度显著增加的因素。<br>保险标的危险程度虽然增加，但增加的危险属于保险合同订立时保险人预见或者应当预见的保险合同承保范围的，不构成危险程度显著增加。</blockquote>\n<p><strong>第 五 条</strong></p>\n<blockquote>被保险人、受让人依法及时向保险人发出保险标的转让通知后,保险人作出答复前，发生保险事故，被保险人或者受让人主张保险人按照保险合同承担赔偿保险金的责任的，人民法院应予支持。</blockquote>\n<p><strong>第 六 条</strong></p>\n<blockquote>保险事故发生后，被保险人依照保险法第五十七条的规定，请求保险人承担为防止或者减少保险标的的损失所支付的必要、合理费用,保险人以被保险人采取的措施未产生实际效果为由抗辩的,人民法院不予支持。</blockquote>\n<p><strong>第 七 条</strong></p>\n<blockquote>保险人依照保险法第六十条的规定,主张代位行使被保险人因第三者侵权或者违约等享有的请求赔偿的权利的，人民法院应予支持。</blockquote>\n<p><strong>第 八 条</strong></p>\n<blockquote>投保人和被保险人为不同主体，因投保人对保险标的的损害而造成保险事故，保险人依法主张代位行使被保险人对投保人请求赔偿的权利的，人民法院应予支持，但法律另有规定或者保险合同另有约定的除外。</blockquote>\n<p><strong>第 九 条</strong></p>\n<blockquote>在保险人以第三者为被告提起的代位求偿权之诉中，第三者以被保险人在保险合同订立前已放弃对其请求赔偿的权利为由进行抗辩，人民法院认定上述放弃行为合法有效，保险人就相应部分主张行使代位求偿权的，人民法院不予支持。<br>保险合同订立时，保险人就是否存在上述放弃情形提出询问，投保人未如实告知，导致保险人不能代位行使请求赔偿的权利，保险人请求返还相应保险金的，人民法院应予支持，但保险人知道或者应当知道上述情形仍同意承保的除外。</blockquote>\n<p><strong>第 十一 条</strong></p>\n<blockquote>被保险人因故意或者重大过失未履行保险法第六十三条规定的义务，致使保险人未能行使或者未能全部行使代位请求赔偿的权利，保险人主张在其损失范围内扣减或者返还相应保险金的，人民法院应予支持。</blockquote>\n<p><strong>第 十二 条</strong></p>\n<blockquote>保险人以造成保险事故的第三者为被告提起代位求偿权之诉的，以被保险人与第三者之间的法律关系确定管辖法院。</blockquote>\n<p><strong>第 十三 条</strong></p>\n<blockquote>保险人提起代位求偿权之诉时，被保险人已经向第三者提起诉讼的，人民法院可以依法合并审理。<br>保险人行使代位求偿权时，被保险人已经向第三者提起诉讼，保险人向受理该案的人民法院申请变更当事人，代位行使被保险人对第三者请求赔偿的权利，被保险人同意的,人民法院应予准许;被保险人不同意的，保险人可以作为共同原告参加诉讼。</blockquote>\n<p><strong>第 十四 条</strong></p>\n<blockquote>具有下列情形之一的，被保险人可以依照保险法第六十五条第二款的规定请求保险人直接向第三者赔偿保险金：<br>（一）被保险人对第三者所负的赔偿责任经人民法院生效裁判、仲裁裁决确认；<br>（二）被保险人对第三者所负的赔偿责任经被保险人与第三者协商一致；<br>（三）被保险人对第三者应负的赔偿责任能够确定的其他情形。<br>前款规定的情形下,保险人主张按照保险合同确定保险赔偿责任的，人民法院应予支持。</blockquote>\n<p><strong>第 十五 条</strong></p>\n<blockquote>被保险人对第三者应负的赔偿责任确定后，被保险人不履行赔偿责任，且第三者以保险人为被告或者以保险人与被保险人为共同 被告提起诉讼时，被保险人尚未向保险人提出直接向第三者赔偿保险金的请求的，可以认定为属于保险法第六十五条第二款规定的“被保险人怠于请求”的情形。</blockquote>\n<p><strong>第 十六 条</strong></p>\n<blockquote>责任保险的被保险人因共同侵权依法承担连带责任，保险人以该连带责任超出被保险人应承担的责任份额为由，拒绝赔付保险金的，人民法院不予支持。保险人承担保险责任后,主张就超出被保险人责任份额的部分向其他连带责任人追偿的，人民法院应予支持。</blockquote>\n<p><strong>第 十七 条</strong></p>\n<blockquote>责任保险的被保险人对第三者所负的赔偿责任已经生效判决确认并已进入执行程序，但未获得清偿或者未获得全部清偿，第三者依法请求保险人赔偿保险金，保险人以前述生效判决已进入执行程序为由抗辩的，人民法院不予支持。</blockquote>\n<p><strong>第 十八 条</strong></p>\n<blockquote>商业责任险的被保险人向保险人请求赔偿保险金的诉讼时效期间，自被保险人对第三者应负的赔偿责任确定之日起计算。</blockquote>\n<p><strong>第 十九 条</strong></p>\n<blockquote>责任保险的被保险人与第三者就被保险人的赔偿责任达成和解协议且经保险人认可，被保险人主张保险人在保险合同范围内依据和解协议承担保险责任的，人民法院应予支持。<br>被保险人与第三者就被保险人的责任达成和解协议，未经保险人认可，保险人主张对保险责任范围以及赔偿数额重新予以核定的，人民法院应予支持。</blockquote>\n<p><strong>第 二十 条</strong></p>\n<blockquote>责任保险的保险人在被保险人向第三者赔偿之前向被保险人赔偿保险金，第三者依照保险法第六十五条第二款的规定行使保险金请求权时，保险人以其已向被保险人赔偿为由拒绝赔偿保险金的，人民法院不予支持。保险人向第三者赔偿后，请求被保险人返还相应保险金的，人民法院应予支持。</blockquote>\n<p><strong>第 二十一 条</strong></p>\n<blockquote>本解释自2018年9月1日起施行。<br>本解释施行后人民法院正在审理的一审、二审案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。<br>法律声明<br>|<br>联系我们<br>|<br>使用帮助<br>中华人民共和国最高人民法院 版权所有</blockquote>\n<blockquote>已提取 21 条。</blockquote>\n<h2 id=\"s37\">五、来源清单</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>文件</th><th>来源 URL</th><th>状态</th></tr></thead><tbody>\n<tr><td>保险法全文</td><td>https://www.zzhkgq.gov.cn/2020/09-24/3379060.html</td><td>成功（51886 字符）</td></tr>\n<tr><td>司法解释（二）</td><td>https://www.court.gov.cn/shenpan/xiangqing/5427.html</td><td>成功</td></tr>\n<tr><td>司法解释（三）</td><td>https://sxszzy.shanxify.gov.cn/article/detail/2015/12/id/1760086.shtml</td><td>成功</td></tr>\n<tr><td>司法解释（四）</td><td>最高人民法院公报 gongbao.court.gov.cn</td><td>成功</td></tr>\n<tr><td>司法解释（三）原始</td><td>最高人民法院公报 gongbao.court.gov.cn</td><td>抓取失败（502），改用山西朔州中院转载最高法发布稿</td></tr>\n</tbody></table></div>\n<h2 id=\"s38\">六、已知缺口</h2>\n<ul>\n<li>《全国法院民商事审判工作会议纪要》（九民纪要）涉保险部分：未抓取，待补</li>\n<li>《重大疾病保险的疾病定义使用规范（2020 年修订版）》官方原文：未抓取，待补</li>\n<li>民法典第 496-498 条（格式条款）原文：未抓取，待补</li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "一、《中华人民共和国保险法》（2009 年修订 / 2015 年修正）"}, {"id": "s2", "lv": 3, "t": "第 10 条"}, {"id": "s3", "lv": 3, "t": "第 11 条"}, {"id": "s4", "lv": 3, "t": "第 12 条"}, {"id": "s5", "lv": 3, "t": "第 13 条"}, {"id": "s6", "lv": 3, "t": "第 14 条"}, {"id": "s7", "lv": 3, "t": "第 15 条"}, {"id": "s8", "lv": 3, "t": "第 16 条【如实告知义务 · 两年不可抗辩 —— 保险纠纷第一战场】"}, {"id": "s9", "lv": 3, "t": "第 17 条【格式条款说明义务 · 免责条款提示与明确说明 —— 保险纠纷第二战场】"}, {"id": "s10", "lv": 3, "t": "第 18 条"}, {"id": "s11", "lv": 3, "t": "第 19 条【格式条款无效】"}, {"id": "s12", "lv": 3, "t": "第 21 条"}, {"id": "s13", "lv": 3, "t": "第 22 条"}, {"id": "s14", "lv": 3, "t": "第 23 条【核定与赔付期限（三十日）】"}, {"id": "s15", "lv": 3, "t": "第 24 条"}, {"id": "s16", "lv": 3, "t": "第 25 条"}, {"id": "s17", "lv": 3, "t": "第 26 条"}, {"id": "s18", "lv": 3, "t": "第 30 条【不利解释规则（疑义利益解释）】"}, {"id": "s19", "lv": 3, "t": "第 31 条"}, {"id": "s20", "lv": 3, "t": "第 34 条"}, {"id": "s21", "lv": 3, "t": "第 36 条"}, {"id": "s22", "lv": 3, "t": "第 37 条"}, {"id": "s23", "lv": 3, "t": "第 43 条"}, {"id": "s24", "lv": 3, "t": "第 44 条"}, {"id": "s25", "lv": 3, "t": "第 45 条"}, {"id": "s26", "lv": 3, "t": "第 47 条"}, {"id": "s27", "lv": 3, "t": "第 52 条【危险程度显著增加的通知义务（车险营运争议核心）】"}, {"id": "s28", "lv": 3, "t": "第 55 条"}, {"id": "s29", "lv": 3, "t": "第 57 条"}, {"id": "s30", "lv": 3, "t": "第 60 条【代位求偿权】"}, {"id": "s31", "lv": 3, "t": "第 61 条"}, {"id": "s32", "lv": 3, "t": "第 62 条"}, {"id": "s33", "lv": 3, "t": "第 65 条"}, {"id": "s34", "lv": 2, "t": "二、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（二）》法释〔2013〕14 号"}, {"id": "s35", "lv": 2, "t": "三、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（三）》法释〔2015〕21 号"}, {"id": "s36", "lv": 2, "t": "四、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（四）》法释〔2018〕13 号"}, {"id": "s37", "lv": 2, "t": "五、来源清单"}, {"id": "s38", "lv": 2, "t": "六、已知缺口"}], "text": "保险法 · 法条与司法解释原文留档 抓取日期：2026 09 16 ｜ 生成脚本： work/gen laws.py 使用规则 ：本文件为原文留档。任何条文对外引用前，须与国家法律法规数据库最新版本核对一次。 标注说明： 【原文未获取，待补】 = 本次未抓到，禁止用记忆填充。 一、《中华人民共和国保险法》（2009 年修订 / 2015 年修正） 来源：郑州航空港经济综合实验区管委会转载全文（2020 09 24） <https://www.zzhkgq.gov.cn/2020/09 24/3379060.html 第 10 条 【原文未获取，待补】 第 11 条 订立保险合同，应当协商一致，遵循公平原则确定各方的权利和义务。 除法律、行政法规规定必须保险的外，保险合同自愿订立。 第 12 条 人身保险的投保人在保险合同订立时，对被保险人应当具有保险利益。 财产保险的被保险人在保险事故发生时，对保险标的应当具有保险利益。 人身保险是以人的寿命和身体为保险标的的保险。 财产保险是以财产及其有关利益为保险标的的保险。 被保险人是指其财产或者人身受保险合同保障，享有保险金请求权的人。投保人可以为被保险人。 保险利益是指投保人或者被保险人对保险标的具有的法律上承认的利益。 第 13 条 投保人提出保险要求，经保险人同意承保，保险合同成立。保险人应当及时向投保人签发保险单或者其他保险凭证。 保险单或者其他保险凭证应当载明当事人双方约定的合同内容。当事人也可以约定采用其他书面形式载明合同内容。 依法成立的保险合同，自成立时生效。投保人和保险人可以对合同的效力约定附条件或者附期限。 第 14 条 保险合同成立后，投保人按照约定交付保险费，保险人按照约定的时间开始承担保险责任。 第 15 条 除本法另有规定或者保险合同另有约定外，保险合同成立后，投保人可以解除合同，保险人不得解除合同。 第 16 条【如实告知义务 · 两年不可抗辩 —— 保险纠纷第一战场】 订立保险合同，保险人就保险标的或者被保险人的有关情况提出询问的，投保人应当如实告知。 投保人故意或者因重大过失未履行前款规定的如实告知义务，足以影响保险人决定是否同意承保或者提高保险费率的，保险人有权解除合同。 前款规定的合同解除权，自保险人知道有解除事由之日起，超过三十日不行使而消灭。自合同成立之日起超过两年的，保险人不得解除合同；发生保险事故的，保险人应当承担赔偿或者给付保险金的责任。 投保人故意不履行如实告知义务的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，并不退还保险费。 投保人因重大过失未履行如实告知义务，对保险事故的发生有严重影响的，保险人对于合同解除前发生的保险事故，不承担赔偿或者给付保险金的责任，但应当退还保险费。 保险人在合同订立时已经知道投保人未如实告知的情况的，保险人不得解除合同；发生保险事故的，保险人应当承担赔偿或者给付保险金的责任。 保险事故是指保险合同约定的保险责任范围内的事故。 第 17 条【格式条款说明义务 · 免责条款提示与明确说明 —— 保险纠纷第二战场】 订立保险合同，采用保险人提供的格式条款的，保险人向投保人提供的投保单应当附格式条款，保险人应当向投保人说明合同的内容。 对保险合同中免除保险人责任的条款，保险人在订立合同时应当在投保单、保险单或者其他保险凭证上作出足以引起投保人注意的提示，并对该条款的内容以书面或者口头形式向投保人作出明确说明；未作提示或者明确说明的，该条款不产生效力。 第 18 条 保险合同应当包括下列事项： （一）保险人的名称和住所； （二）投保人、被保险人的姓名或者名称、住所，以及人身保险的受益人的姓名或者名称、住所； （三）保险标的； （四）保险责任和责任免除； （五）保险期间和保险责任开始时间； （六）保险金额； （七）保险费以及支付办法； （八）保险金赔偿或者给付办法； （九）违约责任和争议处理； （十）订立合同的年、月、日。 投保人和保险人可以约定与保险有关的其他事项。 受益人是指人身保险合同中由被保险人或者投保人指定的享有保险金请求权的人。投保人、被保险人可以为受益人。 保险金额是指保险人承担赔偿或者给付保险金责任的最高限额。 第 19 条【格式条款无效】 采用保险人提供的格式条款订立的保险合同中的下列条款无效： （一）免除保险人依法应承担的义务或者加重投保人、被保险人责任的； （二）排除投保人、被保险人或者受益人依法享有的权利的。 第 21 条 投保人、被保险人或者受益人知道保险事故发生后，应当及时通知保险人。故意或者因重大过失未及时通知，致使保险事故的性质、原因、 损失程度等难以确定的，保险人对无法确定的部分，不承担赔偿或者给付保险金的责任，但保险人通过其他途径已经及时知道或者应当及时知道保险事故发生的除 外。 第 22 条 保险事故发生后，按照保险合同请求保险人赔偿或者给付保险金时，投保人、被保险人或者受益人应当向保险人提供其所能提供的与确认保险事故的性质、原因、损失程度等有关的证明和资料。 保险人按照合同的约定，认为有关的证明和资料不完整的，应当及时一次性通知投保人、被保险人或者受益人补充提供。 第 23 条【核定与赔付期限（三十日）】 保险人收到被保险人或者受益人的赔偿或者给付保险金的请求后，应当及时作出核定；情形复杂的，应当在三十日内作出核定，但合同另有 约定的除外。保险人应当将核定结果通知被保险人或者受益人；对属于保险责任的，在与被保险人或者受益人达成赔偿或者给付保险金的协议后十日内，履行赔偿或 者给付保险金义务。保险合同对赔偿或者给付保险金的期限有约定的，保险人应当按照约定履行赔偿或者给付保险金义务。 保险人未及时履行前款规定义务的，除支付保险金外，应当赔偿被保险人或者受益人因此受到的损失。 任何单位和个人不得非法干预保险人履行赔偿或者给付保险金的义务，也不得限制被保险人或者受益人取得保险金的权利。 第 24 条 保险人依照本法 第 25 条 保险人自收到赔偿或者给付保险金的请求和有关证明、资料之日起六十日内，对其赔偿或者给付保险金的数额不能确定的，应当根据已有证明和资料可以确定的数额先予支付；保险人最终确定赔偿或者给付保险金的数额后，应当支付相应的差额。 第 26 条 人寿保险以外的其他保险的被保险人或者受益人，向保险人请求赔偿或者给付保险金的诉讼时效期间为二年，自其知道或者应当知道保险事故发生之日起计算。 人寿保险的被保险人或者受益人向保险人请求给付保险金的诉讼时效期间为五年，自其知道或者应当知道保险事故发生之日起计算。 第 30 条【不利解释规则（疑义利益解释）】 采用保险人提供的格式条款订立的保险合同，保险人与投保人、被保险人或者受益人对合同条款有争议的，应当按照通常理解予以解释。对合同条款有两种以上解释的，人民法院或者仲裁机构应当作出有利于被保险人和受益人的解释。 第 31 条 投保人对下列人员具有保险利益： （一）本人； （二）配偶、子女、父母； （三）前项以外与投保人有抚养、赡养或者扶养关系的家庭其他成员、近亲属； （四）与投保人有劳动关系的劳动者。 除前款规定外，被保险人同意投保人为其订立合同的，视为投保人对被保险人具有保险利益。 订立合同时，投保人对被保险人不具有保险利益的，合同无效。 第 34 条 以死亡为给付保险金条件的合同，未经被保险人同意并认可保险金额的，合同无效。 按照以死亡为给付保险金条件的合同所签发的保险单，未经被保险人书面同意，不得转让或者质押。 父母为其未成年子女投保的人身保险，不受本条第一款规定限制。 第 36 条 合同约定分期支付保险费，投保人支付首期保险费后，除合同另有约定外，投保人自保险人催告之日起超过三十日未支付当期保险费，或者超过约定的期限六十日未支付当期保险费的，合同效力中止，或者由保险人按照合同约定的条件减少保险金额。 被保险人在前款规定期限内发生保险事故的，保险人应当按照合同约定给付保险金，但可以扣减欠交的保险费。 第 37 条 合同效力依照本法 第 43 条 规定外，不退还保险费。 保险事故发生后，投保人、被保险人或者受益人以伪造、变造的有关证明、资料或者其他证据，编造虚假的事故原因或者夸大损失程度的，保险人对其虚报的部分不承担赔偿或者给付保险金的责任。 投保人、被保险人或者受益人有前三款规定行为之一，致使保险人支付保险金或者支出费用的，应当退回或者赔偿。 第 44 条 以被保险人死亡为给付保险金条件的合同，自合同成立或者合同效力恢复之日起二年内，被保险人自杀的，保险人不承担给付保险金的责任，但被保险人自杀时为无民事行为能力人的除外。 保险人依照前款规定不承担给付保险金责任的，应当按照合同约定退还保险单的现金价值。 第 45 条 因被保险人故意犯罪或者抗拒依法采取的刑事强制措施导致其伤残或者死亡的，保险人不承担给付保险金的责任。投保人已交足二年以上保险费的，保险人应当按照合同约定退还保险单的现金价值。 第 47 条 投保人解除合同的，保险人应当自收到解除合同通知之日起三十日内，按照合同约定退还保险单的现金价值。 第 52 条【危险程度显著增加的通知义务（车险营运争议核心）】 在合同有效期内，保险标的的危险程度显著增加的，被保险人应当按照合同约定及时通知保险人，保险人可以按照合同约定增加保险费或者 解除合同。保险人解除合同的，应当将已收取的保险费，按照合同约定扣除自保险责任开始之日起至合同解除之日止应收的部分后，退还投保人。 被保险人未履行前款规定的通知义务的，因保险标的的危险程度显著增加而发生的保险事故，保险人不承担赔偿保险金的责任。 第 55 条 投保人和保险人约定保险标的的保险价值并在合同中载明的，保险标的发生损失时，以约定的保险价值为赔偿计算标准。 投保人和保险人未约定保险标的的保险价值的，保险标的发生损失时，以保险事故发生时保险标的的实际价值为赔偿计算标准。 保险金额不得超过保险价值。超过保险价值的，超过部分无效，保险人应当退还相应的保险费。 保险金额低于保险价值的，除合同另有约定外，保险人按照保险金额与保险价值的比例承担赔偿保险金的责任。 第 57 条 保险事故发生时，被保险人应当尽力采取必要的措施，防止或者减少损失。 保险事故发生后，被保险人为防止或者减少保险标的的损失所支付的必要的、合理的费用，由保险人承担；保险人所承担的费用数额在保险标的损失赔偿金额以外另行计算，最高不超过保险金额的数额。 第 60 条【代位求偿权】 因第三者对保险标的的损害而造成保险事故的，保险人自向被保险人赔偿保险金之日起，在赔偿金额范围内代位行使被保险人对第三者请求赔偿的权利。 前款规定的保险事故发生后，被保险人已经从第三者取得损害赔偿的，保险人赔偿保险金时，可以相应扣减被保险人从第三者已取得的赔偿金额。 保险人依照本条第一款规定行使代位请求赔偿的权利，不影响被保险人就未取得赔偿的部分向第三者请求赔偿的权利。 第 61 条 保险事故发生后，保险人未赔偿保险金之前，被保险人放弃对第三者请求赔偿的权利的，保险人不承担赔偿保险金的责任。 保险人向被保险人赔偿保险金后，被保险人未经保险人同意放弃对第三者请求赔偿的权利的，该行为无效。 被保险人故意或者因重大过失致使保险人不能行使代位请求赔偿的权利的，保险人可以扣减或者要求返还相应的保险金。 第 62 条 除被保险人的家庭成员或者其组成人员故意造成本法 第 65 条 保险人对责任保险的被保险人给第三者造成的损害，可以依照法律的规定或者合同的约定，直接向该第三者赔偿保险金。 责任保险的被保险人给第三者造成损害，被保险人对第三者应负的赔偿责任确定的，根据被保险人的请求，保险人应当直接向该第三者赔偿保险金。被保险人怠于请求的，第三者有权就其应获赔偿部分直接向保险人请求赔偿保险金。 责任保险的被保险人给第三者造成损害，被保险人未向该第三者赔偿的，保险人不得向被保险人赔偿保险金。 责任保险是指以被保险人对第三者依法应负的赔偿责任为保险标的的保险。 本次从全文中成功提取 31 / 32 条。 二、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（二）》法释〔2013〕14 号 施行：2013 06 08 施行（2020 年修正） ｜ 来源：<https://www.court.gov.cn/shenpan/xiangqing/5427.html 第 十 条 保险人将法律、行政法规中的禁止性规定情形作为保险合同免责条款的免责事由，保险人对该条款作出提示后，投保人、被保险人或者受益人以保险人未履行明确说明义务为由主张该条款不生效的，人民法院不予支持。 第 一 条 财产保险中，不同投保人就同一保险标的分别投保，保险事故发生后，被保险人在其保险利益范围内依据保险合同主张保险赔偿的，人民法院应予支持。 第 二 条 人身保险中，因投保人对被保险人不具有保险利益导致保险合同无效，投保人主张保险人退还扣减相应手续费后的保险费的，人民法院应予支持。 第 三 条 投保人或者投保人的代理人订立保险合同时没有亲自签字或者盖章，而由保险人或者保险人的代理人代为签字或者盖章的，对投保人不生效。但投保人已经交纳保险费的，视为其对代签字或者盖章行为的追认。 保险人或者保险人的代理人代为填写保险单证后经投保人签字或者盖章确认的，代为填写的内容视为投保人的真实意思表示。但有证据证明保险人或者保险人的代理人存在保险法第一百一十六条、第一百三十一条相关规定情形的除外。 第 四 条 保险人接受了投保人提交的投保单并收取了保险费, 尚未作出是否承保的意思表示，发生保险事故，被保险人或者受益人请求保险人按照保险合同承担赔偿或者给付保险金责任，符合承保条件的，人民法院应予支持；不符合承保条件的，保险人不承担保险责任，但应当退还已经收取的保险费。 保险人主张不符合承保条件的，应承担举证责任。 第 五 条 保险合同订立时，投保人明知的与保险标的或者被保险人有关的情况，属于保险法第十六条第一款规定的投保人“应当如实告知”的内容。 第 六 条 投保人的告知义务限于保险人询问的范围和内容。当事人对询问范围及内容有争议的，保险人负举证责任。 保险人以投保人违反了对投保单询问表中所列概括性条款的如实告知义务为由请求解除合同的，人民法院不予支持。但该概括性条款有具体内容的除外。 第 七 条 保险人在保险合同成立后知道或者应当知道投保人未履行如实告知义务，仍然收取保险费，又依照保险法第十六条第二款的规定主张解除合同的，人民法院不予支持。 第 八 条 保险人未行使合同解除权，直接以存在保险法第十六条第四款、第五款规定的情形为由拒绝赔偿的，人民法院不予支持。但当事人就拒绝赔偿事宜及保险合同存续另行达成一致的情况除外。 第 九 条 保险人提供的格式合同文本中的责任免除条款、免赔额、免赔率、比例赔付或者给付等免除或者减轻保险人责任的条款，可以认定为保险法第十七条第二款规定的“免除保险人责任的条款”。 保险人因投保人、被保险人违反法定或者约定义务，享有解除合同权利的条款，不属于保险法第十七条第二款规定的“免除保险人责任的条款”。 第 十一 条 保险合同订立时，保险人在投保单或者保险单等其他保险凭证上，对保险合同中免除保险人责任的条款，以足以引起投保人注意的文字、字体、符号或者其他明显标志作出提示的，人民法院应当认定其履行了保险法第十七条第二款规定的提示义务。 保险人对保险合同中有关免除保险人责任条款的概念、内容及其法律后果以书面或者口头形式向投保人作出常人能够理解的解释说明的，人民法院应当认定保险人履行了保险法第十七条第二款规定的明确说明义务。 第 十二 条 通过网络、电话等方式订立的保险合同，保险人以网页、音频、视频等形式对免除保险人责任条款予以提示和明确说明的，人民法院可以认定其履行了提示和明确说明义务。 第 十三 条 保险人对其履行了明确说明义务负举证责任。 投保人对保险人履行了符合本解释第十一条第二款要求的明确说明义务在相关文书上签字、盖章或者以其他形式予以确认的，应当认定保险人履行了该项义务。但另有证据证明保险人未履行明确说明义务的除外。 第 十四 条 保险合同中记载的内容不一致的，按照下列规则认定： （一）投保单与保险单或者其他保险凭证不一致的，以投保单为准。但不一致的情形系经保险人说明并经投保人同意的，以投保人签收的保险单或者其他保险凭证载明的内容为准； （二）非格式条款与格式条款不一致的，以非格式条款为准； （三）保险凭证记载的时间不同的，以形成时间在后的为准； （四）保险凭证存在手写和打印两种方式的，以双方签字、盖章的手写部分的内容为准。 第 十五 条 保险法第二十三条规定的三十日核定期间，应自保险人初次收到索赔请求及投保人、被保险人或者受益人提供的有关证明和资料之日起算。 保险人主张扣除投保人、被保险人或者受益人补充提供有关证明和资料期间的，人民法院应予支持。扣除期间自保险人根据保险法第二十二条规定作出的通知到达投保人、被保险人或者受益人之日起，至投保人、被保险人或者受益人按照通知要求补充提供的有关证明和资料到达保险人之日止。 第 十六 条 保险人应以自己的名义行使保险代位求偿权。 根据保险法第六十条第一款的规定，保险人代位求偿权的诉讼时效期间应自其取得代位求偿权之日起算。 第 十七 条 保险人在其提供的保险合同格式条款中对非保术语所作的解释符合专业意义，或者虽不符合专业意义，但有利于投保人、被保险人或者受益人的，人民法院应予认可。 第 十八 条 行政管理部门依据法律规定制作的交通事故认定书、火灾事故认定书等，人民法院应当依法审查并确认其相应的证明力，但有相反证据能够推翻的除外。 第 十九 条 保险事故发生后，被保险人或者受益人起诉保险人，保险人以被保险人或者受益人未要求第三者承担责任为由抗辩不承担保险责任的，人民法院不予支持。 财产保险事故发生后，被保险人就其所受损失从第三者取得赔偿后的不足部分提起诉讼，请求保险人赔偿的，人民法院应予依法受理。 第 二十 条 保险公司依法设立并取得营业执照的分支机构属于《中华人民共和国民事诉讼法》第四十八条规定的其他组织，可以作为保险合同纠纷案件的当事人参加诉讼。 第 二十一 条 本解释施行后尚未终审的保险合同纠纷案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。 相关报道 中国共产党新闻网 中国政府网 中国人大网 中国政协网 中国法院网 最高人民检察院 全国人民法庭信息网 人民法院诉讼资产网 地址：北京市东城区东交民巷27号 邮编：100745 总机：67550114 举报电话：67556131 中华人民共和国最高人民法院 版权所有 京公网安备 11040102700145号 京ICP备05023036号 f11e35f5e90c74fe8757ccd4505a3e89 已提取 21 条。 三、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（三）》法释〔2015〕21 号 施行：2015 12 01 施行 ｜ 来源：<https://sxszzy.shanxify.gov.cn/article/detail/2015/12/id/1760086.shtml（朔州中院转载最高法发布稿） 第 十 条 投保人或者被保险人变更受益人，当事人主张变更行为自变更意思表示发出时生效的，人民法院应予支持。 投保人或者被保险人变更受益人未通知保险人，保险人主张变更对其不发生效力的，人民法院应予支持。 投保人变更受益人未经被保险人同意，人民法院应认定变更行为无效。 第 一 条 当事人订立以死亡为给付保险金条件的合同，根据保险法第三十四条的规定，&ldquo;被保险人同意并认可保险金额&rdquo;可以采取书面形式、口头形式或者其他形式；可以在合同订立时作出，也可以在合同订立后追认。 有下列情形之一的，应认定为被保险人同意投保人为其订立保险合同并认可保险金额： （一）被保险人明知他人代其签名同意而未表示异议的； （二）被保险人同意投保人指定的受益人的； （三）有证据足以认定被保险人同意投保人为其投保的其他情形。 第 二 条 被保险人以书面形式通知保险人和投保人撤销其依据保险法第三十四条第一款规定所作出的同意意思表示的，可认定为保险合同解除。 第 三 条 人民法院审理人身保险合同纠纷案件时，应主动审查投保人订立保险合同时是否具有保险利益，以及以死亡为给付保险金条件的合同是否经过被保险人同意并认可保险金额。 第 四 条 保险合同订立后，因投保人丧失对被保险人的保险利益，当事人主张保险合同无效的，人民法院不予支持。 第 五 条 保险人在合同订立时指定医疗机构对被保险人体检，当事人主张投保人如实告知义务免除的，人民法院不予支持。 保险人知道被保险人的体检结果，仍以投保人未就相关情况履行如实告知义务为由要求解除合同的，人民法院不予支持。 第 六 条 未成年人父母之外的其他履行监护职责的人为未成年人订立以死亡为给付保险金条件的合同，当事人主张参照保险法第三十三条第二款、第三十四条第三款的规定认定该合同有效的，人民法院不予支持，但经未成年人父母同意的除外。 第 七 条 当事人以被保险人、受益人或者他人已经代为支付保险费为由，主张投保人对应的交费义务已经履行的，人民法院应予支持。 第 八 条 保险合同效力依照保险法第三十六条规定中止，投保人提出恢复效力申请并同意补交保险费的，除被保险人的危险程度在中止期间显著增加外，保险人拒绝恢复效力的，人民法院不予支持。 保险人在收到恢复效力申请后，三十日内未明确拒绝的，应认定为同意恢复效力。 保险合同自投保人补交保险费之日恢复效力。保险人要求投保人补交相应利息的，人民法院应予支持。 第 九 条 投保人指定受益人未经被保险人同意的，人民法院应认定指定行为无效。 当事人对保险合同约定的受益人存在争议，除投保人、被保险人在保险合同之外另有约定外，按以下情形分别处理： （一）受益人约定为&ldquo;法定&rdquo;或者&ldquo;法定继承人&rdquo;的，以继承法规定的法定继承人为受益人； （二）受益人仅约定为身份关系的，投保人与被保险人为同一主体时，根据保险事故发生时与被保险人的身份关系确定受益人；投保人与被保险人为不同主体时，根据保险合同成立时与被保险人的身份关系确定受益人； （三）约定的受益人包括姓名和身份关系，保险事故发生时身份关系发生变化的，认定为未指定受益人。 第 十一 条 投保人或者被保险人在保险事故发生后变更受益人，变更后的受益人请求保险人给付保险金的，人民法院不予支持。 第 十二 条 投保人或者被保险人指定数人为受益人，部分受益人在保险事故发生前死亡、放弃受益权或者依法丧失受益权的，该受益人应得的受益份额按照保险合同的约定处理；保险合同没有约定或者约定不明的，该受益人应得的受益份额按照以下情形分别处理： （一）未约定受益顺序及受益份额的，由其他受益人平均享有； （二）未约定受益顺序但约定受益份额的,由其他受益人按照相应比例享有； （三）约定受益顺序但未约定受益份额的，由同顺序的其他受益人平均享有；同一顺序没有其他受益人的，由后一顺序的受益人平均享有； （四）约定受益顺序及受益份额的，由同顺序的其他受益人按照相应比例享有；同一顺序没有其他受益人的，由后一顺序的受益人按照相应比例享有。 第 十三 条 保险事故发生后，受益人将与本次保险事故相对应的全部或者部分保险金请求权转让给第三人 ，当事人主张该转让行为有效的，人民法院应予支持，但根据合同性质、当事人约定或者法律规定不得转让的除外。 第 十四 条 保险金根据保险法第四十二条规定作为被保险人遗产，被保险人的继承人要求保险人给付保险金，保险人以其已向持有保险单的被保险人的其他继承人给付保险金为由抗辩的，人民法院应予支持。 第 十五 条 受益人与被保险人存在继承关系，在同一事件中死亡且不能确定死亡先后顺序的，人民法院应依据保险法第四十二条第二款推定受益人死亡在先，并按照保险法及本解释的相关规定确定保险金归属。 第 十六 条 人身保险合同解除时，投保人与被保险人、受益人为不同主体，被保险人或者受益人要求退还保险单的现金价值的，人民法院不予支持，但保险合同另有约定的除外。 投保人故意造成被保险人死亡、伤残或者疾病，保险人依照保险法第四十三条规定退还保险单的现金价值的，其他权利人按照被保险人、被保险人的继承人的顺序确定。 第 十七 条 投保人解除保险合同，当事人以其解除合同未经被保险人或者受益人同意为由主张解除行为无效的，人民法院不予支持，但被保险人或者受益人已向投保人支付相当于保险单现金价值的款项并通知保险人的除外。 第 十八 条 保险人给付费用补偿型的医疗费用保险金时，主张扣减被保险人从公费医疗或者社会医疗保险取得的赔偿金额的，应当证明该保险产品在厘定医疗费用保险费率时已经将公费医疗或者社会医疗保险部分相应扣除，并按照扣减后的标准收取保险费。 第 十九 条 保险合同约定按照基本医疗保险的标准核定医疗费用，保险人以被保险人的医疗支出超出基本医疗保险范围为由拒绝给付保险金的，人民法院不予支持；保险人有证据证明被保险人支出的费用超过基本医疗保险同类医疗费用标准，要求对超出部分拒绝给付保险金的，人民法院应予支持。 第 二十 条 保险人以被保险人未在保险合同约定的医疗服务机构接受治疗为由拒绝给付保险金的，人民法院应予支持，但被保险人因情况紧急必须立即就医的除外。 第 二十一 条 保险人以被保险人自杀为由拒绝承担给付保险金责任的，由保险人承担举证责任。 受益人或者被保险人的继承人以被保险人自杀时无民事行为能力为由抗辩的，由其承担举证责任。 第 二十二 条 保险法第四十五条规定的&ldquo;被保险人故意犯罪&rdquo;的认定，应当以刑事侦查机关、检察机关和审判机关的生效法律文书或者其他结论性意见为依据。 第 二十三 条 保险人主张根据保险法第四十五条的规定不承担给付保险金责任的，应当证明被保险人的死亡、伤残结果与其实施的故意犯罪或者抗拒依法采取的刑事强制措施的行为之间存在因果关系。 被保险人在羁押、服刑期间因意外或者疾病造成伤残或者死亡，保险人主张根据保险法第四十五条的规定不承担给付保险金责任的，人民法院不予支持。 第 二十四 条 投保人为被保险人订立以死亡为给付保险金条件的人身保险合同，被保险人被宣告死亡后，当事人要求保险人按照保险合同约定给付保险金的，人民法院应予支持。 被保险人被宣告死亡之日在保险责任期间之外，但有证据证明下落不明之日在保险责任期间之内，当事人要求保险人按照保险合同约定给付保险金的，人民法院应予支持。 第 二十五 条 被保险人的损失系由承保事故或者非承保事故、免责事由造成难以确定，当事人请求保险人给付保险金的，人民法院可以按照相应比例予以支持。 第 二十六 条 本解释施行后尚未终审的保险合同纠纷案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。 来源：中国法院网 责任编辑：中院研究室 您是第位访客 \" 网站地图 采稿邮箱 山西省朔州市中级人民法院版权所有，未经协议授权禁止下载使用或建立镜像 中国法院网负责网站设计制作 网络安全和技术维护 Copyright © 2025 by www.chinacourt.cn All Rights Reserved. 浏 览 本 网 站 推 荐 您 使 用 IE 8 以 上 浏 览 器 已提取 26 条。 四、《最高人民法院关于适用〈中华人民共和国保险法〉若干问题的解释（四）》法释〔2018〕13 号 施行：2018 09 01 施行 ｜ 来源：<http://gongbao.court.gov.cn/Details/442f0649e12a198e6f9701a9830f7a.html 第 十 条 因第三者对保险标的的损害而造成保险事故，保险人获得代位请求赔偿的权利的情况未通知第三者或者通知到达第三者前,第三者在被保险人已经从保险人处获赔的范围内又向被保险人作出赔偿，保险人主张代位行使被保险人对第三者请求赔偿的权利的，人民法院不予支持。保险人就相应保险金主张被保险人返还的，人民法院应予支持。 保险人获得代位请求赔偿的权利的情况已经通知到第三者，第三者又向被保险人作出赔偿，保险人主张代位行使请求赔偿的权利，第三者以其已经向被保险人赔偿为由抗辩的，人民法院不予支持。 第 一 条 保险标的已交付受让人，但尚未依法办理所有权变更登记，承担保险标的毁损灭失风险的受让人，依照保险法第四十八条、第四十九条的规定主张行使被保险人权利的，人民法院应予支持。 第 二 条 保险人已向投保人履行了保险法规定的提示和明确说明义务，保险标的受让人以保险标的转让后保险人未向其提示或者明确说明为由，主张免除保险人责任的条款不生效的，人民法院不予支持。 第 三 条 被保险人死亡，继承保险标的的当事人主张承继被保险人的权利和义务的，人民法院应予支持。 第 四 条 人民法院认定保险标的是否构成保险法第四十九条、第五十二条规定的“危险程度显著增加”时，应当综合考虑以下因素： （一） 保险标的用途的改变； （二） 保险标的使用范围的改变； （三） 保险标的所处环境的变化； （四） 保险标的因改装等原因引起的变化； （五） 保险标的使用人或者管理人的改变； （六） 危险程度增加持续的时间; （七） 其他可能导致危险程度显著增加的因素。 保险标的危险程度虽然增加，但增加的危险属于保险合同订立时保险人预见或者应当预见的保险合同承保范围的，不构成危险程度显著增加。 第 五 条 被保险人、受让人依法及时向保险人发出保险标的转让通知后,保险人作出答复前，发生保险事故，被保险人或者受让人主张保险人按照保险合同承担赔偿保险金的责任的，人民法院应予支持。 第 六 条 保险事故发生后，被保险人依照保险法第五十七条的规定，请求保险人承担为防止或者减少保险标的的损失所支付的必要、合理费用,保险人以被保险人采取的措施未产生实际效果为由抗辩的,人民法院不予支持。 第 七 条 保险人依照保险法第六十条的规定,主张代位行使被保险人因第三者侵权或者违约等享有的请求赔偿的权利的，人民法院应予支持。 第 八 条 投保人和被保险人为不同主体，因投保人对保险标的的损害而造成保险事故，保险人依法主张代位行使被保险人对投保人请求赔偿的权利的，人民法院应予支持，但法律另有规定或者保险合同另有约定的除外。 第 九 条 在保险人以第三者为被告提起的代位求偿权之诉中，第三者以被保险人在保险合同订立前已放弃对其请求赔偿的权利为由进行抗辩，人民法院认定上述放弃行为合法有效，保险人就相应部分主张行使代位求偿权的，人民法院不予支持。 保险合同订立时，保险人就是否存在上述放弃情形提出询问，投保人未如实告知，导致保险人不能代位行使请求赔偿的权利，保险人请求返还相应保险金的，人民法院应予支持，但保险人知道或者应当知道上述情形仍同意承保的除外。 第 十一 条 被保险人因故意或者重大过失未履行保险法第六十三条规定的义务，致使保险人未能行使或者未能全部行使代位请求赔偿的权利，保险人主张在其损失范围内扣减或者返还相应保险金的，人民法院应予支持。 第 十二 条 保险人以造成保险事故的第三者为被告提起代位求偿权之诉的，以被保险人与第三者之间的法律关系确定管辖法院。 第 十三 条 保险人提起代位求偿权之诉时，被保险人已经向第三者提起诉讼的，人民法院可以依法合并审理。 保险人行使代位求偿权时，被保险人已经向第三者提起诉讼，保险人向受理该案的人民法院申请变更当事人，代位行使被保险人对第三者请求赔偿的权利，被保险人同意的,人民法院应予准许;被保险人不同意的，保险人可以作为共同原告参加诉讼。 第 十四 条 具有下列情形之一的，被保险人可以依照保险法第六十五条第二款的规定请求保险人直接向第三者赔偿保险金： （一）被保险人对第三者所负的赔偿责任经人民法院生效裁判、仲裁裁决确认； （二）被保险人对第三者所负的赔偿责任经被保险人与第三者协商一致； （三）被保险人对第三者应负的赔偿责任能够确定的其他情形。 前款规定的情形下,保险人主张按照保险合同确定保险赔偿责任的，人民法院应予支持。 第 十五 条 被保险人对第三者应负的赔偿责任确定后，被保险人不履行赔偿责任，且第三者以保险人为被告或者以保险人与被保险人为共同 被告提起诉讼时，被保险人尚未向保险人提出直接向第三者赔偿保险金的请求的，可以认定为属于保险法第六十五条第二款规定的“被保险人怠于请求”的情形。 第 十六 条 责任保险的被保险人因共同侵权依法承担连带责任，保险人以该连带责任超出被保险人应承担的责任份额为由，拒绝赔付保险金的，人民法院不予支持。保险人承担保险责任后,主张就超出被保险人责任份额的部分向其他连带责任人追偿的，人民法院应予支持。 第 十七 条 责任保险的被保险人对第三者所负的赔偿责任已经生效判决确认并已进入执行程序，但未获得清偿或者未获得全部清偿，第三者依法请求保险人赔偿保险金，保险人以前述生效判决已进入执行程序为由抗辩的，人民法院不予支持。 第 十八 条 商业责任险的被保险人向保险人请求赔偿保险金的诉讼时效期间，自被保险人对第三者应负的赔偿责任确定之日起计算。 第 十九 条 责任保险的被保险人与第三者就被保险人的赔偿责任达成和解协议且经保险人认可，被保险人主张保险人在保险合同范围内依据和解协议承担保险责任的，人民法院应予支持。 被保险人与第三者就被保险人的责任达成和解协议，未经保险人认可，保险人主张对保险责任范围以及赔偿数额重新予以核定的，人民法院应予支持。 第 二十 条 责任保险的保险人在被保险人向第三者赔偿之前向被保险人赔偿保险金，第三者依照保险法第六十五条第二款的规定行使保险金请求权时，保险人以其已向被保险人赔偿为由拒绝赔偿保险金的，人民法院不予支持。保险人向第三者赔偿后，请求被保险人返还相应保险金的，人民法院应予支持。 第 二十一 条 本解释自2018年9月1日起施行。 本解释施行后人民法院正在审理的一审、二审案件，适用本解释；本解释施行前已经终审，当事人申请再审或者按照审判监督程序决定再审的案件，不适用本解释。 法律声明 联系我们 使用帮助 中华人民共和国最高人民法院 版权所有 已提取 21 条。 五、来源清单 文件 来源 URL 状态 保险法全文 https://www.zzhkgq.gov.cn/2020/09 24/3379060.html 成功（51886 字符） 司法解释（二） https://www.court.gov.cn/shenpan/xiangqing/5427.html 成功 司法解释（三） https://sxszzy.shanxify.gov.cn/article/detail/2015/12/id/1760086.shtml 成功 司法解释（四） 最高人民法院公报 gongbao.court.gov.cn 成功 司法解释（三）原始 最高人民法院公报 gongbao.court.gov.cn 抓取失败（502），改用山西朔州中院转载最高法发布稿 六、已知缺口 《全国法院民商事审判工作会议纪要》（九民纪要）涉保险部分：未抓取，待补 《重大疾病保险的疾病定义使用规范（2020 年修订版）》官方原文：未抓取，待补 民法典第 496 498 条（格式条款）原文：未抓取，待补"}, {"id": "L4-法条库/01-重疾定义使用规范2020", "group": "5 · 法条原文", "groupKey": "L4-法条库", "title": "重大疾病保险的疾病定义使用规范（2020 年修订版）· 原文", "order": 5, "file": "01-重疾定义使用规范2020.md", "html": "<h1 id=\"s0\">重大疾病保险的疾病定义使用规范（2020 年修订版）· 原文</h1>\n<blockquote><strong>来源</strong>：中国保险行业协会官网发布的规范 PDF（<strong>A 级 · 官方原文</strong>）<br>https://www.iachina.cn/module/download/downfile.jsp?filename=dfbe46c8f7aa414694e7043603c6fb0b.pdf<br><br><strong>发布主体</strong>：中国保险行业协会 + 中国医师协会，2020 年 11 月 5 日发布。<br><strong>过渡期</strong>：发文之日起至 <strong>2021 年 1 月 31 日</strong>。过渡期结束后，各公司不得继续销售基于旧规范（2007 版）开发的重大疾病保险产品。<br><strong>适用范围</strong>：保险期间主要为成年人（十八周岁及以上）阶段的重大疾病保险。<br><br><span class=\"warn\">!</span> 本文件为 PDF 文本提取后按版面还原的版本，<strong>条文字句以官方 PDF 为准</strong>。</blockquote>\n<hr>\n<p>重大疾病保险的疾病定义使用规范（2020 年修订版）前 言为进一步保护消费者合法权益，提升重大疾病保险产品供给质量，更好地发挥对社会保障体系的重要补充作用，结合我国重大疾病保险发展及现代医学最新进展情况，并广泛研究参考国际经验，中国保险行业协会与中国医师协会共同对2007年制定的重大疾病保险的疾病定义（以下简称疾病定义）进行了修订。</p>\n<p>为更好地指导保险公司使用疾病定义，中国保险行业协会特制定《重大疾病保险的疾病定义使用规范（2020年修订版）》（以下简称规范）。</p>\n<p>本规范中所称“疾病”是指重大疾病保险合同约定的疾病、疾病状态或手术。</p>\n<h2 id=\"s1\">1</h2>\n<p>适用范围本规范中的疾病定义主要在参考国内外成年人重大疾病保险发展状况并结合现代医学最新进展情况的基础上制定，因此，本规范适用于保险期间主要为成年人（十八周岁及以上）阶段的重大疾病保险。</p>\n<h2 id=\"s2\">2</h2>\n<p>使用原则</p>\n<h3 id=\"s3\">2.1</h3>\n<p>保险公司将产品定名为重大疾病保险，且保险期间主要为成年人（十八周岁及以上）阶段的，该产品保障的疾病范围应当包括本规范内的恶性肿瘤——重度、较重急性心肌梗死、严重脑中风后遗症、重大器官移植术或造血干细胞移植术、冠状动脉搭桥术（或称冠状动脉旁路移植术）、严重慢性肾衰竭；如果该产品还保障了保险金额低于上述六种重度疾病的其他疾病，则还应当包括本规范内的恶性肿瘤——轻度、较轻急性心肌梗死、轻度脑中风后遗症。除前述疾病外，对于本规范疾病范围以内的其他疾病，保险公司可以选择使用；同时，上述疾病均应当使用本规范的疾病名称和疾病定义。</p>\n<h3 id=\"s4\">2.2</h3>\n<p>保险公司设计重大疾病保险产品时，所包含的本规范中的每种轻度疾病累计保险金额分别不应高于所包含的本规范中的相应重度疾病累计保险金额的 30%；如有多次赔付责任的，轻度疾病的单次保险金额还应不高于同一赔付次序的相应重度疾病单次保险金额的 30%，无相同赔付次序的，以最近的赔付次序为参照。</p>\n<h3 id=\"s5\">2.3</h3>\n<p>根据市场需求和经验数据，各保险公司可以在其重大疾病保险产品中增加本规范疾病范围以外的其他疾病，并合理制定相关定义。</p>\n<h3 id=\"s6\">2.4</h3>\n<p>重大疾病保险条款和配套宣传材料中，本规范规定的疾病应当按照本规范 3.1 所列顺序排列（对于分组列示疾病的，本规范规定的疾病可以按照疾病分组顺序排列），并置于各保险公司自行增加的疾病之前；同时，应当对二者予以区别说明。</p>\n<h3 id=\"s7\">2.5</h3>\n<p>保险公司设定重大疾病保险除外责任时，对于被保险人发生的疾病、达到的疾病状态或进行的手术，保险公司不承担保险责任的情形不能超出本规范 3.2 规定的范围。</p>\n<h2 id=\"s8\">3</h2>\n<p>重大疾病保险条款的相关规定重大疾病保险条款中的疾病名称、疾病定义、除外责任和术语释义应当符合本规范的具体规定。</p>\n<h3 id=\"s9\">3.1</h3>\n<p>重大疾病保险的疾病名称及疾病定义被保险人发生符合以下疾病定义所述条件的疾病，应当由专科医生明确诊断。</p>\n<p>以下疾病名称仅供理解使用，具体保障范围以每项疾病具体定义为准。</p>\n<h4 id=\"s10\">3.1.1 重度疾病</h4>\n<h5 id=\"s11\">3.1.1.1 恶性肿瘤——重度</h5>\n<p>指恶性细胞不受控制的进行性增长和扩散，浸润和破坏周围正常组织，可以经血管、淋巴管和体腔扩散转移到身体其他部位，病灶经组织病理学检查（涵盖骨髓病理学检查）结果明确诊断，临床诊断属于世界卫生组织（WHO，World Health Organization）《疾病和有关健康问题的国际统计分类》第十次修订版（ICD-10）的恶性肿瘤类别及《国际疾病分类肿瘤学专辑》第三版（ICD-O-3）的肿瘤形态学编码属于 3、6、9（恶性肿瘤）范畴的疾病。</p>\n<p>下列疾病不属于“恶性肿瘤——重度”，不在保障范围内：</p>\n<ul>\n<li>（1）ICD-O-3 肿瘤形态学编码属于 0（良性肿瘤）、1（动态未定性肿瘤）、2（原位癌和非侵袭性癌）范畴的疾病，如：</li>\n</ul>\n<p>- a.原位癌，癌前病变，非浸润性癌，非侵袭性癌，肿瘤细胞未侵犯基底层，上皮内瘤变，细胞不典型性增生等；</p>\n<p>- b.交界性肿瘤，交界恶性肿瘤，肿瘤低度恶性潜能，潜在低度恶性肿瘤等；</p>\n<ul>\n<li>（2）TNM 分期为Ⅰ期或更轻分期的甲状腺癌；</li>\n</ul>\n<ul>\n<li>（3）TNM 分期为 T1N0M0 期或更轻分期的前列腺癌；</li>\n</ul>\n<ul>\n<li>（4）黑色素瘤以外的未发生淋巴结和远处转移的皮肤恶性肿瘤；</li>\n</ul>\n<ul>\n<li>（5）相当于 Binet 分期方案 A 期程度的慢性淋巴细胞白血病；</li>\n</ul>\n<ul>\n<li>（6）相当于 Ann Arbor 分期方案Ⅰ期程度的何杰金氏病；</li>\n</ul>\n<ul>\n<li>（7）未发生淋巴结和远处转移且 WHO 分级为 G1 级别（核分裂像&lt;10/50 HPF 和 ki-67≤2%）或更轻分级的神经内分泌肿瘤。</li>\n</ul>\n<h5 id=\"s12\">3.1.1.2 较重急性心肌梗死急性心肌梗死</h5>\n<p>指由于冠状动脉闭塞或梗阻引起部分心肌严重的持久性缺血造成急性心肌坏死。急性心肌梗死的诊断必须依据国际国内诊断标准，符合（1）检测到肌酸激酶同工酶（CK-MB）或肌钙蛋白（cTn）升高和/或降低的动态变化，至少一次达到或超过心肌梗死的临床诊断标准；（2）同时存在下列之一的证据，包括：缺血性胸痛症状、新发生的缺血性心电图改变、新生成的病理性 Q 波、影像学证据显示有新出现的心肌活性丧失或新出现局部室壁运动异常、冠脉造影证实存在冠状动脉血栓。</p>\n<p>较重急性心肌梗死指依照上述标准被明确诊断为急性心肌梗死，并且必须同时满足下列至少一项条件：</p>\n<ul>\n<li>（1）心肌损伤标志物肌钙蛋白（cTn）升高，至少一次检测结果达到该检验正常参考值上限的 15 倍（含）以上；</li>\n</ul>\n<ul>\n<li>（2）肌酸激酶同工酶（CK-MB）升高，至少一次检测结果达到该检验正常参考值上限的 2 倍（含）以上；</li>\n</ul>\n<ul>\n<li>（3）出现左心室收缩功能下降，在确诊 6 周以后，检测左室射血分数（LVEF）低于 50%（不含）；</li>\n</ul>\n<ul>\n<li>（4）影像学检查证实存在新发的乳头肌功能失调或断裂引起的中度（含）以上的二尖瓣反流；</li>\n</ul>\n<ul>\n<li>（5）影像学检查证实存在新出现的室壁瘤；</li>\n</ul>\n<ul>\n<li>（6）出现室性心动过速、心室颤动或心源性休克。其他非冠状动脉阻塞性疾病所引起的肌钙蛋白（cTn）升高不在保障范围内。</li>\n</ul>\n<h5 id=\"s13\">3.1.1.3 严重脑中风后遗症</h5>\n<p>指因脑血管的突发病变引起脑血管出血、栓塞或梗塞，须由头颅断层扫描（CT）、核磁共振检查（MRI）等影像学检查证实，并导致神经系统永久性的功能障碍。神经系统永久性的功能障碍，指疾病确诊 180 天后，仍遗留下列至少一种障碍：</p>\n<ul>\n<li>（1）一肢（含）以上肢体肌力 2 级（含）以下；</li>\n</ul>\n<ul>\n<li>（2）语言能力完全丧失，或严重咀嚼吞咽功能障碍；</li>\n</ul>\n<ul>\n<li>（3）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。</li>\n</ul>\n<h5 id=\"s14\">3.1.1.4 重大器官移植术或造血干细胞移植术重大器官移植术，</h5>\n<p>指因相应器官功能衰竭，已经实施了肾脏、肝脏、心脏、肺脏或小肠的异体移植手术。</p>\n<p>造血干细胞移植术，指因造血功能损害或造血系统恶性肿瘤，已经实施了造血干细胞（包括骨髓造血干细胞、外周血造血干细胞和脐血造血干细胞）的移植手术。</p>\n<h5 id=\"s15\">3.1.1.5 冠状动脉搭桥术（或称冠状动脉旁路移植术）</h5>\n<p>指为治疗严重的冠心病，已经实施了切开心包进行的冠状动脉血管旁路移植的手术。</p>\n<p>所有未切开心包的冠状动脉介入治疗不在保障范围内。</p>\n<h5 id=\"s16\">3.1.1.6 严重慢性肾衰竭</h5>\n<p>指双肾功能慢性不可逆性衰竭，依据肾脏病预后质量倡议（K/DOQI）制定的指南，分期达到慢性肾脏病 5 期，且经诊断后已经进行了至少 90 天的规律性透析治疗。规律性透析是指每周进行血液透析或每天进行腹膜透析。</p>\n<h5 id=\"s17\">3.1.1.7 多个肢体缺失</h5>\n<p>指因疾病或意外伤害导致两个或两个以上肢体自腕关节或踝关节近端（靠近躯干端）以上完全性断离。</p>\n<h5 id=\"s18\">3.1.1.8 急性重症肝炎或亚急性重症肝炎</h5>\n<p>指因肝炎病毒感染引起肝脏组织弥漫性坏死，导致急性肝功能衰竭，且经血清学或病毒学检查证实，并须满足下列全部条件：</p>\n<ul>\n<li>（1）重度黄疸或黄疸迅速加重；</li>\n</ul>\n<ul>\n<li>（2）肝性脑病；</li>\n</ul>\n<ul>\n<li>（3）B 超或其他影像学检查显示肝脏体积急速萎缩；</li>\n</ul>\n<ul>\n<li>（4）肝功能指标进行性恶化。</li>\n</ul>\n<h5 id=\"s19\">3.1.1.9 严重非恶性颅内肿瘤</h5>\n<p>指起源于脑、脑神经、脑被膜的非恶性肿瘤，ICD-O-3 肿瘤形态学编码属于 0（良性肿瘤）、1（动态未定性肿瘤）范畴，并已经引起颅内压升高或神经系统功能损害，出现视乳头水肿或视觉受损、听觉受损、面部或肢体瘫痪、癫痫等，须由头颅断层扫描（CT）、核磁共振检查（MRI）或正电子发射断层扫描（PET）等影像学检查证实，且须满足下列至少一项条件：</p>\n<ul>\n<li>（1）已经实施了开颅进行的颅内肿瘤完全或部分切除手术；</li>\n</ul>\n<ul>\n<li>（2）已经实施了针对颅内肿瘤的放射治疗，如γ刀、质子重离子治疗等。</li>\n</ul>\n<p>下列疾病不在保障范围内：</p>\n<ul>\n<li>（1）脑垂体瘤；</li>\n</ul>\n<ul>\n<li>（2）脑囊肿；</li>\n</ul>\n<ul>\n<li>（3）颅内血管性疾病（如脑动脉瘤、脑动静脉畸形、海绵状血管瘤、毛细血管扩张症等）。</li>\n</ul>\n<h5 id=\"s20\">3.1.1.10 严重慢性肝衰竭</h5>\n<p>指因慢性肝脏疾病导致的肝衰竭，且须满足下列全部条件：</p>\n<ul>\n<li>（1）持续性黄疸；</li>\n</ul>\n<ul>\n<li>（2）腹水；</li>\n</ul>\n<ul>\n<li>（3）肝性脑病；</li>\n</ul>\n<ul>\n<li>（4）充血性脾肿大伴脾功能亢进或食管胃底静脉曲张。因酗酒或药物滥用导致的肝衰竭不在保障范围内。</li>\n</ul>\n<h5 id=\"s21\">3.1.1.11 严重脑炎后遗症或严重脑膜炎后遗症</h5>\n<p>指因患脑炎或脑膜炎导致的神经系统永久性的功能障碍。神经系统永久性的功能障碍，指经相关专科医生确诊疾病 180 天后，仍遗留下列至少一种障碍：</p>\n<ul>\n<li>（1）一肢（含）以上肢体肌力 2 级（含）以下；</li>\n</ul>\n<ul>\n<li>（2）语言能力完全丧失，或严重咀嚼吞咽功能障碍；</li>\n</ul>\n<ul>\n<li>（3）由具有评估资格的专科医生根据临床痴呆评定量表（CDR，Clinical Dementia Rating）评估结果为 3 分；</li>\n</ul>\n<ul>\n<li>（4）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。</li>\n</ul>\n<h5 id=\"s22\">3.1.1.12 深度昏迷</h5>\n<p>指因疾病或意外伤害导致意识丧失，对外界刺激和体内需求均无反应，昏迷程度按照格拉斯哥昏迷分级（GCS，Glasgow ComaScale）结果为 5 分或 5 分以下，且已经持续使用呼吸机及其他生命维持系统 96 小时以上。</p>\n<p>因酗酒或药物滥用导致的深度昏迷不在保障范围内。</p>\n<h5 id=\"s23\">3.1.1.13 双耳失聪</h5>\n<p>指因疾病或意外伤害导致双耳听力永久不可逆性丧失，在</p>\n<h2 id=\"s24\">500</h2>\n<p>赫兹、1000 赫兹和 2000 赫兹语音频率下，平均听阈大于等于 91 分贝，且经纯音听力测试、声导抗检测或听觉诱发电位检测等证实。</p>\n<p>注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在疾病定义中特别说明。</p>\n<h5 id=\"s25\">3.1.1.14 双目失明</h5>\n<p>指因疾病或意外伤害导致双眼视力永久不可逆性丧失，双眼中较好眼须满足下列至少一项条件：</p>\n<ul>\n<li>（1）眼球缺失或摘除；</li>\n</ul>\n<ul>\n<li>（2）矫正视力低于 0.02（采用国际标准视力表，如果使用其他视力表应进行换算）；</li>\n</ul>\n<ul>\n<li>（3）视野半径小于 5 度。注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在疾病定义中特别说明。</li>\n</ul>\n<h5 id=\"s26\">3.1.1.15 瘫痪</h5>\n<p>指因疾病或意外伤害导致两肢或两肢以上肢体随意运动功能永久完全丧失。肢体随意运动功能永久完全丧失，指疾病确诊</p>\n<h2 id=\"s27\">180</h2>\n<p>天后或意外伤害发生 180 天后，每肢三大关节中的两大关节仍然完全僵硬，或肢体肌力在 2 级（含）以下。</p>\n<h5 id=\"s28\">3.1.1.16 心脏瓣膜手术</h5>\n<p>指为治疗心脏瓣膜疾病，已经实施了切开心脏进行的心脏瓣膜置换或修复的手术。</p>\n<p>所有未切开心脏的心脏瓣膜介入手术不在保障范围内。</p>\n<h5 id=\"s29\">3.1.1.17 严重阿尔茨海默病</h5>\n<p>指因大脑进行性、不可逆性改变导致智能严重衰退或丧失，临床表现为严重的认知功能障碍、精神行为异常和社交能力减退等，其日常生活必须持续受到他人监护。须由头颅断层扫描（CT）、核磁共振检查（MRI）或正电子发射断层扫描（PET）等影像学检查证实，并经相关专科医生确诊，且须满足下列至少一项条件：</p>\n<ul>\n<li>（1）由具有评估资格的专科医生根据临床痴呆评定量表（CDR，Clinical Dementia Rating）评估结果为 3 分；</li>\n</ul>\n<ul>\n<li>（2）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。</li>\n</ul>\n<p>阿尔茨海默病之外的其他类型痴呆不在保障范围内。注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在疾病定义中特别说明。</p>\n<h5 id=\"s30\">3.1.1.18 严重脑损伤</h5>\n<p>指因头部遭受机械性外力，引起脑重要部位损伤，导致神经系统永久性的功能障碍。须由头颅断层扫描（CT）、核磁共振检查（MRI）或正电子发射断层扫描（PET）等影像学检查证实。神经系统永久性的功能障碍，指脑损伤 180 天后，仍遗留下列至少一种障碍：</p>\n<ul>\n<li>（1）一肢（含）以上肢体肌力 2 级（含）以下；</li>\n</ul>\n<ul>\n<li>（2）语言能力完全丧失，或严重咀嚼吞咽功能障碍；</li>\n</ul>\n<ul>\n<li>（3）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。</li>\n</ul>\n<h5 id=\"s31\">3.1.1.19 严重原发性帕金森病是一种中枢神经系统的退行性疾病，临床表现为运动迟缓、静止性震颤</h5>\n<p>或肌强直等，经相关专科医生确诊，且须满足自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。</p>\n<p>继发性帕金森综合征、帕金森叠加综合征不在保障范围内。注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在疾病定义中特别说明。</p>\n<h5 id=\"s32\">3.1.1.20 严重Ⅲ度烧伤</h5>\n<p>指烧伤程度为Ⅲ度，且Ⅲ度烧伤的面积达到全身体表面积的20％或 20％以上。体表面积根据《中国新九分法》计算。</p>\n<h5 id=\"s33\">3.1.1.21 严重特发性肺动脉高压</h5>\n<p>指不明原因的肺动脉压力持续性增高，进行性发展而导致的慢性疾病，已经造成永久不可逆性的体力活动能力受限，达到美国纽约心脏病学会（New York Heart Association，NYHA）心功能状态分级 IV 级，且静息状态下肺动脉平均压在 36mmHg（含）以上。</p>\n<h5 id=\"s34\">3.1.1.22 严重运动神经元病是一组中枢神经系统运动神经元的进行性变性疾病，包括进行性脊肌萎缩</h5>\n<p>症、进行性延髓麻痹症、原发性侧索硬化症、肌萎缩性侧索硬化症,经相关专科医生确诊，且须满足下列至少一项条件：</p>\n<ul>\n<li>（1）严重咀嚼吞咽功能障碍；</li>\n</ul>\n<ul>\n<li>（2）呼吸肌麻痹导致严重呼吸困难，且已经持续使用呼吸机 7 天（含）以上；</li>\n</ul>\n<ul>\n<li>（3）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。</li>\n</ul>\n<p>注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在疾病定义中特别说明。</p>\n<h5 id=\"s35\">3.1.1.23 语言能力丧失</h5>\n<p>指因疾病或意外伤害导致语言能力完全丧失，经过积极治疗至少 12 个月（声带完全切除不受此时间限制），仍无法通过现有医疗手段恢复。</p>\n<p>精神心理因素所致的语言能力丧失不在保障范围内。注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在疾病定义中特别说明。</p>\n<h5 id=\"s36\">3.1.1.24 重型再生障碍性贫血</h5>\n<p>指因骨髓造血功能慢性持续性衰竭导致的贫血、中性粒细胞减少及血小板减少，且须满足下列全部条件：</p>\n<ul>\n<li>（1）骨髓穿刺检查或骨髓活检结果支持诊断：骨髓细胞增生程度&lt;正常的 25%；如≥正常的 25%但&lt;50%，则残存的造血细胞应&lt;30%；</li>\n</ul>\n<ul>\n<li>（2）外周血象须具备以下三项条件中的两项：①中性粒细胞绝对值&lt;0.5×109/L；</li>\n</ul>\n<p>②网织红细胞计数&lt;20×109/L；③血小板绝对值&lt;20×109/L。</p>\n<h5 id=\"s37\">3.1.1.25 主动脉手术</h5>\n<p>指为治疗主动脉疾病或主动脉创伤，已经实施了开胸（含胸腔镜下）或开腹（含腹腔镜下）进行的切除、置换、修补病损主动脉血管、主动脉创伤后修复的手术。主动脉指升主动脉、主动脉弓和降主动脉（含胸主动脉和腹主动脉），不包括升主动脉、主动脉弓和降主动脉的分支血管。</p>\n<p>所有未实施开胸或开腹的动脉内介入治疗不在保障范围内。</p>\n<h5 id=\"s38\">3.1.1.26 严重慢性呼吸衰竭</h5>\n<p>指因慢性呼吸系统疾病导致永久不可逆性的呼吸衰竭，经过积极治疗 180 天后满足以下所有条件：</p>\n<ul>\n<li>（1）静息时出现呼吸困难；</li>\n</ul>\n<ul>\n<li>（2）肺功能第一秒用力呼气容积（FEV1）占预计值的百分比＜30%；</li>\n</ul>\n<ul>\n<li>（3）在静息状态、呼吸空气条件下，动脉血氧分压（PaO2）＜50mmHg。</li>\n</ul>\n<h5 id=\"s39\">3.1.1.27 严重克罗恩病</h5>\n<p>指一种慢性肉芽肿性肠炎，具有特征性的克罗恩病（Crohn病）病理组织学变化，须根据组织病理学特点诊断，且已经造成瘘管形成并伴有肠梗阻或肠穿孔。</p>\n<h5 id=\"s40\">3.1.1.28 严重溃疡性结肠炎</h5>\n<p>指伴有致命性电解质紊乱的急性暴发性溃疡性结肠炎，病变已经累及全结肠，表现为严重的血便和系统性症状体征，须根据组织病理学特点诊断，且已经实施了结肠切除或回肠造瘘术。</p>\n<h4 id=\"s41\">3.1.2 轻度疾病</h4>\n<h5 id=\"s42\">3.1.2.1 恶性肿瘤——轻度</h5>\n<p>指恶性细胞不受控制的进行性增长和扩散，浸润和破坏周围正常组织，可以经血管、淋巴管和体腔扩散转移到身体其他部位，病灶经组织病理学检查（涵盖骨髓病理学检查）结果明确诊断，临床诊断属于世界卫生组织（WHO， World Health Organization）《疾病和有关健康问题的国际统计分类》第十次修订版（ICD-10）的恶性肿瘤类别及《国际疾病分类肿瘤学专辑》第三版（ICD-O-3）的肿瘤形态学编码属于 3、6、9（恶性肿瘤）范畴，但不在“恶性肿瘤——重度”保障范围的疾病。且特指下列六项之一：</p>\n<ul>\n<li>（1）TNM 分期为Ⅰ期的甲状腺癌；</li>\n</ul>\n<ul>\n<li>（2）TNM 分期为 T1N0M0 期的前列腺癌；</li>\n</ul>\n<ul>\n<li>（3）黑色素瘤以外的未发生淋巴结和远处转移的皮肤恶性肿瘤；</li>\n</ul>\n<ul>\n<li>（4）相当于 Binet 分期方案 A 期程度的慢性淋巴细胞白血病；</li>\n</ul>\n<ul>\n<li>（5）相当于 Ann Arbor 分期方案Ⅰ期程度的何杰金氏病；</li>\n</ul>\n<ul>\n<li>（6）未发生淋巴结和远处转移且 WHO 分级为 G1 级别（核分裂像&lt;10/50 HPF 和 ki-67≤2%）的神经内分泌肿瘤。</li>\n</ul>\n<p>下列疾病不属于“恶性肿瘤——轻度”，不在保障范围内：ICD-O-3 肿瘤形态学编码属于 0（良性肿瘤）、1（动态未定性肿瘤）、2（原位癌和非侵袭性癌）范畴的疾病，如：</p>\n<p>- a.原位癌，癌前病变，非浸润性癌，非侵袭性癌，肿瘤细胞未侵犯基底层，上皮内瘤变，细胞不典型性增生等；</p>\n<p>- b.交界性肿瘤，交界恶性肿瘤，肿瘤低度恶性潜能，潜在低度恶性肿瘤等。</p>\n<h5 id=\"s43\">3.1.2.2 较轻急性心肌梗死急性心肌梗死</h5>\n<p>指由于冠状动脉闭塞或梗阻引起部分心肌严重的持久性缺血造成急性心肌坏死。急性心肌梗死的诊断必须依据国际国内诊断标准，符合（1）检测到肌酸激酶同工酶（CK-MB）或肌钙蛋白（cTn）升高和/或降低的动态变化，至少一次达到或超过心肌梗死的临床诊断标准；（2）同时存在下列之一的证据，包括：缺血性胸痛症状、新发生的缺血性心电图改变、新生成的病理性 Q 波、影像学证据显示有新出现的心肌活性丧失或新出现局部室壁运动异常、冠脉造影证实存在冠状动脉血栓。</p>\n<p>较轻急性心肌梗死指依照上述标准被明确诊断为急性心肌梗死，但未达到“较重急性心肌梗死”的给付标准。</p>\n<p>其他非冠状动脉阻塞性疾病引起的肌钙蛋白（cTn）升高不在保障范围内。</p>\n<h5 id=\"s44\">3.1.2.3 轻度脑中风后遗症</h5>\n<p>指因脑血管的突发病变引起脑血管出血、栓塞或梗塞，须由头颅断层扫描（CT）、核磁共振检查（MRI）等影像学检查证实，并导致神经系统永久性的功能障碍，但未达到“严重脑中风后遗症”的给付标准，在疾病确诊 180 天后，仍遗留下列至少一种障碍：</p>\n<ul>\n<li>（1）一肢（含）以上肢体肌力为 3 级；</li>\n</ul>\n<ul>\n<li>（2）自主生活能力部分丧失，无法独立完成六项基本日常生活活动中的两项。</li>\n</ul>\n<h3 id=\"s45\">3.2</h3>\n<p>重大疾病保险的除外责任因下列情形之一，导致被保险人发生疾病、达到疾病状态或进行手术的，保险公司不承担保险责任：</p>\n<h4 id=\"s46\">3.2.1 投保人对被保险人的故意杀害、故意伤害；</h4>\n<h4 id=\"s47\">3.2.2 被保险人故意犯罪或抗拒依法采取的刑事强制措施；</h4>\n<h4 id=\"s48\">3.2.3 被保险人故意自伤、或自本合同成立或者本合同效力恢复之日起 2 年内自杀，但被保险</h4>\n<p>人自杀时为无民事行为能力人的除外；</p>\n<h4 id=\"s49\">3.2.4 被保险人服用、吸食或注射毒品；</h4>\n<h4 id=\"s50\">3.2.5 被保险人酒后驾驶、无合法有效驾驶证驾驶，或驾驶无合法有效行驶证的机动车；</h4>\n<h4 id=\"s51\">3.2.6 被保险人感染艾滋病病毒或患艾滋病；</h4>\n<h4 id=\"s52\">3.2.7 战争、军事冲突、暴乱或武装叛乱；</h4>\n<h4 id=\"s53\">3.2.8 核爆炸、核辐射或核污染；</h4>\n<h4 id=\"s54\">3.2.9 遗传性疾病，先天性畸形、变形或染色体异常。</h4>\n<h3 id=\"s55\">3.3</h3>\n<p>术语释义</p>\n<h4 id=\"s56\">3.3.1 专科医生</h4>\n<p>专科医生应当同时满足以下四项资格条件：（1）具有有效的中华人民共和国《医师资格证书》；（2）具有有效的中华人民共和国《医师执业证书》，并按期到相关部门登记注册；（3）具有有效的中华人民共和国主治医师或主治医师以上职称的《医师职称证书》；（4）在国家《医院分级管理标准》二级或二级以上医院的相应科室从事临床工作三年以上。</p>\n<h4 id=\"s57\">3.3.2 组织病理学检查</h4>\n<p>组织病理学检查是通过局部切除、钳取、穿刺等手术方法，从患者机体采取病变组织块，经过包埋、切片后，进行病理检查的方法。</p>\n<p>通过采集病变部位脱落细胞、细针吸取病变部位细胞、体腔积液分离病变细胞等方式获取病变细胞，制成涂片，进行病理检查的方法，属于细胞病理学检查，不属于组织病理学检查。</p>\n<h4 id=\"s58\">3.3.3 ICD-10 与</h4>\n<p>ICD-O-3《疾病和有关健康问题的国际统计分类》第十次修订版（ICD-10），是世界卫生组织（WHO）发布的国际通用的疾病分类方法。《国际疾病分类肿瘤学专辑》第三版（ICD-O-3），是 WHO发布的针对 ICD 中肿瘤形态学组织学细胞类型、动态、分化程度的补充编码。其中形态学编码：0 代表良性肿瘤；1 代表动态未定性肿瘤；2 代表原位癌和非侵袭性癌；3 代表恶性肿瘤（原发性）；6 代表恶性肿瘤（转移性）；9 代表恶性肿瘤（原发性或转移性未肯定）。如果出现 ICD-10 与 ICD-O-3 不一致的情况，以ICD-O-3 为准。</p>\n<h4 id=\"s59\">3.3.4 TNM 分期</h4>\n<p>TNM 分期采用 AJCC 癌症分期手册标准。该标准由美国癌症联合委员会与国际抗癌联合会 TNM 委员会联合制定，是目前肿瘤医学分期的国际通用标准。T 指原发肿瘤的大小、形态等；N 指淋巴结的转移情况；M 指有无其他脏器的转移情况。</p>\n<h4 id=\"s60\">3.3.5 甲状腺癌的 TNM 分期</h4>\n<p>甲状腺癌的TNM分期采用目前现行的AJCC第八版定义标准，我国国家卫生健康委员会2018年发布的《甲状腺癌诊疗规范（2018年版）》也采用此定义标准，具体见下：</p>\n<p>甲状腺乳头状癌、滤泡癌、低分化癌、Hürthle 细胞癌和未分化癌pTX：原发肿瘤不能评估</p>\n<p>pT0：无肿瘤证据</p>\n<p>pT1：肿瘤局限在甲状腺内，最大径≤2cmT1a 肿瘤最大径≤1cmT1b 肿瘤最大径＞1cm，≤2cm</p>\n<p>pT2：肿瘤 2～4cm</p>\n<p>pT3：肿瘤&gt;4cm，局限于甲状腺内或大体侵犯甲状腺外带状肌</p>\n<p>pT3a：肿瘤&gt;4cm，局限于甲状腺内</p>\n<p>pT3b：大体侵犯甲状腺外带状肌，无论肿瘤大小带状肌包括：胸骨舌骨肌、胸骨甲状肌、甲状舌骨肌、肩胛舌骨肌</p>\n<p>pT4：大体侵犯甲状腺外带状肌外</p>\n<p>pT4a：侵犯喉、气管、食管、喉反神经及皮下软组织</p>\n<p>pT4b：侵犯椎前筋膜，或包裹颈动脉、纵隔血管甲状腺髓样癌pTX：原发肿瘤不能评估</p>\n<p>pT0：无肿瘤证据</p>\n<p>pT1：肿瘤局限在甲状腺内，最大径≤2cmT1a 肿瘤最大径≤1cmT1b 肿瘤最大径＞1cm，≤2cm</p>\n<p>pT2：肿瘤 2～4cm</p>\n<p>pT3：肿瘤&gt;4cm，局限于甲状腺内或大体侵犯甲状腺外带状肌</p>\n<p>pT3a：肿瘤&gt;4cm，局限于甲状腺内</p>\n<p>pT3b：大体侵犯甲状腺外带状肌，无论肿瘤大小带状肌包括：胸骨舌骨肌、胸骨甲状肌、甲状舌骨肌、肩胛舌骨肌</p>\n<p>pT4：进展期病变</p>\n<p>pT4a：中度进展，任何大小的肿瘤，侵犯甲状腺外颈部周围器官和软组织，如喉、气管、食管、喉反神经及皮下软组织</p>\n<p>pT4b：重度进展，任何大小的肿瘤，侵犯椎前筋膜，或包裹颈动脉、纵隔血管区域淋巴结：适用于所有甲状腺癌pNx：区域淋巴结无法评估pN0：无淋巴结转移证据pN1：区域淋巴结转移pN1a：转移至Ⅵ、Ⅶ区（包括气管旁、气管前、喉前/Delphian 或上纵隔）淋巴结，可以为单侧或双侧。</p>\n<p>pN1b：单侧、双侧或对侧颈淋巴结转移（包括Ⅰ、Ⅱ、Ⅲ、Ⅳ或Ⅴ区）淋巴结或咽后淋巴结转移。</p>\n<p>远处转移：适用于所有甲状腺癌M0：无远处转移M1：有远处转移乳头状或滤泡状癌（分化型）年龄＜55 岁Ⅰ期Ⅱ期年龄≥55 岁Ⅰ期Ⅱ期Ⅲ期ⅣA 期ⅣB 期髓样癌（所有年龄组）N任何任何0/x0/x任何任何任何任何MT任何任何1～23a～3b4a4b任何Ⅰ期Ⅱ期Ⅲ期ⅣA 期ⅣB 期ⅣC 期未分化癌（所有年龄组）ⅣA 期ⅣB 期ⅣC 期2～31～34a1～34b任何1～3a1～3a3b～4任何1a任何1b任何任何0/x任何任何注：以上表格中“年龄”指患者病理组织标本获取日期时的年龄。</p>\n<h4 id=\"s61\">3.3.6 肢体</h4>\n<p>肢体是指包括肩关节的整个上肢或包括髋关节的整个下肢。</p>\n<h4 id=\"s62\">3.3.7 肌力</h4>\n<p>指肌肉收缩时的力量。肌力划分为 0-5 级，具体为：</p>\n<h2 id=\"s63\">0</h2>\n<p>级：肌肉完全瘫痪，毫无收缩。</p>\n<h2 id=\"s64\">1</h2>\n<p>级：可看到或者触及肌肉轻微收缩，但不能产生动作。</p>\n<h2 id=\"s65\">2</h2>\n<p>级：肌肉在不受重力影响下，可进行运动，即肢体能在床面上移动，但不能抬高。</p>\n<h2 id=\"s66\">3</h2>\n<p>级：在和地心引力相反的方向中尚能完成其动作，但不能对抗外加阻力。</p>\n<h2 id=\"s67\">4</h2>\n<p>级：能对抗一定的阻力，但较正常人为低。</p>\n<h2 id=\"s68\">5</h2>\n<p>级：正常肌力。</p>\n<h4 id=\"s69\">3.3.8 语言能力完全丧失或严重咀嚼吞咽功能障碍语言能力完全丧失，</h4>\n<p>指无法发出四种语音（包括口唇音、齿舌音、口盖音和喉头音）中的任何三种、或声带全部切除，或因大脑语言中枢受伤害而患失语症。</p>\n<p>严重咀嚼吞咽功能障碍，指因牙齿以外的原因导致器质障碍或机能障碍，以致不能作咀嚼吞咽运动，除流质食物外不能摄取或吞咽的状态。</p>\n<h4 id=\"s70\">3.3.9 六项基本日常生活活动</h4>\n<p>六项基本日常生活活动是指：（1）穿衣：自己能够穿衣及脱衣；（2）移动：自己从一个房间到另一个房间；（3）行动：自己上下床或上下轮椅；（4）如厕：自己控制进行大小便；（5）进食：</p>\n<p>自己从已准备好的碗或碟中取食物放入口中；（6）洗澡：自己进行淋浴或盆浴。</p>\n<p>六项基本日常生活活动能力的鉴定不适用于 0-3 周岁幼儿。</p>\n<h4 id=\"s71\">3.3.10 永久不可逆</h4>\n<p>指自疾病确诊或意外伤害发生之日起，经过积极治疗 180 天后，仍无法通过现有医疗手段恢复。</p>\n<h4 id=\"s72\">3.3.11 美国纽约心脏病学会（New York Heart Association，NYH</h4>\n<p>A）心功能状态分级美国纽约心脏病学会（New York Heart Association，NYHA）将心功能状态分为四级：</p>\n<p>Ⅰ级：心脏病病人日常活动量不受限制，一般活动不引起乏力、呼吸困难等心衰症状。</p>\n<p>Ⅱ级：心脏病病人体力活动轻度受限制，休息时无自觉症状，一般活动下可出现心衰症状。</p>\n<p>Ⅲ级：心脏病病人体力活动明显受限，低于平时一般活动即引起心衰症状。</p>\n<p>Ⅳ级：心脏病病人不能从事任何体力活动，休息状态下也存在心衰症状，活动后加重。</p>\n<h4 id=\"s73\">3.3.12 感染艾滋病病毒或患艾滋病艾滋病病毒</h4>\n<p>指人类免疫缺陷病毒，英文缩写为 HIV。艾滋病指人类免疫缺陷病毒引起的获得性免疫缺陷综合征，英文缩写为AIDS。</p>\n<p>在人体血液或其他样本中检测到艾滋病病毒或其抗体呈阳性，没有出现临床症状或体征的，为感染艾滋病病毒；如果同时出现了明显临床症状或体征的，为患艾滋病。</p>\n<h4 id=\"s74\">3.3.13 遗传性疾病</h4>\n<p>指生殖细胞或受精卵的遗传物质（染色体和基因）发生突变或畸变所引起的疾病，通常具有由亲代传至后代的垂直传递的特征。</p>\n<h4 id=\"s75\">3.3.14 先天性畸形、变形或染色体异常</h4>\n<p>指被保险人出生时就具有的畸形、变形或染色体异常。先天性畸形、变形和染色体异常依照世界卫生组织《疾病和有关健康问题的国际统计分类》第十次修订版（ICD-10）确定。</p>\n<h2 id=\"s76\">4</h2>\n<p>重大疾病保险宣传材料的相关规定在重大疾病保险的宣传材料中，如果保障的疾病名称单独出现，应当采用以下主标题和副标题结合的形式。</p>\n<h3 id=\"s77\">4.1</h3>\n<p>〔恶性肿瘤——重度〕——不包括部分早期恶性肿瘤</p>\n<h3 id=\"s78\">4.2</h3>\n<p>较重急性心肌梗死</p>\n<h3 id=\"s79\">4.3</h3>\n<p>严重脑中风后遗症——永久性的功能障碍</p>\n<h3 id=\"s80\">4.4</h3>\n<p>重大器官移植术或造血干细胞移植术——重大器官须异体移植手术</p>\n<h3 id=\"s81\">4.5</h3>\n<p>冠状动脉搭桥术（或称冠状动脉旁路移植术）——须切开心包手术</p>\n<h3 id=\"s82\">4.6</h3>\n<p>严重慢性肾衰竭——须规律透析治疗</p>\n<h3 id=\"s83\">4.7</h3>\n<p>多个肢体缺失——完全性断离</p>\n<h3 id=\"s84\">4.8</h3>\n<p>急性重症肝炎或亚急性重症肝炎</p>\n<h3 id=\"s85\">4.9</h3>\n<p>严重非恶性颅内肿瘤——须开颅手术或放射治疗</p>\n<h3 id=\"s86\">4.10</h3>\n<p>严重慢性肝衰竭——不包括酗酒或药物滥用所致</p>\n<h3 id=\"s87\">4.11</h3>\n<p>严重脑炎后遗症或严重脑膜炎后遗症——永久性的功能障碍</p>\n<h3 id=\"s88\">4.12</h3>\n<p>深度昏迷——不包括酗酒或药物滥用所致</p>\n<h3 id=\"s89\">4.13</h3>\n<p>双耳失聪——永久不可逆注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在副标题中注明。</p>\n<h3 id=\"s90\">4.14</h3>\n<p>双目失明——永久不可逆注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在副标题中注明。</p>\n<h3 id=\"s91\">4.15</h3>\n<p>瘫痪——永久完全</p>\n<h3 id=\"s92\">4.16</h3>\n<p>心脏瓣膜手术——须切开心脏手术</p>\n<h3 id=\"s93\">4.17</h3>\n<p>严重阿尔茨海默病——严重认知功能障碍或自主生活能力完全丧失注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在副标题中注明。</p>\n<h3 id=\"s94\">4.18</h3>\n<p>严重脑损伤——永久性的功能障碍</p>\n<h3 id=\"s95\">4.19</h3>\n<p>严重原发性帕金森病——自主生活能力完全丧失注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在副标题中注明。</p>\n<h3 id=\"s96\">4.20</h3>\n<p>严重Ⅲ度烧伤——至少达体表面积的20%</p>\n<h3 id=\"s97\">4.21</h3>\n<p>严重特发性肺动脉高压——有心力衰竭表现</p>\n<h3 id=\"s98\">4.22</h3>\n<p>严重运动神经元病——自主生活能力完全丧失注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在副标题中注明。</p>\n<h3 id=\"s99\">4.23</h3>\n<p>语言能力丧失——完全丧失且经积极治疗至少12个月注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在副标题中注明</p>\n<h3 id=\"s100\">4.24</h3>\n<p>重型再生障碍性贫血</p>\n<h3 id=\"s101\">4.25</h3>\n<p>主动脉手术——须开胸（含胸腔镜下）或开腹（含腹腔镜下）手术</p>\n<h3 id=\"s102\">4.26</h3>\n<p>严重慢性呼吸衰竭——永久不可逆</p>\n<h3 id=\"s103\">4.27</h3>\n<p>严重克罗恩病——瘘管形成</p>\n<h3 id=\"s104\">4.28</h3>\n<p>严重溃疡性结肠炎——须结肠切除或回肠造瘘术</p>\n<h3 id=\"s105\">4.29</h3>\n<p>恶性肿瘤——轻度</p>\n<h3 id=\"s106\">4.30</h3>\n<p>较轻急性心肌梗死</p>\n<h3 id=\"s107\">4.31</h3>\n<p>轻度脑中风后遗症——永久性的功能障碍</p>\n<h2 id=\"s108\">5</h2>\n<p>附则</p>\n<h3 id=\"s109\">5.1</h3>\n<p>中国保险行业协会设立保险行业疾病定义管理办公室，协助中国银保监会做好健康保险产品监管中有关疾病定义的管理工作，建立行业疾病定义长效管理机制，研究重大疾病保险相关疾病医疗实践的进展情况，原则上至少每 5 年对疾病定义及规范进行全面评估，视评估结果决定是否开展修订工作。</p>\n<h3 id=\"s110\">5.2</h3>\n<p>本规范自发布之日起施行。本规范发布之日前已生效的重大疾病保险合同，保险公司应按该保险合同约定做好相关服务工作。</p>\n<p>自 2021 年 2 月 1 日起签订的保险期间主要为成年人（十八周岁及以上）阶段的重大疾病保险合同应当符合本规范。</p>\n<h3 id=\"s111\">5.3</h3>\n<p>本规范由中国保险行业协会负责解释。</p>", "toc": [{"id": "s1", "lv": 2, "t": "1"}, {"id": "s2", "lv": 2, "t": "2"}, {"id": "s3", "lv": 3, "t": "2.1"}, {"id": "s4", "lv": 3, "t": "2.2"}, {"id": "s5", "lv": 3, "t": "2.3"}, {"id": "s6", "lv": 3, "t": "2.4"}, {"id": "s7", "lv": 3, "t": "2.5"}, {"id": "s8", "lv": 2, "t": "3"}, {"id": "s9", "lv": 3, "t": "3.1"}, {"id": "s24", "lv": 2, "t": "500"}, {"id": "s27", "lv": 2, "t": "180"}, {"id": "s45", "lv": 3, "t": "3.2"}, {"id": "s55", "lv": 3, "t": "3.3"}, {"id": "s63", "lv": 2, "t": "0"}, {"id": "s64", "lv": 2, "t": "1"}, {"id": "s65", "lv": 2, "t": "2"}, {"id": "s66", "lv": 2, "t": "3"}, {"id": "s67", "lv": 2, "t": "4"}, {"id": "s68", "lv": 2, "t": "5"}, {"id": "s76", "lv": 2, "t": "4"}, {"id": "s77", "lv": 3, "t": "4.1"}, {"id": "s78", "lv": 3, "t": "4.2"}, {"id": "s79", "lv": 3, "t": "4.3"}, {"id": "s80", "lv": 3, "t": "4.4"}, {"id": "s81", "lv": 3, "t": "4.5"}, {"id": "s82", "lv": 3, "t": "4.6"}, {"id": "s83", "lv": 3, "t": "4.7"}, {"id": "s84", "lv": 3, "t": "4.8"}, {"id": "s85", "lv": 3, "t": "4.9"}, {"id": "s86", "lv": 3, "t": "4.10"}, {"id": "s87", "lv": 3, "t": "4.11"}, {"id": "s88", "lv": 3, "t": "4.12"}, {"id": "s89", "lv": 3, "t": "4.13"}, {"id": "s90", "lv": 3, "t": "4.14"}, {"id": "s91", "lv": 3, "t": "4.15"}, {"id": "s92", "lv": 3, "t": "4.16"}, {"id": "s93", "lv": 3, "t": "4.17"}, {"id": "s94", "lv": 3, "t": "4.18"}, {"id": "s95", "lv": 3, "t": "4.19"}, {"id": "s96", "lv": 3, "t": "4.20"}, {"id": "s97", "lv": 3, "t": "4.21"}, {"id": "s98", "lv": 3, "t": "4.22"}, {"id": "s99", "lv": 3, "t": "4.23"}, {"id": "s100", "lv": 3, "t": "4.24"}, {"id": "s101", "lv": 3, "t": "4.25"}, {"id": "s102", "lv": 3, "t": "4.26"}, {"id": "s103", "lv": 3, "t": "4.27"}, {"id": "s104", "lv": 3, "t": "4.28"}, {"id": "s105", "lv": 3, "t": "4.29"}, {"id": "s106", "lv": 3, "t": "4.30"}, {"id": "s107", "lv": 3, "t": "4.31"}, {"id": "s108", "lv": 2, "t": "5"}, {"id": "s109", "lv": 3, "t": "5.1"}, {"id": "s110", "lv": 3, "t": "5.2"}, {"id": "s111", "lv": 3, "t": "5.3"}], "text": "重大疾病保险的疾病定义使用规范（2020 年修订版）· 原文 来源 ：中国保险行业协会官网发布的规范 PDF（ A 级 · 官方原文 ） https://www.iachina.cn/module/download/downfile.jsp?filename=dfbe46c8f7aa414694e7043603c6fb0b.pdf 发布主体 ：中国保险行业协会 + 中国医师协会，2020 年 11 月 5 日发布。 过渡期 ：发文之日起至 2021 年 1 月 31 日 。过渡期结束后，各公司不得继续销售基于旧规范（2007 版）开发的重大疾病保险产品。 适用范围 ：保险期间主要为成年人（十八周岁及以上）阶段的重大疾病保险。 ⚠️ 本文件为 PDF 文本提取后按版面还原的版本， 条文字句以官方 PDF 为准 。 重大疾病保险的疾病定义使用规范（2020 年修订版）前 言为进一步保护消费者合法权益，提升重大疾病保险产品供给质量，更好地发挥对社会保障体系的重要补充作用，结合我国重大疾病保险发展及现代医学最新进展情况，并广泛研究参考国际经验，中国保险行业协会与中国医师协会共同对2007年制定的重大疾病保险的疾病定义（以下简称疾病定义）进行了修订。 为更好地指导保险公司使用疾病定义，中国保险行业协会特制定《重大疾病保险的疾病定义使用规范（2020年修订版）》（以下简称规范）。 本规范中所称“疾病”是指重大疾病保险合同约定的疾病、疾病状态或手术。 1 适用范围本规范中的疾病定义主要在参考国内外成年人重大疾病保险发展状况并结合现代医学最新进展情况的基础上制定，因此，本规范适用于保险期间主要为成年人（十八周岁及以上）阶段的重大疾病保险。 2 使用原则 2.1 保险公司将产品定名为重大疾病保险，且保险期间主要为成年人（十八周岁及以上）阶段的，该产品保障的疾病范围应当包括本规范内的恶性肿瘤——重度、较重急性心肌梗死、严重脑中风后遗症、重大器官移植术或造血干细胞移植术、冠状动脉搭桥术（或称冠状动脉旁路移植术）、严重慢性肾衰竭；如果该产品还保障了保险金额低于上述六种重度疾病的其他疾病，则还应当包括本规范内的恶性肿瘤——轻度、较轻急性心肌梗死、轻度脑中风后遗症。除前述疾病外，对于本规范疾病范围以内的其他疾病，保险公司可以选择使用；同时，上述疾病均应当使用本规范的疾病名称和疾病定义。 2.2 保险公司设计重大疾病保险产品时，所包含的本规范中的每种轻度疾病累计保险金额分别不应高于所包含的本规范中的相应重度疾病累计保险金额的 30%；如有多次赔付责任的，轻度疾病的单次保险金额还应不高于同一赔付次序的相应重度疾病单次保险金额的 30%，无相同赔付次序的，以最近的赔付次序为参照。 2.3 根据市场需求和经验数据，各保险公司可以在其重大疾病保险产品中增加本规范疾病范围以外的其他疾病，并合理制定相关定义。 2.4 重大疾病保险条款和配套宣传材料中，本规范规定的疾病应当按照本规范 3.1 所列顺序排列（对于分组列示疾病的，本规范规定的疾病可以按照疾病分组顺序排列），并置于各保险公司自行增加的疾病之前；同时，应当对二者予以区别说明。 2.5 保险公司设定重大疾病保险除外责任时，对于被保险人发生的疾病、达到的疾病状态或进行的手术，保险公司不承担保险责任的情形不能超出本规范 3.2 规定的范围。 3 重大疾病保险条款的相关规定重大疾病保险条款中的疾病名称、疾病定义、除外责任和术语释义应当符合本规范的具体规定。 3.1 重大疾病保险的疾病名称及疾病定义被保险人发生符合以下疾病定义所述条件的疾病，应当由专科医生明确诊断。 以下疾病名称仅供理解使用，具体保障范围以每项疾病具体定义为准。 3.1.1 重度疾病 3.1.1.1 恶性肿瘤——重度 指恶性细胞不受控制的进行性增长和扩散，浸润和破坏周围正常组织，可以经血管、淋巴管和体腔扩散转移到身体其他部位，病灶经组织病理学检查（涵盖骨髓病理学检查）结果明确诊断，临床诊断属于世界卫生组织（WHO，World Health Organization）《疾病和有关健康问题的国际统计分类》第十次修订版（ICD 10）的恶性肿瘤类别及《国际疾病分类肿瘤学专辑》第三版（ICD O 3）的肿瘤形态学编码属于 3、6、9（恶性肿瘤）范畴的疾病。 下列疾病不属于“恶性肿瘤——重度”，不在保障范围内： （1）ICD O 3 肿瘤形态学编码属于 0（良性肿瘤）、1（动态未定性肿瘤）、2（原位癌和非侵袭性癌）范畴的疾病，如： a.原位癌，癌前病变，非浸润性癌，非侵袭性癌，肿瘤细胞未侵犯基底层，上皮内瘤变，细胞不典型性增生等； b.交界性肿瘤，交界恶性肿瘤，肿瘤低度恶性潜能，潜在低度恶性肿瘤等； （2）TNM 分期为Ⅰ期或更轻分期的甲状腺癌； （3）TNM 分期为 T1N0M0 期或更轻分期的前列腺癌； （4）黑色素瘤以外的未发生淋巴结和远处转移的皮肤恶性肿瘤； （5）相当于 Binet 分期方案 A 期程度的慢性淋巴细胞白血病； （6）相当于 Ann Arbor 分期方案Ⅰ期程度的何杰金氏病； （7）未发生淋巴结和远处转移且 WHO 分级为 G1 级别（核分裂像<10/50 HPF 和 ki 67≤2%）或更轻分级的神经内分泌肿瘤。 3.1.1.2 较重急性心肌梗死急性心肌梗死 指由于冠状动脉闭塞或梗阻引起部分心肌严重的持久性缺血造成急性心肌坏死。急性心肌梗死的诊断必须依据国际国内诊断标准，符合（1）检测到肌酸激酶同工酶（CK MB）或肌钙蛋白（cTn）升高和/或降低的动态变化，至少一次达到或超过心肌梗死的临床诊断标准；（2）同时存在下列之一的证据，包括：缺血性胸痛症状、新发生的缺血性心电图改变、新生成的病理性 Q 波、影像学证据显示有新出现的心肌活性丧失或新出现局部室壁运动异常、冠脉造影证实存在冠状动脉血栓。 较重急性心肌梗死指依照上述标准被明确诊断为急性心肌梗死，并且必须同时满足下列至少一项条件： （1）心肌损伤标志物肌钙蛋白（cTn）升高，至少一次检测结果达到该检验正常参考值上限的 15 倍（含）以上； （2）肌酸激酶同工酶（CK MB）升高，至少一次检测结果达到该检验正常参考值上限的 2 倍（含）以上； （3）出现左心室收缩功能下降，在确诊 6 周以后，检测左室射血分数（LVEF）低于 50%（不含）； （4）影像学检查证实存在新发的乳头肌功能失调或断裂引起的中度（含）以上的二尖瓣反流； （5）影像学检查证实存在新出现的室壁瘤； （6）出现室性心动过速、心室颤动或心源性休克。其他非冠状动脉阻塞性疾病所引起的肌钙蛋白（cTn）升高不在保障范围内。 3.1.1.3 严重脑中风后遗症 指因脑血管的突发病变引起脑血管出血、栓塞或梗塞，须由头颅断层扫描（CT）、核磁共振检查（MRI）等影像学检查证实，并导致神经系统永久性的功能障碍。神经系统永久性的功能障碍，指疾病确诊 180 天后，仍遗留下列至少一种障碍： （1）一肢（含）以上肢体肌力 2 级（含）以下； （2）语言能力完全丧失，或严重咀嚼吞咽功能障碍； （3）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。 3.1.1.4 重大器官移植术或造血干细胞移植术重大器官移植术， 指因相应器官功能衰竭，已经实施了肾脏、肝脏、心脏、肺脏或小肠的异体移植手术。 造血干细胞移植术，指因造血功能损害或造血系统恶性肿瘤，已经实施了造血干细胞（包括骨髓造血干细胞、外周血造血干细胞和脐血造血干细胞）的移植手术。 3.1.1.5 冠状动脉搭桥术（或称冠状动脉旁路移植术） 指为治疗严重的冠心病，已经实施了切开心包进行的冠状动脉血管旁路移植的手术。 所有未切开心包的冠状动脉介入治疗不在保障范围内。 3.1.1.6 严重慢性肾衰竭 指双肾功能慢性不可逆性衰竭，依据肾脏病预后质量倡议（K/DOQI）制定的指南，分期达到慢性肾脏病 5 期，且经诊断后已经进行了至少 90 天的规律性透析治疗。规律性透析是指每周进行血液透析或每天进行腹膜透析。 3.1.1.7 多个肢体缺失 指因疾病或意外伤害导致两个或两个以上肢体自腕关节或踝关节近端（靠近躯干端）以上完全性断离。 3.1.1.8 急性重症肝炎或亚急性重症肝炎 指因肝炎病毒感染引起肝脏组织弥漫性坏死，导致急性肝功能衰竭，且经血清学或病毒学检查证实，并须满足下列全部条件： （1）重度黄疸或黄疸迅速加重； （2）肝性脑病； （3）B 超或其他影像学检查显示肝脏体积急速萎缩； （4）肝功能指标进行性恶化。 3.1.1.9 严重非恶性颅内肿瘤 指起源于脑、脑神经、脑被膜的非恶性肿瘤，ICD O 3 肿瘤形态学编码属于 0（良性肿瘤）、1（动态未定性肿瘤）范畴，并已经引起颅内压升高或神经系统功能损害，出现视乳头水肿或视觉受损、听觉受损、面部或肢体瘫痪、癫痫等，须由头颅断层扫描（CT）、核磁共振检查（MRI）或正电子发射断层扫描（PET）等影像学检查证实，且须满足下列至少一项条件： （1）已经实施了开颅进行的颅内肿瘤完全或部分切除手术； （2）已经实施了针对颅内肿瘤的放射治疗，如γ刀、质子重离子治疗等。 下列疾病不在保障范围内： （1）脑垂体瘤； （2）脑囊肿； （3）颅内血管性疾病（如脑动脉瘤、脑动静脉畸形、海绵状血管瘤、毛细血管扩张症等）。 3.1.1.10 严重慢性肝衰竭 指因慢性肝脏疾病导致的肝衰竭，且须满足下列全部条件： （1）持续性黄疸； （2）腹水； （3）肝性脑病； （4）充血性脾肿大伴脾功能亢进或食管胃底静脉曲张。因酗酒或药物滥用导致的肝衰竭不在保障范围内。 3.1.1.11 严重脑炎后遗症或严重脑膜炎后遗症 指因患脑炎或脑膜炎导致的神经系统永久性的功能障碍。神经系统永久性的功能障碍，指经相关专科医生确诊疾病 180 天后，仍遗留下列至少一种障碍： （1）一肢（含）以上肢体肌力 2 级（含）以下； （2）语言能力完全丧失，或严重咀嚼吞咽功能障碍； （3）由具有评估资格的专科医生根据临床痴呆评定量表（CDR，Clinical Dementia Rating）评估结果为 3 分； （4）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。 3.1.1.12 深度昏迷 指因疾病或意外伤害导致意识丧失，对外界刺激和体内需求均无反应，昏迷程度按照格拉斯哥昏迷分级（GCS，Glasgow ComaScale）结果为 5 分或 5 分以下，且已经持续使用呼吸机及其他生命维持系统 96 小时以上。 因酗酒或药物滥用导致的深度昏迷不在保障范围内。 3.1.1.13 双耳失聪 指因疾病或意外伤害导致双耳听力永久不可逆性丧失，在 500 赫兹、1000 赫兹和 2000 赫兹语音频率下，平均听阈大于等于 91 分贝，且经纯音听力测试、声导抗检测或听觉诱发电位检测等证实。 注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在疾病定义中特别说明。 3.1.1.14 双目失明 指因疾病或意外伤害导致双眼视力永久不可逆性丧失，双眼中较好眼须满足下列至少一项条件： （1）眼球缺失或摘除； （2）矫正视力低于 0.02（采用国际标准视力表，如果使用其他视力表应进行换算）； （3）视野半径小于 5 度。注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在疾病定义中特别说明。 3.1.1.15 瘫痪 指因疾病或意外伤害导致两肢或两肢以上肢体随意运动功能永久完全丧失。肢体随意运动功能永久完全丧失，指疾病确诊 180 天后或意外伤害发生 180 天后，每肢三大关节中的两大关节仍然完全僵硬，或肢体肌力在 2 级（含）以下。 3.1.1.16 心脏瓣膜手术 指为治疗心脏瓣膜疾病，已经实施了切开心脏进行的心脏瓣膜置换或修复的手术。 所有未切开心脏的心脏瓣膜介入手术不在保障范围内。 3.1.1.17 严重阿尔茨海默病 指因大脑进行性、不可逆性改变导致智能严重衰退或丧失，临床表现为严重的认知功能障碍、精神行为异常和社交能力减退等，其日常生活必须持续受到他人监护。须由头颅断层扫描（CT）、核磁共振检查（MRI）或正电子发射断层扫描（PET）等影像学检查证实，并经相关专科医生确诊，且须满足下列至少一项条件： （1）由具有评估资格的专科医生根据临床痴呆评定量表（CDR，Clinical Dementia Rating）评估结果为 3 分； （2）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。 阿尔茨海默病之外的其他类型痴呆不在保障范围内。注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在疾病定义中特别说明。 3.1.1.18 严重脑损伤 指因头部遭受机械性外力，引起脑重要部位损伤，导致神经系统永久性的功能障碍。须由头颅断层扫描（CT）、核磁共振检查（MRI）或正电子发射断层扫描（PET）等影像学检查证实。神经系统永久性的功能障碍，指脑损伤 180 天后，仍遗留下列至少一种障碍： （1）一肢（含）以上肢体肌力 2 级（含）以下； （2）语言能力完全丧失，或严重咀嚼吞咽功能障碍； （3）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。 3.1.1.19 严重原发性帕金森病是一种中枢神经系统的退行性疾病，临床表现为运动迟缓、静止性震颤 或肌强直等，经相关专科医生确诊，且须满足自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。 继发性帕金森综合征、帕金森叠加综合征不在保障范围内。注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在疾病定义中特别说明。 3.1.1.20 严重Ⅲ度烧伤 指烧伤程度为Ⅲ度，且Ⅲ度烧伤的面积达到全身体表面积的20％或 20％以上。体表面积根据《中国新九分法》计算。 3.1.1.21 严重特发性肺动脉高压 指不明原因的肺动脉压力持续性增高，进行性发展而导致的慢性疾病，已经造成永久不可逆性的体力活动能力受限，达到美国纽约心脏病学会（New York Heart Association，NYHA）心功能状态分级 IV 级，且静息状态下肺动脉平均压在 36mmHg（含）以上。 3.1.1.22 严重运动神经元病是一组中枢神经系统运动神经元的进行性变性疾病，包括进行性脊肌萎缩 症、进行性延髓麻痹症、原发性侧索硬化症、肌萎缩性侧索硬化症,经相关专科医生确诊，且须满足下列至少一项条件： （1）严重咀嚼吞咽功能障碍； （2）呼吸肌麻痹导致严重呼吸困难，且已经持续使用呼吸机 7 天（含）以上； （3）自主生活能力完全丧失，无法独立完成六项基本日常生活活动中的三项或三项以上。 注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在疾病定义中特别说明。 3.1.1.23 语言能力丧失 指因疾病或意外伤害导致语言能力完全丧失，经过积极治疗至少 12 个月（声带完全切除不受此时间限制），仍无法通过现有医疗手段恢复。 精神心理因素所致的语言能力丧失不在保障范围内。注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在疾病定义中特别说明。 3.1.1.24 重型再生障碍性贫血 指因骨髓造血功能慢性持续性衰竭导致的贫血、中性粒细胞减少及血小板减少，且须满足下列全部条件： （1）骨髓穿刺检查或骨髓活检结果支持诊断：骨髓细胞增生程度<正常的 25%；如≥正常的 25%但<50%，则残存的造血细胞应<30%； （2）外周血象须具备以下三项条件中的两项：①中性粒细胞绝对值<0.5×109/L； ②网织红细胞计数<20×109/L；③血小板绝对值<20×109/L。 3.1.1.25 主动脉手术 指为治疗主动脉疾病或主动脉创伤，已经实施了开胸（含胸腔镜下）或开腹（含腹腔镜下）进行的切除、置换、修补病损主动脉血管、主动脉创伤后修复的手术。主动脉指升主动脉、主动脉弓和降主动脉（含胸主动脉和腹主动脉），不包括升主动脉、主动脉弓和降主动脉的分支血管。 所有未实施开胸或开腹的动脉内介入治疗不在保障范围内。 3.1.1.26 严重慢性呼吸衰竭 指因慢性呼吸系统疾病导致永久不可逆性的呼吸衰竭，经过积极治疗 180 天后满足以下所有条件： （1）静息时出现呼吸困难； （2）肺功能第一秒用力呼气容积（FEV1）占预计值的百分比＜30%； （3）在静息状态、呼吸空气条件下，动脉血氧分压（PaO2）＜50mmHg。 3.1.1.27 严重克罗恩病 指一种慢性肉芽肿性肠炎，具有特征性的克罗恩病（Crohn病）病理组织学变化，须根据组织病理学特点诊断，且已经造成瘘管形成并伴有肠梗阻或肠穿孔。 3.1.1.28 严重溃疡性结肠炎 指伴有致命性电解质紊乱的急性暴发性溃疡性结肠炎，病变已经累及全结肠，表现为严重的血便和系统性症状体征，须根据组织病理学特点诊断，且已经实施了结肠切除或回肠造瘘术。 3.1.2 轻度疾病 3.1.2.1 恶性肿瘤——轻度 指恶性细胞不受控制的进行性增长和扩散，浸润和破坏周围正常组织，可以经血管、淋巴管和体腔扩散转移到身体其他部位，病灶经组织病理学检查（涵盖骨髓病理学检查）结果明确诊断，临床诊断属于世界卫生组织（WHO， World Health Organization）《疾病和有关健康问题的国际统计分类》第十次修订版（ICD 10）的恶性肿瘤类别及《国际疾病分类肿瘤学专辑》第三版（ICD O 3）的肿瘤形态学编码属于 3、6、9（恶性肿瘤）范畴，但不在“恶性肿瘤——重度”保障范围的疾病。且特指下列六项之一： （1）TNM 分期为Ⅰ期的甲状腺癌； （2）TNM 分期为 T1N0M0 期的前列腺癌； （3）黑色素瘤以外的未发生淋巴结和远处转移的皮肤恶性肿瘤； （4）相当于 Binet 分期方案 A 期程度的慢性淋巴细胞白血病； （5）相当于 Ann Arbor 分期方案Ⅰ期程度的何杰金氏病； （6）未发生淋巴结和远处转移且 WHO 分级为 G1 级别（核分裂像<10/50 HPF 和 ki 67≤2%）的神经内分泌肿瘤。 下列疾病不属于“恶性肿瘤——轻度”，不在保障范围内：ICD O 3 肿瘤形态学编码属于 0（良性肿瘤）、1（动态未定性肿瘤）、2（原位癌和非侵袭性癌）范畴的疾病，如： a.原位癌，癌前病变，非浸润性癌，非侵袭性癌，肿瘤细胞未侵犯基底层，上皮内瘤变，细胞不典型性增生等； b.交界性肿瘤，交界恶性肿瘤，肿瘤低度恶性潜能，潜在低度恶性肿瘤等。 3.1.2.2 较轻急性心肌梗死急性心肌梗死 指由于冠状动脉闭塞或梗阻引起部分心肌严重的持久性缺血造成急性心肌坏死。急性心肌梗死的诊断必须依据国际国内诊断标准，符合（1）检测到肌酸激酶同工酶（CK MB）或肌钙蛋白（cTn）升高和/或降低的动态变化，至少一次达到或超过心肌梗死的临床诊断标准；（2）同时存在下列之一的证据，包括：缺血性胸痛症状、新发生的缺血性心电图改变、新生成的病理性 Q 波、影像学证据显示有新出现的心肌活性丧失或新出现局部室壁运动异常、冠脉造影证实存在冠状动脉血栓。 较轻急性心肌梗死指依照上述标准被明确诊断为急性心肌梗死，但未达到“较重急性心肌梗死”的给付标准。 其他非冠状动脉阻塞性疾病引起的肌钙蛋白（cTn）升高不在保障范围内。 3.1.2.3 轻度脑中风后遗症 指因脑血管的突发病变引起脑血管出血、栓塞或梗塞，须由头颅断层扫描（CT）、核磁共振检查（MRI）等影像学检查证实，并导致神经系统永久性的功能障碍，但未达到“严重脑中风后遗症”的给付标准，在疾病确诊 180 天后，仍遗留下列至少一种障碍： （1）一肢（含）以上肢体肌力为 3 级； （2）自主生活能力部分丧失，无法独立完成六项基本日常生活活动中的两项。 3.2 重大疾病保险的除外责任因下列情形之一，导致被保险人发生疾病、达到疾病状态或进行手术的，保险公司不承担保险责任： 3.2.1 投保人对被保险人的故意杀害、故意伤害； 3.2.2 被保险人故意犯罪或抗拒依法采取的刑事强制措施； 3.2.3 被保险人故意自伤、或自本合同成立或者本合同效力恢复之日起 2 年内自杀，但被保险 人自杀时为无民事行为能力人的除外； 3.2.4 被保险人服用、吸食或注射毒品； 3.2.5 被保险人酒后驾驶、无合法有效驾驶证驾驶，或驾驶无合法有效行驶证的机动车； 3.2.6 被保险人感染艾滋病病毒或患艾滋病； 3.2.7 战争、军事冲突、暴乱或武装叛乱； 3.2.8 核爆炸、核辐射或核污染； 3.2.9 遗传性疾病，先天性畸形、变形或染色体异常。 3.3 术语释义 3.3.1 专科医生 专科医生应当同时满足以下四项资格条件：（1）具有有效的中华人民共和国《医师资格证书》；（2）具有有效的中华人民共和国《医师执业证书》，并按期到相关部门登记注册；（3）具有有效的中华人民共和国主治医师或主治医师以上职称的《医师职称证书》；（4）在国家《医院分级管理标准》二级或二级以上医院的相应科室从事临床工作三年以上。 3.3.2 组织病理学检查 组织病理学检查是通过局部切除、钳取、穿刺等手术方法，从患者机体采取病变组织块，经过包埋、切片后，进行病理检查的方法。 通过采集病变部位脱落细胞、细针吸取病变部位细胞、体腔积液分离病变细胞等方式获取病变细胞，制成涂片，进行病理检查的方法，属于细胞病理学检查，不属于组织病理学检查。 3.3.3 ICD 10 与 ICD O 3《疾病和有关健康问题的国际统计分类》第十次修订版（ICD 10），是世界卫生组织（WHO）发布的国际通用的疾病分类方法。《国际疾病分类肿瘤学专辑》第三版（ICD O 3），是 WHO发布的针对 ICD 中肿瘤形态学组织学细胞类型、动态、分化程度的补充编码。其中形态学编码：0 代表良性肿瘤；1 代表动态未定性肿瘤；2 代表原位癌和非侵袭性癌；3 代表恶性肿瘤（原发性）；6 代表恶性肿瘤（转移性）；9 代表恶性肿瘤（原发性或转移性未肯定）。如果出现 ICD 10 与 ICD O 3 不一致的情况，以ICD O 3 为准。 3.3.4 TNM 分期 TNM 分期采用 AJCC 癌症分期手册标准。该标准由美国癌症联合委员会与国际抗癌联合会 TNM 委员会联合制定，是目前肿瘤医学分期的国际通用标准。T 指原发肿瘤的大小、形态等；N 指淋巴结的转移情况；M 指有无其他脏器的转移情况。 3.3.5 甲状腺癌的 TNM 分期 甲状腺癌的TNM分期采用目前现行的AJCC第八版定义标准，我国国家卫生健康委员会2018年发布的《甲状腺癌诊疗规范（2018年版）》也采用此定义标准，具体见下： 甲状腺乳头状癌、滤泡癌、低分化癌、Hürthle 细胞癌和未分化癌pTX：原发肿瘤不能评估 pT0：无肿瘤证据 pT1：肿瘤局限在甲状腺内，最大径≤2cmT1a 肿瘤最大径≤1cmT1b 肿瘤最大径＞1cm，≤2cm pT2：肿瘤 2～4cm pT3：肿瘤 4cm，局限于甲状腺内或大体侵犯甲状腺外带状肌 pT3a：肿瘤 4cm，局限于甲状腺内 pT3b：大体侵犯甲状腺外带状肌，无论肿瘤大小带状肌包括：胸骨舌骨肌、胸骨甲状肌、甲状舌骨肌、肩胛舌骨肌 pT4：大体侵犯甲状腺外带状肌外 pT4a：侵犯喉、气管、食管、喉反神经及皮下软组织 pT4b：侵犯椎前筋膜，或包裹颈动脉、纵隔血管甲状腺髓样癌pTX：原发肿瘤不能评估 pT0：无肿瘤证据 pT1：肿瘤局限在甲状腺内，最大径≤2cmT1a 肿瘤最大径≤1cmT1b 肿瘤最大径＞1cm，≤2cm pT2：肿瘤 2～4cm pT3：肿瘤 4cm，局限于甲状腺内或大体侵犯甲状腺外带状肌 pT3a：肿瘤 4cm，局限于甲状腺内 pT3b：大体侵犯甲状腺外带状肌，无论肿瘤大小带状肌包括：胸骨舌骨肌、胸骨甲状肌、甲状舌骨肌、肩胛舌骨肌 pT4：进展期病变 pT4a：中度进展，任何大小的肿瘤，侵犯甲状腺外颈部周围器官和软组织，如喉、气管、食管、喉反神经及皮下软组织 pT4b：重度进展，任何大小的肿瘤，侵犯椎前筋膜，或包裹颈动脉、纵隔血管区域淋巴结：适用于所有甲状腺癌pNx：区域淋巴结无法评估pN0：无淋巴结转移证据pN1：区域淋巴结转移pN1a：转移至Ⅵ、Ⅶ区（包括气管旁、气管前、喉前/Delphian 或上纵隔）淋巴结，可以为单侧或双侧。 pN1b：单侧、双侧或对侧颈淋巴结转移（包括Ⅰ、Ⅱ、Ⅲ、Ⅳ或Ⅴ区）淋巴结或咽后淋巴结转移。 远处转移：适用于所有甲状腺癌M0：无远处转移M1：有远处转移乳头状或滤泡状癌（分化型）年龄＜55 岁Ⅰ期Ⅱ期年龄≥55 岁Ⅰ期Ⅱ期Ⅲ期ⅣA 期ⅣB 期髓样癌（所有年龄组）N任何任何0/x0/x任何任何任何任何MT任何任何1～23a～3b4a4b任何Ⅰ期Ⅱ期Ⅲ期ⅣA 期ⅣB 期ⅣC 期未分化癌（所有年龄组）ⅣA 期ⅣB 期ⅣC 期2～31～34a1～34b任何1～3a1～3a3b～4任何1a任何1b任何任何0/x任何任何注：以上表格中“年龄”指患者病理组织标本获取日期时的年龄。 3.3.6 肢体 肢体是指包括肩关节的整个上肢或包括髋关节的整个下肢。 3.3.7 肌力 指肌肉收缩时的力量。肌力划分为 0 5 级，具体为： 0 级：肌肉完全瘫痪，毫无收缩。 1 级：可看到或者触及肌肉轻微收缩，但不能产生动作。 2 级：肌肉在不受重力影响下，可进行运动，即肢体能在床面上移动，但不能抬高。 3 级：在和地心引力相反的方向中尚能完成其动作，但不能对抗外加阻力。 4 级：能对抗一定的阻力，但较正常人为低。 5 级：正常肌力。 3.3.8 语言能力完全丧失或严重咀嚼吞咽功能障碍语言能力完全丧失， 指无法发出四种语音（包括口唇音、齿舌音、口盖音和喉头音）中的任何三种、或声带全部切除，或因大脑语言中枢受伤害而患失语症。 严重咀嚼吞咽功能障碍，指因牙齿以外的原因导致器质障碍或机能障碍，以致不能作咀嚼吞咽运动，除流质食物外不能摄取或吞咽的状态。 3.3.9 六项基本日常生活活动 六项基本日常生活活动是指：（1）穿衣：自己能够穿衣及脱衣；（2）移动：自己从一个房间到另一个房间；（3）行动：自己上下床或上下轮椅；（4）如厕：自己控制进行大小便；（5）进食： 自己从已准备好的碗或碟中取食物放入口中；（6）洗澡：自己进行淋浴或盆浴。 六项基本日常生活活动能力的鉴定不适用于 0 3 周岁幼儿。 3.3.10 永久不可逆 指自疾病确诊或意外伤害发生之日起，经过积极治疗 180 天后，仍无法通过现有医疗手段恢复。 3.3.11 美国纽约心脏病学会（New York Heart Association，NYH A）心功能状态分级美国纽约心脏病学会（New York Heart Association，NYHA）将心功能状态分为四级： Ⅰ级：心脏病病人日常活动量不受限制，一般活动不引起乏力、呼吸困难等心衰症状。 Ⅱ级：心脏病病人体力活动轻度受限制，休息时无自觉症状，一般活动下可出现心衰症状。 Ⅲ级：心脏病病人体力活动明显受限，低于平时一般活动即引起心衰症状。 Ⅳ级：心脏病病人不能从事任何体力活动，休息状态下也存在心衰症状，活动后加重。 3.3.12 感染艾滋病病毒或患艾滋病艾滋病病毒 指人类免疫缺陷病毒，英文缩写为 HIV。艾滋病指人类免疫缺陷病毒引起的获得性免疫缺陷综合征，英文缩写为AIDS。 在人体血液或其他样本中检测到艾滋病病毒或其抗体呈阳性，没有出现临床症状或体征的，为感染艾滋病病毒；如果同时出现了明显临床症状或体征的，为患艾滋病。 3.3.13 遗传性疾病 指生殖细胞或受精卵的遗传物质（染色体和基因）发生突变或畸变所引起的疾病，通常具有由亲代传至后代的垂直传递的特征。 3.3.14 先天性畸形、变形或染色体异常 指被保险人出生时就具有的畸形、变形或染色体异常。先天性畸形、变形和染色体异常依照世界卫生组织《疾病和有关健康问题的国际统计分类》第十次修订版（ICD 10）确定。 4 重大疾病保险宣传材料的相关规定在重大疾病保险的宣传材料中，如果保障的疾病名称单独出现，应当采用以下主标题和副标题结合的形式。 4.1 〔恶性肿瘤——重度〕——不包括部分早期恶性肿瘤 4.2 较重急性心肌梗死 4.3 严重脑中风后遗症——永久性的功能障碍 4.4 重大器官移植术或造血干细胞移植术——重大器官须异体移植手术 4.5 冠状动脉搭桥术（或称冠状动脉旁路移植术）——须切开心包手术 4.6 严重慢性肾衰竭——须规律透析治疗 4.7 多个肢体缺失——完全性断离 4.8 急性重症肝炎或亚急性重症肝炎 4.9 严重非恶性颅内肿瘤——须开颅手术或放射治疗 4.10 严重慢性肝衰竭——不包括酗酒或药物滥用所致 4.11 严重脑炎后遗症或严重脑膜炎后遗症——永久性的功能障碍 4.12 深度昏迷——不包括酗酒或药物滥用所致 4.13 双耳失聪——永久不可逆注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在副标题中注明。 4.14 双目失明——永久不可逆注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在副标题中注明。 4.15 瘫痪——永久完全 4.16 心脏瓣膜手术——须切开心脏手术 4.17 严重阿尔茨海默病——严重认知功能障碍或自主生活能力完全丧失注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在副标题中注明。 4.18 严重脑损伤——永久性的功能障碍 4.19 严重原发性帕金森病——自主生活能力完全丧失注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在副标题中注明。 4.20 严重Ⅲ度烧伤——至少达体表面积的20% 4.21 严重特发性肺动脉高压——有心力衰竭表现 4.22 严重运动神经元病——自主生活能力完全丧失注：如果保险公司仅承担被保险人在某年龄之前的保障责任，须在副标题中注明。 4.23 语言能力丧失——完全丧失且经积极治疗至少12个月注：如果保险公司仅承担被保险人在某年龄之后的保障责任，须在副标题中注明 4.24 重型再生障碍性贫血 4.25 主动脉手术——须开胸（含胸腔镜下）或开腹（含腹腔镜下）手术 4.26 严重慢性呼吸衰竭——永久不可逆 4.27 严重克罗恩病——瘘管形成 4.28 严重溃疡性结肠炎——须结肠切除或回肠造瘘术 4.29 恶性肿瘤——轻度 4.30 较轻急性心肌梗死 4.31 轻度脑中风后遗症——永久性的功能障碍 5 附则 5.1 中国保险行业协会设立保险行业疾病定义管理办公室，协助中国银保监会做好健康保险产品监管中有关疾病定义的管理工作，建立行业疾病定义长效管理机制，研究重大疾病保险相关疾病医疗实践的进展情况，原则上至少每 5 年对疾病定义及规范进行全面评估，视评估结果决定是否开展修订工作。 5.2 本规范自发布之日起施行。本规范发布之日前已生效的重大疾病保险合同，保险公司应按该保险合同约定做好相关服务工作。 自 2021 年 2 月 1 日起签订的保险期间主要为成年人（十八周岁及以上）阶段的重大疾病保险合同应当符合本规范。 5.3 本规范由中国保险行业协会负责解释。"}, {"id": "L4-法条库/02-民法典格式条款与合同编通则解释", "group": "5 · 法条原文", "groupKey": "L4-法条库", "title": "民法典格式条款 + 合同编通则司法解释（保险维权核心条文）", "order": 5, "file": "02-民法典格式条款与合同编通则解释.md", "html": "<h1 id=\"s0\">民法典格式条款 + 合同编通则司法解释（保险维权核心条文）</h1>\n<blockquote><strong>来源</strong>：最高人民法院公报（民法典条文）、北京金融法院官网「金融案鉴」栏目、多地法院官网引用（合同编通则解释第 10 条）。<br><strong>可信度</strong>：A 级（官方来源原文）。<span class=\"warn\">!</span> 条文以官方文本为准。<br><br><strong>为什么这一组条文重要</strong>：保险合同 100% 是格式合同。<strong>「提示说明义务」这条武器，民法典 496 条 + 合同编通则解释第 10 条，比保险法第 17 条更锋利</strong>——尤其第 10 条第 3 款，直接击穿了互联网投保的\"勾选/弹窗\"抗辩。</blockquote>\n<hr>\n<h2 id=\"s1\">一、《民法典》第四百九十六条【格式条款的定义与提示说明义务】</h2>\n<blockquote>格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。<br><br>采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意<strong>免除或者减轻其责任等与对方有重大利害关系的条款</strong>，按照对方的要求，对该条款予以说明。提供格式条款的一方未履行提示或者说明义务，<strong>致使对方没有注意或者理解与其有重大利害关系的条款的，对方可以主张该条款不成为合同的内容</strong>。</blockquote>\n<p><strong>要点</strong></p>\n<ol>\n<li><strong>\"有重大利害关系\"的范围比保险法的\"免责条款\"更宽</strong>——不限于免除责任，还包括限制对方权利等。</li>\n<li><strong>法律后果是\"不成为合同的内容\"</strong>（而非\"不生效\"），即该条款压根没进合同，保险人无从援引。</li>\n<li>与保险法 §17 是<strong>并列</strong>关系，可以<strong>同时主张</strong>。</li>\n</ol>\n<hr>\n<h2 id=\"s2\">二、《民法典》第四百九十七条【格式条款无效的情形】</h2>\n<blockquote>有下列情形之一的，该格式条款无效：<br><br>（一）具有本法第一编第六章第三节和本法第五百零六条规定的无效情形；<br><br>（二）提供格式条款一方<strong>不合理地免除或者减轻其责任、加重对方责任、限制对方主要权利</strong>；<br><br>（三）提供格式条款一方<strong>排除对方主要权利</strong>。</blockquote>\n<p><strong>要点</strong>：与保险法 §19（免除保险人依法应承担的义务、加重投保人责任、排除投保人/被保险人/受益人依法享有的权利的条款无效）<strong>高度重合，可并列主张</strong>。</p>\n<hr>\n<h2 id=\"s3\">三、《民法典》第四百九十八条【格式条款的解释】</h2>\n<blockquote>对格式条款的理解发生争议的，应当按照<strong>通常理解</strong>予以解释。对格式条款有<strong>两种以上解释</strong>的，应当作出<strong>不利于提供格式条款一方</strong>的解释。格式条款和非格式条款不一致的，应当采用<strong>非格式条款</strong>。</blockquote>\n<p><strong>要点</strong>：与保险法 §30（不利解释）<strong>完全一致</strong>，且明确\"<strong>非格式条款优先</strong>\"——所以销售人员的<strong>书面承诺</strong>（非格式条款）优先于印好的条款。</p>\n<hr>\n<h2 id=\"s4\">四、《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条（法释〔2023〕13 号，2023 年 12 月 5 日施行）</h2>\n<blockquote><strong>第十条</strong> 提供格式条款的一方在合同订立时采用<strong>通常足以引起对方注意的文字、符号、字体等明显标识</strong>，提示对方注意免除或者减轻其责任、排除或者限制对方权利等与对方有重大利害关系的<strong>异常条款</strong>的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的<strong>提示义务</strong>。<br><br>提供格式条款的一方按照对方的要求，就与对方有重大利害关系的异常条款的<strong>概念、内容及其法律后果</strong>以书面或者口头形式向对方作出<strong>通常能够理解的解释说明</strong>的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的<strong>说明义务</strong>。<br><br>提供格式条款的一方对其<strong>已经尽到提示义务或者说明义务承担举证责任</strong>。对于<strong>通过互联网等信息网络订立的电子合同</strong>，提供格式条款的一方<strong>仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持</strong>，但是其举证符合前两款规定的除外。</blockquote>\n<h3 id=\"s5\">三款分别意味着什么</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>款</th><th>规则</th><th>对你的意义</th></tr></thead><tbody>\n<tr><td><strong>第 1 款</strong></td><td>提示 = \"通常足以引起注意\"的<strong>明显标识</strong></td><td>加粗加黑只是及格线；要看在整体页面里是否真的显眼</td></tr>\n<tr><td><strong>第 2 款</strong></td><td>说明 = 对<strong>概念、内容、法律后果</strong>作出\"通常能够理解\"的解释</td><td>光说\"这是免责条款\"不够，得说明<strong>拒赔会怎么发生</strong></td></tr>\n<tr><td><strong>第 3 款</strong> 🔥</td><td><strong>电子合同：仅以\"设置勾选、弹窗\"为由主张已履行义务的，法院不予支持</strong></td><td><strong>互联网投保的决定性武器。</strong> 直接击穿\"你勾了已阅读\"的抗辩</td></tr>\n<tr><td><strong>举证责任</strong></td><td>由提供格式条款一方（保险人）承担</td><td>与解释二 §13① 一致，进一步加固</td></tr>\n</tbody></table></div>\n<h3 id=\"s6\">与《保险法》解释（二）的关系</h3>\n<div class=\"tablewrap\"><table><thead><tr><th>规则</th><th>保险法路径</th><th>民法典路径</th></tr></thead><tbody>\n<tr><td>提示义务</td><td>解释二 §11（明显标志）</td><td>通则解释 §10①（明显标识）</td></tr>\n<tr><td>明确说明义务</td><td>解释二 §11②（常人能够理解）</td><td>通则解释 §10②（通常能够理解）</td></tr>\n<tr><td>举证责任</td><td>解释二 §13①（保险人举证）</td><td>通则解释 §10③前段（保险人举证）</td></tr>\n<tr><td><strong>签字/勾选的推定</strong></td><td>解释二 §13②：<strong>签字确认即推定已履行</strong>（对投保人不利）</td><td>通则解释 §10③后段：<strong>电子合同仅勾选不足以认定已履行</strong>（对投保人有利）</td></tr>\n</tbody></table></div>\n<p><strong><span class=\"warn\">!</span> 这两条存在张力，实战用法是</strong>：</p>\n<ol>\n<li>保险人援引<strong>解释二 §13②</strong>（\"他已经签字/勾选确认了\"）→ 你援引<strong>通则解释 §10③后段</strong>（\"电子合同仅勾选/弹窗不足以认定\"）。</li>\n<li><strong>新法优于旧法 + 特别法 vs 一般法</strong>：通则解释（2023）晚于解释二（2013），且针对电子合同这一<strong>具体场景</strong>作了更严格的规定。主张在<strong>网络投保</strong>场景下应适用通则解释 §10③。</li>\n<li>即便法院仍适用解释二 §13②，该条本身有<strong>但书</strong>（\"另有证据证明保险人未履行的除外\"）——所以<strong>录屏 + 页面设计证据</strong>永远是核心。</li>\n</ol>\n<hr>\n<h2 id=\"s7\">五、来源清单</h2>\n<div class=\"tablewrap\"><table><thead><tr><th>内容</th><th>来源</th><th>状态</th></tr></thead><tbody>\n<tr><td>民法典 §496-498</td><td>最高人民法院公报 http://gongbao.court.gov.cn/Details/dfe439fb9450f0525bd7e7b50a6242.html</td><td>✅</td></tr>\n<tr><td>合同编通则解释 §10</td><td>北京金融法院「金融案鉴」https://bjfc.bjcourt.gov.cn/cac/1780043234767.html ；山东法院 PDF；广西高院、湖南法院官网交叉引用</td><td>✅ 多源一致</td></tr>\n<tr><td>合同编通则解释其他条文</td><td>—</td><td>【原文未获取，待补】</td></tr>\n</tbody></table></div>", "toc": [{"id": "s1", "lv": 2, "t": "一、《民法典》第四百九十六条【格式条款的定义与提示说明义务】"}, {"id": "s2", "lv": 2, "t": "二、《民法典》第四百九十七条【格式条款无效的情形】"}, {"id": "s3", "lv": 2, "t": "三、《民法典》第四百九十八条【格式条款的解释】"}, {"id": "s4", "lv": 2, "t": "四、《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条（法释〔2023〕13 号，2023 年 12 月 5 日施行）"}, {"id": "s5", "lv": 3, "t": "三款分别意味着什么"}, {"id": "s6", "lv": 3, "t": "与《保险法》解释（二）的关系"}, {"id": "s7", "lv": 2, "t": "五、来源清单"}], "text": "民法典格式条款 + 合同编通则司法解释（保险维权核心条文） 来源 ：最高人民法院公报（民法典条文）、北京金融法院官网「金融案鉴」栏目、多地法院官网引用（合同编通则解释第 10 条）。 可信度 ：A 级（官方来源原文）。⚠️ 条文以官方文本为准。 为什么这一组条文重要 ：保险合同 100% 是格式合同。 「提示说明义务」这条武器，民法典 496 条 + 合同编通则解释第 10 条，比保险法第 17 条更锋利 ——尤其第 10 条第 3 款，直接击穿了互联网投保的\"勾选/弹窗\"抗辩。 一、《民法典》第四百九十六条【格式条款的定义与提示说明义务】 格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。 采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意 免除或者减轻其责任等与对方有重大利害关系的条款 ，按照对方的要求，对该条款予以说明。提供格式条款的一方未履行提示或者说明义务， 致使对方没有注意或者理解与其有重大利害关系的条款的，对方可以主张该条款不成为合同的内容 。 要点 1. \"有重大利害关系\"的范围比保险法的\"免责条款\"更宽 ——不限于免除责任，还包括限制对方权利等。 2. 法律后果是\"不成为合同的内容\" （而非\"不生效\"），即该条款压根没进合同，保险人无从援引。 3. 与保险法 §17 是 并列 关系，可以 同时主张 。 二、《民法典》第四百九十七条【格式条款无效的情形】 有下列情形之一的，该格式条款无效： （一）具有本法第一编第六章第三节和本法第五百零六条规定的无效情形； （二）提供格式条款一方 不合理地免除或者减轻其责任、加重对方责任、限制对方主要权利 ； （三）提供格式条款一方 排除对方主要权利 。 要点 ：与保险法 §19（免除保险人依法应承担的义务、加重投保人责任、排除投保人/被保险人/受益人依法享有的权利的条款无效） 高度重合，可并列主张 。 三、《民法典》第四百九十八条【格式条款的解释】 对格式条款的理解发生争议的，应当按照 通常理解 予以解释。对格式条款有 两种以上解释 的，应当作出 不利于提供格式条款一方 的解释。格式条款和非格式条款不一致的，应当采用 非格式条款 。 要点 ：与保险法 §30（不利解释） 完全一致 ，且明确\" 非格式条款优先 \"——所以销售人员的 书面承诺 （非格式条款）优先于印好的条款。 四、《最高人民法院关于适用〈中华人民共和国民法典〉合同编通则若干问题的解释》第十条（法释〔2023〕13 号，2023 年 12 月 5 日施行） 第十条 提供格式条款的一方在合同订立时采用 通常足以引起对方注意的文字、符号、字体等明显标识 ，提示对方注意免除或者减轻其责任、排除或者限制对方权利等与对方有重大利害关系的 异常条款 的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的 提示义务 。 提供格式条款的一方按照对方的要求，就与对方有重大利害关系的异常条款的 概念、内容及其法律后果 以书面或者口头形式向对方作出 通常能够理解的解释说明 的，人民法院可以认定其已经履行民法典第四百九十六条第二款规定的 说明义务 。 提供格式条款的一方对其 已经尽到提示义务或者说明义务承担举证责任 。对于 通过互联网等信息网络订立的电子合同 ，提供格式条款的一方 仅以采取了设置勾选、弹窗等方式为由主张其已经履行提示义务或者说明义务的，人民法院不予支持 ，但是其举证符合前两款规定的除外。 三款分别意味着什么 款 规则 对你的意义 第 1 款 提示 = \"通常足以引起注意\"的 明显标识 加粗加黑只是及格线；要看在整体页面里是否真的显眼 第 2 款 说明 = 对 概念、内容、法律后果 作出\"通常能够理解\"的解释 光说\"这是免责条款\"不够，得说明 拒赔会怎么发生 第 3 款 🔥 电子合同：仅以\"设置勾选、弹窗\"为由主张已履行义务的，法院不予支持 互联网投保的决定性武器。 直接击穿\"你勾了已阅读\"的抗辩 举证责任 由提供格式条款一方（保险人）承担 与解释二 §13① 一致，进一步加固 与《保险法》解释（二）的关系 规则 保险法路径 民法典路径 提示义务 解释二 §11（明显标志） 通则解释 §10①（明显标识） 明确说明义务 解释二 §11②（常人能够理解） 通则解释 §10②（通常能够理解） 举证责任 解释二 §13①（保险人举证） 通则解释 §10③前段（保险人举证） 签字/勾选的推定 解释二 §13②： 签字确认即推定已履行 （对投保人不利） 通则解释 §10③后段： 电子合同仅勾选不足以认定已履行 （对投保人有利） ⚠️ 这两条存在张力，实战用法是 ： 1. 保险人援引 解释二 §13② （\"他已经签字/勾选确认了\"）→ 你援引 通则解释 §10③后段 （\"电子合同仅勾选/弹窗不足以认定\"）。 2. 新法优于旧法 + 特别法 vs 一般法 ：通则解释（2023）晚于解释二（2013），且针对电子合同这一 具体场景 作了更严格的规定。主张在 网络投保 场景下应适用通则解释 §10③。 3. 即便法院仍适用解释二 §13②，该条本身有 但书 （\"另有证据证明保险人未履行的除外\"）——所以 录屏 + 页面设计证据 永远是核心。 五、来源清单 内容 来源 状态 民法典 §496 498 最高人民法院公报 http://gongbao.court.gov.cn/Details/dfe439fb9450f0525bd7e7b50a6242.html ✅ 合同编通则解释 §10 北京金融法院「金融案鉴」https://bjfc.bjcourt.gov.cn/cac/1780043234767.html ；山东法院 PDF；广西高院、湖南法院官网交叉引用 ✅ 多源一致 合同编通则解释其他条文 — 【原文未获取，待补】"}, {"id": "L4-法条库/03-健康险监管规范", "group": "5 · 法条原文", "groupKey": "L4-法条库", "title": "健康险监管规范 · 短期健康保险（银保监办发〔2021〕7 号）原文摘录", "order": 5, "file": "03-健康险监管规范.md", "html": "<h1 id=\"s0\">健康险监管规范 · 短期健康保险（银保监办发〔2021〕7 号）原文摘录</h1>\n<blockquote><strong>来源</strong>：中国政府网 https://www.gov.cn/zhengce/zhengceku/2021-01/12/content_5579193.htm （<strong>A 级 · 官方原文</strong>）<br><strong>文件名</strong>：《中国银保监会办公厅关于规范短期健康保险业务有关问题的通知》银保监办发〔2021〕7 号，2021 年 1 月 11 日<br><br><strong>为什么重要</strong>：百万医疗险 90% 是\"短期健康保险\"。这份通知是<strong>监管针对\"短险长做\"骗局的直接禁令</strong>，<br>里面对续保表述、停售、拒赔考核、搭售、健康告知设定都有硬性规定。<br><strong>消费者拿它当武器，比跟保险公司讲道理有效得多</strong>——因为违反的是监管明文禁令，可直接向 12378 举报。</blockquote>\n<hr>\n<h2 id=\"s1\">一、适用对象（第 1 条）</h2>\n<blockquote>本通知所规范的短期健康保险，是指保险公司向个人销售的<strong>保险期间为一年及一年以下且不含有保证续保条款的健康保险</strong>。团体保险业务除外。</blockquote>\n<p><strong>推论</strong>：保险期间超过 1 年，或<strong>包含保证续保责任</strong>的，属于长期健康保险，不适用本通知。</p>\n<hr>\n<h2 id=\"s2\">二、产品关键信息必须清晰无歧义（第 2 条）</h2>\n<blockquote>保险公司开发的短期健康保险产品应当在保险条款中对<strong>保险期间、保险责任、责任免除、理赔条件、退保约定，以及保费交纳方式、等待期设置，保险金额、免赔额、赔付比例</strong>等产品关键信息进行<strong>清晰、明确、无歧义</strong>的表述。</blockquote>\n<p><strong>用法</strong>：条款对免赔额口径、赔付比例表述含糊的 → 既违反监管要求，又可主张 §30 不利解释。<strong>监管违规 + 民事不利解释，两条一起打。</strong></p>\n<hr>\n<h2 id=\"s3\">三、🔥 \"不保证续保\"的强制表述 + 禁用词（第 3 条）</h2>\n<blockquote>保险公司开发的短期健康保险产品中包含续保责任的，应当在保险条款中<strong>明确表述为\"不保证续保\"条款</strong>。不保证续保条款中至少应当包含以下内容：<br><br><strong>本产品保险期间为一年（或不超过一年）。保险期间届满，投保人需要重新向保险公司申请投保本产品，并经保险人同意，交纳保险费，获得新的保险合同。</strong><br><br>保险公司不得在短期健康保险产品条款、宣传材料中使用<strong>\"自动续保\"\"承诺续保\"\"终身限额\"</strong>等易与长期健康保险混淆的词句。</blockquote>\n<p><strong>这是百万医疗险最核心的一条。</strong> 实战检查清单：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>如果你在页面/条款里看到</th><th>判断</th></tr></thead><tbody>\n<tr><td>\"自动续保\"</td><td>❌ <strong>明令禁止</strong>，可举报</td></tr>\n<tr><td>\"承诺续保\"</td><td>❌ <strong>明令禁止</strong></td></tr>\n<tr><td>\"终身限额\"</td><td>❌ <strong>明令禁止</strong></td></tr>\n<tr><td>\"可续保至 100 岁 / 续保时最高年龄可至 XX 周岁\"</td><td>❌ 易混淆，监管明确禁止（见监管后续备案要求）</td></tr>\n<tr><td>\"我们不会因为被保险人在首次投保后的健康状况变化而拒绝您的重新投保申请\"</td><td>❌ 变相承诺续保，监管明确禁止</td></tr>\n<tr><td>\"不保证续保\" + \"期满需重新申请投保，经保险人同意\"</td><td>✅ 合规表述</td></tr>\n<tr><td>\"保证续保 20 年\"</td><td>✅ 属长期健康险，不受本条限制</td></tr>\n</tbody></table></div>\n<p><strong>打法</strong>：投保时的<strong>宣传页面快照</strong>如果用了上述禁用词 → ① 销售误导，主张按页面承诺履行；② 向 12378 举报违规宣传。</p>\n<hr>\n<h2 id=\"s4\">四、不得设定虚高保额（第 5 条）</h2>\n<blockquote>保险公司应当根据医疗费用实际发生水平、理赔经验数据等因素，合理确定短期健康保险产品费率、免赔额、赔付比例和保险金额等。保险公司<strong>不得设定严重背离理赔经验数据基础的、虚高的保险金额</strong>。</blockquote>\n<p><strong>用法</strong>：保额 400 万、600 万的营销数字，如果与实际理赔经验严重背离，属于本条规制对象。当然这不直接导致赔付增加，但<strong>可用于质疑\"宣传误导\"</strong>——把保额当卖点，本身就有问题。</p>\n<hr>\n<h2 id=\"s5\">五、禁止强制搭售（第 7 条）</h2>\n<blockquote>保险公司将短期健康险开发设计成主险产品的，<strong>不得强制要求</strong>保险消费者在购买主险产品的同时，购买该公司其他产品。<br><br>保险公司将短期健康险开发设计成附加险产品的，应当明确告知保险消费者附加险所对应的主险产品情况，并由保险消费者<strong>自主决定</strong>是否购买该产品组合。<br><br>保险公司<strong>不得在附加险产品条款中限制投保人单独解除附加险合同的权利</strong>。</blockquote>\n<hr>\n<h2 id=\"s6\">六、投保须知书的 9 项强制提示（第 8 条）</h2>\n<blockquote>保险公司在销售短期健康保险产品时，应当向保险消费者提供\"<strong>短期健康保险产品投保须知书</strong>\"，并重点提示以下内容：<br>（一）投保人如实告知义务及未如实告知会造成的后果；（二）保险责任及<strong>除外责任</strong>；（三）保险期间；（四）保险金额；（五）<strong>免赔额</strong>；（六）<strong>赔付比例</strong>；（七）<strong>等待期</strong>；（八）投保年龄与保费高低具有关联性等情况；（九）银保监会规定的其他告知事项。</blockquote>\n<p><strong>用法</strong>：<strong>向保险人索要投保须知书</strong>，核对是否 9 项齐全、是否向你提示过。缺失即可作为\"未尽提示义务\"的证据。<strong>这是被严重低估的取证手段。</strong></p>\n<hr>\n<h2 id=\"s7\">七、🔥 严禁设定拒赔率考核指标（第 9 条）</h2>\n<blockquote>保险公司应当加强对短期健康保险产品的核保、理赔管理，<strong>规范设定健康告知信息，健康告知信息的设定不得出现有违一般医学常识等情形</strong>。保险公司应当引导保险消费者向保险公司履行如实告知义务。<br><br>保险公司<strong>不得无理拒赔</strong>。<strong>严禁保险公司通过设定产品拒赔率等考核指标</strong>，影响保险消费者正常、合理的理赔诉求，以弥补因产品定价假设不合理、不科学造成的实际经营损失，侵害消费者利益。</blockquote>\n<p><strong>两条用法</strong></p>\n<ol>\n<li><strong>\"健康告知信息的设定不得有违一般医学常识\"</strong> → 攻击<strong>概括性询问</strong>（\"有无其他疾病\"\"身体是否异常\"）的<strong>监管依据</strong>。与司法解释二 §6② 并用，威力加倍。</li>\n<li><strong>\"严禁设定拒赔率考核指标\"</strong> → 如果怀疑理赔员因考核压力拒赔，可在投诉中<strong>要求监管核查其考核指标设置</strong>。这是从内部机制上施压。</li>\n</ol>\n<hr>\n<h2 id=\"s8\">八、停售的披露义务（第 10 条）</h2>\n<blockquote>保险公司决定停止销售短期健康保险产品的，应当将产品停售的<strong>具体原因、具体时间，以及后续服务措施</strong>等信息通过公司官网和即时通讯工具等便于公众知晓的方式披露告知保险消费者，<strong>并为已购买产品的保险消费者在保险期间内继续提供保障服务，同时在保险期间届满时提供转保建议</strong>。<br><br>保险公司<strong>主动停售</strong>保险产品的，应当<strong>至少在产品停售前 30 日</strong>披露相关信息。保险公司因产品设计存在违法违规等问题被监管机构<strong>责令停售</strong>的，应当于停售之日起 <strong>3 日内</strong>披露相关信息。保险公司应当在披露产品停售相关信息后，以合理方式<strong>通知每一张有效保单的投保人</strong>。<br><br>保险公司应当于每年 <strong>3 月 31 日</strong>前在公司官网披露前三个年度个人短期健康保险产品停售情况及每一款产品的有效保单数量。</blockquote>\n<p><strong>用法</strong>：产品停售导致无法续保的 → 核查保险公司是否履行了披露与通知义务、是否提供转保建议。<strong>未履行的，既是监管违规，也是主张损失赔偿的事实基础。</strong></p>\n<hr>\n<h2 id=\"s9\">九、其他</h2>\n<ul>\n<li><strong>第 6 条</strong>：最低现金价值 = 净保费 ×（1 − m/n），m=已生效天数，n=保险期间天数。</li>\n<li><strong>第 4 条</strong>：保险公司应<strong>每半年</strong>在官网披露个人短期健康险整体<strong>综合赔付率</strong>（上半年不晚于 7 月底，年度不晚于次年 2 月底）。→ 可以用来查某家公司的赔付率数据。</li>\n<li><strong>第 13 条</strong>：本通知印发前已审批/备案的不合规产品，应于 <strong>2021 年 5 月 1 日前停止销售</strong>。</li>\n</ul>\n<hr>\n<h2 id=\"s10\">待补</h2>\n<ul>\n<li>【原文未获取，待补】《健康保险管理办法》（中国银行保险监督管理委员会令 2019 年第 3 号）—— 长期健康险、费率调整等相关规定</li>\n<li>【原文未获取，待补】《人身保险公司保险条款和保险费率管理办法》</li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "一、适用对象（第 1 条）"}, {"id": "s2", "lv": 2, "t": "二、产品关键信息必须清晰无歧义（第 2 条）"}, {"id": "s3", "lv": 2, "t": "三、🔥 \"不保证续保\"的强制表述 + 禁用词（第 3 条）"}, {"id": "s4", "lv": 2, "t": "四、不得设定虚高保额（第 5 条）"}, {"id": "s5", "lv": 2, "t": "五、禁止强制搭售（第 7 条）"}, {"id": "s6", "lv": 2, "t": "六、投保须知书的 9 项强制提示（第 8 条）"}, {"id": "s7", "lv": 2, "t": "七、🔥 严禁设定拒赔率考核指标（第 9 条）"}, {"id": "s8", "lv": 2, "t": "八、停售的披露义务（第 10 条）"}, {"id": "s9", "lv": 2, "t": "九、其他"}, {"id": "s10", "lv": 2, "t": "待补"}], "text": "健康险监管规范 · 短期健康保险（银保监办发〔2021〕7 号）原文摘录 来源 ：中国政府网 https://www.gov.cn/zhengce/zhengceku/2021 01/12/content 5579193.htm （ A 级 · 官方原文 ） 文件名 ：《中国银保监会办公厅关于规范短期健康保险业务有关问题的通知》银保监办发〔2021〕7 号，2021 年 1 月 11 日 为什么重要 ：百万医疗险 90% 是\"短期健康保险\"。这份通知是 监管针对\"短险长做\"骗局的直接禁令 ， 里面对续保表述、停售、拒赔考核、搭售、健康告知设定都有硬性规定。 消费者拿它当武器，比跟保险公司讲道理有效得多 ——因为违反的是监管明文禁令，可直接向 12378 举报。 一、适用对象（第 1 条） 本通知所规范的短期健康保险，是指保险公司向个人销售的 保险期间为一年及一年以下且不含有保证续保条款的健康保险 。团体保险业务除外。 推论 ：保险期间超过 1 年，或 包含保证续保责任 的，属于长期健康保险，不适用本通知。 二、产品关键信息必须清晰无歧义（第 2 条） 保险公司开发的短期健康保险产品应当在保险条款中对 保险期间、保险责任、责任免除、理赔条件、退保约定，以及保费交纳方式、等待期设置，保险金额、免赔额、赔付比例 等产品关键信息进行 清晰、明确、无歧义 的表述。 用法 ：条款对免赔额口径、赔付比例表述含糊的 → 既违反监管要求，又可主张 §30 不利解释。 监管违规 + 民事不利解释，两条一起打。 三、🔥 \"不保证续保\"的强制表述 + 禁用词（第 3 条） 保险公司开发的短期健康保险产品中包含续保责任的，应当在保险条款中 明确表述为\"不保证续保\"条款 。不保证续保条款中至少应当包含以下内容： 本产品保险期间为一年（或不超过一年）。保险期间届满，投保人需要重新向保险公司申请投保本产品，并经保险人同意，交纳保险费，获得新的保险合同。 保险公司不得在短期健康保险产品条款、宣传材料中使用 \"自动续保\"\"承诺续保\"\"终身限额\" 等易与长期健康保险混淆的词句。 这是百万医疗险最核心的一条。 实战检查清单： 如果你在页面/条款里看到 判断 \"自动续保\" ❌ 明令禁止 ，可举报 \"承诺续保\" ❌ 明令禁止 \"终身限额\" ❌ 明令禁止 \"可续保至 100 岁 / 续保时最高年龄可至 XX 周岁\" ❌ 易混淆，监管明确禁止（见监管后续备案要求） \"我们不会因为被保险人在首次投保后的健康状况变化而拒绝您的重新投保申请\" ❌ 变相承诺续保，监管明确禁止 \"不保证续保\" + \"期满需重新申请投保，经保险人同意\" ✅ 合规表述 \"保证续保 20 年\" ✅ 属长期健康险，不受本条限制 打法 ：投保时的 宣传页面快照 如果用了上述禁用词 → ① 销售误导，主张按页面承诺履行；② 向 12378 举报违规宣传。 四、不得设定虚高保额（第 5 条） 保险公司应当根据医疗费用实际发生水平、理赔经验数据等因素，合理确定短期健康保险产品费率、免赔额、赔付比例和保险金额等。保险公司 不得设定严重背离理赔经验数据基础的、虚高的保险金额 。 用法 ：保额 400 万、600 万的营销数字，如果与实际理赔经验严重背离，属于本条规制对象。当然这不直接导致赔付增加，但 可用于质疑\"宣传误导\" ——把保额当卖点，本身就有问题。 五、禁止强制搭售（第 7 条） 保险公司将短期健康险开发设计成主险产品的， 不得强制要求 保险消费者在购买主险产品的同时，购买该公司其他产品。 保险公司将短期健康险开发设计成附加险产品的，应当明确告知保险消费者附加险所对应的主险产品情况，并由保险消费者 自主决定 是否购买该产品组合。 保险公司 不得在附加险产品条款中限制投保人单独解除附加险合同的权利 。 六、投保须知书的 9 项强制提示（第 8 条） 保险公司在销售短期健康保险产品时，应当向保险消费者提供\" 短期健康保险产品投保须知书 \"，并重点提示以下内容： （一）投保人如实告知义务及未如实告知会造成的后果；（二）保险责任及 除外责任 ；（三）保险期间；（四）保险金额；（五） 免赔额 ；（六） 赔付比例 ；（七） 等待期 ；（八）投保年龄与保费高低具有关联性等情况；（九）银保监会规定的其他告知事项。 用法 ： 向保险人索要投保须知书 ，核对是否 9 项齐全、是否向你提示过。缺失即可作为\"未尽提示义务\"的证据。 这是被严重低估的取证手段。 七、🔥 严禁设定拒赔率考核指标（第 9 条） 保险公司应当加强对短期健康保险产品的核保、理赔管理， 规范设定健康告知信息，健康告知信息的设定不得出现有违一般医学常识等情形 。保险公司应当引导保险消费者向保险公司履行如实告知义务。 保险公司 不得无理拒赔 。 严禁保险公司通过设定产品拒赔率等考核指标 ，影响保险消费者正常、合理的理赔诉求，以弥补因产品定价假设不合理、不科学造成的实际经营损失，侵害消费者利益。 两条用法 1. \"健康告知信息的设定不得有违一般医学常识\" → 攻击 概括性询问 （\"有无其他疾病\"\"身体是否异常\"）的 监管依据 。与司法解释二 §6② 并用，威力加倍。 2. \"严禁设定拒赔率考核指标\" → 如果怀疑理赔员因考核压力拒赔，可在投诉中 要求监管核查其考核指标设置 。这是从内部机制上施压。 八、停售的披露义务（第 10 条） 保险公司决定停止销售短期健康保险产品的，应当将产品停售的 具体原因、具体时间，以及后续服务措施 等信息通过公司官网和即时通讯工具等便于公众知晓的方式披露告知保险消费者， 并为已购买产品的保险消费者在保险期间内继续提供保障服务，同时在保险期间届满时提供转保建议 。 保险公司 主动停售 保险产品的，应当 至少在产品停售前 30 日 披露相关信息。保险公司因产品设计存在违法违规等问题被监管机构 责令停售 的，应当于停售之日起 3 日内 披露相关信息。保险公司应当在披露产品停售相关信息后，以合理方式 通知每一张有效保单的投保人 。 保险公司应当于每年 3 月 31 日 前在公司官网披露前三个年度个人短期健康保险产品停售情况及每一款产品的有效保单数量。 用法 ：产品停售导致无法续保的 → 核查保险公司是否履行了披露与通知义务、是否提供转保建议。 未履行的，既是监管违规，也是主张损失赔偿的事实基础。 九、其他 第 6 条 ：最低现金价值 = 净保费 ×（1 − m/n），m=已生效天数，n=保险期间天数。 第 4 条 ：保险公司应 每半年 在官网披露个人短期健康险整体 综合赔付率 （上半年不晚于 7 月底，年度不晚于次年 2 月底）。→ 可以用来查某家公司的赔付率数据。 第 13 条 ：本通知印发前已审批/备案的不合规产品，应于 2021 年 5 月 1 日前停止销售 。 待补 【原文未获取，待补】《健康保险管理办法》（中国银行保险监督管理委员会令 2019 年第 3 号）—— 长期健康险、费率调整等相关规定 【原文未获取，待补】《人身保险公司保险条款和保险费率管理办法》"}, {"id": "L5-关于/01-免责声明与内容说明", "group": "6 · 关于", "groupKey": "L5-关于", "title": "免责声明与内容说明", "order": 6, "file": "01-免责声明与内容说明.md", "html": "<h1 id=\"s0\">免责声明与内容说明</h1>\n<h2 id=\"s1\">一、这不是法律意见</h2>\n<p><strong>本网站内容是法律学习与知识整理资料，不构成对任何具体案件的法律意见，也不构成律师—客户关系。</strong></p>\n<p>保险纠纷高度依赖个案事实：同一种拒赔理由，在不同条款措辞、不同投保轨迹、不同病历记载下，结论可能完全相反。 文中所有\"打法\"\"规则\"\"判准\"都只是<strong>分析起点</strong>，不是结论。</p>\n<ul>\n<li>遇到真实纠纷，请结合你的<strong>保单原文、投保流程记录、完整病历</strong>判断；</li>\n<li>涉及金额较大或时效紧迫的，<strong>请咨询执业律师</strong>或向当地法律援助机构求助；</li>\n<li>本文作者不对任何依据本站内容作出的决定承担责任。</li>\n</ul>\n<h2 id=\"s2\">二、案例的可信度分级</h2>\n<p>本站案例分三级，页面上都标了：</p>\n<div class=\"tablewrap\"><table><thead><tr><th>级别</th><th>含义</th><th>能否直接引用</th></tr></thead><tbody>\n<tr><td><strong>A 级</strong></td><td>裁判文书网判决书<strong>原文</strong>，含案号、法院、一审案号，裁判理由逐字摘录</td><td>✅ 可以写进代理词</td></tr>\n<tr><td><strong>B 级</strong></td><td>法院官网、人民法院报、官媒发布的<strong>典型案例</strong>（含\"法官说法/法官提醒\"）</td><td>✅ 可作参考，引用时注明来源为法院发布</td></tr>\n<tr><td><strong>C 级</strong></td><td>律所文章、自媒体等二手来源</td><td><span class=\"warn\">!</span> <strong>不得直接引用</strong>，只能当检索线索，用前必须核验</td></tr>\n</tbody></table></div>\n<p><strong>本站不编造案号、法院名称、裁判理由。</strong> 找不到的争议类型标注为\"检索缺口\"，不凑数。</p>\n<h2 id=\"s3\">三、时效提醒（最容易翻车）</h2>\n<ul>\n<li>人身保险（寿险以外的）诉讼时效 <strong>2 年</strong>，人寿保险 <strong>5 年</strong>，自知道或应当知道保险事故发生之日起算（保险法 §26）。</li>\n<li>保险人解除权：知道解除事由起 <strong>30 日</strong>内行使；合同成立满 <strong>2 年</strong>不得解除（保险法 §16③）。</li>\n<li><strong>时效不因投诉、协商而当然中断</strong>，需要保留书面主张的证据。</li>\n<li>详细时效表见<a class=\"dlink\" href=\"#/README\">《开始这里 · 怎么用这套东西》</a>（开始这里）。</li>\n</ul>\n<h2 id=\"s4\">四、隐私与立场</h2>\n<ul>\n<li>本站为个人学习项目，<strong>不代表任何机构、雇主或保险公司的立场</strong>。</li>\n<li>案例中的当事人名称沿用裁判文书网的公开脱敏规则（\"某公司\"\"某某\"），非本站另行改动。</li>\n<li>文中对保险产品的分析<strong>针对条款设计类型，不针对特定公司</strong>。</li>\n<li>本站不收集任何个人信息，无后端、无统计脚本。</li>\n</ul>\n<h2 id=\"s5\">五、内容来源</h2>\n<p>法条与司法解释来自：全国人大网、最高人民法院官网及公报、中国政府网、中国保险行业协会官网等官方渠道。 案例来自：裁判文书网（A 级）、中国法院网、各级法院官网、人民法院报（B 级）。 每一篇的末尾都列了具体来源。</p>\n<p><strong>法条会修改、判决会被推翻。</strong> 引用前请与最新有效版本核对——尤其是司法解释的\"2020 年修正\"版本与原始版本的差异。</p>\n<h2 id=\"s6\">六、怎么引用本站内容</h2>\n<p>可以：个人学习、内部培训、注明出处后非商业转载。 不可以：把文中内容当作法律意见出具给第三人；删除出处后当作自己的作品发布；用于商业咨询收费。</p>\n<h2 id=\"s7\">七、如果发现错误</h2>\n<p>法条和判例引用出错是严肃的事。发现任何错误请通过站点所属域名联系作者，会尽快更正并在此致谢。</p>\n<hr>\n<h2 id=\"s8\">与其他页面的关系</h2>\n<ul>\n<li>回到入口：见<a class=\"dlink\" href=\"#/README\">《开始这里 · 怎么用这套东西》</a></li>\n<li>通用打法：见<a class=\"dlink\" href=\"#/L0-%E6%89%93%E6%B3%95%E5%B1%82%2F01-%E5%85%AB%E6%8A%8A%E9%80%9A%E7%94%A8%E6%AD%A6%E5%99%A8\">《八把通用武器》</a></li>\n<li>A 级判例原文：见<a class=\"dlink\" href=\"#/L2-%E6%A1%88%E4%BE%8B%E5%BA%93%2F%E5%B9%BF%E4%B8%9C%E4%BA%8C%E5%AE%A1%E5%88%A4%E5%86%B3%E5%8E%9F%E6%96%87%E7%B2%BE%E8%AF%BB-A%E7%BA%A7\">《广东二审判决原文精读 · 第一辑（人身险）》</a></li>\n<li>法条原文：见<a class=\"dlink\" href=\"#/L4-%E6%B3%95%E6%9D%A1%E5%BA%93%2F00-%E6%B3%95%E6%9D%A1%E4%B8%8E%E5%8F%B8%E6%B3%95%E8%A7%A3%E9%87%8A%E5%8E%9F%E6%96%87\">《保险法 · 法条与司法解释原文留档》</a></li>\n</ul>", "toc": [{"id": "s1", "lv": 2, "t": "一、这不是法律意见"}, {"id": "s2", "lv": 2, "t": "二、案例的可信度分级"}, {"id": "s3", "lv": 2, "t": "三、时效提醒（最容易翻车）"}, {"id": "s4", "lv": 2, "t": "四、隐私与立场"}, {"id": "s5", "lv": 2, "t": "五、内容来源"}, {"id": "s6", "lv": 2, "t": "六、怎么引用本站内容"}, {"id": "s7", "lv": 2, "t": "七、如果发现错误"}, {"id": "s8", "lv": 2, "t": "与其他页面的关系"}], "text": "免责声明与内容说明 一、这不是法律意见 本网站内容是法律学习与知识整理资料，不构成对任何具体案件的法律意见，也不构成律师—客户关系。 保险纠纷高度依赖个案事实：同一种拒赔理由，在不同条款措辞、不同投保轨迹、不同病历记载下，结论可能完全相反。 文中所有\"打法\"\"规则\"\"判准\"都只是 分析起点 ，不是结论。 遇到真实纠纷，请结合你的 保单原文、投保流程记录、完整病历 判断； 涉及金额较大或时效紧迫的， 请咨询执业律师 或向当地法律援助机构求助； 本文作者不对任何依据本站内容作出的决定承担责任。 二、案例的可信度分级 本站案例分三级，页面上都标了： 级别 含义 能否直接引用 A 级 裁判文书网判决书 原文 ，含案号、法院、一审案号，裁判理由逐字摘录 ✅ 可以写进代理词 B 级 法院官网、人民法院报、官媒发布的 典型案例 （含\"法官说法/法官提醒\"） ✅ 可作参考，引用时注明来源为法院发布 C 级 律所文章、自媒体等二手来源 ⚠️ 不得直接引用 ，只能当检索线索，用前必须核验 本站不编造案号、法院名称、裁判理由。 找不到的争议类型标注为\"检索缺口\"，不凑数。 三、时效提醒（最容易翻车） 人身保险（寿险以外的）诉讼时效 2 年 ，人寿保险 5 年 ，自知道或应当知道保险事故发生之日起算（保险法 §26）。 保险人解除权：知道解除事由起 30 日 内行使；合同成立满 2 年 不得解除（保险法 §16③）。 时效不因投诉、协商而当然中断 ，需要保留书面主张的证据。 详细时效表见README（开始这里）。 四、隐私与立场 本站为个人学习项目， 不代表任何机构、雇主或保险公司的立场 。 案例中的当事人名称沿用裁判文书网的公开脱敏规则（\"某公司\"\"某某\"），非本站另行改动。 文中对保险产品的分析 针对条款设计类型，不针对特定公司 。 本站不收集任何个人信息，无后端、无统计脚本。 五、内容来源 法条与司法解释来自：全国人大网、最高人民法院官网及公报、中国政府网、中国保险行业协会官网等官方渠道。 案例来自：裁判文书网（A 级）、中国法院网、各级法院官网、人民法院报（B 级）。 每一篇的末尾都列了具体来源。 法条会修改、判决会被推翻。 引用前请与最新有效版本核对——尤其是司法解释的\"2020 年修正\"版本与原始版本的差异。 六、怎么引用本站内容 可以：个人学习、内部培训、注明出处后非商业转载。 不可以：把文中内容当作法律意见出具给第三人；删除出处后当作自己的作品发布；用于商业咨询收费。 七、如果发现错误 法条和判例引用出错是严肃的事。发现任何错误请通过站点所属域名联系作者，会尽快更正并在此致谢。 与其他页面的关系 回到入口：见README 通用打法：见L0 打法层/01 八把通用武器 A 级判例原文：见L2 案例库/广东二审判决原文精读 A级 法条原文：见L4 法条库/00 法条与司法解释原文"}];
window.GROUPS = [{"key": "README.md", "name": "开始这里", "desc": "入口 · 定位表 · 时效速查", "order": 0}, {"key": "L0-打法层", "name": "1 · 通用打法", "desc": "八把通用武器 · 维权全流程", "order": 1}, {"key": "L1-险种层", "name": "2 · 险种深挖", "desc": "重疾 / 医疗 / 意外 / 寿险 / 车险 / 财产责任 / 互联网投保", "order": 2}, {"key": "L2-案例库", "name": "3 · 广东案例库", "desc": "A级判决书原文 · B级典型案例 · 案号 · 裁判要旨", "order": 3}, {"key": "L3-输出层", "name": "4 · 工具箱", "desc": "风险清单 · 常见坑 · 比喻库 · AI 指令库", "order": 4}, {"key": "L4-法条库", "name": "5 · 法条原文", "desc": "保险法 · 司法解释二三四 · 民法典格式条款", "order": 5}, {"key": "L5-关于", "name": "6 · 关于", "desc": "免责声明 · 可信度分级 · 引用规则", "order": 6}];
